def _telethon_env_info_uncached():
    """One-line description of the Telethon that is ACTUALLY running in this process (not what
    requirements.txt asks for — the two can differ on a host with a cached/old venv): package
    version, the TL layer it speaks, and whether it knows the "tap to copy" button type.
    Used by the startup log and by /who's copy-button error reports."""
    try:
        import telethon as _tl
        version = getattr(_tl, "__version__", "?")
    except Exception:
        version = "?"
    try:
        from telethon.tl.alltlobjects import LAYER as _layer
    except Exception:
        _layer = "?"
    has_copy = hasattr(types, "KeyboardButtonCopy")
    info = f"Telethon {version} · layer {_layer} · KeyboardButtonCopy: {'yes' if has_copy else 'NO'}"
    if not has_copy:
        # If a newer layer renamed the "tap to copy" button, this shows what it's called now.
        copy_like = sorted(n for n in dir(types) if "copy" in n.lower())
        info += f" · copy-like names in types: {copy_like or 'none'}"
    return info

_telethon_env_cache = None

def telethon_env_info():
    """Cached: the answer cannot change while the process runs, and /w used to rebuild it (a scan of every name in telethon.tl.types) on every reveal."""
    global _telethon_env_cache
    if _telethon_env_cache is None:
        _telethon_env_cache = _telethon_env_info_uncached()
    return _telethon_env_cache

# ⚡ (2026-11, per owner report — ".w reveal နှေးတယ်"): ONE long-lived httpx client for every Bot API call. bot_api_send_with_copy_button used to open
# a brand-new client per call, so every /w reveal paid a fresh TCP + TLS handshake to api.telegram.org before its message could even be sent.
# Keep-alive connections are reused now; keepalive_expiry is kept short so a reused connection is never one the server already dropped.
_bot_api_http = None

def _bot_api_client():
    global _bot_api_http
    import httpx
    if _bot_api_http is None or _bot_api_http.is_closed:
        _bot_api_http = httpx.AsyncClient(timeout=httpx.Timeout(10.0, connect=5.0),
                                          limits=httpx.Limits(max_keepalive_connections=4, keepalive_expiry=30.0))
    return _bot_api_http

async def warm_bot_api_connection():
    """Opens that connection once at startup (getMe — a tiny call) so even the first reveal after a deploy doesn't pay the handshake."""
    try:
        await _bot_api_client().get(f"https://api.telegram.org/bot{MAIN_BOT_TOKEN}/getMe")
    except Exception as e:
        print(f"ℹ️ Bot API warm-up skipped ({type(e).__name__}) — the first reveal connects on demand")

async def bot_api_send_with_copy_button(chat_id, reply_to_msg_id, text_html, button_text, copy_text):
    """Reply with a real 'tap to copy' button via the Bot API HTTP endpoint (Telethon 1.45.0 has no KeyboardButtonCopy). Raises on any failure so the caller can fall back; the token is scrubbed from error text."""
    try:
        import httpx  # already installed — openai/groq depend on it — so no requirements.txt change
    except ImportError:
        raise RuntimeError("httpx is not installed")
    payload = {
        "chat_id": chat_id,
        "text": text_html,
        "parse_mode": "HTML",
        "reply_parameters": {"message_id": reply_to_msg_id, "allow_sending_without_reply": True},
        "reply_markup": {"inline_keyboard": [[{"text": button_text, "copy_text": {"text": copy_text}}]]},
    }
    try:
        resp = await _bot_api_client().post(f"https://api.telegram.org/bot{MAIN_BOT_TOKEN}/sendMessage", json=payload)
        data = resp.json()
    except Exception as e:
        # 🩹 FIX (per owner report — a /who copy-button failure alert showed as blank:
        raise RuntimeError((str(e) or repr(e)).replace(MAIN_BOT_TOKEN, "***")) from None
    if not data.get("ok"):
        raise RuntimeError(f"Bot API {data.get('error_code')}: {data.get('description')}")
    return data["result"]

async def get_today_stats():
    # 🩹 FIX: daily_report_scheduler fires this at 6:00 AM, intending to summarize the PREVIOUS …
    now = datetime.now(TZ)
    today_midnight = now.replace(hour=0, minute=0, second=0, microsecond=0)
    period_end = today_midnight.timestamp()
    period_start = (today_midnight - timedelta(days=1)).timestamp()
    # 🩹 FIXED (2026-10, per owner report — "ULTRA/SUPREME ကန့်သတ်ထားတာတောင် report မှာ 29 / 9 ခု ပြနေတုန်းပဲ"): every harem entry that …
    pipeline = [
        {"$unwind": "$harem"},
        {"$match": {"harem.caught_date": {"$gte": period_start, "$lt": period_end}}},
        {"$facet": {
            "totals": [{"$match": {"harem.chat_id": {"$exists": True}}}, {"$group": {
                "_id": None,
                "total": {"$sum": 1},
                "catchers": {"$addToSet": "$user_id"},
                "groups": {"$addToSet": "$harem.chat_id"}
            }}],
            "rarity": [{"$match": {"harem.chat_id": {"$exists": True}}},
                       {"$group": {"_id": "$harem.rarity", "count": {"$sum": 1}}}],
            "other": [{"$match": {"harem.chat_id": {"$exists": False}}},
                      {"$group": {"_id": "$harem.rarity", "count": {"$sum": 1}}}]
        }}
    ]
    result = await users_catcher_col.aggregate(pipeline).to_list(length=1)
    doc = result[0] if result else {"totals": [], "rarity": [], "other": []}
    totals = doc["totals"][0] if doc["totals"] else {"total": 0, "catchers": [], "groups": []}
    rarity_breakdown = {r["_id"]: r["count"] for r in doc["rarity"]}
    other_breakdown = {r["_id"]: r["count"] for r in doc.get("other", [])}

    return {
        "total_catches": totals["total"],
        "groups": len(totals["groups"]),
        "rarity": rarity_breakdown,
        "other": other_breakdown,
        "catchers": len(totals["catchers"])
    }

async def send_daily_report():
    stats = await get_today_stats()
    # 🩹 FIX: label with the date actually being summarized — yesterday, since the window above
    # is [yesterday midnight, today midnight) — not today's date, which was misleading.
    report_date = (datetime.now(TZ) - timedelta(days=1)).strftime("%Y-%m-%d")
    text = f"📊 <b>Daily Report – {report_date}</b>\n"
    text += f"━━━━━━━━━━━━━━━━━━━━\n"
    text += f"🐇 <b>Total Catches:</b> <code>{stats['total_catches']}</code>\n"
    text += f"👥 <b>Unique Catchers:</b> <code>{stats['catchers']}</code>\n"
    text += f"🪐 <b>Groups Active:</b> <code>{stats['groups']}</code>\n\n"
    text += f"🏷️ <b>Rarity Breakdown:</b>\n"
    # The same rarity can sit in the data in two fonts (an old and a newer display string), which used to show as two lines
    # (ULTRA 19 + ULTRA 10). Merge them per tier, keeping the spelling that was used most.
    _merged = {}
    for rarity, count in stats['rarity'].items():
        _key = classify_rarity(rarity or "")
        if _key not in RARITY_TIERS:
            _key = rarity
        _m = _merged.setdefault(_key, [0, rarity, 0])
        _m[0] += count
        if count > _m[2]:
            _m[1], _m[2] = rarity, count
    for _key, (count, label, _best) in sorted(_merged.items(), key=lambda kv: kv[1][0], reverse=True):
        text += f"  • {label} — <code>{count}</code>\n"
    if not stats['rarity']:
        text += "  <i>No catches that day.</i>\n"
    # 🔒 (2026-10) how many ULTRA / SUPREME cards actually spawned that day vs. the daily cap (ULTRA 3 / SUPREME 6)
    try:
        _spawned = await get_rare_spawn_counts(report_date)
        text += f"\n🎴 <b>Rare Spawns (daily cap):</b>\n"
        for _t, _cap in RARE_SPAWN_DAILY_CAPS.items():
            _rest = "" if rare_tier_open_on(_t, report_date) else " <i>(rest day)</i>"
            text += f"  • {RARITY_EMOJI.get(_t, RARITY_DEFAULT_EMOJI)} {RARITY_DISPLAY_NAME.get(_t, _t)} — <code>{_spawned[_t]}/{_cap}</code>{_rest}\n"
        # cards that reached a harem WITHOUT spawning (Owner Shop / gift / trade) — shown apart so they can't be mistaken for spawn catches
        _other = stats.get("other") or {}
        if _other:
            _ot = {t: 0 for t in RARE_SPAWN_DAILY_CAPS}
            for _r, _c in _other.items():
                _k = classify_rarity(_r or "")
                if _k in _ot:
                    _ot[_k] += _c
            text += (f"\n🛒 <b>Not from spawns</b> <i>(shop / gift / trade)</i>: <code>{sum(_other.values())}</code> cards"
                     + "".join(f" · {RARITY_EMOJI.get(_t, RARITY_DEFAULT_EMOJI)} {RARITY_DISPLAY_NAME.get(_t, _t)} <code>{_n}</code>" for _t, _n in _ot.items()) + "\n")
    except Exception as e:
        print(f"Daily report rare-spawn line failed: {e}")
    text += f"\n<code>/today</code> to see today's top catchers so far."

    # Send to force-sub group
    try:
        await send_safe_message(bot1, FORCE_SUB_CHAT_ID, text, parse_mode='html')
    except Exception as e:
        print(f"Daily report to group failed: {e}")

    # Send to owner's DM
    try:
        await send_safe_message(bot1, OWNER_ID, text, parse_mode='html')
    except Exception as e:
        print(f"Daily report to owner DM failed: {e}")
async def daily_report_scheduler():
    while True:
        now = datetime.now(TZ)
        target = now.replace(hour=6, minute=0, second=0, microsecond=0)
        if now >= target:
            target += timedelta(days=1)
        wait_seconds = (target - now).total_seconds()
        await asyncio.sleep(wait_seconds)

        # Check if already sent today (to avoid duplicates after restart)
        last_sent = await bot_settings_col.find_one({"_id": "daily_report_last_sent"})
        today_str = datetime.now(TZ).strftime("%Y-%m-%d")
        if last_sent and last_sent.get("date") == today_str:
            continue
        await send_daily_report()
        await bot_settings_col.update_one(
            {"_id": "daily_report_last_sent"},
            {"$set": {"date": today_str}},
            upsert=True
        )

