# 🛡 NO-PROFIT MARKET (2026-11, per owner request — "buy and sell လုပ်နေလည်း user အမြတ်မဖြစ်အောင်လုပ်ပါ"):
SELL_ALL_MULT = 0.10
BUY_FLOOR_MULT = 2.0

def _apply_buy_floor(mn, mx):
    """(min, max) of a value band with the buy floor applied to the MIN. Never touches the max."""
    try:
        floor = round(float(mx) * SELL_ALL_MULT * BUY_FLOOR_MULT, 2)
        if floor < float(mx):
            return max(mn, floor), mx
    except (TypeError, ValueError):
        pass
    return mn, mx
def _build_fancy_font_reverse_map():
    mapping = {}
    for cp in range(0x1D400, 0x1D800):
        try:
            name = unicodedata.name(chr(cp))
        except ValueError:
            continue
        if not name.startswith("MATHEMATICAL "):
            continue
        tokens = name.split()
        last = tokens[-1]
        if "DIGIT" in tokens:
            digit_words = {"ZERO": "0", "ONE": "1", "TWO": "2", "THREE": "3", "FOUR": "4",
                           "FIVE": "5", "SIX": "6", "SEVEN": "7", "EIGHT": "8", "NINE": "9"}
            if last in digit_words:
                mapping[chr(cp)] = digit_words[last]
        elif "DOTLESS" in tokens:
            mapping[chr(cp)] = last.lower()
        elif len(last) == 1 and last.isalpha():
            if "SMALL" in tokens:
                mapping[chr(cp)] = last.lower()
            elif "CAPITAL" in tokens:
                mapping[chr(cp)] = last.upper()
    return mapping

_FANCY_TO_PLAIN = str.maketrans(_build_fancy_font_reverse_map())

def normalize_char_id_input(raw_id):
    """Turns whatever the player typed (with/without 'BOD', any case, leading zeros like '0071') into the stored form, e.g. 'BOD1234'."""
    raw_id = (raw_id or "").strip().upper()
    if raw_id.isdigit():
        return f"BOD{int(raw_id)}"
    return raw_id

def display_char_id(char_id):
    """Strips the internal 'BOD' prefix and zero-pads to 4 digits ('BOD71' -> '0071') so lists align; display-only, the stored char_id is never padded."""
    if isinstance(char_id, str) and char_id.upper().startswith("BOD"):
        digits = char_id[3:]
        return digits.zfill(4) if digits.isdigit() else digits
    return char_id

def artist_line(card_doc, prefix="", suffix="\n", label="Artist"):
    """Builds a formatted 'Artist' credit line for any character display, given either a
    full character document (dict with an 'artist' key) or the artist name itself.
    Returns '' when no artist is on file, so callers can safely inline this everywhere
    a character's name/rarity is shown (catch results, /check, /harem, gifts, etc.).
    `label` swaps the word after the 🎨 (default "Artist"; /check passes "Uploader")."""
    if isinstance(card_doc, dict):
        artist = card_doc.get("artist")
    else:
        artist = card_doc
    if not artist or not str(artist).strip():
        return ""
    return f"{prefix}🎨 <b>{label}:</b> <code>{escape_html(str(artist).strip())}</code>{suffix}"

