_cached_value_overrides = {}  # key -> {"min": int, "max": int}

def value_override_key(tier, event_no=None):
    if tier == "ULTRA" and event_no is not None:
        return f"ULTRA:{int(event_no)}"
    return tier

def default_value_range(tier):
    """The built-in band for a tier: (buy floor = BUY_FLOOR_MULT × the /sell payout, RARITY_VLT_PRICE)."""
    mx = RARITY_VLT_PRICE.get(tier, 0)
    return _apply_buy_floor(0, mx)

def tier_value_range(tier):
    """Tier-wide band (ignores ULTRA's per-event bands): override if set, else default."""
    ov = _cached_value_overrides.get(tier)
    if ov:
        return _apply_buy_floor(ov["min"], ov["max"])
    return default_value_range(tier)

def value_range_for_char(char_doc):
    """(min, max) 💠 for one card. ULTRA + an event with its own band -> that band."""
    if not char_doc:
        return 0, 0
    tier = classify_rarity(char_doc.get("rarity_tier") or char_doc.get("rarity", ""))
    if tier == "ULTRA":
        try:
            ev = int(char_doc.get("event_no"))
        except (TypeError, ValueError):
            ev = None
        if ev is not None:
            ov = _cached_value_overrides.get(f"ULTRA:{ev}")
            if ov:
                return _apply_buy_floor(ov["min"], ov["max"])
    return tier_value_range(tier)

async def load_card_value_overrides_cache():
    try:
        doc = await bot_settings_col.find_one({"_id": "card_value_overrides"})
        cleaned = {}
        for key, v in ((doc or {}).get("values") or {}).items():
            tier, _, ev = key.partition(":")
            if tier not in RARITY_TIERS:
                continue
            if ev and (tier != "ULTRA" or not ev.isdigit() or int(ev) not in EVENT_TYPES):
                continue
            try:
                mn, mx = int(v["min"]), int(v["max"])
            except (KeyError, TypeError, ValueError):
                continue
            if mn < 1 or mx < mn:
                continue
            cleaned[key] = {"min": mn, "max": mx}
        _cached_value_overrides.clear()
        _cached_value_overrides.update(cleaned)
    except Exception as e:
        print(f"load_card_value_overrides_cache error: {e}")

def vlt_price_for_char(char_doc):
    """💠 OWNER SHOP / MARKET PRICE — the MAX of the card's value band (see VALUE BANDS above):
    RARITY_VLT_PRICE by default, or whatever /setvalue set for its tier (ULTRA: its event).
    Kept as its own named function so the pricing rule reads clearly at every /buy [char id] /
    /show call site. 🩹 2026-08: this used to be priced in ⭐ Star — the Market now runs on 💠 VLT only."""
    return value_range_for_char(char_doc)[1]

def rarity_price_list_text(skip=()):
    """Compact 'EMOJI TIER price💠 / ...' string built straight from RARITY_VLT_PRICE, in
    rarity order (No.1 rarest first) — used wherever help text needs to show the current
    Owner Shop price list, so it can never drift out of sync with the real prices again."""
    return " / ".join(
        f"{RARITY_EMOJI.get(tier, RARITY_DEFAULT_EMOJI)}{RARITY_DISPLAY_NAME.get(tier, tier)} {tier_value_range(tier)[1]}💠"
        for tier in RARITY_TIERS if tier not in skip
    )

def catch_star_reward(rarity_str):
    """⭐ Star bonus paid out when a spawn is actually CAUGHT from the wild — not bought from
    the Owner Shop. A DELIBERATELY SEPARATE, smaller, purely rank-based formula (rank * 25,
    ULTRA flat 500⭐) from the Owner Shop's VLT price list (RARITY_VLT_PRICE) — it does not
    read that table and is unaffected by Owner Shop price changes, so catching a card always
    stays meaningfully cheaper (in VLT-equivalent terms) than buying it outright."""
    if classify_rarity(rarity_str) == "ULTRA":
        return 500
    return rarity_rank_value(rarity_str) * 25

# ⭐ (2026-11, per owner request — "Catch success တိုင်း star ပေးတာ နားမယ်"): catching a spawn no longer pays Stars. perform_catch pays
# catch_total_star_reward() instead of the old catch_star_reward() + catch_rarity_star_bonus() sum; flip this back to True to restore the old payout
# (the success message's "💰 +⭐" line follows automatically). Stars still come from /daily, /hunt, trivia, the Casino and the rest.
CATCH_STAR_REWARD_ENABLED = False

def catch_total_star_reward(rarity_str):
    return (catch_rarity_star_bonus(rarity_str) + catch_star_reward(rarity_str)) if CATCH_STAR_REWARD_ENABLED else 0

def catch_rarity_star_bonus(rarity_str):
    """⭐ Extra flat Star bonus paid on top of catch_star_reward() when a spawn is CAUGHT,
    keyed by rarity tier. Paid into star_balance alongside catch_star_reward(), never on its own."""
    tier = classify_rarity(rarity_str)
    return _RARITY_STAR_BONUS_MAP.get(tier, 0)
# ==========================================
# ⭐ STAR DISPLAY FORMATTING
# ==========================================
# 🩹 2026-08 USD RETIREMENT: this file used to also have format_usd() / format_usd_compact()
# for USD wallet_balance display. Both are retired along with USD — every call site that used
# to format a USD amount now calls format_star_plain() below instead.
def format_star_plain(star_amount):
    """Clean Star display — whole numbers show with no decimals, fractional Star (e.g. quiz
    rewards of 0.2-1⭐) show up to 2 decimal places."""
    try:
        amount = float(star_amount)
    except Exception:
        return f"{star_amount} ⭐"
    if amount.is_integer():
        return f"{int(amount):,} ⭐"
    return f"{amount:,.2f} ⭐"

def format_vlt_plain(vlt_amount):
    """💠 VLT display, same shape as format_star_plain() — whole numbers with no decimals,
    fractional VLT (e.g. a /sellvlt of 2.5💠) shown with up to 2 decimal places."""
    try:
        amount = float(vlt_amount)
    except Exception:
        return f"{vlt_amount} 💠"
    if amount.is_integer():
        return f"{int(amount):,} 💠"
    return f"{amount:,.2f} 💠"

