def normalize_contact_link(text):
    """What the Owner typed -> a safe https link, or None. Accepts a full http(s) link, t.me/xxx, or @username."""
    t = (text or "").strip().strip("<>").strip()
    if not t or len(t) > 256 or any(ch.isspace() or ch in "'\"<>" for ch in t):
        return None
    if re.fullmatch(r"@[A-Za-z0-9_]{4,32}", t):
        return "https://t.me/" + t[1:]
    if re.match(r"(?i)^(?:t\.me|telegram\.me)/", t):
        t = "https://" + t
    m = re.match(r"(?i)^https?://([^/?#]+)(?:[/?#].*)?$", t)
    if not m or "." not in m.group(1):
        return None
    return "https://" + t.split("://", 1)[1] if t.lower().startswith("http://") else t

