    await show_group_cd_col.create_index("expire_at", expireAfterSeconds=0)     # 🖼️ group /show cooldown records delete themselves 4 h after they were made
    # ❌ REMOVED: gotu_pairs_col, gotu_games_col, gotu_players_col, quiz_questions_col, quiz_msg_counters_col
