# ==========================================
# 🚦 FLOOD GOVERNOR — keeps bot1 under Telegram's send limits (2026-11, owner: "ဒီနေ့ Sunday လူသုံးများလို့ group chat တွေမှာ mine/balance/today/gift/harem တွေ …
# ==========================================
import contextvars as _ctxv

FLOOD_GOVERNOR_ON = os.environ.get("FLOOD_GOVERNOR", "1") != "0"

def _flood_env(name, default, lo=0.0):
    try:
        return max(lo, float(os.environ.get(name, default)))
    except (TypeError, ValueError):
        return float(default)

FLOOD_GROUP_PER_MIN = _flood_env("FLOOD_GROUP_PER_MIN", 18, 1)        # Telegram: ~20 messages a minute per group — keep a margin
FLOOD_PM_PER_10S = _flood_env("FLOOD_PM_PER_10S", 8, 1)               # private chats: about one a second
FLOOD_MIN_GAP = _flood_env("FLOOD_MIN_GAP", 1.0, 0.0)                 # seconds between two messages to the same chat (an edit counts FLOOD_EDIT_WEIGHT of it)
FLOOD_EDIT_WEIGHT = _flood_env("FLOOD_EDIT_WEIGHT", 0.5, 0.0)
FLOOD_GLOBAL_PER_SEC = _flood_env("FLOOD_GLOBAL_PER_SEC", 25, 1)      # Telegram: ~30 a second across the whole account
FLOOD_MAX_WAIT = _flood_env("FLOOD_MAX_WAIT", 15, 1)                  # longest a message may be held back
FLOOD_RETRY_MAX = _flood_env("FLOOD_RETRY_MAX", 30, 0)                # a Telegram FloodWait up to this long is waited out and retried
FLOOD_HOT_FRACTION = _flood_env("FLOOD_HOT_FRACTION", 0.7, 0.1)       # a group is "hot" once this share of its minute budget is used
FLOOD_CHAT_CMD_CAP = _flood_env("FLOOD_CHAT_CMD_CAP", 12, 1)          # view/game commands admitted per group per minute before the group counts as hot

_FLOOD_INNER = _ctxv.ContextVar("flood_inner", default=False)         # True while we are inside a wrapped call (send_message(file=…) calls send_file — counted once)

class OutboundShed(FloodWaitError):
    """Raised INSTEAD of sending when the chat is too busy (or blocked by Telegram) for longer than FLOOD_MAX_WAIT. A FloodWaitError, so every existing
    `except FloodWaitError` / `except Exception` around a send already copes with it."""
    def __init__(self, seconds):
        self.seconds = int(seconds) + 1
        self.request = None
        self.code = 420
        self.message = "OUTBOUND_PACED"
        Exception.__init__(self, f"chat is busy — outbound paced for {self.seconds}s")

class FloodGovernor:
    WINDOW_GROUP = 60.0
    WINDOW_PM = 10.0

    def __init__(self, name, clock=None, sleeper=None):
        self.name = name
        self.clock = clock or time.monotonic
        self.sleeper = sleeper or asyncio.sleep
        self.events = {}                     # chat key -> [(start time, weight)] ascending (future-dated = reserved)
        self.blocked_until = {}              # chat key -> time Telegram told us to stay away until
        self.global_blocked_until = 0.0
        self.adm = {}                        # chat key -> times view/game commands were admitted
        self.glob = []                       # [(time, weight)] real sends, last second
        self.fw_log = []                     # [(time, chat key, seconds)]
        self.stats = {"sent": 0, "delayed": 0, "delay_total": 0.0, "shed_sends": 0, "floodwaits": 0, "retries": 0, "shed_cmds": 0, "notices": 0}

    # ---- who is this message going to? ----
    @staticmethod
    def chat_key(entity):
        """(key, is_group) — or None when it can't be told (a username, an inline message …): those are simply not paced."""
        if entity is None or isinstance(entity, (bool, str, bytes)):
            return None
        if isinstance(entity, int):
            if entity < 0:
                n = -entity
                if n > 10 ** 12:
                    n -= 10 ** 12            # Telegram marks a channel / supergroup id as -(10**12 + id): -1001234567890 and InputPeerChannel(1234567890) are the same chat
                return str(n), True
            return str(entity), False
        cls = type(entity).__name__
        if cls == "InputPeerSelf":
            return "self", False
        if cls == "User" or cls.startswith(("InputPeerUser", "PeerUser", "InputUser")):          # …also the *FromMessage variants Telegram hands out for peers it only knows from a message
            uid = getattr(entity, "user_id", None) or getattr(entity, "id", None)
            return (str(uid), False) if uid else None
        if cls in ("Channel", "Chat") or cls.startswith(("InputPeerChannel", "PeerChannel", "InputChannel", "InputPeerChat", "PeerChat")):
            cid = getattr(entity, "channel_id", None) or getattr(entity, "chat_id", None) or getattr(entity, "id", None)
            return (str(cid), True) if cid else None
        chat_id = getattr(entity, "chat_id", None)           # a Message passed to edit_message(): its chat decides
        if isinstance(chat_id, int) and not isinstance(chat_id, bool):
            return FloodGovernor.chat_key(chat_id)
        return None

    def _bucket(self, is_group):
        return (self.WINDOW_GROUP, FLOOD_GROUP_PER_MIN) if is_group else (self.WINDOW_PM, FLOOD_PM_PER_10S)

    # ---- reserving a slot ----
    def plan(self, key, is_group, weight):
        """-> (now, start, live events). `start` is the earliest moment this message may go out: after Telegram's block, after the minimum gap,
        and once enough of the minute's budget has expired. Reservations are future-dated, so concurrent callers queue up in order."""
        now = self.clock()
        window, budget = self._bucket(is_group)
        ev = [e for e in self.events.get(key, []) if e[0] > now - window]
        t = max(now, self.blocked_until.get(key, 0.0), self.global_blocked_until)
        if ev:
            t = max(t, ev[-1][0] + FLOOD_MIN_GAP * weight)
        live = [e for e in ev if e[0] > t - window]
        total = sum(w for _, w in live)
        if total + weight > budget + 1e-9:
            over = total + weight - budget
            removed, start = 0.0, t
            for ts, wt in live:
                removed += wt
                start = max(start, ts + window + 1e-6)
                if removed + 1e-9 >= over:
                    break
            t = start
        return now, t, ev

    def _tidy(self):
        """Forget chats that have been quiet for two minutes — a bot in thousands of groups must not keep a list for every one of them forever."""
        now = self.clock()
        for k in [k for k, ev in self.events.items() if not ev or ev[-1][0] < now - 120.0]:
            self.events.pop(k, None)
        for k in [k for k, t in self.blocked_until.items() if t < now - 120.0]:
            self.blocked_until.pop(k, None)
        for k in [k for k, a in self.adm.items() if not a or a[-1] < now - 120.0]:
            self.adm.pop(k, None)

    async def acquire(self, key, is_group, weight):
        if len(self.events) > 3000:
            self._tidy()
        now, start, ev = self.plan(key, is_group, weight)
        wait = start - now
        if wait > FLOOD_MAX_WAIT:
            self.stats["shed_sends"] += 1
            raise OutboundShed(wait)
        self.events[key] = ev + [(start, weight)]
        if wait > 0.05:
            self.stats["delayed"] += 1
            self.stats["delay_total"] += wait
            await self.sleeper(wait)
        while True:                                          # the whole-account limit (per second) — short, so a simple loop is enough
            t = self.clock()
            self.glob = [g for g in self.glob if g[0] > t - 1.0]
            if sum(w for _, w in self.glob) + weight <= FLOOD_GLOBAL_PER_SEC + 1e-9:
                break
            await self.sleeper(max(0.02, self.glob[0][0] + 1.0 - t + 0.001))
        self.glob.append((self.clock(), weight))
        self.stats["sent"] += 1

    def on_floodwait(self, key, seconds):
        now = self.clock()
        self.blocked_until[key] = max(self.blocked_until.get(key, 0.0), now + seconds + 1.0)
        self.stats["floodwaits"] += 1
        self.fw_log.append((now, key, seconds))
        del self.fw_log[:-100]
        if len({k for t, k, s in self.fw_log if now - t <= 20}) >= 3:          # several chats at once = it is the account, not the chat
            self.global_blocked_until = max(self.global_blocked_until, now + min(seconds, 10.0))
        print(f"🚦 {self.name}: Telegram FloodWait {seconds:g}s in chat {key} — nothing is sent there until it ends")

    async def call(self, orig, weight, entity, args, kwargs):
        ck = self.chat_key(entity)
        if ck is None or _FLOOD_INNER.get():
            return await orig(*args, **kwargs)
        key, is_group = ck
        attempt = 0
        while True:
            await self.acquire(key, is_group, weight)
            token = _FLOOD_INNER.set(True)
            try:
                return await orig(*args, **kwargs)
            except OutboundShed:
                raise
            except FloodWaitError as e:
                secs = float(getattr(e, "seconds", 0) or 0)
                self.on_floodwait(key, secs)
                attempt += 1
                if secs > FLOOD_RETRY_MAX or attempt > 2:
                    raise
                self.stats["retries"] += 1
                await self.sleeper(secs + 0.5)
            finally:
                _FLOOD_INNER.reset(token)

    # ---- is this group "hot"? (used by the command guard) ----
    def used(self, key, is_group=True):
        now = self.clock()
        window, _ = self._bucket(is_group)
        return sum(w for ts, w in self.events.get(key, []) if ts > now - window)

    def admitted(self, key):
        now = self.clock()
        self.adm[key] = [t for t in self.adm.get(key, []) if t > now - 60.0]
        return len(self.adm[key])

    def admit(self, chat_id):
        ck = self.chat_key(chat_id)
        if ck and ck[1]:
            self.adm.setdefault(ck[0], []).append(self.clock())

    def is_hot(self, chat_id):
        ck = self.chat_key(chat_id)
        if not ck or not ck[1]:
            return False
        key = ck[0]
        now = self.clock()
        if self.blocked_until.get(key, 0.0) > now or self.global_blocked_until > now:
            return True
        _, budget = self._bucket(True)
        if self.used(key) >= FLOOD_HOT_FRACTION * budget:
            return True
        return self.admitted(key) >= FLOOD_CHAT_CMD_CAP

    def retry_after(self, chat_id):
        """Roughly how many seconds until this group has cooled down (3 … 60) — only for the one-line notice."""
        ck = self.chat_key(chat_id)
        if not ck:
            return 3
        key, now = ck[0], self.clock()
        waits = [self.blocked_until.get(key, 0.0) - now, self.global_blocked_until - now]
        window, budget = self._bucket(True)
        live = sorted(e for e in self.events.get(key, []) if e[0] > now - window)
        over = sum(w for _, w in live) - FLOOD_HOT_FRACTION * budget
        removed = 0.0
        for ts, wt in live:
            if over < 0:
                break
            removed += wt
            waits.append(ts + window - now)
            if removed > over:
                break
        adm = sorted(t for t in self.adm.get(key, []) if t > now - 60.0)
        if len(adm) >= FLOOD_CHAT_CMD_CAP:
            waits.append(adm[len(adm) - int(FLOOD_CHAT_CMD_CAP)] + 60.0 - now)
        return int(min(60.0, max(3.0, max(waits) if waits else 3.0)) + 0.999)

    def snapshot(self):
        now = self.clock()
        window, budget = self._bucket(True)
        hot = []
        for key, ev in self.events.items():
            used = sum(w for ts, w in ev if ts > now - window)
            if used >= FLOOD_HOT_FRACTION * budget * 0.5:
                hot.append((used, key))
        hot.sort(reverse=True)
        last_fw = self.fw_log[-1] if self.fw_log else None
        return {**self.stats, "hot": hot[:5], "budget": budget, "last_floodwait": (last_fw[2], last_fw[1], now - last_fw[0]) if last_fw else None,
                "floodwaits_1h": sum(1 for t, k, s in self.fw_log if now - t <= 3600)}

_FLOOD_GOV = {}          # "bot1" -> FloodGovernor

def install_flood_governor(client, name):
    """Wraps the send-type methods of `client` (an instance-level override: Message.reply, event.respond, event.edit … all reach Telegram through these). Never
    changes arguments or return values, and re-raises every exception it did not itself raise."""
    if client is None or not FLOOD_GOVERNOR_ON:
        return None
    gov = FloodGovernor(name)
    _FLOOD_GOV[name] = gov
    for attr, weight in (("send_message", 1.0), ("send_file", 1.0), ("forward_messages", 1.0), ("edit_message", FLOOD_EDIT_WEIGHT)):
        orig = getattr(client, attr, None)
        if orig is None or getattr(orig, "_flood_wrapped", False):
            continue
        def _make(orig=orig, weight=weight):
            async def wrapper(*args, **kwargs):
                entity = args[0] if args else kwargs.get("entity")
                return await gov.call(orig, weight, entity, args, kwargs)
            wrapper._flood_wrapped = True
            return wrapper
        setattr(client, attr, _make())
    return gov

install_flood_governor(bot1, "bot1")

