from telethon.extensions import html as _tl_html   # module-local alias — can't be shadowed by a stray `html` name

_PE_MAX_PER_MESSAGE = 90   # Telegram rejects a message with > 100 entities; stay well under it

def _pe_build_matcher():
    ids = {}
    for _emoji, _doc_id in CASINO_PREMIUM_EMOJI.items():
        ids[_emoji.replace("\ufe0f", "")] = int(_doc_id)        # match with or without the VS16 selector
    alts = ["".join(re.escape(ch) + "\ufe0f?" for ch in base)
            for base in sorted(ids, key=len, reverse=True)]
    return ids, "|".join(alts)

_PE_IDS, _PE_ALT = _pe_build_matcher()
_PE_RE = re.compile(rf"(?<!\u200d)(?:{_PE_ALT})(?!\u200d)")       # skip pieces of ZWJ sequences (😮‍💨 etc.)
_PE_CODE_RE = re.compile(r"<code>(.*?)</code>", re.S)
_PE_LEAD_RE = re.compile(rf"^\s*({_PE_ALT})\s*")
_PE_TRAIL_RE = re.compile(rf"\s*({_PE_ALT})\s*$")
# entity types a custom emoji can't sit inside of
_PE_NO_NEST = tuple(getattr(types, _n) for _n in (
    "MessageEntityCode", "MessageEntityPre", "MessageEntityTextUrl", "MessageEntityUrl",
    "MessageEntityMentionName", "InputMessageEntityMentionName", "MessageEntityCustomEmoji",
) if hasattr(types, _n))

def _pe_u16len(s):
    return len(s.encode("utf-16-le")) // 2

def _pe_rebuild():
    """Re-derive the matcher tables after CASINO_PREMIUM_EMOJI changed (an ID Telegram doesn't know was dropped)."""
    global _PE_IDS, _PE_ALT, _PE_RE, _PE_LEAD_RE, _PE_TRAIL_RE
    _PE_IDS, _PE_ALT = _pe_build_matcher()
    if not _PE_ALT:
        _PE_ALT = "(?!)"          # empty map: never match (an empty alternation would match everywhere)
    _PE_RE = re.compile(rf"(?<!\u200d)(?:{_PE_ALT})(?!\u200d)")
    _PE_LEAD_RE = re.compile(rf"^\s*({_PE_ALT})\s*")
    _PE_TRAIL_RE = re.compile(rf"\s*({_PE_ALT})\s*$")

def _pe_unwrap_code(text):
    """<code>1,000 ⭐</code> → <code>1,000</code> ⭐ (and the same for a leading emoji) so the ⭐/💠
    can become a premium emoji — custom emoji can't live inside a code entity."""
    def _fix(m):
        inner = m.group(1)
        pre = post = ""
        mt = _PE_TRAIL_RE.search(inner)
        if mt:
            post = " " + mt.group(1)
            inner = inner[:mt.start()]
        ml = _PE_LEAD_RE.match(inner)
        if ml:
            pre = ml.group(1) + " "
            inner = inner[ml.end():]
        if not inner.strip():
            return m.group(0)            # the span is nothing but emoji — leave it alone
        return f"{pre}<code>{inner}</code>{post}"
    return _PE_CODE_RE.sub(_fix, text)

def _pe_add_entities(plain, ents):
    """Adds a MessageEntityCustomEmoji for every mapped emoji in `plain` (offsets are UTF-16 units,
    as Telegram wants them), skipping any that fall inside an entity they can't be nested in."""
    if not plain:
        return plain, ents
    blocked = [(e.offset, e.offset + e.length) for e in ents if isinstance(e, _PE_NO_NEST)]
    out = list(ents)
    room = _PE_MAX_PER_MESSAGE - len(out)
    pos_char = pos_u16 = 0
    for m in _PE_RE.finditer(plain):
        if room <= 0:
            break
        pos_u16 += _pe_u16len(plain[pos_char:m.start()])
        pos_char = m.start()
        start, length = pos_u16, _pe_u16len(m.group())
        if any(start < b_end and start + length > b_start for b_start, b_end in blocked):
            continue
        doc_id = _PE_IDS.get(m.group().replace("\ufe0f", ""))
        if doc_id is None:
            continue
        out.append(types.MessageEntityCustomEmoji(offset=start, length=length, document_id=doc_id))
        room -= 1
    out.sort(key=lambda e: (e.offset, -e.length))
    return plain, out

class _PremiumHtmlMode:
    """Telethon parse mode: identical to parse_mode='html', plus premium custom emoji (see the
    block comment above). Must be passed as this INSTANCE (PREMIUM_HTML), not the class."""
    def parse(self, text):
        try:
            prepared = _pe_unwrap_code(text)
        except Exception:
            prepared = text
        plain, ents = _tl_html.parse(prepared)
        if not CASINO_PREMIUM_EMOJI_ENABLED:
            return plain, ents
        try:
            return _pe_add_entities(plain, ents)
        except Exception as e:           # never let the cosmetic layer break a game message
            logging.error(f"❌ premium-emoji pass failed, sending plain emoji instead: {e}")
            return plain, ents
    def unparse(self, text, entities):
        return _tl_html.unparse(text, entities)

PREMIUM_HTML = _PremiumHtmlMode()

# ==========================================
# 🎩 OWNER HAT (2026-11, per owner request — "Owner name ရှေ့ကော နောက်ကောကနေ 🎩 ထည့်ပေးပါ — 🎩 owner 🎩")
# ==========================================
OWNER_HAT = "🎩"
_OWNER_MENTION_RE = re.compile(
    r"<a\s+href\s*=\s*(['\"])tg://user\?id=" + str(OWNER_ID) + r"\1[^>]*>.*?</a>",
    re.DOTALL | re.IGNORECASE,
)

def add_owner_hats(html_text):
    """'<a href=\'tg://user?id=OWNER\'>X</a>' -> '🎩 <a …>X</a> 🎩'. Pure string work, safe to call twice (a mention that already
    has the hats around it is left alone). Any other text is returned unchanged."""
    if not html_text or str(OWNER_ID) not in html_text:
        return html_text
    def _wrap(m):
        whole = m.string
        before = whole[max(0, m.start() - len(OWNER_HAT) - 1):m.start()]
        after = whole[m.end():m.end() + len(OWNER_HAT) + 1]
        pre = "" if before == OWNER_HAT + " " else OWNER_HAT + " "
        post = "" if after == " " + OWNER_HAT else " " + OWNER_HAT
        return f"{pre}{m.group(0)}{post}"
    return _OWNER_MENTION_RE.sub(_wrap, html_text)

_orig_tl_html_parse = _tl_html.parse

def _tl_html_parse_with_owner_hat(text):
    try:
        if isinstance(text, str):
            text = add_owner_hats(text)
    except Exception:
        pass                      # cosmetic only — never let it break a message
    return _orig_tl_html_parse(text)

if not getattr(_tl_html.parse, "_owner_hat", False):
    _tl_html_parse_with_owner_hat._owner_hat = True
    _tl_html.parse = _tl_html_parse_with_owner_hat

def _pm(client):
    """parse_mode for a casino/wallet send or edit made through `client` — always plain 'html' (bot1 can't send custom emoji)."""
    return 'html'


