async def premium_harem_state(force=False):
    now = time.time()
    if not force and (now - _PREMIUM_HAREM["ts"]) < PREMIUM_HAREM_CACHE_TTL:
        return _PREMIUM_HAREM
    try:
        doc = await bot_settings_col.find_one({"_id": PREMIUM_HAREM_SETTING_ID}) or {}
        _PREMIUM_HAREM["on"] = bool(doc.get("enabled"))
        _PREMIUM_HAREM["icons"] = bool(doc.get("icons", True))      # button icons default ON (owner can turn off)
    except Exception as e:
        print(f"⚠️ premium_harem_state read failed ({e}); keeping the last known value")
    _PREMIUM_HAREM["ts"] = now
    return _PREMIUM_HAREM

async def premium_icons_active():
    return bool((await premium_harem_state())["icons"])

# ---- Premium emoji as a button's ICON (Bot API `icon_custom_emoji_id`) ----------------------------------
# A button's text can't hold a custom emoji, but Telegram's Bot API lets an inline button carry one as its ICON
# (`icon_custom_emoji_id`, shown before the label). Telethon's own button classes can't set that, so — exactly like
# the working social-bot example — it goes through the plain Bot API with bot1's token:
#   1. bot1 sends / edits the message through Telethon as always (normal-emoji buttons, premium emoji in the text);
#   2. right after, if any button's label STARTS with an emoji that has a premium ID (CASINO_PREMIUM_EMOJI), the
#      keyboard is re-sent with Bot API editMessageReplyMarkup: that emoji becomes the button's icon and is
#      removed from the label ("🔄 Play Again" -> [🔄 premium icon] Play Again).
# It hooks bot1.send_message / bot1.edit_message once (see _install_bot1_premium_hooks), so every bot1 message with
# buttons — casino cards, the wallet, /harem pages, /hmode — gets it without touching each call site, and an edit
# that leaves the buttons alone (text-only edit) keeps the icons Telegram already has.
# If Telegram refuses (e.g. the account can't use button icons) the buttons simply stay as normal emoji buttons, the
# error is logged once, and icons pause for 10 minutes so every send isn't doubled — the same fallback the example
# bot uses. An upgrade is skipped (never half-applied) when the keyboard has a button type it can't rebuild
# (web-app / buy / auth buttons). Owner switch: /premiumharem icons on|off (default ON). Kill switch: CASINO_PREMIUM_EMOJI=0.
import urllib.error
_B3_BLANK_LABEL = "\u2800"        # invisible-looking label, so an emoji-ONLY button (🏀 🎲 🎯) can still carry a premium icon
_B3_BLANK_OK = True               # flips to False if Telegram ever refuses a blank label
_B3_ICON_BENIGN = ("message is not modified", "message to edit not found", "chat not found", "bot was blocked",
                   "forbidden", "not enough rights", "have no rights", "too many requests", "user is deactivated")

def _b3_btn_to_api(b):
    """One Telethon button -> Bot API dict, or None if it's a type we can't rebuild faithfully."""
    b = getattr(b, "button", b)
    text = getattr(b, "text", None)
    if text is None:
        return None
    d = {"text": text}
    if isinstance(b, types.KeyboardButtonCallback):
        d["callback_data"] = b.data.decode("utf-8")
    elif isinstance(b, types.KeyboardButtonSwitchInline):
        d["switch_inline_query_current_chat" if getattr(b, "same_peer", False) else "switch_inline_query"] = b.query
    elif isinstance(b, types.KeyboardButtonUrl):
        d["url"] = b.url
    else:
        return None
    st = getattr(b, "style", None)             # the colours _apply_button_style sets
    if st is not None:
        for attr, name in (("bg_success", "success"), ("bg_danger", "danger"), ("bg_primary", "primary")):
            if getattr(st, attr, None):
                d["style"] = name
                break
    return d

def _b3_pick_icon(text, allow_blank=True):
    """Which premium icon should this button label carry? -> (doc_id, new_text, used_blank) or None.
    A button can hold ONE icon, shown before its text, so:
      • "🔄 Play again"  → icon 🔄,   text "Play again"
      • "🏀"  (emoji only) → icon 🏀, a blank label (Telegram needs *some* text)
      • "10⭐" (emoji at the END, real text before it) → icon ⭐, text "10"
    (🩹 2026-10, per owner report — buttons like the casino's 🏀 🎲 🎯 and 10⭐ 50⭐ 100⭐ used to stay plain, because only
    "mapped emoji + text" at the START was recognised.)"""
    m = _PE_LEAD_RE.match(text)
    if m:
        doc_id = _PE_IDS.get(m.group(1).replace("\ufe0f", ""))
        if doc_id:
            rest = text[m.end():].strip()
            if rest:
                return doc_id, rest, False
            return (doc_id, _B3_BLANK_LABEL, True) if allow_blank else None
    m = _PE_TRAIL_RE.search(text)
    if m:
        doc_id = _PE_IDS.get(m.group(1).replace("\ufe0f", ""))
        head = text[:m.start()].strip()
        if doc_id and head and any(ch.isalnum() for ch in head):
            return doc_id, head, False
    return None

def _b3_icon_keyboard(buttons, allow_blank=None):
    """Telethon `buttons=` value -> (Bot API inline_keyboard with premium icons, used_a_blank_label), or (None, False) when
    there's nothing to upgrade (no button has a premium-mapped emoji) or the keyboard can't be rebuilt exactly."""
    if allow_blank is None:
        allow_blank = _B3_BLANK_OK
    if isinstance(buttons, types.ReplyInlineMarkup):
        src = [list(r.buttons) for r in buttons.rows]
    elif isinstance(buttons, (list, tuple)):
        if not buttons:
            return None
        src = [list(r) for r in buttons] if isinstance(buttons[0], (list, tuple)) else [list(buttons)]
    else:
        src = [[buttons]]
    rows, any_icon, used_blank = [], False, False
    for row in src:
        out = []
        for b in row:
            d = _b3_btn_to_api(b)
            if d is None:
                return None, False
            pick = _b3_pick_icon(d["text"], allow_blank=allow_blank)
            if pick:
                doc_id, new_text, blank = pick
                d["icon_custom_emoji_id"] = str(doc_id)
                d["text"] = new_text
                any_icon, used_blank = True, (used_blank or blank)
            out.append(d)
        rows.append(out)
    return (rows, used_blank) if any_icon else (None, False)

# ======================================================================================================
# 💎 BOT1 TAKEOVER (2026-11, per owner request) — bot1 sends the premium custom emoji ITSELF.
# ======================================================================================================
_PREMIUM_EMOJI_BOT1 = {"on": False}
PREMIUM_EMOJI_BOT1_SETTING_ID = "premium_emoji_bot1"
_B1_ICONS_OFF_UNTIL = 0.0
_B1_ICON_STATS = Counter()        # since start: ok / nothing (no premium emoji on the keyboard) / refused — shown by /premiumharem
_B1_ICON_LAST_ERROR = ""
_B1_ICON_PAUSE = 60               # seconds icons pause after Telegram refuses a keyboard (was 600 — one odd keyboard silenced EVERY bot1 button, Hunt included, for 10 minutes)

async def premium_emoji_bot1_state(force=False):
    try:
        doc = await bot_settings_col.find_one({"_id": PREMIUM_EMOJI_BOT1_SETTING_ID}) or {}
        _PREMIUM_EMOJI_BOT1["on"] = bool(doc.get("enabled"))
    except Exception as e:
        print(f"⚠️ premium_emoji_bot1_state read failed ({e}); keeping the last known value")
    return _PREMIUM_EMOJI_BOT1["on"]

def _b1_api_sync(method, payload):
    req = urllib.request.Request(
        f"https://api.telegram.org/bot{MAIN_BOT_TOKEN}/{method}",
        data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
        headers={"Content-Type": "application/json"},
    )
    try:
        with urllib.request.urlopen(req, timeout=8) as r:
            return json.loads(r.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        try:
            return json.loads(e.read().decode("utf-8"))
        except Exception:
            return {"ok": False, "description": f"HTTP {e.code}"}
    except Exception as e:
        return {"ok": False, "description": f"{type(e).__name__}: {e}"}

async def _b1_api(method, **payload):
    return await asyncio.to_thread(_b1_api_sync, method, payload)

async def _b1_after_send(res, buttons):
    """Premium icons on bot1's inline buttons via the Bot API . Never raises. Retries with blank labels for emoji-only buttons; a refusal pauses icons only _B1_ICON_PAUSE (60s); counts and last error show in /premiumharem."""
    global _B1_ICONS_OFF_UNTIL, _B1_ICON_LAST_ERROR, _B3_BLANK_OK
    try:
        if not buttons or not isinstance(res, types.Message):
            return
        if time.monotonic() < _B1_ICONS_OFF_UNTIL or not await premium_icons_active():
            return
        out = _b3_icon_keyboard(buttons)
        rows, used_blank = out if out else (None, False)
        if rows is None:
            _B1_ICON_STATS["nothing"] += 1
            return

        async def _send(kb):
            return await asyncio.to_thread(_b1_api_sync, "editMessageReplyMarkup",
                                           {"chat_id": res.chat_id, "message_id": res.id,
                                            "reply_markup": {"inline_keyboard": kb}})
        r = await _send(rows)
        if not r.get("ok") and used_blank and not any(f in str(r.get("description") or "").lower() for f in _B3_ICON_BENIGN):
            out2 = _b3_icon_keyboard(buttons, allow_blank=False)     # maybe Telegram doesn't take a blank label
            rows2 = out2[0] if out2 else None
            if rows2 is not None:
                r2 = await _send(rows2)
                if r2.get("ok"):
                    _B3_BLANK_OK = False
                    print("ℹ️ Telegram refuses a blank button label — icon-only buttons (🏀 🎲 🎯 …) stay plain; the rest get icons")
                    _B1_ICON_STATS["ok"] += 1
                    return
        if r.get("ok"):
            _B1_ICON_STATS["ok"] += 1
            return
        desc = str(r.get("description") or "")
        if not any(f in desc.lower() for f in _B3_ICON_BENIGN):
            _B1_ICON_STATS["refused"] += 1
            _B1_ICONS_OFF_UNTIL = time.monotonic() + _B1_ICON_PAUSE
            if desc != _B1_ICON_LAST_ERROR:
                print(f"⚠️ bot1 button icons refused by Telegram ({desc}); buttons stay plain, icons paused for {_B1_ICON_PAUSE}s")
            _B1_ICON_LAST_ERROR = desc
    except Exception as e:
        print(f"⚠️ bot1 button-icon upgrade failed ({type(e).__name__}: {e})")

def _install_bot1_premium_hooks():
    if getattr(bot1, "_pe_b1_hooks", False):
        return
    _o_send, _o_edit, _o_file = bot1.send_message, bot1.edit_message, bot1.send_file

    async def _go(orig, a, k):
        if not (_PREMIUM_EMOJI_BOT1["on"] and CASINO_PREMIUM_EMOJI_ENABLED and k.get("parse_mode") == 'html'):
            return await orig(*a, **k)
        try:
            return await orig(*a, **dict(k, parse_mode=PREMIUM_HTML))
        except errors.RPCError as e:
            if isinstance(e, (errors.FloodError, errors.MessageNotModifiedError)):
                raise
            print(f"⚠️ bot1 premium-emoji send failed ({type(e).__name__}: {e}); retrying with plain emoji")
            _f = k.get("file")
            if hasattr(_f, "seek"):
                try:
                    _f.seek(0)
                except Exception:
                    pass
            return await orig(*a, **k)

    async def send_message(*a, **k):
        res = await _go(_o_send, a, k)
        if k.get("file") is None:                  # with file= Telethon routes through send_file (hooked below)
            await _b1_after_send(res, k.get("buttons"))
        return res

    async def edit_message(*a, **k):
        res = await _go(_o_edit, a, k)
        await _b1_after_send(res, k.get("buttons"))
        return res

    async def send_file(*a, **k):
        res = await _go(_o_file, a, k)
        await _b1_after_send(res, k.get("buttons"))
        return res

    bot1.send_message, bot1.edit_message, bot1.send_file = send_message, edit_message, send_file
    bot1._pe_b1_hooks = True

_install_bot1_premium_hooks()


async def _pe_startup_check():
    await asyncio.sleep(25)
    return

# ==============================================================================================================
# 💎 /emoji — add premium emoji IDs without touching the code (2026-10, per owner request)
# ==============================================================================================================
#   /emoji 😀 <id>                  add or change one      (several at once: /emoji, then one "emoji id" per line)
#   /emoji del 😀                   remove one you added
#   /emoji list | /emoji missing    what you added · emoji in the bot's texts that still have no premium ID
# Owner only. It takes effect immediately for everything the bot sends and is saved in the database (bot_settings), so it
# survives a redeploy. The ID is checked with Telegram first, and only REAL emoji are accepted — a plain symbol such as ⇩
# has no premium version, and mapping one makes Telegram refuse the premium emoji of the whole message it appears in.
PREMIUM_EMOJI_CUSTOM_SETTING_ID = "premium_emoji_custom"
_PE_BUILTIN = dict(CASINO_PREMIUM_EMOJI)     # what main.py itself defines (before /emoji additions are merged in)
_PE_CUSTOM = {}                              # emoji -> id added with /emoji (mirrored in the database)

# "Is this really an emoji?" — Telegram only takes a custom-emoji entity on a genuine emoji character. Pictographs plus
# the text-symbol characters that have an emoji form; ⇩ ⋆ ★ → ✓ ➤ • and the like are NOT in here, on purpose.
_PE_EMO_BMP = [(0xA9, 0xA9), (0xAE, 0xAE), (0x203C, 0x203C), (0x2049, 0x2049), (0x2122, 0x2122), (0x2139, 0x2139), (0x2194, 0x2199),
    (0x21A9, 0x21AA), (0x231A, 0x231B), (0x2328, 0x2328), (0x23CF, 0x23CF), (0x23E9, 0x23F3), (0x23F8, 0x23FA), (0x24C2, 0x24C2),
    (0x25AA, 0x25AB), (0x25B6, 0x25B6), (0x25C0, 0x25C0), (0x25FB, 0x25FE), (0x2600, 0x2604), (0x260E, 0x260E), (0x2611, 0x2611),
    (0x2614, 0x2615), (0x2618, 0x2618), (0x261D, 0x261D), (0x2620, 0x2620), (0x2622, 0x2623), (0x2626, 0x2626), (0x262A, 0x262A),
    (0x262E, 0x262F), (0x2638, 0x263A), (0x2640, 0x2640), (0x2642, 0x2642), (0x2648, 0x2653), (0x265F, 0x2660), (0x2663, 0x2663),
    (0x2665, 0x2666), (0x2668, 0x2668), (0x267B, 0x267B), (0x267E, 0x267F), (0x2692, 0x2697), (0x2699, 0x2699), (0x269B, 0x269C),
    (0x26A0, 0x26A1), (0x26A7, 0x26A7), (0x26AA, 0x26AB), (0x26B0, 0x26B1), (0x26BD, 0x26BE), (0x26C4, 0x26C5), (0x26C8, 0x26C8),
    (0x26CE, 0x26CF), (0x26D1, 0x26D1), (0x26D3, 0x26D4), (0x26E9, 0x26EA), (0x26F0, 0x26F5), (0x26F7, 0x26FA), (0x26FD, 0x26FD),
    (0x2702, 0x2702), (0x2705, 0x2705), (0x2708, 0x270D), (0x270F, 0x270F), (0x2712, 0x2712), (0x2714, 0x2714), (0x2716, 0x2716),
    (0x271D, 0x271D), (0x2721, 0x2721), (0x2728, 0x2728), (0x2733, 0x2734), (0x2744, 0x2744), (0x2747, 0x2747), (0x274C, 0x274C),
    (0x274E, 0x274E), (0x2753, 0x2755), (0x2757, 0x2757), (0x2763, 0x2764), (0x2795, 0x2797), (0x27A1, 0x27A1), (0x27B0, 0x27B0),
    (0x27BF, 0x27BF), (0x2934, 0x2935), (0x2B05, 0x2B07), (0x2B1B, 0x2B1C), (0x2B50, 0x2B50), (0x2B55, 0x2B55), (0x3030, 0x3030),
    (0x303D, 0x303D), (0x3297, 0x3297), (0x3299, 0x3299)]
_PE_EMO_ASTRAL = [(0x1F004, 0x1F004), (0x1F0CF, 0x1F0CF), (0x1F170, 0x1F171), (0x1F17E, 0x1F17F), (0x1F18E, 0x1F18E), (0x1F191, 0x1F19A),
    (0x1F201, 0x1F202), (0x1F21A, 0x1F21A), (0x1F22F, 0x1F22F), (0x1F232, 0x1F23A), (0x1F250, 0x1F251), (0x1F300, 0x1F64F),
    (0x1F680, 0x1F6FF), (0x1F7E0, 0x1F7EB), (0x1F90C, 0x1F9FF), (0x1FA70, 0x1FAFF)]
def _pe_class(ranges):
    return "[" + "".join(re.escape(chr(a)) if a == b else re.escape(chr(a)) + "-" + re.escape(chr(b)) for a, b in ranges) + "]"
_PE_EMO_BASE = _pe_class(_PE_EMO_BMP + _PE_EMO_ASTRAL)
_PE_EMO_RE = re.compile(
    "(?:[\U0001F1E6-\U0001F1FF]{2})"                                        # flags
    "|(?:[0-9#*]\ufe0f?\u20e3)"                                             # keycaps
    "|(?:" + _PE_EMO_BASE + "\ufe0f?[\U0001F3FB-\U0001F3FF]?"
    "(?:\u200d" + _PE_EMO_BASE + "\ufe0f?[\U0001F3FB-\U0001F3FF]?)*)")      # emoji (+ skin tone, + ZWJ sequences)
_PE_ID_RE = re.compile(r"\d{15,20}")

def _pe_find_emoji(text):
    return _PE_EMO_RE.findall(text or "")

def _pe_norm(e):
    return e.replace("\ufe0f", "")

def _pe_parse_pairs(text):
    """'🎨 5321…' lines (several allowed, junk like '⇩ = ⬇️ 6206…' tolerated) -> (pairs [(emoji, id)], rejected [(symbol, why)],
    unparsed [line]). Every REAL emoji on a line before its ID maps to that ID; a plain symbol on the line is reported, not used."""
    import unicodedata
    pairs, rejected, unparsed = [], [], []
    for raw in (text or "").splitlines():
        line = raw.strip()
        if not line:
            continue
        nums = _PE_ID_RE.findall(line)
        if not nums:
            unparsed.append(line[:60])
            continue
        cid = int(nums[-1])
        head = line[:line.rfind(nums[-1])]
        emos = _pe_find_emoji(head)
        rest = _PE_EMO_RE.sub(" ", head)
        stray = [c for c in rest if unicodedata.category(c).startswith("S") and c not in "=+<>|~^$"]
        for c in dict.fromkeys(stray):
            rejected.append((c, "not an emoji — Telegram only allows a premium emoji on a real emoji"))
        if not emos and not stray:
            unparsed.append(line[:60])
        for e in dict.fromkeys(emos):
            pairs.append((e, cid))
    return pairs, rejected, unparsed

async def _pe_lookup_ids(ids):
    """Which of these custom-emoji IDs does Telegram know? -> ({id: the emoji it is}, None), or ({}, reason) if it couldn't ask."""
    found = {}
    ids = sorted(set(ids))
    for i in range(0, len(ids), 100):
        chunk = ids[i:i + 100]
        res = await _b1_api("getCustomEmojiStickers", custom_emoji_ids=[str(x) for x in chunk])
        if res.get("ok"):
            for st in (res.get("result") or []):
                if st.get("custom_emoji_id"):
                    found[int(st["custom_emoji_id"])] = st.get("emoji", "")
        elif res.get("error_code") == 400:         # the batch was refused (an invalid ID in it) — ask one by one
            for cid in chunk:
                r1 = await _b1_api("getCustomEmojiStickers", custom_emoji_ids=[str(cid)])
                if r1.get("ok"):
                    for st in (r1.get("result") or []):
                        if st.get("custom_emoji_id"):
                            found[int(st["custom_emoji_id"])] = st.get("emoji", "")
                elif r1.get("error_code") != 400:
                    return {}, str(r1.get("description") or "no answer")
        else:
            return {}, str(res.get("description") or "no answer")
    return found, None

async def _pe_save_custom():
    await bot_settings_col.update_one({"_id": PREMIUM_EMOJI_CUSTOM_SETTING_ID},
                                      {"$set": {"items": [[e, str(i)] for e, i in _PE_CUSTOM.items()]}}, upsert=True)

async def _pe_load_custom():
    """At startup: merge the emoji added with /emoji back in, so a redeploy loses nothing."""
    try:
        doc = await bot_settings_col.find_one({"_id": PREMIUM_EMOJI_CUSTOM_SETTING_ID}) or {}
        n = 0
        for item in (doc.get("items") or []):
            try:
                emo, cid = item[0], int(item[1])
            except Exception:
                continue
            key = next((k for k in CASINO_PREMIUM_EMOJI if _pe_norm(k) == _pe_norm(emo)), emo)
            CASINO_PREMIUM_EMOJI[key] = cid
            _PE_CUSTOM[key] = cid
            n += 1
        if n:
            _pe_rebuild()
            print(f"💎 loaded {n} premium emoji added with /emoji")
    except Exception as e:
        print(f"⚠️ couldn't load the premium emoji added with /emoji ({type(e).__name__}: {e})")

def _pe_missing_emoji():
    """Emoji used in the bot's OWN user-facing texts — string literals in main.py, not comments, docstrings or print() logging —
    that have no premium ID yet. -> [(emoji, uses)] most-used first, or None if main.py can't be read."""
    try:
        with open(os.path.abspath(__file__), "r", encoding="utf-8") as fh:
            tree = ast.parse(fh.read())
    except Exception as e:
        print(f"⚠️ couldn't scan main.py for emoji without a premium ID ({type(e).__name__}: {e})")
        return None
    skip = set()
    for node in ast.walk(tree):
        if isinstance(node, (ast.Module, ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)) and node.body:
            first = node.body[0]
            if isinstance(first, ast.Expr) and isinstance(first.value, ast.Constant) and isinstance(first.value.value, str):
                skip.add(id(first.value))                                      # docstring
        elif isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == "print":
            for child in ast.walk(node):
                skip.add(id(child))                                            # console logging, nobody sees it
    have = {_pe_norm(k) for k in CASINO_PREMIUM_EMOJI}
    counts, shown = Counter(), {}
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value, str) and id(node) not in skip:
            for e in _pe_find_emoji(node.value):
                n = _pe_norm(e)
                if n not in have:
                    counts[n] += 1
                    shown.setdefault(n, e)
    del tree
    return [(shown[n], c) for n, c in counts.most_common()]

def _pe_missing_text(missing, header=None, cap=120):
    """HTML for the "emoji with no premium ID yet" list ('' when there are none)."""
    if not missing:
        return ""
    shown = " ".join(f"{e}×{c}" for e, c in missing[:cap])
    more = f"\n… and {len(missing) - cap} rarer ones" if len(missing) > cap else ""
    return ((header + "\n") if header else "") + (
        f"❓ <b>{len(missing)} emoji in the bot's texts have no premium ID yet</b> (most used first):\n\n{escape_html(shown)}{more}\n\n"
        "Send <code>/emoji 🛒 &lt;id&gt;</code> — or <code>/emoji</code> followed by one <code>emoji id</code> per line.")

_PE_EMOJI_HELP = (
    "💎 <b>Premium emoji IDs</b>\n"
    "<code>/emoji 🎨 5321444151663800028</code> — add or change one\n"
    "Several at once: <code>/emoji</code> then one <code>emoji id</code> per line\n"
    "<code>/emoji del 🎨</code> — remove one you added\n"
    "<code>/emoji list</code> — what you've added\n"
    "<code>/emoji missing</code> — emoji in the bot's texts that still have no premium ID\n\n"
    "It applies at once to every message the bot sends, and it's saved — a redeploy keeps it.")

async def _premium_emoji_cmd_impl(event):
    if event.sender_id != OWNER_ID:
        return
    arg = (event.pattern_match.group(1) or "").strip()
    low = arg.lower()
    if not arg or low in ("help", "?"):
        return await event.reply(_PE_EMOJI_HELP, parse_mode='html')

    if low == "list":
        lines = [f"💎 <b>Added with /emoji</b>: {len(_PE_CUSTOM)} · built into main.py: {len(_PE_BUILTIN)}"]
        for k, v in _PE_CUSTOM.items():
            live = CASINO_PREMIUM_EMOJI.get(k) == v
            lines.append(f"• {k} <code>{v}</code>" + ("" if live else " — ❌ dropped (Telegram doesn't know this ID)"))
        if not _PE_CUSTOM:
            lines.append("Nothing yet — try <code>/emoji 🎨 5321444151663800028</code>.")
        return await event.reply("\n".join(lines), parse_mode='html')

    if low in ("missing", "todo"):
        missing = await asyncio.to_thread(_pe_missing_emoji)
        if missing is None:
            return await event.reply("⚠️ Couldn't read main.py to scan it.", parse_mode='html')
        return await event.reply(_pe_missing_text(missing) or "✅ Every emoji used in the bot's texts already has a premium ID.", parse_mode='html')

    if low.split()[0] in ("del", "delete", "remove", "rm"):
        parts = arg.split(None, 1)
        targets = _pe_find_emoji(parts[1] if len(parts) > 1 else "")
        if not targets:
            return await event.reply("Which one? e.g. <code>/emoji del 🎨</code>", parse_mode='html')
        out, changed = [], False
        for e in dict.fromkeys(targets):
            key = next((k for k in _PE_CUSTOM if _pe_norm(k) == _pe_norm(e)), None)
            if key:
                _PE_CUSTOM.pop(key)
                if key in _PE_BUILTIN:
                    CASINO_PREMIUM_EMOJI[key] = _PE_BUILTIN[key]
                    out.append(f"♻️ {e} — your change removed, the built-in ID is back")
                else:
                    CASINO_PREMIUM_EMOJI.pop(key, None)
                    out.append(f"🗑 {e} — removed (it's a normal emoji again)")
                changed = True
            elif any(_pe_norm(k) == _pe_norm(e) for k in _PE_BUILTIN):
                out.append(f"⚠️ {e} — it's built into main.py, so it can't be removed here")
            else:
                out.append(f"❔ {e} — you hadn't added it")
        if changed:
            _pe_rebuild()
            await _pe_save_custom()
        return await event.reply("\n".join(out), parse_mode='html')

    # ---- add / change ----
    pairs, rejected, unparsed = _pe_parse_pairs(arg)
    if not pairs and not rejected:
        return await event.reply("Couldn't find an <code>emoji id</code> pair. Example: <code>/emoji 🎨 5321444151663800028</code>\n"
                                 "(an ID is the long number, 15–20 digits)", parse_mode='html')
    found, problem = await _pe_lookup_ids([cid for _, cid in pairs]) if pairs else ({}, None)
    added, bad, odd, changed = [], [], [], False
    for emo, cid in pairs:
        if not problem and cid not in found:
            bad.append((emo, cid))
            continue
        key = next((k for k in CASINO_PREMIUM_EMOJI if _pe_norm(k) == _pe_norm(emo)), emo)
        prev = CASINO_PREMIUM_EMOJI.get(key)
        CASINO_PREMIUM_EMOJI[key] = cid
        _PE_CUSTOM[key] = cid
        changed = True
        added.append(f"{emo} <code>{cid}</code>" + ("" if prev is None else (" (same as before)" if prev == cid else " (replaced the old ID)")))
        sh = found.get(cid)
        if sh and _pe_norm(sh) != _pe_norm(emo):
            odd.append(f"{emo} → that ID is a {sh}")
    if changed:
        _pe_rebuild()
        await _pe_save_custom()
    out = []
    if added:
        out.append("✅ <b>Added</b> — live now, and saved:\n" + "\n".join("• " + a for a in added))
    if bad:
        out.append("❌ <b>Telegram doesn't know these IDs</b> (typo, or not a custom emoji) — not added:\n"
                   + "\n".join(f"• {e} <code>{c}</code>" for e, c in bad))
    if rejected:
        out.append("⛔ <b>Not real emoji</b> — skipped:\n" + "\n".join(f"• {escape_html(c)} — {w}" for c, w in rejected))
    if unparsed:
        out.append("❔ Couldn't read: " + escape_html(" | ".join(unparsed[:5])))
    if problem and added:
        out.append(f"⚠️ I couldn't reach Telegram to check the IDs (<code>{escape_html(problem[:100])}</code>) — saved unverified.")
    if odd:
        out.append("ℹ️ Mapped to a different emoji than its own (fine if you meant it):\n" + "\n".join("• " + escape_html(o) for o in odd[:10]))
    await event.reply("\n\n".join(out), parse_mode='html')

