# ==========================================
# ⚖️ FAIR SPAWN SELECTION (2026-10, per owner request — "ကဒ်အသစ်အဟောင်းမျှတအောင်ချပေး၊ အဟောင်းတွေ catch …
# ==========================================
SPAWN_TIER_FIRST_SELECTION = True
SPAWN_FAIR_CATCH_TARGET = 10      # catches every card should reach before already-caught cards get priority
SPAWN_FAIR_DEFICIT_STEP = 2       # extra pull per catch still missing from the target
SPAWN_UNKNOWN_TIER_WEIGHT = 1     # share for a card whose rarity can't be classified (a stray shouldn't take a big slice)

def spawn_fairness_multiplier(char):
    """1 + STEP x (catches still missing from the target); plain 1 once a card has reached it."""
    try:
        catches = int(char.get("spawn_count") or 0)
    except (TypeError, ValueError):
        catches = 0
    return 1 + SPAWN_FAIR_DEFICIT_STEP * max(0, SPAWN_FAIR_CATCH_TARGET - catches)

def spawn_card_weights(cards, tier_weights, now_ts):
    """One random.choices() weight per card, in order. Tier-first mode: each tier's cards share that
    tier's weight in proportion to spawn_fairness_multiplier, so a tier's total is exactly its weight.
    Legacy mode (SPAWN_TIER_FIRST_SELECTION = False): tier weight x freshness boost, per card."""
    tiers = [c.get("rarity_tier") or classify_rarity(c.get("rarity", "")) for c in cards]
    if not SPAWN_TIER_FIRST_SELECTION:
        return [tier_weights.get(t, 20) * spawn_freshness_multiplier(c, now_ts) for c, t in zip(cards, tiers)]
    fair = [spawn_fairness_multiplier(c) for c in cards]
    totals = {}
    for t, f in zip(tiers, fair):
        totals[t] = totals.get(t, 0.0) + f
    return [tier_weights.get(t, SPAWN_UNKNOWN_TIER_WEIGHT) * f / totals[t] for t, f in zip(tiers, fair)]

def spawn_freshness_multiplier(char, now_ts):
    """Temporary spawn-weight boost for a character younger than NEW_CHARACTER_BOOST_DAYS (1.0 for
    everyone else). Module-level so trigger_dynamic_spawn and the /spawnweight odds readout can't drift."""
    created_at = char.get("created_at")
    if not created_at:
        return 1.0
    age_days = (now_ts - created_at) / 86400
    if age_days >= NEW_CHARACTER_BOOST_DAYS or age_days < 0:
        return 1.0
    return NEW_CHARACTER_BOOST_MULTIPLIER
