def _rarity_gate_mask_hint(number_str, reveal_count=1):
    """Masks a 4-digit number with * leaving reveal_count random digits visible ('6820', 1 -> '*8**'). The correct gate slot gets more revealed digits than the rest, so the gate is deliberately solvable."""
    reveal_at = set(random.sample(range(4), min(reveal_count, 4)))
    return "".join(ch if i in reveal_at else "*" for i, ch in enumerate(number_str))

