# ---- finding the emoji at the START of what the owner typed ------------------------------------------------------
# 🩹 FIX (2026-10, per owner report — "♥ Event Name ♥ ဆိုပြီးထားပေမယ့် 🎪 ပဲ [] ထဲပြနေတာ"): the emoji used to be "the first …
_EMOJI_JOINERS = ("\u200d", "\ufe0f", "\ufe0e", "\u20e3")

def _is_emoji_base(ch):
    if not ch or ch.isalnum() or ch.isspace():
        return False
    o = ord(ch)
    return unicodedata.category(ch) in ("So", "Sk") or 0x1F000 <= o <= 0x1FAFF

def _first_emoji_end(s):
    """Index just past the FIRST emoji at the start of `s` (0 if `s` doesn't start with an emoji)."""
    n = len(s or "")
    if not n:
        return 0
    c0 = s[0]
    if 0x1F1E6 <= ord(c0) <= 0x1F1FF:                              # flag = two regional-indicator letters
        i = 2 if n > 1 and 0x1F1E6 <= ord(s[1]) <= 0x1F1FF else 1
    elif c0 in "0123456789#*" and n > 1 and s[1] in ("\ufe0f", "\u20e3"):   # keycap 1️⃣ #️⃣
        i = 1
    elif _is_emoji_base(c0):
        i = 1
    else:
        return 0
    while i < n:
        c = s[i]
        if c in _EMOJI_JOINERS or 0x1F3FB <= ord(c) <= 0x1F3FF:    # VS16 / ZWJ / keycap mark / skin tone
            i += 1
            if c == "\u200d" and i < n and _is_emoji_base(s[i]):   # 👩‍🎤 — the emoji after the joiner is part of it
                i += 1
        else:
            break
    return i

def parse_event_text(text):
    """'🎃 Halloween 2026' -> ('🎃', 'Halloween 2026');  '💃Angel💃' -> ('💃', 'Angel💃');  '♥ Event Name ♥' -> ('♥', 'Event Name ♥').
    No emoji typed at all ('Halloween') -> ('🎪', 'Halloween') as a last-resort placeholder. (None, None) if empty."""
    text = " ".join((text or "").split())
    if not text:
        return None, None
    end = _first_emoji_end(text)
    if end:
        return text[:end], text[end:].strip()
    return CUSTOM_EVENT_DEFAULT_EMOJI, text

def event_filter_label(ev):
    """Display label for an /hmode event choice — an ULTRA kind's string, or a custom event's '🎃 Name'."""
    if ev in EVENT_TYPES:
        return EVENT_TYPES[ev]
    c = _CUSTOM_EVENTS.get(ev)
    return c["label"] if c else None

def char_in_event(char_doc, ev):
    """Is this character under /hmode event choice `ev` (ULTRA kind or custom event)?"""
    if ev in EVENT_TYPES:
        return event_label_of(char_doc) == EVENT_TYPES[ev]
    return char_doc.get("custom_event_no") == ev

def custom_event_list_html():
    if not _CUSTOM_EVENTS:
        return "<i>No events yet — create one with</i> <code>/newevent 🎃 Name</code>"
    return "\n".join(f"<code>{no}</code> = {escape_html(ev['label'])}" for no, ev in sorted(_CUSTOM_EVENTS.items()))

async def load_custom_events():
    try:
        docs = await custom_events_col.find({}).to_list(length=None)
        _CUSTOM_EVENTS.clear()
        for d in docs:
            if d.get("no") is None:
                continue
            emoji = d.get("emoji") or CUSTOM_EVENT_DEFAULT_EMOJI
            name = d.get("name") or ""
            label = d.get("label") or f"{emoji} {name}"
            # 🩹 One-time self-repair (2026-10): an event saved while the glued-emoji bug existed ("💃Angel💃" -> emoji 🎪,
            # name "💃Angel💃") gets its real emoji back — its name STARTS with an emoji while its stored emoji is only the
            # placeholder. Saved to the DB and onto its cards, so nothing has to be re-typed by hand.
            if emoji == CUSTOM_EVENT_DEFAULT_EMOJI and _first_emoji_end(name):
                _end = _first_emoji_end(name)
                _fixed_emoji, _fixed_name = name[:_end], name[_end:].strip()
                if _fixed_name and any(ch.isalnum() for ch in _fixed_name):
                    emoji, name, label = _fixed_emoji, _fixed_name, f"{_fixed_emoji} {_fixed_name}"
                    try:
                        await custom_events_col.update_one({"no": int(d["no"])}, {"$set": {"emoji": emoji, "name": name, "label": label}})
                        await characters_base_col.update_many({"custom_event_no": int(d["no"])}, {"$set": {"custom_event": label}})
                        print(f"🎪 repaired event #{d['no']}: now {label}")
                    except Exception as fe:
                        print(f"load_custom_events repair error (#{d['no']}): {fe}")
            _CUSTOM_EVENTS[int(d["no"])] = {"no": int(d["no"]), "emoji": emoji, "name": name, "label": label}
        print(f"🎪 {len(_CUSTOM_EVENTS)} custom event(s) loaded")
    except Exception as e:
        print(f"load_custom_events error: {e}")

async def create_custom_event(emoji, name, created_by):
    """Next number in sequence — from a counter that only ever goes up, so deleting an event never makes its number
    mean something else later."""
    seq = await bot_settings_col.find_one_and_update(
        {"_id": "custom_event_seq"}, {"$inc": {"n": 1}}, upsert=True, return_document=ReturnDocument.AFTER)
    no = CUSTOM_EVENT_FIRST_NO + int(seq["n"]) - 1
    doc = {"no": no, "emoji": emoji, "name": name, "label": f"{emoji} {name}"}
    await custom_events_col.insert_one({**doc, "created_by": created_by, "created_at": time.time()})
    _CUSTOM_EVENTS[no] = doc
    return doc

def current_rarity_filter_name(raw_filter):
    """🩹 FIX (per owner report — "/hmode shows the OLD rarity instead of the new one"): a player's saved
    users.rarity_filter is the full rarity STRING as it was when they tapped the button (emoji + fancy name +
    No.X). After a rename/re-emoji (LEGEND ☀️ -> SUPREME 🪞, EPIC ⚡ -> DIVINE ⚜️, ...) that stored string is
    stale, so /hmode kept showing the old name, never ticked the ✅ on the new button, and /harem's "Filter:"
    line printed the old name too. The filter always MEANT a tier, so this maps whatever is stored back onto
    the tier (classify_rarity understands old and new names) and returns that tier's CURRENT official name.
    Anything it can't classify is returned untouched."""
    if not raw_filter:
        return raw_filter
    num = RARITY_TIER_TO_NUM.get(classify_rarity(raw_filter))
    return RARITY_NUM_MAP[num]["name"] if num else raw_filter

def rarity_filter_emoji(raw_filter):
    """Just the rarity's EMOJI for a saved /hmode filter (2026-11, per owner request — /harem shows the emoji only, no "DIVINE No.4"
    after it). Goes through the same tier lookup as current_rarity_filter_name, so an old saved name still shows today's emoji.
    Anything it can't classify falls back to its first word, so a filter never shows up blank."""
    if not raw_filter:
        return ""
    tier = classify_rarity(raw_filter)
    if tier in RARITY_TIER_TO_NUM and RARITY_EMOJI.get(tier):
        return RARITY_EMOJI[tier]
    return str(raw_filter).split(" ", 1)[0]

def event_filter_emoji(ev):
    """Just the emoji of an /hmode event choice ('🎌 Anime 🎌' -> '🎌', '🎃 Halloween' -> '🎃')."""
    label = event_filter_label(ev) or ""
    return label.split(" ", 1)[0] if label else ""

