# 🏆 TRIVIA 3-DAY SEASONS + TOP 10 VLT REWARD (2026-11, per owner request — "Trivia rank မှာ pts အများကြီးနဲ့ old quiz ဖြေသူတွေက အမြဲ top ယူနေလို့ …
TRIVIA_SEASON_DAYS = 3
TRIVIA_SEASON_SETTING_ID = "trivia_season"
# 🩹 CHANGED (per owner request — "star 5000 ကနေ vlt 3000 ပြောင်းပေးပါ"): this whole tier used …
TRIVIA_TOP10_REWARD_VLT = [3000, 2400, 1800, 1500, 1200, 1050, 900, 750, 600, 450]
# ^ index 0 = rank 1 (top), index 9 = rank 10. This list is the ONLY place that needs to
# change to adjust the payout scale.

async def get_current_trivia_top10_ids():
    """Set of user_ids currently on this SEASON's Top 10 (by `trivia_points_period`). Used by the Top 10 double wrong-penalty in trivia_answer_callback — a fresh, cheap
    indexed query every call rather than a cache, since the caller needs exactly current standings. Empty right after a reset (nobody has season points yet)."""
    top_users = await users_catcher_col.find(
        {"trivia_points_period": {"$gt": 0}, "user_id": {"$nin": banned_user_ids()}}, {"user_id": 1}
    ).sort("trivia_points_period", -1).limit(10).to_list(length=10)
    return {u["user_id"] for u in top_users}

def _trivia_next_midnight(ts):
    """The first 00:00 (TZ) at or after unix time `ts`."""
    d = datetime.fromtimestamp(ts, TZ)
    m = d.replace(hour=0, minute=0, second=0, microsecond=0)
    if m < d:
        m += timedelta(days=1)
    return m.timestamp()

async def get_trivia_season():
    """-> the season doc {"no", "ends_at", "state", ...}; the very first call creates season 1."""
    doc = await bot_settings_col.find_one({"_id": TRIVIA_SEASON_SETTING_ID})
    if doc:
        return doc
    now = time.time()
    await bot_settings_col.update_one(
        {"_id": TRIVIA_SEASON_SETTING_ID},
        {"$setOnInsert": {"no": 1, "state": "active", "started_at": now,
                          "ends_at": _trivia_next_midnight(now + TRIVIA_SEASON_DAYS * 86400)}},
        upsert=True)
    return await bot_settings_col.find_one({"_id": TRIVIA_SEASON_SETTING_ID}) or {"no": 1, "state": "active", "ends_at": now + TRIVIA_SEASON_DAYS * 86400}

def trivia_fmt_remaining(seconds):
    seconds = max(0, int(seconds))
    d, rem = divmod(seconds, 86400)
    h, rem = divmod(rem, 3600)
    m = rem // 60
    if d:
        return f"{d}d {h}h"
    return f"{h}h {m}m" if h else f"{m}m"

async def send_trivia_top10_rewards(season_no):
    """Pays TRIVIA_TOP10_REWARD_VLT to the season's Top 10 by `trivia_points_period`, most to least by rank. Announces the full list to the force-sub group AND DMs each winner.
    Each payout is stamped `trivia_paid_season` = season_no in the same atomic update, so calling this again for the same season (a retry after a crash) pays nobody twice.
    A DM failure never stops the rest. -> list of {user_id, name, pts, reward, rank} for the people paid by THIS call."""
    n = len(TRIVIA_TOP10_REWARD_VLT)
    top_users = await users_catcher_col.find(
        {"trivia_points_period": {"$gt": 0}, "user_id": {"$nin": banned_user_ids()}}
    ).sort("trivia_points_period", -1).limit(n).to_list(length=n)
    if not top_users:
        return []
    lines, paid = [], []
    for idx, u in enumerate(top_users):
        reward = TRIVIA_TOP10_REWARD_VLT[idx]
        pts = u.get("trivia_points_period", 0)
        try:
            res = await users_catcher_col.update_one(
                {"user_id": u["user_id"], "trivia_paid_season": {"$ne": season_no}},
                {"$inc": {"vlt_balance": reward}, "$set": {"trivia_paid_season": season_no}})
        except Exception as e:
            print(f"Trivia Top10 reward payout error for {u['user_id']}: {e}")
            continue
        if not res.modified_count:
            continue                      # already paid for this season
        uname = escape_html(clean_display_name(u.get("fullname"), fallback=f"Agent {u['user_id']}"))
        mention = f"<a href='tg://user?id={u['user_id']}'>{uname}</a>"
        lines.append(f"<b>{idx + 1}.</b> {mention} — <code>{pts} pts</code> → +<code>{format_vlt_plain(reward)}💠</code>")
        paid.append({"user_id": u["user_id"], "name": clean_display_name(u.get("fullname"), fallback=f"Agent {u['user_id']}"),
                     "pts": pts, "reward": reward, "rank": idx + 1})
        try:
            await send_safe_message(
                bot1, u["user_id"],
                f"🏆 <b>Trivia Top 10!</b>\n"
                f"You finished <b>#{idx + 1}</b> in Season <b>{season_no}</b> ({TRIVIA_SEASON_DAYS}-day) with <code>{pts}</code> Season Points.\n"
                f"💠 <b>Reward:</b> +<code>{format_vlt_plain(reward)}💠</code> — credited now!",
                parse_mode='html'
            )
        except Exception:
            pass  # blocked the bot / DMs closed — the group announcement still credits them publicly
    if lines:
        announce_text = (f"🏆 <b>TRIVIA TOP 10 REWARDS — Season {season_no}</b>\n\n" + "\n".join(lines)
                         + f"\n\n🔄 <i>Season points reset to 0 now — a new {TRIVIA_SEASON_DAYS}-day season starts. All-time ranks are kept.</i>")
        try:
            await send_safe_message(bot1, FORCE_SUB_CHAT_ID, announce_text, parse_mode='html')
        except Exception as e:
            print(f"Trivia Top10 reward announcement failed: {e}")
    return paid

async def trivia_season_rollover():
    """Ends the current season once its time is up: pay the Top 10, save the history, reset every season score, start the next season. Safe to call any time —
    -> True if it ran. A season left half-finished by a crash (state "rolling") is resumed; payouts are idempotent per user (see send_trivia_top10_rewards)."""
    now = time.time()
    doc = await bot_settings_col.find_one_and_update(
        {"_id": TRIVIA_SEASON_SETTING_ID, "state": "active", "ends_at": {"$lte": now}},
        {"$set": {"state": "rolling", "rolling_at": now}})          # returns the doc as it was BEFORE the update
    if doc is None:
        doc = await bot_settings_col.find_one({"_id": TRIVIA_SEASON_SETTING_ID, "state": "rolling"})
        if doc is None:
            return False
    no = doc.get("no", 1)
    paid = await send_trivia_top10_rewards(no)                        # 1) VLT first …
    try:
        await trivia_season_history_col.update_one({"no": no}, {"$set": {"no": no, "ended_at": now, "top10": paid}}, upsert=True)
    except Exception as e:
        print(f"Trivia season history save failed: {e}")
    await users_catcher_col.update_many({"trivia_points_period": {"$gt": 0}}, {"$set": {"trivia_points_period": 0}})   # 2) … then reset
    step = TRIVIA_SEASON_DAYS * 86400
    ends = float(doc.get("ends_at") or now)
    while ends <= now:                                                # a long outage skips the missed seasons instead of paying them all
        ends += step
    await bot_settings_col.update_one(                                # 3) next season
        {"_id": TRIVIA_SEASON_SETTING_ID},
        {"$set": {"state": "active", "no": no + 1, "started_at": now, "ends_at": ends}})
    print(f"🏆 Trivia season {no} closed — {len(paid)} Top-10 payouts, scores reset; season {no + 1} runs until {datetime.fromtimestamp(ends, TZ):%Y-%m-%d %H:%M}")
    return True

async def trivia_top10_reward_scheduler():
    """Loop: sleep until the current season ends (re-reading the season doc at least hourly), then run trivia_season_rollover(). Survives restarts — the schedule lives in the database."""
    while True:
        try:
            doc = await get_trivia_season()
            wait = 0.0 if doc.get("state") == "rolling" else max(0.0, float(doc.get("ends_at", 0)) - time.time())
            if wait > 0:
                await asyncio.sleep(min(wait, 3600))
                continue
            if not await trivia_season_rollover():
                await asyncio.sleep(5)
        except Exception as e:
            print(f"Trivia season scheduler error: {e}")
            await asyncio.sleep(60)

