# 🌙 NIGHTLY VLT DRAW (2026-10, per owner request — "Main Group @BODgram_SF ထဲမှာ ည ၉ နာရီတိုင်း bot user ၅ ယောက်ကို ကျပန်း VLT ၃၀၀၀ စီပေးမယ်")
# ==========================================
NIGHTLY_DRAW_ENABLED = os.environ.get("NIGHTLY_DRAW_ENABLED", "1") != "0"
NIGHTLY_DRAW_HOUR = int(os.environ.get("NIGHTLY_DRAW_HOUR", "21"))
NIGHTLY_DRAW_WINNERS = int(os.environ.get("NIGHTLY_DRAW_WINNERS", "5"))
NIGHTLY_DRAW_VLT = int(os.environ.get("NIGHTLY_DRAW_VLT", "3000"))
nightly_draw_log_col = db["nightly_vlt_draws"]

async def _pick_nightly_winners(n):
    try:
        banned = {d["user_id"] async for d in gban_col.find({"active": True}, {"user_id": 1, "_id": 0})}
    except Exception:
        banned = set()
    winners, tried = [], set()
    for _ in range(10):                                             # up to 10 random batches of 40 candidates
        batch = await users_catcher_col.aggregate([
            {"$match": {"total_caught": {"$gt": 0}}},
            {"$sample": {"size": 40}},
            {"$project": {"_id": 0, "user_id": 1, "fullname": 1}},
        ]).to_list(length=40)
        if not batch:
            break
        for u in batch:
            uid = u.get("user_id")
            if not uid or uid in tried or uid == OWNER_ID or uid in banned:
                continue
            tried.add(uid)
            if not await is_force_sub_member(uid, force_confirm=True):
                continue
            winners.append(u)
            if len(winners) >= n:
                return winners
    return winners

async def run_nightly_vlt_draw(label="scheduled"):
    """Picks the winners, credits them and posts the announcement. Returns the number of winners paid."""
    winners = await _pick_nightly_winners(NIGHTLY_DRAW_WINNERS)
    if not winners:
        print("🌙 Nightly VLT draw: no eligible winners found.")
        return 0
    lines, paid = [], []
    for i, u in enumerate(winners, 1):
        try:
            await users_catcher_col.update_one({"user_id": u["user_id"]}, {"$inc": {"vlt_balance": NIGHTLY_DRAW_VLT}})
        except Exception as e:
            print(f"Nightly draw payout error for {u['user_id']}: {e}")
            continue
        paid.append(u["user_id"])
        name = escape_html(clean_display_name(u.get("fullname"), fallback=f"Agent {u['user_id']}"))
        lines.append(f"<b>{i}.</b> <a href='tg://user?id={u['user_id']}'>{name}</a> — <code>+{NIGHTLY_DRAW_VLT:,} 💠</code>")
    if not paid:
        return 0
    try:
        await nightly_draw_log_col.insert_one({"date": datetime.now(TZ).strftime("%Y-%m-%d"), "label": label, "winners": paid,
                                               "amount": NIGHTLY_DRAW_VLT, "timestamp": time.time()})
    except Exception as e:
        print(f"Nightly draw log error: {e}")
    text = (
        f"🌙 <b>{small_caps_full('nightly vlt draw')}</b> · <b>{NIGHTLY_DRAW_HOUR:02d}:00</b>\n"
        f"<i>ဒီည ကံထူးရှင် {len(paid)} ဦးကို 💠 {NIGHTLY_DRAW_VLT:,} စီ ပေးလိုက်ပါပြီ!</i>\n\n"
        f"<blockquote>{chr(10).join(lines)}</blockquote>\n"
        f"🎉 <b>Congratulations!</b> 💠 VLT ကို balance ထဲ ထည့်ပေးပြီးပါပြီ။ မနက်ဖြန်ညလည်း ပါဝင်ဖို့ ဒီ group ထဲမှာ ရှိနေပါ။"
    )
    try:
        await send_safe_message(bot1, FORCE_SUB_CHAT_ID, text, parse_mode='html', link_preview=False)
    except Exception as e:
        print(f"Nightly draw announcement failed: {e}")
    return len(paid)

async def _claim_nightly_draw(today):
    """Atomic once-per-day claim — True for the one caller that wins the day."""
    from pymongo.errors import DuplicateKeyError
    try:
        await bot_settings_col.update_one({"_id": "nightly_vlt_draw", "last_date": {"$ne": today}},
                                          {"$set": {"last_date": today}}, upsert=True)
        return True
    except DuplicateKeyError:
        return False

async def nightly_vlt_draw_scheduler():
    done_date, failed_tries = None, 0
    while True:
        try:
            now = datetime.now(TZ)
            today = now.strftime("%Y-%m-%d")
            if NIGHTLY_DRAW_ENABLED and now.hour >= NIGHTLY_DRAW_HOUR and done_date != today:
                done_date = today                                   # whatever happens next, don't re-check the DB every minute tonight
                if await _claim_nightly_draw(today):
                    if await run_nightly_vlt_draw("scheduled") == 0 and failed_tries < 5:
                        # nobody could be paid (e.g. a Telegram hiccup during the membership checks) — give the day back and retry in ~10 min
                        failed_tries += 1
                        await bot_settings_col.update_one({"_id": "nightly_vlt_draw"}, {"$set": {"last_date": ""}})
                        done_date = None
                        await asyncio.sleep(600)
                        continue
        except Exception as e:
            print(f"nightly_vlt_draw_scheduler error: {e}")
        await asyncio.sleep(60)

