_DEAD_LOG_COLLECTIONS = ("star_purchase_log", "star_sell_log", "star_exchange_log", "vlt_exchange_log")
async def purge_dead_logs():
    """Drops the four retired history-log collections if they still exist (frees their data AND their indexes). Safe to run on every start:
    once they are gone this is a single cheap list call."""
    try:
        existing = set(await db.list_collection_names())
        for name in _DEAD_LOG_COLLECTIONS:
            if name in existing:
                await db.drop_collection(name)
                print(f"🧹 dropped retired log collection: {name}")
    except Exception as e:
        print(f"purge_dead_logs error: {e}")

async def data_retention_loop():
    await asyncio.sleep(120)
    await purge_dead_logs()
    while True:
        try:
            removed = 0
            day_cut = (datetime.now(TZ) - timedelta(days=3)).strftime("%Y-%m-%d")
            removed += (await casino_daily_col.delete_many({"date": {"$lt": day_cut}})).deleted_count
            removed += (await spam_mutes_col.delete_many({"last": {"$lt": time.time() - SPAM_STRIKE_MEMORY_SECONDS}})).deleted_count
            if removed:
                print(f"🧹 data retention: removed {removed} old log rows")
        except Exception as e:
            print(f"data_retention_loop error: {e}")
        await asyncio.sleep(86400)

