# 🆕 EXCLUSIVE ARTWORK CHANNEL GATE (2026-11, per owner request) — /gift, /giftvlt, /giftstar, /top, /gtop, /daily, /hunt, /game, /casino …
# ==========================================
_EXL_CH_CACHE = {}          # user_id -> (is_member, expiry_ts, checked_at)
_EXL_CH_PAID = set()        # user ids known to be already paid (saves a DB write on every /gift)
_EXL_CH_WARNED = False

async def is_exclusive_channel_member(user_id, force_confirm=False):
    global _EXL_CH_WARNED
    now = time.time()
    c = _EXL_CH_CACHE.get(user_id)
    if c and now < c[1]:
        if c[0]:
            return True
        if not force_confirm or now - c[2] < FORCE_SUB_CONFIRM_DEBOUNCE:
            return False
    try:
        perms = await bot1.get_permissions(EXCLUSIVE_CHANNEL_ID, user_id)
        is_member = perms is not None and not getattr(perms, "is_banned", False)
    except errors.UserNotParticipantError:
        is_member = False
    except Exception as e:
        if not _EXL_CH_WARNED:
            _EXL_CH_WARNED = True
            print(f"⚠️ Exclusive-channel membership check failed ({type(e).__name__}: {e}) — failing open. Is bot1 an ADMIN of {EXCLUSIVE_CHANNEL_ID}?")
        return True
    if len(_EXL_CH_CACHE) > 5000:
        _EXL_CH_CACHE.clear()
    _EXL_CH_CACHE[user_id] = (is_member, now + (FORCE_SUB_MEMBERSHIP_TTL if is_member else FORCE_SUB_MEMBERSHIP_NEGATIVE_TTL), now)
    return is_member

def _exl_ch_reward_text():
    return ("<b>Channel ကို Join ပြီးပါပြီ — Reward ရောက်ပါပြီ!</b>\n"
            f"<code>{format_star_plain(EXCLUSIVE_CHANNEL_REWARD_STAR)}</code> + "
            f"<code>{format_vlt_plain(EXCLUSIVE_CHANNEL_REWARD_VLT)}</code>")

async def _exclusive_channel_reward(user_id, name_event=None):
    """Pay the channel-join reward once. -> True only when THIS call paid it. Never raises."""
    if user_id in _EXL_CH_PAID:
        return False
    try:
        if name_event is not None:
            await ensure_user_registered(user_id, await get_plain_name(name_event, user_id))
        res = await users_catcher_col.update_one(
            {"user_id": user_id, "exclusive_channel_rewarded": {"$ne": True}},
            {"$inc": {"star_balance": EXCLUSIVE_CHANNEL_REWARD_STAR, "vlt_balance": EXCLUSIVE_CHANNEL_REWARD_VLT},
             "$set": {"exclusive_channel_rewarded": True}})
        if res.modified_count:
            _EXL_CH_PAID.add(user_id)
            return True
        doc = await users_catcher_col.find_one({"user_id": user_id}, {"exclusive_channel_rewarded": 1})
        if doc and doc.get("exclusive_channel_rewarded"):
            _EXL_CH_PAID.add(user_id)            # already paid earlier; a missing account is NOT marked, so it can still be paid later
    except Exception as e:
        print(f"⚠️ exclusive channel join reward error for {user_id}: {e}")
    return False

