# ==========================================
# 🛡️ GAME SPAM THROTTLE (every group — not just the force-join room)
# ==========================================
# Originally scoped to just the force-join room, since that was bot1's busiest room for
# casino/economy commands. But the same problem — a group of people rapid-firing a game command
# at once — happens in ANY group bot1 is in, and each send/edit call eats into bot1's own
# per-chat and per-account send budget. This now throttles game commands everywhere, using the
# same per-player cooldown. The notice is posted via bot1 (the event's own client).
GUARD_GAME_COOLDOWN_SECONDS = 4  # minimum gap between game commands per player, in any one chat
GUARD_GAME_COMMANDS = {"slot", "basketball", "bball", "dice", "rps", "dart", "darts", "football", "soccer", "fb", "bowling", "bowl", "mines", "mine", "wheel", "luckywheel", "crash"}  # 🩹 2026-08 (per owner request): every other casino game was removed, then basketball/dice were added back as native-dice games alongside slot

# 🚦 2026-11 (owner: Sunday rush — "mine/balance/today/gift/harem တွေ ဆက်တိုက်ပြုံလုပ်လို့ flooding ဖြစ်ပြီး ရပ်တန့်နေခဲ့တယ်") — INGRESS half of the flood governor (egress half: see FloodGovernor …
FLOOD_VIEW_COMMANDS = {"balance", "bal", "today", "top", "gtop", "richest", "stars", "harem", "info", "id", "points", "profile", "topgift", "topcouples", "hunters", "giftranks",
                       "stats", "triviarank", "market", "events", "dex", "show", "gift"}
FLOOD_VIEW_COOLDOWN_SECONDS = 3
_flood_user_notice_at = {}     # (user_id, chat_id) -> when that player last got the "ခဏစောင့်ပါ" notice
_flood_chat_notice_at = {}     # chat_id -> when the group last got the "busy" notice

def _flood_notifier(event):
    return event.client

async def _flood_user_notice(event, remaining, gov):
    now = time.time()
    key = (event.sender_id, event.chat_id)
    if now - _flood_user_notice_at.get(key, 0.0) < 20:
        return                                               # already told them — every extra reply is one more message in a busy chat
    if gov is not None and not event.is_private and gov.is_hot(event.chat_id):
        return
    _flood_user_notice_at[key] = now
    if len(_flood_user_notice_at) > 5000:
        for k in [k for k, v in _flood_user_notice_at.items() if v < now - 120]:
            _flood_user_notice_at.pop(k, None)
    notifier = _flood_notifier(event)
    try:
        warn = await notifier.send_message(
            event.chat_id,
            f" <b>ခဏစောင့်ပါ!</b> Game တွေ မကြာခဏ မဆော့ပါနဲ့ — <code>{remaining}s</code> လောက် စောင့်ပြီးမှ ထပ်ကစားပါ။",
            parse_mode='html'
        )
        schedule_game_cleanup(notifier, event.chat_id, warn, delay=5)
    except Exception:
        pass
    try:
        await event.delete()
    except Exception:
        pass

async def _flood_chat_notice(event, gov):
    gov.stats["shed_cmds"] += 1
    now = time.time()
    if now - _flood_chat_notice_at.get(event.chat_id, 0.0) < 60:
        return
    _flood_chat_notice_at[event.chat_id] = now
    if len(_flood_chat_notice_at) > 2000:
        for k in [k for k, v in _flood_chat_notice_at.items() if v < now - 300]:
            _flood_chat_notice_at.pop(k, None)
    gov.stats["notices"] += 1
    wait = gov.retry_after(event.chat_id)
    notifier = _flood_notifier(event)
    try:
        warn = await notifier.send_message(
            event.chat_id,
            f"⏳ <b>လူများနေလို့ ခဏစောင့်ပါ</b> — Telegram limit ကြောင့် command တွေကို ခဏလျှော့ထားတာပါ။ <code>~{wait}s</code> လောက်နေမှ ထပ်ကြိုးစားပါ။",
            parse_mode='html'
        )
        schedule_game_cleanup(notifier, event.chat_id, warn, delay=10)
    except Exception:
        pass

@bot1.on(events.NewMessage(pattern=r'^[/.]'))
async def guard_bot_game_throttle(event):
    user_id = event.sender_id
    if not user_id or user_id == OWNER_ID or user_id in bot_ids: return
    m = _FORCE_SUB_CMD_RE.match(event.raw_text or "")
    if not m: return
    cmd_word = m.group(1).split('@')[0].lower()
    is_game = cmd_word in GUARD_GAME_COMMANDS
    gov = _FLOOD_GOV.get("bot1")                              # None when FLOOD_GOVERNOR=0
    if not is_game and (gov is None or cmd_word not in FLOOD_VIEW_COMMANDS): return
    on_cooldown, remaining = await is_on_cooldown(
        user_id, "guard_game_spam" if is_game else "guard_view_spam",
        GUARD_GAME_COOLDOWN_SECONDS if is_game else FLOOD_VIEW_COOLDOWN_SECONDS)
    if on_cooldown:
        if gov is not None:
            gov.stats["shed_cmds"] += 1
        if is_game:
            await _flood_user_notice(event, remaining, gov)
        raise events.StopPropagation
    if gov is not None and not event.is_private:
        if gov.is_hot(event.chat_id):
            await _flood_chat_notice(event, gov)
            raise events.StopPropagation
        gov.admit(event.chat_id)

# ---- JOIN REWARD — RESTORED (2026-09, per owner request). This used to grant …

@bot1.on(events.ChatAction(chats=FORCE_SUB_CHAT_ID))
async def force_sub_join_tracker(event):
    """Warms the membership cache on a live join and grants the one-time join reward (FORCE_SUB_REWARD_STAR + FORCE_SUB_REWARD_VLT). Handles batch joins via event.user_ids or [event.user_id]."""
    if not (event.user_joined or event.user_added):
        return
    target_ids = event.user_ids or [event.user_id]
    now = time.time()
    for user_id in target_ids:
        if not user_id or user_id in bot_ids:
            continue
        force_sub_membership_cache[user_id] = (True, now + FORCE_SUB_MEMBERSHIP_TTL)
        # ⭐ Join reward — "$ne: True" (rather than pre-reading the doc) makes the grant itself
        # a single atomic operation: two near-simultaneous join events for the same account
        # (a duplicate update, a weird Telegram retry) can never both match and pay out twice,
        # since only the FIRST one still finds force_sub_rewarded != True at the instant it runs.
        try:
            plain_name = await get_plain_name(event, user_id)
            await ensure_user_registered(user_id, plain_name)
            result = await users_catcher_col.update_one(
                {"user_id": user_id, "force_sub_rewarded": {"$ne": True}},
                {
                    "$inc": {"star_balance": FORCE_SUB_REWARD_STAR, "vlt_balance": FORCE_SUB_REWARD_VLT},
                    "$set": {"force_sub_rewarded": True},
                }
            )
            if result.modified_count:
                try:
                    await bot1.send_message(
                        user_id,
                        f"<b>Group ကို Join ပြီးပါပြီ — Reward ရောက်ပါပြီ!</b>\n"
                        f"<code>{format_star_plain(FORCE_SUB_REWARD_STAR)}</code> + "
                        f"<code>{format_vlt_plain(FORCE_SUB_REWARD_VLT)}</code>",
                        parse_mode='html'
                    )
                except Exception:
                    pass  # DM blocked/not started yet — reward still landed, just no notification
        except Exception as e:
            print(f"⚠️ force_sub join reward error for {user_id}: {e}")

