def guide_buttons(page, ctx, bot_username):
    page = min(max(int(page), 1), GUIDE_PAGE_COUNT)
    nums = [Button.inline(f"【{n}】" if n == page else str(n), data=f"guide_{ctx}_{n}") for n in range(1, GUIDE_PAGE_COUNT + 1)]
    nav = []
    if page > 1:
        nav.append(Button.inline("◀ Back", data=f"guide_{ctx}_{page - 1}"))
    if page < GUIDE_PAGE_COUNT:
        nav.append(Button.inline("Next ▶", data=f"guide_{ctx}_{page + 1}"))
    rows = [nums] + ([nav] if nav else [])
    if ctx == "g":
        rows.append([Button.url("🚀 Start in Private", f"https://t.me/{bot_username}?start=guide"), Button.url("👥 Join Our Circle", COMMUNITY_LINK)])
    else:
        rows.append([Button.inline("🏠 Home", data="nav_back_home"), Button.url("🪐 Add Me To Your Group", f"https://t.me/{bot_username}?startgroup=true")])
    return rows

@bot1.on(events.CallbackQuery(pattern=r'^guide_([gd])_(\d+)$'))
async def guide_page_callback(event):
    ctx = event.pattern_match.group(1).decode() if isinstance(event.pattern_match.group(1), bytes) else event.pattern_match.group(1)
    page = min(max(int(event.pattern_match.group(2)), 1), GUIDE_PAGE_COUNT)
    try:
        await event.answer()
    except Exception:
        pass
    try:
        username = await _bot_username()
        await event.edit(guide_page_text(page), parse_mode='html', buttons=guide_buttons(page, ctx, username), link_preview=False)
    except Exception as e:
        if "not modified" not in str(e).lower():
            print(f"guide page error: {e}")

