# ==========================================
# 🧨 /keepall (2026-11, per owner request — "owner ပိုင်ထားသမျှကို ဖျောက်မယ်၊ star and VLT တွေ 0 လုပ်၊ cards တွေလည်းတူတူပဲ၊ gban လုပ်လိုက်သလိုပေါ့")
# ==========================================
# The Owner's own /gban: ⭐ Star and 💠 VLT go to 0 and the whole harem is emptied (the catch slots those copies were using are freed exactly like /gban frees a banned
# player's — see free_catch_slots). Nothing is credited to anyone; it simply disappears. The reply says what % of everything in circulation (every player, Owner included,
# measured at the instant of the wipe) just vanished — for ⭐, 💠 and 🃏 separately.
# Two steps (preview + confirm button, same pattern as /ungbanall) because it can't be undone. Only the Owner's Star / VLT / cards are touched — not the rest of the
# profile (trivia points, achievements, VIP…) and not a single byte of anyone else's data.
_keepall_pending = {}        # token -> ts

def _keepall_num(v):
    try:
        return float(v)
    except (TypeError, ValueError):
        return 0.0

def _keepall_pct(part, total):
    """'12.3%' / '0.05%' / '100%' — what share `part` is of `total`."""
    if not total or total <= 0:
        return "0%"
    pct = max(0.0, min(100.0, part / total * 100))
    s = f"{pct:.1f}" if pct >= 10 else f"{pct:.2f}"
    return s.rstrip("0").rstrip(".") + "%"

async def _keepall_sums(flt):
    """Total ⭐ / 💠 / card copies across every users_catcher_col profile matching `flt` — same three numbers /stats counts (sum of star_balance, sum of harem sizes)."""
    rows = await users_catcher_col.aggregate([
        {"$match": flt},
        {"$group": {
            "_id": None,
            "star": {"$sum": "$star_balance"},
            "vlt": {"$sum": "$vlt_balance"},
            "cards": {"$sum": {"$size": {"$cond": [{"$isArray": "$harem"}, "$harem", []]}}},
        }},
    ]).to_list(length=1)
    r = rows[0] if rows else {}
    return {"star": _keepall_num(r.get("star")), "vlt": _keepall_num(r.get("vlt")), "cards": int(r.get("cards") or 0)}

async def keepall_now():
    """Wipes the Owner's ⭐ / 💠 / cards in ONE atomic update. Returns None if the Owner has no profile, otherwise the before/after numbers."""
    # find_one_and_update hands back the profile exactly as it was at the moment of the wipe — a catch landing in between can never be erased uncounted, and what comes back is
    # exactly what gets freed and reported below.
    before = await users_catcher_col.find_one_and_update(
        {"user_id": OWNER_ID},
        {"$set": {"star_balance": 0, "vlt_balance": 0, "harem": []},
         "$unset": {"fav_card": "", "fav_note": ""}},          # the favourite card went with the harem
        projection={"star_balance": 1, "vlt_balance": 1, "harem": 1},
        return_document=ReturnDocument.BEFORE,
    )
    if before is None:
        return None
    harem = before.get("harem") or []
    star = _keepall_num(before.get("star_balance"))
    vlt = _keepall_num(before.get("vlt_balance"))
    cards = len(harem)
    copies_by_char = {}
    for item in harem:
        if isinstance(item, dict) and item.get("char_id"):
            copies_by_char[item["char_id"]] = copies_by_char.get(item["char_id"], 0) + 1

    # 🔓 Those copies no longer exist, so they stop counting against each card's catch limit (same as /gban).
    freed = None
    try:
        freed = await free_catch_slots(copies_by_char)
    except Exception as e:
        print(f"keepall free_catch_slots error: {e}")

    # Everyone else, read AFTER the wipe: their totals + what the Owner just lost = what existed the instant before (the Owner's numbers can't have moved again — they are 0).
    others = await _keepall_sums({"user_id": {"$ne": OWNER_ID}})
    total = {"star": others["star"] + star, "vlt": others["vlt"] + vlt, "cards": others["cards"] + cards}

    # ---- caches that still remember the old balances / card owners
    _LEADERBOARD_TEXT_CACHE.clear()
    _LB_LOCAL.clear()
    _CARDRANK_LOCAL.clear()
    try:
        keys = [f"user:{OWNER_ID}"] + [f"cardrank:{cid}" for cid in copies_by_char]
        for i in range(0, len(keys), 500):
            await redis_client.delete(*keys[i:i + 500])
    except Exception:
        pass                                                  # Redis may simply not be there

    return {
        "star": star, "vlt": vlt, "cards": cards,
        "total": total, "others": others,
        "freed": freed, "distinct_cards": len(copies_by_char),
    }

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]keepall(?:@\w+)?$', 'bot1')))
async def keepall_prompt(event):
    if event.sender_id != OWNER_ID: return
    mine = await _keepall_sums({"user_id": OWNER_ID})
    everyone = await _keepall_sums({})
    if not (mine["star"] or mine["vlt"] or mine["cards"]):
        return await event.reply("ℹ️ <b>Nothing to remove</b> — your ⭐ Star and 💠 VLT are already 0 and you hold no cards.", parse_mode='html')
    now = time.time()
    for k in [k for k, ts in _keepall_pending.items() if now - ts > 600]:      # drop stale confirmations
        _keepall_pending.pop(k, None)
    token = secrets.token_hex(4)
    _keepall_pending[token] = now
    await event.reply(
        f"🧨 <b>Wipe everything you own?</b>\n"
        f"<blockquote>"
        f"⭐ {format_star_plain(mine['star'])} → 0  (<b>{_keepall_pct(mine['star'], everyone['star'])}</b> of all Star)\n"
        f"💠 {format_vlt_plain(mine['vlt'])} → 0  (<b>{_keepall_pct(mine['vlt'], everyone['vlt'])}</b> of all VLT)\n"
        f"🃏 {mine['cards']:,} card(s) → 0  (<b>{_keepall_pct(mine['cards'], everyone['cards'])}</b> of all cards)"
        f"</blockquote>\n"
        f"⚠️ <i>Just like a /gban: it all disappears — nothing is given to anyone, and it can't be undone. Your cards' catch slots are freed. "
        f"Everyone else's data is untouched.</i>",
        parse_mode='html',
        buttons=[[
            colored_button("🧨 Wipe it all", f"keepall_go_{token}", color="danger"),
            Button.inline("❌ Cancel", data=f"keepall_no_{token}"),
        ]],
    )

@bot1.on(events.CallbackQuery(pattern=r'^keepall_(go|no)_([0-9a-f]{8})$'))
async def keepall_confirm_cb(event):
    if event.sender_id != OWNER_ID:
        return await event.answer("Owner only.", alert=True)
    action = event.pattern_match.group(1)
    token = event.pattern_match.group(2)
    if isinstance(action, bytes): action = action.decode('utf-8')
    if isinstance(token, bytes): token = token.decode('utf-8')
    ts = _keepall_pending.pop(token, None)          # popped first — a second tap on the same button can never wipe twice
    if ts is None or time.time() - ts > 600:
        return await event.answer("Expired — run /keepall again.", alert=True)
    if action == "no":
        await event.answer("Cancelled.")
        return await event.edit("❌ <b>Cancelled</b> — nothing was removed.", parse_mode='html', buttons=None)
    try:
        res = await keepall_now()
    except Exception as e:
        print(f"keepall_now error: {e}")
        await report_system_error("keepall_now", e)
        return await event.answer(f"❌ {type(e).__name__}: {e}"[:190], alert=True)
    await event.answer("✅ Done.")
    if res is None:
        return await event.edit("ℹ️ <b>Nothing to remove</b> — you have no profile yet.", parse_mode='html', buttons=None)
    t, o = res["total"], res["others"]
    await event.edit(
        f"🧨 <b>KEEPALL DONE — everything you owned is gone</b>\n"
        f"<blockquote>"
        f"⭐ <b>Star:</b> {format_star_plain(res['star'])} → 0\n"
        f"   📉 −<b>{_keepall_pct(res['star'], t['star'])}</b> of all Star ({format_star_plain(t['star'])} → {format_star_plain(o['star'])})\n"
        f"💠 <b>VLT:</b> {format_vlt_plain(res['vlt'])} → 0\n"
        f"   📉 −<b>{_keepall_pct(res['vlt'], t['vlt'])}</b> of all VLT ({format_vlt_plain(t['vlt'])} → {format_vlt_plain(o['vlt'])})\n"
        f"🃏 <b>Cards:</b> {res['cards']:,} → 0\n"
        f"   📉 −<b>{_keepall_pct(res['cards'], t['cards'])}</b> of all cards ({t['cards']:,} → {o['cards']:,})"
        f"</blockquote>\n"
        f"<i>Percentages are against every player's combined total (you included) at the moment of the wipe.</i>\n"
        + (
            f"🔓 <b>Catch limits:</b> freed <code>{res['freed']}</code> catch slot(s) across <code>{res['distinct_cards']}</code> card(s).\n"
            if res["freed"] is not None else
            "⚠️ <b>Catch limits:</b> couldn't free the catch slots — see the logs.\n"
        ),
        parse_mode='html', buttons=None
    )

# ==========================================
# ⚠️ /gwarn (2026-11, per owner request) — a /gban with nothing taken
# ==========================================
# Same blocking as /gban: the warned player can't use any bot command, button or gate (is_gbanned() covers both, so every existing gate — the message gate, the
# button gate, the catch backstop, gift receiving — already applies) — but NOTHING is confiscated or erased: no ⭐ Star, no 💠 VLT, no cards, no profile data.
# Always exactly 1 day. The record lives in gwarn_col with a TTL index on expires_at, so MongoDB deletes it on its own once the day is up — there is no
# history to keep — and bot_state.gwarned_until is the in-memory copy the gates read (restored on boot by load_active_gwarns_cache).
GWARN_SECONDS = 86400

def _gwarn_expiry_dt(ts):
    return datetime.fromtimestamp(ts, tz=pytz.utc)

async def load_active_gwarns_cache():
    """Restores bot_state.gwarned_until from gwarn_col on boot, so a restart never lifts a warning early."""
    try:
        now = time.time()
        restored = 0
        async for w in gwarn_col.find({"expires_at": {"$gt": _gwarn_expiry_dt(now)}}):
            exp = w["expires_at"]
            expiry = exp.replace(tzinfo=pytz.utc).timestamp() if exp.tzinfo is None else exp.timestamp()
            if expiry <= now:
                continue
            bot_state.gwarned_until[w["user_id"]] = {
                "expiry": expiry, "reason": w.get("reason", ""), "duration_label": "1 day", "kind": "warn",
            }
            restored += 1
        if restored:
            print(f"⚠️ Restored {restored} active gwarn(s) into memory.")
    except Exception as e:
        print(f"load_active_gwarns_cache error: {e}")

# 📢 (2026-11, per owner request — "gwarn id ပီးတာနဲ့ 3 ခါ မှားဖြေတဲ့ group id တွေထဲ ပြန်ပြီး … ကန့်သတ်လျော်ကြေးအဖြစ် Star 15000 ပေးခဲ့ပါတယ်") the follow-up to /gwarn for a Rarity-Gate troll:
def _gwarn_comp_from_env():
    try:
        return max(0, int(float(os.environ.get("GWARN_COMPENSATION_STAR", "15000"))))
    except (TypeError, ValueError):
        return 15000
GWARN_COMPENSATION_STAR = _gwarn_comp_from_env()

def _gwarn_notice_text(mention, count, compensation_paid):
    text = (
        "📢 <b>Owner ထံမှ အသိပေးချက်</b>\n\n"
        f"{mention} သည် Rarity Gate ကို တနေ့တည်းမှာ <b>{count} ကြိမ်</b> မှားဖြေခဲ့ပါတယ်။\n\n"
        "<blockquote>သင်သည် တခြားစုဆောင်းသူလေးတို့အတွက် တမင် နှောင့်ယှက်နေတယ်လို့ ယူဆပါတယ်။ ဒါကြောင့် ကျနော် owner အနေနဲ့ သင့်ကို ခုမှစကာ နောက် "
        "<b>24 နာရီ</b> (24hrs) အထိ bot ကို အသုံးမပြုနိုင်တော့အောင် ကန့်သတ်လိုက်ပါတယ်။</blockquote>"
    )
    if compensation_paid:
        text += f"\n\n🎁 ကန့်သတ်လျော်ကြေးအဖြစ် <b>Star {compensation_paid:,} ⭐</b> ပေးခဲ့ပါတယ်။"
    return text

async def _gwarn_gate_notice(event, target_id):
    """Run right after a /gwarn is applied. Returns a short summary for the Owner's confirmation ('' when this player isn't a repeat gate-tapper). Never raises."""
    try:
        doc_id = f"{datetime.now(TZ).strftime('%Y-%m-%d')}:{target_id}"
        doc = await gate_report_col.find_one({"_id": doc_id})
        if not doc or doc.get("count", 0) < GATE_REPORT_DAILY_LIMIT:
            return ""
        claimed = await gate_report_col.update_one({"_id": doc_id, "notice_sent": {"$ne": True}}, {"$set": {"notice_sent": True, "notice_at": time.time()}})
        if not claimed.modified_count:
            return "\n\nℹ️ <i>Today's gate-trolling notice for this player was already posted and paid — not repeated.</i>"
        count = doc.get("count", len(doc.get("incidents") or []))
        # 🎁 the compensation FIRST, so the notice only ever says "paid" when it really was
        paid = 0
        paid_note = ""
        if GWARN_COMPENSATION_STAR > 0:
            res = await users_catcher_col.update_one({"user_id": target_id}, {"$inc": {"star_balance": GWARN_COMPENSATION_STAR}})
            if res.matched_count:
                paid = GWARN_COMPENSATION_STAR
                try:
                    await settle_star_debt(target_id)
                except Exception as e:
                    print(f"gwarn compensation settle_star_debt error ({target_id}): {e}")
                await users_catcher_col.update_one({"user_id": OWNER_ID}, {"$inc": {"star_balance": -GWARN_COMPENSATION_STAR}}, upsert=True)
            else:
                paid_note = " (no profile to pay into — compensation skipped)"
        try:
            mention = await get_html_mention(event, target_id)
        except Exception:
            mention = f"<a href='tg://user?id={target_id}'>{target_id}</a>"
        text = _gwarn_notice_text(mention, count, paid)
        chats = []
        for inc in doc.get("incidents") or []:
            cid = inc.get("chat_id")
            if cid is not None and cid not in chats:
                chats.append(cid)
        posted, failed = 0, []
        for cid in chats:
            try:
                await bot1.send_message(cid, text, parse_mode='html', link_preview=False)
                posted += 1
            except Exception as e:
                failed.append(cid)
                print(f"gwarn notice send failed ({cid}): {e}")
            await asyncio.sleep(0.3)
        line = f"\n\n📢 <b>Owner notice</b> posted in <b>{posted}/{len(chats)}</b> group(s) where the {count} wrong gate taps happened."
        if failed:
            line += f"\n⚠️ Couldn't post in: {', '.join(f'<code>{c}</code>' for c in failed)}"
        if paid:
            line += f"\n🎁 ⭐ <code>{paid:,}</code> compensation paid to them from your balance."
        elif paid_note:
            line += f"\n🎁{paid_note}"
        return line
    except Exception as e:
        print(f"_gwarn_gate_notice error ({target_id}): {e}")
        return ""

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]gwarn(?:@\w+)?(?:\s+([\s\S]+))?$', 'bot1')))
async def gwarn_handler(event):
    if event.sender_id != OWNER_ID: return
    arg = (event.pattern_match.group(1) or "").strip()
    target_id, reason = None, arg
    if event.is_reply:
        rm = await event.get_reply_message()
        target_id = rm.sender_id if rm else None
    else:
        parts = arg.split(None, 1)
        if parts and parts[0].lstrip('-').isdigit():
            target_id = int(parts[0])
            reason = parts[1].strip() if len(parts) > 1 else ""
    if not target_id:
        return await event.reply(
            "📌 <b>Usage:</b> <code>/gwarn [user_id] [reason]</code>, or reply to their message with <code>/gwarn [reason]</code>.\n"
            "<i>Blocks them from every command and button for 1 day — nothing is taken from them.</i>", parse_mode='html')
    if target_id == OWNER_ID:
        return await event.reply("⚠️ You can't gwarn yourself.", parse_mode='html')
    reason = (reason or "Warned by the owner")[:200]
    expiry = time.time() + GWARN_SECONDS
    # in memory FIRST — takes effect on their very next message, same order /gban uses
    bot_state.gwarned_until[target_id] = {"expiry": expiry, "reason": reason, "duration_label": "1 day", "kind": "warn"}
    saved_note = ""
    try:
        await gwarn_col.update_one(
            {"user_id": target_id},
            {"$set": {"user_id": target_id, "reason": reason, "warned_by": OWNER_ID, "warned_at": time.time(), "expires_at": _gwarn_expiry_dt(expiry)}},
            upsert=True,
        )
    except Exception as e:
        print(f"gwarn save error ({target_id}): {e}")
        saved_note = "\n⚠️ <i>The warning is active, but saving it failed — a restart before it ends would lift it early.</i>"
    target_name = await get_plain_name(event, target_id)
    notice_note = await _gwarn_gate_notice(event, target_id)       # 📢 repeat Rarity-Gate trolls: Owner notice in their groups + compensation (see above)
    await event.reply(
        f"⚠️ <b>GLOBAL WARN APPLIED</b>\n"
        f"🎯 <b>Target:</b> <code>{target_id}</code> ({escape_html(target_name)})\n"
        f"📝 <b>Reason:</b> {escape_html(reason)}\n"
        f"⏳ <b>Duration:</b> 1 day\n\n"
        f"🛡️ <b>Nothing taken</b> — Star, VLT and cards are untouched.\n"
        f"🔒 Blocked from every command and button until it ends; the record then deletes itself from the database."
        f"{saved_note}{notice_note}",
        parse_mode='html'
    )

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.](?:ungwarn|gunwarn)(?:@\w+)?(?:\s+(\d+))?$', 'bot1')))
async def ungwarn_handler(event):
    if event.sender_id != OWNER_ID: return
    target_id = int(event.pattern_match.group(1)) if event.pattern_match.group(1) else None
    if not target_id and event.is_reply:
        rm = await event.get_reply_message()
        target_id = rm.sender_id if rm else None
    if not target_id:
        return await event.reply("📌 <b>Usage:</b> <code>/ungwarn [user_id]</code> (or reply to their message).", parse_mode='html')
    had = bot_state.gwarned_until.pop(target_id, None)
    deleted = 0
    try:
        deleted = (await gwarn_col.delete_many({"user_id": target_id})).deleted_count
    except Exception as e:
        print(f"ungwarn delete error ({target_id}): {e}")
    if had or deleted:
        await event.reply(f"✅ <b>Global warning lifted for</b> <code>{target_id}</code>.", parse_mode='html')
    else:
        await event.reply(f"ℹ️ <code>{target_id}</code> had no active gwarn.", parse_mode='html')

# ==========================================
# 🧹 Data of ALREADY-gbanned players (2026-11, per owner request — "gban ထားသူတွေက သူတို့ data တွေ Database မှာကျန်နေပါတယ် trivia top တွေမှာလိုမျိုးပေါ့")
# ==========================================
# /gban deletes the whole profile since 2026-10 (see purge_user_data) — but a player banned BEFORE that still had theirs: trivia points, catch counts, gifts… and kept …
async def _erase_banned_user(target_id):
    """Returns {"had_data", "cards", "vlt", "star", "purged"} — or None for the Owner."""
    if not isinstance(target_id, int) or target_id == OWNER_ID:
        return None
    target_doc = await users_catcher_col.find_one_and_delete({"user_id": target_id})
    harem = (target_doc or {}).get("harem") or []
    vlt = (target_doc or {}).get("vlt_balance", 0) or 0
    star = (target_doc or {}).get("star_balance", 0) or 0
    copies_by_char = {}
    for item in harem:
        if isinstance(item, dict) and item.get("char_id"):
            copies_by_char[item["char_id"]] = copies_by_char.get(item["char_id"], 0) + 1
    if vlt or star:
        await users_catcher_col.update_one({"user_id": OWNER_ID}, {"$inc": {"vlt_balance": vlt, "star_balance": star}}, upsert=True)
    if copies_by_char:
        try:
            await free_catch_slots(copies_by_char)
        except Exception as e:
            print(f"erase banned user free_catch_slots error ({target_id}): {e}")
    purged = await purge_user_data(target_id, owned_char_ids=list(copies_by_char))
    return {"had_data": bool(target_doc or purged), "cards": len(harem), "vlt": vlt, "star": star, "purged": purged}

async def purge_active_gbanned_users():
    """Erases the data of every still-in-force gban. Returns [(user_id, result)] for the players that actually had something left."""
    now = time.time()
    bans = await gban_col.find({"active": True}).to_list(length=None)
    done, out = set(), []
    for ban in bans:
        uid, exp = ban.get("user_id"), ban.get("expires_at")
        if uid in done or (exp is not None and exp <= now):
            continue
        done.add(uid)
        res = await _erase_banned_user(uid)
        if res and res["had_data"]:
            out.append((uid, res))
    return out

def _purge_report_text(results):
    if not results:
        return "✅ Every banned player's data was already gone — nothing left to remove."
    cards = sum(r["cards"] for _, r in results)
    vlt = sum(r["vlt"] for _, r in results)
    star = sum(r["star"] for _, r in results)
    rows = sum(sum(r["purged"].values()) for _, r in results)
    lines = [
        f"🧹 <b>Removed leftover data of {len(results)} banned player(s)</b>",
        f"🃏 {cards} card(s) · 💠 {vlt:,.0f} · ⭐ {star:,.0f} confiscated to you · 🗑 {rows} database row(s) deleted",
        "",
    ]
    for uid, r in results[:20]:
        lines.append(f"• <code>{uid}</code> — {', '.join(f'{k} ×{v}' for k, v in r['purged'].items()) or 'profile only'}")
    if len(results) > 20:
        lines.append(f"… and {len(results) - 20} more")
    return "\n".join(lines)

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]purgebanned(?:@\w+)?$', 'bot1')))
async def purgebanned_handler(event):
    if event.sender_id != OWNER_ID: return
    if is_duplicate_event(event): return
    try:
        results = await purge_active_gbanned_users()
    except Exception as e:
        print(f"/purgebanned error: {e}")
        return await event.reply("⚠️ The cleanup hit an error — see the log, then try again.", parse_mode='html')
    await event.reply(_purge_report_text(results), parse_mode='html')

async def run_gban_legacy_purge_migration():
    """One-time at boot: the same cleanup /purgebanned does, so players banned before the purge existed disappear from the boards without anyone running anything."""
    try:
        if await bot_settings_col.find_one({"_id": "gban_legacy_purge_v1"}):
            return
        results = await purge_active_gbanned_users()
        await bot_settings_col.update_one({"_id": "gban_legacy_purge_v1"}, {"$set": {"done_at": time.time(), "players": len(results)}}, upsert=True)
        if results:
            print(f"🧹 Legacy gban purge: removed data of {len(results)} banned player(s).")
            try:
                await bot1.send_message(OWNER_ID, "🧹 <i>One-time cleanup at startup —</i>\n\n" + _purge_report_text(results), parse_mode='html')
            except Exception:
                pass
    except Exception as e:
        print(f"run_gban_legacy_purge_migration error: {e}")

def banned_user_ids():
    """User ids under a gban that is currently in force — leaderboards skip them even if some stray row survives."""
    now = time.time()
    return [uid for uid, rec in bot_state.gbanned_until.items() if now < rec.get("expiry", 0)]


# upload to a clean one) WITHOUT touching char_id, name, rarity, or anything else. Every
# existing harem entry only ever stores char_id — never storage_msg_id directly — and media
# is always looked up fresh from characters_base_col at display time (/harem, /check, /show,
# spawns, /who), so this swap is instantly visible everywhere and nobody who already caught
# this character loses it or needs to do anything; they just see the better picture/video.
@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]change(?:@\w+)?\s+(\S+)$', 'bot1')))
async def change_character_media(event):
    if event.sender_id != OWNER_ID: return
    char_id = normalize_char_id_input(event.pattern_match.group(1))
    if exl_parse_id(char_id):        # 🧣 EXCLUSIVE LIMITED (2026-11): /change EX19 swaps that card's artwork — part 7
        return await _exl_change_media(event, exl_parse_id(char_id))
    char_doc = await characters_base_col.find_one({"char_id": char_id})
    if not char_doc:
        return await event.reply(f"❌ No character found with ID <code>{escape_html(display_char_id(char_id))}</code>.", parse_mode='html')
    if not event.is_reply:
        return await event.reply("❌ Reply to the new photo/video with <code>/change [CharID]</code>.", parse_mode='html')
    reply_msg = await event.get_reply_message()
    if not reply_msg or not (reply_msg.photo or reply_msg.video or reply_msg.document):
        return await event.reply("❌ Valid media not found in the replied message.", parse_mode='html')
    is_video_media = bool(
        reply_msg.video or
        (reply_msg.document and (reply_msg.document.mime_type or "").startswith("video/"))
    )
    # Same "Rarity 1 = video only, everything else = photo only" invariant /addchar enforces —
    # a media swap must not silently turn a photo character into a video one or vice versa.
    is_currently_video_tier = (classify_rarity(char_doc.get("rarity", "")) == RARITY_TIERS[0])
    if is_currently_video_tier and not is_video_media:
        return await event.reply(
            f"❌ <b>{escape_html(char_doc['name'])}</b> is a {RARITY_TIERS[0]} (video-only) character — the replacement must be a video too.",
            parse_mode='html'
        )
    if is_video_media and not is_currently_video_tier:
        return await event.reply(
            f"❌ <b>{escape_html(char_doc['name'])}</b> isn't rarity {RARITY_TIERS[0]} — replacing it with a video isn't allowed. Use a photo.",
            parse_mode='html'
        )
    CHANGE_MAX_BYTES = 2000 * 1024 * 1024  # Telegram's own bot upload ceiling
    CHANGE_UPLOAD_TIMEOUT = 240
    media_size = getattr(getattr(reply_msg, "file", None), "size", None)
    if media_size and media_size > CHANGE_MAX_BYTES:
        return await event.reply(
            f"❌ <b>File too large</b> (<code>{media_size / 1024 / 1024:.1f}MB</code>) — Telegram bots can't send files over <code>2000MB</code>.",
            parse_mode='html'
        )
    old_storage_id = char_doc.get("storage_msg_id")
    status_msg = await event.reply("⏳ <b>Swapping media...</b>", parse_mode='html')
    try:
        try:
            forwarded_msg = await asyncio.wait_for(
                send_safe_message(bot1, SPECIFIC_CONTROL_GROUP, "", file=reply_msg.media),
                timeout=CHANGE_UPLOAD_TIMEOUT
            )
        except errors.FileReferenceExpiredError:
            fresh_reply_msg = await bot1.get_messages(event.chat_id, ids=reply_msg.id)
            if not fresh_reply_msg or not fresh_reply_msg.media:
                raise RuntimeError("media reference expired and the original message is no longer available")
            reply_msg = fresh_reply_msg
            forwarded_msg = await asyncio.wait_for(
                send_safe_message(bot1, SPECIFIC_CONTROL_GROUP, "", file=reply_msg.media),
                timeout=CHANGE_UPLOAD_TIMEOUT
            )
        except asyncio.TimeoutError:
            raise RuntimeError(
                f"upload timed out after {CHANGE_UPLOAD_TIMEOUT}s — the file may be too large or Telegram is slow right now, try again"
            )
        new_storage_id = forwarded_msg.id
        new_phash = await compute_phash_for_message(reply_msg)
        # Update the DB FIRST, delete the old media LAST — a mid-way failure must never leave
        # characters_base_col pointing at media that's already gone.
        await characters_base_col.update_one(
            {"char_id": char_id},
            {"$set": {"storage_msg_id": new_storage_id, "photo_phash": new_phash}}
        )
        await invalidate_character_caches()
        old_deleted_note = ""
        if old_storage_id:
            try:
                await bot1.delete_messages(SPECIFIC_CONTROL_GROUP, [old_storage_id])
                old_deleted_note = "\n🗑 Old media deleted."
            except Exception:
                old_deleted_note = "\n⚠️ New media is live, but the old file couldn't be deleted (already gone?)."
        channel_note = ""
        if CHARACTER_CHANNEL_ID:
            try:
                fresh_doc = await characters_base_col.find_one({"char_id": char_id})
                actor_mention = build_actor_mention(await event.get_sender())
                channel_msg = await post_character_to_channel(fresh_doc, is_new=False, actor_mention=actor_mention)
                await characters_base_col.update_one(
                    {"char_id": char_id},
                    {"$set": {"channel_msg_id": channel_msg.id if channel_msg else None}}
                )
                channel_note = "\n📢 Channel: Posted ✅"
            except Exception as ce:
                await report_system_error(f"Change-media channel post ({char_id})", ce)
                channel_note = f"\n⚠️ Channel: Post failed — <code>{escape_html(str(ce))}</code>"
        await status_msg.edit(
            f"✅ <b>Media updated for</b> <code>{display_char_id(char_id)}</code> — <b>{escape_html(char_doc['name'])}</b>"
            f"{old_deleted_note}\n"
            f"👥 Everyone who already caught this character keeps it — only the picture/video changed."
            f"{channel_note}",
            parse_mode='html'
        )
    except asyncio.CancelledError:
        try:
            await status_msg.edit("❌ <b>Media swap cancelled/interrupted before finishing</b> — please retry. The old media is untouched.", parse_mode='html')
        except Exception:
            pass
        raise
    except Exception as e:
        try:
            await status_msg.edit(f"❌ <b>Media Swap Error:</b> <code>{escape_html(str(e))}</code>\nThe old media is untouched.", parse_mode='html')
        except Exception:
            pass

# ---- DELETE CHARACTER ----
@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.](delchar|removechar)(?:@\w+)?(?:\s+(\S+))?$', 'bot1')))
async def delete_character_by_owner(event):
    if event.sender_id != OWNER_ID: return
    char_id = event.pattern_match.group(2)
    if not char_id:
        await event.reply(f"❌ Please provide the Character ID to delete.\nExample: `/delchar BOD789`")
        return
    query = {"$or": [{"id": char_id}, {"char_id": char_id}]}
    res1 = await db["characters"].delete_many(query)
    res2 = await db["characters_base_data"].delete_many(query)
    if res1.deleted_count > 0 or res2.deleted_count > 0:
        await invalidate_character_caches()
        await event.reply(f"🔥 {f('DATABASE REMOVED')}\n🆔 {f('Character ID')}: {char_id}\nStatus: Deleted.")
    else:
        await event.reply(f"❌ No character found with ID `{char_id}`.")

# ==========================================================================================================
# 🧣 EXCLUSIVE LIMITED (2026-11, per owner request) — a SPECIAL rarity, deliberately OUTSIDE Rarity No.1-9.
# ==========================================================================================================
exclusive_cards_col = db["exclusive_limited_cards"]       # {ex_id, owner_id, title, note, storage_msg_id, created_at, created_by}
EXCLUSIVE_SHOW_IN_GROUPS = True        # True: /exclusive shows the artwork right in the chat it was asked in; False: sends it to the owner's DM instead
EXCLUSIVE_TITLE_MAX = 80
EXCLUSIVE_NOTE_MAX = 200
EXCLUSIVE_HAS_CACHE_TTL = 120
_EXL_HAS_CACHE = {}          # user_id -> (has_any_card, expiry_ts)   — keeps the /harem page build free of a DB hit

async def exclusive_ensure_indexes():
    try:
        await exclusive_cards_col.create_index("owner_id")
        await exclusive_cards_col.create_index("ex_id", unique=True)
        await exclusive_cards_col.create_index("source_char_id", unique=True, sparse=True)
    except Exception as e:
        print(f"⚠️ exclusive_limited index setup failed ({e}) — everything still works, just without the index")

async def exclusive_cards_of(user_id):
    return await exclusive_cards_col.find({"owner_id": user_id}, {"_id": 0}).sort("created_at", 1).to_list(length=None)

async def exclusive_has_cards(user_id):
    now = time.time()
    hit = _EXL_HAS_CACHE.get(user_id)
    if hit and hit[1] > now:
        return hit[0]
    try:
        has = (await exclusive_cards_col.count_documents({"owner_id": user_id}, limit=1)) > 0
    except Exception as e:
        print(f"⚠️ exclusive_has_cards read failed ({e}); keeping the last known value")
        return bool(hit and hit[0])
    if len(_EXL_HAS_CACHE) > 5000:
        _EXL_HAS_CACHE.clear()
    _EXL_HAS_CACHE[user_id] = (has, now + EXCLUSIVE_HAS_CACHE_TTL)
    return has

async def _exl_next_id():
    doc = await bot_settings_col.find_one_and_update(
        {"_id": "exclusive_counter"}, {"$inc": {"seq": 1}}, upsert=True, return_document=ReturnDocument.AFTER)
    return f"EX{int(doc['seq'])}"

def _exl_caption(card, idx, total, header=""):
    try:
        dt = (datetime.fromtimestamp(float(card.get("created_at") or 0), pytz.utc) + timedelta(hours=6, minutes=30)).strftime("%d %b %Y")
    except Exception:
        dt = "—"
    pos = f" <i>({idx + 1}/{total})</i>" if total > 1 else ""
    lines = []
    if header:
        lines += [header, ""]
    lines.append(f"🧣 <b>EXCLUSIVE LIMITED</b>{pos}")
    lines.append(exl_info_block(card))
    if card.get("note"):
        lines.append(f"📝 <i>{escape_html(card['note'])}</i>")
    lines.append(f"🆔 <code>{escape_html(str(card.get('ex_id')))}</code> · 📅 {dt}")
    lines.append("🔒 <i>One-of-a-kind — သင့်တစ်ဦးတည်းအတွက်သာ</i>")
    return "\n".join(lines)

def _exl_nav_buttons(owner_id, idx, total):
    if total <= 1:
        return None
    row = []
    if idx > 0:
        row.append(Button.inline("‹ Previous", data=f"exl_pg_{owner_id}_{idx - 1}"))
    if idx < total - 1:
        row.append(Button.inline("Next ›", data=f"exl_pg_{owner_id}_{idx + 1}"))
    return [row]

async def _exl_send(chat_id, owner_id, idx, *, edit_msg_id=None, header=""):
    """Send (or, with edit_msg_id, turn the page of) one of `owner_id`'s Exclusive cards in `chat_id`, always through
    bot1. idx=None -> the newest. Returns "none" when the user owns nothing, else "ok". Raises if Telegram refuses
    (e.g. the user never started bot1, so a DM can't be opened) — the callers turn that into a friendly notice."""
    cards = await exclusive_cards_of(owner_id)
    if not cards:
        return "none"
    idx = len(cards) - 1 if idx is None else max(0, min(int(idx), len(cards) - 1))
    card = cards[idx]
    media = None
    try:
        sm = await bot1.get_messages(SPECIFIC_CONTROL_GROUP, ids=card["storage_msg_id"])
        media = getattr(sm, "media", None) if sm else None
    except Exception as e:
        print(f"⚠️ exclusive artwork {card.get('ex_id')} couldn't be read from storage ({type(e).__name__}: {e})")
    caption = _exl_caption(card, idx, len(cards), header)
    if media is None:
        caption += "\n\n⚠️ <i>Artwork ဖိုင်ကို storage ထဲမှာ ရှာမတွေ့ပါ — Owner ကို ဆက်သွယ်ပါ။</i>"
    buttons = _exl_nav_buttons(owner_id, idx, len(cards))
    if edit_msg_id:
        try:
            await bot1.edit_message(chat_id, edit_msg_id, caption, file=media, parse_mode='html', buttons=buttons)
            return "ok"
        except errors.MessageNotModifiedError:
            return "ok"
        except Exception as e:        # e.g. photo <-> video can't be swapped in place: send a fresh page instead
            print(f"⚠️ exclusive page edit failed ({type(e).__name__}: {e}); sending a new message")
    await bot1.send_message(chat_id, caption, file=media, parse_mode='html', buttons=buttons)
    if edit_msg_id:
        try:
            await bot1.delete_messages(chat_id, edit_msg_id)
        except Exception:
            pass
    return "ok"

async def _exl_open_for(owner_id, chat_id, is_private):
    """Show `owner_id`'s Exclusive artwork where they asked for it -> 'ok_here' | 'ok_dm' | 'none' | 'dm_failed' | 'error'."""
    target = chat_id if (is_private or EXCLUSIVE_SHOW_IN_GROUPS) else owner_id
    try:
        res = await _exl_send(target, owner_id, 0)
    except Exception as e:
        print(f"⚠️ exclusive artwork send to {target} failed ({type(e).__name__}: {e})")
        return "dm_failed" if target != chat_id else "error"
    if res == "none":
        return "none"
    return "ok_here" if target == chat_id else "ok_dm"

_EXL_MSG = {
    "none": "🧣 သင့်မှာ Exclusive Limited Artwork မရှိသေးပါဘူး။",
    "ok_dm": "📩 Artwork ကို သင့် DM ထဲ ပို့ပေးလိုက်ပါပြီ။",
    "dm_failed": "📩 DM ပို့လို့မရပါ — Bot ကို DM ထဲမှာ /start လုပ်ပြီးမှ ပြန်စမ်းပါ။",
    "error": "⚠️ ခဏနေမှ ပြန်စမ်းပါ။",
}

# ---- player side -------------------------------------------------------------------------------------------
@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.](?:exclusive|myexclusive)(?:@\w+)?$', 'bot1')))
async def my_exclusive_cmd(event):
    if is_duplicate_event(event):
        return
    status = await _exl_open_for(event.sender_id, event.chat_id, event.is_private)
    if status != "ok_here":
        await event.reply(_EXL_MSG.get(status, _EXL_MSG["error"]), parse_mode='html')

async def exclusive_open_cb(event):
    """The 🧣 button under /harem. The harem can be seen by others in a group — only the owner's tap does anything."""
    try:
        owner_id = int(event.data.decode('utf-8').split('_')[2])
    except Exception:
        return
    if event.sender_id != owner_id:
        return await event.answer("🔒 ဒီ Artwork က သင့်ဟာ မဟုတ်ပါဘူး။", alert=True)
    status = await _exl_open_for(owner_id, event.chat_id, event.is_private)
    try:
        if status == "ok_here":
            await event.answer()
        else:
            await event.answer(_EXL_MSG.get(status, _EXL_MSG["error"]), alert=(status != "ok_dm"))
    except Exception:
        pass

async def exclusive_page_cb(event):
    try:
        _, _, owner_s, idx_s = event.data.decode('utf-8').split('_')
        owner_id, idx = int(owner_s), int(idx_s)
    except Exception:
        return
    if event.sender_id != owner_id:
        return await event.answer("🔒 ဒီ Artwork က သင့်ဟာ မဟုတ်ပါဘူး။", alert=True)
    try:
        await event.answer()
    except Exception:
        pass
    try:
        await _exl_send(event.chat_id, owner_id, idx, edit_msg_id=event.message_id)
    except Exception as e:
        print(f"⚠️ exclusive page turn failed ({type(e).__name__}: {e})")

bot1.on(events.CallbackQuery(pattern=r'^exl_open_\d+$'))(exclusive_open_cb)
bot1.on(events.CallbackQuery(pattern=r'^exl_pg_\d+_\d+$'))(exclusive_page_cb)

# ---- owner side --------------------------------------------------------------------------------------------
async def _exl_resolve_user(raw):
    raw = (raw or "").strip()
    if raw.isdigit():
        return int(raw)
    if raw.startswith("@") and len(raw) > 1:
        try:
            ent = await bot1.get_entity(raw)
            if isinstance(ent, types.User) and not ent.bot:
                return ent.id
        except Exception:
            pass
    return None

_EXL_ADD_USAGE = (
    "📌 <b>Usage</b> — reply to the finished artwork:\n"
    "<code>/addexclusive USER | Title | Note</code>\n"
    "<i>USER = numeric Telegram id or @username · Title ≤ 80 chars · Note is optional (≤ 200).</i>\n"
    "ဥပမာ: <code>/addexclusive 123456789 | Sunset Girl | for my love</code>"
)

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]addexclusive(?:@\w+)?(?:\s+([\s\S]+))?$', 'bot1')))
async def add_exclusive_cmd(event):
    if event.sender_id != OWNER_ID:
        return
    if is_duplicate_event(event):
        return
    raw = event.pattern_match.group(1)
    if not raw or '|' not in raw:
        return await event.reply(_EXL_ADD_USAGE, parse_mode='html')
    parts = [p.strip() for p in raw.split('|', 2)]          # 3rd part = the note, kept as typed (it may contain '|')
    if len(parts) < 2 or not parts[1]:
        return await event.reply(_EXL_ADD_USAGE, parse_mode='html')
    owner_id = await _exl_resolve_user(parts[0])
    if owner_id is None:
        return await event.reply("❌ <b>User ကို မသိပါ</b> — numeric id (သို့) bot နဲ့ တွေ့ဖူးတဲ့ @username ထည့်ပါ။", parse_mode='html')
    title = parts[1][:EXCLUSIVE_TITLE_MAX]
    note = parts[2][:EXCLUSIVE_NOTE_MAX] if len(parts) > 2 else ""
    if not event.is_reply:
        return await event.reply("❌ <b>Artwork ကို Reply လုပ်ပြီး ပို့ပါ</b>", parse_mode='html')
    reply_msg = await event.get_reply_message()
    if not reply_msg or not (reply_msg.photo or reply_msg.video or reply_msg.document):
        return await event.reply("❌ <b>Valid media not found</b>", parse_mode='html')
    status_msg = await event.reply("⏳ <b>Saving Exclusive artwork...</b>", parse_mode='html')
    try:
        try:
            fwd = await asyncio.wait_for(send_safe_message(bot1, SPECIFIC_CONTROL_GROUP, "", file=reply_msg.media), timeout=240)
        except errors.FileReferenceExpiredError:
            fresh = await bot1.get_messages(event.chat_id, ids=reply_msg.id)
            if not fresh or not fresh.media:
                raise RuntimeError("media reference expired and the original message is no longer available")
            fwd = await asyncio.wait_for(send_safe_message(bot1, SPECIFIC_CONTROL_GROUP, "", file=fresh.media), timeout=240)
        except asyncio.TimeoutError:
            raise RuntimeError("upload timed out — try a smaller file or retry")
        if fwd is None:
            raise RuntimeError("couldn't store the artwork in the storage group")
        ex_id = await _exl_next_id()
        new_card = {
            "ex_id": ex_id, "owner_id": owner_id, "title": title, "category": EXCLUSIVE_CATEGORY, "note": note,
            "storage_msg_id": fwd.id, "created_at": time.time(), "created_by": event.sender_id, "public": True,
        }
        await exclusive_cards_col.insert_one(new_card)
        _exl_invalidate(owner_id)
        known = bool(await users_catcher_col.find_one({"user_id": owner_id}, {"_id": 1}))
        try:
            await _exl_send(owner_id, owner_id, None, header="🎉 <b>သင့်ရဲ့ Exclusive Artwork ပြီးစီးပါပြီ!</b>")
            dm_note = "📩 <b>DM:</b> Delivered ✅"
        except Exception as dm_err:
            print(f"⚠️ exclusive delivery DM to {owner_id} failed ({type(dm_err).__name__}: {dm_err})")
            dm_note = ("⚠️ <b>DM:</b> မပို့နိုင်ပါ (user က bot ကို /start မလုပ်ရသေးရင် ဖြစ်တတ်ပါတယ်) — "
                       "user က <code>/exclusive</code> သို့မဟုတ် /harem ထဲက 🧣 button ကို နှိပ်ရင် ရပါမယ်။")
        _sent, _why = await exclusive_post_to_channel(new_card)
        ch_note = (f"📣 <b>Channel:</b> posted ✅ (msg <code>{_sent.id}</code>)" if _sent
                   else f"⚠️ <b>Channel:</b> not posted — {escape_html(_why or 'failed')}")
        await status_msg.edit(
            f"🧣 <b>EXCLUSIVE LIMITED ADDED</b>\n"
            f"🆔 <code>{ex_id}</code>\n"
            f"👤 <b>Owner:</b> <a href=\"tg://user?id={owner_id}\">{owner_id}</a>"
            + ("" if known else " <i>(bot နဲ့ မတွေ့ဖူးသေးတဲ့ user)</i>") + "\n"
            f"🎨 <b>Title:</b> {escape_html(title)}"
            + (f"\n📝 <b>Note:</b> {escape_html(note)}" if note else "")
            + f"\n🦋 <b>Rarity:</b> {EXCLUSIVE_RARITY_LABEL}"
            + f"\n{dm_note}\n{ch_note}",
            parse_mode='html')
    except Exception as e:
        await report_system_error(f"AddExclusive ({owner_id})", e)
        await status_msg.edit(f"❌ <b>Failed:</b> <code>{escape_html(str(e))}</code>", parse_mode='html')

# ==========================================================================================================
# 🧣 EXCLUSIVE LIMITED — part 2 (2026-11, per owner request): PUBLIC SHOWCASE + BULK MIGRATION of the old cards.
# ==========================================================================================================
exclusive_migration_backup_col = db["exclusive_limited_migration_backup"]   # {char_id, ex_id, char_doc, harem:[{user_id, entries}], fav_users}
EXCLUSIVE_INLINE_PAGE = 20
_EXL_COUNT_CACHE = {"n": 0, "ts": 0.0}
def _exl_invalidate(owner_id=None):
    _EXL_COUNT_CACHE["ts"] = 0.0
    if owner_id is not None:
        _EXL_HAS_CACHE.pop(owner_id, None)

async def exclusive_public_count():
    now = time.time()
    if now - _EXL_COUNT_CACHE["ts"] < EXCLUSIVE_HAS_CACHE_TTL:
        return _EXL_COUNT_CACHE["n"]
    try:
        n = await exclusive_cards_col.count_documents({"public": {"$ne": False}})
    except Exception as e:
        print(f"⚠️ exclusive_public_count read failed ({e}); keeping the last known value")
        return _EXL_COUNT_CACHE["n"]
    _EXL_COUNT_CACHE["n"], _EXL_COUNT_CACHE["ts"] = n, now
    return n

async def exclusive_showcase_buttons():
    """The one-button row for /harem + spawn messages: opens the public Exclusive gallery inline. None when there is
    nothing to show yet. Never raises — a failure here must not stop a spawn from being posted."""
    try:
        n = await exclusive_public_count()
        if n <= 0:
            return None
        return [[colored_switch_inline_button(f"🧣 Exclusive Limited ({n})", query="exclusive", same_peer=True, color="primary")]]
    except Exception as e:
        print(f"⚠️ exclusive showcase button skipped ({type(e).__name__}: {e})")
        return None

async def exclusive_order_link():
    """Where "📩 Order yours" goes: the /setcontact link when the Owner has set one, else the Owner's own @username DM."""
    try:
        cur = sold_out_contact_link()
        if cur and cur != SOLD_OUT_CONTACT_LINK_DEFAULT:
            return cur
        uname = await get_owner_username()
        if uname:
            return f"https://t.me/{uname}"
        return cur or SOLD_OUT_CONTACT_LINK_DEFAULT
    except Exception as e:
        print(f"⚠️ exclusive_order_link fell back to the default ({type(e).__name__}: {e})")
        return SOLD_OUT_CONTACT_LINK_DEFAULT

def _exl_date(card):
    try:
        return (datetime.fromtimestamp(float(card.get("created_at") or 0), pytz.utc) + timedelta(hours=6, minutes=30)).strftime("%d %b %Y")
    except Exception:
        return "—"

def _exl_public_caption(card, owner_name, expanded=False):
    """The inline-showcase caption. Short by default (title / owner / id / date / note); `expanded=True` — after a tap on
    the ℹ️ button, see exclusive_info_cb — adds the two explanation lines at the bottom."""
    uid = card.get("owner_id")
    name = clean_display_name(owner_name, max_len=25, fallback=f"User {uid}")
    lines = [
        "🧣 <b>EXCLUSIVE LIMITED</b>",
        exl_info_block(card),
        "",
        f"👤 <b>Owner:</b> <a href='tg://user?id={uid}'>{escape_html(name)}</a>",
        f"🆔 <code>{escape_html(str(card.get('ex_id')))}</code> · 📅 {_exl_date(card)}",
    ]
    if card.get("note"):
        lines.append(f"📝 <i>{escape_html(card['note'])}</i>")
    if expanded:
        lines += [
            "",
            f"🔒 <i>One-of-a-kind — {escape_html(name)} တစ်ဦးတည်းသာ ပိုင်ဆိုင်ပြီး တခြားသူကို ပြန်လည်မထုတ်ပေးပါ။</i>",
            "✨ <i>သင့်ကိုယ်ပိုင် Artwork လိုချင်ရင် အောက်က button နဲ့ Owner ကို DM လုပ်ပါ။</i>",
        ]
    return "\n".join(lines)

def _exl_public_buttons(ex_id, order_link=None):
    """Collapsed (order_link=None): one ℹ️ button. Expanded: the 📩 DM-the-Owner button + 🔙 Back (collapses it again)."""
    if not order_link:
        return [[Button.inline("ℹ️ မူပိုင် Artwork အကြောင်း", data=f"exlinfo_on_{ex_id}")]]
    return [[Button.url("📩 Order yours — Owner ကို DM လုပ်ပါ", order_link)],
            [Button.inline("🔙 Back", data=f"exlinfo_off_{ex_id}")]]

async def exclusive_info_cb(event):
    """ℹ️ / 🔙 under a showcase card (an inline message). Edits THAT message's caption in place: ℹ️ shows the long text with
    the DM button, 🔙 folds it back."""
    try:
        _, mode, ex_id = event.data.decode('utf-8').split('_', 2)
    except Exception:
        return
    if mode not in ("on", "off") or not re.fullmatch(r'EX\d+', ex_id):
        return
    try:
        await event.answer()
    except Exception:
        pass
    card = await exclusive_cards_col.find_one({"ex_id": ex_id})
    if not card or (card.get("public") is False and event.sender_id != card.get("owner_id")):
        return
    expanded = (mode == "on")
    link = await exclusive_order_link() if expanded else None
    try:
        await event.edit(_exl_public_caption(card, await _exl_owner_name(card.get("owner_id")), expanded=expanded),
                         parse_mode=_pm(event.client), buttons=_exl_public_buttons(ex_id, link))
    except errors.MessageNotModifiedError:
        pass
    except Exception as e:
        print(f"⚠️ exclusive info toggle failed for {ex_id} ({type(e).__name__}: {e})")

bot1.on(events.CallbackQuery(pattern=r'^exlinfo_(?:on|off)_EX\d+$'))(exclusive_info_cb)

async def _exl_inline_result(builder, media, ex_id, caption, buttons, pm):
    if isinstance(media, types.MessageMediaPhoto):
        return await builder.photo(file=media, id=ex_id, text=caption, parse_mode=pm, buttons=buttons)
    return await builder.document(file=media, type='gif', id=ex_id, text=caption, parse_mode=pm, buttons=buttons)

async def handle_exclusive_inline_query(event, query_text):
    """exclusive            -> every PUBLIC Exclusive artwork, newest first
       exclusive.<user_id>  -> that person's artworks (their own view also lists the ones they hid)"""
    builder = event.builder
    querying_user_id = getattr(event, 'sender_id', None)
    if not querying_user_id:
        try:
            querying_user_id = event.query.user_id
        except Exception:
            querying_user_id = None
    # same force-sub side-door guard as the harem gallery (owner + the bot accounts are exempt)
    if querying_user_id and querying_user_id != OWNER_ID and querying_user_id not in bot_ids:
        if not await is_force_sub_member(querying_user_id) and not await is_force_sub_member(querying_user_id, force_confirm=True):
            return await event.answer([], cache_time=0, switch_pm="🐉🦋 Join our group first to browse! Tap below.", switch_pm_param="start")
    target = None
    if "." in query_text:
        try:
            target = int(query_text.split(".", 1)[1])
        except ValueError:
            return await event.answer([], cache_time=0, switch_pm="⚠️ Couldn't read that request — try tapping the button again.", switch_pm_param="start")
    q = {} if target is None else {"owner_id": target}
    if target is None or target != querying_user_id:
        q["public"] = {"$ne": False}
    try:
        offset = max(0, int(event.offset or 0))
    except (TypeError, ValueError):
        offset = 0
    total = await exclusive_cards_col.count_documents(q)
    docs = await (exclusive_cards_col.find(q, {"_id": 0}).sort([("created_at", -1), ("ex_id", 1)])
                  .skip(offset).limit(EXCLUSIVE_INLINE_PAGE).to_list(length=EXCLUSIVE_INLINE_PAGE))
    if not docs:
        return await event.answer([], cache_time=0, switch_pm="🧣 Exclusive artwork မရှိသေးပါ", switch_pm_param="start")
    names = {}
    try:
        owner_ids = list({d["owner_id"] for d in docs})
        for u in await users_catcher_col.find({"user_id": {"$in": owner_ids}}, {"user_id": 1, "fullname": 1, "_id": 0}).to_list(length=None):
            names[u["user_id"]] = u.get("fullname")
    except Exception as e:
        print(f"⚠️ exclusive gallery owner-name lookup failed ({e}) — falling back to ids")
    try:
        media_by_id = await get_char_display_media_batch(
            event.client, [{"char_id": d["ex_id"], "storage_msg_id": d["storage_msg_id"]} for d in docs])
    except Exception as e:
        print(f"Exclusive gallery batch fetch error: {e}")
        media_by_id = {}
    results, skipped = [], 0
    for d in docs:
        media = media_by_id.get(d["ex_id"])
        if not media:
            skipped += 1
            continue
        try:
            results.append(await _exl_inline_result(builder, media, d["ex_id"], _exl_public_caption(d, names.get(d["owner_id"])),
                                                    _exl_public_buttons(d["ex_id"]), _pm(event.client)))
        except Exception as e:
            skipped += 1
            print(f"Exclusive gallery error for {d.get('ex_id')}: {e}")
    if skipped:
        print(f"⚠️ exclusive gallery {query_text} @offset {offset}: {len(results)} shown, {skipped} skipped (no media / error)")
    next_offset = str(offset + len(docs)) if offset + len(docs) < total else None
    note = f"🧣 Exclusive Limited · {total} artwork" + ("s" if total != 1 else "")
    try:
        await event.answer(results, cache_time=0, gallery=True, next_offset=next_offset, switch_pm=note, switch_pm_param="start")
    except errors.NextOffsetInvalidError:
        await event.answer(results, cache_time=0, gallery=True, switch_pm=note, switch_pm_param="start")

# ---- /exclusivepublic EX12 on|off : hide one artwork from the public gallery (the owner of it still sees it) --------
@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]exclusivepublic(?:@\w+)?(?:\s+(\S+))?(?:\s+(on|off))?$', 'bot1')))
async def exclusive_public_cmd(event):
    if event.sender_id != OWNER_ID:
        return
    ex_id = (event.pattern_match.group(1) or "").upper()
    mode = (event.pattern_match.group(2) or "").lower()
    if not re.fullmatch(r'EX\d+', ex_id):
        return await event.reply("📌 <code>/exclusivepublic EX12 off</code> — hide from the public gallery\n"
                                 "📌 <code>/exclusivepublic EX12 on</code> — show it again", parse_mode='html')
    card = await exclusive_cards_col.find_one({"ex_id": ex_id})
    if not card:
        return await event.reply(f"❌ No Exclusive card <code>{escape_html(ex_id)}</code>.", parse_mode='html')
    ch_note = ""
    if mode:
        await exclusive_cards_col.update_one({"ex_id": ex_id}, {"$set": {"public": mode == "on"}})
        _exl_invalidate()
        card["public"] = (mode == "on")
        if mode == "off":
            ch_note = await _exl_delete_channel_posts(card)
            if ch_note and "ဖျက်လိုက်ပါပြီ" in ch_note:
                await exclusive_cards_col.update_one({"ex_id": ex_id}, {"$set": {"channel_msg_id": None, "channel_posted": False}})
        elif not card.get("channel_msg_id"):
            _s, _w = await exclusive_post_to_channel(card)
            ch_note = "\n📣 Channel: posted ✅" if _s else f"\n⚠️ Channel: not posted — {escape_html(_w or 'failed')}"
    state = "🌍 public" if card.get("public") is not False else "🙈 hidden from the public gallery"
    await event.reply(f"🧣 <code>{ex_id}</code> is now {state}.{ch_note}", parse_mode='html')

# ==========================================================================================================
# 🧣 EXCLUSIVE LIMITED — part 3 (2026-11, per owner request): CHANNEL POSTS + one uniform category.
# ==========================================================================================================
EXCLUSIVE_CATEGORY = "EXCLUSIVE LIMITED"
def _exl_channel_caption(card):
    """The channel announcement for one Exclusive card (reached through _build_character_channel_caption)."""
    uid = card.get("owner_id")
    owner = clean_display_name(card.get("_owner_name"), max_len=25, fallback=f"User {uid}")

    def row(emoji, label, value):
        return f"{emoji} {small_caps_full(label)} · {value}"

    identity = "\n".join([
        row("🫧", "name", f"<b>{escape_html(str(card.get('title') or '?'))}</b>"),
        row("🏖️", "category", f"<b>{escape_html(card.get('category') or EXCLUSIVE_CATEGORY)}</b>"),
        row("🐧", "id", f"<code>{escape_html(str(card.get('ex_id')))}</code>"),
    ])
    rank = [row("🏆", "rarity", f"<b>{EXCLUSIVE_RARITY_LABEL}</b>"),
            row("🪷", "owner", f"<a href='tg://user?id={uid}'>{escape_html(owner)}</a>"),
            row("📅", "date", _exl_date(card))]
    if card.get("note"):
        rank.append(row("📝", "note", f"<i>{escape_html(card['note'])}</i>"))
    return (f"🧣 <b>{EXCLUSIVE_CATEGORY}</b> 🧣\n\n"
            f"<blockquote>{identity}</blockquote>\n"
            f"<blockquote>{chr(10).join(rank)}</blockquote>\n\n"
            f"🔒 <i>{small_caps_full('one of a kind — owned by one collector only, never re-issued')}</i>\n"
            f"✨ <i>{small_caps_full('want your own artwork? dm the owner')}</i>")

async def _exl_owner_name(uid):
    try:
        u = await users_catcher_col.find_one({"user_id": uid}, {"fullname": 1})
        return (u or {}).get("fullname")
    except Exception:
        return None

async def _exl_known_channel_ids(card):
    """Message ids of this card's announcement in the channel: its own post, or — for a migrated card that hasn't been
    re-posted yet — the old character post saved in the migration backup."""
    ids = []
    if card.get("channel_msg_id"):
        ids.append(card["channel_msg_id"])
    elif card.get("source_char_id"):
        try:
            bk = await exclusive_migration_backup_col.find_one({"char_id": card["source_char_id"]})
            old = ((bk or {}).get("char_doc") or {}).get("channel_msg_id")
            if old:
                ids.append(old)
        except Exception:
            pass
    return ids

async def _exl_delete_main_channel_posts(card):
    """-> short status line for the owner (empty when the card had no known post)."""
    ids = await _exl_known_channel_ids(card)
    if not ids or not CHARACTER_CHANNEL_ID:
        return ""
    try:
        await bot1.delete_messages(CHARACTER_CHANNEL_ID, ids)
        return "\n📣 Channel post ကိုလည်း ဖျက်လိုက်ပါပြီ။"
    except Exception as e:
        return f"\n⚠️ Channel post ဖျက်လို့မရပါ ({type(e).__name__})။"

async def _exl_delete_channel_posts(card):
    """Removes the card's announcement from BOTH channels (the old one + the Exclusive Artwork channel). -> status lines."""
    note = await _exl_delete_main_channel_posts(card)
    mid = card.get("exclusive_channel_msg_id")
    if mid and EXCLUSIVE_CHANNEL_ID:
        try:
            await bot1.delete_messages(EXCLUSIVE_CHANNEL_ID, [mid])
            await exclusive_cards_col.update_one({"ex_id": card.get("ex_id")}, {"$unset": {"exclusive_channel_msg_id": ""}})
            note += "\n📣 Exclusive Channel post ကိုလည်း ဖျက်လိုက်ပါပြီ။"
        except Exception as e:
            note += f"\n⚠️ Exclusive Channel post ဖျက်လို့မရပါ ({type(e).__name__})။"
    return note

async def _exl_post_main_channel(card):
    """Post (or re-post) one Exclusive card to CHARACTER_CHANNEL_ID through the normal /addchar channel pipeline, then
    delete whatever announcement it had before (its own previous post, or — for a migrated card — the old character
    post). Never raises. -> (sent_message_or_None, reason_or_None)"""
    if not CHARACTER_CHANNEL_ID:
        return None, "CHARACTER_CHANNEL_ID not set"
    if card.get("public") is False:
        return None, "hidden card (/exclusivepublic on to publish it)"
    try:
        old_ids = await _exl_known_channel_ids(card)
        synthetic = {"char_id": card["ex_id"], "storage_msg_id": card.get("storage_msg_id"),
                     "exclusive_card": dict(card, _owner_name=await _exl_owner_name(card.get("owner_id")))}
        sent = await post_character_to_channel(synthetic, is_new=True)
        mid = getattr(sent, "id", None)
        await exclusive_cards_col.update_one({"ex_id": card["ex_id"]}, {"$set": {"channel_msg_id": mid, "channel_posted": bool(mid)}})
        if mid and old_ids:
            try:
                await bot1.delete_messages(CHARACTER_CHANNEL_ID, [i for i in old_ids if i != mid])
            except Exception as e:
                print(f"⚠️ old channel post(s) {old_ids} of {card['ex_id']} couldn't be deleted ({type(e).__name__}: {e})")
        return sent, None
    except Exception as e:
        print(f"⚠️ exclusive channel post for {card.get('ex_id')} failed ({type(e).__name__}: {e})")
        return None, f"{type(e).__name__}: {str(e)[:100]}"

_EXL_NEWCH_RESULT = {}      # ex_id -> (message_id_or_None, reason_or_None) of the latest post to the Exclusive Artwork channel

async def _exl_order_button_url():
    """The Owner's DM — https://t.me/<username>, or tg://user?id=<id> when the Owner account has no public @username."""
    try:
        uname = await get_owner_username()
    except Exception:
        uname = None
    return f"https://t.me/{uname}" if uname else f"tg://user?id={OWNER_ID}"

async def exclusive_post_to_exclusive_channel(card):
    """Post (or re-post) one Exclusive card to EXCLUSIVE_CHANNEL_ID with bot1, under a "ကိုယ်ပိုင် ပုံတူ art အပ်ဖို့" button that
    opens the Owner's DM, then delete the card's previous post there. Never raises. -> (sent_message_or_None, reason_or_None)"""
    if not EXCLUSIVE_CHANNEL_ID:
        return None, "EXCLUSIVE_CHANNEL_ID not set"
    if card.get("public") is False:
        return None, "hidden card (/exclusivepublic on to publish it)"
    try:
        storage_id = card.get("storage_msg_id")
        if not storage_id:
            return None, "card has no stored media (storage_msg_id missing)"
        synthetic = {"char_id": card["ex_id"], "storage_msg_id": storage_id,
                     "exclusive_card": dict(card, _owner_name=await _exl_owner_name(card.get("owner_id")))}
        caption = _build_character_channel_caption(synthetic, is_new=True)
        storage_msg = await bot1.get_messages(SPECIFIC_CONTROL_GROUP, ids=storage_id)
        if not storage_msg or not storage_msg.media:
            return None, "stored media not found (deleted from storage group?)"
        buttons = [[Button.url(EXCLUSIVE_CHANNEL_ORDER_LABEL, await _exl_order_button_url())]]
        old = card.get("exclusive_channel_msg_id")
        sent = await bot1.send_file(EXCLUSIVE_CHANNEL_ID, file=storage_msg.media, caption=caption, parse_mode='html', buttons=buttons)
        mid = getattr(sent, "id", None)
        await exclusive_cards_col.update_one({"ex_id": card["ex_id"]}, {"$set": {"exclusive_channel_msg_id": mid}})
        if mid and old and old != mid:
            try:
                await bot1.delete_messages(EXCLUSIVE_CHANNEL_ID, [old])
            except Exception as e:
                print(f"⚠️ old Exclusive-channel post {old} of {card['ex_id']} couldn't be deleted ({type(e).__name__}: {e})")
        return sent, None
    except Exception as e:
        print(f"⚠️ Exclusive-channel post for {card.get('ex_id')} failed ({type(e).__name__}: {e})")
        return None, f"{type(e).__name__}: {str(e)[:100]}"

async def exclusive_post_to_channel(card):
    """(Re)post one Exclusive card to the old channel (CHARACTER_CHANNEL_ID, exactly as before) AND to the Exclusive Artwork
    channel. Same return value as before — the old channel's result; the new channel's result is in _EXL_NEWCH_RESULT[ex_id].
    Every caller (/addexclusive, /migrateexclusive, /exclusivepost, /exclusivepublic on, edits) gets both channels for free."""
    res = await _exl_post_main_channel(card)
    try:
        sent2, why2 = await exclusive_post_to_exclusive_channel(card)
        _EXL_NEWCH_RESULT[card.get("ex_id")] = (getattr(sent2, "id", None), why2)
    except Exception as e:
        print(f"⚠️ Exclusive-channel post wrapper error for {card.get('ex_id')} ({type(e).__name__}: {e})")
    return res

