def exl_parse_id(raw):
    """'ex1' / 'EX001' / ' EX12 ' -> 'EX1' / 'EX1' / 'EX12'. Anything else (BOD ids, plain numbers, junk) -> None."""
    m = re.fullmatch(r'EX0*(\d+)', str(raw or "").strip().upper())
    if not m or int(m.group(1)) <= 0:
        return None
    return f"EX{int(m.group(1))}"

def _exl_forget_has_cache(*user_ids):
    """Owner list changed -> drop the cached 'has any Exclusive card' answer (it feeds the 🧣 Mine button in /harem)."""
    for uid in user_ids:
        _EXL_HAS_CACHE.pop(uid, None)

async def exl_fav_doc_for(user_id, fav_card_id, public_only=False):
    """The Exclusive card behind a player's `fav_card`, or None when `fav_card_id` isn't an EX id, the card is gone, or
    `user_id` no longer owns it (so a gifted-away favourite heals itself on the next /harem or /profile)."""
    ex_id = exl_parse_id(fav_card_id)
    if not ex_id:
        return None
    card = await exclusive_cards_col.find_one({"ex_id": ex_id, "owner_id": user_id}, {"_id": 0})
    if not card or (public_only and card.get("public") is False):
        return None
    return card

# ---- /check EX… --------------------------------------------------------------------------------------------
async def exl_build_check(card):
    """-> (character-like dict, info_text) — the SAME shape build_character_check_text returns for a normal card. The
    dict carries only what the /check senders need (char_id + storage_msg_id for the artwork) plus `_exclusive`, which
    tells check_character_id_handler to skip the 🛒 Buy button."""
    uid = card.get("owner_id")
    ex_id = str(card.get("ex_id"))
    owner = clean_display_name(await _exl_owner_name(uid), max_len=25, fallback=f"User {uid}")
    try:
        _vip_gem = " 💎" if is_vip_active(await users_catcher_col.find_one({"user_id": uid}, {"premium_until": 1, "_id": 0})) else ""
    except Exception:
        _vip_gem = ""
    lines = [
        "🧣 <b>EXCLUSIVE LIMITED</b>",
        "",
        exl_info_block(card),
        f"🆔 <b>ID:</b> <code>{escape_html(ex_id)}</code>",
        f"👤 <b>Owner:</b> <a href='tg://user?id={uid}'>{escape_html(owner)}</a>{_vip_gem}",
        f"📅 <b>Created:</b> {_exl_date(card)}",
    ]
    if card.get("note"):
        lines.append(f"📝 <i>{escape_html(card['note'])}</i>")
    lines += ["", "🔒 <i>One-of-a-kind — တစ်ချိန်မှာ ပိုင်ရှင်တစ်ဦးတည်းသာ ရှိပြီး ပြန်လည်မထုတ်ပေးပါ။</i>"]
    return {"char_id": ex_id, "storage_msg_id": card.get("storage_msg_id"), "_exclusive": True}, "\n".join(lines)

# ---- /fav EX… ----------------------------------------------------------------------------------------------
async def _exl_fav_prompt(event, user_id, ex_id, fav_note):
    """The /fav confirmation card for an Exclusive card. `fav_note` arrives already HTML-escaped and capped (see
    set_favorite_card). The ✅/❌ buttons reuse the normal fav_confirm_* / fav_cancel_* callbacks (the id is just EX1)."""

    async def _say(text, buttons=None):
        return await event.reply(text, parse_mode='html', buttons=buttons)

    card = await exclusive_cards_col.find_one({"ex_id": ex_id})
    if not card:
        return await _say("❌ <b>Card not found.</b>")
    if card.get("owner_id") != user_id:
        return await _say("❌ <b>You don't own this card.</b>")

    note_preview = f"\n\n💬 <b>Note: {fav_note}</b>" if fav_note else ""
    confirm_text = (
        f"<b>🫧 Favourite this card?</b>\n\n"
        f"🧣 <b>{EXCLUSIVE_CATEGORY}</b>\n\n"
        f"{exl_info_block(card)}\n"
        f"🆔 <code>{escape_html(ex_id)}</code>"
        f"{note_preview}"
    )
    if fav_note:
        pending_fav_notes[(user_id, ex_id)] = {"note": fav_note, "expiry": time.time() + 600}
    buttons = [[
        colored_button("✅ Yep, why not", f"fav_confirm_{user_id}_{ex_id}", color="success"),
        Button.inline("❌ Nope", data=f"fav_cancel_{user_id}_{ex_id}")
    ]]

    async def _send_fav_confirm(media):
        return await event.reply(confirm_text, file=media, buttons=buttons, parse_mode='html')

    sent = None
    if sent is None:
        sent = await send_with_char_media(ex_id, card.get("storage_msg_id"), _send_fav_confirm)
    if sent is None:
        await _say(confirm_text, buttons)

async def _exl_fav_confirm(event, user_id, ex_id):
    """The ✅ tap on that card (called from the fav branch of unified_callback_handler)."""
    card = await exclusive_cards_col.find_one({"ex_id": ex_id})
    if not card:
        return await event.answer("❌ Card not found.", alert=True)
    if card.get("owner_id") != user_id:
        return await event.answer("❌ You don't own this card anymore!", alert=True)
    # Pop (not peek): a note belongs to exactly the ONE /fav it was typed with; no note this time clears any stale one.
    note_entry = pending_fav_notes.pop((user_id, ex_id), None)
    fav_note = note_entry["note"] if (note_entry and time.time() <= note_entry["expiry"]) else ""
    update_ops = {"$set": {"fav_card": ex_id}}
    if fav_note:
        update_ops["$set"]["fav_note"] = fav_note
    else:
        update_ops["$unset"] = {"fav_note": ""}
    await users_catcher_col.update_one({"user_id": user_id}, update_ops, upsert=True)
    await event.answer("✅ Favourite updated!")
    note_line = f"\n\n💬 <b>Note: {fav_note}</b>" if fav_note else ""
    try:
        await event.edit(
            f"🍬 <code>{escape_html(card.get('title') or '—')}</code> <code>{escape_html(ex_id)}</code> is now your favourite.\n\n"
            f"It'll be shown as your <code>/harem</code> thumbnail."
            f"{note_line}",
            parse_mode=_pm(event.client), buttons=None
        )
    except Exception:
        pass

