async def _exl_gift_prompt(event, sender_id, receiver_id, ex_id, gift_note):
    """The /gift confirmation card for an Exclusive card (called from gift_asset_handler once the self-gift and
    gbanned-receiver checks have passed). Buttons are the normal gift_confirm_* / gift_cancel_* ones."""
    card = await exclusive_cards_col.find_one({"ex_id": ex_id})
    if not card:
        return await event.reply("❌ <b>Character data not found.</b>", parse_mode='html')
    if card.get("owner_id") != sender_id:
        _hint = (f"\n\nℹ️ <i>{EXCLUSIVE_CATEGORY} cards are one-of-a-kind — only the card's current owner can gift it.</i>"
                 if is_owner_mode(sender_id) else "")
        return await event.reply(f"❌ <b>You don’t have this card.</b>{_hint}", parse_mode='html')

    r_mention = await get_html_mention(event, receiver_id)
    note_preview = f"💭 Note: <i>{gift_note}</i>\n" if gift_note else ""
    confirm_text = (
        f"<b>🫧 Gift Confirmation</b>\n\n"
        f"🎁 <code>#{escape_html(ex_id)}</code> · 🧣 {EXCLUSIVE_CATEGORY}\n\n"
        f"{exl_info_block(card)}\n\n"
        f"💌 Sending to {r_mention}\n"
        f"{note_preview}\n"
        f"<blockquote>Send this card to {r_mention}?</blockquote>\n\n"
        f"⚠️ <i>One-of-a-kind — ပေးလိုက်ရင် ဒီ Artwork က {r_mention} ပိုင်သွားမှာဖြစ်ပြီး သင့်မှာ မကျန်တော့ပါဘူး။</i>\n\n"
        f"✨ Tap below to confirm! Sir."
    )
    if gift_note:
        pending_gift_notes[(sender_id, receiver_id, ex_id)] = {"note": gift_note, "expiry": time.time() + 600}
    buttons = [[
        colored_button("✅ Yep, Why Not✔", f"gift_confirm_{sender_id}_{receiver_id}_{ex_id}", color="success"),
        Button.inline("❌ Nope, Jk✗", data=f"gift_cancel_{sender_id}_{receiver_id}_{ex_id}")
    ]]

    async def _send_gift_confirm(media):
        return await event.reply(confirm_text, file=media, buttons=buttons, parse_mode='html')

    sent = await send_with_char_media(ex_id, card.get("storage_msg_id"), _send_gift_confirm)
    if sent is None:
        await event.reply(confirm_text, buttons=buttons, parse_mode='html')

async def _exl_gift_execute(event, sender_id, receiver_id, ex_id, gift_note):
    """The ✅ tap: move the card. Called from gift_callback_handler (tap owner, receiver-ban and single-tap checks already done)."""
    now = time.time()
    # ONE atomic move, conditional on the sender STILL being the owner — a double tap, or two /gift confirmations in
    # flight, can never duplicate the card or give it twice; the loser of the race just finds nothing to move.
    card = await exclusive_cards_col.find_one_and_update(
        {"ex_id": ex_id, "owner_id": sender_id},
        {"$set": {"owner_id": receiver_id, "gifted_at": now, "gifted_from": sender_id},
         "$push": {"owner_history": {"from": sender_id, "to": receiver_id, "at": now}}},
        return_document=ReturnDocument.AFTER
    )
    if not card:
        await event.edit(
            f"❌ <b>Oops!</b>\n\n"
            f"It seems you no longer have card <code>{escape_html(ex_id)}</code>.\n"
            f"☄️ Looks like luck played a little trick on you!",
            parse_mode='html', buttons=None
        )
        return await event.answer("Card not found.", alert=True)

    _exl_forget_has_cache(sender_id, receiver_id)
    # The giver's /fav pointed at this card? It's not theirs any more.
    await users_catcher_col.update_one({"user_id": sender_id, "fav_card": ex_id}, {"$unset": {"fav_card": "", "fav_note": ""}})
    # Gift stats: counts toward the giver's total (rank titles) but not toward a rarity tier — an Exclusive card has none.
    await users_catcher_col.update_one({"user_id": sender_id}, {"$inc": {"total_gifted": 1}}, upsert=True)
    r_mention = await get_html_mention(event, receiver_id)
    r_plain_name = await get_plain_name(event, receiver_id)
    await users_catcher_col.update_one(
        {"user_id": receiver_id},
        {"$inc": {"total_gift_received": 1}, "$set": {"fullname": r_plain_name}},
        upsert=True
    )
    # 🩹 REMOVED (2026-11, per owner request): no per-gift history rows are written to the database any more (it was never needed).

    # 🎖️ Gift Rank — identical to the normal gift confirmation
    sender_after = await users_catcher_col.find_one({"user_id": sender_id}, {"total_gifted": 1})
    sender_gift_count = (sender_after or {}).get("total_gifted", 0)
    giver_title = get_giver_title(sender_gift_count)
    giver_promoted = sender_gift_count in GIFT_TIER_THRESHOLDS
    if giver_title:
        giver_rank_line = f"{giver_title[0]} {giver_title[1]} · Gift #{sender_gift_count}\n"
    else:
        giver_rank_line = f"🎁 Gift #{sender_gift_count}\n"
    giver_promo_line = (
        f"\n\n🎉 <b>New rank unlocked!</b>\n{giver_title[0]} {giver_title[1]} · {sender_gift_count} gifts"
        if giver_promoted and giver_title else ""
    )
    s_mention = await get_html_mention(event, sender_id)
    await event.edit(
        f"<b>🎁 Gift sent!</b>\n\n"
        f"{s_mention} → {r_mention}\n\n"
        f"🧣 <code>#{escape_html(ex_id)}</code> · {EXCLUSIVE_CATEGORY}\n\n"
        f"{exl_info_block(card)}\n\n"
        f"{giver_rank_line}"
        f"{'💭 <i>' + gift_note + '</i>' + chr(10) if gift_note else ''}\n"
        f"Enjoy your card ♡"
        f"{giver_promo_line}",
        parse_mode='html', buttons=None
    )
    await event.answer("Gift sent successfully!", alert=True)


# ==========================================================================================================
# ✨ INLINE CARD PREMIUM EDIT (2026-11, per owner request) — part 6.
# ==========================================================================================================
INLINE_PREMIUM_EDIT_ENABLED = os.environ.get("INLINE_PREMIUM_EDIT", "1").strip().lower() not in ("0", "false", "off", "no")
INLINE_PREMIUM_TIERS = set(RARITY_TIERS[:3])           # ULTRA · LEGEND (shown as SUPREME) · MYTHIC (shown as CROSSVERSE)
INLINE_STASH_TTL = 1800                                # seconds a gallery caption is kept for its 💎 / auto-edit
INLINE_STASH_MAX = 3000
_INLINE_STASH = {}                                     # token -> (caption_html, expiry_ts)

def _inline_can_premium(client):
    """True when an edit made by `client` comes out with Premium emoji: only while the bot1 takeover is ON."""
    return bool(CASINO_PREMIUM_EMOJI_ENABLED and _PREMIUM_EMOJI_BOT1["on"])

def inline_premium_prepare(cid, caption, rarity, client=None):
    """Called while a gallery result is built -> (result_id, buttons). Ordinary cards: (cid, None), exactly as before."""
    if not (INLINE_PREMIUM_EDIT_ENABLED and rarity and classify_rarity(rarity) in INLINE_PREMIUM_TIERS):
        return cid, None
    if client is not None and not _inline_can_premium(client):
        return cid, None
    now = time.time()
    if len(_INLINE_STASH) > INLINE_STASH_MAX:
        for k in [k for k, (_c, exp) in _INLINE_STASH.items() if exp <= now]:
            _INLINE_STASH.pop(k, None)
        if len(_INLINE_STASH) > INLINE_STASH_MAX:          # still full (a burst of galleries): drop the oldest half
            for k in sorted(_INLINE_STASH, key=lambda k: _INLINE_STASH[k][1])[:INLINE_STASH_MAX // 2]:
                _INLINE_STASH.pop(k, None)
    token = os.urandom(4).hex()
    _INLINE_STASH[token] = (caption, now + INLINE_STASH_TTL)
    return f"{cid}~{token}", [[Button.inline("💎", data=f"inlprem_{token}")]]

async def _inline_premium_edit(client, msg_id, caption, buttons):
    """Edit the sent inline message. Right after a pick Telegram sometimes isn't ready for the edit yet, so it is retried
    twice; the last try uses plain 'html' so the message still ends up clean (💎 removed) if Premium is refused."""
    pm = _pm(client)
    for delay, mode in ((0, pm), (1.0, pm), (2.5, 'html')):
        if delay:
            await asyncio.sleep(delay)
        try:
            await client.edit_message(msg_id, caption, parse_mode=mode, buttons=buttons)
            return True
        except errors.MessageNotModifiedError:
            return True
        except errors.FloodError:
            return False
        except Exception as e:
            last = f"{type(e).__name__}: {e}"
    print(f"⚠️ inline premium edit failed ({last})")
    return False

def _make_inline_send_handler(client):
    async def _on_inline_send(update):
        """UpdateBotInlineSend: a player just sent one of our inline results into a chat."""
        try:
            if not INLINE_PREMIUM_EDIT_ENABLED or getattr(update, "msg_id", None) is None or not _inline_can_premium(client):
                return
            rid = str(getattr(update, "id", "") or "")
            ex_id = exl_parse_id(rid)
            if ex_id:                                                    # 🧣 Exclusive: result id == EX id
                card = await exclusive_cards_col.find_one({"ex_id": ex_id})
                if not card:
                    return
                caption = _exl_public_caption(card, await _exl_owner_name(card.get("owner_id")))
                buttons = _exl_public_buttons(ex_id)                      # keeps the ℹ️ button
            elif "~" in rid:                                             # ULTRA / SUPREME / CROSSVERSE: "<char>~<token>"
                hit = _INLINE_STASH.get(rid.rsplit("~", 1)[1])
                if not hit or hit[1] <= time.time():
                    return
                caption, buttons = hit[0], None                          # None = the 💎 button goes away
            else:
                return
            await _inline_premium_edit(client, update.msg_id, caption, buttons)
        except Exception as e:
            print(f"⚠️ inline send handler failed ({type(e).__name__}: {e})")
    return _on_inline_send

async def inline_premium_cb(event):
    """💎 under a gallery card: the manual version of the auto-edit (used when Inline Feedback isn't switched on)."""
    try:
        token = event.data.decode('utf-8').split('_', 1)[1]
    except Exception:
        return
    hit = _INLINE_STASH.get(token)
    if not hit or hit[1] <= time.time():
        return await event.answer("⌛ Expired — search the card again and re-send it.", alert=True)
    try:
        await event.answer()
    except Exception:
        pass
    try:
        await event.edit(hit[0], parse_mode=_pm(event.client), buttons=None)
    except errors.MessageNotModifiedError:
        pass
    except Exception as e:
        print(f"⚠️ 💎 inline edit failed ({type(e).__name__}: {e})")

try:
    bot1.on(events.Raw(types.UpdateBotInlineSend))(_make_inline_send_handler(bot1))
except Exception as _e:        # an unexpected Telethon build must never stop the bot from starting
    print(f"⚠️ inline premium auto-edit not registered ({type(_e).__name__}: {_e}) — the 💎 / ℹ️ buttons still work")
bot1.on(events.CallbackQuery(pattern=r'^inlprem_[0-9a-f]{8}$'))(inline_premium_cb)


# ==========================================================================================================
# 🧣 EXCLUSIVE LIMITED — part 7 (2026-11, per owner request): /change works on EX ids too.
# ==========================================================================================================
async def _exl_change_media(event, ex_id):
    card = await exclusive_cards_col.find_one({"ex_id": ex_id})
    if not card:
        return await event.reply(f"❌ No Exclusive card <code>{escape_html(ex_id)}</code>.", parse_mode='html')
    if not event.is_reply:
        return await event.reply(f"❌ Reply to the new photo/video with <code>/change {escape_html(ex_id)}</code>.", parse_mode='html')
    reply_msg = await event.get_reply_message()
    if not reply_msg or not (reply_msg.photo or reply_msg.video or reply_msg.document):
        return await event.reply("❌ Valid media not found in the replied message.", parse_mode='html')
    max_bytes = 2000 * 1024 * 1024                      # Telegram's own bot upload ceiling (same as /change for BOD ids)
    media_size = getattr(getattr(reply_msg, "file", None), "size", None)
    if media_size and media_size > max_bytes:
        return await event.reply(
            f"❌ <b>File too large</b> (<code>{media_size / 1024 / 1024:.1f}MB</code>) — Telegram bots can't send files over <code>2000MB</code>.",
            parse_mode='html')
    status_msg = await event.reply("⏳ <b>Swapping Exclusive artwork...</b>", parse_mode='html')
    try:
        try:
            fwd = await asyncio.wait_for(send_safe_message(bot1, SPECIFIC_CONTROL_GROUP, "", file=reply_msg.media), timeout=240)
        except errors.FileReferenceExpiredError:
            fresh = await bot1.get_messages(event.chat_id, ids=reply_msg.id)
            if not fresh or not fresh.media:
                raise RuntimeError("media reference expired and the original message is no longer available")
            fwd = await asyncio.wait_for(send_safe_message(bot1, SPECIFIC_CONTROL_GROUP, "", file=fresh.media), timeout=240)
        except asyncio.TimeoutError:
            raise RuntimeError("upload timed out — the file may be too large or Telegram is slow right now, try again")
        if fwd is None:
            raise RuntimeError("couldn't store the artwork in the storage group")
        now = time.time()
        old_storage_id = card.get("storage_msg_id")
        # The DB switches only AFTER the new file is safely stored — a failure above leaves the old artwork live.
        upd = await exclusive_cards_col.find_one_and_update(
            {"ex_id": ex_id},
            {"$set": {"storage_msg_id": fwd.id, "media_changed_at": now, "media_changed_by": event.sender_id},
             "$push": {"media_history": {"storage_msg_id": old_storage_id, "replaced_at": now, "by": event.sender_id}}},
            return_document=ReturnDocument.AFTER)
        if not upd:
            raise RuntimeError(f"{ex_id} was deleted while the file was uploading — the new file is in the storage group (msg {fwd.id})")
        _CHAR_PHOTO_CACHE.pop(ex_id, None)               # cached copy of the old picture
        if upd.get("channel_msg_id"):
            _sent, _why = await exclusive_post_to_channel(upd)
            ch_note = ("\n📣 <b>Channel:</b> re-posted ✅" if _sent
                       else f"\n⚠️ <b>Channel:</b> not refreshed — {escape_html(_why or 'failed')}")
        else:
            ch_note = "\n📣 <b>Channel:</b> this card isn't on the channel — left as it was"
        await status_msg.edit(
            f"✅ <b>Exclusive artwork updated</b> — <code>{escape_html(ex_id)}</code> · <b>{escape_html(upd.get('title') or '—')}</b>\n"
            f"👤 Owner <code>{upd.get('owner_id')}</code> keeps the card — only the picture/video changed."
            + (f"\n🗂 <i>Old file kept in the storage group (msg <code>{old_storage_id}</code>), not deleted.</i>" if old_storage_id else "")
            + ch_note,
            parse_mode='html')
    except asyncio.CancelledError:
        try:
            await status_msg.edit("❌ <b>Artwork swap cancelled/interrupted before finishing</b> — please retry. The old artwork is untouched.", parse_mode='html')
        except Exception:
            pass
        raise
    except Exception as e:
        try:
            await status_msg.edit(f"❌ <b>Artwork Swap Error:</b> <code>{escape_html(str(e))}</code>\nThe old artwork is untouched.", parse_mode='html')
        except Exception:
            pass


