@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]editevent(?:@\w+)?(?:\s+(\d+)(?:\s+([\s\S]+))?)?$', 'bot1')))
async def edit_event_handler(event):
    if event.sender_id != OWNER_ID: return
    if is_duplicate_event(event): return
    usage = "🎪 <b>/editevent</b> <code>9 🎃 New name</code>\n\n" + custom_event_list_html()
    no_s, text = event.pattern_match.group(1), event.pattern_match.group(2)
    if not no_s:
        return await event.reply(usage, parse_mode='html')
    no = int(no_s)
    if no not in _CUSTOM_EVENTS:
        return await event.reply(f"❌ <b>No event #{no}.</b>\n\n" + custom_event_list_html(), parse_mode='html')
    emoji, name = parse_event_text(text)
    if not name or len(name) > CUSTOM_EVENT_NAME_MAX or not any(ch.isalnum() for ch in name):
        return await event.reply(usage, parse_mode='html')
    for other_no, ev in _CUSTOM_EVENTS.items():
        if other_no != no and ev["name"].casefold() == name.casefold():
            return await event.reply(f"❌ <b>That name is already event #{other_no}.</b>", parse_mode='html')
    label = f"{emoji} {name}"
    await custom_events_col.update_one({"no": no}, {"$set": {"emoji": emoji, "name": name, "label": label}})
    _CUSTOM_EVENTS[no] = {"no": no, "emoji": emoji, "name": name, "label": label}
    res = await characters_base_col.update_many({"custom_event_no": no}, {"$set": {"custom_event": label}})
    if res.modified_count:
        await invalidate_character_caches()
    await event.reply(f"✅ <b>Event #{no}</b> is now {escape_html(label)} — <code>{res.modified_count}</code> card(s) updated.", parse_mode='html')

async def _announce_event_assignment(ev, docs, sender):
    """Shows an /evset in CHARACTER_CHANNEL_ID. Returns a note line for the owner's reply."""
    if not CHARACTER_CHANNEL_ID:
        return "\n⚠️ Channel: <code>CHARACTER_CHANNEL_ID</code> not set — skipped."
    try:
        actor = build_actor_mention(sender)
        if len(docs) <= CUSTOM_EVENT_CARD_POSTS_MAX:
            for d in docs:
                msg = await post_character_to_channel(d, is_new=False, actor_mention=actor, event_post=True)
                await characters_base_col.update_one({"char_id": d["char_id"]}, {"$set": {"channel_msg_id": msg.id if msg else None}})
        else:
            head = (f"🎪 <b>EVENT #{ev['no']}</b> — {escape_html(ev['label'])}\n"
                    f"➕ <b>{len(docs)}</b> card(s) added\n🤵 <b>Set by:</b> {actor}\n\n")
            lines = [f"• <code>{escape_html(display_char_id(d['char_id']))}</code> · "
                     f"{RARITY_EMOJI.get(classify_rarity(d.get('rarity', '')), RARITY_DEFAULT_EMOJI)} {escape_html(str(d.get('name', '?')))}"
                     for d in docs]
            chunks, cur = [], head
            for line in lines:
                if len(cur) + len(line) + 1 > 3800:
                    chunks.append(cur)
                    cur = f"🎪 <b>EVENT #{ev['no']}</b> — {escape_html(ev['label'])} <i>(continued)</i>\n\n"
                cur += line + "\n"
            chunks.append(cur)
            for c in chunks:
                await bot1.send_message(CHARACTER_CHANNEL_ID, c, parse_mode='html')
        return "\n📢 Channel: Posted ✅"
    except Exception as ce:
        await report_system_error(f"EvSet channel post (event #{ev['no']})", ce)
        return f"\n⚠️ Channel: Post failed — <code>{escape_html(str(ce))}</code>"

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]evset(?:@\w+)?(?:\s+([\s\S]+))?$', 'bot1')))
async def evset_handler(event):
    if event.sender_id != OWNER_ID: return
    if is_duplicate_event(event): return
    usage = (
        "🎪 <b>/evset</b>\n"
        "<code>/evset 9 | 1138, 1149-1152</code>\n"
        "<code>/evset 9</code> <i>(reply to a list of CharIDs, or to a card's photo/video)</i>\n"
        "<code>/evset none | 1138</code> <i>(take out of its event)</i>\n\n"
        f"{custom_event_list_html()}"
    )
    arg = (event.pattern_match.group(1) or "").strip()
    m = re.match(r'^(\d+|none|clear|-)\s*(?:\|\s*([\s\S]*))?$', arg, re.IGNORECASE)
    if not m:
        return await event.reply(usage, parse_mode='html')
    code, tail = m.group(1).lower(), m.group(2)
    ev = None
    if code in ("none", "clear", "-"):
        event_no = None
    else:
        event_no = int(code)
        ev = _CUSTOM_EVENTS.get(event_no)
        if ev is None:
            return await event.reply(f"❌ <b>No event #{event_no}.</b>\n\n{custom_event_list_html()}", parse_mode='html')
    # ---- which cards? an ID list typed after "|", else the replied-to message: media -> recognise the card, text -> IDs
    ids = {}
    source_text = tail if (tail and tail.strip()) else None
    rm = (await event.get_reply_message()) if (source_text is None and event.is_reply) else None
    if rm is not None and getattr(rm, "media", None):
        # Media first: recognise the card from the photo/video itself (same lookup /who uses). A card's channel post has
        # numbers in its caption (price, limit …), so its text must not be mistaken for a CharID list.
        char = await find_character_by_media(rm)
        if char:
            ids = {char["char_id"]: False}
        elif not (rm.text or "").strip():
            return await event.reply("❌ <b>I couldn't recognise that media</b> as any character in the roster.", parse_mode='html')
    if not ids:
        if source_text is None and rm is not None:
            source_text = rm.text or ""
        try:
            ids = _setcat_collect_ids(source_text or "")
        except ValueError as ve:
            return await event.reply(f"⚠️ {escape_html(str(ve))}", parse_mode='html')
    if not ids:
        return await event.reply("⚠️ I couldn't find any CharIDs (or a card's media).\n\n" + usage, parse_mode='html')
    id_list = list(ids)
    found = {}
    for i in range(0, len(id_list), 1000):
        for d in await characters_base_col.find({"char_id": {"$in": id_list[i:i + 1000]}}).to_list(length=None):
            found[d["char_id"]] = d
    ultra = [cid for cid, d in found.items() if classify_rarity(d.get("rarity", "")) == RARITY_TIERS[0]]
    ultra_set = set(ultra)
    eligible = [d for cid, d in found.items() if cid not in ultra_set]
    if event_no:
        update = {"$set": {"custom_event_no": event_no, "custom_event": ev["label"]}}
    else:
        update = {"$unset": {"custom_event_no": "", "custom_event": ""}}
    ops = [UpdateOne({"char_id": d["char_id"]}, update) for d in eligible]
    for i in range(0, len(ops), 500):
        await characters_base_col.bulk_write(ops[i:i + 500], ordered=False)
    if ops:
        await invalidate_character_caches()
    missing = [c for c, from_range in ids.items() if c not in found and not from_range]
    gaps = sum(1 for c, from_range in ids.items() if c not in found and from_range)
    head = f"✅ <b>Event #{event_no}</b> {escape_html(ev['label'])}" if event_no else "✅ <b>Event cleared</b>"
    lines = [f"{head} — <code>{len(ops)}</code> card(s)"]
    if ultra:
        shown = ", ".join(display_char_id(c) for c in ultra[:20])
        lines.append(f"⏭️ <b>ULTRA skipped ({len(ultra)}):</b> <code>{escape_html(shown)}</code>" + (" …" if len(ultra) > 20 else "") + "\n<i>ULTRA cards use /setevent (kinds 1-8).</i>")
    if missing:
        shown = ", ".join(display_char_id(c) for c in missing[:20])
        lines.append(f"❌ <b>Not found ({len(missing)}):</b> <code>{escape_html(shown)}</code>" + (" …" if len(missing) > 20 else ""))
    if gaps:
        lines.append(f"🕳️ <b>Empty slots inside ranges (skipped):</b> {gaps}")
    if event_no and eligible:
        updated = [{**d, "custom_event_no": event_no, "custom_event": ev["label"]} for d in eligible]
        lines.append((await _announce_event_assignment(ev, updated, await event.get_sender())).strip())
    await event.reply("\n".join(lines), parse_mode='html')

# ==========================================
# 🗂️ /setcat — BULK-SET CATEGORY ("Series") STRAIGHT FROM CHAT (per owner request — fixing categories used to …
# ==========================================
SETCAT_MAX_IDS = 5000          # one range / one job may not cover more IDs than this
_SETCAT_ID_RE = re.compile(r'^(?:bod)?\d+$', re.IGNORECASE)
_SETCAT_RANGE_RE = re.compile(r'^(?:bod)?(\d{1,7})[-–—](?:bod)?(\d{1,7})$', re.IGNORECASE)
def _setcat_token(tok):
    """Pure. One token -> [(char_id, from_range), ...], or None when it isn't an ID/range at all.
    '1234' / 'BOD1234' / '0071' -> BOD1234 / BOD1234 / BOD71;  '100-150' -> BOD100..BOD150 (from_range=True)."""
    tok = (tok or "").strip()
    m = _SETCAT_RANGE_RE.match(tok)
    if m:
        a, b = int(m.group(1)), int(m.group(2))
        if a > b:
            a, b = b, a
        if b - a + 1 > SETCAT_MAX_IDS:
            raise ValueError(f"The range {tok} covers more than {SETCAT_MAX_IDS} IDs — split it up.")
        return [(f"BOD{n}", True) for n in range(a, b + 1)]
    if _SETCAT_ID_RE.match(tok):
        digits = tok[3:] if tok[:3].upper() == "BOD" else tok
        return [(f"BOD{int(digits)}", False)]
    return None

def _setcat_merge(into, pairs):
    """An ID typed on its own beats the same ID merely falling inside a range (matters for 'not found' noise)."""
    for cid, from_range in pairs:
        into[cid] = into.get(cid, True) and from_range

def _setcat_collect_ids(text):
    """Pure. Every ID / range token in a block of text -> {char_id: from_range}; other words are ignored
    (same forgiving rule as /cr's reply-list)."""
    out = {}
    for tok in re.split(r'[\s,]+', text or ""):
        if tok:
            got = _setcat_token(tok)
            if got:
                _setcat_merge(out, got)
    return out

# ==========================================
# 🖼️ /show — full-quality rarity gallery browser, open to any user but DM-only.
# Walks EVERY character of a given rarity tier (/show no1 .. /show no9) one at a time with
# Prev/Next buttons. Media is sent by re-using the original stored file reference
# (storage_msg.media) instead of downloading+re-uploading, so quality never degrades — the
# exact same technique /check, /harem and spawns already rely on.
# ==========================================
# ❤️ (2026-11, per owner request) WISHLIST + sort modes for /show — "old cards always show first so nobody sees the new /addchar cards":
WISHLIST_MAX = 50
SHOW_DEFAULT_SORT = "a"
SHOW_SORT_LABELS = {"a": "📚 A-Z", "n": "🆕 New", "w": "🔥 Most", "m": "💝 Mine"}
WISHLIST_NOTIFY_TIERS = FIXED_CATCH_LIMIT_TIERS        # ULTRA + SUPREME (internal tier id LEGEND)
_WISH_LAST_NOTIFIED = {}                               # char_id -> the count a DM round already went out for (two near-simultaneous catches never send the same number twice)

def _char_num(c):
    d = re.sub(r"\D", "", str(c.get("char_id", "")))
    return int(d) if d else 0

async def get_user_wishlist(user_id):
    if not user_id:
        return []
    doc = await users_catcher_col.find_one({"user_id": user_id}, {"_id": 0, "wishlist": 1})
    return list((doc or {}).get("wishlist") or [])

async def _get_show_list(tier_num, mode=SHOW_DEFAULT_SORT, user_id=None):
    tier = RARITY_TIERS[int(tier_num) - 1]
    q = {"rarity_tier": tier}
    if mode == "m":
        wl = await get_user_wishlist(user_id)
        if not wl:
            return []
        q["char_id"] = {"$in": wl}
    elif mode == "w":
        q["wish_count"] = {"$gt": 0}
    chars = await characters_base_col.find(q).to_list(length=None)
    if mode == "n":
        chars.sort(key=lambda c: (c.get("created_at") or 0, _char_num(c)), reverse=True)     # old cards without created_at fall back to their id
    elif mode == "w":
        chars.sort(key=lambda c: (-(c.get("wish_count") or 0), (c.get("name") or "").lower()))
    else:
        chars.sort(key=lambda c: (c.get("name") or "").lower())
    return chars

async def _wish_fix_floor(char_id):
    await characters_base_col.update_one({"char_id": char_id, "wish_count": {"$lt": 0}}, {"$set": {"wish_count": 0}})

async def wishlist_toggle(user_id, char_id, full_name=""):
    """Love / un-love one card. -> (status, wish_count) with status "added" | "removed" | "full" | "missing". Each step is one atomic update, so a double-tap can't double-count."""
    char = await characters_base_col.find_one({"char_id": char_id}, {"_id": 0, "char_id": 1})
    if not char:
        return "missing", 0
    res = await users_catcher_col.update_one({"user_id": user_id, "wishlist": char_id}, {"$pull": {"wishlist": char_id}})
    if res.modified_count:
        doc = await characters_base_col.find_one_and_update({"char_id": char_id}, {"$inc": {"wish_count": -1}},
                                                           projection={"_id": 0, "wish_count": 1}, return_document=ReturnDocument.AFTER)
        await _wish_fix_floor(char_id)
        return "removed", max(0, (doc or {}).get("wish_count", 0))
    await ensure_user_registered(user_id, full_name or f"User {user_id}")
    res = await users_catcher_col.update_one(
        {"user_id": user_id, "wishlist": {"$ne": char_id}, f"wishlist.{WISHLIST_MAX - 1}": {"$exists": False}},
        {"$push": {"wishlist": char_id}})
    if not res.modified_count:
        return "full", 0
    doc = await characters_base_col.find_one_and_update({"char_id": char_id}, {"$inc": {"wish_count": 1}},
                                                       projection={"_id": 0, "wish_count": 1}, return_document=ReturnDocument.AFTER)
    return "added", (doc or {}).get("wish_count", 1)

async def wishlist_progress_notify(char_id, exclude=()):
    """ULTRA / SUPREME only: the card's catch count just went up -> DM everyone who wishlisted it (except `exclude`, i.e. whoever just got a copy).
    Fire as a task right after the spawn_count increment; reads the count fresh; never raises; paced so a big wishlist can't trip Telegram's flood limits."""
    try:
        ch = await characters_base_col.find_one({"char_id": char_id}, {"_id": 0, "char_id": 1, "name": 1, "rarity": 1, "rarity_tier": 1, "spawn_count": 1, "spawn_limit": 1})
        if not ch or ch.get("rarity_tier") not in WISHLIST_NOTIFY_TIERS:
            return
        limit, count = ch.get("spawn_limit") or 0, ch.get("spawn_count") or 0
        if limit <= 0 or count <= 0:
            return
        count = min(count, limit)
        if _WISH_LAST_NOTIFIED.get(char_id, -1) >= count:
            return
        _WISH_LAST_NOTIFIED[char_id] = count
        ids = [d["user_id"] for d in await users_catcher_col.find(
            {"wishlist": char_id, "user_id": {"$nin": [x for x in exclude if x]}}, {"_id": 0, "user_id": 1}).to_list(length=None)]
        if not ids:
            return
        tier = classify_rarity(ch.get("rarity", ""))
        card = (f"🫧 <b>{escape_html(ch.get('name') or '?')}</b> · <code>{display_char_id(char_id)}</code> · "
                f"{RARITY_EMOJI.get(tier, RARITY_DEFAULT_EMOJI)} {RARITY_DISPLAY_NAME.get(tier, tier)}")
        if count >= limit:
            text = (f"Hi Collector😊\n\n🔒 မင်းလိုချင် (wishlist) လုပ်ထားတဲ့ ကဒ်က <b>{count}/{limit}</b> ပြည့်သွားပါပြီ — wild spawn / shop ကနေ မရနိုင်တော့ပါဘူး။ "
                    f"Collector တွေဆီက <code>/trade</code> သို့ <code>/gift</code> နဲ့ပဲ ရနိုင်တော့မယ်။\n\n{card}")
        else:
            text = (f"Hi Collector😊\n\nမင်းလိုချင် (wishlist) လုပ်ထားတဲ့ ကဒ်က အခု <b>{count}/{limit}</b> ဖြစ်နေပြီ။\n{card}\n\n"
                    f"<b>{limit}</b> မပြည့်ခင် စုဆောင်းပါနော် 🏃")
        buttons = [[Button.inline("💔 Wishlist ကနေ ဖယ်မယ်", data=f"wishrm_{char_id}")]]
        for uid in ids:
            for attempt in (1, 2):
                try:
                    await bot1.send_message(uid, text, parse_mode='html', buttons=buttons)
                    break
                except FloodWaitError as e:
                    await asyncio.sleep(min(e.seconds, 30) + 1)
                except Exception:
                    break                       # blocked the bot / DMs closed — skip quietly
            await asyncio.sleep(0.06)
    except Exception as e:
        print(f"⚠️ wishlist progress DM skipped for {char_id} ({type(e).__name__}: {e})")

@bot1.on(events.CallbackQuery(pattern=r'^wishrm_([A-Za-z0-9]+)$'))
async def wishlist_remove_callback(event):
    """The 💔 button under a wishlist progress DM: take the card off the wishlist."""
    cid = event.pattern_match.group(1)
    if isinstance(cid, bytes): cid = cid.decode('utf-8')
    res = await users_catcher_col.update_one({"user_id": event.sender_id, "wishlist": cid}, {"$pull": {"wishlist": cid}})
    if res.modified_count:
        await characters_base_col.update_one({"char_id": cid}, {"$inc": {"wish_count": -1}})
        await _wish_fix_floor(cid)
        return await event.answer("💔 Wishlist ကနေ ဖယ်ပြီးပါပြီ", alert=True)
    await event.answer("ဒီကဒ်က Wishlist ထဲမှာ မရှိတော့ပါဘူး", alert=True)

# 🖼️ /show in GROUP chats (2026-11, per owner request) — 👑 VIP Mode users only, ONE use per SHOW_GROUP_COOLDOWN_SECONDS (4 h) per user.
SHOW_GROUP_COOLDOWN_SECONDS = 4 * 3600
_SHOW_GROUP_MSG_OWNER = {}      # (chat_id, message_id) -> (user_id, monotonic time). In memory: after a restart an old group gallery just asks to run /show again.
_SHOW_GROUP_NOTICE_AT = {}      # user_id -> monotonic time of the last "please wait" notice, so a VIP who keeps typing /show isn't answered every single time

def _show_vip_dm_note():
    return "👑 <b>VIP Mode</b> — Group chat တွေထဲမှာလည်း <code>/show</code> ကို သုံးလို့ရပါတယ် <i>(၄ နာရီ တစ်ကြိမ်)</i>"

def _show_grid_text(vip_note=False):
    return (
        f"🖼️ <b>ဝယ်ချင်တဲ့ ကဒ် Rarity ကိုရွေးပါ</b>\n"
        f"<i>ကြိုက်တဲ့ကဒ်တွေ့ရင် 💠 VLT နဲ့ တန်းဝယ်နိုင်ပါတယ် (No.1 ULTRA &amp; No.2 SUPREME မှလွဲ၍)။</i>"
        + (f"\n\n{_show_vip_dm_note()}" if vip_note else "")
    )

def _show_fmt_wait(seconds):
    h, m = divmod(max(60, int(seconds)) // 60, 60)
    return f"{h} နာရီ {m} မိနစ်" if h else f"{m} မိနစ်"

def _show_group_remember(chat_id, msg, user_id):
    """Remember who opened the /show gallery `msg` in a group (called again if the card is ever deleted + re-sent)."""
    mid = getattr(msg, "id", None)
    if mid is None:
        return
    now = time.monotonic()
    if len(_SHOW_GROUP_MSG_OWNER) > 500:
        for k in [k for k, (_u, t) in _SHOW_GROUP_MSG_OWNER.items() if now - t > 6 * 3600]:
            _SHOW_GROUP_MSG_OWNER.pop(k, None)
    _SHOW_GROUP_MSG_OWNER[(chat_id, mid)] = (user_id, now)

async def _show_group_gate(event):
    """Runs first in every /show command. -> (ok, claim).
    DM: always ok. Group: the Owner always; otherwise only a 👑 VIP Mode user who is off cooldown. The 4 h slot is claimed right here (an update or
    an insert that can only succeed once — two quick /show can't both pass). `claim` is what _show_group_release needs if nothing ends up being shown."""
    if event.is_private:
        return True, None
    uid = event.sender_id
    if uid == OWNER_ID:                      # 👑 Owner: no VIP needed, no cooldown, nothing stored
        return True, None
    if not uid or not await check_vip(uid):
        await event.reply("📩 <b>DM me</b> and use <code>/show</code> there — it only works in private chat.", parse_mode='html')
        return False, None
    now = time.time()
    new_exp = _gwarn_expiry_dt(now + SHOW_GROUP_COOLDOWN_SECONDS)
    # (1) a leftover record whose 4 h is already up (Mongo's TTL monitor sweeps about once a minute) -> just reuse it
    res = await show_group_cd_col.update_one({"_id": uid, "expire_at": {"$lte": _gwarn_expiry_dt(now)}}, {"$set": {"expire_at": new_exp}})
    claimed = bool(res.modified_count)
    if not claimed:
        try:                                 # (2) no record -> make one; DuplicateKeyError = a live record = still cooling down
            await show_group_cd_col.insert_one({"_id": uid, "expire_at": new_exp})
            claimed = True
        except DuplicateKeyError:
            pass
    if not claimed:
        exp = ((await show_group_cd_col.find_one({"_id": uid})) or {}).get("expire_at")
        left = (exp.replace(tzinfo=pytz.utc).timestamp() - now) if exp is not None else 60
        t = time.monotonic()
        if t - _SHOW_GROUP_NOTICE_AT.get(uid, -1e9) >= 60:
            _SHOW_GROUP_NOTICE_AT[uid] = t
            await event.reply(
                f"⏳ <b>Group ထဲမှာ /show ကို ၄ နာရီ တစ်ကြိမ်ပဲ သုံးလို့ရပါတယ်။</b>\n"
                f"နောက်တစ်ကြိမ်ကို <code>{_show_fmt_wait(left)}</code> အကြာမှာ သုံးနိုင်ပါမယ်။\n"
                f"📩 <i>DM မှာတော့ အကန့်အသတ်မရှိ သုံးလို့ရပါတယ်။</i>", parse_mode='html')
        return False, None
    return True, new_exp

async def _show_group_release(user_id, claim):
    """The group /show claimed the 4 h slot but nothing was shown (no cards / media missing / send failed) -> delete the record again, slot handed back."""
    if not claim:
        return
    try:
        await show_group_cd_col.delete_one({"_id": user_id})
    except Exception as e:
        print(f"⚠️ couldn't hand back the group /show slot of {user_id} ({type(e).__name__}: {e})")

async def _show_cb_guard(event):
    """First line of every /show button. DM: anyone (it's their own chat). Group: only the VIP who opened that gallery."""
    if event.is_private:
        return True
    owner = _SHOW_GROUP_MSG_OWNER.get((event.chat_id, event.message_id))
    if owner and owner[0] == event.sender_id:
        return True
    if owner:
        await event.answer("🖼️ ဒီ /show ကို ဖွင့်ထားတဲ့သူကပဲ နှိပ်လို့ရပါတယ် — DM မှာ /show သုံးပါ။", alert=True)
    else:
        await event.answer("⌛ ဒီ /show က ကုန်ဆုံးသွားပါပြီ — ပြန်ရိုက်ပါ။", alert=True)
    return False

def _show_rarity_grid_buttons():
    """3x3 grid of rarity buttons (No.1 ... No.9, with each tier's emoji) — shown for a bare
    /show, matching the 9-tier layout used everywhere else in the bot."""
    rows, row = [], []
    for num in sorted(RARITY_NUM_MAP.keys(), key=int):
        tier = RARITY_TIERS[int(num) - 1]
        emoji = RARITY_EMOJI.get(tier, RARITY_DEFAULT_EMOJI)
        row.append(Button.inline(f"{emoji} No.{num}", data=f"shownav_{num}_0"))
        if len(row) == 3:
            rows.append(row)
            row = []
    if row:
        rows.append(row)
    return rows

# 📌 (2026-11, per owner request) ULTRA (No.1) + SUPREME (No.2, internal tier id LEGEND) are the top-value cards: /show does NOT offer the …
SHOW_NO_VLT_TIERS = {"ULTRA", "LEGEND"}

def _show_vlt_note(tier):
    if tier not in SHOW_NO_VLT_TIERS:
        return ""
    return (
        f"\n<blockquote>📌 <b>Note</b>\n"
        f"💎 <b>ULTRA &amp; SUPREME</b> သည် အမြင့်ဆုံး တကယ့်တန်ဖိုးကြီး Card များဖြစ်သောကြောင့် bot တွင် 💠 VLT နဲ့ ဝယ်ယူခြင်း <b>unavailable</b> ဖြစ်ပါတယ်။\n"
        f"🤝 Collector အချင်းချင်း buying, selling and trading လုပ်တာကို လက်ခံပါတယ်။\n"
        f"👤 {owner_tag()} ဆီကနေလည်း လိုချင်တဲ့ Card ကို စျေးသက်သာစွာ ဝယ်ယူနိုင်ပါတယ်။</blockquote>"
    )

def _show_nav_buttons(tier_num, idx, total, char_doc=None, mode=SHOW_DEFAULT_SORT, loved=False):
    prev_idx = (idx - 1) % total
    next_idx = (idx + 1) % total
    rows = [[
        Button.inline("⬅️ Prev", data=f"shownav_{tier_num}_{prev_idx}_{mode}"),
        Button.inline("➡️ Next", data=f"shownav_{tier_num}_{next_idx}_{mode}")
    ]]
    if char_doc and char_doc.get("char_id"):
        wc = char_doc.get("wish_count") or 0
        rows.append([Button.inline(f"❤️ Loved · {wc}" if loved else f"🤍 Love · {wc}", data=f"showlove_{char_doc['char_id']}_{tier_num}_{idx}_{mode}")])
    rows.append([Button.inline(("• " if m == mode else "") + label, data=f"shownav_{tier_num}_0_{m}") for m, label in SHOW_SORT_LABELS.items()])
    if char_doc and char_doc.get("char_id"):
        tier = RARITY_TIERS[int(tier_num) - 1]
        limit = char_doc.get("spawn_limit", 0)
        char_locked = bool(limit and limit > 0 and char_doc.get("spawn_count", 0) >= limit)
        if tier in SHOW_NO_VLT_TIERS:
            rows.append([Button.url("👤 Owner ဆီက စျေးသက်သာစွာ ဝယ်မယ်", sold_out_contact_link())])
        elif tier in _cached_disabled_buy_tiers:
            # 🩹 CHANGED (per owner request): a dead "sold out" button used to just show an …
            rows.append([Button.url("🚫 အရောင်းကုန်ပါပြီ — ဝယ်ရန်ဆက်သွယ်ပါ", sold_out_contact_link())])
        elif char_locked:
            # 🎯 CATCH LIMIT reached for THIS specific character — Owner Shop no longer sells …
            rows.append([Button.url("🔒 Locked — ဆက်သွယ်ရန်", sold_out_contact_link())])
        else:
            lo, hi = _buy_bounds(char_doc)
            label = f"🛒 {lo}~{hi}💠 ညှိနှိုင်းဝယ်မယ်" if lo < hi else f"🛒 {hi}💠 ဖြင့်ဝယ်မယ်"
            rows.append([Button.inline(label, data=f"shopbuy_{char_doc['char_id']}")])
    rows.append([Button.inline("🔢 Rarity List", data="showgrid_back")])
    return rows

def _build_show_caption(char_doc, tier_num, idx, total, mode=SHOW_DEFAULT_SORT):
    rarity_display = char_doc.get("rarity") or RARITY_NUM_MAP.get(tier_num, {}).get("name", "Unknown")
    limit = char_doc.get("spawn_limit", 0)
    spawned = char_doc.get("spawn_count", 0)
    caught_text = "♾️ <b>Infinite</b>" if not limit else f"<code>{spawned}/{limit}</code>"
    lo, hi = _buy_bounds(char_doc)
    price = f"{lo} ~ {hi}" if lo < hi else f"{hi}"
    tier = RARITY_TIERS[int(tier_num) - 1]
    body = (
        f"✨ <b>Name:</b> <code>{escape_html(char_doc.get('name',''))}</code>\n"
        f"🆔 <b>ID:</b> <code>{display_char_id(char_doc.get('char_id',''))}</code>\n"
        f"{rarity_display}\n"
        f"🫧 <b>Category:</b> <code>{escape_html(char_doc.get('category','') or 'Unknown')}</code>\n"
        f"{artist_line(char_doc)}"
        f"🔁 <b>Caught:</b> {caught_text}"
    )
    if char_doc.get("wish_count"):
        body += f"\n❤️ <b>Wishlisted by:</b> <code>{char_doc['wish_count']}</code>"
    if tier not in SHOW_NO_VLT_TIERS:      # ULTRA / SUPREME have no VLT shop price — they get the note instead
        body += f"\n💠 <b>Shop Price:</b> <code>{price}💠</code>"
    return (
        f"🖼️ <b>Rarity Gallery</b> — <code>{idx + 1}/{total}</code> · {SHOW_SORT_LABELS.get(mode, '')}\n"
        f"<blockquote>{body}</blockquote>"
        + _show_vlt_note(tier)
    )

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]show(?:@\w+)?\s+(?:no)?([1-9])$', 'bot1')))
async def show_rarity_gallery_handler(event):
    ok, claim = await _show_group_gate(event)       # DM: always · group: 👑 VIP Mode only, once per 4 h
    if not ok:
        return
    tier_num = event.pattern_match.group(1)
    chars = await _get_show_list(tier_num)
    if not chars:
        await _show_group_release(event.sender_id, claim)
        r_info = RARITY_NUM_MAP.get(tier_num)
        label = r_info["name"] if r_info else f"Rarity No.{tier_num}"
        return await event.reply(f"📭 <b>No characters found for {label} yet.</b>", parse_mode='html')
    idx = 0
    char_doc = chars[idx]
    mode = SHOW_DEFAULT_SORT
    _wl = set(await get_user_wishlist(event.sender_id))
    caption = _build_show_caption(char_doc, tier_num, idx, len(chars), mode)
    if event.is_private and await check_vip(event.sender_id):      # 👑 VIP in DM: remind them that groups work too
        _note = "\n\n" + _show_vip_dm_note()
        if len(caption) + len(_note) < 950:                         # Telegram caps a caption at 1024 characters
            caption += _note
    buttons = _show_nav_buttons(tier_num, idx, len(chars), char_doc, mode, char_doc["char_id"] in _wl)

    async def _send_show(media):
        return await event.reply(caption, file=media, buttons=buttons, parse_mode='html')

    try:
        sent = await send_with_char_media(char_doc["char_id"], char_doc["storage_msg_id"], _send_show)
    except Exception:
        await _show_group_release(event.sender_id, claim)
        raise
    if sent is None:
        await _show_group_release(event.sender_id, claim)
        await event.reply(
            f"❌ <b>Media missing for</b> <code>{display_char_id(char_doc.get('char_id',''))}</code> "
            f"— its storage message may have been deleted.",
            parse_mode='html'
        )
    elif not event.is_private:
        _show_group_remember(event.chat_id, sent, event.sender_id)

