def _dec(x):
    return x.decode('utf-8') if isinstance(x, bytes) else x


def _cb_plain_name(sender, fallback_id=None):
    if sender is None:
        return f"Player {fallback_id}" if fallback_id else "Player"
    full = " ".join(p for p in (getattr(sender, "first_name", None), getattr(sender, "last_name", None)) if p).strip()
    return full or getattr(sender, "username", None) or f"Player {getattr(sender, 'id', fallback_id)}"


def _cb_mention(side_doc):
    return f'<a href="tg://user?id={side_doc.get("uid")}">{escape_html(side_doc.get("name") or "Player")}</a>'


def _cb_rarity_label(tier):
    return f"{RARITY_EMOJI.get(tier, '❓')} {RARITY_DISPLAY_NAME.get(tier, tier)}"


def _cb_card_line(stake):
    tier = classify_rarity((stake.get("item") or {}).get("rarity"))
    return f"{_cb_rarity_label(tier)} · <b>{escape_html(stake.get('name') or stake.get('char_id', '?'))}</b> <code>{display_char_id(stake.get('char_id', ''))}</code>"


def _cb_side_line(m, side):
    sd = m[side]
    icon = "🅰️" if side == "a" else "🅱️"
    if sd.get("uid") is None:
        if m.get("target_uid") and side == "b":
            return f"{icon} <a href=\"tg://user?id={m['target_uid']}\">{escape_html(m.get('target_name') or 'Challenged player')}</a> — <i>invited, waiting…</i>"
        return f"{icon} <i>waiting for an opponent…</i>"
    stake = sd.get("stake") or sd.get("preview")           # preview = the card named in /cardbet, not locked yet
    return f"{icon} {_cb_mention(sd)} — " + (_cb_card_line(stake) if stake else "<i>choosing a card…</i>")


def _cb_render(m):
    """(text, buttons) of the public match message for the match's current state."""
    st, mid = m["state"], m["_id"]
    head = f"🎴 <b>CARD BET</b> <code>#{mid}</code>\n"
    body = f"<blockquote>{_cb_side_line(m, 'a')}\n{_cb_side_line(m, 'b')}</blockquote>\n"
    mins = max(1, int((m.get("expires_at", 0) - time.time()) / 60) + 1)
    if st == "open":
        who = "" if not m.get("target_uid") else f" Only <a href=\"tg://user?id={m['target_uid']}\">{escape_html(m.get('target_name') or 'the invited player')}</a> can accept."
        return (head + body + f"⚔️ Winner takes <b>both</b> cards.{who}\n⏳ <i>Expires in ~{mins} min</i>",
                [[colored_button("⚔️ Accept", f"cbet_a_{mid}", color="success"), Button.inline("❌ Cancel", data=f"cbet_x_{mid}")]])
    if st == "challenge":
        return (head + body +
                "⚔️ Winner takes <b>both</b> cards.\n"
                f"👉 {_cb_mention(m['b'])} — tap <b>ကစားမည်</b> to play, or <b>တော်ပြီ</b> to decline.\n"
                f"⏳ <i>Expires in ~{mins} min</i>",
                [[colored_button("🎲 ကစားမည်", f"cbet_y_{mid}", color="success"),
                  Button.inline("❌ တော်ပြီ", data=f"cbet_x_{mid}")]])
    if st == "locking":
        return head + body + "🔍 <i>Re-checking both cards and locking them…</i>", None
    if st == "b_picking":
        return (head + body + "🎴 <i>The opponent is picking a card…</i>", [[Button.inline("❌ Cancel bet", data=f"cbet_x_{mid}")]])
    if st == "proposed":
        return (head + body + f"✅ Both cards are locked. {_cb_mention(m['a'])}, start the duel?\n⏳ <i>Auto-cancels in ~{mins} min</i>",
                [[colored_button("🎲 Start duel", f"cbet_g_{mid}", color="success"), Button.inline("❌ Cancel", data=f"cbet_x_{mid}")]])
    if st == "rolling":
        return head + body + "🎲 <b>Rolling…</b>", None
    if st in ("settling", "done"):
        return head + body + "🏁 <b>Duel finished</b> — result below ⬇️", None
    note = m.get("cancel_note")
    if st == "expired":
        return head + body + "⌛ <b>Expired</b> — " + (note or "any locked card was returned to its owner."), None
    if st == "cancelled":
        return head + body + "❌ <b>Cancelled</b> — " + (note or "any locked card was returned to its owner."), None
    return head + body, None


async def _cb_get(mid):
    return await cardbet_col.find_one({"_id": mid})


async def _cb_cas(mid, from_states, update, extra=None):
    """Compare-and-set: applies `update` only if the match is still in one of from_states. Returns the NEW doc or None."""
    q = {"_id": mid, "state": {"$in": list(from_states)}}
    if extra:
        q.update(extra)
    upd = dict(update)
    upd["$set"] = {**upd.get("$set", {}), "updated_at": time.time()}
    return await cardbet_col.find_one_and_update(q, upd, return_document=ReturnDocument.AFTER)


async def _cb_refresh(m, send_if_missing=False):
    if not m:
        return
    text, buttons = _cb_render(m)
    try:
        if m.get("msg_id"):
            await bot1.edit_message(m["chat_id"], m["msg_id"], text, parse_mode='html', buttons=buttons, link_preview=False)
        elif send_if_missing:
            sent = await bot1.send_message(m["chat_id"], text, parse_mode='html', buttons=buttons, link_preview=False)
            await cardbet_col.update_one({"_id": m["_id"]}, {"$set": {"msg_id": sent.id}})
    except errors.MessageNotModifiedError:
        pass
    except Exception as e:
        print(f"cardbet refresh {m.get('_id')}: {e}")


async def _cb_notify_owner(text):
    try:
        await bot1.send_message(OWNER_ID, text, parse_mode='html')
    except Exception as e:
        print(f"cardbet owner notify failed: {e}")


async def _cb_active_for(uid):
    return await cardbet_col.find_one({"state": {"$in": list(_CB_ACTIVE)}, "$or": [{"a.uid": uid}, {"b.uid": uid}]})


async def _cb_vault(uid):
    doc = await users_catcher_col.find_one({"user_id": uid}, {"harem": 1})
    return [it for it in ((doc or {}).get("harem") or []) if isinstance(it, dict) and it.get("char_id") and it.get("status") == "vault"]


async def _cb_can_join(uid):
    """None if uid may start/join a card bet, else a short reason (used as an alert)."""
    if is_owner_mode(uid):
        return "👑 Owners have an unlimited vault, so they can't bet real cards."
    if await _cb_active_for(uid):
        return "You're already in a card bet — finish it, or send /cardbet cancel."
    if not await _cb_vault(uid):
        return "You don't have any cards in your vault to bet."
    return None


# ---------------------------------------------------------------- escrow ----
async def _cb_lock_stake(mid, side, uid, char_id, state=None):
    """Takes ONE vault copy of char_id out of uid's harem into the match. Returns (ok, reason).
    Journaled: an `intent` (with how many copies existed) is written BEFORE the card moves, so a crash between the two
    writes is repaired by _cb_resolve_intents() instead of leaving a card nobody owns."""
    vault = [it for it in await _cb_vault(uid) if it.get("char_id") == char_id]
    if not vault:
        return False, "no_card"
    item = dict(vault[0])                                   # the same copy the positional $ below will pick (first match)
    char = await characters_base_col.find_one({"char_id": char_id}, {"name": 1})
    name = (char or {}).get("name") or char_id
    need_state = state or ("draft" if side == "a" else "b_picking")
    intent = {"char_id": char_id, "copies_before": len(vault), "item": item, "name": name, "ts": time.time(), "boot": _CARDBET_BOOT}
    r = await cardbet_col.update_one(
        {"_id": mid, "state": need_state, f"{side}.uid": uid, f"{side}.held": {"$ne": True}, f"{side}.intent": {"$exists": False}},
        {"$set": {f"{side}.intent": intent}})
    if r.matched_count == 0:
        return False, "state"
    taken = await users_catcher_col.update_one(
        {"user_id": uid, "harem": {"$elemMatch": {"char_id": char_id, "status": "vault"}}},
        {"$unset": {"harem.$": 1}})
    if taken.modified_count == 0:
        await cardbet_col.update_one({"_id": mid}, {"$unset": {f"{side}.intent": ""}})
        return False, "no_card"
    await users_catcher_col.update_one({"user_id": uid}, {"$pull": {"harem": None}})
    await cardbet_col.update_one(
        {"_id": mid},
        {"$set": {f"{side}.held": True, f"{side}.stake": {"char_id": char_id, "name": name, "item": item}}, "$unset": {f"{side}.intent": ""}})
    return True, ""


async def _cb_resolve_intents():
    """Finishes/undoes any lock that was cut off between 'take the card' and 'record it' (crash, restart)."""
    now = time.time()
    q = {"$or": [{"a.intent": {"$exists": True}}, {"b.intent": {"$exists": True}}]}
    async for m in cardbet_col.find(q):
        for side in ("a", "b"):
            it = (m.get(side) or {}).get("intent")
            if not it:
                continue
            if it.get("boot") == _CARDBET_BOOT and now - it.get("ts", 0) <= CARDBET_INTENT_STALE:
                continue                                    # still being worked on by this very process
            uid = m[side]["uid"]
            now_copies = sum(1 for x in await _cb_vault(uid) if x.get("char_id") == it["char_id"])
            if now_copies <= it["copies_before"] - 1:       # the card really left the harem -> record it as held
                await cardbet_col.update_one(
                    {"_id": m["_id"], f"{side}.intent": {"$exists": True}},
                    {"$set": {f"{side}.held": True, f"{side}.stake": {"char_id": it["char_id"], "name": it["name"], "item": it["item"]}},
                     "$unset": {f"{side}.intent": ""}})
                print(f"🎴 cardbet {m['_id']}: recovered an interrupted lock ({side}) for {uid}")
            else:                                           # the card never moved -> just drop the intent
                await cardbet_col.update_one({"_id": m["_id"]}, {"$unset": {f"{side}.intent": ""}})


async def _cb_give_card(uid, item, ref, fresh_date=False):
    """Idempotent: puts the card into uid's harem unless an item tagged `ref` is already there.
    Returns 'ok' | 'exists' | 'nouser'."""
    new = dict(item)
    new["status"] = "vault"
    new["cb_ref"] = ref
    if fresh_date:
        new["caught_date"] = time.time()
    r = await users_catcher_col.update_one({"user_id": uid, "harem": {"$not": {"$elemMatch": {"cb_ref": ref}}}}, {"$push": {"harem": new}})
    if r.matched_count:
        return "ok"
    there = await users_catcher_col.find_one({"user_id": uid, "harem": {"$elemMatch": {"cb_ref": ref}}}, {"user_id": 1})
    return "exists" if there else "nouser"


async def _cb_close_stakes(mid):
    """Hands every still-escrowed card to whoever it belongs to now: back to its owner (cancelled/expired) or to the winner
    (settling/done). Safe to run any number of times, from any process, at any moment."""
    m = await _cb_get(mid)
    if not m or m["state"] not in ("cancelled", "expired", "settling", "done"):
        return m
    for side in ("a", "b"):
        sd = m[side]
        if not sd.get("held") or sd.get("closed"):
            continue
        if m["state"] in ("cancelled", "expired"):
            recipient, fresh = sd["uid"], False
        else:
            recipient, fresh = m[m["winner"]]["uid"], True
        ref = f"{mid}:{side}"
        res = await _cb_give_card(recipient, sd["stake"]["item"], ref, fresh)
        if res == "nouser":                                 # recipient's account no longer exists (e.g. /gban purge) — don't silently vanish a card
            await cardbet_col.update_one({"_id": mid}, {"$set": {f"{side}.closed": True, f"{side}.orphaned": True}})
            await _cb_notify_owner(f"⚠️ <b>Card bet #{mid}</b>: couldn't return <code>{display_char_id(sd['stake']['char_id'])}</code> — "
                                   f"user <code>{recipient}</code> has no account any more. The card is kept in the match record (cardbet_matches).")
            continue
        await cardbet_col.update_one({"_id": mid}, {"$set": {f"{side}.closed": True}})
        try:
            await users_catcher_col.update_one({"user_id": recipient}, {"$unset": {"harem.$[e].cb_ref": ""}}, array_filters=[{"e.cb_ref": ref}])
        except Exception:
            pass                                            # tidy-up only
    return await _cb_get(mid)


async def _cb_cancel(mid, from_states, reason_state="cancelled", extra=None, note=None):
    sets = {"state": reason_state, "finished_at": time.time()}
    if note:
        sets["cancel_note"] = note                          # HTML shown on the closed match message
    c = await _cb_cas(mid, from_states, {"$set": sets}, extra)
    if not c:
        return None
    c = await _cb_close_stakes(mid) or c
    await _cb_refresh(c)
    return c


# ----------------------------------------------------------------- duel ----
async def _cb_start_duel(mid, from_state="proposed"):
    m = await _cb_cas(mid, (from_state,), {"$set": {"state": "rolling", "rolling_at": time.time(), "rolling_by": _CARDBET_BOOT}})
    if not m:
        return False
    await _cb_refresh(m)
    await _cb_roll_and_settle(m)
    return True


async def _cb_roll_and_settle(m):
    """rolling -> settling. The two stakes stay in escrow the whole time, so if this is interrupted a later pass just rolls again."""
    mid, chat_id, reply_to = m["_id"], m["chat_id"], m.get("msg_id")
    rolls, animated = [], True
    a_val = b_val = 0
    for attempt in range(8):
        try:
            die_a = await bot1.send_file(chat_id, types.InputMediaDice(emoticon="🎲"), reply_to=reply_to)
            die_b = await bot1.send_file(chat_id, types.InputMediaDice(emoticon="🎲"), reply_to=reply_to)
            a_val, b_val = int(die_a.media.value), int(die_b.media.value)
        except Exception as e:
            print(f"cardbet {mid}: dice send failed ({e}) — using a server-side roll")
            a_val, b_val, animated = secrets.randbelow(6) + 1, secrets.randbelow(6) + 1, False
        rolls.append([a_val, b_val])
        if a_val != b_val:
            break
        try:
            await bot1.send_message(chat_id, f"🤝 <b>Tie ({a_val}–{b_val})</b> — rolling again…", parse_mode='html', reply_to=reply_to)
        except Exception:
            pass
        await asyncio.sleep(3.5)
    winner = "a" if a_val > b_val else ("b" if b_val > a_val else secrets.choice(("a", "b")))
    if animated:
        await asyncio.sleep(3.5)                            # purely cosmetic: let Telegram's dice animation finish
    done = await _cb_cas(mid, ("rolling",), {"$set": {"state": "settling", "winner": winner, "rolls": rolls,
                                                      "settling_at": time.time(), "settling_by": _CARDBET_BOOT}})
    if done:
        await _cb_finish_settle(mid)


async def _cb_finish_settle(mid):
    m = await _cb_close_stakes(mid)
    if not m or m["state"] != "settling":
        return
    if any(m[s].get("held") and not m[s].get("closed") for s in ("a", "b")):
        return                                              # a transfer failed this time — the next janitor pass retries it
    done = await _cb_cas(mid, ("settling",), {"$set": {"state": "done", "finished_at": time.time()}})
    if not done:
        return
    w = done["winner"]
    l = "b" if w == "a" else "a"
    await users_catcher_col.update_one({"user_id": done[w]["uid"]}, {"$inc": {"cardbet_wins": 1}})
    await users_catcher_col.update_one({"user_id": done[l]["uid"]}, {"$inc": {"cardbet_losses": 1}})
    try:
        loser_doc = await users_catcher_col.find_one({"user_id": done[l]["uid"]}, {"harem": 1})
        await clear_stale_favorite(done[l]["uid"], done[l]["stake"]["char_id"], (loser_doc or {}).get("harem", []))
    except Exception as e:
        print(f"cardbet clear_stale_favorite: {e}")
    await _cb_announce_result(done)


async def _cb_announce_result(m):
    w = m["winner"]
    last = (m.get("rolls") or [[0, 0]])[-1]
    ties = len(m.get("rolls") or []) - 1
    wd = await users_catcher_col.find_one({"user_id": m[w]["uid"]}, {"cardbet_wins": 1, "cardbet_losses": 1}) or {}
    text = (
        f"🎴 <b>CARD BET</b> <code>#{m['_id']}</code> — <b>RESULT</b>\n"
        f"<blockquote>🅰️ {_cb_mention(m['a'])} 🎲 <b>{last[0]}</b>\n🅱️ {_cb_mention(m['b'])} 🎲 <b>{last[1]}</b>"
        + (f"\n🤝 {ties} tie(s) re-rolled" if ties > 0 else "") + "</blockquote>\n"
        f"🏆 <b>{_cb_mention(m[w])}</b> wins <b>both</b> cards!\n"
        f"<blockquote>{_cb_card_line(m['a']['stake'])}\n{_cb_card_line(m['b']['stake'])}</blockquote>\n"
        f"📊 <i>Record: {wd.get('cardbet_wins', 0)}W – {wd.get('cardbet_losses', 0)}L</i>"
    )
    try:
        await bot1.send_message(m["chat_id"], text, parse_mode='html', reply_to=m.get("msg_id"), link_preview=False)
    except Exception as e:
        print(f"cardbet result message failed: {e}")
        try:
            await bot1.send_message(m["chat_id"], text, parse_mode='html', link_preview=False)
        except Exception:
            pass
    await _cb_refresh(m)


async def _cb_accept_challenge(mid):
    """ကစားမည် pressed by the challenged player. Nothing has been locked until now, so:
       1) claim the match (challenge -> locking) so a double tap can't run this twice,
       2) RE-CHECK that both players still hold their card in the vault (gift / sell / trade / scrap since the challenge),
       3) escrow both cards, 4) roll. Any failure cancels and returns whatever was already locked."""
    m = await _cb_cas(mid, ("challenge",), {"$set": {"state": "locking", "locking_at": time.time(), "locking_by": _CARDBET_BOOT}})
    if not m:
        return False
    await _cb_refresh(m)
    for side in ("a", "b"):                                 # step 2 — nothing has moved yet
        sd = m[side]
        cid = (sd.get("preview") or {}).get("char_id")
        if not cid or not any(it.get("char_id") == cid for it in await _cb_vault(sd["uid"])):
            await _cb_cancel(mid, ("locking",), note=f"{_cb_mention(sd)} no longer has <code>{display_char_id(cid or '')}</code> "
                                                      f"in their vault (gifted / sold / traded?) — nothing was played, no card moved.")
            return False
    for side in ("a", "b"):                                 # step 3 — escrow (journaled, crash-safe)
        sd = m[side]
        ok, why = await _cb_lock_stake(mid, side, sd["uid"], sd["preview"]["char_id"], state="locking")
        if not ok:
            if why == "state":                              # match was cancelled under us (owner tool / janitor) — they own the cleanup
                return False
            await _cb_cancel(mid, ("locking",), note=f"{_cb_mention(sd)} no longer has <code>{display_char_id(sd['preview']['char_id'])}</code> "
                                                      f"in their vault — cards returned, nothing was played.")
            return False
    return await _cb_start_duel(mid, "locking")             # step 4


# ------------------------------------------------------------ pickers (UI) ----
def _cb_tier_counts(vault):
    c = Counter()
    for it in vault:
        c[classify_rarity(it.get("rarity"))] += 1
    return c


def _cb_rarity_view(mid, vault, who_html, again=False):
    counts = _cb_tier_counts(vault)
    legend = "\n".join(f"{i}️⃣ {_cb_rarity_label(t)} — <code>{counts.get(t, 0)}</code>" for i, t in enumerate(RARITY_TIERS, start=1))
    text = (f"🎴 <b>Card Bet</b> — {who_html}, what will you bet?\n"
            f"Pick the <b>rarity</b> of the card you want to put on the line:\n<blockquote>{legend}</blockquote>")
    rows, row = [], []
    for i, t in enumerate(RARITY_TIERS, start=1):
        n = counts.get(t, 0)
        row.append(Button.inline(f"{RARITY_EMOJI.get(t, '❓')} {i} · {n}" if n else f"▫️ {i} · 0", data=f"cbet_r_{mid}_{i}" if n else f"cbet_z_{mid}"))
        if len(row) == 3:
            rows.append(row)
            row = []
    rows.append([Button.inline("❌ Cancel", data=f"cbet_x_{mid}")])
    return text, rows


async def _cb_cards_view(mid, vault, tier_n, page):
    tier = RARITY_TIERS[tier_n - 1]
    by_id = Counter(it["char_id"] for it in vault if classify_rarity(it.get("rarity")) == tier)
    docs = await characters_base_col.find({"char_id": {"$in": list(by_id)}}, {"char_id": 1, "name": 1}).to_list(length=None) if by_id else []
    names = {d["char_id"]: d.get("name") or d["char_id"] for d in docs}
    cards = sorted(by_id, key=lambda c: (names.get(c, c).lower(), c))
    pages = max(1, -(-len(cards) // CARDBET_PAGE_SIZE))
    page = max(0, min(page, pages - 1))
    chunk = cards[page * CARDBET_PAGE_SIZE:(page + 1) * CARDBET_PAGE_SIZE]
    rows = []
    for c in chunk:
        label = f"{names.get(c, c)[:26]}{f' ×{by_id[c]}' if by_id[c] > 1 else ''} · {display_char_id(c)}"
        rows.append([Button.inline(label, data=f"cbet_s_{mid}_{c}")])
    nav = []
    if page > 0:
        nav.append(Button.inline("⬅️", data=f"cbet_p_{mid}_{tier_n}_{page - 1}"))
    nav.append(Button.inline(f"{page + 1}/{pages}", data=f"cbet_n_{mid}"))
    if page < pages - 1:
        nav.append(Button.inline("➡️", data=f"cbet_p_{mid}_{tier_n}_{page + 1}"))
    rows.append(nav)
    rows.append([Button.inline("🔙 Rarity", data=f"cbet_b_{mid}"), Button.inline("❌ Cancel", data=f"cbet_x_{mid}")])
    text = f"🎴 <b>Card Bet</b> — {_cb_rarity_label(tier)}\nTap the card you want to bet <i>({len(cards)} different card(s))</i>:"
    return text, rows


async def _cb_confirm_view(mid, vault, char_id):
    copies = [it for it in vault if it.get("char_id") == char_id]
    if not copies:
        return None, None
    char = await characters_base_col.find_one({"char_id": char_id}, {"name": 1, "category": 1})
    tier = classify_rarity(copies[0].get("rarity"))
    text = (f"🎴 <b>Lock this card into the bet?</b>\n<blockquote>{_cb_rarity_label(tier)}\n"
            f"✨ <b>{escape_html((char or {}).get('name') or char_id)}</b> <code>{display_char_id(char_id)}</code>\n"
            f"🏖️ {escape_html((char or {}).get('category') or 'Unknown')}\n📦 You own <code>{len(copies)}</code> cop{'y' if len(copies) == 1 else 'ies'} — one of them goes in.</blockquote>\n"
            f"⚠️ <i>If you lose the duel, this card goes to your opponent.</i>")
    return text, [[colored_button("🔒 Lock it in", f"cbet_k_{mid}_{char_id}", color="success"),
                   Button.inline("🔙 Back", data=f"cbet_p_{mid}_{RARITY_TIERS.index(tier) + 1}_0")]]


# ----------------------------------------------------------- commands ----
@bot1.on(events.NewMessage(pattern=own_pattern(r'(?i)^[/.]cardbet(?:@\w+)?(?:\s+([A-Za-z0-9_]+))?(?:\s+([A-Za-z0-9_]+))?$', 'bot1')))
async def cardbet_command(event):
    """/cardbet                       -> how to play
       (reply) /cardbet MINE THEIRS   -> challenge: shows both cards + ကစားမည် / တော်ပြီ buttons for the challenged player
       /cardbet cancel                -> cancel / decline your current bet"""
    if is_duplicate_event(event): return
    uid = event.sender_id
    arg1 = (event.pattern_match.group(1) or "").strip()
    arg2 = (event.pattern_match.group(2) or "").strip()
    if not arg1 or arg1.lower() in ("help", "rules"):
        return await event.reply(CARDBET_RULES, parse_mode='html')
    if arg1.lower() == "cancel":
        m = await _cb_active_for(uid)
        if not m:
            return await event.reply("You're not in a card bet right now.", parse_mode='html')
        if m["state"] in ("locking", "rolling", "settling"):
            return await event.reply("🎲 The duel is already being decided — it can't be cancelled now.", parse_mode='html')
        if uid == m["a"].get("uid"):
            c = await _cb_cancel(m["_id"], ("draft", "open", "b_picking", "proposed", "challenge"),
                                 note=f"{_cb_mention(m['a'])} withdrew the challenge." if m["state"] == "challenge" else None)
        elif uid == m["b"].get("uid") and m["state"] in ("proposed", "challenge"):
            c = await _cb_cancel(m["_id"], ("proposed", "challenge"),
                                 note=f"{_cb_mention(m['b'])} declined." if m["state"] == "challenge" else None)
        else:
            return await event.reply("Use the ❌ Cancel button on your card-picker message.", parse_mode='html')
        return await event.reply("❌ <b>Card bet cancelled</b> — no card was lost." if c else "⏳ One moment — try again.", parse_mode='html')
    if event.is_private:
        return await event.reply("🎴 Card bets are played in <b>groups</b> — use <code>/cardbet</code> in a group chat.", parse_mode='html')
    if not arg2 or not event.is_reply:
        return await event.reply(CARDBET_USAGE, parse_mode='html')

    rm = await event.get_reply_message()
    tsender = await rm.get_sender() if rm else None
    if not tsender or tsender.id == uid:
        return await event.reply("❌ Reply to <b>another player</b> to challenge them.", parse_mode='html')
    if getattr(tsender, "bot", False):
        return await event.reply("❌ You can't bet against a bot.", parse_mode='html')
    if is_owner_mode(tsender.id):
        return await event.reply("👑 Owners can't be challenged to a card bet.", parse_mode='html')
    err = await _cb_can_join(uid)
    if err:
        return await event.reply(f"❌ {err}", parse_mode='html')
    t_uid, t_name = tsender.id, _cb_plain_name(tsender)
    if await _cb_active_for(t_uid):
        return await event.reply(f"❌ <b>{escape_html(t_name)}</b> is already in a card bet.", parse_mode='html')

    a_cid, b_cid = normalize_char_id_input(arg1), normalize_char_id_input(arg2)
    a_copy = next((it for it in await _cb_vault(uid) if it.get("char_id") == a_cid), None)
    if not a_copy:
        return await event.reply(f"❌ You don't have <code>{display_char_id(a_cid)}</code> in your vault.", parse_mode='html')
    b_copy = next((it for it in await _cb_vault(t_uid) if it.get("char_id") == b_cid), None)
    if not b_copy:
        return await event.reply(f"❌ <b>{escape_html(t_name)}</b> doesn't have <code>{display_char_id(b_cid)}</code> in their vault.", parse_mode='html')

    names = {d["char_id"]: d.get("name") for d in await characters_base_col.find({"char_id": {"$in": [a_cid, b_cid]}}, {"char_id": 1, "name": 1}).to_list(length=None)}
    me = await event.get_sender()
    now = time.time()
    mid = secrets.token_hex(4)
    await cardbet_col.insert_one({
        "_id": mid, "chat_id": event.chat_id, "msg_id": None, "flow": "v3", "state": "challenge",
        "created_at": now, "updated_at": now, "expires_at": now + CARDBET_CHALLENGE_TTL,
        "target_uid": t_uid, "target_name": t_name,
        "a": {"uid": uid, "name": _cb_plain_name(me, uid), "held": False,
              "preview": {"char_id": a_cid, "name": names.get(a_cid) or a_cid, "item": {"rarity": a_copy.get("rarity")}}},
        "b": {"uid": t_uid, "name": t_name, "held": False,
              "preview": {"char_id": b_cid, "name": names.get(b_cid) or b_cid, "item": {"rarity": b_copy.get("rarity")}}}})
    m = await _cb_get(mid)
    text, buttons = _cb_render(m)
    sent = await event.reply(text, parse_mode='html', buttons=buttons, link_preview=False)
    await cardbet_col.update_one({"_id": mid}, {"$set": {"msg_id": sent.id}})


@bot1.on(events.CallbackQuery(pattern=r'^cbet_([a-z])_([0-9a-f]{8})(?:_(.+))?$'))
async def cardbet_callback(event):
    act, mid, rest = _dec(event.pattern_match.group(1)), _dec(event.pattern_match.group(2)), _dec(event.pattern_match.group(3)) or ""
    uid = event.sender_id
    m = await _cb_get(mid)
    if not m:
        return await event.answer("⚠️ This card bet no longer exists.", alert=True)
    st = m["state"]
    a_uid, b_uid = m["a"].get("uid"), m["b"].get("uid")

    if act == "n":                                       # page counter button — does nothing
        return await event.answer()
    if act == "z":
        return await event.answer("You have no cards of that rarity.", alert=True)

    # ---------- 🎲 ကစားမည် (challenged player) ----------
    if act == "y":
        if st != "challenge":
            return await event.answer("⌛ This challenge is no longer open.", alert=True)
        if uid != b_uid:
            return await event.answer("⏳ Waiting for the challenged player — you can tap တော်ပြီ to withdraw." if uid == a_uid
                                      else "This challenge isn't for you.", alert=True)
        if not claim_single_tap(event):
            return await event.answer("⏳ One moment…")
        await event.answer("🔍 Checking both cards…")
        return await _cb_accept_challenge(mid)

    # ---------- ⚔️ Accept (opponent) ----------
    if act == "a":
        if st != "open":
            return await event.answer("⌛ This challenge is no longer open.", alert=True)
        if uid == a_uid:
            return await event.answer("That's your own challenge — wait for an opponent, or Cancel.", alert=True)
        if m.get("target_uid") and m["target_uid"] != uid:
            return await event.answer("This challenge is for someone else.", alert=True)
        if not claim_single_tap(event):
            return await event.answer("⏳ One moment…")
        err = await _cb_can_join(uid)
        if err:
            return await event.answer(err, alert=True)
        me = await event.get_sender()
        c = await _cb_cas(mid, ("open",), {"$set": {"state": "b_picking", "pick_deadline": time.time() + CARDBET_PICK_TTL,
                                                    "b": {"uid": uid, "name": _cb_plain_name(me, uid), "held": False}}})
        if not c:
            return await event.answer("Someone else just accepted this challenge.", alert=True)
        await event.answer("🎴 Pick the card you'll bet!")
        text, buttons = _cb_rarity_view(mid, await _cb_vault(uid), _cb_mention(c["b"]))
        await bot1.send_message(c["chat_id"], text, parse_mode='html', buttons=buttons, reply_to=c.get("msg_id"))
        return await _cb_refresh(c)

    # ---------- 🎲 Start duel (challenger) ----------
    if act == "g":
        if uid != a_uid:
            return await event.answer("Only the challenger can start the duel.", alert=True)
        if st != "proposed":
            return await event.answer("⌛ Nothing to start right now.", alert=True)
        if not claim_single_tap(event):
            return await event.answer("⏳ Already starting…")
        await event.answer("🎲 Duel starts!")
        return await _cb_start_duel(mid)

    # ---------- ❌ Cancel ----------
    if act == "x":
        if st == "challenge":                            # တော်ပြီ — the challenged player declines, or the challenger withdraws
            if uid not in (a_uid, b_uid):
                return await event.answer("This challenge isn't yours.", alert=True)
            note = f"{_cb_mention(m['b'])} declined." if uid == b_uid else f"{_cb_mention(m['a'])} withdrew the challenge."
            c = await _cb_cancel(mid, ("challenge",), note=note)
            return await event.answer("❌ Cancelled — no card moved." if c else "⏳ Too late — it already started.", alert=not c)
        if st == "draft" and uid == a_uid:
            c = await _cb_cas(mid, ("draft",), {"$set": {"state": "cancelled", "finished_at": time.time()}}, {"a.intent": {"$exists": False}})
            if not c:
                return await event.answer("🔒 Locking your card — one moment…", alert=True)
            await event.answer("Cancelled.")
            return await event.edit("❌ <b>Card bet cancelled.</b>", parse_mode='html', buttons=None)
        if st == "b_picking" and uid == b_uid:
            c = await _cb_cas(mid, ("b_picking",), {"$set": {"state": "open", "expires_at": max(m.get("expires_at", 0), time.time() + 60),
                                                             "b": {"uid": None, "name": None, "held": False}}}, {"b.intent": {"$exists": False}})
            if not c:
                return await event.answer("🔒 Locking your card — one moment…", alert=True)
            await event.answer("Cancelled.")
            try:
                await event.delete()
            except Exception:
                pass
            return await _cb_refresh(c)
        if (uid == a_uid and st in ("open", "b_picking", "proposed")) or (uid == b_uid and st == "proposed"):
            c = await _cb_cancel(mid, ("open", "b_picking", "proposed"))
            return await event.answer("❌ Bet cancelled — cards returned." if c else "⏳ One moment — try again.", alert=not c)
        return await event.answer("You can't cancel this one.", alert=True)

    # ---------- picker steps (rarity / page / back / select / lock) ----------
    side = "a" if (st == "draft" and uid == a_uid) else ("b" if (st == "b_picking" and uid == b_uid) else None)
    if act in ("r", "p", "b", "s", "k"):
        if side is None:
            return await event.answer("This menu isn't yours — or it already expired.", alert=True)
        vault = await _cb_vault(uid)
        if act == "b":
            text, buttons = _cb_rarity_view(mid, vault, _cb_mention(m[side]))
        elif act == "r":
            text, buttons = await _cb_cards_view(mid, vault, int(rest), 0)
        elif act == "p":
            tier_n, page = (int(x) for x in rest.split("_"))
            text, buttons = await _cb_cards_view(mid, vault, tier_n, page)
        elif act == "s":
            text, buttons = await _cb_confirm_view(mid, vault, rest)
            if not text:
                return await event.answer("That card isn't in your vault any more.", alert=True)
        else:                                            # act == "k": lock it in
            if not claim_single_tap(event):
                return await event.answer("⏳ Already locking…")
            ok, why = await _cb_lock_stake(mid, side, uid, rest)
            if not ok:
                return await event.answer("That card isn't in your vault any more — pick another." if why == "no_card"
                                          else "⌛ This bet is no longer active.", alert=True)
            if side == "a":
                c = await _cb_cas(mid, ("draft",), {"$set": {"state": "open", "expires_at": time.time() + CARDBET_OPEN_TTL}})
                if not c:
                    await _cb_close_stakes(mid)
                    return await event.answer("⌛ The bet was cancelled — your card is back.", alert=True)
                await event.answer("🔒 Card locked! Waiting for an opponent.")
                text, buttons = _cb_render(c)
                return await event.edit(text, parse_mode='html', buttons=buttons, link_preview=False)
            c = await _cb_cas(mid, ("b_picking",), {"$set": {"state": "proposed", "expires_at": time.time() + CARDBET_PROPOSED_TTL}}, {"b.uid": uid})
            if not c:
                await _cb_close_stakes(mid)
                return await event.answer("⌛ The bet was cancelled — your card is back.", alert=True)
            await event.answer("🔒 Card locked! Waiting for the challenger to start the duel.")
            try:
                await event.delete()
            except Exception:
                pass
            return await _cb_refresh(c)
        await event.answer()
        return await event.edit(text, parse_mode='html', buttons=buttons)
    await event.answer()


# -------------------------------------------- janitor / recovery / owner tool ----
async def _cardbet_janitor_pass():
    now = time.time()
    await _cb_resolve_intents()
    # a draft nobody finished holds no card — just close it
    async for m in cardbet_col.find({"state": "draft", "expires_at": {"$lt": now}, "a.intent": {"$exists": False}}):
        c = await _cb_cas(m["_id"], ("draft",), {"$set": {"state": "cancelled", "finished_at": now}}, {"a.intent": {"$exists": False}})
        if c and c.get("msg_id"):
            try:
                await bot1.edit_message(c["chat_id"], c["msg_id"], "⌛ <b>Card bet expired</b> — no card was chosen.", parse_mode='html', buttons=None)
            except Exception:
                pass
    # unanswered challenge / undecided duel -> expire + refund
    for st in ("open", "proposed", "challenge"):
        async for m in cardbet_col.find({"state": st, "expires_at": {"$lt": now}}):
            await _cb_cancel(m["_id"], (st,), "expired", note="nobody answered in time — no card moved." if st == "challenge" else None)
    # ကစားမည် was pressed but the process died before the duel started -> give back whatever was locked
    async for m in cardbet_col.find({"state": "locking", "a.intent": {"$exists": False}, "b.intent": {"$exists": False},
                                     "$or": [{"locking_by": {"$ne": _CARDBET_BOOT}}, {"locking_at": {"$lt": now - CARDBET_STALE_SECS}}]}):
        await _cb_cancel(m["_id"], ("locking",), note="the bot was interrupted while starting the duel — cards returned.",
                         extra={"a.intent": {"$exists": False}, "b.intent": {"$exists": False}})
    # opponent walked away mid-pick -> challenge goes back on the board
    async for m in cardbet_col.find({"state": "b_picking", "pick_deadline": {"$lt": now}, "b.intent": {"$exists": False}}):
        c = await _cb_cas(m["_id"], ("b_picking",), {"$set": {"state": "open", "expires_at": max(m.get("expires_at", 0), now + 60),
                                                              "b": {"uid": None, "name": None, "held": False}}}, {"b.intent": {"$exists": False}})
        await _cb_refresh(c)
    # a roll / payout a previous process (or a stuck task) left half-done
    async for m in cardbet_col.find({"state": "rolling", "$or": [{"rolling_by": {"$ne": _CARDBET_BOOT}}, {"rolling_at": {"$lt": now - CARDBET_STALE_SECS}}]}):
        c = await cardbet_col.find_one_and_update(
            {"_id": m["_id"], "state": "rolling", "$or": [{"rolling_by": {"$ne": _CARDBET_BOOT}}, {"rolling_at": {"$lt": now - CARDBET_STALE_SECS}}]},
            {"$set": {"rolling_by": _CARDBET_BOOT, "rolling_at": now}}, return_document=ReturnDocument.AFTER)
        if c:
            print(f"🎴 cardbet {c['_id']}: resuming an interrupted roll")
            asyncio.create_task(_cb_roll_and_settle(c))
    async for m in cardbet_col.find({"state": "settling", "$or": [{"settling_by": {"$ne": _CARDBET_BOOT}}, {"settling_at": {"$lt": now - CARDBET_STALE_SECS}}]}):
        print(f"🎴 cardbet {m['_id']}: finishing an interrupted payout")
        await cardbet_col.update_one({"_id": m["_id"]}, {"$set": {"settling_by": _CARDBET_BOOT, "settling_at": now}})
        await _cb_finish_settle(m["_id"])
    # any finished/cancelled match that still has a card in escrow -> hand it over (idempotent)
    async for m in cardbet_col.find({"state": {"$in": ["cancelled", "expired", "done"]},
                                     "$or": [{"a.held": True, "a.closed": {"$ne": True}}, {"b.held": True, "b.closed": {"$ne": True}}]}):
        await _cb_close_stakes(m["_id"])


async def cardbet_janitor_loop():
    while True:
        try:
            await _cardbet_janitor_pass()
        except Exception as e:
            print(f"cardbet janitor error: {e}")
        await asyncio.sleep(CARDBET_JANITOR_INTERVAL)


async def cardbet_recover_on_startup():
    """Run once at every start (run_bot1_forever): indexes, resume whatever the previous process left, start the janitor."""
    global _cardbet_janitor_task
    try:
        await cardbet_col.create_index([("state", 1), ("expires_at", 1)])
        await cardbet_col.create_index("a.uid")
        await cardbet_col.create_index("b.uid")
        await _cardbet_janitor_pass()
        active = await cardbet_col.count_documents({"state": {"$in": list(_CB_ACTIVE)}})
        print(f"🎴 cardbet: startup recovery done — {active} bet(s) still active (their buttons keep working).")
    except Exception as e:
        print(f"⚠️ cardbet startup recovery failed (the janitor will retry): {type(e).__name__}: {e}")
    if _cardbet_janitor_task is None or _cardbet_janitor_task.done():
        _cardbet_janitor_task = asyncio.create_task(cardbet_janitor_loop())


# ==========================================
# NEW COMMAND — /reconcilegroups …
# ==========================================
@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]reconcilegroups(?:@\w+)?$', 'bot1')))
async def reconcile_groups_cmd(event):
    """Owner-only: reconciles active_groups (groups_col — what /send reads) against chat_ids
    this bot has DEFINITELY seen real message activity in (groups_counters_col)."""
    if event.sender_id != OWNER_ID: return
    status = await event.reply("🔄 <b>Reconciling active_groups from known chat activity...</b>", parse_mode='html')
    try:
        known_chat_ids = await groups_counters_col.distinct("chat_id")
        known_chat_ids = [cid for cid in known_chat_ids if isinstance(cid, int) and cid < 0]
        if not known_chat_ids:
            return await status.edit(
                "⚠️ <b>groups_counters_col came back empty — that looks wrong</b> "
                "(hundreds of groups should have counter entries by now), so I didn't touch "
                "active_groups at all rather than risk wiping it on a bad read. Check the DB "
                "connection and try again.",
                parse_mode='html'
            )

        total = len(known_chat_ids)
        added, updated = 0, 0
        failed_details = []  # (chat_id, reason) — every failure gets a name, not just a tally

        # Progress edits are throttled to roughly ~20 updates across the whole run (min every
        # 10 chats) rather than one per chat — editing the status message on every single
        # iteration would burn through Telegram's edit rate limit long before a few hundred
        # groups finished processing.
        progress_every = max(10, total // 20)

        for i, chat_id in enumerate(known_chat_ids, start=1):
            try:
                title = "Unknown"
                try:
                    entity = await bot1.get_entity(chat_id)
                    title = getattr(entity, 'title', None) or "Unknown"
                except Exception:
                    pass  # a title-lookup miss isn't a reconciliation failure — the upsert
                          # below still goes through fine with "Unknown" as a placeholder
                result = await groups_col.update_one(
                    {"chat_id": chat_id},
                    {"$set": {"chat_id": chat_id, "title": title}},
                    upsert=True
                )
                if result.upserted_id is not None:
                    added += 1
                elif result.modified_count:
                    updated += 1
            except Exception as e:
                failed_details.append((chat_id, str(e)))
                print(f"reconcile_groups_cmd per-chat error ({chat_id}): {e}")

            if i % progress_every == 0 or i == total:
                try:
                    await status.edit(
                        f"🔄 <b>Reconciling active_groups...</b>\n"
                        f"📊 <code>{i}/{total}</code> processed — "
                        f"➕ <code>{added}</code> new, 🔄 <code>{updated}</code> updated, "
                        f"❌ <code>{len(failed_details)}</code> failed so far",
                        parse_mode='html'
                    )
                except Exception:
                    pass  # a progress edit failing (rate limit, not-modified, whatever) is
                          # never worth interrupting the reconciliation itself over

        removed = 0
        stale = await groups_col.count_documents({"chat_id": {"$nin": known_chat_ids}})
        if stale:
            await groups_col.delete_many({"chat_id": {"$nin": known_chat_ids}})
            removed = stale

        summary = (
            f"✅ <b>Group reconciliation complete.</b>\n"
            f"➕ New: <code>{added}</code>\n"
            f"🔄 Updated: <code>{updated}</code>\n"
            f"🗑️ Removed (invalid/stale): <code>{removed}</code>\n"
            f"❌ Failed: <code>{len(failed_details)}</code>\n"
            f"📊 Total tracked now: <code>{total}</code>"
        )
        if failed_details:
            # Capped at 15 so a bad run against a huge group list can't blow past Telegram's
            # 4096-char message limit — the rest are still in the logs via the print() above.
            shown = failed_details[:15]
            fail_lines = "\n".join(f"  <code>{cid}</code> — {escape_html(reason)}" for cid, reason in shown)
            more = f"\n  ...and {len(failed_details) - 15} more (see logs)" if len(failed_details) > 15 else ""
            summary += f"\n\n<b>Failures:</b>\n{fail_lines}{more}"

        await status.edit(summary, parse_mode='html')
    except Exception as e:
        print(f"reconcile_groups_cmd error: {e}")
        try:
            await status.edit(f"❌ <b>Reconciliation failed:</b> <code>{escape_html(str(e))}</code>", parse_mode='html')
        except Exception:
            pass

# ==========================================
# 🛒 DAILY OWNER SHOP — Owner hand-picks up to DAILY_SHOP_MAX_ITEMS characters and sets a VLT
# price for each, once a day (/setshop), then broadcasts that exact batch to every group as a
# browsable Prev/Next gallery (/broadcastshop). This is deliberately separate from the existing
# automatic per-rarity Owner Shop (/buy, RARITY_VLT_PRICE, execute_star_shop_purchase) — that one
# is instant/self-service at a fixed price per tier; this one is a manually curated, manually
# fulfilled sale at a price the Owner sets per character. Tapping 🛒 Buy doesn't move any VLT or
# card — it opens the buyer's chat with the Owner with "Hello owner <id> ကို လိုချင်လို့ပါ" already
# typed (SHOP_BUY_MESSAGE), so the Owner closes the sale personally. The bot sends the Owner nothing. Storage is one singleton doc in bot_settings_col (same "single-document
# global settings" pattern as the rarity-spawn-weight level) — running /setshop again simply
# overwrites it, which is also how the Owner rotates in a fresh 10 the next day.
# ==========================================
DAILY_SHOP_MAX_ITEMS = 10
DAILY_SHOP_SETTINGS_ID = "daily_owner_shop"
_DAILY_SHOP_LINE_RE = re.compile(r'^\s*(\S+)\s+(\d+(?:\.\d+)?)\s*$')

_owner_username_cache = None
async def get_owner_username():
    """Cached forever once found — same "won't change mid-run" assumption as
    get_force_sub_invite_link(). Returns None (callers fall back to a plain "Owner" label) if
    the Owner's account has no public @username set."""
    global _owner_username_cache
    if _owner_username_cache:
        return _owner_username_cache
    try:
        owner_ent = await bot1.get_entity(OWNER_ID)
        if getattr(owner_ent, 'username', None):
            _owner_username_cache = owner_ent.username
    except Exception as e:
        print(f"⚠️ Could not fetch Owner's username: {e}")
    return _owner_username_cache

async def get_daily_shop_doc():
    return await bot_settings_col.find_one({"_id": DAILY_SHOP_SETTINGS_ID})

def parse_daily_shop_text(raw_text):
    """One 'char_id price' pair per non-empty, non-comment line — same shape as the Owner's
    own example ('8180 5000'). Returns (parsed, errors); parsed keeps input order so slot 1 in
    the paste is slot 1 in the gallery."""
    parsed, errors_out = [], []
    for line_no, raw_line in enumerate(raw_text.splitlines(), start=1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        m = _DAILY_SHOP_LINE_RE.match(line)
        if not m:
            errors_out.append((line_no, raw_line, "expected '<char_id> <price>', e.g. '8180 5000'"))
            continue
        char_id = normalize_char_id_input(m.group(1))
        price = float(m.group(2))
        if price <= 0:
            errors_out.append((line_no, raw_line, "price must be greater than 0"))
            continue
        parsed.append({"char_id": char_id, "price": price})
    return parsed, errors_out

def _shop_price_text(price):
    """Plain price for every shop screen — just the amount (per owner request): '5,000'. No 💠, no 'VLT'."""
    return format_vlt_plain(price).replace("💠", "").strip()

def _shop_catches_text(char_doc):
    spawn_count = char_doc.get("spawn_count", 0) or 0
    limit = char_doc.get("spawn_limit", 0) or 0
    if not limit:
        return f"<code>{spawn_count}</code> · ♾️ Infinite"
    if spawn_count >= limit:
        return f"<code>{spawn_count}/{limit}</code> · 🔒 LOCKED"
    return f"<code>{spawn_count}/{limit}</code> · <code>{limit - spawn_count} left</code>"

def _daily_shop_caption(char_doc, price, idx, total):
    """The shop card: everything /check shows about the card itself (event, rarity, anime, artist/video credit, catches) + the price."""
    rarity_display = char_doc.get("rarity") or "Unknown"
    event_label = " | ".join(x for x in (event_label_of(char_doc), escape_html(custom_event_label_of(char_doc) or "")) if x)
    header = f"{event_label} | {rarity_display}" if event_label else rarity_display
    credit = ultra_credit_line(char_doc) or artist_line(char_doc)
    return (
        f"🛒 <b>Owner's Daily Shop</b> — <code>{idx + 1}/{total}</code>\n"
        f"<blockquote>"
        f"✨ <b>Name:</b> <code>{escape_html(char_doc.get('name',''))}</code>\n"
        f"🆔 <b>ID:</b> <code>{display_char_id(char_doc.get('char_id',''))}</code>\n"
        f"{header}\n"
        f"🏖️ <b>Anime:</b> {escape_html(char_doc.get('category') or 'Unknown')}\n"
        f"{credit}"
        f"🌎 <b>Global Catches:</b> {_shop_catches_text(char_doc)}\n"
        f"💰 <b>Price:</b> <code>{_shop_price_text(price)}</code>"
        f"</blockquote>\n"
        f"👇 <i>Tap Buy to message the Owner directly</i>"
    )

from urllib.parse import quote as _url_quote

# 🛒 Buy on a daily-shop card (2026-11, per owner request): no more "purchase request" DM from the bot with an "Open buyer's chat" button for the Owner.
# The button now opens the buyer's own chat with the Owner with this message already typed — they only press Send. {id} = the card id as shown in the shop.
SHOP_BUY_MESSAGE = "Hello owner {id} ကို လိုချင်လို့ပါ"          # no emoji
_shop_buy_no_username_warned = False

async def _daily_shop_buy_url(char_id):
    """https://t.me/<owner username>?text=... — needs the Owner account to have a public @username (that's what lets Telegram pre-fill the draft).
    Without one it falls back to the Owner's profile link, which opens the chat but cannot pre-fill anything."""
    global _shop_buy_no_username_warned
    text = SHOP_BUY_MESSAGE.format(id=display_char_id(char_id))
    uname = await get_owner_username()
    if uname:
        return f"https://t.me/{uname}?text={_url_quote(text, safe='')}"
    if not _shop_buy_no_username_warned:
        _shop_buy_no_username_warned = True
        print("⚠️ Daily shop 🛒 Buy: the Owner account has no public @username (or it couldn't be read) — the button opens the Owner's profile but can't pre-fill the message")
    return f"tg://user?id={OWNER_ID}"

async def _daily_shop_nav_buttons(idx, total, char_doc):
    rows = []
    if total > 1:
        rows.append([
            Button.inline("⬅️ Prev", data=f"dshop_{(idx - 1) % total}"),
            Button.inline("➡️ Next", data=f"dshop_{(idx + 1) % total}"),
        ])
    rows.append([
        Button.url("📢 Owner's Group", sold_out_contact_link()),
        _apply_button_style(Button.url("🛒 Buy", await _daily_shop_buy_url(char_doc['char_id'])), "success"),
    ])
    return rows

def _daily_shop_summary(confirmed, doc_by_id, missing, errors_out):
    """The /setshop success message — one block per card with its details and price."""
    lines = []
    for i, item in enumerate(confirmed, start=1):
        d = doc_by_id[item["char_id"]]
        lines.append(
            f"<b>{i}.</b> <b>{escape_html(d.get('name', '?'))}</b> · <code>{display_char_id(item['char_id'])}</code>\n"
            f"     {d.get('rarity') or 'Unknown'} · {escape_html(d.get('category') or 'Unknown')}\n"
            f"     💰 <code>{_shop_price_text(item['price'])}</code> · 🌎 {_shop_catches_text(d)}"
        )
    summary = f"✅ <b>Today's Owner Shop set — {len(confirmed)} card(s):</b>\n<blockquote>" + "\n\n".join(lines) + "</blockquote>"
    if missing:
        summary += f"\n\n⚠️ Skipped (not found): <code>{', '.join(display_char_id(m) for m in missing)}</code>"
    if errors_out:
        err_lines = "\n".join(f"  Line {ln}: {reason}" if ln else f"  {reason}" for ln, _raw, reason in errors_out)
        summary += f"\n\n❌ <b>Line issues:</b>\n<code>{escape_html(err_lines)}</code>"
    summary += ("\n\n🔍 <i>Tap a Check button to preview a card exactly as buyers see it.</i>\n"
                "🛒 <i>While this shop is set, every catch message shows a 🛒 Daily Shop button that opens it.</i>\n"
                "📢 <i>/broadcastshop sends this batch to every group + DM — /broadcastshop groups for groups only.</i>")
    return summary

def _daily_shop_check_buttons(confirmed):
    btns = [Button.inline(f"🔍 Check #{display_char_id(item['char_id'])}", data=f"dshopchk_{i}") for i, item in enumerate(confirmed)]
    return [btns[k:k + 2] for k in range(0, len(btns), 2)]

async def _daily_shop_send_card(chat_id, idx, reply_to=None):
    """Posts one shop card (media + details + Prev/Next + Buy) into chat_id. Returns the sent message, or None if the card is gone."""
    shop_doc = await get_daily_shop_doc()
    items = (shop_doc or {}).get("items") or []
    if not items:
        return None
    idx %= len(items)
    item = items[idx]
    char_doc = await characters_base_col.find_one({"char_id": item["char_id"]})
    if not char_doc:
        return None
    caption = _daily_shop_caption(char_doc, item["price"], idx, len(items))
    buttons = await _daily_shop_nav_buttons(idx, len(items), char_doc)

    async def _send(media):
        return await bot1.send_message(chat_id, caption, file=media, buttons=buttons, parse_mode='html', reply_to=reply_to)
    sent = await send_with_char_media(char_doc["char_id"], char_doc.get("storage_msg_id"), _send)
    if sent is None:        # media unavailable — still show the details
        sent = await bot1.send_message(chat_id, caption, buttons=buttons, parse_mode='html', reply_to=reply_to)
    return sent

@bot1.on(events.CallbackQuery(pattern=r'^dshopchk_(\d+)$'))
async def daily_shop_check_callback(event):
    """🔍 Check #id under the /setshop success message -> that card, as buyers see it (details, Prev/Next, Buy)."""
    idx = int(event.pattern_match.group(1))
    try:
        sent = await _daily_shop_send_card(event.chat_id, idx)
    except Exception as e:
        print(f"daily_shop_check_callback error: {e}")
        sent = None
    if sent is None:
        return await event.answer("⚠️ That card is no longer in the shop — run /setshop again.", alert=True)
    await event.answer()

# 🛒 The "Daily Shop" button under every catch-success message (replaces the old 🔍 Check #id there while a shop is set).
# perform_catch asks daily_shop_is_active() on every catch, so it is cached in memory (one Mongo read per TTL, and /setshop refreshes it).
_DAILY_SHOP_FLAG_TTL = 120
_daily_shop_flag = {"on": False, "ts": 0.0}

async def daily_shop_is_active():
    now = time.time()
    if now - _daily_shop_flag["ts"] > _DAILY_SHOP_FLAG_TTL:
        try:
            doc = await bot_settings_col.find_one({"_id": DAILY_SHOP_SETTINGS_ID}, {"items": 1})
            _daily_shop_flag.update({"on": bool(doc and doc.get("items")), "ts": now})
        except Exception as e:
            print(f"⚠️ daily_shop_is_active read failed: {e}")
            _daily_shop_flag["ts"] = now - _DAILY_SHOP_FLAG_TTL + 15      # keep the last answer, retry in ~15 s
    return _daily_shop_flag["on"]

_shop_open_last = {}            # user_id -> last time they opened the shop from a catch message
SHOP_OPEN_COOLDOWN = 10         # seconds — one tap per person posts the shop; stops a group being flooded with copies

async def daily_shop_open_callback(event):
    """🛒 Daily Shop button under a catch message -> posts the Owner's shop (card 1 + details + Prev/Next + Buy) as a reply in that chat.
    Sent by bot1 — the same messages /broadcastshop posts — so the Prev/Next/Buy taps that follow land on bot1's handlers."""
    uid = event.sender_id
    now = time.time()
    if uid and now - _shop_open_last.get(uid, 0) < SHOP_OPEN_COOLDOWN:
        return await event.answer("🛒 The shop is already open just below — scroll down!")
    shop_doc = await get_daily_shop_doc()
    if not ((shop_doc or {}).get("items")):
        _daily_shop_flag.update({"on": False, "ts": now})
        return await event.answer("📭 The Owner hasn't set up a shop today.", alert=True)
    if uid:
        if len(_shop_open_last) > 5000:
            _shop_open_last.clear()
        _shop_open_last[uid] = now
    try:
        sent = await _daily_shop_send_card(event.chat_id, 0, reply_to=event.message_id)
    except Exception as e:
        print(f"daily_shop_open_callback error: {e}")
        sent = None
    if sent is None:
        _shop_open_last.pop(uid, None)
        return await event.answer("⚠️ Couldn't open the shop right now — try again in a moment.", alert=True)
    await event.answer()

bot1.on(events.CallbackQuery(pattern=r'^dshopopen$'))(daily_shop_open_callback)

@bot1.on(events.CallbackQuery(pattern=r'^dshopbuy_([A-Za-z0-9_\-]+)$'))
async def daily_shop_buy_callback(event):
    """LEGACY. Shop messages posted before 🛒 Buy became a direct link to the Owner's DM still carry this callback button.
    It no longer sends the Owner anything: it swaps that message's keyboard for the current one (🛒 Buy = link with the message pre-typed)."""
    char_id = _dec(event.pattern_match.group(1))
    shop_doc = await get_daily_shop_doc()
    items = (shop_doc or {}).get("items") or []
    idx = next((n for n, i in enumerate(items) if i["char_id"] == char_id), None)
    char_doc = await characters_base_col.find_one({"char_id": char_id}) if idx is not None else None
    if char_doc is None:
        return await event.answer("📭 This card is no longer in today's shop.", alert=True)
    try:
        await event.edit(buttons=await _daily_shop_nav_buttons(idx, len(items), char_doc))
    except errors.MessageNotModifiedError:
        pass
    except Exception as e:
        print(f"daily_shop_buy_callback: couldn't refresh the old Buy button: {type(e).__name__}: {e}")
    await event.answer("🛒 Buy ခလုတ်ကို အသစ်ပြောင်းပေးလိုက်ပါပြီ — 🛒 Buy ကို တစ်ခါထပ်နှိပ်ပါ။", alert=True)

async def _build_shop_sender():
    """For /broadcastshop: loads + validates the batch once, then returns sender(target_id) for the shared broadcast engine."""
    shop_doc = await get_daily_shop_doc()
    items = (shop_doc or {}).get("items") or []
    if not items:
        raise RuntimeError("No shop set for today — run /setshop first.")
    first = items[0]
    char_doc = await characters_base_col.find_one({"char_id": first["char_id"]})
    if not char_doc:
        raise RuntimeError(f"{display_char_id(first['char_id'])} no longer exists — run /setshop again.")
    # warm the media cache ONCE so 20 workers don't all fetch the same file at the same instant
    if await get_char_display_media(bot1, char_doc["char_id"], char_doc.get("storage_msg_id")) is None:
        raise RuntimeError("The first card's media couldn't be loaded — try again in a moment.")
    caption = _daily_shop_caption(char_doc, first["price"], 0, len(items))
    buttons = await _daily_shop_nav_buttons(0, len(items), char_doc)

    async def sender(target_id):
        async def _send(media):
            return await bot1.send_message(target_id, caption, file=media, buttons=buttons, parse_mode='html')
        sent = await send_with_char_media(char_doc["char_id"], char_doc.get("storage_msg_id"), _send)
        if sent is None:
            raise RuntimeError("shop media unavailable")
    return sender

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]setshop(?:@\w+)?$', 'bot1')))
async def set_daily_shop_handler(event):
    if event.sender_id != OWNER_ID: return
    try:
        async with bot1.conversation(event.chat_id, timeout=600) as conv:
            await conv.send_message(
                f"🛒 <b>Set Today's Owner Shop</b> — up to {DAILY_SHOP_MAX_ITEMS} cards.\n\n"
                f"Send them now, <b>one per line</b>, as <code>char_id price</code>:\n"
                f"<code>8180 5000\n3121 2000\n131 4200</code>\n\n"
                f"This replaces whatever batch is currently set — run /setshop again anytime "
                f"(e.g. tomorrow) to rotate in a fresh batch.\n\n"
                f"Send /cancel to stop.",
                parse_mode='html'
            )
            resp = await conv.get_response()
            if (resp.raw_text or "").strip().lower() == "/cancel":
                return await conv.send_message("❌ Cancelled.")
            raw_text = resp.raw_text or ""
            if not raw_text.strip():
                return await conv.send_message("❌ That was empty. Cancelled — run /setshop again.")

            parsed, errors_out = parse_daily_shop_text(raw_text)
            if len(parsed) > DAILY_SHOP_MAX_ITEMS:
                dropped = len(parsed) - DAILY_SHOP_MAX_ITEMS
                errors_out.append((0, "", f"only the first {DAILY_SHOP_MAX_ITEMS} valid lines are kept — {dropped} extra line(s) dropped"))
                parsed = parsed[:DAILY_SHOP_MAX_ITEMS]
            if not parsed:
                summary_lines = "\n".join(f"  Line {ln}: {reason}" for ln, _raw, reason in errors_out) or "no valid lines found"
                return await conv.send_message(f"❌ <b>Nothing usable there.</b>\n<code>{escape_html(summary_lines)}</code>", parse_mode='html')

            # Verify every char_id actually exists — drop (and report) any that don't, rather
            # than silently pointing the broadcast gallery at a card that will 404 later.
            confirmed, missing, doc_by_id = [], [], {}
            for item in parsed:
                char_doc = await characters_base_col.find_one({"char_id": item["char_id"]})
                if char_doc:
                    confirmed.append(item)
                    doc_by_id[item["char_id"]] = char_doc
                else:
                    missing.append(item["char_id"])
            if not confirmed:
                return await conv.send_message("❌ <b>None of those character IDs exist.</b> Double-check and try again.", parse_mode='html')

            await bot_settings_col.update_one(
                {"_id": DAILY_SHOP_SETTINGS_ID},
                {"$set": {"items": confirmed, "set_at": time.time(), "set_by": event.sender_id}},
                upsert=True
            )
            _daily_shop_flag.update({"on": True, "ts": time.time()})
            summary = _daily_shop_summary(confirmed, doc_by_id, missing, errors_out)
            await conv.send_message(summary, parse_mode='html', buttons=_daily_shop_check_buttons(confirmed))
    except asyncio.TimeoutError:
        await event.reply("⌛ <b>Timed out waiting for your list.</b> Run /setshop again.", parse_mode='html')
    except Exception as e:
        print(f"set_daily_shop_handler error: {e}")
        await event.reply(f"❌ <b>Something went wrong:</b> <code>{escape_html(str(e))}</code>", parse_mode='html')

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]broadcastshop(?:@\w+)?(?:\s+(all|groups|group|dms|dm))?$', 'bot1')))
async def broadcast_daily_shop_handler(event):
    """Same engine as /send (preview -> ✅ confirm, parallel paced workers, live progress, 🛑 Stop, auto-skip of dead chats),
    sending today's shop gallery. /broadcastshop = groups + DMs · /broadcastshop groups · /broadcastshop dms"""
    if event.sender_id != OWNER_ID: return
    if is_duplicate_event(event): return
    if _broadcast_state["running"]:
        return await event.reply(
            "⚠️ <b>A broadcast is already running.</b>\n"
            "<i>Wait for it, or use</i> <code>/stopbroadcast</code>.",
            parse_mode='html',
        )
    shop_doc = await get_daily_shop_doc()
    items = (shop_doc or {}).get("items") or []
    if not items:
        return await event.reply("📭 <b>No shop set for today.</b> Run /setshop first.", parse_mode='html')
    first_doc = await characters_base_col.find_one({"char_id": items[0]["char_id"]})
    if not first_doc:
        return await event.reply(f"❌ <b><code>{display_char_id(items[0]['char_id'])}</code> no longer exists.</b> Run /setshop again.", parse_mode='html')

    arg = (event.pattern_match.group(1) or "all").lower()
    target = {"group": "groups", "dm": "dms"}.get(arg, arg)
    n_groups = (await groups_col.count_documents(_bc_group_query())) if target in ("all", "groups") else 0
    n_dms = (await users_catcher_col.count_documents(_bc_dm_query())) if target in ("all", "dms") else 0
    total = n_groups + n_dms
    if total == 0:
        return await event.reply("📭 Nothing to send to.", parse_mode='html')

    lines = ["🛒 <b>Shop Broadcast Preview</b>\n", f"🎯 <b>Target:</b> <code>{target}</code>"]
    if target in ("all", "groups"):
        lines.append(f"👥 <b>Groups:</b> <code>{n_groups}</code>")
    if target in ("all", "dms"):
        lines.append(f"📩 <b>DMs:</b> <code>{n_dms}</code> <i>(active in last {BROADCAST_DM_ACTIVE_DAYS}d — only those who started the bot will receive it)</i>")
    lines.append(f"📊 <b>Total:</b> <code>{total}</code>")
    lines.append(f"⏱ <b>Est. time:</b> <code>~{_fmt_duration(total / max(1.0, BROADCAST_RATE))}</code>\n")
    lines.append(f"🎴 <b>Batch:</b> <code>{len(items)}</code> card(s) — posting card 1: <b>{escape_html(first_doc.get('name', ''))}</b> "
                 f"(<code>{display_char_id(first_doc['char_id'])}</code>), buyers browse the rest with Prev/Next")
    lines.append("\n⚠️ <i>Press ✅ to send. This cannot be undone.</i>")

    now = time.time()
    for k in [k for k, v in _send_pending.items() if now - v["ts"] > 3600]:
        _send_pending.pop(k, None)
    token = secrets.token_hex(4)
    _send_pending[token] = {"kind": "shop", "text": None, "target": target, "reply_msg_id": None, "reply_chat_id": None,
                            "group_count": n_groups, "dm_count": n_dms, "ts": now}
    await event.reply(
        "\n".join(lines), parse_mode='html',
        buttons=[[
            colored_button(f"✅ Send to {total}", f"broadcast_go_{token}", color="success"),
            Button.inline("❌ Cancel", data=f"broadcast_no_{token}"),
        ]],
    )

@bot1.on(events.CallbackQuery(pattern=r'^dshop_(\d+)$'))
async def daily_shop_nav_callback(event):
    idx = int(event.pattern_match.group(1))
    shop_doc = await get_daily_shop_doc()
    items = (shop_doc or {}).get("items") or []
    if not items:
        return await event.answer("📭 This shop batch is no longer active.", alert=True)
    idx = idx % len(items)
    item = items[idx]
    char_doc = await characters_base_col.find_one({"char_id": item["char_id"]})
    if not char_doc:
        return await event.answer("⚠️ This card is no longer available.", alert=True)
    caption = _daily_shop_caption(char_doc, item["price"], idx, len(items))
    buttons = await _daily_shop_nav_buttons(idx, len(items), char_doc)

    async def _edit_shop(media):
        return await event.edit(caption, file=media, buttons=buttons, parse_mode='html')

    try:
        result = await send_with_char_media(char_doc["char_id"], char_doc["storage_msg_id"], _edit_shop)
        if result is None:
            return await event.answer("⚠️ Media missing for this one — skipping.", alert=True)
        await event.answer()
    except errors.MessageNotModifiedError:
        await event.answer()
    except Exception:
        # Fallback for the rare case Telegram rejects an in-place media swap — delete and
        # resend fresh instead of getting stuck, same as /show's nav callback.
        try:
            await event.delete()
        except Exception:
            pass

        async def _resend_shop(media):
            return await bot1.send_message(event.chat_id, caption, file=media, buttons=buttons, parse_mode='html')

        await send_with_char_media(char_doc["char_id"], char_doc["storage_msg_id"], _resend_shop)
        await event.answer()

async def handle_buyowner_inline_query(event, query_text):
    """'Buy from OWNER' — a same_peer=False switch_inline button (see _daily_shop_nav_buttons),
    so this fires wherever the buyer picks to send it; the '📢 Owner's Group' button sits right
    next to it as the recommended destination. This is a MANUAL sale, not the automatic /buy
    flow — no VLT moves and no card changes hands here, it just hands the buyer a ready-to-send
    request naming the character and price so the Owner can complete the sale personally."""
    char_id = normalize_char_id_input(query_text[len("buyowner."):])
    char_doc = await characters_base_col.find_one({"char_id": char_id})
    if not char_doc:
        return await event.answer([], cache_time=0)
    shop_doc = await get_daily_shop_doc()
    items = (shop_doc or {}).get("items") or []
    price_item = next((i for i in items if i["char_id"] == char_id), None)
    price_text = f" for {_shop_price_text(price_item['price'])}" if price_item else ""
    owner_username = await get_owner_username()
    owner_tag = f"@{owner_username}" if owner_username else "Owner"
    message_text = (
        f"{owner_tag} — I want to buy <b>{escape_html(char_doc.get('name',''))}</b> "
        f"(ID <code>{display_char_id(char_id)}</code>){price_text}"
    )
    builder = event.builder
    result = builder.article(
        title=f"Buy {char_doc.get('name','this card')}",
        description=f"Sends a purchase request to {owner_tag}",
        text=message_text,
        parse_mode='html',
        id=f"buyowner_{char_id}"
    )
    await event.answer([result], cache_time=0)

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]haii(?:@\w+)?$', 'bot1')))
async def force_spawn_by_owner(event):
    if event.sender_id != OWNER_ID: return
    await trigger_dynamic_spawn(event.chat_id)

# ⚡ PERFORMANCE: spawn_target used to be re-fetched from Mongo (1-2 reads) on literally
# every single group message — the hottest path in the whole bot. It only ever changes
# via an explicit owner command, so cache it and just bust the cache on that one write path.
_spawn_target_cache = bot_state._spawn_target_cache
# 🩹 (2026-10, Render 5 GB/month outbound cap) two fixes here. (1) BotState's 10-minute sweeper reads the 2nd item of every cache tuple …
SPAWN_TARGET_CACHE_TTL = 1800  # seconds

async def get_spawn_target(chat_id):
    cached = _spawn_target_cache.get(chat_id)
    now = time.time()
    if cached and now < cached[1]:
        return cached[0]
    group_config = await groups_config_col.find_one({"chat_id": chat_id})
    if group_config and "spawn_target" in group_config:
        spawn_target = group_config["spawn_target"]
    else:
        global_config = await groups_config_col.find_one({"chat_id": GLOBAL_SPAWN_CHAT_KEY})
        spawn_target = global_config.get("spawn_target", 50) if global_config else 50
    _spawn_target_cache[chat_id] = (spawn_target, now + SPAWN_TARGET_CACHE_TTL)     # (value, EXPIRY time)
    return spawn_target

# ---- AUTOMATIC SPAWN PROCESSOR ----
GROUP_COUNTER_FLUSH_SECONDS = 48
# how often the in-memory spawn counters get batched to Mongo
# 👥 CROWD TRACKER (2026-10, per owner request — rare spawns were dropping even in chats where one person was typing to themselves): the last time each
# person spoke in each group, in memory only (no database traffic). rare_spawn_gate_ok() asks "how many DIFFERENT people spoke here recently?".
RARE_CROWD_WINDOW_SECONDS = int(os.environ.get("RARE_CROWD_WINDOW_MIN", "10")) * 60
_CHAT_RECENT_SPEAKERS = {}      # chat_id -> {user_id: last message ts}

def _note_chat_speaker(chat_id, user_id, now):
    d = _CHAT_RECENT_SPEAKERS.setdefault(chat_id, {})
    d[user_id] = now
    if len(d) > 60:
        for uid in [u for u, t in d.items() if now - t > RARE_CROWD_WINDOW_SECONDS]:
            d.pop(uid, None)
    if len(_CHAT_RECENT_SPEAKERS) > 5000:
        _CHAT_RECENT_SPEAKERS.clear()

def chat_crowd(chat_id):
    now = time.time()
    return sum(1 for t in _CHAT_RECENT_SPEAKERS.get(chat_id, {}).values() if now - t <= RARE_CROWD_WINDOW_SECONDS)

# ==========================================
# 🎯🛡️ CHAT QUALITY for ULTRA / SUPREME (2026-11, per owner request — "ULTRA and Supreme ကို လူစည်းကား active ဖြစ်လွန်းတဲ့ group chat တွေမှာ ပိုမိုကျနိူင်ခြေများအောင်လုပ်ပါ၊
# တမင် လူ လေးငါးယောက်လောက်နဲ့ spamming သေချာလုပ်နေတဲ့ auto farm chat တွေမှာ မကျအောင်သေချာလုပ်ပါ")
# ==========================================
# 🩹 v2 (2026-11, per owner report — "auto farm က group အားလုံးနီးပါးကို block နေခဲ့တယ်၊ တကယ်က user တွေက သူတို့ဘာသာ စာပို့နေကြတာပါ"). What went wrong in v1: a spawn only …
def _env_float_safe(name, default):
    try:
        return float(os.environ.get(name, default))
    except (TypeError, ValueError):
        return float(default)

CHAT_ACTIVITY_TAU = 600.0          # slow window — breadth
CHAT_RATE_TAU = 120.0              # fast window — typing speed
RARE_BOOST_START_SPEAKERS = _env_float_safe("RARE_BOOST_START_SPEAKERS", 6)
RARE_FULL_BOOST_SPEAKERS = max(_env_float_safe("RARE_FULL_BOOST_SPEAKERS", 20), RARE_BOOST_START_SPEAKERS + 1)
RARE_MAX_BOOST = max(1.0, _env_float_safe("RARE_MAX_BOOST", 3.0))
RARE_BOOST_MIN_ACTIVITY = _env_float_safe("RARE_BOOST_MIN_ACTIVITY", 25)
RARE_FARM_MIN_RATE = _env_float_safe("RARE_FARM_MIN_RATE", 25)               # messages per minute, whole chat
RARE_FARM_MAX_EFFECTIVE = _env_float_safe("RARE_FARM_MAX_EFFECTIVE", 6)
RARE_HEAVY_RATE = _env_float_safe("RARE_HEAVY_RATE", 5)                      # messages per minute, ONE account
RARE_HEAVY_SHARE = _env_float_safe("RARE_HEAVY_SHARE", 0.75)
RARE_FARM_STRIKES = max(1, int(_env_float_safe("RARE_FARM_STRIKES", 3)))
RARE_FARM_STRIKE_GAP_SECONDS = _env_float_safe("RARE_FARM_STRIKE_GAP_SECONDS", 240)
RARE_FARM_STRIKE_RESET_SECONDS = _env_float_safe("RARE_FARM_STRIKE_RESET_SECONDS", 1200)
RARE_FARM_BLOCK_SECONDS = int(_env_float_safe("RARE_FARM_BLOCK_HOURS", 6) * 3600)
CHAT_FARM_DM_PER_HOUR = int(_env_float_safe("CHAT_FARM_DM_PER_HOUR", 6))
_CHAT_ACTIVITY = {}        # chat_id -> {user_id: [slow decayed count, fast decayed count, last message ts]}
_RARE_FARM_CHATS = {}      # chat_id -> blocked-until ts   (mirrored in bot_settings_col "rare_farm_chats")
_FARM_STRIKES = {}         # chat_id -> [strikes, ts of the last strike]
_FARM_DM_TIMES = []        # when the Owner was last DM'd about a blocked chat (rate limit)

def _is_bot_command_text(text):
    """'/coll name', '/w', '.coll' — an action aimed at the bot, not conversation. A lone '.' or '...' is NOT a command."""
    t = (text or "").lstrip()
    return len(t) > 1 and t[0] in "/." and t[1].isalpha()

def _note_chat_activity(chat_id, user_id, now):
    d = _CHAT_ACTIVITY.setdefault(chat_id, {})
    rec = d.get(user_id)
    if rec is None:
        d[user_id] = [1.0, 1.0, now]
    else:
        dt = now - rec[2]
        rec[0] = rec[0] * _math.exp(-dt / CHAT_ACTIVITY_TAU) + 1.0
        rec[1] = rec[1] * _math.exp(-dt / CHAT_RATE_TAU) + 1.0
        rec[2] = now
    if len(d) > 150:                                              # forget speakers whose messages have decayed away
        for uid in [u for u, r in d.items() if r[0] * _math.exp(-(now - r[2]) / CHAT_ACTIVITY_TAU) < 0.2]:
            d.pop(uid, None)
    if len(_CHAT_ACTIVITY) > 5000:
        for cid in [c for c, dd in _CHAT_ACTIVITY.items() if not dd or max(r[2] for r in dd.values()) < now - 3600]:
            _CHAT_ACTIVITY.pop(cid, None)
        if len(_CHAT_ACTIVITY) > 5000:
            _CHAT_ACTIVITY.clear()

def chat_quality(chat_id, now=None):
    """The quality read described above. Pure and cheap — safe to call from the spawn path."""
    now = time.time() if now is None else now
    slow, fast = [], []
    for rec in (_CHAT_ACTIVITY.get(chat_id) or {}).values():
        s = rec[0] * _math.exp(-(now - rec[2]) / CHAT_ACTIVITY_TAU)
        f = rec[1] * _math.exp(-(now - rec[2]) / CHAT_RATE_TAU)
        if s >= 0.2:
            slow.append(s)
        if f >= 0.2:
            fast.append(f)
    total = sum(slow)
    effective = (total * total / sum(s * s for s in slow)) if slow else 0.0
    fast_total = sum(fast)
    rate = fast_total / CHAT_RATE_TAU * 60.0                      # messages per minute, whole chat
    fast_effective = (fast_total * fast_total / sum(f * f for f in fast)) if fast else 0.0
    heavy = [f for f in fast if f / CHAT_RATE_TAU * 60.0 >= RARE_HEAVY_RATE]
    heavy_share = (sum(heavy) / fast_total) if fast_total > 0 else 0.0
    looks_farm = rate >= RARE_FARM_MIN_RATE and (
        fast_effective < RARE_FARM_MAX_EFFECTIVE or (len(heavy) >= 3 and heavy_share >= RARE_HEAVY_SHARE))
    farm_until = _RARE_FARM_CHATS.get(chat_id, 0)
    farm_blocked = farm_until > now
    eligible = (not farm_blocked) and (not looks_farm)
    boost = 1.0
    if eligible and total >= RARE_BOOST_MIN_ACTIVITY:
        frac = (effective - RARE_BOOST_START_SPEAKERS) / (RARE_FULL_BOOST_SPEAKERS - RARE_BOOST_START_SPEAKERS)
        boost = 1.0 + (RARE_MAX_BOOST - 1.0) * min(1.0, max(0.0, frac))
    return {"speakers": len(slow), "activity": total, "effective": effective, "rate": rate, "fast_effective": fast_effective,
            "heavy": len(heavy), "heavy_share": heavy_share, "looks_farm": looks_farm, "farm_blocked": farm_blocked,
            "farm_until": farm_until, "eligible": eligible, "boost": boost,
            "strikes": (_FARM_STRIKES.get(chat_id) or [0, 0])[0]}

async def _chat_title(chat_id):
    try:
        ent = await bot1.get_entity(chat_id)
        return getattr(ent, "title", None) or str(chat_id)
    except Exception:
        return str(chat_id)

async def _farm_watch(chat_id, q, now=None):
    """Called on every spawn evaluation. Counts a strike when the chat reads like a farm (at most one per RARE_FARM_STRIKE_GAP_SECONDS), forgives one on a calm reading,
    and blocks the chat once RARE_FARM_STRIKES strikes pile up. Returns True when it has JUST blocked the chat. Never raises."""
    try:
        now = time.time() if now is None else now
        if q["farm_blocked"]:
            return False
        st = _FARM_STRIKES.get(chat_id)
        if st and now - st[1] > RARE_FARM_STRIKE_RESET_SECONDS:
            _FARM_STRIKES.pop(chat_id, None)                      # stale — start over
            st = None
        if not q["looks_farm"]:
            if st:
                st[0] -= 1
                if st[0] <= 0:
                    _FARM_STRIKES.pop(chat_id, None)
            return False
        if st is None:
            st = [1, now]
        elif now - st[1] >= RARE_FARM_STRIKE_GAP_SECONDS:
            st = [st[0] + 1, now]
        _FARM_STRIKES[chat_id] = st
        if st[0] >= RARE_FARM_STRIKES:
            _FARM_STRIKES.pop(chat_id, None)
            await _flag_farm_chat(chat_id, q, now)
            return True
        return False
    except Exception as e:
        print(f"_farm_watch error ({chat_id}): {e}")
        return False

async def _flag_farm_chat(chat_id, q, now=None):
    """Blocks a chat from ULTRA/SUPREME for RARE_FARM_BLOCK_SECONDS, saves it, and (rate-limited) DMs the Owner. Never raises."""
    try:
        now = time.time() if now is None else now
        until = now + RARE_FARM_BLOCK_SECONDS
        _RARE_FARM_CHATS[chat_id] = until
        try:
            await bot_settings_col.update_one({"_id": "rare_farm_chats"}, {"$set": {f"chats.{chat_id}": until}}, upsert=True)
        except Exception as e:
            print(f"farm chat save error ({chat_id}): {e}")
        _FARM_DM_TIMES[:] = [t for t in _FARM_DM_TIMES if now - t < 3600]
        if len(_FARM_DM_TIMES) >= CHAT_FARM_DM_PER_HOUR:
            print(f"🤖 farm chat {chat_id} blocked (owner DM skipped — rate limit; see /farmchats)")
            return
        _FARM_DM_TIMES.append(now)
        title = escape_html(await _chat_title(chat_id))
        why = (f"only {q['fast_effective']:.1f} effective speakers" if q["fast_effective"] < RARE_FARM_MAX_EFFECTIVE
               else f"{q['heavy']} accounts sent {q['heavy_share'] * 100:.0f}% of the messages")
        await bot1.send_message(
            OWNER_ID,
            f"🤖 <b>Auto-farm chat blocked from ULTRA / SUPREME</b>\n"
            f"<b>{title}</b> · <code>{chat_id}</code>\n"
            f"📊 ~{q['rate']:.0f} msgs/min, {q['speakers']} account(s) — {why}, seen on {RARE_FARM_STRIKES} spawns in a row.\n"
            f"⏳ Blocked for {RARE_FARM_BLOCK_SECONDS // 3600}h (normal spawns are unaffected).",
            parse_mode='html')
    except Exception as e:
        print(f"_flag_farm_chat error ({chat_id}): {e}")

async def load_rare_farm_chats():
    """Restores the farm blocks on boot so a restart doesn't hand a farm its drops back — except that the FIRST time v2 runs it wipes whatever v1 saved (v1 blocked almost every chat)."""
    try:
        if not await bot_settings_col.find_one({"_id": "rare_farm_reset_v2"}):
            await bot_settings_col.delete_one({"_id": "rare_farm_chats"})
            await bot_settings_col.update_one({"_id": "rare_farm_reset_v2"}, {"$set": {"at": time.time()}}, upsert=True)
            _RARE_FARM_CHATS.clear()
            print("🤖 Cleared every auto-farm block saved by the first (too strict) version.")
            return
        doc = await bot_settings_col.find_one({"_id": "rare_farm_chats"}) or {}
        now = time.time()
        for cid, until in (doc.get("chats") or {}).items():
            if until and until > now:
                _RARE_FARM_CHATS[int(cid)] = until
        if _RARE_FARM_CHATS:
            print(f"🤖 Restored {len(_RARE_FARM_CHATS)} auto-farm chat block(s).")
    except Exception as e:
        print(f"load_rare_farm_chats error: {e}")

@bot1.on(events.NewMessage(incoming=True))
async def global_message_counter_handler(event):
    if event.is_private or event.chat_id == SPECIFIC_CONTROL_GROUP: return
    if _event_sender_is_bot(event): return          # 🤖 another bot's message (Bot-to-Bot Communication) — not a person chatting: no spawn / trivia progress, no activity
    chat_id = event.chat_id
    _uid = event.sender_id
    if _uid is not None and _uid not in bot_ids:
        if is_spam_muted(_uid):
            return                      # 🛡️ a spam-muted player's messages don't count toward spawns or trivia
        _note_chat_speaker(chat_id, _uid, time.time())
        if not _is_bot_command_text(event.raw_text):          # 🎯 who is REALLY carrying the chat — see CHAT QUALITY (/coll, /w … are actions, not conversation)
            _note_chat_activity(chat_id, _uid, time.time())

    # 🛡️ Tiny groups (see MIN_GROUP_MEMBERS_FOR_SPAWN) no longer get blocked outright — they …
    member_count = get_cached_group_member_count_nowait(chat_id)
    if member_count is None:
        schedule_group_member_count_refresh(chat_id)
    is_small_group = member_count is not None and member_count < MIN_GROUP_MEMBERS_FOR_SPAWN

    # 🧠 TRIVIA AUTO-SPAWN — deliberately checked FIRST and kept fully independent of the
    # character-spawn counter below: it ticks on every group message regardless of whether a
    # character spawn or rarity-gate quiz is currently active in this chat, and is only ever
    # paused by its own pending_trivia_quiz (so a chat never gets two trivia prompts stacked on
    # top of each other). In-memory only, no Mongo persistence — a restart just costs at most
    # one trivia chat's worth of progress toward its next question, never anything durable.
    if _cached_trivia_enabled and chat_id not in pending_trivia_quiz:
        trivia_target = get_trivia_target(chat_id)
        new_trivia_count = trivia_spawn_counters.get(chat_id, 0) + 1
        if new_trivia_count >= trivia_target:
            trivia_spawn_counters[chat_id] = 0
            trivia_spawn_targets.pop(chat_id, None)
            asyncio.create_task(trigger_trivia_spawn(chat_id))
        else:
            trivia_spawn_counters[chat_id] = new_trivia_count

    if chat_id in active_group_spawns or chat_id in pending_rarity_quiz: return
    spawn_target = await get_spawn_target(chat_id)
    if is_small_group:
        # 🩹 CHANGED (2026-08, per owner request): tiny groups used to be blocked from
        # spawning entirely — now they just need double the normal haitime/spawn_target
        # (e.g. haitime 100 → 200 messages for these groups) instead of being shut off.
        spawn_target *= 2
    # ⚡ PERFORMANCE: this used to be a MongoDB find_one_and_update on EVERY single group …
    new_count = group_spawn_counters.get(chat_id, 0) + 1
    group_spawn_counters[chat_id] = new_count
    if new_count >= spawn_target:
        # 🛡️ RELIABILITY: subtract spawn_target instead of hard-resetting to 0, so any
        # "overshoot" from the threshold check never silently disappears (same reasoning as
        # the old Mongo $inc version — just applied to the in-memory value now).
        group_spawn_counters[chat_id] = new_count - spawn_target
        try:
            await groups_counters_col.update_one(
                {"chat_id": chat_id},
                {"$set": {"counter": group_spawn_counters[chat_id]}},
                upsert=True
            )
            _flushed_group_counters[chat_id] = group_spawn_counters[chat_id]
        except Exception as e:
            logging.error(f"Group counter persist-on-spawn error: {e}")
        await trigger_dynamic_spawn(chat_id)

async def load_group_spawn_counters_cache():
    """One-time load of persisted spawn counters into memory on boot, so a restart doesn't
    reset every group's progress back to 0 — only whatever hadn't been flushed yet (at most
    ~GROUP_COUNTER_FLUSH_SECONDS worth) is at risk."""
    try:
        docs = await groups_counters_col.find({}, {"chat_id": 1, "counter": 1}).to_list(length=None)
        for d in docs:
            group_spawn_counters[d["chat_id"]] = d.get("counter", 0)
            _flushed_group_counters[d["chat_id"]] = d.get("counter", 0)
        print(f"📥 Loaded {len(docs)} group spawn counters into memory.")
    except Exception as e:
        print(f"load_group_spawn_counters_cache error: {e}")

_flushed_group_counters = {}      # chat_id -> last value written to Mongo, so unchanged counters are never re-sent

async def group_counter_flush_loop():
    """Batches every group's in-memory spawn counter to Mongo in a single bulk_write every
    GROUP_COUNTER_FLUSH_SECONDS — this is the ONLY place (besides the on-spawn write above)
    that persists group_spawn_counters, replacing what used to be a write on every message."""
    while True:
        await asyncio.sleep(GROUP_COUNTER_FLUSH_SECONDS)
        try:
            # 🩹 (2026-10, Render 5 GB/month outbound cap) used to re-send EVERY group's counter every 48 s, changed or not —
            # for hundreds of mostly-quiet groups that is the same bytes over and over, all day. Now only counters whose value
            # moved since the last flush are written; a quiet group costs nothing.
            snapshot = {cid: val for cid, val in group_spawn_counters.items() if _flushed_group_counters.get(cid) != val}
            if not snapshot:
                continue
            ops = [
                UpdateOne({"chat_id": cid}, {"$set": {"counter": val}}, upsert=True)
                for cid, val in snapshot.items()
            ]
            await groups_counters_col.bulk_write(ops, ordered=False)
            _flushed_group_counters.update(snapshot)
        except Exception as e:
            logging.error(f"Group counter flush error: {e}")

def get_trivia_target(chat_id):
    """Next message-count threshold before this chat's next trivia auto-spawn — a fresh random
    value between TRIVIA_SPAWN_MIN_MSGS and TRIVIA_SPAWN_MAX_MSGS, rolled once and cached in
    trivia_spawn_targets until the trivia actually fires (then trigger_trivia_spawn's caller
    pops it so a new random target gets rolled for the next cycle). In-memory only, same
    reasoning as group_spawn_counters — worst case on a restart is losing progress toward the
    next question, never anything durable."""
    target = trivia_spawn_targets.get(chat_id)
    if target is None:
        target = random.randint(TRIVIA_SPAWN_MIN_MSGS, TRIVIA_SPAWN_MAX_MSGS)
        trivia_spawn_targets[chat_id] = target
    return target

# ==========================================
# 🔒 DAILY SPAWN CAP for ULTRA + SUPREME (2026-10, per owner request — "Ultra, Supreme new and old တွေကို များစွာ spawn …
# ==========================================
RARE_SPAWN_DAILY_CAPS = {
    RARITY_TIERS[0]: int(os.environ.get("ULTRA_DAILY_SPAWN_CAP", "3")),     # ULTRA   (Rarity No.1)
    RARITY_TIERS[1]: int(os.environ.get("SUPREME_DAILY_SPAWN_CAP", "6")),   # SUPREME (Rarity No.2, internal tier LEGEND)
}

# 😴 REST DAYS (2026-10, per owner request — "နေ့တိုင်း ultra နဲ့ supreme ကို spawn မနေနဲ့၊ တန်ဖိုးတွေလျော့တယ်"): the daily cap alone still let …
RARE_SPAWN_EVERY_N_DAYS = {
    RARITY_TIERS[0]: max(1, int(os.environ.get("ULTRA_SPAWN_EVERY_N_DAYS", "1"))),
    RARITY_TIERS[1]: max(1, int(os.environ.get("SUPREME_SPAWN_EVERY_N_DAYS", "1"))),
}
RARE_SPAWN_DAY_OFFSET = {RARITY_TIERS[0]: 0, RARITY_TIERS[1]: 1}

def rare_tier_open_on(tier, day):
    """True if `tier` may spawn on `day` ('YYYY-MM-DD', Yangon). Tiers with no rest-day rule are always open."""
    n = RARE_SPAWN_EVERY_N_DAYS.get(tier, 1)
    if n <= 1:
        return True
    try:
        ordinal = datetime.strptime(day, "%Y-%m-%d").date().toordinal()
    except Exception:
        return True
    return (ordinal + RARE_SPAWN_DAY_OFFSET.get(tier, 0)) % n == 0

def _rare_spawn_day(now=None):
    return (now or datetime.now(TZ)).strftime("%Y-%m-%d")

def _rare_spawn_doc_id(day):
    return f"rare_spawns_{day}"

# 🎯 RARE SPAWN TARGETING (2026-10, per owner request — "Supreme 6 / Ultra 3 က ကျမယ့်နေ့ဆို ဆက်တိုက်ကျတာ မကြိုက်ဘူး၊ လူစည်ကားတဲ့ညဘက်ကို ပိုtarget ဖြစ်စေချင်တယ်၊ …
RARE_MIN_CHAT_USERS = int(os.environ.get("RARE_MIN_CHAT_USERS", "3"))
RARE_PEAK_START_HOUR = int(os.environ.get("RARE_PEAK_START_HOUR", "19"))
RARE_PEAK_END_HOUR = int(os.environ.get("RARE_PEAK_END_HOUR", "24"))
RARE_OFFPEAK_CHANCE = float(os.environ.get("RARE_OFFPEAK_CHANCE", "0.15"))
RARE_MIN_GAP_SECONDS = {
    RARITY_TIERS[0]: int(os.environ.get("ULTRA_MIN_GAP_MIN", "90")) * 60,
    RARITY_TIERS[1]: int(os.environ.get("SUPREME_MIN_GAP_MIN", "40")) * 60,
}

def rare_spawn_gate_ok(chat_id, hour=None, crowd=None, quality=None):
    """Quality + crowd + peak-hour check for an ULTRA/SUPREME drop in this chat (the spacing is checked in reserve_rare_spawn_slot).
    🎯 2026-11: the chat must also pass chat_quality() — real, broad activity and not an auto-farm — and a busier chat gets a proportionally better off-peak chance."""
    q = quality if quality is not None else chat_quality(chat_id)
    if not q["eligible"]:
        return False
    if (chat_crowd(chat_id) if crowd is None else crowd) < RARE_MIN_CHAT_USERS:
        return False
    h = datetime.now(TZ).hour if hour is None else hour
    if RARE_PEAK_START_HOUR <= h < RARE_PEAK_END_HOUR:
        return True
    return random.random() < min(1.0, RARE_OFFPEAK_CHANCE * q["boost"])

def rare_cap_tier(char):
    """ULTRA / LEGEND(=SUPREME) if this card belongs to a daily-capped tier, else None. Looks at BOTH the stored
    rarity_tier and the rarity string, so an old card whose stored tier is stale or missing is still caught."""
    for t in (char.get("rarity_tier"), classify_rarity(char.get("rarity", ""))):
        if t in RARE_SPAWN_DAILY_CAPS:
            return t
    return None

async def get_rare_spawn_counts(day=None):
    """{tier: spawns so far} for a day (default today) — 0 for a tier with none."""
    doc = await bot_settings_col.find_one({"_id": _rare_spawn_doc_id(day or _rare_spawn_day())}) or {}
    return {t: int(doc.get(t, 0) or 0) for t in RARE_SPAWN_DAILY_CAPS}

async def rare_spawn_tiers_at_cap():
    """Tiers that already used up today's cap. On a DB error nothing is reported as capped here — the atomic
    reserve_rare_spawn_slot() below is the real gatekeeper and fails CLOSED."""
    today = _rare_spawn_day()
    closed = {t for t in RARE_SPAWN_DAILY_CAPS if not rare_tier_open_on(t, today)}     # 😴 rest day = same as "cap used up"
    try:
        doc = await bot_settings_col.find_one({"_id": _rare_spawn_doc_id(today)}) or {}
        now = time.time()
        for t, cap in RARE_SPAWN_DAILY_CAPS.items():
            if int(doc.get(t, 0) or 0) >= cap or now - float(doc.get(f"{t}_last", 0) or 0) < RARE_MIN_GAP_SECONDS.get(t, 0):
                closed.add(t)                                   # cap used up, OR still inside the spacing since the last one
        return closed
    except Exception as e:
        print(f"rare_spawn_tiers_at_cap error: {e}")
        return closed

async def reserve_rare_spawn_slot(tier):
    """Atomically takes one of today's slots for `tier`. Returns the day key the slot belongs to (needed to give it
    back later), or None when the cap is reached — or when the database can't be reached (fails closed: better to
    skip an ULTRA spawn than to break the cap)."""
    cap = RARE_SPAWN_DAILY_CAPS.get(tier)
    if cap is None:
        return _rare_spawn_day(), 0.0
    from pymongo.errors import DuplicateKeyError
    day = _rare_spawn_day()
    if not rare_tier_open_on(tier, day):          # 😴 rest day — the atomic gate refuses too, not just the pre-filter
        return None
    doc_id = _rare_spawn_doc_id(day)
    try:
        try:
            await bot_settings_col.update_one({"_id": doc_id}, {"$setOnInsert": {"date": day}}, upsert=True)
        except DuplicateKeyError:
            pass                                            # two first-of-the-day callers raced — the doc exists now
        from pymongo import ReturnDocument
        now = time.time()
        gap = RARE_MIN_GAP_SECONDS.get(tier, 0)
        before = await bot_settings_col.find_one_and_update(
            {"_id": doc_id, "$and": [
                {"$or": [{tier: {"$exists": False}}, {tier: {"$lt": cap}}]},                              # daily cap not reached
                {"$or": [{f"{tier}_last": {"$exists": False}}, {f"{tier}_last": {"$lte": now - gap}}]},   # and spaced from the previous one
            ]},
            {"$inc": {tier: 1}, "$set": {f"{tier}_last": now}},
            return_document=ReturnDocument.BEFORE
        )
        if before is None:
            return None
        return day, float(before.get(f"{tier}_last", 0) or 0)       # (day, previous spawn time — needed to hand the spacing back on a refund)
    except Exception as e:
        print(f"reserve_rare_spawn_slot error ({tier}): {e}")
        return None

async def refund_rare_spawn_slot(tier, day, prev_last=0.0):
    """Gives a reserved slot back (a pick that never turned into a real spawn) — and the spacing with it."""
    if tier not in RARE_SPAWN_DAILY_CAPS or not day:
        return
    try:
        await bot_settings_col.update_one({"_id": _rare_spawn_doc_id(day), tier: {"$gt": 0}},
                                          {"$inc": {tier: -1}, "$set": {f"{tier}_last": prev_last}})
    except Exception as e:
        print(f"refund_rare_spawn_slot error ({tier}): {e}")

async def refund_gate_slot(quiz):
    """Gives back the daily slot held by a Rarity Gate quiz that will never release its spawn."""
    slot = quiz.get("slot") if quiz else None
    if slot:
        quiz["slot"] = None                                 # never refund the same slot twice
        await refund_rare_spawn_slot(*slot)

async def rare_spawn_counts_line():
    """'🥇 ULTRA 2/3 · 🪞 SUPREME 5/6' for today — used in the storage-group catch log."""
    counts = await get_rare_spawn_counts()
    return " · ".join(f"{RARITY_EMOJI.get(t, RARITY_DEFAULT_EMOJI)} {RARITY_DISPLAY_NAME.get(t, t)} {counts[t]}/{RARE_SPAWN_DAILY_CAPS[t]}"
                      for t in RARE_SPAWN_DAILY_CAPS)

async def log_rare_catch_to_storage(chat_id, user_id, spawn_data, mention, tier, catcher_total):
    """📋 (2026-10, per owner request) every ULTRA / SUPREME card that gets collected is written up in the storage group
    (SPECIFIC_CONTROL_GROUP): WHICH chat, WHICH card, WHO collected it — plus when, how fast, and how many of the day's slots
    are used — so the Owner always knows where these cards go. Fire-and-forget: a failure here only prints, it can never
    touch the player's catch."""
    try:
        char_id = spawn_data.get("char_id")
        char_doc = await characters_base_col.find_one({"char_id": char_id}, {"_id": 0, "event_no": 1, "custom_event_no": 1, "custom_event": 1, "spawn_count": 1, "spawn_limit": 1, "category": 1}) or {}
        # ---- the chat
        title = uname = None
        try:
            ent = await bot1.get_entity(chat_id)
            title, uname = getattr(ent, "title", None), getattr(ent, "username", None)
        except Exception:
            pass
        msg_id = spawn_data.get("spawn_msg_id")
        link = None
        if msg_id:
            if uname:
                link = f"https://t.me/{uname}/{msg_id}"
            elif str(chat_id).startswith("-100"):
                link = f"https://t.me/c/{str(chat_id)[4:]}/{msg_id}"
        chat_line = f"<b>{escape_html(title or 'Unknown chat')}</b>" + (f" (@{escape_html(uname)})" if uname else "")
        chat_line += f"\n🆔 <code>{chat_id}</code>" + (f" · <a href='{link}'>spawn message</a>" if link else "")
        # ---- the collector
        c_user = None
        try:
            ent_u = await bot1.get_entity(user_id)
            c_user = getattr(ent_u, "username", None)
        except Exception:
            pass
        # ---- the card
        emoji = RARITY_EMOJI.get(tier, RARITY_DEFAULT_EMOJI)
        ev = " | ".join(x for x in (event_label_of(char_doc), custom_event_label_of(char_doc)) if x)
        limit = char_doc.get("spawn_limit")
        catches = f"{char_doc.get('spawn_count', 0)}/{limit}" if limit else f"{char_doc.get('spawn_count', 0)}/♾️"
        took = ""
        if spawn_data.get("spawn_time"):
            took = f"\n⏱ <b>Collected after:</b> <code>{max(0, int(time.time() - spawn_data['spawn_time']))}s</code>"
        gate = f"\n🔐 <b>Gate solved by:</b> {spawn_data['gate_winner']}" if spawn_data.get("gate_winner") else ""
        text = (
            f"{emoji} <b>{escape_html(RARITY_DISPLAY_NAME.get(tier, tier))} COLLECTED</b>\n"
            f"━━━━━━━━━━━━━━━━━━━━\n"
            f"🫧 <b>Card:</b> {escape_html(str(spawn_data.get('name', '?')))} | <code>{escape_html(str(display_char_id(char_id)))}</code>\n"
            f"🏖️ <b>Series:</b> {escape_html(str(char_doc.get('category') or spawn_data.get('category') or '?'))}\n"
            f"{emoji} <b>Rarity:</b> {escape_html(strip_rarity_number(str(spawn_data.get('rarity', tier))))}\n"
            + (f"🎪 <b>Event:</b> {escape_html(ev)}\n" if ev else "")
            + f"🔁 <b>Card catches:</b> <code>{catches}</code>\n\n"
            f"💬 <b>Chat:</b> {chat_line}\n\n"
            f"👤 <b>Collected by:</b> {mention}" + (f" (@{escape_html(c_user)})" if c_user else "") + "\n"
            f"🆔 <b>User ID:</b> <code>{user_id}</code>\n"
            f"🎒 <b>Collector total cards:</b> <code>{catcher_total}</code>"
            f"{took}{gate}\n"
            f"🕒 <b>Time:</b> <code>{datetime.now(TZ).strftime('%Y-%m-%d %H:%M:%S')}</code> (Yangon)\n"
            f"📊 <b>Today's spawns:</b> {await rare_spawn_counts_line()}"
        )
        await send_safe_message(bot1, SPECIFIC_CONTROL_GROUP, text, parse_mode='html', link_preview=False)
    except Exception as e:
        print(f"log_rare_catch_to_storage error: {e}")

# ---- TRIGGER DYNAMIC SPAWN ----
async def trigger_dynamic_spawn(chat_id):
    if chat_id in active_group_spawns or chat_id in pending_rarity_quiz: return
    # 🔒 Two messages can cross the spawn_target threshold within milliseconds of each other —
    # both would pass the check above since neither active_group_spawns nor pending_rarity_quiz
    # has been written yet. Serialize on the same per-chat lock the quiz-solve callback already
    # uses, and re-check once inside it, so only the first caller actually spawns anything.
    async with spawn_locks[chat_id]:
        if chat_id in active_group_spawns or chat_id in pending_rarity_quiz: return
        try:
            characters_list = await get_all_characters_cached()
            if not characters_list: return
            eligible_characters = []
            for char in characters_list:
                limit = char.get("spawn_limit", 0)
                # spawn_count now represents number of catches, so compare against limit —
                # this is what makes an individual ULTRA character (or any other capped
                # character) stop spawning once IT specifically hits its own cap; see the
                # ULTRA SCARCITY CAP note near ULTRA_DEFAULT_CATCH_LIMIT above.
                if limit and limit > 0 and char.get("spawn_count", 0) >= limit:
                    continue
                eligible_characters.append(char)
            if not eligible_characters:
                return
            # 🔒 Daily cap (ULTRA 3 / SUPREME 6): a tier that already used up today's slots drops out of the draw.
            _capped_now = await rare_spawn_tiers_at_cap()
            _quality = chat_quality(chat_id)
            if await _farm_watch(chat_id, _quality):                 # 🤖 the same farm pattern on RARE_FARM_STRIKES spawns in a row: blocked from ULTRA/SUPREME for hours, Owner told
                _quality = chat_quality(chat_id)
            if not rare_spawn_gate_ok(chat_id, quality=_quality):    # 🎯 not busy/broad enough, an auto-farm, or not the busy hours -> no ULTRA or SUPREME here, now
                _capped_now = set(_capped_now) | set(RARE_SPAWN_DAILY_CAPS)
            if _capped_now:
                eligible_characters = [c for c in eligible_characters if rare_cap_tier(c) not in _capped_now]
                if not eligible_characters:
                    return
            # ⚖️ Configurable via /spawnweight (groups 1-3 / 4-6 / 7-9); falls back to
            # DEFAULT_RARITY_WEIGHTS for any group left unset.
            RARITY_WEIGHTS = get_effective_rarity_weights()

            # 🩹 NEW (owner report — "old /addchar characters keep spawning almost always, …
            now_ts = time.time()
            # 🛡️ RELIABILITY: a character whose storage media has gone missing (deleted from …
            candidates = list(eligible_characters)
            max_attempts = min(5, len(candidates))
            attempt = 0
            while candidates and attempt < max_attempts:
                # ⚖️ tier-first + catch-fair (see FAIR SPAWN SELECTION) — recomputed each attempt because
                # `candidates` shrinks when a pick fails.
                weights = spawn_card_weights(candidates, RARITY_WEIGHTS, now_ts)
                if _quality["boost"] > 1.0:                           # 🚀 a genuinely busy chat gets a better shot at ULTRA / SUPREME (the daily caps still apply)
                    weights = [w * (_quality["boost"] if rare_cap_tier(c) else 1.0) for w, c in zip(weights, candidates)]
                chosen_char = random.choices(candidates, weights=weights, k=1)[0]
                tier = chosen_char.get("rarity_tier") or classify_rarity(chosen_char.get("rarity", ""))
                # 🔒 ULTRA / SUPREME: take one of today's slots NOW (atomic, before any quiz is posted). If the cap was
                # reached in the meantime (another group got there first) the whole tier is dropped and we simply draw
                # again — that is not counted as a failed attempt.
                cap_tier = rare_cap_tier(chosen_char)
                slot = None
                if cap_tier:
                    reserved = await reserve_rare_spawn_slot(cap_tier)
                    if reserved is None:
                        candidates = [c for c in candidates if rare_cap_tier(c) != cap_tier]
                        continue
                    slot = (cap_tier, reserved[0], reserved[1])
                attempt += 1
                if tier in RARITY_GATE_TIERS:
                    # Rarity No.1-4 — don't spawn directly, gate it behind a quiz first.
                    ok = await start_rarity_gate_quiz(chat_id, chosen_char, slot=slot)
                    if not ok:
                        # Quiz couldn't be posted (e.g. no quiz questions configured) — release
                        # directly rather than silently stalling the whole group.
                        ok = await release_spawn(chat_id, chosen_char)
                else:
                    ok = await release_spawn(chat_id, chosen_char)
                if ok:
                    return
                if slot:                                    # the pick never became a spawn — give the slot back
                    await refund_rare_spawn_slot(*slot)
                candidates = [c for c in candidates if c["char_id"] != chosen_char["char_id"]]
                if not candidates:
                    break
            print(f"⚠️ Spawn Reliability: exhausted {max_attempts} attempt(s) in chat {chat_id} without a usable character.")
        except Exception as e:
            print(f"Spawn Error Tracker: {e}")

# ==========================================
# 🆕 (2026-11, per owner request — "Spawn message မှာ စာကိုပြောင်းပါ၊ font က အကုန်အကြီးကိုမှ အရွယ်သေးတာနဲ့") the spawn card's three lines have NEW wording, still in the …
# ==========================================
SPAWN_TITLE_LINES = [
    "a wild character just showed up",
    "a new character has arrived in the chat",
    "someone new slipped into this chat",
    "a mystery character is up for grabs",
    "a character just popped into the chat",
]
SPAWN_REPLY_LINES = [
    "reply {cmd} to this card",
    "send {cmd} as a reply to this card",
    "hit reply on this card and send {cmd}",
]
SPAWN_CATCH_LINES = [
    "then {cmd}",
    "then catch it with {cmd}",
    "and finish with {cmd}",
]

def _spawn_small_caps_line(template, cmd_html):
    """'reply {cmd} to this card' -> small-caps words around the <code> command (the command itself stays plain so a tap copies it)."""
    before, _, after = template.partition("{cmd}")
    return f"{small_caps_full(before)}{cmd_html}{small_caps_full(after)}"

async def release_spawn(chat_id, chosen_char, gate_winner_mention=None, gate_reward_vlt=None):
    """Posts the spawn message and opens the /who window for chosen_char (normal or solved-gate spawns); returns True on success, False if it couldn't post. gate_winner_mention/gate_reward_vlt add a 'Solved by X +NVLT' caption line; leave both None for ungated spawns."""
    if chat_id in active_group_spawns: return False
    try:
        # Do NOT increment spawn_count here; it will be incremented on successful catch.
        rarity_display = chosen_char.get("rarity", "Unknown")
        rarity_tier = classify_rarity(rarity_display)
        rarity_emoji = RARITY_EMOJI.get(rarity_tier, RARITY_DEFAULT_EMOJI)
        artist_raw = chosen_char.get("artist")
        artist_display = escape_html(str(artist_raw).strip()) if artist_raw and str(artist_raw).strip() else "-"
        # Spelled out step-by-step on purpose — players were missing that /who has to be a …
        spawn_text = (
            f"{rarity_emoji} ⋆ {small_caps_full(random.choice(SPAWN_TITLE_LINES))} ✨\n"
            f"⇩ {_spawn_small_caps_line(random.choice(SPAWN_REPLY_LINES), '<code>/w</code>')}\n"
            f"⇩ {_spawn_small_caps_line(random.choice(SPAWN_CATCH_LINES), '<code>/coll [name]</code>')} 🐇\n"
        )
        if is_ultra_card(chosen_char):
            spawn_text += f"\n{ultra_credit_line(chosen_char)}"      # 🎬 video-editor credit on every ULTRA spawn
        if gate_winner_mention:
            # 🩹 NEW (2026-09, per owner request): the Rarity Gate's "who solved it + what they
            # got" now lives HERE, on the spawn it unlocked, instead of a separate message.
            spawn_text += f"\n🔐 {small_caps_full('solved by')}: {gate_winner_mention}　💠 +{format_vlt_plain(gate_reward_vlt)}VLT\n"

        # 🩹 FIX (per owner report — "first person doesn't get it, last person does"): this …
        active_group_spawns[chat_id] = {
            "spawn_msg_id": None,
            "char_id": chosen_char["char_id"],
            "name": chosen_char["name"],
            "category": chosen_char["category"],
            "value": chosen_char["currency_value"],
            "rarity": rarity_display,
            "artist": chosen_char.get("artist"),
            "spawn_time": time.time(),
            "revealed": False,
            "claimed": False,
            "gate_winner": gate_winner_mention      # None for an ungated spawn — only used by the storage-group catch log
        }

        _exl_spawn_buttons = await exclusive_showcase_buttons()      # 🧣 Exclusive Limited showcase button (None until a card exists)

        async def _post_spawn(media):
            return await bot1.send_message(chat_id, spawn_text, parse_mode='html', file=media, buttons=_exl_spawn_buttons)

        spawn_msg = await send_with_char_media(chosen_char["char_id"], chosen_char["storage_msg_id"], _post_spawn)
        print(f"🎴 spawn posted by bot1 in {chat_id}")
        if spawn_msg is None:
            print(f"⚠️ Spawn Reliability: storage media missing for {chosen_char.get('char_id')} — skipping.")
            active_group_spawns.pop(chat_id, None)  # roll back the placeholder so a retry can proceed
            return False

        active_group_spawns[chat_id]["spawn_msg_id"] = spawn_msg.id
        asyncio.create_task(_chat_daily_bump(chat_id))            # 📊 per-chat daily spawn tally (/limitaudit)
        # 🆕 A new spawn is live now — the previous "who caught it last" record is obsolete.
        last_caught_spawns.pop(chat_id, None)
        return True
    except Exception as e:
        print(f"Spawn Error Tracker: {e}")
        active_group_spawns.pop(chat_id, None)  # never leave a half-set entry behind on error
        return False


# ---- RARITY GATE QUIZ (No.1 / No.2 only) ----

async def start_rarity_gate_quiz(chat_id, chosen_char, slot=None, redrop=False, blocked_users=None):
    """Posts the Rarity Gate for a Rarity 1-4 pick: 4 numbers from RARITY_GATE_NUMBER_POOL shown as the button labels (full number only on the button, masked hints in the text); one is secretly correct (random correct_index) and unlocks release_spawn(). One tap per person."""
    try:
        numbers = random.sample(RARITY_GATE_NUMBER_POOL, 4)
        correct_index = random.randint(0, 3)

        # 🩹 CHANGED (2026-09, per owner request): strip_rarity_number() drops the trailing …
        rarity_display = strip_rarity_number(str(chosen_char.get("rarity", "Unknown")))
        # 🩹 CHANGED (2026-09, per owner request): the correct slot's hint reveals 2-3 digits
        # (a real, usable clue); the 3 wrong slots reveal only 1 each. See
        # _rarity_gate_mask_hint's docstring — this asymmetry is intentional, not a bug.
        hint_lines = "\n".join(
            f"{i + 1}️⃣ <code>{_rarity_gate_mask_hint(numbers[i], reveal_count=random.choice([2, 3]) if i == correct_index else 1)}</code>"
            for i in range(4)
        )
        quiz_text = (
            f"🔐 {sans_bold_italic('Rarity Gate')} 🔐\n"
            f"   {small_caps_full('prove yourself to unlock the spawn')}\n"
            + ("🔁 <i>Re-dropped on purpose — the last gate was answered wrong. This is the one and only retry.</i>\n"
               "🔁 <i>တမင်ပြန်ချပေးထားတာပါ — ဒါက နောက်ဆုံး တစ်ကြိမ်ပဲ ရပါမယ်။</i>\n" if redrop else "")
            + f"\n"
            f"{f('RARITY')}: {escape_html(rarity_display)}\n\n"
            f"        🎲 <b>အောက်က ၄ ခုထဲက တစ်ခုကို နှိပ်ပါ</b>\n\n"
            f"{hint_lines}\n\n"
            f"⏱ {small_caps_full('time')}: {RARITY_GATE_TIMEOUT_SECONDS}s\n"
            f"🎯 {small_caps_full('first correct tap unlocks the spawn!')}\n"
            f"⚠️ {small_caps_full('one wrong tap cancels the spawn for everyone')}"
        )
        buttons = [
            [Button.inline(numbers[0], data=f"rgate_{chat_id}_0"), Button.inline(numbers[1], data=f"rgate_{chat_id}_1")],
            [Button.inline(numbers[2], data=f"rgate_{chat_id}_2"), Button.inline(numbers[3], data=f"rgate_{chat_id}_3")],
        ]
        sent = await bot1.send_message(chat_id, quiz_text, buttons=buttons, parse_mode='html')

        pending_rarity_quiz[chat_id] = {
            "char": chosen_char,
            "numbers": numbers,
            "correct_index": correct_index,
            "msg_id": sent.id,
            "quiz_time": time.time(),
            "solved": False,
            "attempted_users": set(blocked_users or ()),     # a re-drop carries over who already tapped (and wrongly) — no second go for them
            "redrop_used": bool(redrop),                     # True = this gate IS the one re-drop; a wrong tap on it is final
            "slot": slot,       # (tier, day) of the ULTRA/SUPREME daily slot this gate is holding, or None
        }
        asyncio.create_task(rarity_gate_quiz_timeout_watcher(chat_id, sent.id))
        return True
    except Exception as e:
        print(f"Rarity Gate Quiz Error: {e}")
        return False

async def _redrop_rarity_gate(chat_id, old_quiz):
    """Puts the SAME card's Rarity Gate up again, once, RARITY_GATE_REDROP_DELAY_SECONDS after a wrong tap closed it (see RARITY_GATE_REDROP_TIERS)."""
    try:
        await asyncio.sleep(min(RARITY_GATE_REDROP_DELAY_SECONDS, 9))
        async with spawn_locks[chat_id]:                  # same per-chat lock trigger_dynamic_spawn holds while it posts a gate
            if chat_id in active_group_spawns or chat_id in pending_rarity_quiz:
                return                                    # something else already took this chat during the pause — leave it alone
            ok = await start_rarity_gate_quiz(chat_id, old_quiz["char"], slot=None, redrop=True,
                                              blocked_users=old_quiz.get("attempted_users"))
            if not ok:
                print(f"⚠️ Rarity Gate re-drop could not be posted in chat {chat_id}.")
    except Exception as e:
        print(f"Rarity Gate re-drop error in chat {chat_id}: {e}")

@bot1.on(events.CallbackQuery(pattern=r'^rgate_(-?\d+)_(\d)$'))
async def rarity_gate_answer_callback(event):
    chat_id = int(event.pattern_match.group(1))
    chosen_idx = int(event.pattern_match.group(2))
    quiz = pending_rarity_quiz.get(chat_id)
    if not quiz or quiz.get("solved"):
        return await event.answer("⌛ This gate is already closed.", alert=True)
    if time.time() - quiz["quiz_time"] > RARITY_GATE_TIMEOUT_SECONDS:
        return await event.answer("⌛ Time's up already!", alert=True)
    # 🔒 One attempt per person, no retries — check-and-mark with no await between them so
    # a user double-tapping can't sneak in a second try.
    attempted_users = quiz.setdefault("attempted_users", set())
    if event.sender_id in attempted_users:
        return await event.answer("⚠️ You already used your one attempt on this gate.", alert=True)
    attempted_users.add(event.sender_id)
    if chosen_idx != quiz["correct_index"]:
        # 🩹 CHANGED AGAIN (2026-10, per owner request — "မှားဖြေလည်း မှန်အောင်ဖြေတဲ့ထိ စောင့်နေတာဖျက်မယ်"): ONE wrong tap now closes the gate …
        async with spawn_locks[chat_id]:
            quiz = pending_rarity_quiz.get(chat_id)
            if not quiz or quiz.get("solved"):
                return await event.answer("⌛ This gate is already closed.", alert=True)
            quiz["solved"] = True
            if pending_rarity_quiz.get(chat_id) is quiz:
                del pending_rarity_quiz[chat_id]
        await refund_gate_slot(quiz)        # no spawn happened — an ULTRA/SUPREME daily slot goes back, so trolling can't burn the cap
        # 🔁 CROSSVERSE / DIVINE: this gate comes back ONCE, within 10 seconds, on purpose (see RARITY_GATE_REDROP_TIERS).
        _gate_tier = quiz["char"].get("rarity_tier") or classify_rarity(quiz["char"].get("rarity", ""))
        _will_redrop = _gate_tier in RARITY_GATE_REDROP_TIERS and not quiz.get("redrop_used")
        if _will_redrop:
            asyncio.create_task(_redrop_rarity_gate(chat_id, quiz))
        # 📨 (2026-11, per owner request) the failed-gate message now NAMES whoever tapped wrong and offers a Report to Bot Owner button — see
        # rarity_gate_report_callback. The details are stashed so the owner's alert can say which group / rarity it was.
        try:
            await event.answer(
                "❌ Wrong answer — but a fresh gate will be dropped again within 10 seconds, on purpose." if _will_redrop
                else "❌ Wrong answer — the gate is closed and the spawn is cancelled.", alert=True)
        except Exception:
            pass
        try:
            wrong_mention = await get_html_mention(event, event.sender_id)
        except Exception:
            wrong_mention = f"<code>{event.sender_id}</code>"
        try:
            _fail_chat = await event.get_chat()
            _fail_title = getattr(_fail_chat, "title", None)
        except Exception:
            _fail_title = None
        try:
            _gate_stash_failure(chat_id, quiz["msg_id"], {
                "chat_title": _fail_title, "rarity": strip_rarity_number(str(quiz["char"].get("rarity", "Unknown"))), "ts": time.time(),
            })
        except Exception:
            pass
        try:
            if _will_redrop:
                _tier_name = RARITY_DISPLAY_NAME.get(_gate_tier, _gate_tier)
                _fail_text = (
                    f"❌ {sans_bold_italic('Gate Failed!')}\n"
                    f"{wrong_mention} <i>answered incorrectly.</i>\n\n"
                    f"🔁 <b>Re-drop — done on purpose!</b>\n"
                    f"<i>This is a {escape_html(_tier_name)} card, so the gate is deliberately dropped again, once, within 10 seconds. Get ready!</i>\n\n"
                    f"🔁 <b>တမင်ပြန်ချပေးတာပါ!</b>\n"
                    f"<i>{escape_html(_tier_name)} ကဒ်ဖြစ်လို့ Gate ကို ၁၀ စက္ကန့်အတွင်း တစ်ကြိမ် ပြန်ချပေးပါမယ်။ ပြင်ဆင်ထားကြပါ!</i>"
                )
            else:
                _fail_text = (
                    f"❌ {sans_bold_italic('Gate Failed!')}\n"
                    f"{wrong_mention} <i>answered incorrectly, therefore the spawn will no longer appear.</i>"
                )
            await event.edit(
                _fail_text,
                parse_mode='html',
                buttons=[[Button.inline("📨 Report to Bot Owner", data=f"rgrep_{event.sender_id}_{chat_id}_{quiz['msg_id']}")]]
            )
        except Exception:
            pass
        return
    async with spawn_locks[chat_id]:
        quiz = pending_rarity_quiz.get(chat_id)
        if not quiz or quiz.get("solved"):
            return await event.answer("⌛ Someone already solved it!", alert=True)
        quiz["solved"] = True
        winner_id = event.sender_id
    mention = await get_html_mention(event, winner_id)
    # 🩹 CHANGED (2026-09, per owner request): flat VLT reward (RARITY_GATE_REWARD_VLT) instead …
    try:
        await users_catcher_col.update_one({"user_id": winner_id}, {"$inc": {"vlt_balance": RARITY_GATE_REWARD_VLT}}, upsert=True)
    except Exception as e:
        print(f"Rarity Gate VLT reward error: {e}")
    try:
        await event.edit(f"✅ {sans_bold_italic('Gate Cleared!')}", parse_mode='html', buttons=None)
    except Exception:
        pass
    await event.answer(f"✅ Correct! +{format_vlt_plain(RARITY_GATE_REWARD_VLT)}VLT — releasing the spawn...", alert=True)
    if pending_rarity_quiz.get(chat_id) is quiz:
        del pending_rarity_quiz[chat_id]
    released_ok = await release_spawn(chat_id, quiz["char"], gate_winner_mention=mention, gate_reward_vlt=RARITY_GATE_REWARD_VLT)
    if not released_ok:
        await refund_gate_slot(quiz)        # solved, but the card could not be posted — the daily slot goes back
        try:
            await event.edit(
                f"⚠️ <b>{mention} answered correctly, but that character's media could no longer be found.</b>\n"
                f"<i>No chance was lost — a fresh spawn will come around again soon.</i>",
                parse_mode='html',
                buttons=None
            ) 
        except Exception:
            pass

# ---- 📨 Report to Bot Owner (2026-11, per owner request) -----------------------------------------------------------------------------------------------
# One wrong Rarity Gate tap cancels the spawn for the whole group, so the "Gate Failed!" message now NAMES the person who tapped wrong and carries a
# 📨 Report to Bot Owner button that ANYONE in the group can press. Each failed gate counts at most once (however many people press it, and whoever
# presses it) against the wrong-tapper's tally for that Yangon day, kept in gate_report_col. When a person's tally reaches GATE_REPORT_DAILY_LIMIT, the bot
# posts the full details in the force-sub join group so the Owner can act (a /gwarn hint is included).
GATE_REPORT_DAILY_LIMIT = 3
_gate_fail_info = {}               # (chat_id, msg_id) -> details of a just-failed gate (chat title, rarity, time) — only used to enrich the report
_gate_reported_keys = set()        # incidents already reported by someone in this process (the DB filter below also guards across restarts)

def _gate_stash_failure(chat_id, msg_id, info):
    _gate_fail_info[(chat_id, msg_id)] = info
    if len(_gate_fail_info) > 300:                                # cheap bound — the oldest entries go first
        for k in list(_gate_fail_info)[:100]:
            _gate_fail_info.pop(k, None)

async def _notify_force_sub_group(text):
    """Posts `text` in the force-sub join group via bot1. If it can't post, the Owner gets it
    in a DM instead, so an alert is never silently lost. Returns True when it landed in the group."""
    try:
        await bot1.send_message(FORCE_SUB_CHAT_ID, text, parse_mode='html')
        return True
    except Exception as e:
        print(f"force-sub group notice failed via bot1: {e}")
    try:
        await bot1.send_message(OWNER_ID, "⚠️ <i>(Couldn't post this in the force-sub group — sending it here instead.)</i>\n\n" + text, parse_mode='html')
    except Exception as e:
        print(f"force-sub group notice DM fallback failed: {e}")
    return False

async def _gate_report_alert(event, wrong_uid, doc):
    try:
        mention = await get_html_mention(event, wrong_uid)
    except Exception:
        mention = f"<code>{wrong_uid}</code>"
    incidents = (doc or {}).get("incidents") or []
    count = (doc or {}).get("count", len(incidents))
    lines = [
        "🚨 <b>Rarity Gate — repeated wrong taps</b>",
        f"👤 {mention} (<code>{wrong_uid}</code>)",
        f"📊 <b>{count} reported wrong tap{'s' if count != 1 else ''} today</b> (alert limit: {GATE_REPORT_DAILY_LIMIT})",
        "",
    ]
    for i, inc in enumerate(incidents[-15:], 1):
        try:
            when = datetime.fromtimestamp(inc.get("failed_at") or inc.get("reported_at") or time.time(), TZ).strftime("%H:%M")
        except Exception:
            when = "?"
        lines.append(
            f"{i}. {escape_html(str(inc.get('chat_title') or 'unknown chat'))} (<code>{inc.get('chat_id')}</code>) · "
            f"{escape_html(str(inc.get('rarity') or '—'))} · {when} · reported by <code>{inc.get('reported_by')}</code>"
        )
    lines += ["", f"👮 <a href='tg://user?id={OWNER_ID}'>Owner</a> — to act on it: <code>/gwarn {wrong_uid} gate trolling</code> <i>(also posts your notice in these groups"
        + (f" and pays ⭐ {GWARN_COMPENSATION_STAR:,} compensation" if GWARN_COMPENSATION_STAR > 0 else "") + ")</i>"]
    await _notify_force_sub_group("\n".join(lines))

@bot1.on(events.CallbackQuery(pattern=r'^rgrep_(\d+)_(-?\d+)_(\d+)$'))
async def rarity_gate_report_callback(event):
    wrong_uid = int(event.pattern_match.group(1))
    chat_id = int(event.pattern_match.group(2))
    msg_id = int(event.pattern_match.group(3))
    key = f"{chat_id}:{msg_id}"
    if wrong_uid == OWNER_ID:
        return await event.answer("ℹ️ Nothing to report here.", alert=False)
    if key in _gate_reported_keys:
        return await event.answer("📨 This one was already reported.", alert=False)
    _gate_reported_keys.add(key)                       # claimed synchronously — two near-simultaneous taps can't both count
    day = datetime.now(TZ).strftime("%Y-%m-%d")
    doc_id = f"{day}:{wrong_uid}"
    info = _gate_fail_info.get((chat_id, msg_id), {})
    incident = {
        "key": key, "chat_id": chat_id, "msg_id": msg_id, "chat_title": info.get("chat_title"), "rarity": info.get("rarity"),
        "failed_at": info.get("ts"), "reported_by": event.sender_id, "reported_at": time.time(),
    }
    try:
        # the "incidents.key $ne" filter makes the same failed gate count only once even across restarts: when it is already in the document the filter no
        # longer matches, the upsert then tries to create the same _id and Mongo raises DuplicateKeyError
        await gate_report_col.update_one(
            {"_id": doc_id, "incidents.key": {"$ne": key}},
            {"$push": {"incidents": incident}, "$inc": {"count": 1},
             "$set": {"user_id": wrong_uid, "date": day, "expire_at": datetime.fromtimestamp(time.time() + 3 * 86400, tz=pytz.utc)}},
            upsert=True,
        )
    except DuplicateKeyError:
        return await event.answer("📨 This one was already reported.", alert=False)
    except Exception as e:
        _gate_reported_keys.discard(key)               # not saved — let them try again
        print(f"rarity gate report save error: {e}")
        return await event.answer("⚠️ Couldn't save the report — try again in a moment.", alert=True)
    await event.answer("📨 Reported to the bot owner — thank you!", alert=True)
    try:
        await event.edit(buttons=[[Button.inline("✅ Reported to Bot Owner", data=event.data)]])
    except Exception:
        pass
    try:
        doc = await gate_report_col.find_one({"_id": doc_id})
        if doc and doc.get("count", 0) >= GATE_REPORT_DAILY_LIMIT:
            await _gate_report_alert(event, wrong_uid, doc)
    except Exception as e:
        print(f"rarity gate report alert error: {e}")

async def rarity_gate_quiz_timeout_watcher(chat_id, msg_id):
    try:
        await asyncio.sleep(RARITY_GATE_TIMEOUT_SECONDS)
        quiz = pending_rarity_quiz.get(chat_id)
        if not quiz or quiz.get("solved") or quiz.get("msg_id") != msg_id:
            return
        del pending_rarity_quiz[chat_id]
        await refund_gate_slot(quiz)        # nobody solved it — no spawn happened, so the daily slot goes back
        try:
            timeup_title = sans_bold_italic("Time's up!")
            await bot1.edit_message(
                chat_id, msg_id,
                f"⏰ {timeup_title}\n"
                f" {small_caps_full('nobody solved the gate in time')}",
                parse_mode='html',
                buttons=None
            )
        except Exception:
            pass
    except Exception as e:
        # 🛡️ RELIABILITY: no matter what goes wrong above, this chat's gate must never stay
        # stuck — a leftover pending_rarity_quiz entry silently blocks every future auto-spawn
        # in this chat (see the guard at the top of global_message_counter_handler).
        print(f"Rarity Gate Timeout Watcher Error: {e}")
        if pending_rarity_quiz.get(chat_id, {}).get("msg_id") == msg_id:
            _dead_quiz = pending_rarity_quiz.pop(chat_id, None)
            if _dead_quiz and not _dead_quiz.get("solved"):
                await refund_gate_slot(_dead_quiz)

# ---- TRIVIA AUTO-SPAWN — standalone 4-option "first correct tap wins ⭐ Stars" event. Fully
# independent of the character-spawn / rarity-gate-quiz system above (no character involved at
# all, purely a Star + Trivia-Points payout). See global_message_counter_handler for cadence. ----
async def trivia_leaderboard_button(user_id=None):
    """Button set on every trivia result: jump to the Global Top 50 Trivia Points leaderboard (opens on page 0), plus a ♻️ Bulk Scrap row when user_id is given (None for the 'nobody answered' timeout message)."""
    rows = [
        [Button.inline("🏆 Global Top 50", data="trivialb")]
    ]
    if user_id is not None:
        rows.append([Button.inline("♻️ Bulk Scrap Dupes", data=f"bscrap_o_{user_id}")])
    return rows

TRIVIA_LB_PAGE_SIZE = 10
TRIVIA_LB_TOTAL = 50  # 🩹 CHANGED (per owner request): expanded from a Top 20 (2 pages) to a
# Top 50 (5 pages) by cumulative Trivia Points, still 10 per page with ◀ Previous / Next ▶
# inline buttons — same fetch-once-then-slice shape as render_leaderboard_page() above for the
# catch leaderboard.

async def render_trivia_leaderboard_page(page):
    """Builds (text, buttons) for one page of the Global Top 50 SEASON leaderboard (ranked by `trivia_points_period`, the current 3-day season).
    page is 0-indexed: 0 = ranks 1-10 … 4 = ranks 41-50. Re-fetches fresh on every call. Each row shows the player's PERMANENT rank name (from their all-time
    points) next to this season's points. A "🏛 All-Time Top 10" button opens the permanent history page (render_trivia_alltime_page)."""
    top_users = await users_catcher_col.find(
        {"trivia_points_period": {"$gt": 0}, "user_id": {"$nin": banned_user_ids()}},
        {"user_id": 1, "fullname": 1, "trivia_points": 1, "trivia_points_period": 1, "_id": 0}
    ).sort("trivia_points_period", -1).limit(TRIVIA_LB_TOTAL).to_list(length=TRIVIA_LB_TOTAL)
    total = len(top_users)
    start = page * TRIVIA_LB_PAGE_SIZE
    page_rows = top_users[start:start + TRIVIA_LB_PAGE_SIZE]

    if not page_rows:
        body = "😶 <i>No Trivia points this season yet — be the first to answer one!</i>" if page == 0 else "<i>No more entries.</i>"
    else:
        lines = []
        for i, u in enumerate(page_rows):
            rank = start + i + 1
            uname = escape_html(clean_display_name(u.get("fullname"), fallback=f"Agent {u['user_id']}"))
            mention = f"<a href='tg://user?id={u['user_id']}'>{uname}</a>"
            _, rank_name, _, _ = get_trivia_rank_info(u.get("trivia_points", 0))
            lines.append(f"<b>{rank}.</b> {mention} — {rank_name} (<code>{u.get('trivia_points_period', 0)} pts</code>)")
        body = "\n".join(lines)
    try:
        season = await get_trivia_season()
        season_line = (f"🗓 <i>Season {season.get('no', 1)} · {TRIVIA_SEASON_DAYS}-day · resets in "
                       f"{trivia_fmt_remaining(float(season.get('ends_at', 0)) - time.time())}</i>\n"
                       f"💠 <i>Top 10 win VLT right before each reset</i>\n\n")
    except Exception:
        season_line = ""
    text = "🏆 <b>GLOBAL TRIVIA LEADERBOARD</b>\n" + season_line + ("\n" if not season_line else "") + body

    global_participants = await users_catcher_col.count_documents({"trivia_points": {"$exists": True}})

    nav_row = []
    if page > 0:
        nav_row.append(Button.inline("◀ Previous", data=f"trivialb_pg_{page - 1}"))
    if start + TRIVIA_LB_PAGE_SIZE < total:
        nav_row.append(Button.inline("Next ▶", data=f"trivialb_pg_{page + 1}"))

    buttons = []
    if nav_row:
        buttons.append(nav_row)
    buttons.append([Button.inline("🏛 All-Time Top 10", data="trivialb_all")])
    buttons.append([Button.inline(f"🌍 Globally: {global_participants:,}", data="trivia_global_count_noop")])
    return text, buttons

async def render_trivia_alltime_page():
    """(text, buttons) for the permanent "Top 10 Global of All Time" page — ranked by `trivia_points`, which never resets."""
    top_users = await users_catcher_col.find(
        {"trivia_points": {"$gt": 0}, "user_id": {"$nin": banned_user_ids()}},
        {"user_id": 1, "fullname": 1, "trivia_points": 1, "_id": 0}
    ).sort("trivia_points", -1).limit(10).to_list(length=10)
    if not top_users:
        body = "😶 <i>No Trivia ranks yet.</i>"
    else:
        lines = []
        for i, u in enumerate(top_users):
            uname = escape_html(clean_display_name(u.get("fullname"), fallback=f"Agent {u['user_id']}"))
            mention = f"<a href='tg://user?id={u['user_id']}'>{uname}</a>"
            pts = u.get("trivia_points", 0)
            _, rank_name, _, _ = get_trivia_rank_info(pts)
            lines.append(f"<b>{i + 1}.</b> {mention} — {rank_name} (<code>{pts} pts</code>)")
        body = "\n".join(lines)
    text = ("🏛 <b>GLOBAL TRIVIA — ALL-TIME TOP 10</b>\n"
            "📜 <i>Permanent history — these points never reset</i>\n\n" + body)
    return text, [[Button.inline("⬅ Season Board", data="trivialb_pg_0")]]

@bot1.on(events.CallbackQuery(pattern=r'^trivialb_all$'))
async def trivia_alltime_callback(event):
    """🏛 All-Time Top 10 button on the season board — edits the same message in place."""
    text, buttons = await render_trivia_alltime_page()
    try:
        await event.edit(text, parse_mode='html', buttons=buttons)
        await event.answer()
    except errors.MessageNotModifiedError:
        await event.answer()
    except Exception as e:
        await event.answer(f"❌ Error: {e}", alert=True)

@bot1.on(events.CallbackQuery(pattern=r'^trivialb_pg_(\d+)$'))
async def trivia_leaderboard_page_callback(event):
    """◀ Previous / Next ▶ taps on the Global Top 50 Trivia leaderboard — same
    edit-in-place-with-graceful-MessageNotModified shape as leaderboard_callback_handler
    (the catch leaderboard's own pager) above."""
    page = int(event.pattern_match.group(1))
    text, buttons = await render_trivia_leaderboard_page(page)
    try:
        await event.edit(text, parse_mode='html', buttons=buttons)
        await event.answer()
    except errors.MessageNotModifiedError:
        await event.answer()
    except Exception as e:
        await event.answer(f"❌ Error: {e}", alert=True)

async def get_trivia_pool(difficulty):
    """Merge owner-bulk-added questions (trivia_bank_col, filtered to this difficulty) with the
    static built-in TRIVIA_QUESTION_BANK[difficulty] fallback list — same "DB questions plus a
    static safety net" shape as _get_quiz_pool() for the rarity-gate quiz above. Custom docs
    come first so a growing owner-authored bank naturally dominates the built-in seed set over
    time without needing to touch the static list. Can legitimately return an empty list for a
    difficulty nobody has bulk-imported into yet — see the fallback search in
    trigger_trivia_spawn, which handles that instead of crashing."""
    custom = await trivia_bank_col.find({"difficulty": difficulty}, {"_id": 0}).to_list(length=None)
    static = TRIVIA_QUESTION_BANK.get(difficulty) or []
    return (custom or []) + static

async def trigger_trivia_spawn(chat_id, forced_difficulty=None, force_golden=False):
    """Posts one TRIVIA_OPTION_COUNT-option question in chat_id at a weighted random difficulty (or the owner's /ftrivia forced_difficulty). First correct tap wins the tier's Star reward + Trivia Points; everyone gets one attempt, wrong taps cost Trivia Points. Rolls GOLDEN_QUESTION_CHANCE every spawn."""
    if chat_id in pending_trivia_quiz:
        return
    try:
        difficulty = forced_difficulty if forced_difficulty in TRIVIA_DIFFICULTY_CONFIG else weighted_random_trivia_difficulty()
        cfg = TRIVIA_DIFFICULTY_CONFIG[difficulty]
        bank = await get_trivia_pool(difficulty)
        if not bank:
            # 🛡️ FALLBACK: the chosen tier has no questions yet (owner hasn't bulk-imported
            # that difficulty via /addtriviabulk). Try every other tier before giving up, so a
            # partially-stocked bank still fires trivia instead of a group going quiet just
            # because one specific tier is still empty.
            for fallback_difficulty in TRIVIA_DIFFICULTY_ORDER:
                if fallback_difficulty == difficulty:
                    continue
                fallback_bank = await get_trivia_pool(fallback_difficulty)
                if fallback_bank:
                    difficulty, cfg, bank = fallback_difficulty, TRIVIA_DIFFICULTY_CONFIG[fallback_difficulty], fallback_bank
                    break
        if not bank:
            # Truly nothing anywhere yet (fresh install, nothing bulk-imported at all) — skip
            # this cycle quietly rather than crashing on random.choice([]); tries again once
            # this chat's counter reaches its next random target.
            return
        q = random.choice(bank)
        options = q["options"][:]
        correct_answer_text = options[q["correct_index"]]
        random.shuffle(options)
        correct_index = options.index(correct_answer_text)

        is_golden = force_golden or random.random() < GOLDEN_QUESTION_CHANCE
        _base_min, _base_max = trivia_star_range(cfg)
        star_min = _base_min * GOLDEN_QUESTION_MULTIPLIER if is_golden else _base_min
        star_max = _base_max * GOLDEN_QUESTION_MULTIPLIER if is_golden else _base_max
        # Header line is the one thing that visually separates a Golden round from a normal one …
        if is_golden:
            title_line = f"{GOLDEN_QUESTION_EMOJI} {sans_bold_italic('Golden Question')} {GOLDEN_QUESTION_EMOJI}"
        else:
            title_line = f"🧠 {sans_bold_italic('Quick Trivia Time')}"
        header = (
            f"{title_line}\n"
            f"   {cfg['emoji']} {small_caps_full(cfg['label'] + ' difficulty')}\n\n"
            f"         ❓ <b>{escape_html(q['question'])}</b>"
        )

        # 🩹 CHANGED (per owner request): the option TEXT lives in the message body, and the
        # inline buttons are bare "1"/"2"/"3"/"4" in a single row — not one full-width button
        # per option with the answer text printed on it.
        options_text = "\n".join(
            f"  {small_caps_full(f'opt{i + 1}')}  ➜  {escape_html(opt)}" for i, opt in enumerate(options)
        )
        # 🩹 STAGE 1 (per owner report — "people mash-tap without even reading the question"):
        # question only, no options, no buttons. Nothing tappable exists yet at all, so no
        # amount of reflex-tapping can land a lucky guess in this window.
        stage1_text = (
            f"{header}\n\n"
            + (f"{GOLDEN_QUESTION_EMOJI} <i>Star reward ×{GOLDEN_QUESTION_MULTIPLIER} this round!</i>\n" if is_golden else "")
            + f"👀 {small_caps_full('read it first — options in')} {TRIVIA_OPTIONS_REVEAL_DELAY}s..."
        )
        stage2_text = (
            f"{header}\n\n"
            f"{options_text}\n\n"
            f"⏱ {small_caps_full('time')}: {TRIVIA_TIMEOUT_SECONDS}s\n"
            f"⭐ {small_caps_full('reward')}: {star_min}-{star_max} {small_caps_full('star')} + {cfg['points']} {small_caps_full('rank pts')}\n"
            f"🎯 <i>အဖြေမှန်ကို အရင်ဆုံးနှိပ်သူ Star ဆုရမယ်!</i>"
        )
        buttons = [
            [Button.inline(str(i + 1), data=f"triv_{chat_id}_{i}") for i in range(len(options))],
            [Button.inline("🎮 Casino ဆော့ကြမယ်", data="trivslot")],
        ]
        sent = await bot1.send_message(chat_id, stage1_text, parse_mode='html')

        # Set immediately (not after the reveal) so the "one trivia at a time per chat" guard
        # at the top of this function also covers the reveal-delay window itself — otherwise a
        # second trigger_trivia_spawn call landing in that gap could post an overlapping quiz.
        # "revealed": False is what stops trivia_answer_callback (and stray taps in general)
        # from doing anything until stage 2 actually posts real buttons — belt-and-suspenders,
        # since no buttons exist to tap yet anyway.
        quiz_state = {
            "options": options,
            "correct_index": correct_index,
            "question": q["question"],
            "difficulty": difficulty,
            "msg_id": sent.id,
            "quiz_time": time.time(),
            "solved": False,
            "attempted_users": set(),
            "revealed": False,
            "is_golden": is_golden,
            "star_min": star_min,
            "star_max": star_max,
        }
        pending_trivia_quiz[chat_id] = quiz_state

        await asyncio.sleep(TRIVIA_OPTIONS_REVEAL_DELAY)
        if pending_trivia_quiz.get(chat_id) is not quiz_state:
            return  # got force-cleared/replaced during the delay (e.g. owner ran /ftrivia) — bail out quietly

        try:
            await bot1.edit_message(chat_id, sent.id, stage2_text, parse_mode='html', buttons=buttons)
        except errors.MessageNotModifiedError:
            pass
        # Answering-timeout window starts NOW — at reveal — not at the original stage-1 post,
        # so the mandatory reading pause never eats into anyone's real answering time.
        quiz_state["quiz_time"] = time.time()
        quiz_state["revealed"] = True
        asyncio.create_task(trivia_quiz_timeout_watcher(chat_id, sent.id))
    except Exception as e:
        pending_trivia_quiz.pop(chat_id, None)  # never leave a stuck "pending" guard behind on error
        print(f"Trivia Spawn Error: {e}")

@bot1.on(events.CallbackQuery(pattern=r'^triv_(-?\d+)_(\d)$'))
async def trivia_answer_callback(event):
    chat_id = int(event.pattern_match.group(1))
    chosen_idx = int(event.pattern_match.group(2))
    quiz = pending_trivia_quiz.get(chat_id)
    if not quiz or quiz.get("solved"):
        return await event.answer("⌛ ဒီ Trivia မေးခွန်း ပြီးသွားပါပြီ။", alert=True)
    if time.time() - quiz["quiz_time"] > TRIVIA_TIMEOUT_SECONDS:
        return await event.answer("⌛ အချိန်ကုန်သွားပါပြီ။", alert=True)
    # 🔒 One attempt per person, no retries — check-and-mark with no await between them so a
    # user double-tapping can't sneak in a second try. Same pattern as the rarity-gate quiz.
    attempted_users = quiz.setdefault("attempted_users", set())
    if event.sender_id in attempted_users:
        return await event.answer("⚠️ သင့်မှာ ဒီမေးခွန်းအတွက် တစ်ကြိမ်ပဲ ဖြေခွင့်ရှိပါတယ်။", alert=True)
    attempted_users.add(event.sender_id)
    cfg = TRIVIA_DIFFICULTY_CONFIG[quiz.get("difficulty", "EASY")]

    if chosen_idx != quiz["correct_index"]:
        # 🩹 CHANGED (per owner request): a wrong tap now also costs Trivia Points ("ချိန်ဆလျှော့"
        base_penalty = cfg["wrong_penalty"]
        penalty = base_penalty
        star_penalty = trivia_star_penalty(cfg)
        is_top10 = False
        new_points = None
        star_penalty_note = ""
        try:
            wrong_user = await users_catcher_col.find_one({"user_id": event.sender_id})
            current_points = (wrong_user or {}).get("trivia_points", 0)
            current_period = (wrong_user or {}).get("trivia_points_period", 0)
            current_star = (wrong_user or {}).get("star_balance", 0)
            top10_ids = await get_current_trivia_top10_ids()
            is_top10 = event.sender_id in top10_ids
            if is_top10:
                penalty = base_penalty * 2
                star_penalty = star_penalty * 2
            new_points = max(0, current_points - penalty)
            new_period = max(0, current_period - penalty)          # the 3-day season score takes the same hit
            paid_now = round(max(0, min(current_star, star_penalty)), 2)
            added_debt = round(star_penalty - paid_now, 2)
            await users_catcher_col.update_one(
                {"user_id": event.sender_id},
                {"$set": {"trivia_points": new_points, "trivia_points_period": new_period}, "$inc": {"star_balance": -paid_now, "star_debt": added_debt}},
                upsert=True
            )
            star_penalty_note = (
                f" | ⭐−{format_star_plain(star_penalty)} ({format_star_plain(added_debt)} အကြွေးမှတ်)"
                if added_debt > 0 else f" | ⭐−{format_star_plain(star_penalty)}"
            )
        except Exception as e:
            print(f"Trivia wrong-answer penalty error: {e}")
        points_note = f"(now {new_points})" if new_points is not None else "(couldn't update)"
        return await event.answer(
            f"❌ မှားသွားပါပြီ။ Rank Points −{penalty}{' (Top 10 x2)' if is_top10 else ''} {points_note}"
            f"{star_penalty_note}\n"
            f"နောက်ထပ် အခွင့်အရေး မရတော့ပါ။",
            alert=True
        )

    async with spawn_locks[chat_id]:
        quiz = pending_trivia_quiz.get(chat_id)
        if not quiz or quiz.get("solved"):
            return await event.answer("⌛ တစ်ယောက်ယောက်က အရင်ဖြေပြီးသွားပါပြီ။", alert=True)
        quiz["solved"] = True
        winner_id = event.sender_id
    mention = await get_html_mention(event, winner_id)

    # ⭐ Star reward random within this round's range — quiz["star_min"/"star_max"] is either
    # cfg's plain range, or that range ×GOLDEN_QUESTION_MULTIPLIER if this was a 🌟 Golden
    # Question (see trigger_trivia_spawn). 👑 VIP winners get VIP_QUIZ_REWARD_MULTIPLIER
    # extra on top of THAT (same bonus rule as the rarity-gate quiz) — Trivia Points are
    # deliberately NOT boosted by either bonus, so the rank ladder stays skill/participation
    # based rather than pay-to-win or luck-to-win.
    is_golden = quiz.get("is_golden", False)
    _fallback_min, _fallback_max = trivia_star_range(cfg)
    star_reward = random.randint(quiz.get("star_min", _fallback_min), quiz.get("star_max", _fallback_max))
    points_earned = cfg["points"]
    winner_is_vip = await check_vip(winner_id)
    if winner_is_vip:
        star_reward = round(star_reward * VIP_QUIZ_REWARD_MULTIPLIER)

    points_before = 0
    points_after = points_earned
    try:
        winner_doc_before = await users_catcher_col.find_one({"user_id": winner_id})
        points_before = (winner_doc_before or {}).get("trivia_points", 0)
        points_after = points_before + points_earned
        await users_catcher_col.update_one(
            {"user_id": winner_id},
            {"$inc": {"star_balance": star_reward, "trivia_points": points_earned, "trivia_points_period": points_earned}},
            upsert=True
        )
        await settle_star_debt(winner_id)
    except Exception as e:
        print(f"Trivia star/points reward error: {e}")

    rank_before_idx, _rb_name, _rb_floor, _rb_next = get_trivia_rank_info(points_before)
    rank_after_idx, rank_after_name, floor_after, next_after = get_trivia_rank_info(points_after)
    bar = build_trivia_progress_bar(points_after, floor_after, next_after)
    progress_line = (
        f"{bar}  {points_after} pts (MAX 🏆)" if next_after is None
        else f"{bar}  {points_after}/{next_after} pts"
    )
    rank_up_line = f"🎉 {small_caps_full('rank up')}!\n" if rank_after_idx > rank_before_idx else ""
    trivia_position, trivia_total = await get_trivia_position(points_after)

    try:
        await event.edit(
            f"✅ {sans_bold_italic('Correct!')}\n\n"
            f"🏆 {small_caps_full('winner')}: {mention}\n"
            f"✔ {small_caps_full('answer')}: {escape_html(quiz['options'][quiz['correct_index']])}\n\n"
            f"⭐ {small_caps_full('reward')}: +{star_reward} {small_caps_full('star')}{' 👑' if winner_is_vip else ''}\n"
            f"🧠 {small_caps_full('rank pts')}: +{points_earned}\n\n"
            f"{rank_up_line}"
            f"🏅 {small_caps_full('rank')} {rank_after_idx}/{len(TRIVIA_RANKS)}: {rank_after_name}\n"
            f"{progress_line}\n"
            f"🌍 {small_caps_full('position')}: #{trivia_position} / {trivia_total}",
            parse_mode='html',
            buttons=await trivia_leaderboard_button(user_id=winner_id)
        )
    except Exception:
        pass

    # 🏆 NEW (per owner request — "make the winner announcement more public/exciting"): the …
    if is_golden:
        announce = (
            f"{GOLDEN_QUESTION_EMOJI} <b>GOLDEN QUESTION WON!</b> {GOLDEN_QUESTION_EMOJI}\n"
            f"🏆 {mention} {small_caps('walked away with')} <code>+{star_reward}⭐</code>!"
        )
    else:
        announce = (
            f"🏆 {mention} {small_caps('swept the trivia')}!\n"
            f"⭐ +{star_reward} · 🧠 +{points_earned} pts"
        )
    if rank_after_idx > rank_before_idx:
        announce += f"\n🎉 {small_caps('rank up')} — now {rank_after_name}!"
    try:
        await bot1.send_message(chat_id, announce, parse_mode='html')
    except Exception:
        pass

    await event.answer(f"✅ မှန်ပါတယ်! +{star_reward}⭐  +{points_earned} pts ရရှိပါပြီ!", alert=True)
    if pending_trivia_quiz.get(chat_id) is quiz:
        del pending_trivia_quiz[chat_id]

