def parse_bulk_trivia_text(raw_text):
    """Parses pipe-delimited bulk trivia, one question per line: 'Question | Opt1 | ... | OptN | correct (1-4 or A-D)' (field count follows TRIVIA_OPTION_COUNT). Skips blank and '#' lines. Returns (valid_docs, errors) where errors = (line_number, raw_line, reason)."""
    expected_fields = 1 + TRIVIA_OPTION_COUNT + 1  # question + N options + correct marker
    letter_map = {chr(ord('A') + i): i for i in range(TRIVIA_OPTION_COUNT)}
    valid = []
    errors = []
    for line_no, raw_line in enumerate(raw_text.splitlines(), start=1):
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        parts = [p.strip() for p in line.split("|")]
        if len(parts) != expected_fields:
            errors.append((
                line_no, raw_line,
                f"expected {expected_fields} parts separated by '|' (question + "
                f"{TRIVIA_OPTION_COUNT} options + correct answer), got {len(parts)}"
            ))
            continue
        question = parts[0]
        options = parts[1:1 + TRIVIA_OPTION_COUNT]
        correct_raw = parts[-1]
        if not question or any(not opt for opt in options):
            errors.append((line_no, raw_line, "question/option text can't be empty"))
            continue
        correct_norm = correct_raw.strip().upper()
        correct_index = None
        if correct_norm.isdigit() and 1 <= int(correct_norm) <= TRIVIA_OPTION_COUNT:
            correct_index = int(correct_norm) - 1
        elif correct_norm in letter_map:
            correct_index = letter_map[correct_norm]
        if correct_index is None:
            digits = "/".join(str(i + 1) for i in range(TRIVIA_OPTION_COUNT))
            letters = "/".join(chr(ord('A') + i) for i in range(TRIVIA_OPTION_COUNT))
            errors.append((line_no, raw_line, f"last field must be {digits} or {letters}, got '{correct_raw}'"))
            continue
        valid.append({"question": question, "options": options, "correct_index": correct_index})
    return valid, errors

# ---- /addtriviabulk: owner-only, BULK authoring of Trivia questions for ONE difficulty tier at
# a time — accepts HUNDREDS of questions in a single paste (or a .txt file upload for batches
# too big for one Telegram message). DM-only so nobody in the group sees it happening. ----
@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]addtriviabulk(?:@\w+)?(?:\s+(\S+))?$', 'bot1')))
async def add_trivia_bulk_handler(event):
    if event.sender_id != OWNER_ID: return
    if not event.is_private:
        return await event.reply(
            "⚠️ <b>Please DM me /addtriviabulk</b> — authored privately so nobody in the group sees it happening.",
            parse_mode='html'
        )
    difficulty = normalize_trivia_difficulty_arg(event.pattern_match.group(1) or "")
    if not difficulty:
        return await event.reply(
            f"📦 <b>Bulk-add Trivia questions</b>\n\n"
            f"<b>Usage:</b> <code>/addtriviabulk [difficulty]</code>\n"
            f"<b>Difficulty:</b> {' / '.join(TRIVIA_DIFFICULTY_ORDER)}\n\n"
            f"Example: <code>/addtriviabulk hard</code>",
            parse_mode='html'
        )
    cfg = TRIVIA_DIFFICULTY_CONFIG[difficulty]
    try:
        async with bot1.conversation(event.chat_id, timeout=600) as conv:
            await conv.send_message(
                f"📦 <b>Bulk Add Trivia — {cfg['emoji']} {cfg['label']}</b>\n\n"
                f"Send me ALL your questions now, <b>one per line</b>, in this exact format:\n"
                f"<code>Question | Option 1 | Option 2 | Option 3 | Option 4 | 1</code>\n\n"
                f"The last field says which option is correct — <code>1</code>-<code>4</code> "
                f"or <code>A</code>-<code>D</code> (whichever's easier to type).\n\n"
                f"<b>Example:</b>\n"
                f"<code>ဂျပန်နိုင်ငံရဲ့ မြို့တော်က ဘယ်မြို့လဲ? | တိုကျို | အိုစာကာ | ကျိုတို | နာဂိုယာ | 1</code>\n\n"
                f"📎 For a LOT of questions, upload a <code>.txt</code> file (one question per "
                f"line, same format) instead of pasting — no length limit that way.\n\n"
                f"Send /cancel anytime to stop.",
                parse_mode='html'
            )
            resp = await conv.get_response()
            if (resp.raw_text or "").strip().lower() == "/cancel":
                return await conv.send_message("❌ Cancelled.")

            if resp.document:
                try:
                    file_bytes = await bot1.download_media(resp, file=bytes)
                    raw_text = file_bytes.decode('utf-8', errors='replace')
                except Exception as e:
                    return await conv.send_message(f"❌ Couldn't read that file: <code>{escape_html(str(e))}</code>", parse_mode='html')
            else:
                raw_text = resp.raw_text or ""

            if not raw_text.strip():
                return await conv.send_message("❌ That was empty. Cancelled — run /addtriviabulk again.")

            valid, parse_errors = parse_bulk_trivia_text(raw_text)

            # 🧹 Dedup — both within this batch AND against what's already stored for this
            # difficulty, so it's always safe to fix a few bad lines and resubmit the WHOLE
            # file without doubling up the lines that already succeeded the first time.
            existing_questions = set()
            try:
                existing_docs = await trivia_bank_col.find(
                    {"difficulty": difficulty}, {"_id": 0, "question": 1}
                ).to_list(length=None)
                existing_questions = {d["question"].strip().lower() for d in existing_docs}
            except Exception as e:
                print(f"addtriviabulk existing-dedup lookup error: {e}")

            to_insert = []
            seen_in_batch = set()
            skipped_dupes = 0
            for doc in valid:
                key = doc["question"].strip().lower()
                if key in existing_questions or key in seen_in_batch:
                    skipped_dupes += 1
                    continue
                seen_in_batch.add(key)
                doc["difficulty"] = difficulty
                doc["created_by"] = event.sender_id
                doc["created_at"] = time.time()
                to_insert.append(doc)

            inserted_count = 0
            if to_insert:
                try:
                    result = await trivia_bank_col.insert_many(to_insert)
                    inserted_count = len(result.inserted_ids)
                except Exception as e:
                    return await conv.send_message(f"❌ Insert failed: <code>{escape_html(str(e))}</code>", parse_mode='html')

            summary = f"✅ <b>Added {inserted_count} question(s) to {cfg['emoji']} {cfg['label']}.</b>\n"
            if skipped_dupes:
                summary += f"⏭️ Skipped {skipped_dupes} duplicate question(s) (already in this tier).\n"
            if parse_errors:
                shown = parse_errors[:15]
                err_lines = "\n".join(f"  Line {ln}: {reason}" for ln, _raw, reason in shown)
                more = f"\n  ...and {len(parse_errors) - 15} more" if len(parse_errors) > 15 else ""
                summary += f"❌ <b>{len(parse_errors)} line(s) had problems:</b>\n<code>{escape_html(err_lines)}{more}</code>\n"
            summary += f"\nUse <code>/listtriviabank {difficulty}</code> to review, or run /addtriviabulk again to add more."
            await conv.send_message(summary, parse_mode='html')
    except asyncio.TimeoutError:
        await event.reply("⌛ <b>Timed out waiting for your bulk paste.</b> Run /addtriviabulk again.", parse_mode='html')
    except Exception as e:
        print(f"add_trivia_bulk_handler error: {e}")
        await event.reply(f"❌ <b>Something went wrong:</b> <code>{escape_html(str(e))}</code>", parse_mode='html')

# ---- /listtriviabank: owner-only. No args = quick counts across all 5 tiers. With a difficulty
# arg = that tier's custom (DB) questions, newest-last, capped to 30 shown so a big bank never
# blows past Telegram's message-length limit. ----
@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]listtriviabank(?:@\w+)?(?:\s+(\S+))?$', 'bot1')))
async def list_trivia_bank_handler(event):
    if event.sender_id != OWNER_ID: return
    raw_arg = event.pattern_match.group(1) or ""
    if not raw_arg:
        lines = []
        for d in TRIVIA_DIFFICULTY_ORDER:
            dcfg = TRIVIA_DIFFICULTY_CONFIG[d]
            custom_count = await trivia_bank_col.count_documents({"difficulty": d})
            static_count = len(TRIVIA_QUESTION_BANK.get(d) or [])
            lines.append(
                f"{dcfg['emoji']} <b>{dcfg['label']}:</b> {custom_count} custom + {static_count} "
                f"built-in = <code>{custom_count + static_count}</code>"
            )
        return await event.reply(
            "🧠 <b>Trivia Question Bank — Overview</b>\n\n" + "\n".join(lines) +
            f"\n\nUse <code>/listtriviabank [difficulty]</code> to see a tier's custom questions.",
            parse_mode='html'
        )
    difficulty = normalize_trivia_difficulty_arg(raw_arg)
    if not difficulty:
        return await event.reply(
            f"❌ Unknown difficulty. Usage: <code>/listtriviabank [{'|'.join(TRIVIA_DIFFICULTY_ORDER)}]</code>",
            parse_mode='html'
        )
    cfg = TRIVIA_DIFFICULTY_CONFIG[difficulty]
    custom = await trivia_bank_col.find(
        {"difficulty": difficulty}, {"question": 1}
    ).sort("created_at", 1).to_list(length=None)
    static_count = len(TRIVIA_QUESTION_BANK.get(difficulty) or [])
    shown = custom[:30]
    lines = [f"<code>{i + 1}.</code> {escape_html(q['question'][:70])}" for i, q in enumerate(shown)]
    more = f"\n<i>...and {len(custom) - 30} more.</i>" if len(custom) > 30 else ""
    await event.reply(
        f"🧠 <b>Custom {cfg['emoji']} {cfg['label']} Trivia ({len(custom)})</b>\n" +
        ("\n".join(lines) if lines else "<i>None yet — use /addtriviabulk.</i>") + more +
        f"\n\n<i>Plus {static_count} built-in fallback questions, always in rotation too.</i>",
        parse_mode='html'
    )

# ==========================================
# 🔎 IDENTIFY VIA /who ON A SAVED/REPOSTED PHOTO OR VIDEO — if a character's original media
# (added through /addchar) was saved to someone's gallery and later sent back — as a photo/
# video WITH "/who" as the caption, or as a plain photo/video that then gets replied to with
# /who — recognizes it via perceptual hash and shows name/id/rarity + a /collect hint.
# Works in groups AND in the bot's DM. INFO ONLY: never touches active_group_spawns, so it
# never makes anything catchable by itself — /collect still only works against a real live spawn.
# ==========================================
# 🩹 FIX (2026-11, owner report — "/check 1 = Ronaldo, but .w on the same photo/video says 3102 Mikasa"): see the long note above find_character_by_media.
IDENTIFY_HAMMING_THRESHOLD = 16
IDENTIFY_MIN_MARGIN = 10
HASH_HEX_LEN = PHASH_SIZE * PHASH_SIZE // 4      # 64 hex chars = the 256-bit hash; anything else (e.g. the old 64-bit ones) is "legacy" and never compared
IDENTIFY_COOLDOWN_SECONDS = 1  # per-user, so repeated attempts don't spam replies

# 🩹 (2026-10 perf pass, ported from the faster build) The same Telegram file (a repost / forward of a spawn image)
MEDIA_IDENTIFY_HASH_TTL = 900                  # a hash-derived answer is a GUESS: memory only, 15 min, never written to Mongo
MEDIA_IDENTIFY_NEGATIVE_CACHE_TTL = 300
_MEDIA_ID_CACHE = {}   # media_key -> (char_id_or_None, cached_at, src) — src "card": the file IS that card's stored media (certain, no expiry) · "hash": a guess
_MEDIA_ID_CONFLICT = set()   # file keys that turned out to be the stored media of TWO cards: a file id can't tell them apart, so the hash decides
media_identity_col = db["media_identity_index"]

def get_media_identity_key(media_msg):
    """photo.id / document.id — what stays identical across forwards of the exact same file (a screenshot or
    re-compression is a NEW file and rightly gets its own hash). None when there's no photo/video/document."""
    try:
        if media_msg.photo:
            return f"photo:{media_msg.photo.id}"
        if media_msg.document:
            return f"doc:{media_msg.document.id}"
    except Exception:
        pass
    return None

async def _persist_media_identity(key, char_id, src="card"):
    try:
        await media_identity_col.update_one({"_id": key}, {"$set": {"char_id": char_id, "src": src, "updated_at": time.time()}}, upsert=True)
    except Exception as e:
        print(f"⚠️ media identity persist failed for {key}: {e}")

async def _forget_media_identity(key):
    try:
        await media_identity_col.delete_one({"_id": key})
    except Exception as e:
        print(f"⚠️ media identity delete failed for {key}: {e}")

async def load_media_identity_cache_from_db():
    """One Mongo query at boot. ONLY certain mappings (src == "card") are loaded. Older documents have no src: they were written from hash GUESSES —
    including wrong ones, which stayed cached for a week and were re-armed on every boot — so they are ignored (left in place, harmless)."""
    loaded, now = 0, time.time()
    async for doc in media_identity_col.find({"src": "card"}, {"char_id": 1}):
        if doc.get("char_id"):
            _MEDIA_ID_CACHE[doc["_id"]] = (doc["char_id"], now, "card")
            loaded += 1
    return loaded

def learn_media_identity(msg, char_id):
    """Called wherever the bot fetches a card's OWN stored media (get_char_display_media + its batch sibling): the Telegram file of that message
    IS this card, whoever reposts or forwards it later keeps the same photo.id / document.id. Remembering that makes .w on a spawn / /check / shop
    photo or video an exact lookup — no perceptual hash involved, so no way to name the wrong card."""
    try:
        key = get_media_identity_key(msg)
        if not key or not char_id or key in _MEDIA_ID_CONFLICT:
            return
        cur = _MEDIA_ID_CACHE.get(key)
        loop = asyncio.get_running_loop()
        if cur and cur[2] == "card":
            if cur[0] != char_id:        # the same file is the stored media of two cards -> never trust the file id for it
                _MEDIA_ID_CONFLICT.add(key)
                _MEDIA_ID_CACHE.pop(key, None)
                loop.create_task(_forget_media_identity(key))
                print(f"ℹ️ media identity: {key} is the stored media of both {cur[0]} and {char_id} — falling back to the hash for it")
            return
        _MEDIA_ID_CACHE[key] = (char_id, time.time(), "card")
        loop.create_task(_persist_media_identity(key, char_id, "card"))
    except RuntimeError:
        pass                              # no running loop (import time / tests) — nothing to learn from
    except Exception as e:
        print(f"learn_media_identity error: {type(e).__name__}: {e}")

_popcount = int.bit_count if hasattr(int, "bit_count") else (lambda x: bin(x).count("1"))

async def _rank_by_hash(incoming_hash, top=3):
    """[(distance, char_doc), ...] nearest first, over every card with a usable stored hash (ties keep roster order, like the old loop)."""
    import heapq
    try:
        incoming_int = int(incoming_hash, 16)
    except (ValueError, TypeError):
        return []
    hashes, docs = await _get_char_hash_index()
    near = heapq.nsmallest(top, ((_popcount(incoming_int ^ h), i) for i, h in enumerate(hashes)))
    return [(d, docs[i]) for d, i in near]

def _hash_verdict(ranked):
    """(doc_or_None, why) — why: ok | empty | too_far | ambiguous. The nearest card only counts when it is close enough AND clearly closer than the next."""
    if not ranked:
        return None, "empty"
    d1, doc1 = ranked[0]
    if d1 > IDENTIFY_HAMMING_THRESHOLD:
        return None, "too_far"
    if len(ranked) > 1 and ranked[1][0] - d1 < IDENTIFY_MIN_MARGIN:
        return None, "ambiguous"
    return doc1, "ok"

@_log_slow("find_character_by_media", 2.0)
async def find_character_by_media(media_msg):
    """Core character lookup for a photo/video message — the best-matching character doc, or None. Shared by _identify_media_and_reply (the /who-style
    public lookup) and add_artist_handler's reply-based shortcut.
    Order: (1) the exact Telegram file — certain whenever the bot has ever shown that card's own media; (2) a perceptual-hash match, accepted only when it
    is close AND clearly better than the runner-up (see IDENTIFY_HAMMING_THRESHOLD). 🩹 What used to go wrong: any nearest card within 40 bits was
    accepted, the answer was cached for a week AND written to Mongo (re-armed at every boot), so one wrong guess became permanent; and cards whose
    stored hash was missing / the old 64-bit size could never win, which left a look-alike as "nearest"."""
    media_key = get_media_identity_key(media_msg)
    if media_key and media_key not in _MEDIA_ID_CONFLICT:
        cached = _MEDIA_ID_CACHE.get(media_key)
        if cached:
            cached_char_id, cached_at, src = cached
            if src == "card" or (time.time() - cached_at) < (MEDIA_IDENTIFY_HASH_TTL if cached_char_id is not None else MEDIA_IDENTIFY_NEGATIVE_CACHE_TTL):
                if cached_char_id is None:
                    return None
                char = await get_character_by_id_cached(cached_char_id)   # re-check it still exists (/delchar)
                if char is not None:
                    return dict(char)
    try:
        incoming_hash = await compute_phash_for_message(media_msg)
    except Exception as e:
        print(f"find_character_by_media hash error: {e}")
        return None
    if not incoming_hash:
        return None
    ranked = await _rank_by_hash(incoming_hash, top=2)
    best, why = _hash_verdict(ranked)
    if ranked:
        print(f"🔎 identify(hash): {why} — nearest {ranked[0][1].get('char_id')} d={ranked[0][0]}" + (f", runner-up {ranked[1][1].get('char_id')} d={ranked[1][0]}" if len(ranked) > 1 else ""))
    # Shallow copy: the index's docs are shared between calls, so a caller that mutates its result can't corrupt the next lookup.
    best = dict(best) if best else None
    if media_key and media_key not in _MEDIA_ID_CONFLICT:
        cur = _MEDIA_ID_CACHE.get(media_key)
        if not (cur and cur[2] == "card"):                            # never let a guess overwrite a certain answer
            _MEDIA_ID_CACHE[media_key] = (best["char_id"] if best else None, time.time(), "hash")   # memory only — a guess is never persisted
    return best

async def _get_char_hash_index():
    """(hashes_as_ints, docs) for every character with a USABLE photo_phash — a 64-hex-char (256-bit) one. Missing, legacy-size (the old 64-bit
    hashes) and unparseable hashes are left out, because a distance against a different-size hash is meaningless (a legacy card could never win,
    which is how a look-alike ended up "nearest"). The counts are kept in _CHAR_HASH_INDEX["stats"] and logged when they change; /rehash repairs them.
    Rebuilt only after invalidate_character_caches() (or after CHAR_HASH_INDEX_MAX_AGE), not per lookup."""
    ver = _OWNER_ROSTER_VERSION["v"]
    if _CHAR_HASH_INDEX["version"] == ver and (time.time() - _CHAR_HASH_INDEX["ts"]) < CHAR_HASH_INDEX_MAX_AGE:
        return _CHAR_HASH_INDEX["hashes"], _CHAR_HASH_INDEX["docs"]
    characters_list = await get_all_characters_cached()
    hashes, docs = [], []
    missing = legacy = 0
    for char in characters_list:
        h = char.get("photo_phash")
        if not h:
            missing += 1
            continue
        if not isinstance(h, str) or len(h) != HASH_HEX_LEN:
            legacy += 1
            continue
        try:
            hashes.append(int(h, 16))
        except (ValueError, TypeError):
            legacy += 1
            continue
        docs.append(char)
    hashes, docs = tuple(hashes), tuple(docs)
    stats = {"usable": len(hashes), "missing": missing, "legacy": legacy}
    if _OWNER_ROSTER_VERSION["v"] == ver:   # roster didn't change while we were awaiting — safe to keep
        if stats != _CHAR_HASH_INDEX.get("stats") and (missing or legacy):
            print(f"🔎 hash index: {stats['usable']} usable · {missing} without a hash · {legacy} legacy/invalid — those can't be recognised by .w until /rehash missing")
        _CHAR_HASH_INDEX.update(version=ver, ts=time.time(), hashes=hashes, docs=docs, stats=stats)
    return hashes, docs

async def _identify_media_and_reply(event, media_msg):
    user_id = event.sender_id
    is_cd, _ = await is_on_cooldown(user_id, "identify_repost", IDENTIFY_COOLDOWN_SECONDS)
    if is_cd:
        return
    best_match = await find_character_by_media(media_msg)
    if not best_match:
        return await event.reply("❓ <b>This one isn't recognized.</b>", parse_mode='html')
    # 🔐 If this exact character is currently sitting behind an unsolved rarity-gate quiz
    # in ANY chat, don't confirm its identity — that would leak Rarity 1-4 characters before
    # the gate is actually cleared and the spawn is released.
    for quiz in pending_rarity_quiz.values():
        if not quiz.get("solved") and quiz.get("char", {}).get("char_id") == best_match["char_id"]:
            return await event.reply(
                "🔐 <b>Can't confirm this one yet — it's still sealed behind a gate somewhere.</b>",
                parse_mode='html'
            )
    # 🛡️ (2026-11, per owner request — scripts catching off the /who reveal) the same rule as the gate above: while this exact card is a LIVE, unclaimed spawn
    # in ANY chat, don't confirm it here — otherwise a script could send the spawn's own photo to this lookup and read the name + "/coll name" from the
    # reply, getting round the reveal that no longer prints the name. After the spawn is caught or expires the lookup works again. (Remove this loop to undo.)
    for _live in list(active_group_spawns.values()):
        if _live and not _live.get("claimed") and _live.get("char_id") == best_match["char_id"]:
            return await event.reply(
                f"🔐 <b>{small_caps_full('this one is live right now')}</b>\n"
                f"<i>{small_caps_full('reply /w to the spawn itself')}</i>",
                parse_mode='html'
            )
    try:
        rarity_tier = classify_rarity(best_match.get("rarity", ""))
        rarity_emoji = RARITY_EMOJI.get(rarity_tier, RARITY_DEFAULT_EMOJI)
        reveal_text = (
            f"🔎 <b>Recognized!</b>\n\n"
            f"<b>Name:</b> <b>{escape_html(best_match['name'])}</b>\n"
            f"🔖 <b>Character ID:</b> <code>{display_char_id(best_match['char_id'])}</code>\n"
            f"{rarity_emoji} <b>Rarity:</b> {best_match.get('rarity', '?')}\n"
            f"{artist_line(best_match)}\n\n"
            f"<code>/coll {escape_html(best_match['name'])}</code>\n\n"
            f"<i>Only catchable if this one is actually live right now — this is just a lookup.</i>"
        )
        await event.reply(reveal_text, parse_mode='html')
    except Exception as e:
        print(f"identify reply error: {e}")

# ---- 🔎 owner tools for the photo/video recogniser (2026-11) ----
@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]hashcheck(?:@\w+)?(?:\s+(\S+))?\s*$', 'bot1')))
async def hashcheck_handler(event):
    """/hashcheck [card id] — reply to a photo/video to see what the recogniser makes of it: exact-file hit, the 3 nearest cards with their distances and
    the verdict; with an id, also that card's stored-hash state (ok / MISSING / LEGACY) and its distance to the replied media."""
    if event.sender_id != OWNER_ID or is_duplicate_event(event):
        return
    arg = event.pattern_match.group(1)
    await _get_char_hash_index()
    st = _CHAR_HASH_INDEX.get("stats") or {}
    out = ["🔎 <b>Hash check</b>",
           f"index: <code>{st.get('usable', 0)}</code> usable · <code>{st.get('missing', 0)}</code> no hash · <code>{st.get('legacy', 0)}</code> legacy/invalid",
           f"rule: nearest within <code>{IDENTIFY_HAMMING_THRESHOLD}</code> bits and <code>{IDENTIFY_MIN_MARGIN}</code>+ closer than the runner-up"]
    target = None
    if arg:
        cid = normalize_char_id_input(arg)
        target = await get_character_by_id_cached(cid)
        if not target:
            out.append(f"❌ no card <code>{escape_html(display_char_id(cid))}</code>")
        else:
            h = target.get("photo_phash")
            state = ("MISSING" if not h else "ok" if (isinstance(h, str) and len(h) == HASH_HEX_LEN)
                     else f"LEGACY/INVALID (length {len(h) if isinstance(h, str) else '?'})")
            out.append(f"🎴 <b>{escape_html(target.get('name', '?'))}</b> <code>{escape_html(display_char_id(cid))}</code> — stored hash: <b>{state}</b>")
    media = await event.get_reply_message() if event.is_reply else None
    if media and (media.photo or media.video or media.document):
        key = get_media_identity_key(media)
        cur = _MEDIA_ID_CACHE.get(key) if key else None
        if key in _MEDIA_ID_CONFLICT:
            out.append("🔑 file id: shared by two cards — the hash decides")
        elif cur and cur[2] == "card":
            c = await get_character_by_id_cached(cur[0])
            out.append(f"🔑 exact file match: <b>{escape_html((c or {}).get('name', '?'))}</b> <code>{escape_html(display_char_id(cur[0]))}</code> (certain)")
        else:
            out.append("🔑 file id: not a known card file — falls to the hash")
        h = await compute_phash_for_message(media)
        if not h:
            out.append("⚠️ couldn't compute a hash for this media")
        else:
            ranked = await _rank_by_hash(h, top=3)
            for n, (d, doc) in enumerate(ranked, 1):
                out.append(f"{n}. <code>d={d}</code> — {escape_html(doc.get('name', '?'))} <code>{escape_html(display_char_id(doc.get('char_id', '')))}</code>")
            best, why = _hash_verdict(ranked)
            out.append("verdict: " + (f"✅ would match <b>{escape_html(best.get('name', '?'))}</b>" if best else f"❌ not recognized (<code>{why}</code>)"))
            if target and isinstance(target.get("photo_phash"), str) and len(target["photo_phash"]) == HASH_HEX_LEN:
                out.append(f"↔️ distance to <code>{escape_html(display_char_id(target['char_id']))}</code>: <code>{_popcount(int(h, 16) ^ int(target['photo_phash'], 16))}</code>")
    elif not arg:
        out.append("<i>Reply to a photo/video (and/or add a card id) — e.g. </i><code>/hashcheck 1</code>")
    await event.reply("\n".join(out), parse_mode='html')

_REHASH_RUNNING = {"on": False}

async def _rehash_card(char, msg=None):
    """Recompute char's stored hash from its CURRENT storage media (the very file spawns / /check show). (hash, None) or (None, reason)."""
    try:
        msg = msg or await bot1.get_messages(SPECIFIC_CONTROL_GROUP, ids=char["storage_msg_id"])
        if not msg or not msg.media:
            return None, "storage message missing"
        h = await compute_phash_for_message(msg)
        if not h:
            return None, "no usable image/thumbnail to hash"
        await characters_base_col.update_one({"char_id": char["char_id"]}, {"$set": {"photo_phash": h}})
        learn_media_identity(msg, char["char_id"])
        return h, None
    except Exception as e:
        return None, f"{type(e).__name__}"

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]rehash(?:@\w+)?\s+(\S+)\s*$', 'bot1')))
async def rehash_handler(event):
    """/rehash <card id> — rebuild that card's hash · /rehash missing — rebuild every card whose hash is missing or legacy-size (background, throttled)."""
    if event.sender_id != OWNER_ID or is_duplicate_event(event):
        return
    arg = event.pattern_match.group(1)
    if arg.lower() != "missing":
        cid = normalize_char_id_input(arg)
        char = await characters_base_col.find_one({"char_id": cid})
        if not char or not char.get("storage_msg_id"):
            return await event.reply(f"❌ no card <code>{escape_html(display_char_id(cid))}</code> with stored media.", parse_mode='html')
        old = char.get("photo_phash")
        h, err = await _rehash_card(char)
        if err:
            return await event.reply(f"❌ <code>{escape_html(display_char_id(cid))}</code>: {escape_html(err)}", parse_mode='html')
        await invalidate_character_caches()
        return await event.reply(f"✅ <b>{escape_html(char.get('name', '?'))}</b> <code>{escape_html(display_char_id(cid))}</code> rehashed "
                                 f"({'unchanged' if old == h else 'updated'}).", parse_mode='html')
    if _REHASH_RUNNING["on"]:
        return await event.reply("⏳ A rehash is already running.", parse_mode='html')
    cards = await characters_base_col.find({"storage_msg_id": {"$exists": True, "$ne": None}},
                                           {"char_id": 1, "name": 1, "storage_msg_id": 1, "photo_phash": 1}).to_list(length=None)
    todo = [c for c in cards if not (isinstance(c.get("photo_phash"), str) and len(c["photo_phash"]) == HASH_HEX_LEN)]
    if not todo:
        return await event.reply("✅ Every card with media already has a current hash.", parse_mode='html')
    _REHASH_RUNNING["on"] = True
    try:
        status = await event.reply(f"⏳ Rehashing <code>{len(todo)}</code> card(s)…", parse_mode='html')
        ok, failed, sem = 0, [], asyncio.Semaphore(3)

        async def _one(c, m):
            async with sem:
                if m is None:
                    return c, "storage message missing"
                return c, (await _rehash_card(c, m))[1]

        for i in range(0, len(todo), 50):
            chunk = todo[i:i + 50]
            try:
                msgs = await bot1.get_messages(SPECIFIC_CONTROL_GROUP, ids=[c["storage_msg_id"] for c in chunk])
            except Exception as e:
                print(f"rehash: fetch failed: {type(e).__name__}: {e}")
                msgs = [None] * len(chunk)
            for c, err in await asyncio.gather(*(_one(c, m) for c, m in zip(chunk, msgs))):
                if err:
                    failed.append((c["char_id"], err))
                else:
                    ok += 1
            try:
                await status.edit(f"⏳ Rehashing… <code>{min(i + 50, len(todo))}/{len(todo)}</code> · ✅ {ok} · ❌ {len(failed)}", parse_mode='html')
            except Exception:
                pass
            await asyncio.sleep(1)
        await invalidate_character_caches()
        tail = ("\n" + "\n".join(f"• <code>{escape_html(display_char_id(cid))}</code> — {escape_html(err)}" for cid, err in failed[:10])
                + (f"\n…and {len(failed) - 10} more" if len(failed) > 10 else "")) if failed else ""
        await event.reply(f"🏁 <b>Rehash done</b> — ✅ <code>{ok}</code> · ❌ <code>{len(failed)}</code>{tail}", parse_mode='html')
    finally:
        _REHASH_RUNNING["on"] = False

# ---- /who (aliases: /w, /waifu) ----
# 🩹 CHANGED (per owner request, 2026-10): when several people reply .w/.who/.waifu to the SAME spawn (or saved …
WHO_REVEAL_SHARED_COOLDOWN = 30   # seconds
# 🛡️ (2026-11, per owner request — PC players and auto-collect scripts were reading the revealed "/coll name" out of the /who reply and winning the catch)
WHO_REVEAL_MODE = os.environ.get("WHO_REVEAL_MODE", "copy").strip().lower()
if WHO_REVEAL_MODE not in ("copy", "inline"):
    WHO_REVEAL_MODE = "copy"

# 🎛️ /whomode (2026-11, per owner request — "Plan B ကို ငါလိုသလိုပြောင်းနိုင်အောင် owner only command"): the owner flips the reveal mode live, no restart, no env var.
# The choice is saved in bot_settings ("who_reveal_mode") and beats the WHO_REVEAL_MODE environment default after a restart.
WHO_REVEAL_MODES = {
    "copy":   "📋 <b>Copy &amp; send</b> — a Copy button holds <code>/coll name</code>; the message text shows no name",
    "inline": "📨 <b>Collect now</b> (Plan B) — no Copy button; the button sends <code>/coll name</code> as an inline \"via @bot\" message",
}

async def load_who_reveal_mode():
    """Restore the owner's last /whomode choice at startup."""
    global WHO_REVEAL_MODE
    try:
        doc = await bot_settings_col.find_one({"_id": "who_reveal_mode"})
        if doc and doc.get("mode") in WHO_REVEAL_MODES:
            WHO_REVEAL_MODE = doc["mode"]
    except Exception as e:
        print(f"load_who_reveal_mode error: {e}")

def _whomode_status_text(head=""):
    rows = "\n".join(f"{'✅' if m == WHO_REVEAL_MODE else '▫️'} <code>{m}</code> — {desc}" for m, desc in WHO_REVEAL_MODES.items())
    return (
        (head + "\n\n" if head else "")
        + "🛡️ <b>/w · /who reveal mode</b>\n"
        + f"<blockquote>{rows}</blockquote>\n"
        + "Switch: <code>/whomode copy</code> · <code>/whomode inline</code>\n"
        + "<i>Takes effect on the very next /w, in every chat, and survives a restart.</i>"
    )

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]whomode(?:@\w+)?(?:\s+(\S+))?$', 'bot1')))
async def whomode_handler(event):
    if event.sender_id != OWNER_ID: return
    global WHO_REVEAL_MODE
    arg = (event.pattern_match.group(1) or "").strip().lower()
    if not arg:
        return await event.reply(_whomode_status_text(), parse_mode='html')
    if arg not in WHO_REVEAL_MODES:
        return await event.reply(_whomode_status_text("❌ <b>Unknown mode</b> — use <code>copy</code> or <code>inline</code>."), parse_mode='html')
    previous = WHO_REVEAL_MODE
    WHO_REVEAL_MODE = arg
    try:
        await bot_settings_col.update_one({"_id": "who_reveal_mode"}, {"$set": {"mode": arg, "set_at": time.time()}}, upsert=True)
        saved = True
    except Exception as e:
        print(f"whomode save error: {e}")
        saved = False
    head = (f"✅ <b>Reveal mode set to {arg}</b>" if previous != arg else f"ℹ️ <b>Already on {arg}</b>")
    if not saved:
        head += "\n⚠️ <i>Applied now, but saving failed — it will fall back to the default after a restart.</i>"
    await event.reply(_whomode_status_text(head), parse_mode='html')
_who_reveal_recent = {}           # (chat_id, replied message id) -> time the last reveal was started
_who_copy_note_logged = {"done": False}
_bot1_self_id = None

async def _get_bot1_id():
    """bot1's own user id, fetched once. The reveal handler used to call bot1.get_me() — a full API round trip — on every single .w."""
    global _bot1_self_id
    if _bot1_self_id is None:
        _bot1_self_id = (await bot1.get_me()).id
    return _bot1_self_id

def _who_reveal_already_shown(chat_id, msg_id):
    """True = a reveal for this exact message was posted within the cooldown -> stay quiet. False = go ahead
    (and this call also records it NOW, before any await, so simultaneous .w's can't all slip through)."""
    now = time.time()
    key = (chat_id, msg_id)
    if now - _who_reveal_recent.get(key, 0) < WHO_REVEAL_SHARED_COOLDOWN:
        return True
    _who_reveal_recent[key] = now
    if len(_who_reveal_recent) > 2000:
        for k in [k for k, ts in _who_reveal_recent.items() if now - ts > 300]:
            _who_reveal_recent.pop(k, None)
    return False

def _who_reveal_release(chat_id, msg_id):
    """The reveal FAILED to go out — free the slot so the next .w can try instead of being swallowed."""
    _who_reveal_recent.pop((chat_id, msg_id), None)

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.](?:who|w|waifu)(?:@\w+)?$', 'bot1')))
async def who_reveal_handler(event):
    user_id = event.sender_id
    chat_id = event.chat_id
    # Check if user is spam-muted — GLOBALLY, across every group.
    if user_id in user_mute_until and time.time() < user_mute_until[user_id]:
        return

    # 🩹 CHANGED (per owner request): only skip when this is a reply to ANOTHER BOT's own …
    _sp_fast = active_group_spawns.get(chat_id)
    _reply_is_live_spawn = bool(event.is_reply and _sp_fast and _sp_fast.get("spawn_msg_id")
                                and event.reply_to_msg_id == _sp_fast.get("spawn_msg_id"))
    if event.is_reply and not _reply_is_live_spawn:
        replied_msg = await event.get_reply_message()
        # A reply to the live main-group spawn's own message id counts as a reply to OUR spawn (exact), not to some other collector bot's.
        _sp_live = active_group_spawns.get(chat_id)
        _live_main_spawn = bool(chat_id == FORCE_SUB_CHAT_ID and _sp_live and _sp_live.get("spawn_msg_id")
                                and event.reply_to_msg_id == _sp_live.get("spawn_msg_id"))
        if not replied_msg and not _live_main_spawn:
            return
        if replied_msg:
            bot_me_id = await _get_bot1_id()
            if replied_msg.sender_id != bot_me_id and not _live_main_spawn:
                replied_sender = await replied_msg.get_sender()
                if getattr(replied_sender, 'bot', False):
                    return

    # ---- Path A: replying to the CURRENT live spawn message in this group — original,
    # unchanged flow (expiry/claimed guards, catch button, etc.) ----
    if not event.is_private and chat_id in active_group_spawns:
        spawn_data = active_group_spawns[chat_id]
        if event.is_reply and event.reply_to_msg_id == spawn_data["spawn_msg_id"]:
            if time.time() - spawn_data["spawn_time"] > 300:
                del active_group_spawns[chat_id]
                return await event.reply(
                    "Too slow — this spawn already expired. Wait for the next one.",
                    parse_mode='html'
                )
            if spawn_data.get("claimed"):
                return await _reply_already_caught(event, spawn_data)
            # 🩹 REVERTED (2026-09, per owner request — "/who ပြိုင်ရိုက်ရင်လည်း /obtain name …
            if _who_reveal_already_shown(chat_id, spawn_data["spawn_msg_id"]):
                return
            async with spawn_locks[chat_id]:
                spawn_data = active_group_spawns.get(chat_id)
                if not spawn_data or spawn_data.get("claimed"):
                    return await _reply_already_caught(event, spawn_data)
                spawn_data["revealed"] = True
                spawn_data["revealed_by"] = user_id
            try:
                char_name = spawn_data['name']
                rarity_tier = classify_rarity(spawn_data.get('rarity', ''))
                rarity_emoji = RARITY_EMOJI.get(rarity_tier, RARITY_DEFAULT_EMOJI)
                # 🩹 REDESIGNED (per owner request — match the small_caps fancy-font style …
                reveal_text = (
                    f"{rarity_emoji} ⋆ {small_caps_full('just dropped')} ✨\n"
                    f"⇩ {small_caps_full('tap the button to copy, then send it')}"
                )
                reveal_text_inline = (
                    f"{rarity_emoji} ⋆ {small_caps_full('just dropped')} ✨\n"
                    f"⇩ {small_caps_full('tap the button to send it')}"
                )
                _copy_btn_label = "📋 Copy & send"
                _inline_btn_label = "📨 Collect now"
                _inline_only = (WHO_REVEAL_MODE == "inline")
                # 🩹 FIX (per owner report — this was firing report_system_error on literally …
                sent_ok = False
                copy_problem = None
                if _inline_only:
                    pass                                    # PLAN B: no Copy button at all — straight to the inline "via @bot" button below
                elif hasattr(types, 'KeyboardButtonCopy'):
                    try:
                        # Explicit ReplyInlineMarkup on purpose — Telethon's automatic buttons=
                        # classifier doesn't treat KeyboardButtonCopy as inline-only
                        # (LonamiWebs/Telethon#4588) and builds a ReplyKeyboardMarkup instead,
                        # which Telegram rejects with ButtonTypeInvalidError.
                        copy_markup = types.ReplyInlineMarkup(rows=[
                            types.KeyboardButtonRow(buttons=[
                                types.KeyboardButtonCopy(
                                    text=_copy_btn_label,
                                    copy_text=f"/coll {char_name}"
                                )
                            ])
                        ])
                        await event.reply(reveal_text, parse_mode='html', buttons=copy_markup)
                        sent_ok = True
                    except Exception as tl_error:
                        copy_problem = f"Telethon copy button failed: {type(tl_error).__name__}: {tl_error}"
                else:
                    copy_problem = "this Telethon has no types.KeyboardButtonCopy"

                if not sent_ok and not _inline_only:
                    if not _who_copy_note_logged["done"]:           # once per process — not on every reveal
                        _who_copy_note_logged["done"] = True
                        print(f"ℹ️ /who: Telethon copy button unavailable — {copy_problem} ({telethon_env_info()}); using the Bot API for reveals")
                    try:
                        await bot_api_send_with_copy_button(
                            event.chat_id, event.id, reveal_text,
                            _copy_btn_label, f"/coll {char_name}"
                        )
                        sent_ok = True
                    except Exception as api_error:
                        detail = f"{type(api_error).__name__}: {api_error}"
                        print(f"⚠️ /who Bot API copy-button send failed — {detail}")
                        await report_system_error("who_reveal_botapi", f"{detail} | {telethon_env_info()}")

                if not sent_ok:
                    try:
                        await event.reply(
                            reveal_text_inline, parse_mode='html',
                            buttons=[[colored_switch_inline_button(_inline_btn_label, query=f"/coll {char_name}", same_peer=True)]]
                        )
                    except Exception as send_error:
                        await report_system_error("who_reveal_send", f"Reveal send failed: {type(send_error).__name__}: {send_error}")
                        # Every route failed. The text no longer carries the name, so a plain reply would be an empty reveal — free the slot and
                        # ask for a retry instead (the owner already got the error report above).
                        _who_reveal_release(chat_id, spawn_data.get("spawn_msg_id"))
                        await event.reply(f"⚠️ {small_caps_full('could not reveal this one — send /w again')}", parse_mode='html')
            except KeyError as ke:
                _who_reveal_release(chat_id, spawn_data.get("spawn_msg_id"))
                error_msg = f"KeyError: {ke}. Spawn data: {spawn_data}"
                print(error_msg)
                await report_system_error("who_reveal_handler", error_msg)
                await event.reply(
                    "❌ <b>Oops! The records are incomplete. Please try again later.</b>",
                    parse_mode='html'
                )
            except Exception as e:
                _who_reveal_release(chat_id, spawn_data.get("spawn_msg_id"))
                error_msg = f"General error in /who: {e}\nSpawn data: {spawn_data}"
                print(error_msg)
                await report_system_error("who_reveal_handler", error_msg)
                await event.reply(
                    "❌ <b>Something went wrong while revealing! Fixing it now...</b>",
                    parse_mode='html'
                )
            return

    # ---- Path B: identify a saved/reposted photo or video — works in groups AND DM.
    # Triggers if /who was sent AS the caption on the media, or as a reply to a message
    # that carries a photo/video. (Stickers excluded — animated .webm video-stickers carry a
    # DocumentAttributeVideo alongside DocumentAttributeSticker, so .video alone isn't enough
    # to tell a real video from a video-sticker.) ----
    media_msg = None
    if (event.photo or event.video) and not event.sticker:
        media_msg = event.message
    elif event.is_reply:
        replied = await event.get_reply_message()
        if replied and (replied.photo or replied.video) and not replied.sticker:
            media_msg = replied
    if media_msg is not None:
        # Group replies to one media message (e.g. the spawn that was JUST caught, or a repost): same rule as
        # Path A — one reveal per message, extra .w's on it stay quiet. (Caption-.w and DMs are one-person, no dedupe.)
        if event.is_reply and not event.is_private and media_msg is not event.message:
            if _who_reveal_already_shown(chat_id, media_msg.id):
                return
        return await _identify_media_and_reply(event, media_msg)

    # ---- Path C: nothing to show ----
    if event.is_private:
        return await event.reply(
            "<b>Send a photo/video with /who as the caption, or reply to one with /who, to identify it.</b>",
            parse_mode='html'
        )
    if chat_id not in active_group_spawns:
        return await event.reply(
            "<b>Nothing here yet... No one has come your way.</b>",
            parse_mode='html'
        )
    return await event.reply(
        "📌 <b>Hey! Reply directly to the spawn message to reveal the buddy — "
        "or reply to a saved photo/video with /who to identify it.</b>",
        parse_mode='html'
    )

# ==========================================
# 📊 PER-CHAT DAILY TALLY + /limitaudit (2026-11, per owner request): "ည 12 မှာ daily limit reset ပြီး 2 နာရီအတွင်း 10-15 catch တွေ ဖြစ်နေတယ် — 22 နဲ့အထက်ဖြစ်တဲ့သူက …
# ==========================================
_CHAT_STATS_SINCE_SET = False

def _chat_stats_day():
    return datetime.now(TZ).strftime("%Y-%m-%d")

def _db_dt_aware(v):
    """Mongo (this client isn't tz-aware) hands datetimes back as naive UTC — make them aware so .astimezone(TZ) / .date() mean Myanmar time, not the server's or UTC."""
    if isinstance(v, datetime) and v.tzinfo is None:
        return pytz.utc.localize(v)
    return v

def _db_dt_to_tz_date(v):
    """The Myanmar calendar date of a stored datetime (see _db_dt_aware); non-datetimes pass through."""
    v = _db_dt_aware(v)
    return v.astimezone(TZ).date() if isinstance(v, datetime) else v

async def _chat_daily_bump(chat_id, user_id=None):
    """user_id None = a spawn was posted in chat_id; otherwise user_id caught one there. Never raises."""
    global _CHAT_STATS_SINCE_SET
    try:
        day = _chat_stats_day()
        inc = {"spawns": 1} if user_id is None else {"catches": 1, f"by_user.{user_id}": 1}
        await chat_daily_stats_col.update_one(
            {"_id": f"{day}:{chat_id}"},
            {"$inc": inc, "$setOnInsert": {"day": day, "chat_id": chat_id, "day_dt": datetime.now(TZ)}},
            upsert=True)
        if not _CHAT_STATS_SINCE_SET:
            _CHAT_STATS_SINCE_SET = True
            await bot_settings_col.update_one({"_id": "chat_stats_since"}, {"$setOnInsert": {"ts": time.time()}}, upsert=True)
    except Exception as e:
        print(f"⚠️ chat daily tally skipped ({type(e).__name__}: {e})")

def _limit_audit_render(users, stats, since_ts, titles, thr, ts0):
    """Pure text builder for /limitaudit -> list of HTML chunks (<= ~3800 chars each).
    users: rows with user_id/fullname/daily_catches/daily_limit_hit_at/premium_until and `today` = [{"c": chat_id, "t": caught_epoch}] (this user's catches made today, from their harem);
    stats: {chat_id: chat_daily_stats doc}; titles: {chat_id: title}."""
    head = [f"🔎 <b>LIMIT AUDIT</b> — today's catchers at <b>{thr}+</b> catches  ({len(users)} shown)"]
    if since_ts and since_ts > ts0:
        head.append(f"<i>⚠️ spawn/catch tally only started at {datetime.fromtimestamp(since_ts, TZ):%H:%M} today — 'spawns' below can be lower than the real number; the per-chat catch counts come from each user's own harem (copies they sold/traded since don't show).</i>")
    sections = []
    for u in users:
        uid = u["user_id"]
        name = escape_html(clean_display_name(u.get("fullname"), fallback=f"User {uid}"))
        mention = f"<a href='tg://user?id={uid}'>{name}</a>"
        crown = " 👑" if is_vip_active(u) else ""
        entries = [t for t in (u.get("today") or []) if isinstance(t, dict)]
        per_chat, times = {}, []
        for t in entries:
            per_chat[t.get("c")] = per_chat.get(t.get("c"), 0) + 1
            if isinstance(t.get("t"), (int, float)):
                times.append(t["t"])
        for cid, d in stats.items():                      # the live tally can only raise a count (a harem copy may have been sold since)
            n = (d.get("by_user") or {}).get(str(uid), 0)
            if n > per_chat.get(cid, 0):
                per_chat[cid] = n
        counter = u.get("daily_catches", 0)
        lines = [f"🚨 <b>{mention}</b>{crown} <code>{uid}</code> — counter <b>{counter}</b>"]
        hit = u.get("daily_limit_hit_at")
        if hit:
            lines[0] += f" · limit hit {_db_dt_aware(hit).astimezone(TZ):%H:%M}"
        if times:
            span = max(times) - min(times)
            lines.append(f"⏱ first <code>{datetime.fromtimestamp(min(times), TZ):%H:%M}</code> → last <code>{datetime.fromtimestamp(max(times), TZ):%H:%M}</code>"
                         f" ({len(times)} catches in {int(span // 3600)}h {int(span % 3600 // 60)}m)")
        if len(entries) < counter - 2:
            lines.append(f"📦 harem shows only <b>{len(entries)}</b> catches made today (counter says {counter}) — sold/traded/scrapped copies, <b>or a stale counter</b>")
        chats = sorted(per_chat.items(), key=lambda kv: -kv[1])
        if len(chats) == 1:
            lines.append("🚩 <b>every catch today was in ONE chat</b>")
        for cid, c in chats[:4]:
            d = stats.get(cid)
            title = escape_html(titles.get(cid) or "")
            row = f"   • <code>{cid}</code> {title}: caught <b>{c}</b>"
            if d and d.get("spawns"):
                sp = d["spawns"]
                row += f" of <b>{sp}</b> spawns"
                if sp >= 8 and c / sp >= 0.8:
                    row += " 🚩"
            elif d:
                row += " · spawns: 0 tallied"
            else:
                row += " · spawns: n/a (no tally for this chat today)"
            tot = (d or {}).get("catches")
            if tot:
                row += f" · chat total catches {tot} (they took {round(100 * c / tot)}%)"
            lines.append(row)
        if len(chats) > 4:
            lines.append(f"   … +{len(chats) - 4} more chats")
        sections.append("\n".join(lines))
    chunks, cur = [], "\n".join(head)
    for sec in sections:
        if len(cur) + len(sec) + 2 > 3800:
            chunks.append(cur)
            cur = sec
        else:
            cur += "\n\n" + sec
    chunks.append(cur)
    return chunks

_AUDIT_TITLES = {}

async def _audit_chat_title(chat_id):
    if chat_id in _AUDIT_TITLES:
        return _AUDIT_TITLES[chat_id]
    title = ""
    try:
        ent = await asyncio.wait_for(bot1.get_entity(chat_id), 4)
        title = getattr(ent, "title", "") or getattr(ent, "first_name", "") or ""
    except Exception:
        pass
    _AUDIT_TITLES[chat_id] = title
    return title

@bot1.on(events.NewMessage(pattern=own_pattern(r'(?i)^[/.](?:limitaudit|catchaudit)(?:@\w+)?(?:\s+(\d+))?(?:\s+(\d+))?$', 'bot1')))
async def limit_audit_cmd(event):
    """OWNER ONLY — who is at/above the daily catch limit TODAY, and WHERE they caught: per chat id -> their catches, that chat's spawns today, their share.
         /limitaudit            everyone at 22+ today (top 15)
         /limitaudit 10         everyone at 10+ today
         /limitaudit 10 30      …up to 30 people"""
    if event.sender_id != OWNER_ID:
        return
    thr = max(1, int(event.pattern_match.group(1))) if event.pattern_match.group(1) else DAILY_CATCH_LIMIT
    max_users = min(40, max(1, int(event.pattern_match.group(2)))) if event.pattern_match.group(2) else 15
    today_start = datetime.now(TZ).replace(hour=0, minute=0, second=0, microsecond=0)
    ts0 = today_start.timestamp()
    pipeline = [
        {"$match": {"daily_catches": {"$gte": thr}, "last_catch_date": {"$gte": today_start}}},
        {"$sort": {"daily_catches": -1}},
        {"$limit": max_users},
        {"$project": {"_id": 0, "user_id": 1, "fullname": 1, "daily_catches": 1, "daily_limit_hit_at": 1, "premium_until": 1,
                      "today": {"$map": {
                          "input": {"$filter": {"input": {"$ifNull": ["$harem", []]}, "as": "h",
                                                "cond": {"$and": [{"$gte": ["$$h.caught_date", ts0]},
                                                                  {"$ne": [{"$type": "$$h.chat_id"}, "missing"]}]}}},
                          "as": "t", "in": {"c": "$$t.chat_id", "t": "$$t.caught_date"}}}}},
    ]
    try:
        users = await users_catcher_col.aggregate(pipeline).to_list(length=max_users)
    except Exception as e:
        return await event.reply(f"❌ audit query failed: <code>{escape_html(f'{type(e).__name__}: {e}')}</code>", parse_mode='html')
    if not users:
        return await event.reply(f"✅ Today nobody is at <b>{thr}+</b> catches.", parse_mode='html')
    stats = {d["chat_id"]: d for d in await chat_daily_stats_col.find({"day": _chat_stats_day()}).to_list(length=None)}
    since_doc = await bot_settings_col.find_one({"_id": "chat_stats_since"})
    titles = {}
    for u in users:
        for t in (u.get("today") or []):
            cid = t.get("c") if isinstance(t, dict) else None
            if cid is not None and cid not in titles and len(titles) < 30:
                titles[cid] = await _audit_chat_title(cid)
    for chunk in _limit_audit_render(users, stats, (since_doc or {}).get("ts"), titles, thr, ts0):
        await event.reply(chunk, parse_mode='html', link_preview=False)

# ---- CATCH LOGIC (with daily limit and spawn_count increment on success) ----
DAILY_CATCH_LIMIT = 22  # flat cap for everyone — single source of truth, used by both the
# limit check in catch_handler and the /today "who hit the limit first" ranking below.

async def perform_catch(chat_id, user_id, spawn_data, event, reply_to_msg=None, is_callback=False, temp_msg_id=None, temp_client=None, second_event=None, second_uid=None):
    """Grants the catch reward. IMPORTANT: by the time this is called, catch_handler has
    already atomically marked spawn_data['claimed'] = True under spawn_locks[chat_id] —
    that's the actual "who wins" decision. This function no longer re-checks or re-locks
    that; it assumes the caller already won and just needs the reward + message sent.
    (This split is what fixes the freeze/spam under simultaneous catches — see catch_handler.)"""
    try:
        # 🛡️ DEFENSE-IN-DEPTH (per owner report — "gbanned players still able to win a …
        banned, _ban_rec = is_gbanned(user_id)
        if banned:
            async with spawn_locks[chat_id]:
                still_current = active_group_spawns.get(chat_id)
                if still_current is spawn_data and still_current.get("claimed_by") == user_id:
                    still_current["claimed"] = False
                    still_current["claimed_by"] = None
            print(f"⚠️ perform_catch aborted — user {user_id} is gbanned. Spawn handed back.")
            return
        # 🩹 FIX: mention/plain_name/ensure_user_registered used to run BEFORE this try block, …
        mention = await get_html_mention(event, user_id)
        plain_name = await get_plain_name(event, user_id)
        await ensure_user_registered(user_id, plain_name)
        # Update user: add card, increment total, balance, group catches, and daily catches.
        # find_one_and_update (not update_one) so we get the POST-increment daily_catches
        # back atomically, with no separate read that could race against another catch.
        updated_user = await users_catcher_col.find_one_and_update(
            {"user_id": user_id},
            {
                "$push": {
                    "harem": {
                        "char_id": spawn_data['char_id'],
                        "caught_date": time.time(),
                        "rarity": spawn_data['rarity'],
                        "status": "vault",
                        "chat_id": chat_id
                    }
                },
                "$inc": {
                    "total_caught": 1,
                    "star_balance": catch_total_star_reward(spawn_data['rarity']),
                    f"group_catches.{str(chat_id)}": 1,
                    "daily_catches": 1
                },
                "$set": {"fullname": plain_name, "last_catch_date": datetime.now(TZ)}
            },
            upsert=True,
            return_document=ReturnDocument.AFTER
        )
        await settle_star_debt(user_id)
        asyncio.create_task(_chat_daily_bump(chat_id, user_id))
        # Record exactly when this user's daily_catches first reached today's cap — this is
        # what /today's leaderboard sorts by ("who hit the limit first"). daily_catches only
        # ever moves up by 1 and is reset to 0 (with daily_limit_hit_at unset) at the start of
        # each new day — see the day-rollover check in catch_handler below — so the update
        # that brings it to exactly the user's own cap (VIP_DAILY_CATCH_LIMIT for VIP,
        # DAILY_CATCH_LIMIT otherwise) is the one and only moment that happens today, and the
        # $exists guard makes the write itself idempotent too.
        effective_limit = VIP_DAILY_CATCH_LIMIT if is_vip_active(updated_user) else DAILY_CATCH_LIMIT
        if updated_user and updated_user.get("daily_catches") == effective_limit:
            await users_catcher_col.update_one(
                {"user_id": user_id, "daily_limit_hit_at": {"$exists": False}},
                {"$set": {"daily_limit_hit_at": datetime.now(TZ)}}
            )
        # ✅ Increment spawn_count ONLY on successful catch
        await characters_base_col.update_one(
            {"char_id": spawn_data['char_id']},
            {"$inc": {"spawn_count": 1}}
        )
        # 🆕 (2026-11, owner request) SECOND collector (GOLDENMOON and below): same card + same Star reward, written in its own try so a hiccup here can never cost the winner their catch.
        second_user = None
        second_mention = None
        second_newly = []
        if second_uid:
            try:
                second_mention = await get_html_mention(second_event, second_uid)
                _s_name = await get_plain_name(second_event, second_uid)
                await ensure_user_registered(second_uid, _s_name)
                second_user = await users_catcher_col.find_one_and_update(
                    {"user_id": second_uid},
                    {
                        "$push": {"harem": {"char_id": spawn_data['char_id'], "caught_date": time.time(), "rarity": spawn_data['rarity'],
                                            "status": "vault", "chat_id": chat_id}},
                        "$inc": {"total_caught": 1,
                                 "star_balance": catch_total_star_reward(spawn_data['rarity']),
                                 f"group_catches.{str(chat_id)}": 1, "daily_catches": 1},
                        "$set": {"fullname": _s_name, "last_catch_date": datetime.now(TZ)}
                    },
                    upsert=True, return_document=ReturnDocument.AFTER
                )
                await settle_star_debt(second_uid)
                asyncio.create_task(_chat_daily_bump(chat_id, second_uid))
                _s_limit = VIP_DAILY_CATCH_LIMIT if is_vip_active(second_user) else DAILY_CATCH_LIMIT
                if second_user and second_user.get("daily_catches") == _s_limit:
                    await users_catcher_col.update_one({"user_id": second_uid, "daily_limit_hit_at": {"$exists": False}},
                                                       {"$set": {"daily_limit_hit_at": datetime.now(TZ)}})
                await characters_base_col.update_one({"char_id": spawn_data['char_id']}, {"$inc": {"spawn_count": 1}})
                second_newly = await check_and_award_achievements(second_uid)
            except Exception as _s_err:
                print(f"perform_catch: second collector failed: {type(_s_err).__name__}: {_s_err}")
                second_user = None
                second_mention = None
        asyncio.create_task(wishlist_progress_notify(spawn_data['char_id'], exclude=(user_id, second_uid)))      # ❤️ ULTRA/SUPREME: tell the wishlisters the count moved
        character_name = spawn_data['name']
        if ARTIST_COLLECT_REWARD_ENABLED:
            asyncio.create_task(_maybe_reward_artist_for_collect(spawn_data.get('artist'), mention, character_name, spawn_data['char_id']))
        newly_earned = await check_and_award_achievements(user_id)
        rarity_tier = classify_rarity(spawn_data['rarity'])
        rarity_emoji = RARITY_EMOJI.get(rarity_tier, RARITY_DEFAULT_EMOJI)
        rarity_name = RARITY_DISPLAY_NAME.get(rarity_tier, rarity_tier)
        # 👑 VIP catchers get a flashier catch card than everyone else — a banner up top,
        # a crown next to their name, and the 🎃🐢 pair — so a VIP catch visibly stands out
        # in the group.
        is_catcher_vip = is_vip_active(updated_user)
        # 💎 (2026-11, per owner request): the VIP catch header starts with "VIP USER" and uses the pretty emoji (👑 ✨ 💎 — all three have custom-emoji IDs)
        vip_banner = f"💎✨ <b>{sans_bold_italic('VIP USER')}</b> ✨💎\n" if is_catcher_vip else ""
        vip_crown = " 👑" if is_catcher_vip else ""

        # 🩹 NEW (per owner request — reference template provided): "(owned/total)" progress …
        category = spawn_data.get('category') or 'Unknown Series'
        owned_char_ids = list({
            item.get("char_id") for item in updated_user.get("harem", [])
            if isinstance(item, dict) and item.get("char_id")
        })
        owned_in_category = await characters_base_col.count_documents(
            {"category": category, "char_id": {"$in": owned_char_ids}}
        )
        category_totals = await get_category_totals_cached()
        category_total = category_totals.get(category, owned_in_category)
        progress_txt = f"<code>{owned_in_category}/{category_total}</code>"
        if second_user:
            _s_ids = list({it.get("char_id") for it in second_user.get("harem", []) if isinstance(it, dict) and it.get("char_id")})
            _s_owned = await characters_base_col.count_documents({"category": category, "char_id": {"$in": _s_ids}})
            progress_txt += f" · <code>{_s_owned}/{category_total}</code>"

        # 🎉 NEW (2026-11, per owner request): the card's EVENT on the catch message, when it has one — read the same two ways /check reads it
        # (an ULTRA event kind + an owner-made custom event). A dict lookup in the in-memory roster (already warm from the call above), not a
        # DB query; and wrapped so that a hiccup here can never cost the player their catch message.
        event_line = ""
        try:
            _ev_doc = await get_character_by_id_cached(spawn_data['char_id'])
            _ev_text = (" | ".join(x for x in (event_label_of(_ev_doc), escape_html(custom_event_label_of(_ev_doc) or "")) if x)
                        if _ev_doc else "")
            if _ev_text:
                event_line = f"🎉 E{small_caps('vent')}: {_ev_text}\n"
        except Exception as _ev_err:
            print(f"perform_catch: event lookup skipped: {type(_ev_err).__name__}: {_ev_err}")

        # 🩹 REDESIGNED (2026-08, per owner request — reference template provided): fancy-font …
        _both = (f"{mention}{vip_crown} {small_caps('and')} {second_mention}{' 👑' if is_vip_active(second_user) else ''}"
                 if second_user else f"{mention}{vip_crown}")
        _reward_txt = format_star_plain(catch_total_star_reward(spawn_data['rarity'])) + (" each" if second_user else "")
        _reward_line = f"💰 +{_reward_txt}\n" if catch_total_star_reward(spawn_data['rarity']) else ""      # no Star payout -> no "💰 +⭐" line
        success_msg = (
            f"{vip_banner}"
            f"🪷 {_both}, {small_caps('you collected a new character')}!\n\n"
            f"🫧 N{small_caps('ame')}: <b>{escape_html(character_name)}</b>"
            f" | 🐧 <code>{display_char_id(spawn_data['char_id'])}</code>\n"
            f"{rarity_emoji} {sans_bold_italic('RARITY')}: {rarity_name}\n"
            f"{event_line}"
            f"🏖️ A{small_caps('nime')}: {escape_html(category)} ({progress_txt})\n"
            f"{artist_line(spawn_data.get('artist'))}"
            f"{_reward_line}\n"
            f"👒 {small_caps('check your')} <code>/harem</code>!"
        )

        success_msg += format_achievement_unlocks(newly_earned)
        if second_user and second_newly:
            success_msg += format_achievement_unlocks(second_newly)
        # 🩹 CHANGED (per owner request): the old buttons here were "🐇Collections" (switch_inline …
        _first_btn = (colored_button("🛒 Daily Shop", "dshopopen", color="success") if await daily_shop_is_active()
                      else Button.inline(f"🔍 Check #{display_char_id(spawn_data['char_id'])}", data=f"checkcard_{spawn_data['char_id']}"))
        # 🔥 CHANGED (2026-11, owner request): "💰 Balance" -> "🔥 Sell" (scrap this catch's card right away). Two collectors = one Sell button each.
        _cid = spawn_data['char_id']
        _sell_btns = ([Button.inline("🔥 Sell #1", data=f"catchsell_{user_id}_{_cid}"), Button.inline("🔥 Sell #2", data=f"catchsell_{second_uid}_{_cid}")]
                      if second_user else [Button.inline("🔥 Sell", data=f"catchsell_{user_id}_{_cid}")])
        success_buttons = [[_first_btn] + _sell_btns]
        # ♻️ NEW (2026-09, per owner request): only shown when THIS catch was itself a …
        _dupe_copies = sum(
            1 for it in updated_user.get("harem", [])
            if isinstance(it, dict) and it.get("char_id") == spawn_data['char_id'] and it.get("status") == "vault"
        )
        if _dupe_copies > 1:
            success_buttons.append([colored_button("♻️ Bulk Scrap Dupes", data=f"bscrap_o_{user_id}", color="danger")])
        # 🆕 Remember who won BEFORE the spawn entry disappears (same synchronous block as the
        # delete below — no await in between — so a late /obtain can never land in a gap where
        # neither the live spawn nor this record exists). See catch_handler's
        # "chat_id not in active_group_spawns" branch for where it's read.
        last_caught_spawns[chat_id] = {
            "name": spawn_data["name"],
            "char_id": spawn_data["char_id"],
            "claimed_by": user_id,
            "also_by": second_uid if second_user else None,
            "ts": time.time(),
        }
        if chat_id in active_group_spawns: del active_group_spawns[chat_id]
        if chat_id in spawn_locks: del spawn_locks[chat_id]
        # 📋 ULTRA / SUPREME collected -> detailed note in the storage group (which chat, which card, who) — see
        # log_rare_catch_to_storage. Runs in the background; the player's own result message below is not delayed.
        if rarity_tier in RARE_SPAWN_DAILY_CAPS:
            asyncio.create_task(log_rare_catch_to_storage(chat_id, user_id, spawn_data, mention, rarity_tier, updated_user.get("total_caught", 0)))
        if is_callback:
            await bot1.send_message(chat_id, success_msg, reply_to=reply_to_msg or event.message_id, parse_mode='html', buttons=success_buttons)
        elif temp_msg_id:
            # 🩹 Edit the 🐛→🦋 catching-animation message into the final result in place, …
            _tc = temp_client or bot1
            try:
                await _tc.edit_message(chat_id, temp_msg_id, success_msg, parse_mode=_pm(_tc), buttons=success_buttons)
            except errors.MessageNotModifiedError:
                pass
            except Exception:
                # Edit failed for some other reason (e.g. message too old) — make sure the
                # player still sees their result rather than silently losing it.
                await event.reply(success_msg, parse_mode='html', buttons=success_buttons)
        else:
            await event.reply(success_msg, parse_mode='html', buttons=success_buttons)
        return True
    except Exception as e:
        # NOTE: we deliberately do NOT reset claimed=False here. This spawn was already
        # atomically handed to this user in catch_handler — reopening it after a failure
        # (e.g. a Telegram flood-wait mid-flow) is exactly how two people could end up
        # winning the same character. Instead we clear the spawn out so the game doesn't
        # get stuck, log the fault, and let the next spawn come normally.
        if chat_id in active_group_spawns: del active_group_spawns[chat_id]
        if chat_id in spawn_locks: del spawn_locks[chat_id]
        error_msg = f"❌ <b>Catch Logic Fault:</b> {e}"
        if is_callback:
            await bot1.send_message(chat_id, error_msg, parse_mode='html')
        else:
            await event.reply(error_msg, parse_mode='html')
        return False

CATCH_USAGE_TEXT = (
    "📌 <b>Usage:</b> <code>/coll [Character Name]</code>\n"
    "<i>Reply with /who to reveal a spawn, then use the exact name shown, "
    "or just tap the inline button.</i>"
)

# 🎯 CATCH_RACE_JUDGE_WINDOW — 2026-08, per owner report (repeated, and confirmed via …
CATCH_RACE_JUDGE_WINDOW = 0.6
# 🩹 CHANGED (2026-10, per owner request — "catch animation နည်နည်းကြာပေးပါ"): seconds each of the 3 catch-animation frames
# (⚡️ → 💥 → ✨) stays up before the result replaces it. Was 0.8 (2.4s total); now 1.1 (3.3s). Safe to change freely: by the time
# the animation starts the winner is already decided and the spawn claimed, so late /obtain messages just get "too slow".
CATCH_ANIMATION_FRAME_DELAY = 1.1

# 🩹 (per owner request) RACE FIX: the judge below used to look at ONE racer only — the earliest. If that person …
def _catch_user_blocked(user_id):
    """Sync + in-memory. True while the user is spam-muted or gbanned."""
    if user_id in user_mute_until and time.time() < user_mute_until[user_id]:
        return True
    return bool(is_gbanned(user_id)[0])

# A spam-muted player's /obtain used to be ignored in total silence, so they thought the bot was broken. They now
# get ONE short notice with the time left (+ the clock time it ends), throttled per person so mashing /obtain
# can't turn the notice itself into spam, and it deletes itself after a while.
CATCH_MUTE_NOTICE_COOLDOWN = 15   # seconds — at most one notice per muted person per window
CATCH_MUTE_NOTICE_TTL = 30        # seconds until the notice deletes itself
_catch_mute_notice_last = {}      # user_id -> ts

def _fmt_mute_left(seconds):
    """Pure. 372 -> '6m 12s', 45 -> '45s', 4000 -> '1h 06m' (rounded up, never shows 0)."""
    seconds = max(1, int(seconds) + (0 if float(seconds).is_integer() else 1))
    h, rem = divmod(seconds, 3600)
    m, sec = divmod(rem, 60)
    if h:
        return f"{h}h {m:02d}m"
    if m:
        return f"{m}m {sec:02d}s"
    return f"{sec}s"

async def _send_catch_block_notice(event, user_id):
    """Tells a spam-MUTED racer why their /obtain was ignored and when it ends. Sent as a plain message, not a
    reply — a muted player's command may already be deleted by the spam handler, and replying to a deleted
    message fails. gbanned racers get nothing here (gban_block_gate already showed them the ban text).
    Never raises."""
    try:
        now = time.time()
        if is_gbanned(user_id)[0]:
            return
        until = user_mute_until.get(user_id, 0)
        if now >= until:
            return
        if now - _catch_mute_notice_last.get(user_id, 0) < CATCH_MUTE_NOTICE_COOLDOWN:
            return
        _catch_mute_notice_last[user_id] = now   # set BEFORE any await — concurrent /obtain messages must not double-send
        if len(_catch_mute_notice_last) > 5000:
            for k in [k for k, ts in _catch_mute_notice_last.items() if now - ts > 300]:
                _catch_mute_notice_last.pop(k, None)
        mention = await get_html_mention(event, user_id)
        end_clock = datetime.fromtimestamp(until, TZ).strftime("%H:%M")
        msg = await bot1.send_message(
            event.chat_id,
            bq(f"⏳ {mention}, /coll is paused for you right now — it unlocks in "
               f"<code>{_fmt_mute_left(until - now)}</code> (≈ {end_clock})."),
            parse_mode='html')
        asyncio.create_task(_delete_after_delay(bot1, event.chat_id, msg.id, delay=CATCH_MUTE_NOTICE_TTL))
    except Exception as _e:
        print(f"⚠️ catch block notice failed for {user_id}: {type(_e).__name__}: {_e}")

async def _catch_eligibility(event, user_id):
    """Can this racer actually take the spawn right now? Returns (status, notice_text):
         ("ok", None)       — free to catch
         ("blocked", None)  — spam-muted / gbanned: skipped (the judge sends muted ones _send_catch_block_notice)
         ("capped", text)   — hit their daily limit: skipped, with the usual 'come back tomorrow' text
    Never claims or changes the spawn."""
    if _catch_user_blocked(user_id):
        return "blocked", None
    user_doc = await users_catcher_col.find_one({"user_id": user_id})
    if user_doc:
        today = datetime.now(TZ).date()
        last_catch_date = user_doc.get("last_catch_date")
        if last_catch_date:
            # 🩹 FIX (2026-11): Mongo hands last_catch_date back as a naive UTC datetime, so .date() was the UTC date while `today` is the Myanmar date — for the 6½ hours
            # after Myanmar midnight (00:00-06:30) the two never matched, so the counter was zeroed again on EVERY catch attempt (the daily limit could not trigger).
            # Both are Myanmar dates now.
            last_date = _db_dt_to_tz_date(last_catch_date)
            if last_date != today:
                await users_catcher_col.update_one(
                    {"user_id": user_id},
                    {"$set": {"daily_catches": 0, "last_catch_date": datetime.now(TZ)},
                     "$unset": {"daily_limit_hit_at": ""}}
                )
                user_doc["daily_catches"] = 0
        daily_catches = user_doc.get("daily_catches", 0)
        daily_limit = VIP_DAILY_CATCH_LIMIT if is_vip_active(user_doc) else DAILY_CATCH_LIMIT
        if daily_catches >= daily_limit:
            mention = await get_html_mention(event, user_id)
            return "capped", (
                f"<b>Notice:</b> {mention}, you've reached your daily catch limit of {daily_limit}! "
                f"That's enough for today. Come back tomorrow. 🌟"
            )
    return "ok", None

# 🩹 CHANGED (per owner request): /collect renamed to /obtain — /collect is also a command …
@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.](?:coll|morgan|obtain)(?:@\w+)?\s+(.*)$', 'bot1')))
async def catch_handler(event):
    if event.is_private: return
    user_id = event.sender_id
    chat_id = event.chat_id
    # Check spam mute — GLOBALLY, across every group.
    if user_id in user_mute_until and time.time() < user_mute_until[user_id]:
        await _send_catch_block_notice(event, user_id)
        return
    
    catch_name = event.pattern_match.group(1).strip()
    if not catch_name:
        return await event.reply(CATCH_USAGE_TEXT, parse_mode='html')

    # ==========================================
    # 🛸 NORMAL SPAWN CATCH LOGIC
    # ==========================================
    if chat_id not in active_group_spawns:
        # 🆕 (per owner request): the spawn is already over and caught. If SOMEONE ELSE types …
        last = last_caught_spawns.get(chat_id)
        if last and last.get("claimed_by") != user_id and last.get("also_by") != user_id and normalize_name(catch_name) == normalize_name(last.get("name")):
            _queue_too_late(event, last)   # batched with the other losers — see _flush_too_late
            return
        return await event.reply(f"🛸 <b>Nothing to collect here!</b>", parse_mode='html')
    
    spawn_data = active_group_spawns[chat_id]
    if spawn_data["claimed"]:
        _queue_too_late(event, spawn_data)   # batched with the other losers — see _flush_too_late
        return
    
    if time.time() - spawn_data["spawn_time"] > 300:
        if chat_id in active_group_spawns: 
            del active_group_spawns[chat_id]
        return await event.reply(f"⏱️ <b>Too late! They've slipped away.</b>", parse_mode='html')
    
    if normalize_name(catch_name) != normalize_name(spawn_data["name"]):
        return await event.reply(f"❌ <b>Wrong name! Use the exact name shown in /who.</b>", parse_mode='html')

    # 🎯 Buffer this valid attempt and judge the whole race by real Telegram message-ID order
    # once the window closes — see CATCH_RACE_JUDGE_WINDOW's docstring for why. Every racer's
    # task lands here; only the FIRST one to arrive (task-scheduling order doesn't matter for
    # THIS part — it's just "who gets stuck holding the judging job", not who wins) actually
    # runs the code below the `if`. Everyone else just adds themselves to the buffer and
    # returns — the judge replies to them (win or lose) on their behalf once it decides.
    existing_buf = catch_race_buffer.get(chat_id)
    if existing_buf is not None:
        existing_buf.append((event, user_id))
        return
    buf = [(event, user_id)]
    catch_race_buffer[chat_id] = buf
    try:
        await asyncio.sleep(CATCH_RACE_JUDGE_WINDOW)
    finally:
        # try/finally so a stuck buffer entry (which would silently swallow every future
        # /obtain in this chat — see the `if existing_buf is not None` check above) can never
        # survive an unexpected error here.
        candidates = catch_race_buffer.pop(chat_id, buf)

    # Earliest real Telegram message ID = whoever actually sent /obtain first, full stop —
    # independent of network jitter, DB round trips, or asyncio scheduling on the bot's side.
    candidates.sort(key=lambda c: c[0].id)

    # 🔒 Claim the spawn atomically — check-and-set with no await in between, under the per-chat lock — for the
    # WHOLE judging below, so a late /obtain arriving while the racers are sorted out can't grab it. claimed_by
    # stays None until we know who really gets it. (This also guards against the spawn having been claimed some
    # other way in the meantime — expiry cleanup, owner command, etc.)
    async with spawn_locks[chat_id]:
        spawn_data = active_group_spawns.get(chat_id)
        if not spawn_data or spawn_data.get("claimed"):
            for loser_event, _loser_uid in candidates:
                _queue_too_late(loser_event, spawn_data)
            return
        spawn_data["claimed"] = True
        spawn_data["claimed_by"] = None

    # 🩹 FIX (owner report — "when the FIRST racer is at their limit / muted / banned, everybody behind them is …
    winner_idx = None
    try:
        status_by_uid = {}   # one DB check per person, even if they typed /obtain twice
        for idx, (cand_event, cand_uid) in enumerate(candidates):
            if cand_uid in status_by_uid:
                continue   # their earlier message already decided it (and, if capped, already notified)
            try:
                status, notice = await _catch_eligibility(cand_event, cand_uid)
            except Exception as _e:
                print(f"⚠️ catch eligibility check failed for {cand_uid}: {type(_e).__name__}: {_e}")
                status, notice = "error", None
            status_by_uid[cand_uid] = status
            if status == "ok":
                winner_idx = idx
                break
            if status == "blocked":
                asyncio.create_task(_send_catch_block_notice(cand_event, cand_uid))
            elif notice:
                async def _send_notice(ev=cand_event, text=notice):
                    try:
                        await ev.reply(text, parse_mode='html')
                    except Exception:
                        pass
                asyncio.create_task(_send_notice())
    except BaseException:
        spawn_data["claimed"] = False
        spawn_data["claimed_by"] = None
        raise

    if winner_idx is None:
        # nobody could take it — give the spawn back instead of wasting it
        async with spawn_locks[chat_id]:
            if active_group_spawns.get(chat_id) is spawn_data and spawn_data.get("claimed_by") is None:
                spawn_data["claimed"] = False
        return

    winner_event, user_id = candidates[winner_idx]
    spawn_data["claimed_by"] = user_id
    # 🆕 (2026-11, owner request) GOLDENMOON and below: the next eligible racer behind the winner also gets a copy.
    second_event, second_uid = None, None
    if classify_rarity(spawn_data.get("rarity", "")) in SECOND_COLLECTOR_TIERS:
        for _c in candidates[winner_idx + 1:]:
            if _c[1] == user_id:
                continue
            try:
                _st, _ = await _catch_eligibility(_c[0], _c[1])
            except Exception as _e:
                print(f"⚠️ second-collector eligibility check failed for {_c[1]}: {type(_e).__name__}: {_e}")
                _st = "error"
            if _st == "ok":
                second_event, second_uid = _c
                spawn_data["second_claimed_by"] = second_uid
                break
    # Racers who typed it AFTER the winner lose this race (muted ones get their notice instead of "too slow").
    losers = []
    for _c in candidates[winner_idx + 1:]:
        if _c[1] == user_id or _c[1] == second_uid:
            continue
        if _catch_user_blocked(_c[1]):
            asyncio.create_task(_send_catch_block_notice(_c[0], _c[1]))
        else:
            losers.append(_c)

    # Tell everyone who lost this specific race exactly who beat them — fired once the winner's own catch flow
    # has actually finished below, not here (see the try block around perform_catch further down), so
    # "too slow" never lands in the group before the winner's own success message has gone out.
    event = winner_event  # everything below acts on behalf of the judged winner

    # 🐛→🦋 catching animation: one message, edited in place frame-by-frame — no extra …
    temp_client = bot1
    temp_msg = None
    if temp_msg is None:
        temp_msg = await bot1.send_message(chat_id, "⚡️")
        temp_client = bot1
    await asyncio.sleep(CATCH_ANIMATION_FRAME_DELAY)
    # An animation frame is cosmetic: if an edit is refused for any reason, skip the frame — never let it abort the catch.
    try:
        await temp_msg.edit("💥", parse_mode=_pm(temp_client))
    except Exception:
        pass
    await asyncio.sleep(CATCH_ANIMATION_FRAME_DELAY)
    try:
        await temp_msg.edit("✨", parse_mode=_pm(temp_client))
    except Exception:
        pass
    await asyncio.sleep(CATCH_ANIMATION_FRAME_DELAY)
    # 🩹 FIX (per owner report — "sometimes only the 2 emoji show, no success message"): this …
    try:
        await perform_catch(chat_id, user_id, spawn_data, event, reply_to_msg=event.id, is_callback=False, temp_msg_id=temp_msg.id, temp_client=temp_client, second_event=second_event, second_uid=second_uid)
        # 🩹 CHANGED (per owner request): losers now get told "Too slow! X got it first" only
        # AFTER X's own success message has actually landed — fired off concurrently from here
        # so it doesn't block anything further, but never before this point.
        for loser_event, _loser_uid in losers:
            _queue_too_late(loser_event, spawn_data)
    except Exception as e:
        if chat_id in active_group_spawns:
            del active_group_spawns[chat_id]
        if chat_id in spawn_locks:
            del spawn_locks[chat_id]
        error_msg = f"❌ <b>Catch Logic Fault:</b> {escape_html(str(e))}"
        try:
            await temp_client.edit_message(chat_id, temp_msg.id, error_msg, parse_mode=_pm(temp_client))
        except Exception:
            await event.reply(error_msg, parse_mode='html')
    finally:
        # The winner's announcement is out (or failed for good): the batched "too late" message may now go.
        # Set AFTER the losers above were queued, so they land in the same batch as any early stragglers.
        spawn_data["announced"] = True

# 🩹 REDESIGNED (2026-09, per owner request — "make the race-loser message cooler"): same …
_RACE_LOSER_LINES = [
    ("🐸", "Too slow!",       "{m} got it first"),
    ("💨", "Not this time!",  "{m} grabbed it first"),
    ("🫧", "Oop, too late!",  "{m} already took it home"),
    ("🐾", "Nice try!",       "{m} was faster"),
]

async def _reply_already_caught(event, spawn_data):
    """Tells whoever lost the race exactly who beat them (or, if the winner isn't known, just
    that it's already gone) — replaces the old generic 'Already caught!' which left everyone
    guessing."""
    winner_id = (spawn_data or {}).get("claimed_by")
    if winner_id:
        mention = await get_html_mention(event, winner_id)
        emoji, title, line = random.choice(_RACE_LOSER_LINES)
        # Split around the {m} placeholder so only the surrounding words get small-caps —
        # the mention itself is a real link and must stay untouched.
        before, _, after = line.partition("{m}")
        sentence = f"{small_caps_full(before)}{mention}{small_caps_full(after)}"
        text = f"{emoji} {sans_bold_italic(title)}\n{sentence}"
    else:
        text = f"🐸 {sans_bold_italic('Too slow!')}\n{small_caps_full('someone already caught it')}"
    return await event.reply(text, parse_mode='html')

# 🩹 CHANGED (per owner request): with 5 racers the bot used to post FOUR separate "too slow" replies, one per …
TOO_LATE_BATCH_WINDOW = 1.0   # seconds
TOO_LATE_MAX_NAMES = 15       # beyond this: "... and N more" (keeps the message and the pings sane)
_too_late_groups = {}         # chat_id -> {"spawn": spawn_data, "users": {user_id: event}}

def _queue_too_late(event, spawn_data):
    """Sync — adds this loser to the chat's pending 'too late' batch (one entry per person)."""
    chat_id = event.chat_id
    grp = _too_late_groups.get(chat_id)
    if grp is None:
        grp = {"spawn": spawn_data, "users": {}}
        _too_late_groups[chat_id] = grp
        asyncio.create_task(_flush_too_late(chat_id, grp))
    grp["users"].setdefault(event.sender_id, event)

def _join_mentions(mentions):
    """Pure. ['a'] -> 'a' | ['a','b'] -> 'a and b' | ['a','b','c'] -> 'a, b and c'."""
    if len(mentions) <= 1:
        return "".join(mentions)
    return ", ".join(mentions[:-1]) + " and " + mentions[-1]

async def _flush_too_late(chat_id, grp):
    sp = grp["spawn"]
    try:
        await asyncio.sleep(TOO_LATE_BATCH_WINDOW)
        waited = 0.0
        while sp is not None and sp.get("claimed") and not sp.get("announced") and waited < 8.0:
            await asyncio.sleep(0.25)
            waited += 0.25
    finally:
        _too_late_groups.pop(chat_id, None)   # anyone queued from now on starts a fresh batch
    try:
        winner_id = (sp or {}).get("claimed_by")
        if sp is not None and not sp.get("claimed") and winner_id is None:
            return   # the spawn was handed back (nobody could take it) — nothing to be "too late" for
        _second_id = (sp or {}).get("second_claimed_by")
        users = [(uid, ev) for uid, ev in grp["users"].items() if uid != winner_id and uid != _second_id]
        if not users:
            return
        if len(users) == 1:
            await _reply_already_caught(users[0][1], sp)   # 2-person race: the file's own short reply
            return
        shown = users[:TOO_LATE_MAX_NAMES]
        mentions = [await get_html_mention(ev, uid) for uid, ev in shown]
        if len(users) > len(shown):
            names = ", ".join(mentions) + f" and {len(users) - len(shown)} more"
        else:
            names = _join_mentions(mentions)
        by = f" {small_caps_full('by')} {await get_html_mention(users[0][1], winner_id)}" if winner_id else ""
        _late_text = f"Hii {names}, 😭 You all too late, {small_caps_full(chr(105) + chr(39) + 've already been obtained')}{by}"
        _late_sent = None
        if _late_sent is None:
            await bot1.send_message(chat_id, _late_text, parse_mode='html')
    except Exception as e:
        print(f"⚠️ too-late batch failed: {type(e).__name__}: {e}")

