@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]harem(?:@\w+)?(?:\s+(.*))?$', 'bot1')))
async def show_harem_vault(event):
    # 🩹 CHANGED (per owner request): /harem used to let anyone view someone ELSE's vault by
    # replying to their message or passing @username/user_id — that's removed now. /harem
    # always shows the sender's own vault, full stop. Any argument/reply is simply ignored.
    user_id = event.sender_id
    _t_pre = time.perf_counter()
    try:     # how long after Telegram stamped the message did this handler even start? (queueing / update lag shows up here)
        _lag = time.time() - event.message.date.timestamp()
    except Exception:
        _lag = 0.0
    plain_name = await get_plain_name(event, user_id)
    await ensure_user_registered(user_id, plain_name)
    _pre = time.perf_counter() - _t_pre
    if _lag >= 3.0 or _pre >= 1.5:
        print(f"🐢 /harem in {event.chat_id}: handler started {_lag:.1f}s after the message was sent; "
              f"name lookup + registration took {_pre:.1f}s")
    await send_paginated_harem(bot1,
                               event.chat_id, user_id, page=1, viewer_id=user_id)

# ==========================================
# 👑 /addowner · /removeowner · /owners  (OWNER_ID only)
# ==========================================
# Owner mode = the Complete Collection VIEW (see is_owner_mode) + the real-catches gallery. Deliberately NOT a gifting
# privilege: gift/trade/fav all keep checking the grantee's REAL harem, so they can only pass on cards they truly own.
async def _resolve_owner_target(event, arg):
    """Reply -> that message's sender; else a numeric user id; else @username. Returns (user_id, error_html_or_None)."""
    if event.is_reply:
        reply_msg = await event.get_reply_message()
        uid = reply_msg.sender_id if reply_msg else None
        if uid:
            return uid, None
    if arg:
        arg = arg.strip()
        if arg.isdigit():
            return int(arg), None
        try:
            ent = await bot1.get_entity(arg if arg.startswith("@") else "@" + arg)
            return ent.id, None
        except Exception:
            return None, "❌ <b>Couldn't find that user.</b> Reply to their message, or use their numeric ID."
    return None, "❌ <b>Reply to the user</b>, or give their ID / @username."

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]addowner(?:@\w+)?(?:\s+(\S+))?$', 'bot1')))
async def add_owner_handler(event):
    if event.sender_id != OWNER_ID:
        return
    target_id, err = await _resolve_owner_target(event, event.pattern_match.group(1))
    if err:
        return await event.reply(err, parse_mode='html')
    if target_id == OWNER_ID:
        return await event.reply("❌ <b>That's already the Owner.</b>", parse_mode='html')
    if target_id in bot_ids:
        return await event.reply("❌ <b>Can't add a bot.</b>", parse_mode='html')
    name = await get_plain_name(event, target_id)
    mention = f"<a href='tg://user?id={target_id}'><b>{escape_html(name)}</b></a>"
    if target_id in added_owner_ids:
        return await event.reply(f"ℹ️ {mention} already has Owner Mode.", parse_mode='html')
    try:
        await ensure_user_registered(target_id, name)
        await added_owners_col.update_one(
            {"user_id": target_id},
            {"$set": {"user_id": target_id, "fullname": name, "added_by": event.sender_id, "added_at": time.time()}},
            upsert=True
        )
    except Exception as e:
        return await event.reply(f"❌ <b>Couldn't save that:</b> <code>{escape_html(str(e))}</code>", parse_mode='html')
    added_owner_ids.add(target_id)
    await event.reply(
        f"👑 <b>Owner Mode granted</b> to {mention}\n\n"
        f"• /harem and the <code>harem.</code> inline gallery now show the <b>Complete Collection</b> (every character)\n"
        f"• Their real catches stay available under 🎯 My Real Catches\n"
        f"• Each card shows <i>Already Obtained? Yep / Nope</i>\n"
        f"• Gifting is <b>not</b> unlimited — they can only gift cards they really own",
        parse_mode='html'
    )

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.](?:removeowner|rmowner|delowner)(?:@\w+)?(?:\s+(\S+))?$', 'bot1')))
async def remove_owner_handler(event):
    if event.sender_id != OWNER_ID:
        return
    target_id, err = await _resolve_owner_target(event, event.pattern_match.group(1))
    if err:
        return await event.reply(err, parse_mode='html')
    name = await get_plain_name(event, target_id)
    mention = f"<a href='tg://user?id={target_id}'><b>{escape_html(name)}</b></a>"
    if target_id not in added_owner_ids:
        return await event.reply(f"ℹ️ {mention} doesn't have Owner Mode.", parse_mode='html')
    try:
        await added_owners_col.delete_one({"user_id": target_id})
    except Exception as e:
        return await event.reply(f"❌ <b>Couldn't remove that:</b> <code>{escape_html(str(e))}</code>", parse_mode='html')
    added_owner_ids.discard(target_id)
    await event.reply(f"✅ Owner Mode removed from {mention}. Their /harem is their real vault again.", parse_mode='html')

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]owners(?:@\w+)?$', 'bot1')))
async def list_owners_handler(event):
    if event.sender_id != OWNER_ID:
        return
    if not added_owner_ids:
        return await event.reply("👑 <b>No added owners yet.</b> Use /addowner (reply to someone).", parse_mode='html')
    docs = await added_owners_col.find({}, {"user_id": 1, "fullname": 1}).to_list(length=None)
    names = {d["user_id"]: d.get("fullname") for d in docs}
    lines = [f"• <a href='tg://user?id={uid}'><b>{escape_html(names.get(uid) or str(uid))}</b></a> · <code>{uid}</code>"
             for uid in sorted(added_owner_ids)]
    await event.reply(f"👑 <b>Added owners ({len(lines)})</b>\n\n" + "\n".join(lines), parse_mode='html')

