# ---- /fav with inline confirmation ----
FAV_NOTE_MAX_LEN = 150  # characters — same cap/reasoning as GIFT_NOTE_MAX_LEN

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]fav(?:@\w+)?\s+([a-zA-Z0-9_]+)(?:\s+(.+))?$', 'bot1')))
async def set_favorite_card(event):
    # ⭐ NEW (2026-09, per owner request — e.g. "/fav 1234 Sell" or "/fav 1234 ရောင်းမယ် vlt …
    user_id = event.sender_id
    raw_input = event.pattern_match.group(1).strip()
    fav_note = escape_html((event.pattern_match.group(2) or "").strip()[:FAV_NOTE_MAX_LEN])
    char_id_input = normalize_char_id_input(raw_input)

    # 🧣 EXCLUSIVE LIMITED (2026-11): /fav EX1 — own collection + own ownership rule, see part 4 (_exl_fav_prompt)
    _ex_id = exl_parse_id(char_id_input)
    if _ex_id:
        return await _exl_fav_prompt(event, user_id, _ex_id, fav_note)

    # ✅ Case-Insensitive ရှာဖို့
    card = await characters_base_col.find_one({
        "char_id": {"$regex": f"^{char_id_input}$", "$options": "i"}
    })

    if not card:
        return await event.reply("❌ <b>Card not found.</b>", parse_mode='html')

    # ✅ Card ကိုတွေ့ရင် ဆက်လုပ်ပါ
    actual_char_id = card["char_id"]  # Database ထဲက အတိအကျ ID

    if is_owner_mode(user_id):
        # 👑 Unlimited vault (OWNER_ID or an /addowner grantee) — every character counts as owned for /fav, whether
        # they hold a real copy or not: the favourite is just the card shown as their /harem thumbnail, so any card in
        # the Complete Collection can be picked. (Gifting/trading still need a REAL copy.)
        owns_card = True
    else:
        user_doc = await users_catcher_col.find_one({"user_id": user_id})
        user_harem = user_doc.get("harem", []) if user_doc else []
        owns_card = any(
            isinstance(x, dict) and (x.get("char_id") or "").upper() == actual_char_id.upper()
            for x in user_harem
        )

    # ❌ မပိုင်ရင် → Buy This Card flow
    if not owns_card:
        _buy_btn = [[colored_button(
            "🛒 Buy This Card",
            f"favbuy_menu_{user_id}_{actual_char_id}",
            color="primary"
        )]]
        return await event.reply(
            "❌ <b>You don't own this card.</b>",
            parse_mode='html',
            buttons=_buy_btn
        )

    # ✅ Confirmation Buttons
    # Card info in one compact group, artist on its own line only when the card actually has
    # one — no "Favourite Card Confirmation" title / "Waiting for your decision" footer (owner:
    # those read like a generic bot template).
    fav_rarity_emoji = RARITY_EMOJI.get(classify_rarity(card.get("rarity", "")), RARITY_DEFAULT_EMOJI)
    fav_artist = card.get("artist")
    fav_artist_line = f"\n\n🎨 {escape_html(str(fav_artist).strip())}" if fav_artist and str(fav_artist).strip() else ""
    if is_ultra_card(card):
        fav_artist_line = "\n\n" + ultra_credit_line(card, suffix="")      # 🎬 ULTRA: video-editor credit instead
    fav_note_preview = f"\n\n💬 <b>Note: {fav_note}</b>" if fav_note else ""
    confirm_text = (
        f"<b>🫧 Favourite this card?</b>\n\n"
        f"{fav_rarity_emoji} <b>{_rarity_label_plain(card.get('rarity', 'Unknown'))}</b>\n\n"
        f"<code>{escape_html(card['name'])}</code>\n"
        f"<code>{escape_html(card.get('category', '') or 'Unknown')}</code>\n"
        f"<code>{display_char_id(actual_char_id)}</code>"
        f"{fav_artist_line}"
        f"{fav_note_preview}"
    )
    if fav_note:
        pending_fav_notes[(user_id, actual_char_id)] = {"note": fav_note, "expiry": time.time() + 600}
    buttons = [
        [
            colored_button("✅ Yep, why not", f"fav_confirm_{user_id}_{actual_char_id}", color="success"),
            Button.inline("❌ Nope", data=f"fav_cancel_{user_id}_{actual_char_id}")
        ]
    ]
    # 🩹 FIX: this used to be event.reply(confirm_text, ...) with no `file=` at all — the …
    async def _send_fav_confirm(media):
        return await event.reply(confirm_text, file=media, buttons=buttons, parse_mode='html')
    sent = None
    if sent is None:
        sent = await send_with_char_media(actual_char_id, card["storage_msg_id"], _send_fav_confirm)
    if sent is None:
        await event.reply(confirm_text, buttons=buttons, parse_mode='html')

# ==========================================
# 🛒 Buy This Card — /fav on a card the player doesn't own (2026-10, per owner request)
# ==========================================
FAV_BUY_REQUEST_COOLDOWN = 600  # seconds — one Owner DM per (buyer, card) per window, so the
                                # "From Owner" button can't be used to spam the Owner's DMs
_fav_buy_request_last = {}      # (user_id, char_id) -> timestamp of the last request sent

async def _build_fav_buy_menu(user_id, char_id):
    """(text, buttons) for the 🛒 Buy menu — [👥 From Users (N)] [👑 From Owner] — or None if the
    card no longer exists. Shared by /fav (edits its own message in place) and /check (posts it as
    a separate reply so the card info above it stays put)."""
    card = await characters_base_col.find_one({"char_id": char_id})
    if not card:
        return None
    owners_count = await users_catcher_col.count_documents({"harem.char_id": char_id})
    text = (
        f"🛒 <b>Buy {escape_html(card['name'])}</b>\n\n"
        f"🆔 <code>{display_char_id(char_id)}</code>\n"
        f"✨ {escape_html(card.get('rarity', 'Unknown'))}\n\n"
        f"<i>Choose where to buy this card from:</i>"
    )
    buttons = [
        [colored_button(f"👥 From Users ({owners_count})",
                        f"favbuy_users_{user_id}_{char_id}", color="primary")],
        [colored_button("👑 From Owner",
                        f"favbuy_owner_{user_id}_{char_id}", color="primary")],
    ]
    return text, buttons

@bot1.on(events.CallbackQuery(pattern=r'^favbuy_menu_(\d+)_([a-zA-Z0-9_]+)$'))
async def fav_buy_menu_callback(event):
    user_id = int(event.pattern_match.group(1))
    char_id = event.pattern_match.group(2)
    if isinstance(char_id, bytes): char_id = char_id.decode('utf-8')

    if event.sender_id != user_id:
        return await event.answer("⚠️ This isn't your request!", alert=True)

    built = await _build_fav_buy_menu(user_id, char_id)
    if not built:
        return await event.answer("❌ Card not found.", alert=True)
    text, buttons = built

    await event.edit(text, parse_mode=_pm(event.client), buttons=buttons)
    await event.answer()


