@bot1.on(events.CallbackQuery(pattern=r'^favbuy_users_(\d+)_([a-zA-Z0-9_]+)$'))
async def fav_buy_users_callback(event):
    user_id = int(event.pattern_match.group(1))
    char_id = event.pattern_match.group(2)
    if isinstance(char_id, bytes): char_id = char_id.decode('utf-8')

    if event.sender_id != user_id:
        return await event.answer("⚠️ This isn't your request!", alert=True)

    # Top 10 owners — same ranking as /check (most copies first, earliest catch breaks ties)
    pipeline = [
        {"$match": {"harem.char_id": char_id}},
        {"$project": {
            "fullname": 1, "user_id": 1,
            "matches": {"$filter": {"input": "$harem", "as": "item",
                                    "cond": {"$eq": ["$$item.char_id", char_id]}}}
        }},
        {"$project": {
            "fullname": 1, "user_id": 1,
            "count": {"$size": "$matches"},
            "first_caught": {"$min": "$matches.caught_date"}
        }},
        {"$sort": {"count": -1, "first_caught": 1}},
        {"$limit": 10}
    ]
    owners = await users_catcher_col.aggregate(pipeline).to_list(length=10)

    lines = []
    for idx, u in enumerate(owners, start=1):
        uname = escape_html(clean_display_name(u.get("fullname"), fallback=f"Agent {u['user_id']}"))
        mention = f"<a href='tg://user?id={u['user_id']}'>{uname}</a>"
        lines.append(f"<b>{idx}.</b> {mention} ×{u['count']}")

    body = "\n".join(lines) if lines else "<i>No one owns this card yet.</i>"

    await event.edit(
        f"👥 <b>Top 10 Collectors</b>\n\n{body}\n\n"
        f"<i>Tap a name to message them about a trade or gift.</i>",
        parse_mode=_pm(event.client),
        buttons=[[Button.inline("🔙 Back", data=f"favbuy_menu_{user_id}_{char_id}")]]
    )
    await event.answer()


@bot1.on(events.CallbackQuery(pattern=r'^favbuy_owner_(\d+)_([a-zA-Z0-9_]+)$'))
async def fav_buy_owner_callback(event):
    user_id = int(event.pattern_match.group(1))
    char_id = event.pattern_match.group(2)
    if isinstance(char_id, bytes): char_id = char_id.decode('utf-8')

    if event.sender_id != user_id:
        return await event.answer("⚠️ This isn't your request!", alert=True)

    if not claim_single_tap(event):
        return await event.answer("⏳ Already processing...", alert=False)

    card = await characters_base_col.find_one({"char_id": char_id})
    if not card:
        return await event.answer("❌ Card not found.", alert=True)

    # ⏳ one request per (buyer, card) per cooldown window
    now = time.time()
    last_sent = _fav_buy_request_last.get((user_id, char_id), 0)
    if now - last_sent < FAV_BUY_REQUEST_COOLDOWN:
        return await event.answer(
            "⏳ You already sent a request for this card — please wait for the Owner to reply.",
            alert=True
        )

    buyer_name = await get_plain_name(event, user_id)
    buyer_mention = f"<a href='tg://user?id={user_id}'>{escape_html(buyer_name)}</a>"

    # 👑 Owner ဆီ တိုက်ရိုက် DM ပို့
    try:
        await bot1.send_message(
            OWNER_ID,
            f"🛒 <b>Card Buy Request</b>\n\n"
            f"👤 <b>From:</b> {buyer_mention} (<code>{user_id}</code>)\n"
            f"🎴 <b>Card:</b> <code>{escape_html(card['name'])}</code>\n"
            f"🆔 <b>ID:</b> <code>{display_char_id(char_id)}</code>\n"
            f"✨ <b>Rarity:</b> {escape_html(card.get('rarity', 'Unknown'))}\n"
            f"💠 <b>Shop Price:</b> <code>{format_vlt_plain(vlt_price_for_char(card))}</code>\n\n"
            f"<i>Tap the buyer's name to message them and negotiate.</i>",
            parse_mode='html'
        )
    except Exception as e:
        return await event.answer(f"❌ Couldn't reach Owner: {e}", alert=True)

    _fav_buy_request_last[(user_id, char_id)] = now
    if len(_fav_buy_request_last) > 2000:  # cheap bound, same idea as _recent_callback_taps
        cutoff = now - FAV_BUY_REQUEST_COOLDOWN
        for k, ts in list(_fav_buy_request_last.items()):
            if ts < cutoff:
                del _fav_buy_request_last[k]

    await event.answer("✅ Request sent to Owner!", alert=True)
    await event.edit(
        f"✅ <b>Request sent!</b>\n\n"
        f"The Owner has been notified about your interest in "
        f"<code>{escape_html(card['name'])}</code>.\n"
        f"<i>They'll contact you if they're willing to sell.</i>",
        parse_mode=_pm(event.client),
        buttons=[[Button.inline("🔙 Back", data=f"favbuy_menu_{user_id}_{char_id}")]]
    )


# ---- Helper functions for harem ----
async def remove_one_harem_copy(user_id, char_id, status):
    """Atomically removes exactly ONE harem copy matching (char_id, status) from user_id's vault (positional $ null-out, then $pull) - safe with duplicate copies and concurrent harem edits (no find->modify->write-back race, unlike the old read-modify-write)."""
    await users_catcher_col.update_one(
        {"user_id": user_id, "harem": {"$elemMatch": {"char_id": char_id, "status": status}}},
        {"$unset": {"harem.$": 1}}
    )
    await users_catcher_col.update_one({"user_id": user_id}, {"$pull": {"harem": None}})

async def clear_stale_favorite(user_id, char_id, remaining_harem):
    """Call this right after removing char_id from user_id's harem (gift / sell-and-bought /
    trade / scrap). If that was their LAST copy and it happened to be their /fav card, unset
    fav_card so /harem and /profile stop showing a card they no longer own."""
    if is_owner_mode(user_id):
        return   # their favourite isn't tied to a real copy (see /fav), so losing the real copy doesn't make it stale
    still_owns_it = any(isinstance(it, dict) and it.get("char_id") == char_id for it in remaining_harem)
    if still_owns_it:
        return
    await users_catcher_col.update_one(
        {"user_id": user_id, "fav_card": char_id},
        {"$unset": {"fav_card": "", "fav_note": ""}}
    )

CARD_RANK_CACHE_TTL = 600  # 10 minutes — ranks don't need to be perfectly real-time, a bit of staleness is fine
_CARDRANK_LOCAL = {}       # cid -> (owners list, expiry) — in-process copy in front of Redis (see get_user_ranks_for_cards)


def _rank_from_owners(owners, user_id):
    for idx, o in enumerate(owners, start=1):
        if o.get("user_id") == user_id:
            return idx
    return None


async def get_user_ranks_for_cards(user_id, char_ids):
    """Batched, cached replacement for per-card get_user_rank_for_card; returns {char_id: rank_or_None}. Top-10 leaderboards are cached in Redis (CARD_RANK_CACHE_TTL, shared across users); misses resolve in ONE aggregation."""
    if not char_ids:
        return {}
    ranks = {}
    missing = []
    # 🩹 (2026-10, Render 5 GB/month outbound cap): a small in-process layer first. If REDIS_URL isn't set the Redis client points at
    # localhost, every call below fails, and the whole page's ranks were re-aggregated from Mongo on EVERY harem page build. Now a card's
    # owner board is also remembered in memory for CARD_RANK_CACHE_TTL, whatever Redis does.
    _now = time.time()
    _need = []
    for cid in char_ids:
        _l = _CARDRANK_LOCAL.get(cid)
        if _l and _now < _l[1]:
            ranks[cid] = _rank_from_owners(_l[0], user_id)
        else:
            _need.append(cid)
    if not _need:
        return ranks
    char_ids = _need
    # Batched into a single MGET round-trip instead of one GET per char_id in a loop — the
    # old loop meant len(char_ids) sequential network round-trips (up to 500 for a full
    # /harem before the page-scoped fix above), and if Redis was unreachable each of those
    # had to time out individually instead of failing once.
    try:
        cached_values = await redis_client.mget([f"cardrank:{cid}" for cid in char_ids])
    except Exception:
        cached_values = [None] * len(char_ids)
    for cid, cached in zip(char_ids, cached_values):
        if cached is not None:
            _owners = json.loads(cached)
            _CARDRANK_LOCAL[cid] = (_owners, time.time() + CARD_RANK_CACHE_TTL)
            ranks[cid] = _rank_from_owners(_owners, user_id)
        else:
            missing.append(cid)
    if not missing:
        return ranks
    pipeline = [
        {"$match": {"harem.char_id": {"$in": missing}}},
        {"$project": {
            "user_id": 1,
            "harem": {"$filter": {"input": "$harem", "as": "item", "cond": {"$in": ["$$item.char_id", missing]}}}
        }},
        {"$unwind": "$harem"},
        {"$group": {"_id": {"char_id": "$harem.char_id", "user_id": "$user_id"}, "count": {"$sum": 1}}},
        {"$sort": {"_id.char_id": 1, "count": -1}},
        {"$group": {"_id": "$_id.char_id", "owners": {"$push": {"user_id": "$_id.user_id", "count": "$count"}}}},
        {"$project": {"owners": {"$slice": ["$owners", 10]}}}
    ]
    try:
        results = await users_catcher_col.aggregate(pipeline).to_list(length=None)
    except Exception as e:
        logging.error(f"⚠️ get_user_ranks_for_cards aggregation error: {e}")
        results = []
    found_ids = set()
    for doc in results:
        cid = doc["_id"]
        owners = doc.get("owners", [])
        found_ids.add(cid)
        ranks[cid] = _rank_from_owners(owners, user_id)
        _CARDRANK_LOCAL[cid] = (owners, time.time() + CARD_RANK_CACHE_TTL)
        try:
            await redis_client.setex(f"cardrank:{cid}", CARD_RANK_CACHE_TTL, json.dumps(owners))
        except Exception:
            pass
    # Cards nobody owns yet never show up in the aggregation output — cache an empty
    # list for those too, otherwise they'd re-trigger the aggregation on every call.
    for cid in missing:
        if cid not in found_ids:
            ranks[cid] = None
            _CARDRANK_LOCAL[cid] = ([], time.time() + CARD_RANK_CACHE_TTL)
            try:
                await redis_client.setex(f"cardrank:{cid}", CARD_RANK_CACHE_TTL, json.dumps([]))
            except Exception:
                pass
    return ranks

# 🩹 FIX (per owner report — "/harem gets heavier the more characters someone has, page-turns …
_HAREM_PAGES_CACHE = {}
HAREM_PAGES_CACHE_TTL = 45  # seconds
# 🩹 NEW (2026-10, per owner report — the owner's /harem and its page turns are very slow): the owner's …
OWNER_HAREM_PAGES_CACHE_TTL = 900  # seconds

async def _get_owner_roster():
    return await get_all_characters_cached()   # in-process already (see the roster block near the top) — READ-ONLY
HAREM_PAGES_CACHE_MAX_ENTRIES = 2000  # simple size cap so this can never grow unbounded

def _harem_content_fingerprint(harem_counts):
    """Cheap hash of exactly what's in the vault (which chars, how many of each, market
    status) — order-independent, so it's stable across calls even if dict iteration order
    ever differs."""
    return hash(tuple(sorted((cid, v["normal"], v["market"]) for cid, v in harem_counts.items())))

@_log_slow("send_paginated_harem")
async def send_paginated_harem(client, chat_id, user_id, page=1, edit_msg_id=None, viewer_id=None, _bot1_fallback=False):
    if viewer_id is None:
        viewer_id = user_id
    # 🐢 (2026-10, per owner report — "/harem is always 10s+ slow, even with 1 character"): per-stage stopwatch. When a page
    # takes >= 2s the log gets ONE line with where the time went, e.g. "(user_doc 0.01s · pages 0.00s · ranks 9.80s · …)".
    _tm_start = _tm_last = time.perf_counter()
    _tm_parts = []
    def _tm_mark(label):
        nonlocal _tm_last
        _now = time.perf_counter()
        _tm_parts.append(f"{label} {_now - _tm_last:.2f}s")
        _tm_last = _now
    async def _snd(text, **kw):
        return await client.send_message(chat_id, text, parse_mode='html', **kw)
    async def _edt(text, **kw):
        return await client.edit_message(chat_id, edit_msg_id, text, parse_mode='html', **kw)
    async def _notice(text):
        # the short "nothing to show" screens
        try:
            if edit_msg_id:
                await _edt(text)
            else:
                await _snd(text)
        except errors.MessageNotModifiedError:
            pass
        except Exception as _ne:
            raise
    is_own_vault = (viewer_id == user_id)
    # 👑 The owner's vault is unlimited: every character ever added via /addchar (and any
    # added in the future) counts as owned, always exactly one copy each — computed live from
    # characters_base_col rather than stored, so it needs no migration and always reflects the
    # current roster automatically. The owner's REAL personal /collect catches stay in their
    # actual harem array untouched and are shown separately (see the "🎯 My Real Catches"
    # button below and the "collected.<id>" inline gallery) rather than mixed into this view.
    is_unlimited_vault = is_owner_mode(user_id)   # OWNER_ID or an /addowner grantee
    # 🩹 FIX (per owner report — /harem and its page-turns are slow): this projection used to …
    harem_projection = {"harem.char_id": 1} if is_unlimited_vault else {"harem": 1}
    user_doc = await users_catcher_col.find_one({"user_id": user_id}, {**harem_projection, "rarity_filter": 1, "event_filter": 1, "fav_card": 1, "harem_sort": 1, "fullname": 1, "premium_until": 1, "_id": 0}) or {}
    raw_harem = user_doc.get("harem", [])
    _tm_mark("user_doc")
    # (owner: never read — the fav-card staleness check below is skipped for the unlimited vault — so don't build it)
    raw_owned_id_set = set() if is_unlimited_vault else {item.get("char_id") for item in raw_harem if isinstance(item, dict) and item.get("char_id")}
    rarity_filter = user_doc.get("rarity_filter")
    ev_filter = active_event_filter(user_doc)   # 🎪 /hmode: only cards of this event — an ULTRA kind under ULTRA, a custom event under any other rarity (None = all)
    # 🩹 CHANGED BACK (2026-09, per owner request): regular users' default is "rarity" again …
    # ---- history (why "recent" became the default in the first place) ----
    # 🩹 CHANGED (per owner request — default vault view used to feel like it was "always A-Z"
    default_sort = "recent" if is_unlimited_vault else "rarity"
    harem_sort = user_doc.get("harem_sort") or default_sort

    # 🩹 (2026-10 perf pass) Owner fast path: look the finished pages up BEFORE touching the roster at all. A page turn
    # used to re-filter the roster, rebuild a 2,500-entry harem_counts + owned_ids, and sort a 2,500-tuple fingerprint
    # just to discover "yes, cached" — now a hit is one dict lookup keyed on (roster version, filter, sort).
    _owner_pages_key = None
    _owner_hit = None
    if is_unlimited_vault:
        _owner_pages_key = (_OWNER_ROSTER_VERSION["v"], rarity_filter, ev_filter, harem_sort)
        _e = _OWNER_HAREM_PAGES_CACHE.get(_owner_pages_key)
        if _e is not None and (time.time() - _e["ts"]) < OWNER_HAREM_PAGES_CACHE_TTL:
            _owner_hit = _e

    if _owner_hit is not None:
        pages = _owner_hit["pages"]
        owned_ids = _owner_hit["owned_ids"]   # read-only (len + random.choice below)
        harem_counts = None                    # never read on this path (owner: every count is 1)
    elif is_unlimited_vault:
        all_chars = await _get_owner_roster()  # same data as get_all_characters_cached(), minus the Redis+JSON cost per tap. READ-ONLY.
        if rarity_filter:
            _rf_tier = classify_rarity(rarity_filter)   # hoisted: used to be re-classified for EVERY character
            all_chars = [c for c in all_chars if classify_rarity(c.get("rarity")) == _rf_tier]
        if ev_filter:
            all_chars = [c for c in all_chars if char_in_event(c, ev_filter)]
        if not all_chars:
            msg = (f"🚫 <b>No cards found with that filter.</b>\nUse <code>/hmode</code> to change or clear it."
                   if rarity_filter else "🚫 <b>No characters exist yet</b> — add some with /addchar.")
            await _notice(msg)
            return
        harem_counts = {c["char_id"]: {"normal": 1, "market": 0} for c in all_chars}
        owned_ids = list(harem_counts.keys())
    else:
        if not raw_harem:
            msg = "📭 <b>Your vault is empty! Go catch some characters!</b>" if is_own_vault else "📭 <b>Their vault is empty!</b>"
            await _notice(msg)
            return
        filtered_harem = []
        if rarity_filter:
            for item in raw_harem:
                if isinstance(item, dict) and classify_rarity(item.get("rarity")) == classify_rarity(rarity_filter):
                    filtered_harem.append(item)
        else:
            filtered_harem = raw_harem
        if ev_filter:
            filtered_harem = await filter_items_by_event(filtered_harem, ev_filter)
        if not filtered_harem:
            msg = f"🚫 <b>No cards found with that filter.</b>\n"
            msg += f"Use <code>/hmode</code> to change or clear it."
            await _notice(msg)
            return
        harem_counts = {}
        for item in filtered_harem:
            if isinstance(item, dict) and "char_id" in item:
                cid = item["char_id"]
                is_market = item.get("status") == "market"
                if cid not in harem_counts:
                    harem_counts[cid] = {"normal": 0, "market": 0}
                if is_market:
                    harem_counts[cid]["market"] += 1
                else:
                    harem_counts[cid]["normal"] += 1
        owned_ids = list(harem_counts.keys())
        if not owned_ids:
            msg = f"🚫 <b>No valid cards in vault.</b>"
            await _notice(msg)
            return
    if _owner_hit is not None:
        cache_key = None
        cached_entry = (pages, time.time())   # already validated against its TTL above
    elif is_unlimited_vault:
        cache_key = None
        cached_entry = None                   # miss — rebuilt below, then stored in _OWNER_HAREM_PAGES_CACHE
    else:
        content_fp = _harem_content_fingerprint(harem_counts)
        cache_key = (user_id, rarity_filter, ev_filter, harem_sort, content_fp)
        cached_entry = _HAREM_PAGES_CACHE.get(cache_key)
    pages_ttl = OWNER_HAREM_PAGES_CACHE_TTL if is_unlimited_vault else HAREM_PAGES_CACHE_TTL
    if cached_entry and (time.time() - cached_entry[1]) < pages_ttl:
        pages = cached_entry[0]
    else:
        if is_unlimited_vault:
            # all_chars (loaded above) already carries name/category/rarity for exactly the cards in this
            # view — re-querying Mongo with a 2,500+ element $in list just to fetch the same four fields
            # was the heaviest single step of rebuilding the owner's pages.
            db_chars = all_chars
        else:
            # 🩹 (2026-10, Render 5 GB/month outbound cap): used to be a Mongo find whose filter lists EVERY owned card id (about 1 KB per
            # page build, 4,300 of them in 8.5 h). The same seven fields are already in the in-memory roster (by_id index), so read them
            # from there — copied field-by-field, so nothing downstream can touch the shared roster docs.
            _fields = ("char_id", "name", "category", "rarity", "event_no", "custom_event_no", "custom_event")
            _by_id = _roster_derived(await _get_owner_roster())["by_id"]
            db_chars = [{k: _d[k] for k in _fields if k in _d} for _d in (_by_id.get(_cid) for _cid in owned_ids) if _d]
        category_totals = await get_category_totals_cached()
        def get_rarity_weight(rarity_str):
            return rarity_rank_value(rarity_str)

        # 🩹 NEW (per owner request — "Harem Sort/Filter"): a per-user harem_sort setting, picked …
        def build_card_line(card):
            cid = card["char_id"]
            counts = harem_counts.get(cid, {"normal": 0, "market": 0})
            normal_qty, market_qty = counts["normal"], counts["market"]
            if normal_qty > 0 and market_qty > 0:
                status_str = f"<b>(x{normal_qty} | {market_qty} 🛒)</b>"
            elif market_qty > 0:
                status_str = f"<b>({market_qty} 🛒)</b>"
            else:
                status_str = f"<b>(x{normal_qty})</b>"
            tier = classify_rarity(card.get("rarity", ""))
            rarity_emoji = RARITY_EMOJI.get(tier, RARITY_DEFAULT_EMOJI)
            name_html = escape_html(card['name'])
            if tier == RARITY_TIERS[0]:
                # 🎪 (2026-10, per owner request) an ULTRA shows its Event's leading emoji after the name: Velina [🎮]
                ev_emoji = event_top_emoji(card)
                if ev_emoji:
                    name_html += f" [{ev_emoji}]"
            else:
                # 🎪 custom events (/newevent + /evset) — every OTHER rarity shows its event emoji the same way
                cev_emoji = custom_event_emoji(card)
                if cev_emoji:
                    name_html += f" [{cev_emoji}]"
            return (cid, f"<code>{display_char_id(cid)}</code> · {rarity_emoji} · {name_html} {status_str}")

        if harem_sort != "rarity":
            if harem_sort == "recent":
                if is_unlimited_vault:
                    # No per-copy caught_date exists for this synthetic "own everything" view —
                    # but /importcleanup renumbered every character sequentially by true
                    # add-order, and /addchar now assigns the next number up from here on (see
                    # _next_sequential_char_id), so char_id itself IS add-order: highest first.
                    def _char_id_num(cid):
                        digits = display_char_id(cid)
                        return int(digits) if isinstance(digits, str) and digits.isdigit() else 0
                    ordered_cards = sorted(db_chars, key=lambda c: -_char_id_num(c["char_id"]))
                else:
                    # Most-recent caught_date per char_id, off the user's OWN harem array (db_chars
                    # has no caught_date — that lives per-copy, not on the character's base doc). A
                    # duplicate's LATEST catch is what counts for "how recently did I get this one".
                    latest_caught = {}
                    for item in raw_harem:
                        if isinstance(item, dict) and item.get("char_id"):
                            cid = item["char_id"]
                            cd = item.get("caught_date", 0) or 0
                            if cd > latest_caught.get(cid, -1):
                                latest_caught[cid] = cd
                    ordered_cards = sorted(db_chars, key=lambda c: -latest_caught.get(c["char_id"], 0))
            else:  # "az"
                ordered_cards = sorted(db_chars, key=lambda c: c.get("name", "").lower())
            sort_header = ("🕐 Recently Added" if is_unlimited_vault else "🕐 Recently Caught") if harem_sort == "recent" else "🔤 A–Z"
            category_blocks = [([f"{sort_header} <code>{len(ordered_cards)}</code>"], [build_card_line(c) for c in ordered_cards])]
        else:
            from collections import defaultdict
            by_category = defaultdict(list)
            for card in db_chars:
                by_category[card.get("category") or "Unknown Series"].append(card)
            def get_category_weight(cat):
                cards = by_category[cat]
                return max([get_rarity_weight(c.get("rarity", "")) for c in cards], default=0)
            sorted_categories = sorted(by_category.keys(), key=lambda c: (-get_category_weight(c), c.lower()))
            # Build one "block" per category: a header/progress-bar pair plus each card's (char_id, …
            category_blocks = []
            for cat in sorted_categories:
                cat_cards = sorted(by_category[cat], key=lambda x: (-get_rarity_weight(x.get("rarity", "")), x.get("name", "").lower()))
                owned_in_cat = len(cat_cards)
                total_in_cat = category_totals.get(cat, owned_in_cat)
                header_lines = [f"✨ <b>{escape_html(cat)}</b> <code>{owned_in_cat}/{total_in_cat}</code>"]
                card_entries = [build_card_line(card) for card in cat_cards]
                category_blocks.append((header_lines, card_entries))
        # 🩹 FIX: pagination used to keep whole categories together no matter what ("never split a …
        PAGE_CHAR_BUDGET = 650
        pages = []          # each page: [(char_id_or_None, line_text), ...] — None marks header/spacer lines
        current_page, current_len = [], 0

        def _flush_page():
            nonlocal current_page, current_len
            if current_page:
                pages.append(current_page)
            current_page, current_len = [], 0

        for header_lines, card_entries in category_blocks:
            if not card_entries:
                continue
            idx = 0
            header_printed = False
            continuation = False
            while idx < len(card_entries):
                if not header_printed:
                    title = header_lines[0] if not continuation else f"{header_lines[0]} <i>(cont'd)</i>"
                    h_lines = [title]
                    h_len = sum(utf16_len(l) + 1 for l in h_lines)
                    if current_page and current_len + h_len > PAGE_CHAR_BUDGET:
                        _flush_page()
                        continuation = True
                        title = f"{header_lines[0]} <i>(cont'd)</i>"
                        h_lines = [title]
                        h_len = sum(utf16_len(l) + 1 for l in h_lines)
                    for l in h_lines:
                        current_page.append((None, l))
                    current_len += h_len
                    header_printed = True
                cid, line_body = card_entries[idx]
                line_len = utf16_len(line_body) + 1 + 4  # +4 reserves room for a rank badge suffix added after pagination
                # A page holding nothing but the header we just printed must accept at least one
                # card no matter what, or we'd flush forever without ever making progress.
                only_header_so_far = len(current_page) <= 1
                if current_page and not only_header_so_far and current_len + line_len > PAGE_CHAR_BUDGET:
                    _flush_page()
                    header_printed = False
                    continuation = True
                    continue
                current_page.append((cid, line_body))
                current_len += line_len
                idx += 1
            current_page.append((None, ""))  # blank spacer after the category
            current_len += 1
        _flush_page()
        if is_unlimited_vault:
            if len(_OWNER_HAREM_PAGES_CACHE) >= 32:   # a handful of (filter, sort) combos per roster version — tiny
                _OWNER_HAREM_PAGES_CACHE.clear()
            _OWNER_HAREM_PAGES_CACHE[_owner_pages_key] = {"pages": pages, "owned_ids": owned_ids, "ts": time.time()}
        else:
            if len(_HAREM_PAGES_CACHE) >= HAREM_PAGES_CACHE_MAX_ENTRIES:
                _HAREM_PAGES_CACHE.clear()  # simple full-clear cap — cheap, and this cache is only ever a speed optimization, never a correctness dependency
            _HAREM_PAGES_CACHE[cache_key] = (pages, time.time())
    _tm_mark("pages")
    total_pages = len(pages) or 1
    if page < 1: page = 1
    if page > total_pages: page = total_pages
    page_items = pages[page - 1] if pages else []
    # Only now do we know exactly which cards are visible on this page — look up ranks for
    # just those instead of the whole vault.
    page_char_ids = [cid for cid, _ in page_items if cid is not None]
    # 🩹 Skipped for the owner's Complete Collection (2026-10): the 🥇🥈🥉 badge means "you're a top-3 REAL …
    ranks_map = {} if is_unlimited_vault else await get_user_ranks_for_cards(viewer_id, page_char_ids)
    _tm_mark("ranks")
    page_lines = []
    for cid, line_body in page_items:
        if cid is None:
            page_lines.append(line_body)
            continue
        rank = ranks_map.get(cid)
        rank_str = ""
        if rank == 1:
            rank_str = " 🥇"
        elif rank == 2:
            rank_str = " 🥈"
        elif rank == 3:
            rank_str = " 🥉"
        page_lines.append(f"{line_body}{rank_str}")
    fullname = user_doc.get("fullname") or "Hunter"
    mention = f"<a href='tg://user?id={user_id}'><b>{escape_html(fullname)}</b></a>"
    vault_label = "Complete Collection" if is_unlimited_vault else ("Your Vault" if is_own_vault else "Vault")
    vip_badge = " 👑" if (not is_unlimited_vault and is_vip_active(user_doc)) else ""
    # 🩹 (2026-11, per owner request — "အပေါ်စာကြောင်း emoji တွေများနေတာ လျှော့၊ user full name က ထိပ်ကဖြစ်ချင်၊ Collector Points ပြ"): the header used to open with 🍁, put the label BEFORE the …
    total_count = len(owned_ids) if is_unlimited_vault else sum(c['normal'] + c['market'] for c in harem_counts.values())
    if is_unlimited_vault:
        _vault_line = f"<b>{vault_label}</b>"
    else:
        _vault_pts, _, _ = collector_points_of_harem(raw_harem)
        _vault_line = f"<b>{vault_label}</b> · <code>{_vault_pts:,}</code> pts · {collector_title(_vault_pts)[1]}"
    _filter_marks = []
    if rarity_filter:
        _filter_marks.append(rarity_filter_emoji(rarity_filter))
    if ev_filter:
        _filter_marks.append(event_filter_emoji(ev_filter))
    _filter_prefix = (" ".join(m for m in _filter_marks if m) + " · ") if any(_filter_marks) else ""
    _stats_line = (f"{_filter_prefix}Page <code>{page}/{total_pages}</code> · "
                   f"<code>{len(owned_ids)}</code> unique · <code>{total_count}</code> total")
    output_text = f"{mention}{vip_badge}\n<blockquote>{_vault_line}\n{_stats_line}</blockquote>\n"
    output_text += "\n".join(page_lines) + "\n"
    # 🩹 REMOVED (per owner request): the footer used to carry a "/market" purchase hint plus
    # two "/hmode" hint lines (filter-active, sort-active) — all three gone now, which is also
    # why PAGE_CHAR_BUDGET above no longer reserves room for a footer at all.
    buttons = []
    # 🩹 FIX: this used to be len(filtered_harem), so setting an /hmode rarity filter (e.g.
    total_cards = len(owned_ids) if is_unlimited_vault else sum(
        1 for item in raw_harem if isinstance(item, dict) and item.get("char_id")
    )
    # 🩹 CHANGED (per owner request): trimmed the button stack down to just the inline-query …
    grand_total = sum((await get_category_totals_cached()).values())
    _tm_mark("totals")
    buttons.append([colored_switch_inline_button(f"🧩 Characters 🧩 ({total_cards}/{grand_total})", query=f"harem.{user_id}", same_peer=True, color="success")])
    _exl_row = []                                                  # 🧣 EXCLUSIVE LIMITED: public showcase (everyone) + "Mine" (card owners)
    # 🩹 2026-11 (owner: "addowner ပေးထားသူတွေထဲ Exclusive Edition ကဒ်တွေပါ ပါနေတယ် မပါသင့်ပါ"): an /addowner grantee's /harem is the unlimited …
    _hide_exl_row = is_unlimited_vault and user_id != OWNER_ID
    if not _hide_exl_row:
        _exl_n = await exclusive_public_count()
        if _exl_n > 0:
            _exl_row.append(colored_switch_inline_button(f"🧣 Exclusive Limited ({_exl_n})", query="exclusive", same_peer=True, color="primary"))
        if is_own_vault and await exclusive_has_cards(user_id):
            _exl_row.append(colored_switch_inline_button("🧣 Mine", query=f"exclusive.{user_id}", same_peer=True, color="primary"))
    if _exl_row:
        buttons.append(_exl_row)
    # 🗑️ REMOVED (2026-11, per owner request): the red "♻️ Bulk Scrap Dupes" button that used to sit
    # under /harem. Bulk Scrap itself still works via /sell, /scrap, /dupes and the other entry points.
    if is_unlimited_vault:
        # Separate gallery for the owner's REAL /collect catches — deliberately not mixed
        # into the unlimited-vault gallery above (see request that prompted this).
        real_catch_count = sum(1 for item in raw_harem if isinstance(item, dict) and item.get("char_id"))
        buttons.append([Button.switch_inline(f"🎯 My Real Catches ({real_catch_count})", query=f"collected.{user_id}", same_peer=True)])
    nav_buttons = []
    if page > 1:
        nav_buttons.append(Button.inline(f"‹ {f('Previous')}", data=f"harem_{page-1}_{user_id}_{viewer_id}"))
    if page < total_pages:
        nav_buttons.append(Button.inline(f"{f('Next')} ›", data=f"harem_{page+1}_{user_id}_{viewer_id}"))
    if nav_buttons:
        buttons.append(nav_buttons)
    if not buttons:
        buttons = None
    fav_card_id = user_doc.get("fav_card")
    _ex_fav_doc = None
    if fav_card_id and exl_parse_id(fav_card_id):
        # 🧣 EXCLUSIVE LIMITED (2026-11, part 4): the favourite is an Exclusive card. It's never in the harem array, so it is
        # kept only while the card's owner_id is still this player (it may have been gifted away / deleted since).
        _ex_fav_doc = await exl_fav_doc_for(user_id, fav_card_id)
        if _ex_fav_doc is None:
            await users_catcher_col.update_one({"user_id": user_id, "fav_card": fav_card_id}, {"$unset": {"fav_card": "", "fav_note": ""}})
            fav_card_id = None
    elif fav_card_id and not is_unlimited_vault and fav_card_id not in raw_owned_id_set:
        # Owner gifted/sold/traded/scrapped away their last copy of this card since favouriting
        # it — stop treating it as the favourite (both for display here and going forward).
        # (Skipped for the unlimited vault — every card is always "owned" there, so a
        # favourite never goes stale.)
        await users_catcher_col.update_one({"user_id": user_id, "fav_card": fav_card_id}, {"$unset": {"fav_card": "", "fav_note": ""}})
        fav_card_id = None
    fav_media = None
    target_display_id = fav_card_id
    if not target_display_id and owned_ids:
        target_display_id = random.choice(owned_ids)
    if target_display_id and not edit_msg_id:
        # 🩹 (2026-10) only needed when a NEW message is being sent — a Next/Previous tap just edits text
        # (see below), so this used to cost an extra Mongo read + a possible Telegram media fetch per page
        # turn for a photo nobody was going to attach.
        fav_card_data = _ex_fav_doc or await characters_base_col.find_one({"char_id": target_display_id})   # 🧣 EX favourite: its own doc already has storage_msg_id
        if fav_card_data:
            fav_media = await get_char_display_media(client, target_display_id, fav_card_data["storage_msg_id"])
    # 🩹 FIX: attach the fav-card photo whenever it fits, for a vault of ANY size — not just …
    _tm_mark("media")
    CAPTION_SAFE_LIMIT = 1024
    can_attach_photo = bool(fav_media) and utf16_len(output_text) <= CAPTION_SAFE_LIMIT
    try:
        if edit_msg_id:
            try:
                await _edt(output_text, buttons=buttons)
            except errors.MessageNotModifiedError:
                pass
            except Exception as _edit_err:
                # Should never trigger given the PAGE_CHAR_BUDGET guarantee above — kept only
                # as a last-resort safety net (e.g. an unusually long display name we didn't
                # account for) so a genuine edge case degrades to a fresh message instead of an
                # error page.
                try:
                    await client.delete_messages(chat_id, edit_msg_id)
                except Exception:
                    pass
                await _snd(output_text, buttons=buttons)
        else:
            if can_attach_photo:
                async def _send_harem_photo(media):
                    return await client.send_message(chat_id, output_text, file=media, parse_mode='html', buttons=buttons)
                sent = await send_with_char_media(target_display_id, fav_card_data["storage_msg_id"], _send_harem_photo)
                if sent is None:
                    await client.send_message(chat_id, output_text, parse_mode='html', buttons=buttons)
            else:
                await _snd(output_text, buttons=buttons)
    except Exception as main_err:
        try:
            await client.send_message(chat_id, f"❌ <b>Vault Display Error:</b> <code>{escape_html(str(main_err))}</code>", parse_mode='html')
        except: pass
    _tm_mark("send")
    if time.perf_counter() - _tm_start >= 2.0:
        print(f"🐢 /harem page took {time.perf_counter() - _tm_start:.1f}s in {chat_id} "
              f"({'bot1'}; {' · '.join(_tm_parts)})")

# ---- Inline Query for harem ----
def _rarity_weight_for_sort(rarity_str):
    return rarity_rank_value(rarity_str)


async def _inline_media_result(builder, media, cid, title, caption, pm='html', rarity=None, client=None):
    """Builds an inline result for a photo or video (async: builder.photo()/document() must be awaited; videos use type='gif' so they tile like photos; no title, so tiles stay plain thumbnails). Takes the raw media object, fresh or cached."""
    # ✨ part 6: ULTRA / SUPREME / CROSSVERSE get a unique result id + a 💎 button so the bot can edit the sent message
    # (Premium emoji) — see inline_premium_prepare. Every other card: rid == cid, no buttons, exactly as before.
    rid, _btns = inline_premium_prepare(cid, caption, rarity, client)
    if isinstance(media, types.MessageMediaPhoto):
        return await builder.photo(file=media, id=rid, text=caption, parse_mode=pm, buttons=_btns)
    return await builder.document(
        file=media,
        type='gif',
        id=rid,
        text=caption,
        parse_mode=pm,
        buttons=_btns
    )

# ---- harem.<user_id> : shows a user's own vault as an inline gallery.
# collected.<user_id> routes here too (see unified_inline_query_handler) with
# force_real_harem=True, which is what lets the owner's REAL /collect catches be viewed
# separately from their unlimited vault below. ----
@_log_slow("handle_harem_inline_query")
async def handle_harem_inline_query(event, query_text, force_real_harem=False):
    builder = event.builder
    # 🩹 ADDED (per owner request): /harem itself has been force-sub-gated all along (see …
    querying_user_id = getattr(event, 'sender_id', None)
    if not querying_user_id:
        try:
            querying_user_id = event.query.user_id
        except Exception:
            querying_user_id = None
    if querying_user_id and querying_user_id != OWNER_ID and querying_user_id not in bot_ids:
        # Same "confirm live before actually blocking" as force_sub_gate — see
        # is_force_sub_member's force_confirm docstring.
        if not await is_force_sub_member(querying_user_id) and not await is_force_sub_member(querying_user_id, force_confirm=True):
            return await event.answer(
                [], cache_time=0,
                switch_pm="🐉🦋 Join our group first to browse harems! Tap below.",
                switch_pm_param="start"
            )
    try:
        target_user_id = int(query_text.split(".", 1)[1])
    except (ValueError, IndexError):
        return await event.answer(
            [], cache_time=0,
            switch_pm="⚠️ Couldn't read that request — try tapping the button again.", switch_pm_param="start"
        )
    # 🩹 (2026-10 perf pass) the owner's inline view only needs rarity_filter from this doc — not their whole real
    # harem array, which this used to pull in full on every single scroll-page request.
    _owner_view = is_owner_mode(target_user_id) and not force_real_harem
    _proj = None
    if _owner_view:
        _proj = {"rarity_filter": 1, "event_filter": 1, "_id": 0}
        if target_user_id != OWNER_ID:
            _proj["harem.char_id"] = 1   # an /addowner grantee: which cards they REALLY hold, for the "Already Obtained?" line
    user_doc = await users_catcher_col.find_one({"user_id": target_user_id}, _proj)
    rarity_filter = user_doc.get("rarity_filter") if user_doc else None
    # 🎯 Unlike /harem's own text listing (where the rarity_filter genuinely restricts what's
    # shown), this visual gallery always shows EVERY owned card's photo/video — an active
    # /hmode rarity filter only makes cards of that rarity appear FIRST, as a sort preference
    # rather than an exclusion. Hiding most of someone's actual card art behind a filter here
    # would be a jarring surprise for a feature that's meant purely for browsing.
    filter_tier = classify_rarity(rarity_filter) if rarity_filter else None
    ev_filter = active_event_filter(user_doc) if user_doc else None   # 🎪 /hmode event choice (ULTRA kind or custom event)
    # 👑 Same unlimited-vault rule as /harem itself (see send_paginated_harem) — every
    # character that exists counts as owned, one copy each, computed live so /addchar never
    # needs a sync step. force_real_harem (the "collected." entry point) opts back into the
    # owner's REAL harem array, for viewing their actual personal catches.
    is_unlimited_vault = is_owner_mode(target_user_id) and not force_real_harem

    latest_caught = {}   # char_id -> most recent caught_date (a real harem only) — drives "newest obtained first" below
    if is_unlimited_vault:
        all_chars = await _get_owner_roster()  # in-process memo (same data, no Redis GET + 750KB json.loads per scroll page)
        if not all_chars:
            return await event.answer([], cache_time=0, switch_pm="❌ No characters found.", switch_pm_param="start")
        harem_counts = None   # owner: every card is qty 1 (see `qty` below) — no 2,500-entry dict per scroll page
        total_cards = len(all_chars)
    else:
        if not user_doc or not user_doc.get("harem"):
            return await event.answer(
                [], cache_time=0,
                switch_pm="📭 This vault is empty!", switch_pm_param="start"
            )
        raw_harem = [item for item in user_doc.get("harem", []) if isinstance(item, dict) and "char_id" in item]
        if not raw_harem:
            return await event.answer([], cache_time=0, switch_pm="📭 No cards found.", switch_pm_param="start")
        harem_counts = {}
        for item in raw_harem:
            cid = item["char_id"]
            harem_counts[cid] = harem_counts.get(cid, 0) + 1
            cdate = item.get("caught_date") or 0
            if isinstance(cdate, (int, float)) and cdate > latest_caught.get(cid, 0):
                latest_caught[cid] = cdate    # a duplicate's LATEST copy is what counts as "when did I get this one"
        owned_ids = list(harem_counts.keys())
        total_cards = len(raw_harem)
    # 🕒 NEWEST FIRST (per owner request):
    def _inline_sort_key(x):
        rarity_match = bool(filter_tier) and classify_rarity(x.get("rarity", "")) == filter_tier
        if not rarity_match:
            match = 2 if ev_filter else 1
        elif ev_filter:
            match = 0 if char_in_event(x, ev_filter) else 1
        else:
            match = 0
        if is_unlimited_vault:
            return (match, -_char_id_num(x.get("char_id")), 0, "")
        return (
            match,
            -latest_caught.get(x.get("char_id"), 0),
            -_rarity_weight_for_sort(x.get("rarity", "")),
            x.get("name", "").lower()
        )
    if is_unlimited_vault:
        # 🩹 (2026-10 perf pass) This used to run a 2,500-ID $in query against Mongo AND re-sort the whole roster for EVERY …
        _sk = (_OWNER_ROSTER_VERSION["v"], filter_tier, ev_filter)
        _ent = _OWNER_INLINE_SORTED.get(_sk)
        if _ent is not None and (time.time() - _ent[1]) < OWNER_INLINE_SORTED_TTL:
            db_chars = _ent[0]
        else:
            db_chars = sorted(all_chars, key=_inline_sort_key)
            if len(_OWNER_INLINE_SORTED) >= 16:
                _OWNER_INLINE_SORTED.clear()
            _OWNER_INLINE_SORTED[_sk] = (db_chars, time.time())
    else:
        db_chars = await characters_base_col.find({"char_id": {"$in": owned_ids}}, {"char_id": 1, "name": 1, "category": 1, "rarity": 1, "storage_msg_id": 1, "artist": 1, "event_no": 1, "custom_event_no": 1, "custom_event": 1, "_id": 0}).to_list(length=None)
        db_chars = sorted(db_chars, key=_inline_sort_key)
    try:
        owner_ent = await bot1.get_entity(target_user_id)
        first = getattr(owner_ent, 'first_name', '') or ''
        last = getattr(owner_ent, 'last_name', '') or ''
        owner_name = f"{first} {last}".strip() or getattr(owner_ent, 'username', '') or f"User {target_user_id}"
    except Exception:
        owner_name = f"User {target_user_id}"
    # ✅ FULL PAGINATION: Telegram hard-caps a single inline answer at 50 results (more raises
    # ResultsTooMuchError) — that's a platform limit, not a choice. To actually show the
    # WHOLE vault instead of freezing at the first 50, we page through db_chars using
    # next_offset: the client automatically re-queries us with the offset once the person
    # scrolls near the end of the current batch, so scrolling reveals every unique card.
    PAGE_SIZE = 50
    try:
        start_idx = int(event.query.offset) if event.query.offset else 0
    except (ValueError, AttributeError):
        start_idx = 0
    # 🩹 (2026-10) A window of cards whose media can't be fetched (storage message deleted, stale id, ...) used to make …
    INLINE_MAX_WINDOWS = 6
    results = []
    seen_ids = set()
    skipped = {"no_media": 0, "dup": 0, "error": 0}
    # 👑 /addowner grantees only: every card's caption says whether they've REALLY obtained it — so someone browsing a
    # grantee's Complete Collection (or their real-catches gallery) can tell which cards are actually theirs to be
    # asked for as a gift. (OWNER_ID's own galleries are unchanged.)
    show_obtained = (target_user_id in added_owner_ids) and target_user_id != OWNER_ID
    real_owned_ids = set()
    if show_obtained and is_unlimited_vault:
        real_owned_ids = {it.get("char_id") for it in ((user_doc or {}).get("harem") or [])
                          if isinstance(it, dict) and it.get("char_id")}
    next_start = start_idx
    for _window in range(INLINE_MAX_WINDOWS):
        if next_start >= len(db_chars):
            break
        page_chars = db_chars[next_start:next_start + PAGE_SIZE]
        next_start += len(page_chars)
        try:
            media_by_cid = await get_char_display_media_batch(event.client, page_chars)
        except Exception as e:
            print(f"Inline gallery batch fetch error: {e}")
            media_by_cid = {}
        for card in page_chars:
            cid = card["char_id"]
            qty = 1 if harem_counts is None else harem_counts.get(cid, 0)
            storage_media = media_by_cid.get(cid)
            if not storage_media:
                skipped["no_media"] += 1
                continue
            if cid in seen_ids:
                skipped["dup"] += 1
                continue
            try:
                rarity_no_num = card.get('rarity', '').rsplit(' ', 1)[0]
                if is_unlimited_vault and show_obtained:
                    owner_line = f"👤 <b>Owner:</b> <a href='tg://user?id={target_user_id}'>{escape_html(owner_name)}</a> · 🍁 Unlimited vault"
                elif is_unlimited_vault:
                    owner_line = "👤 <b>Owner:</b> 🍁 Owner's unlimited vault"
                else:
                    owner_line = f"👤 <b>Owner:</b> <a href='tg://user?id={target_user_id}'>{escape_html(owner_name)}</a> (x{qty})"
                _evs = [escape_html(x) for x in (event_label_of(card), custom_event_display(card)) if x]
                event_line = f"🎪 <b>Event:</b> {' | '.join(_evs)}\n" if _evs else ""   # any rarity: an ULTRA kind and/or a custom event
                obtained_line = ""
                if show_obtained:
                    obtained = (cid in real_owned_ids) if is_unlimited_vault else True   # real-catches gallery: all of them are real
                    obtained_line = f"\n🎁 <b>Already Obtained?</b> {'Yep ✅' if obtained else 'Nope ❌'}"
                caption = (
                    f"🍁 <b>{escape_html(card['name'])}</b>\n\n"
                    f"🆔 <b>ID:</b> <code>{display_char_id(cid)}</code>\n"
                    f"✨ <b>Category:</b> {escape_html(card.get('category', ''))}\n"
                    f"🦋 <b>Rarity:</b> {rarity_no_num}\n"
                    f"{event_line}"
                    f"{artist_line(card)}"
                    f"{owner_line}{obtained_line}"
                )
                results.append(await _inline_media_result(builder, storage_media, cid, card['name'], caption, pm=_pm(event.client),
                                                          rarity=card.get('rarity'), client=event.client))
                seen_ids.add(cid)
            except Exception as e:
                skipped["error"] += 1
                print(f"Inline gallery error for {cid}: {e}")
                continue
        if results:
            break
    if not results or any(skipped.values()):
        # makes "the gallery is empty" explainable from the logs instead of a silent blank
        print(f"⚠️ inline gallery {query_text} @offset {start_idx}: {len(results)} shown, skipped {skipped}, roster {len(db_chars)}")
    # 🩹 FIX: next_offset used to be "" (explicit empty string) when there was no further page.
    next_offset = str(next_start) if next_start < len(db_chars) else None
    # 🩹 FIX: this printed the INTERNAL tier id (e.g. "LEGEND") instead of the name players see ("SUPREME").
    # Plain display name only — this is an inline switch button (Telegram caps its label), so NOT the long
    # emoji + fancy-font + "No.X" form; the worst case is exactly as long as the old tier-id text was.
    _filter_tier = classify_rarity(rarity_filter) if rarity_filter else None
    _ev_emoji = (event_filter_label(ev_filter) or "").split(" ")[0] if ev_filter else ""
    filter_note = (f"🎚️ {RARITY_DISPLAY_NAME.get(_filter_tier, _filter_tier)}{(' ' + _ev_emoji) if _ev_emoji else ''} shown first"
                   if rarity_filter else "All rarities")
    mode_note = " · 🍁 Unlimited Vault" if is_unlimited_vault else (" · 🎯 Real Collect" if force_real_harem else "")
    try:
        await event.answer(
            results, cache_time=0,
            gallery=True,  # ✅ side-by-side grid, no gaps — instead of a tall one-per-row list
            next_offset=next_offset,
            switch_pm=f"{filter_note} · Total: {total_cards}{mode_note}",
            switch_pm_param="start"
        )
    except errors.NextOffsetInvalidError:
        # Last-resort safety net: whatever Telegram didn't like about next_offset, retry
        # without it (no further-page continuation) so the person still sees these results
        # instead of the whole inline query silently failing.
        await event.answer(
            results, cache_time=0,
            gallery=True,
            switch_pm=f"{filter_note} · Total: {total_cards}{mode_note}",
            switch_pm_param="start"
        )

# ---- dex.<category> : shows every character (caught or not) in a series, image gallery style ----
async def handle_dex_inline_query(event, query_text):
    builder = event.builder
    cat_name = query_text.split(".", 1)[1].strip() if "." in query_text else ""
    if not cat_name:
        return await event.answer([], cache_time=0)
    all_categories = await get_all_categories_cached()
    matched_cat = next((c for c in all_categories if c and c.lower() == cat_name.lower()), None)
    if not matched_cat:
        return await event.answer([], cache_time=0)
    user_id = getattr(event, 'sender_id', None)
    if not user_id:
        try:
            user_id = event.query.user_id
        except Exception:
            user_id = None
    owned_ids = set()
    if user_id:
        user_doc = await users_catcher_col.find_one({"user_id": user_id})
        if user_doc:
            owned_ids = {c.get("char_id") for c in user_doc.get("harem", []) if isinstance(c, dict) and c.get("char_id")}
    cat_chars = [c for c in await get_all_characters_cached() if c.get("category") == matched_cat]
    cat_chars.sort(key=lambda x: (-_rarity_weight_for_sort(x.get("rarity", "")), x.get("name", "").lower()))
    results = []
    page_chars = cat_chars[:50]
    # Batch-fetch (see handle_harem_inline_query for why this matters — one call instead of
    # up to 50 sequential ones); further reduced to only-the-misses by the cache inside
    # get_char_display_media_batch.
    try:
        media_by_cid = await get_char_display_media_batch(bot1, page_chars)
    except Exception as e:
        print(f"Dex inline gallery batch fetch error: {e}")
        media_by_cid = {}
    for card in page_chars:
        cid = card["char_id"]
        owned = cid in owned_ids
        storage_media = media_by_cid.get(cid)
        if not storage_media:
            continue
        try:
            caption = (
                f"Character Name🐇<b>{escape_html(card['name'])}</b>\n"
                f"ID <code>{display_char_id(cid)}</code>\n"
                f"🏞️<b>Category:</b> {escape_html(matched_cat)}\n"
                f" <b>Rarity:</b> {card.get('rarity', '')}\n"
                f"{artist_line(card)}"
                f"{'✅ You caught this!' if owned else '❓ Not caught yet'}"
            )
            results.append(await _inline_media_result(builder, storage_media, cid, card['name'], caption,
                                                          rarity=card.get('rarity'), client=event.client))
        except Exception as e:
            print(f"Dex inline gallery error for {cid}: {e}")
            continue
    await event.answer(results, cache_time=0)

# ---- /coll <name> (was /obtain, was /collect) : lets the /who reveal button's switch_inline query actually send a
# message. Accepts legacy "/collect " and "/catch " prefixes too, so any switch_inline buttons
# already sent to chats before the /collect → /obtain rename still work — but always emits the
# new "/obtain <name>" text going forward. ----
async def handle_collect_inline_query(event, query_text):
    for legacy_prefix in ("/coll ", "/obtain ", "/collect ", "/catch "):
        if query_text.startswith(legacy_prefix):
            prefix = legacy_prefix
            break
    else:
        prefix = "/fucck "
    char_name = query_text[len(prefix):].strip()
    if not char_name:
        return await event.answer([], cache_time=0)
    builder = event.builder
    result = builder.article(
        title=f"🦢 Collect {char_name}!",
        description="Tap here to send this /coll command",
        text=f"/coll {char_name}",
        id=f"collect_{abs(hash(char_name)) % (10 ** 12)}"
    )
    await event.answer([result], cache_time=0)

@bot1.on(events.InlineQuery)
async def unified_inline_query_handler(event):
    # Any exception used to vanish into Telethon's logs while the user just saw an empty tray.
    try:
        await _unified_inline_query_dispatch(event)
    except Exception as e:
        print(f"⚠️ Inline query error: {type(e).__name__}: {e}")
        try:
            await event.answer([], cache_time=0, switch_pm="⚠️ Error — please retry", switch_pm_param="start")
        except Exception:
            pass  # already answered, or the query expired

async def _unified_inline_query_dispatch(event):
    query_text = (event.text or "").strip()
    if query_text.startswith("harem."):
        await handle_harem_inline_query(event, query_text)
    elif query_text.startswith("collected."):
        # Owner's REAL /collect catches, kept separate from their unlimited vault above —
        # see handle_harem_inline_query and send_paginated_harem's "📥 My Real Catches" button.
        await handle_harem_inline_query(event, "harem." + query_text[len("collected."):], force_real_harem=True)
    elif query_text == "exclusive" or query_text.startswith("exclusive."):
        await handle_exclusive_inline_query(event, query_text)      # 🧣 public Exclusive Limited showcase
    elif query_text == "le" or query_text.startswith("le."):
        # 🩹 REMOVED (per owner request): the Limited Editions inline gallery is gone (the cards themselves
        # are untouched). This only answers tidily for OLD menu messages whose batch buttons still carry
        # an "le.N" query, instead of leaving them on a silently empty tray.
        await event.answer([], cache_time=0, switch_pm="🎗️ Limited Editions browsing has been removed.", switch_pm_param="start")
    elif query_text.startswith("dex."):
        await handle_dex_inline_query(event, query_text)
    elif query_text.startswith(("/coll ", "/obtain ", "/collect ", "/catch ")):
        await handle_collect_inline_query(event, query_text)
    elif query_text.startswith("buyowner."):
        await handle_buyowner_inline_query(event, query_text)
    else:
        await event.answer([], cache_time=0)

# ---- Callback for view_all_cards ----
@bot1.on(events.CallbackQuery(pattern=r'^view_all_cards_(\d+)$'))
async def view_all_cards_callback(event):
    user_id = int(event.pattern_match.group(1))
    user_doc = await users_catcher_col.find_one({"user_id": user_id})
    if not user_doc or not user_doc.get("harem"):
        return await event.answer("📭 This vault is empty!", alert=True)
    raw_harem = user_doc.get("harem", [])
    rarity_filter = user_doc.get("rarity_filter")
    filtered_harem = []
    if rarity_filter:
        for item in raw_harem:
            if isinstance(item, dict) and classify_rarity(item.get("rarity")) == classify_rarity(rarity_filter):
                filtered_harem.append(item)
    else:
        filtered_harem = raw_harem
    if not filtered_harem:
        return await event.answer("❌ No cards found with current filter!", alert=True)
    unique_cards = {}
    for item in filtered_harem:
        if isinstance(item, dict) and "char_id" in item:
            cid = item["char_id"]
            if cid not in unique_cards:
                unique_cards[cid] = {"count": 0, "item": item}
            unique_cards[cid]["count"] += 1
    if not unique_cards:
        return await event.answer("❌ No valid cards found!", alert=True)
    card_ids = list(unique_cards.keys())
    page = 1
    per_page = 5
    total_pages = (len(card_ids) + per_page - 1) // per_page
    await send_gallery_page(event, user_id, card_ids, unique_cards, page, per_page, total_pages)

async def send_gallery_page(event, user_id, card_ids, unique_cards, page, per_page, total_pages):
    start_idx = (page - 1) * per_page
    end_idx = min(start_idx + per_page, len(card_ids))
    page_card_ids = card_ids[start_idx:end_idx]
    try:
        owner_ent = await bot1.get_entity(user_id)
        first = getattr(owner_ent, 'first_name', '') or ''
        last = getattr(owner_ent, 'last_name', '') or ''
        owner_name = f"{first} {last}".strip() or getattr(owner_ent, 'username', '') or "Hunter"
    except Exception:
        owner_name = "Hunter"
    gallery_text = f"👀 <b>{escape_html(owner_name)}'s Card Gallery</b>\n"
    filter_doc = await users_catcher_col.find_one({"user_id": user_id})
    rarity_filter = filter_doc.get("rarity_filter") if filter_doc else None
    if rarity_filter:
        gallery_text += f"🔍 <b>Filter:</b> {current_rarity_filter_name(rarity_filter)}\n"
    gallery_text += f"📑 <b>Page {page}/{total_pages}</b> · <b>Total Cards:</b> {len(card_ids)}\n\n"
    gallery_text += f"<i>✨ Tap a card below to see its details</i>\n"
    buttons = []
    row = []
    for idx, cid in enumerate(page_card_ids):
        card_data = await characters_base_col.find_one({"char_id": cid})
        if not card_data:
            continue
        card_name = card_data.get("name", "Unknown")
        emoji = card_data.get("rarity", RARITY_DEFAULT_EMOJI)[0] if card_data.get("rarity") else RARITY_DEFAULT_EMOJI
        count = unique_cards[cid]["count"]
        label = f"{emoji} {card_name} x{count}"
        row.append(Button.inline(label, data=f"card_detail_{cid}_{user_id}"))
        if len(row) == 2:
            buttons.append(row)
            row = []
    if row:
        buttons.append(row)
    nav_row = []
    if page > 1:
        nav_row.append(Button.inline("⬅️ Prev", data=f"gallery_page_{page-1}_{user_id}"))
    if page < total_pages:
        nav_row.append(Button.inline("Next ➡️", data=f"gallery_page_{page+1}_{user_id}"))
    if nav_row:
        buttons.append(nav_row)
    buttons.append([Button.inline("🔙 Back to Vault", data=f"harem_1_{user_id}")])
    await event.edit(gallery_text, parse_mode='html', buttons=buttons)

