# ==========================================
DAILY_BUY_LIMIT = 30  # 🩹 2026-11 (per owner request, negotiable buy): SUCCESSFUL Owner Shop purchases (/buy [char_id] + /show 🛒) per player per day — "Not Deal" attempts are never counted
LIFETIME_BUY_PER_CHAR_LIMIT = 1  # max copies of the SAME character a player can EVER buy via /buy
TOP_RARITY_WEEKLY_TIERS = {"ULTRA", "LEGEND", "MYTHIC"}  # Rarity No.1, No.2, No.3
TOP_RARITY_WEEKLY_BUY_LIMIT = 2  # combined cap across ALL THREE tiers together, per rolling week
TOP_RARITY_WEEK_SECONDS = 7 * 86400
# 🔒 NEW CARD PROTECTION — a freshly /addchar'd character can't be bought outright via …
NEW_CARD_PROTECTION_SECONDS = 86400  # 24 hours

# ==========================================
# 👑 BOT VIP MODE — tuning constants
# ==========================================
VIP_AUTO_STAR_THRESHOLD = 100  # 💠 VLT spent (via /buy Owner Shop) in one day auto-grants VIP
VIP_AUTO_GRANT_DAYS = 1  # length of the auto-grant, from the moment the threshold is crossed
VIP_PRICE_VLT = int(os.environ.get("VIP_PRICE_VLT", "7000"))   # 💠 for one month of VIP
VIP_DAYS = 30                                                       # days one purchase credits
VIP_RENEW_WINDOW_DAYS = 3        # no pre-buying: a new month can only be bought when VIP is off or has <= this many days left
VIP_VLT_SELL_RATIO = 0.95        # NEW perk: VIP sells 💠 at 95% of the live rate (5% fee) instead of VLT_SELL_RATIO (90%)
VIP_DAILY_CATCH_LIMIT = 30  # vs DAILY_CATCH_LIMIT (22) for everyone else  (was 25 before the 2026-10 VIP rework)
VIP_SPAM_MUTE_SECONDS = 180  # 3 minutes, vs SPAM_CATCH_MUTE_SECONDS (8 min / 480s)
VIP_QUIZ_REWARD_MULTIPLIER = 1.5  # VIP winners' rarity-gate quiz Star bonus is scaled by this
# 🩹 CHANGED (2026-10, per owner request — "Divine ကဒ်တွေပြောင်းပေး"): the purchase bonus is now DIVINE (Rarity No.4, tier key "EPIC") instead of 2 x
# GOLDENMOON. NOTE: until now the bonus was only ADVERTISED in the /buyvipmode text — nothing in the purchase code ever granted it. It is granted for real
# now (grant_vip_bonus_cards). Only the buyer's own purchase pays it (never a gift), and only one month can be bought at a time, so it can't be farmed.
VIP_PURCHASE_BONUS_TIER = "EPIC"
VIP_PURCHASE_BONUS_COUNT = int(os.environ.get("VIP_BONUS_DIVINE_COUNT", "1"))

def is_vip_active(user_doc):
    """True if user_doc's premium_until is still in the future. Safe to call with None."""
    return bool(user_doc) and user_doc.get("premium_until", 0) > time.time()

async def check_vip(user_id):
    doc = await users_catcher_col.find_one({"user_id": user_id}, {"premium_until": 1})
    return is_vip_active(doc)

async def grant_vip_days(user_id, days):
    """Extends premium_until by `days`. Stacks on top of any time already remaining —
    buying/earning more while already VIP adds to what's left instead of overwriting it."""
    now = time.time()
    user_doc = await users_catcher_col.find_one({"user_id": user_id}, {"premium_until": 1})
    current_until = (user_doc or {}).get("premium_until", 0)
    base = current_until if current_until > now else now
    new_until = base + days * 86400
    await users_catcher_col.update_one({"user_id": user_id}, {"$set": {"premium_until": new_until}}, upsert=True)
    return new_until

async def _track_star_activity_and_maybe_grant_vip(user_id, kind, amount):
    """kind 'spent' = 💠 VLT spent on /buy Owner Shop purchases (the only kind still used; 'bought' is dead since /buystar was retired). Tracks the per-day total and grants VIP_AUTO_GRANT_DAYS of VIP the first time it crosses VIP_AUTO_STAR_THRESHOLD in a Yangon day; returns the new premium_until or None."""
    field = "star_spent_today" if kind == "spent" else "star_bought_today"
    today_str = datetime.now(TZ).strftime("%Y-%m-%d")
    user_doc = await users_catcher_col.find_one({"user_id": user_id}, {"star_activity_date": 1, field: 1})
    if not user_doc or user_doc.get("star_activity_date") != today_str:
        await users_catcher_col.update_one(
            {"user_id": user_id},
            {"$set": {"star_activity_date": today_str, "star_spent_today": 0.0, "star_bought_today": 0.0}},
            upsert=True
        )
        before = 0.0
    else:
        before = user_doc.get(field, 0.0)
    updated = await users_catcher_col.find_one_and_update(
        {"user_id": user_id}, {"$inc": {field: amount}}, return_document=ReturnDocument.AFTER
    )
    after = updated.get(field, before + amount) if updated else before + amount
    if before < VIP_AUTO_STAR_THRESHOLD <= after:
        return await grant_vip_days(user_id, VIP_AUTO_GRANT_DAYS)
    return None

