import math as _math_neg

NEGOTIATE_BUY_TIMEOUT_SECONDS = 240      # one prompt stays open for 4 minutes
NEGOTIATE_BUY_RETRY_WINDOW = 600         # the 🔄 button under a "Not Deal" keeps working for 10 minutes
NEGOTIATE_BUY_ACCEPT_MIN_PROB = 0.20     # chance of a Deal at exactly the minimum offer
NEGOTIATE_BUY_ACCEPT_MAX_PROB = 0.80     # chance just under the maximum (the maximum itself is a sure sale)
NEGOTIATE_BUY_RETRY_MUST_RAISE = True    # after a Not Deal the next offer must be higher — stops spam-retrying the minimum until it hits
NEGOTIATE_BUY_SWEEP_INTERVAL = 60        # an idle prompt is closed (and its owner told) within ~1 min of the 4-min timeout
_NEG_RNG = random.SystemRandom()
_buy_neg_sweeper_task = None

pending_buy_negotiations = {}            # user_id -> {chat_id, prompt_msg_id, char_id, char_name, lo, hi, started_at, last_rejected}
_buy_retry_pending = {}                  # token -> {user_id, chat_id, char_id, last_rejected, ts}
_buy_last_reject = {}                    # (user_id, char_id) -> (last rejected offer, ts) — the "offer higher" rule survives tapping 🛒 / /buy again


def _buy_bounds(char_doc):
    """(lo, hi) whole-💠 offer bounds of a card, from its /setvalue band."""
    mn, mx = value_range_for_char(char_doc)
    return max(1, _math_neg.ceil(mn)), int(mx)


def _negotiate_accept_probability(offer, lo, hi):
    if offer >= hi:
        return 1.0
    if offer <= lo:
        return NEGOTIATE_BUY_ACCEPT_MIN_PROB
    ratio = (offer - lo) / (hi - lo)
    return NEGOTIATE_BUY_ACCEPT_MIN_PROB + (NEGOTIATE_BUY_ACCEPT_MAX_PROB - NEGOTIATE_BUY_ACCEPT_MIN_PROB) * ratio


def _parse_buy_offer(raw):
    """'800' / '1,000' / '1000 vlt' / '1k' / '1.5k' -> whole number; None if it isn't a positive whole number."""
    if not raw:
        return None
    t = raw.lower().replace(",", "").replace("_", "").replace("vlt", "").replace("💠", "").strip()
    mult = 1
    if t.endswith("k"):
        mult, t = 1000, t[:-1].strip()
    try:
        v = float(t) * mult
    except ValueError:
        return None
    if v <= 0 or not v.is_integer():          # also rejects nan / inf
        return None
    return int(v)


def _neg_expired(neg):
    return time.time() - neg["started_at"] > NEGOTIATE_BUY_TIMEOUT_SECONDS


def _buy_neg_prune():
    now = time.time()
    for uid, neg in list(pending_buy_negotiations.items()):
        if now - neg["started_at"] > NEGOTIATE_BUY_TIMEOUT_SECONDS + 60:
            pending_buy_negotiations.pop(uid, None)
    for tok, st in list(_buy_retry_pending.items()):
        if now - st["ts"] > NEGOTIATE_BUY_RETRY_WINDOW + 60:
            _buy_retry_pending.pop(tok, None)
    for key, (_o, ts) in list(_buy_last_reject.items()):
        if now - ts > NEGOTIATE_BUY_RETRY_WINDOW:
            _buy_last_reject.pop(key, None)


class _BuyPromptRef:
    """Just enough of a sent message (.id) for a prompt that was EDITED into place instead of sent as a new message."""
    def __init__(self, id):
        self.id = id


async def _buy_neg_begin(user_id, chat_id, char_id, send, last_rejected=0, prompt_send=None, refuse_send=None):
    """Opens a negotiation for char_id — or buys outright when the card has no price range (min == max) or the buyer is the Owner.
    `send` = the event's reply function (the purchase result goes through it). Two optional hooks are used by the 🔄 button under a "Not Deal":
      prompt_send  sends ONLY the "how much can you pay?" prompt — the 🔄 button passes a function that EDITS the "Not Deal" message into a 2-line prompt, so a counter-offer
                   adds nothing to the chat (2026-11, owner: "ပြန်ကမ်းလှမ်းမည် user က လုပ်တိုင်း စာအရှည်ကြီးနဲ့ ပြန်ပြန်ပို့နေတယ် မကြိုက်ဘူး"). Without it: the 3-line first prompt.
      refuse_send  sends the refusals (card gone / sold out / not enough 💠) — the 🔄 button shows them as a pop-up on the button instead of another message.
    Returns True when a prompt (or a purchase) was produced."""
    refuse = refuse_send or send
    _buy_neg_prune()
    existing = pending_buy_negotiations.get(user_id)
    if existing and _neg_expired(existing):
        existing = None                                        # stale — the sweeper tells the player; nothing to replace
    # An open prompt is NOT a blocker: the new card is validated first (a refusal leaves the old prompt untouched), then the old one is replaced.
    char_doc = await characters_base_col.find_one({"char_id": char_id})
    if not char_doc:
        await refuse("❌ <b>ဒီ Character ID ကို ရှာမတွေ့ပါ။</b>", parse_mode='html')
        return False
    if user_id != OWNER_ID and char_doc.get("rarity_tier") in SHOW_NO_VLT_TIERS:     # 🚫 ULTRA / SUPREME: HELLO collector message + [Check ID] [Owner DM]
        await refuse(_top_tier_buy_text(char_doc), parse_mode='html', buttons=await _top_tier_buy_buttons(user_id, char_doc))
        return False
    blocked = await _star_shop_blocker(user_id, char_doc)
    if blocked:
        await refuse(blocked[1], parse_mode='html')
        return False
    lo, hi = _buy_bounds(char_doc)
    if user_id == OWNER_ID or lo >= hi:                       # nothing to negotiate -> the classic fixed-price purchase
        ok, msg = await execute_star_shop_purchase(user_id, char_id)
        await send(msg, parse_mode='html')
        return ok
    udoc = await users_catcher_col.find_one({"user_id": user_id}, {"vlt_balance": 1})
    have = (udoc or {}).get("vlt_balance", 0)
    if have < lo:
        await refuse(f"❌ <b>VLT မလုံလောက်ပါ</b> — အနည်းဆုံး <code>{lo}💠</code> လို · ရှိတာ <code>{format_vlt_plain(have)}</code>", parse_mode='html')
        return False
    if NEGOTIATE_BUY_RETRY_MUST_RAISE:                         # the seller remembers: tapping 🛒 / /buy again is no way around "offer higher"
        rec = _buy_last_reject.get((user_id, char_id))
        if rec and time.time() - rec[1] <= NEGOTIATE_BUY_RETRY_WINDOW:
            last_rejected = max(last_rejected, rec[0])
    # the lowest offer that can still be taken: the card's minimum — or one above the last "Not Deal" (so the range shown here is the real one)
    need = max(lo, last_rejected + 1) if (last_rejected and NEGOTIATE_BUY_RETRY_MUST_RAISE) else lo
    name = escape_html(char_doc.get('name') or char_id)
    if prompt_send is not None:
        text = (f"🔄 <b>{name}</b> · <code>{need} ~ {hi}💠</code>\n"
                f"ဒီ message ကို <b>reply</b> လုပ်ပြီး ပိုပေးပါ။ ⏳ 4 မိနစ်")
        post = prompt_send
    else:
        text = (f"🛒 <b>{name}</b> <code>{display_char_id(char_id)}</code> · {char_doc.get('rarity', '')}\n"
                f"💠 <code>{need} ~ {hi}</code> · ဘယ်လောက်ပေးမလဲ? ဒီ message ကို <b>reply</b> လုပ်ပြီး ဂဏန်းပဲ ရိုက်ပါ။\n"
                f"⏳ 4 မိနစ် · <code>/cancelbuy</code>")
        post = send
    sent = await post(text, parse_mode='html')
    old = pending_buy_negotiations.get(user_id)                # read at the moment of the swap, so a racing second tap is replaced too
    pending_buy_negotiations[user_id] = {
        "chat_id": chat_id, "prompt_msg_id": sent.id, "char_id": char_id, "char_name": char_doc.get("name") or char_id,
        "lo": lo, "hi": hi, "started_at": time.time(), "last_rejected": last_rejected}
    if old and old.get("prompt_msg_id") != sent.id and not _neg_expired(old):
        try:                                                   # the replaced prompt can no longer be answered — say so on it
            await bot1.edit_message(old["chat_id"], old["prompt_msg_id"],
                                    f"🔁 <b>{escape_html(old.get('char_name') or '')}</b> — <i>offer ကို ပယ်ဖျက်ပြီး ကဒ်အသစ်အတွက် ပြောင်းလိုက်ပါပြီ။</i>", parse_mode='html')
        except Exception:
            pass
    return True


@bot1.on(events.NewMessage(incoming=True, func=lambda e: bool(e.is_reply) and e.sender_id in pending_buy_negotiations))
async def negotiate_buy_reply_handler(event):
    user_id = event.sender_id
    neg = pending_buy_negotiations.get(user_id)
    if not neg or event.reply_to_msg_id != neg["prompt_msg_id"]:
        return
    raw = (event.raw_text or "").strip()
    if not raw or (raw[0] in "/." and len(raw) > 1 and raw[1].isalpha() and raw.lower().lstrip("/.").split("@")[0] != "cancelbuy"):
        return                                                 # empty / some other command — not an offer
    if _neg_expired(neg):
        pending_buy_negotiations.pop(user_id, None)
        return await event.reply("⏳ <b>အချိန်ကျော်သွားပါပြီ။</b> 🛒 Buy ကို ထပ်နှိပ်ပါ။", parse_mode='html')
    if raw.lower().lstrip("/.").split("@")[0].strip("! ") in ("cancelbuy", "cancel", "no"):
        pending_buy_negotiations.pop(user_id, None)
        return await event.reply("❌ <b>ပယ်ဖျက်ပြီး။</b>", parse_mode='html')
    offer = _parse_buy_offer(raw)
    if offer is None:
        return await event.reply("🔢 <b>ဂဏန်းတစ်ခုတည်း ရိုက်ပါ။</b> <i>(ဥပမာ <code>800</code>)</i>", parse_mode='html')
    lo, hi, char_id = neg["lo"], neg["hi"], neg["char_id"]
    if offer < lo:
        return await event.reply(f"❌ <b>အနည်းဆုံး <code>{lo}💠</code></b> ပေးရပါမယ်။", parse_mode='html')
    if NEGOTIATE_BUY_RETRY_MUST_RAISE and neg.get("last_rejected") and offer <= neg["last_rejected"]:
        return await event.reply(f"⬆️ <b><code>{neg['last_rejected'] + 1}💠</code> ကစပြီး ပေးပါ။</b>", parse_mode='html')
    charge = min(offer, hi)                                    # never charge above the max
    udoc = await users_catcher_col.find_one({"user_id": user_id}, {"vlt_balance": 1})
    have = (udoc or {}).get("vlt_balance", 0)
    if have < charge:
        return await event.reply(f"❌ <b>VLT မလုံလောက်ပါ</b> — <code>{charge}💠</code> လို · ရှိတာ <code>{format_vlt_plain(have)}</code> <i>(ပိုနည်းတဲ့ စျေးနဲ့ ပြန် reply လုပ်ပါ)</i>", parse_mode='html')
    if pending_buy_negotiations.pop(user_id, None) is None:     # a second reply that slipped in while we awaited — only one may decide
        return
    deal = offer >= hi or _NEG_RNG.random() < _negotiate_accept_probability(offer, lo, hi)
    if deal:
        ok, msg = await execute_star_shop_purchase(user_id, char_id, custom_price=charge)
        if ok:
            _buy_last_reject.pop((user_id, char_id), None)
        return await event.reply(("🤝 <b>Deal!</b>\n" if ok else "") + msg, parse_mode='html')
    _buy_last_reject[(user_id, char_id)] = (offer, time.time())
    token = secrets.token_hex(4)
    _buy_retry_pending[token] = {"user_id": user_id, "chat_id": event.chat_id, "char_id": char_id, "last_rejected": offer, "ts": time.time()}
    await event.reply(
        f"💔 <b>Not Deal</b> · <code>{offer}💠</code>",
        parse_mode='html',
        buttons=[[Button.inline("🔄 ပြန်ကမ်းလှမ်းမည်", data=f"negbuy_retry_{token}"),
                  Button.inline("❌ တော်ပြီ", data=f"negbuy_cancel_{user_id}")]])


@bot1.on(events.CallbackQuery(pattern=r'^negbuy_retry_([0-9a-f]{8})$'))
async def negotiate_buy_retry_cb(event):
    token = _dec(event.pattern_match.group(1))
    st = _buy_retry_pending.get(token)
    if not st:
        return await event.answer("⌛ သက်တမ်းကုန်သွားပါပြီ — 🛒 Buy ကို ပြန်နှိပ်ပါ။", alert=True)
    if event.sender_id != st["user_id"]:
        return await event.answer("⚠️ ဒါက သင့် offer မဟုတ်ပါ။", alert=True)
    if time.time() - st["ts"] > NEGOTIATE_BUY_RETRY_WINDOW:
        _buy_retry_pending.pop(token, None)
        return await event.answer("⌛ သက်တမ်းကုန်သွားပါပြီ — 🛒 Buy ကို ပြန်နှိပ်ပါ။", alert=True)
    if not claim_single_tap(event):
        return await event.answer("⏳ One moment…")
    _buy_retry_pending.pop(token, None)
    answered = {"v": False}          # a callback can be answered only ONCE — so it is answered at the very end, unless a refusal already used it as a pop-up

    # 🧹 2026-11 (owner: "ပြန်ကမ်းလှမ်းမည် user က လုပ်တိုင်း စာအရှည်ကြီးနဲ့ ပြန်ပြန်ပို့နေတယ်"): a counter-offer used to send the whole "Name Your Price" prompt as a NEW message every time.
    # Now the "Not Deal" message the button sits under is EDITED into a 2-line prompt (and becomes the message the buyer replies to); a refusal (card gone, sold out, not
    # enough 💠) is a pop-up on the button when it is short — the Not Deal message and its 🔄 stay as they were. Nothing is added to the chat.
    async def _refuse(text, **kw):
        plain = re.sub(r"<[^>]+>", "", unescape_html(text)).strip()
        if len(plain) <= 190 and not kw.get("buttons"):
            answered["v"] = True
            await event.answer(plain, alert=True)
            return None
        return await event.reply(text, parse_mode='html', buttons=kw.get("buttons"))

    async def _edit_prompt(text, **kw):
        try:
            res = await event.edit(text, parse_mode='html', buttons=None)
            return _BuyPromptRef(getattr(res, "id", None) or event.message_id)
        except Exception:
            return await event.reply(text, parse_mode='html')     # the old message can't be edited any more — a short prompt as a new message is still fine

    started = await _buy_neg_begin(st["user_id"], st["chat_id"], st["char_id"], event.reply,
                                   last_rejected=st["last_rejected"] if NEGOTIATE_BUY_RETRY_MUST_RAISE else 0,
                                   prompt_send=_edit_prompt, refuse_send=_refuse)
    if not started:
        _buy_retry_pending[token] = st                         # couldn't open a new prompt (e.g. sold out meanwhile) — keep the button alive
    if not answered["v"]:
        await event.answer()


@bot1.on(events.CallbackQuery(pattern=r'^negbuy_cancel_(\d+)$'))
async def negotiate_buy_cancel_cb(event):
    uid = int(event.pattern_match.group(1))
    if event.sender_id != uid:
        return await event.answer("⚠️ ဒါက သင့် offer မဟုတ်ပါ။", alert=True)
    pending_buy_negotiations.pop(uid, None)
    for k in [k for k, v in _buy_retry_pending.items() if v["user_id"] == uid]:
        _buy_retry_pending.pop(k, None)
    await event.answer("❌ ပယ်ဖျက်ပြီး။")
    try:
        await event.edit("❌ <b>တော်ပြီ။</b>", parse_mode='html', buttons=None)
    except Exception:
        pass


@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]cancelbuy(?:@\w+)?$', 'bot1')))
async def cancel_buy_cmd(event):
    uid = event.sender_id
    cleared = pending_buy_negotiations.pop(uid, None) is not None
    for k in [k for k, v in _buy_retry_pending.items() if v["user_id"] == uid]:
        _buy_retry_pending.pop(k, None)
        cleared = True
    await event.reply("❌ <b>ပယ်ဖျက်ပြီးပါပြီ။</b>" if cleared else "ℹ️ သင့်မှာ ဖွင့်ထားတဲ့ offer မရှိပါဘူး။", parse_mode='html')


async def _buy_neg_user_link(uid):
    """Clickable mention (so the player gets pinged in a group). Falls back to a generic label if Telegram can't resolve the user."""
    name = "Player"
    try:
        ent = await bot1.get_entity(uid)
        name = (" ".join(x for x in (getattr(ent, "first_name", None), getattr(ent, "last_name", None)) if x)
                or getattr(ent, "username", None) or name)
    except Exception:
        pass
    return f'<a href="tg://user?id={uid}">{escape_html(name)}</a>'


async def _buy_neg_sweep_once():
    """Closes every negotiation nobody answered within NEGOTIATE_BUY_TIMEOUT_SECONDS: drops it from RAM and tells the player.
    Also drops expired 🔄 retry tokens. Nothing was ever charged, so there is nothing to refund."""
    now = time.time()
    for uid, neg in list(pending_buy_negotiations.items()):
        if now - neg["started_at"] <= NEGOTIATE_BUY_TIMEOUT_SECONDS:
            continue
        if pending_buy_negotiations.pop(uid, None) is None:      # the reply handler consumed it a moment ago
            continue
        text = f"⏳ {await _buy_neg_user_link(uid)} — <b>{escape_html(neg.get('char_name') or '')}</b> offer အချိန်ကျော်လို့ ပိတ်လိုက်ပါပြီ။"
        try:
            await bot1.send_message(neg["chat_id"], text, parse_mode='html', reply_to=neg.get("prompt_msg_id"), link_preview=False)
        except Exception:
            try:
                await bot1.send_message(neg["chat_id"], text, parse_mode='html', link_preview=False)   # the prompt itself may be deleted
            except Exception as e:
                print(f"buy negotiation timeout notice failed for {uid}: {type(e).__name__}: {e}")
    for tok, st in list(_buy_retry_pending.items()):
        if now - st["ts"] > NEGOTIATE_BUY_RETRY_WINDOW:
            _buy_retry_pending.pop(tok, None)
    for key, (_o, ts) in list(_buy_last_reject.items()):
        if now - ts > NEGOTIATE_BUY_RETRY_WINDOW:
            _buy_last_reject.pop(key, None)


async def buy_negotiation_sweeper_loop():
    while True:
        try:
            await _buy_neg_sweep_once()
        except Exception as e:
            print(f"buy negotiation sweeper error: {e}")
        await asyncio.sleep(NEGOTIATE_BUY_SWEEP_INTERVAL)


def start_buy_negotiation_sweeper():
    """Called once per bot1 start (run_bot1_forever); a reconnect loop never stacks a second copy."""
    global _buy_neg_sweeper_task
    if _buy_neg_sweeper_task is None or _buy_neg_sweeper_task.done():
        _buy_neg_sweeper_task = asyncio.create_task(buy_negotiation_sweeper_loop())


# ---- /buytoggle: owner switches a rarity tier's Owner Shop purchase on/off ("sold out").
# Blocks BOTH /buy [char_id] and the /show gallery's 🛒 Buy button for that tier — catching it
# from a live spawn is never affected. Bare /buytoggle shows current status of all 9 tiers. ----
def _buytoggle_status_text():
    lines = ["🛍️ <b>Owner Shop — Rarity On/Off Status</b>\n"]
    for tier in RARITY_TIERS:
        num = RARITY_TIER_TO_NUM[tier]
        emoji = RARITY_EMOJI.get(tier, RARITY_DEFAULT_EMOJI)
        state = "🚫 <b>ပိတ်ထား</b> (Sold out)" if tier in _cached_disabled_buy_tiers else "✅ <b>ဖွင့်ထား</b>"
        lines.append(f"No.{num} {emoji} {tier} — {state}")
    lines.append("\n<b>Usage:</b> <code>/buytoggle no1</code> <i>(No.1..No.9 တစ်ခုချင်းစီကို ပိတ်/ဖွင့် Toggle)</i>")
    return "\n".join(lines)

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]buytoggle(?:@\w+)?(?:\s+(?:no)?([1-9]))?$', 'bot1')))
async def buy_tier_toggle_handler(event):
    if event.sender_id != OWNER_ID: return
    global _cached_disabled_buy_tiers
    arg = event.pattern_match.group(1)
    if not arg:
        return await event.reply(_buytoggle_status_text(), parse_mode='html')
    tier = RARITY_TIERS[int(arg) - 1]
    if tier in _cached_disabled_buy_tiers:
        _cached_disabled_buy_tiers.discard(tier)
        action = "✅ <b>ပြန်ဖွင့်လိုက်ပါပြီ</b> — ဝယ်လို့ရပါပြီ"
    else:
        _cached_disabled_buy_tiers.add(tier)
        action = "🚫 <b>ပိတ်လိုက်ပါပြီ</b> — အရောင်းကုန် ဖြစ်သွားပါပြီ"
    await bot_settings_col.update_one(
        {"_id": "disabled_buy_tiers"},
        {"$set": {"tiers": sorted(_cached_disabled_buy_tiers)}},
        upsert=True
    )
    emoji = RARITY_EMOJI.get(tier, RARITY_DEFAULT_EMOJI)
    await event.reply(
        f"{emoji} <b>{tier}</b> (No.{arg}) — {action}\n\n" + _buytoggle_status_text(),
        parse_mode='html'
    )

# ---- /setvalue (2026-10, per owner request) — OWNER ONLY. Sets a card value band  min ~ max  per rarity …
def _fmt_vlt_num(n):
    return format_vlt_plain(n).replace(' 💠', '')

def _value_band_label(tier, event_no=None):
    label = f"{RARITY_EMOJI.get(tier, RARITY_DEFAULT_EMOJI)} {RARITY_DISPLAY_NAME.get(tier, tier)}"
    if event_no is not None:
        label += f" · {EVENT_TYPES[event_no]}"
    return label

def _setvalue_status_text():
    lines = ["💠 <b>Card Value Bands</b> <i>(min ~ max — max is the real Owner Shop price)</i>\n"]
    for tier in RARITY_TIERS:
        mn, mx = tier_value_range(tier)
        mark = " ✏️" if tier in _cached_value_overrides else ""
        lines.append(f"No.{RARITY_TIER_TO_NUM[tier]} {_value_band_label(tier)} — <code>{_fmt_vlt_num(mn)} ~ {_fmt_vlt_num(mx)}</code>{mark}")
        if tier == "ULTRA":
            for ev in sorted(EVENT_TYPES):
                ov = _cached_value_overrides.get(f"ULTRA:{ev}")
                if ov:
                    lines.append(f"   ↳ {EVENT_TYPES[ev]} — <code>{_fmt_vlt_num(ov['min'])} ~ {_fmt_vlt_num(ov['max'])}</code> ✏️")
    lines.append("\n✏️ = owner-set, otherwise default.")
    lines.append(
        "\n<b>Usage:</b>\n"
        "<code>/setvalue no3 800 ~ 1200</code> <i>(tier No.3)</i>\n"
        "<code>/setvalue no1 e7 3000 ~ 4800</code> <i>(ULTRA, Event 7 only)</i>\n"
        "<code>/setvalue no3 reset</code> · <code>/setvalue no1 e7 reset</code> <i>(back to default)</i>\n\n"
        f"{event_list_html()}"
    )
    return "\n".join(lines)

def _value_order_warnings(tier, mx):
    """Soft warning only — a rarer tier should cost more than the next one down."""
    out = []
    idx = RARITY_TIERS.index(tier)
    if idx + 1 < len(RARITY_TIERS):
        lower = RARITY_TIERS[idx + 1]
        lower_max = tier_value_range(lower)[1]
        if lower_max >= mx:
            out.append(f"⚠️ No.{idx + 2} {RARITY_DISPLAY_NAME.get(lower, lower)} max is {_fmt_vlt_num(lower_max)} — not below this one.")
    if idx > 0:
        upper = RARITY_TIERS[idx - 1]
        upper_max = tier_value_range(upper)[1]
        if upper_max <= mx:
            out.append(f"⚠️ No.{idx} {RARITY_DISPLAY_NAME.get(upper, upper)} max is {_fmt_vlt_num(upper_max)} — not above this one.")
    return out

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]setvalue(?:@\w+)?(?:\s+([\s\S]+))?$', 'bot1')))
async def setvalue_handler(event):
    if event.sender_id != OWNER_ID: return
    if is_duplicate_event(event): return
    arg = (event.pattern_match.group(1) or "").strip()
    if not arg:
        return await event.reply(_setvalue_status_text(), parse_mode='html')

    m = re.match(
        r'^(?:no)?([1-9])(?:\s+e([1-9]))?\s+(?:(reset|default|clear)|([\d,]+)\s*(?:~|-|–|to)\s*([\d,]+))$',
        arg, re.IGNORECASE
    )
    if not m:
        return await event.reply("❌ <b>Format မမှန်ပါ။</b>\n\n" + _setvalue_status_text(), parse_mode='html')

    tier = RARITY_TIERS[int(m.group(1)) - 1]
    ev = int(m.group(2)) if m.group(2) else None
    if ev is not None:
        if tier != "ULTRA":
            return await event.reply("❌ <b>Event တစ်ခုချင်း သတ်မှတ်လို့ရတာ ULTRA (no1) တစ်ခုတည်းပါ။</b>", parse_mode='html')
        if ev not in EVENT_TYPES:
            return await event.reply(f"❌ Event must be 1-{len(EVENT_TYPES)}.\n\n{event_list_html()}", parse_mode='html')
    key = value_override_key(tier, ev)
    label = _value_band_label(tier, ev)

    # ---- reset ----
    if m.group(3):
        if key not in _cached_value_overrides:
            return await event.reply(f"ℹ️ <b>{label}</b> က default အတိုင်းပါပဲ။", parse_mode='html')
        _cached_value_overrides.pop(key, None)
        await bot_settings_col.update_one({"_id": "card_value_overrides"}, {"$unset": {f"values.{key}": ""}}, upsert=True)
        dmn, dmx = tier_value_range(tier)  # after a reset an ULTRA event falls back to the tier-wide band
        return await event.reply(
            f"♻️ <b>{label}</b> — default ပြန်ထားပြီး။\n\n"
            f"💰 <b>Value:</b> <code>{_fmt_vlt_num(dmn)} ~ {_fmt_vlt_num(dmx)}</code> 💠",
            parse_mode='html'
        )

    # ---- set ----
    mn = int(m.group(4).replace(",", ""))
    mx = int(m.group(5).replace(",", ""))
    if mn < 1 or mx < mn:
        return await event.reply("❌ <b>min က ၁ ထက်မနည်း၊ max က min ထက်မနည်းရပါမယ်။</b> ဥပမာ <code>/setvalue no3 800 ~ 1200</code>", parse_mode='html')

    _cached_value_overrides[key] = {"min": mn, "max": mx}
    await bot_settings_col.update_one(
        {"_id": "card_value_overrides"},
        {"$set": {f"values.{key}": {"min": mn, "max": mx}}},
        upsert=True
    )
    scrap_amt = round(mx * SELL_ALL_MULT, 2)
    notes = []
    _floor_min = _apply_buy_floor(mn, mx)[0]
    if _floor_min > mn:
        notes.append(f"🛡 Min ကို <code>{_fmt_vlt_num(_floor_min)}</code> အထိ မြှင့်ထားပါတယ် (= /sell ပေးတဲ့ဈေးရဲ့ {BUY_FLOOR_MULT:g} ဆ) — ဒါမှ buy → sell လုပ်လို့ အမြတ်မရမှာပါ။")
    if tier == "ULTRA" and ev is None:
        notes.append("ℹ️ ULTRA Event တစ်ခုချင်းအတွက် သီးသန့်သတ်မှတ်ထားရင် အဲ့ဒါကို ဦးစားပေးပါမယ်။")
    if ev is None:
        notes += _value_order_warnings(tier, mx)
    else:
        lower_max = tier_value_range(RARITY_TIERS[1])[1]
        if lower_max >= mx:
            notes.append(f"⚠️ No.2 {RARITY_DISPLAY_NAME.get(RARITY_TIERS[1], RARITY_TIERS[1])} max is {_fmt_vlt_num(lower_max)} — not below this one.")
    await event.reply(
        f"✅ <b>{label}</b> — value set\n\n"
        f"💰 <b>Value:</b> <code>{_fmt_vlt_num(mn)} ~ {_fmt_vlt_num(mx)}</code> 💠\n"
        f"🛒 <b>Owner Shop (/buy):</b> <code>{_fmt_vlt_num(mx)}</code> 💠\n"
        f"🔥 <b>Sell (/sell):</b> <code>{_fmt_vlt_num(scrap_amt)}</code> 💠 <i>({SELL_ALL_MULT * 100:g}% of the shop price)</i>"
        + ("\n\n" + "\n".join(notes) if notes else ""),
        parse_mode='html'
    )

# ==========================================
# 🎞 /noevent + /ultravalue (2026-11, per owner request — "Ultra မှာ event မပါတာ ကြည့်ချင်တယ်၊ ကိုယ်တိုင်ပြန်သတ်မှတ်ချင်တယ်၊ ultra & supreme value min max သတ်မှတ်ချင်သေးတယ်")
# ==========================================
# An ULTRA card added without an Event has no event_no, so it is priced by the tier-wide ULTRA band instead of its Event's own band (see VALUE BANDS) —
# which matters, because the Owner Shop price (the band's max) is what ULTRA/SUPREME cards are sold at.
#   /noevent [page]   -> every ULTRA card with no Event, 20 per page (◀ 🔄 ▶), with a ready-to-edit  /setevent N | <the page's IDs>  line. The Events are
#                        still set BY HAND with the existing /setevent (N = 1 Anime … 8 Live-Action) — nothing is ever assigned automatically.
#   /ultravalue       -> read-only overview of the ULTRA band (tier-wide + one per Event, with card counts, incl. "no event") and the SUPREME band, plus the
#                        exact /setvalue lines that set each one.
NOEVENT_PAGE_SIZE = 20

def _char_id_num(char_id):
    digits = re.sub(r'\D', '', str(char_id or ""))
    return int(digits) if digits else 0

async def _ultra_without_event_docs():
    """Every ULTRA character with no event_no (missing or null), in CharID order."""
    docs = await characters_base_col.find(
        {"rarity_tier": RARITY_TIERS[0], "event_no": None}, {"char_id": 1, "name": 1, "category": 1, "_id": 0}
    ).to_list(length=None)
    # older rows that never got a stored rarity_tier: classify them by their rarity string instead
    stray = await characters_base_col.find(
        {"rarity_tier": {"$exists": False}, "event_no": None}, {"char_id": 1, "name": 1, "category": 1, "rarity": 1, "_id": 0}
    ).to_list(length=None)
    docs += [d for d in stray if classify_rarity(d.get("rarity", "")) == RARITY_TIERS[0]]
    docs.sort(key=lambda d: _char_id_num(d.get("char_id")))
    return docs

async def _noevent_page(page):
    """(text, buttons) for one page of the no-Event ULTRA list."""
    docs = await _ultra_without_event_docs()
    total = len(docs)
    if not total:
        return "✅ <b>Every ULTRA card has an Event.</b>", [[Button.inline("🔄 Refresh", data="noev_0")]]
    pages = (total + NOEVENT_PAGE_SIZE - 1) // NOEVENT_PAGE_SIZE
    page = min(max(int(page), 0), pages - 1)
    chunk = docs[page * NOEVENT_PAGE_SIZE:(page + 1) * NOEVENT_PAGE_SIZE]
    tmn, tmx = tier_value_range(RARITY_TIERS[0])
    lines = [
        f"🎞 <b>ULTRA cards with no Event</b> — <b>{total}</b> <i>(page {page + 1}/{pages})</i>",
        f"<i>Until they get an Event they are priced by the tier-wide ULTRA band <code>{_fmt_vlt_num(tmn)} ~ {_fmt_vlt_num(tmx)}</code> 💠 — an Event with its own /setvalue band overrides that.</i>",
        "",
    ]
    for d in chunk:
        name = escape_html(str(d.get("name", "?"))[:28])
        cat = escape_html(str(d.get("category") or "—")[:20])
        lines.append(f"<code>{escape_html(display_char_id(d['char_id']))}</code> · {name} · <i>{cat}</i>")
    ids = ", ".join(display_char_id(d["char_id"]) for d in chunk)
    lines += [
        "",
        "🎪 <b>File them yourself</b> — copy this, change the number, and keep only the IDs that belong to that Event:",
        f"<code>/setevent 1 | {escape_html(ids)}</code>",
        "",
        event_list_html(),
    ]
    nav = []
    if page > 0:
        nav.append(Button.inline("◀ Prev", data=f"noev_{page - 1}"))
    nav.append(Button.inline("🔄 Refresh", data=f"noev_{page}"))
    if page < pages - 1:
        nav.append(Button.inline("Next ▶", data=f"noev_{page + 1}"))
    return "\n".join(lines), [nav]

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]noevent(?:@\w+)?(?:\s+(\d+))?$', 'bot1')))
async def noevent_handler(event):
    if event.sender_id != OWNER_ID: return
    if is_duplicate_event(event): return
    page = max(int(event.pattern_match.group(1) or 1) - 1, 0)
    try:
        text, buttons = await _noevent_page(page)
    except Exception as e:
        print(f"/noevent error: {e}")
        return await event.reply("⚠️ Couldn't read the character list right now — try again in a moment.", parse_mode='html')
    await event.reply(text, parse_mode='html', buttons=buttons)

@bot1.on(events.CallbackQuery(pattern=r'^noev_(\d+)$'))
async def noevent_page_callback(event):
    if event.sender_id != OWNER_ID:
        return await event.answer("⚠️ Owner only.", alert=True)
    page = int(event.pattern_match.group(1))
    try:
        text, buttons = await _noevent_page(page)
    except Exception as e:
        print(f"/noevent page error: {e}")
        return await event.answer("⚠️ Couldn't load that page.", alert=True)
    await event.answer()
    try:
        await event.edit(text, parse_mode='html', buttons=buttons)
    except Exception:
        pass                          # "message not modified" when Refresh finds nothing new

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]ultravalue(?:@\w+)?$', 'bot1')))
async def ultravalue_handler(event):
    if event.sender_id != OWNER_ID: return
    if is_duplicate_event(event): return
    try:
        rows = await characters_base_col.aggregate(
            [{"$match": {"rarity_tier": RARITY_TIERS[0]}}, {"$group": {"_id": "$event_no", "n": {"$sum": 1}}}]
        ).to_list(length=None)
        supreme_n = await characters_base_col.count_documents({"rarity_tier": RARITY_TIERS[1]})
        no_event = len(await _ultra_without_event_docs())        # the very same list /noevent shows, so the two counts always agree
    except Exception as e:
        print(f"/ultravalue error: {e}")
        return await event.reply("⚠️ Couldn't read the character list right now — try again in a moment.", parse_mode='html')
    per_event, other = {}, 0
    for r in rows:
        ev = r.get("_id")
        if ev is None:
            continue
        elif ev in EVENT_TYPES:
            per_event[ev] = r["n"]
        else:
            other += r["n"]
    ultra_total = no_event + other + sum(per_event.values())
    umn, umx = tier_value_range(RARITY_TIERS[0])
    smn, smx = tier_value_range(RARITY_TIERS[1])
    mark = lambda key: " ✏️" if key in _cached_value_overrides else ""
    lines = [
        "💠 <b>ULTRA &amp; SUPREME values</b> <i>(min ~ max — max is the real Owner Shop price)</i>",
        "",
        f"{_value_band_label(RARITY_TIERS[0])} <b>No.1</b> — tier band <code>{_fmt_vlt_num(umn)} ~ {_fmt_vlt_num(umx)}</code>{mark(RARITY_TIERS[0])} · <b>{ultra_total}</b> card(s)",
    ]
    for ev in sorted(EVENT_TYPES):
        mn, mx = value_range_for_char({"rarity_tier": RARITY_TIERS[0], "event_no": ev})
        own = f"ULTRA:{ev}" in _cached_value_overrides
        lines.append(
            f"   <code>e{ev}</code> {EVENT_TYPES[ev]} — <code>{_fmt_vlt_num(mn)} ~ {_fmt_vlt_num(mx)}</code>"
            + (" ✏️" if own else " <i>(tier band)</i>") + f" · {per_event.get(ev, 0)} card(s)"
        )
    lines.append(f"   ❓ <b>No Event</b> — <code>{_fmt_vlt_num(umn)} ~ {_fmt_vlt_num(umx)}</code> <i>(tier band)</i> · <b>{no_event}</b> card(s)" + ("  → <code>/noevent</code>" if no_event else ""))
    if other:
        lines.append(f"   ⚠️ <b>{other}</b> card(s) carry an Event number that isn't 1-{len(EVENT_TYPES)}.")
    lines += [
        "",
        f"{_value_band_label(RARITY_TIERS[1])} <b>No.2</b> — <code>{_fmt_vlt_num(smn)} ~ {_fmt_vlt_num(smx)}</code>{mark(RARITY_TIERS[1])} · <b>{supreme_n}</b> card(s)",
        "",
        "✏️ = owner-set, otherwise default. <b>Set them:</b>",
        "<code>/setvalue no1 3000 ~ 4800</code> <i>(all ULTRA)</i>",
        "<code>/setvalue no1 e3 3000 ~ 4800</code> <i>(ULTRA, one Event — e1-e8)</i>",
        "<code>/setvalue no2 2000 ~ 3500</code> <i>(SUPREME)</i>",
        "<code>/setvalue no1 e3 reset</code> <i>(back to default)</i>",
    ]
    await event.reply("\n".join(lines), parse_mode='html')

# ==========================================
