@bot1.on(events.CallbackQuery(pattern=r'^sellconf_(\S+)$'))
async def sell_offer_confirm_callback(event):
    sell_id = event.pattern_match.group(1)
    if isinstance(sell_id, bytes): sell_id = sell_id.decode('utf-8')
    offer_data = pending_sell_offers.get(sell_id)
    if not offer_data or time.time() > offer_data["expiry"]:
        pending_sell_offers.pop(sell_id, None)
        return await event.answer("⏳ This offer has expired. Run /sell again.", alert=True)
    if event.sender_id != offer_data["seller_id"]:
        return await event.answer("⚠️ This isn't your offer!", alert=True)
    if not claim_single_tap(event):
        return await event.answer("⏳ Already processing...", alert=False)
    seller_id, char_id, offer = offer_data["seller_id"], offer_data["char_id"], offer_data["offer"]
    user_doc = await users_catcher_col.find_one({"user_id": seller_id})
    user_harem = user_doc.get("harem", []) if user_doc else []
    char_item = next((x for x in user_harem if isinstance(x, dict) and x.get("char_id") == char_id and x.get("status") == "vault"), None)
    if not char_item:
        pending_sell_offers.pop(sell_id, None)
        await event.answer("❌ Card no longer available.", alert=True)
        return await event.edit("❌ <b>ဒီကဒ်ကို ရှာမတွေ့တော့ပါ။</b>", parse_mode='html', buttons=None)
    # 🩹 No owner deduction — scrap VLT is minted fresh for the scrapper (see block header
    # note above), same as any other reward. The card is simply destroyed.
    # Same atomic $pull-based removal as marketplace-buy/trade — see remove_one_harem_copy.
    await remove_one_harem_copy(seller_id, char_id, "vault")
    await users_catcher_col.update_one({"user_id": seller_id}, {"$inc": {"vlt_balance": offer}}, upsert=True)
    seller_doc_after = await users_catcher_col.find_one({"user_id": seller_id}, {"harem": 1})
    await clear_stale_favorite(seller_id, char_id, (seller_doc_after or {}).get("harem", []))
    # (2026-10, per owner request) no buy-back history row is written any more — nothing reads it.
    pending_sell_offers.pop(sell_id, None)
    await event.answer("🔥 Scrapped!", alert=True)
    await event.edit(
        f"🔥 <b>Scrap ဖြစ်သွားပါပြီ!</b>\n"
        f"<blockquote>"
        f"👤 <b>Card:</b> <code>{escape_html(offer_data['char_name'])}</code>\n"
        f"💠 <b>ရရှိ:</b> <code>{format_vlt_plain(offer)}</code>"
        f"</blockquote>",
        parse_mode='html', buttons=None
    )

@bot1.on(events.CallbackQuery(pattern=r'^sellcanc_(\S+)$'))
async def sell_offer_cancel_callback(event):
    sell_id = event.pattern_match.group(1)
    if isinstance(sell_id, bytes): sell_id = sell_id.decode('utf-8')
    offer_data = pending_sell_offers.get(sell_id)
    if offer_data and event.sender_id != offer_data["seller_id"]:
        return await event.answer("⚠️ This isn't your offer!", alert=True)
    pending_sell_offers.pop(sell_id, None)
    await event.answer("👍 Kept.")
    await event.edit("🙅 <b>Scrap လုပ်ခြင်းကို ပယ်ဖျက်လိုက်ပါပြီ — ကဒ်ကို ဆက်ထားနိုင်ပါတယ်။</b>", parse_mode='html', buttons=None)

# ==========================================
# ♻️ BULK SCRAP (2026-09, owner request) — collectors who play a lot end up with huge piles of …
# ==========================================
BULK_SCRAP_MULT = 0.002                                     # 0.2% of Shop price per duplicate — change HERE only
BULK_SCRAP_DEFAULT_TIERS = ("COMMON", "UNCOMMON", "RARE")   # pre-ticked when the menu first opens
BULK_SCRAP_HIGH_TIERS = tuple(RARITY_TIERS[:4])             # Rarity No.1-4 — extra warning on the confirm screen
BULK_SCRAP_MAX_RETRIES = 3

def _bs_bit(tier):
    return 1 << RARITY_TIERS.index(tier)

_BS_ALL_MASK = (1 << len(RARITY_TIERS)) - 1
_BS_DEFAULT_MASK = sum(_bs_bit(t) for t in BULK_SCRAP_DEFAULT_TIERS)

def _bs_tiers_from_mask(mask):
    return [t for t in RARITY_TIERS if mask & _bs_bit(t)]

def _bulk_scrap_vlt(tier, count):
    """Flat payout for `count` duplicates of `tier` (same tier price table /buy and /sell use)."""
    # 🩹 2026-10: tier-wide max (/setvalue-aware). Bulk scrap has only the tier, not the event, so an
    # ULTRA per-event band isn't visible here — it uses the tier-wide ULTRA max.
    return round(tier_value_range(tier)[1] * BULK_SCRAP_MULT * count, 2)

def _bulk_scrap_plan(harem, meta, selected_tiers):
    """PURE function (no DB) — the single place that decides what counts as a duplicate.
    meta = {char_id: tier} for chars the caller owns 2+ vault copies of.
    Returns (new_harem, dupes_by_tier, removed_by_tier):
      dupes_by_tier   — every scrappable duplicate per tier (drives the menu numbers)
      removed_by_tier — only the duplicates in `selected_tiers` (what actually gets deleted)
    The first (oldest) vault copy of each character is always kept; non-vault items are
    never touched, regardless of selection."""
    dupes = {t: 0 for t in RARITY_TIERS}
    removed = {t: 0 for t in RARITY_TIERS}
    new_harem = []
    kept_first = set()
    for item in harem:
        if not isinstance(item, dict) or not item.get("char_id") or item.get("status") != "vault":
            new_harem.append(item)
            continue
        cid = item["char_id"]
        tier = meta.get(cid)
        if tier is None or tier not in dupes:  # unknown / unclassifiable tier -> never touch
            new_harem.append(item)
            continue
        if cid not in kept_first:
            kept_first.add(cid)
            new_harem.append(item)
            continue
        dupes[tier] += 1
        if tier in selected_tiers:
            removed[tier] += 1
        else:
            new_harem.append(item)
    return new_harem, dupes, removed

async def _bulk_scrap_load(user_id):
    """Reads the vault once and looks up rarity only for chars owned 2+ times (cheap even for
    a huge vault). Returns (harem, meta)."""
    user_doc = await users_catcher_col.find_one({"user_id": user_id}, {"harem": 1, "_id": 0}) or {}
    harem = user_doc.get("harem") or []
    counts = {}
    for it in harem:
        if isinstance(it, dict) and it.get("char_id") and it.get("status") == "vault":
            counts[it["char_id"]] = counts.get(it["char_id"], 0) + 1
    dupe_ids = [cid for cid, n in counts.items() if n > 1]
    meta = {}
    if dupe_ids:
        docs = await characters_base_col.find(
            {"char_id": {"$in": dupe_ids}},
            {"char_id": 1, "rarity": 1, "rarity_tier": 1, "_id": 0}
        ).to_list(length=None)
        for d in docs:
            tier = classify_rarity(d.get("rarity_tier") or d.get("rarity", ""))
            meta[d["char_id"]] = tier
    return harem, meta

def _bs_tier_label(tier):
    return f"{RARITY_EMOJI.get(tier, RARITY_DEFAULT_EMOJI)} {RARITY_DISPLAY_NAME.get(tier, tier)}"

async def _build_bulk_scrap_menu(user_id, mask=None):
    """Main menu: (text, buttons). Tier toggles + Select all / Clear + the Scrap button."""
    if mask is None:
        mask = _BS_DEFAULT_MASK
    else:
        mask &= _BS_ALL_MASK
    harem, meta = await _bulk_scrap_load(user_id)
    _new, dupes, _rem = _bulk_scrap_plan(harem, meta, set())
    avail = [t for t in RARITY_TIERS if dupes[t] > 0]
    head = (
        "♻️ <b>BULK SCRAP</b>\n"
        "<blockquote>ထပ်နေတဲ့ (duplicate) ကဒ်တွေကို rarity အလိုက် တစ်ခါတည်း scrap လုပ်ပါ။\n"
        "✅ ကဒ်တစ်ခုချင်းစီရဲ့ <b>၁ ကဒ်ကို အမြဲချန်ထား</b>ပေးပါတယ်</blockquote>\n"
        f"<i>💠 Payout — Shop price ရဲ့ {BULK_SCRAP_MULT*100:.1f}% သာ (/sell [ID] ထက် သိသိသာသာ နည်းပါတယ်)</i>\n"
    )
    if not avail:
        return (head + "\n🎉 <b>ထပ်နေတဲ့ကဒ် မရှိပါဘူး</b> — vault သန့်ရှင်းနေပါတယ်။",
                [[Button.inline("❌ ပိတ်မယ်", data=f"bscrap_x_{user_id}")]])
    sel = [t for t in avail if mask & _bs_bit(t)]
    sel_count = sum(dupes[t] for t in sel)
    sel_vlt = round(sum(_bulk_scrap_vlt(t, dupes[t]) for t in sel), 2)
    lines = [head, "ဖျက်မယ့် rarity ကို နှိပ်ပြီး ရွေးပါ 👇"]
    for t in avail:
        tick = "☑️" if t in sel else "⬜"
        lines.append(f"{tick} {_bs_tier_label(t)} — <code>{dupes[t]:,}</code> ကဒ် → <code>{format_vlt_plain(_bulk_scrap_vlt(t, dupes[t]))}</code>")
    lines.append(f"\n🧾 <b>ရွေးထားတာ:</b> <code>{sel_count:,}</code> ကဒ် → <code>{format_vlt_plain(sel_vlt)}</code>")
    toggles = [Button.inline(f"{'☑️' if t in sel else '⬜'} {RARITY_EMOJI.get(t, RARITY_DEFAULT_EMOJI)} {RARITY_DISPLAY_NAME.get(t, t)} ×{dupes[t]:,}",
                             data=f"bscrap_m_{user_id}_{mask ^ _bs_bit(t)}") for t in avail]
    buttons = [toggles[i:i + 2] for i in range(0, len(toggles), 2)]
    buttons.append([
        Button.inline("☑️ အကုန်ရွေး", data=f"bscrap_m_{user_id}_{_BS_ALL_MASK}"),
        Button.inline("⬜ ရှင်းမယ်", data=f"bscrap_m_{user_id}_0"),
    ])
    if sel_count > 0:
        buttons.append([colored_button(f"🔥 Scrap {sel_count:,} ကဒ် → {format_vlt_plain(sel_vlt)}",
                                       f"bscrap_c_{user_id}_{mask}", color="danger")])
    buttons.append([Button.inline("❌ ပိတ်မယ်", data=f"bscrap_x_{user_id}")])
    return "\n".join(lines), buttons

async def _build_bulk_scrap_confirm(user_id, mask):
    """Confirm screen — recomputed live from the DB so the numbers always match what will
    actually be deleted, even if the vault changed since the menu was opened."""
    harem, meta = await _bulk_scrap_load(user_id)
    _new, dupes, _rem = _bulk_scrap_plan(harem, meta, set())
    sel = [t for t in RARITY_TIERS if dupes[t] > 0 and mask & _bs_bit(t)]
    if not sel:
        return None, None
    total = sum(dupes[t] for t in sel)
    vlt = round(sum(_bulk_scrap_vlt(t, dupes[t]) for t in sel), 2)
    rows = "\n".join(f"{_bs_tier_label(t)} — <code>{dupes[t]:,}</code> ကဒ် → <code>{format_vlt_plain(_bulk_scrap_vlt(t, dupes[t]))}</code>" for t in sel)
    warn = ""
    if any(t in BULK_SCRAP_HIGH_TIERS for t in sel):
        warn = "🚨 <b>Rarity No.1-4 (ရှားပါးတဲ့ ကဒ်) ပါနေပါတယ်!</b> ပြန်ရှာရခက်နိုင်လို့ သေချာစစ်ပါ။\n"
    text = (
        "⚠️ <b>Scrap အတည်ပြုပါ</b>\n"
        f"<blockquote>{rows}\n\n🗑️ <b>ဖျက်မယ့်ကဒ်:</b> <code>{total:,}</code>\n💠 <b>ရမယ့် VLT:</b> <code>{format_vlt_plain(vlt)}</code></blockquote>\n"
        f"{warn}"
        "<i>ကဒ်တစ်ခုချင်းစီရဲ့ ၁ ကဒ်ကို ချန်ထားပါမယ် · LE မထိပါ · ပြန်ပြင်လို့ မရတော့ပါ</i>"
    )
    buttons = [[
        colored_button("🔥 ဟုတ်ကဲ့ Scrap လုပ်မယ်", f"bscrap_g_{user_id}_{mask}", color="danger"),
        Button.inline("🔙 ပြန်သွားမယ်", data=f"bscrap_m_{user_id}_{mask}"),
    ]]
    return text, buttons

async def _bulk_scrap_execute(user_id, mask):
    """Does the deletion + payout in ONE atomic update. Returns (status, removed_by_tier, payout)
    with status in {"ok", "none", "busy"}. The {"harem": {"$size": n}} filter means: if ANYTHING
    added/removed a card between our read and this write (a catch, a gift, a /trade, a second tap
    of this very button), the write simply doesn't match — we re-read and recompute instead of
    overwriting it, so nothing is ever lost and nobody is ever paid twice."""
    selected = set(_bs_tiers_from_mask(mask))
    for _ in range(BULK_SCRAP_MAX_RETRIES):
        harem, meta = await _bulk_scrap_load(user_id)
        new_harem, _dupes, removed = _bulk_scrap_plan(harem, meta, selected)
        total = sum(removed.values())
        if total == 0:
            return "none", removed, 0.0
        payout = round(sum(_bulk_scrap_vlt(t, n) for t, n in removed.items()), 2)
        res = await users_catcher_col.update_one(
            {"user_id": user_id, "harem": {"$size": len(harem)}},
            {"$set": {"harem": new_harem}, "$inc": {"vlt_balance": payout}}
        )
        if res.matched_count:
            return "ok", removed, payout
    return "busy", {}, 0.0


@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.](?:scrap|dupes)(?:@\w+)?$', 'bot1')))
async def bulk_scrap_command(event):
    text, buttons = await _build_bulk_scrap_menu(event.sender_id)
    await event.reply(text, parse_mode='html', buttons=buttons)

@bot1.on(events.CallbackQuery(pattern=r'^bscrap_([omcgx])_(\d+)(?:_(\d+))?$'))
async def bulk_scrap_callback(event):
    """o = open (fresh message, used by the harem/trivia/catch entry-point buttons) ·
    m = menu (edit in place, carries the tier bitmask) · c = confirm screen · g = go (execute) ·
    x = close."""
    def _grp(i):
        v = event.pattern_match.group(i)
        return v.decode('utf-8') if isinstance(v, bytes) else v
    try:
        action = _grp(1)
        owner_id = int(_grp(2))
        mask_raw = _grp(3)
        mask = (int(mask_raw) & _BS_ALL_MASK) if mask_raw is not None else _BS_DEFAULT_MASK
        if event.sender_id != owner_id:
            return await event.answer("⚠️ ဒါ မင်းရဲ့ menu မဟုတ်ပါဘူး!", alert=True)

        if action == 'o':
            # 🩹 ALWAYS a fresh message, never event.edit/event.reply — this button lives on
            # messages we must not touch (a /harem photo caption, a trivia result, a catch
            # card) — same reasoning as every other button that must not overwrite its host message.
            await event.answer()
            text, buttons = await _build_bulk_scrap_menu(owner_id)
            return await bot1.send_message(event.chat_id, text, parse_mode='html', buttons=buttons)

        if action == 'x':
            await event.answer()
            try:
                await event.delete()
            except Exception:
                pass
            return

        if action == 'm':
            text, buttons = await _build_bulk_scrap_menu(owner_id, mask)
            await event.answer()
            try:
                await event.edit(text, parse_mode='html', buttons=buttons)
            except errors.MessageNotModifiedError:
                pass
            return

        if action == 'c':
            text, buttons = await _build_bulk_scrap_confirm(owner_id, mask)
            if not text:
                return await event.answer("ℹ️ Rarity တစ်ခုခု အရင်ရွေးပါ။", alert=True)
            await event.answer()
            try:
                await event.edit(text, parse_mode='html', buttons=buttons)
            except errors.MessageNotModifiedError:
                pass
            return

        # action == 'g' — execute
        if not claim_single_tap(event):
            return await event.answer("⏳ Already processing...", alert=False)
        status, removed, payout = await _bulk_scrap_execute(owner_id, mask)
        if status == "busy":
            return await event.answer("⏳ Vault ပြောင်းလဲနေလို့ မလုပ်ပေးနိုင်သေးပါ — ခဏနေ ပြန်နှိပ်ပါ။", alert=True)
        if status == "none":
            await event.answer("ℹ️ Scrap လုပ်စရာ ထပ်နေတဲ့ကဒ် မရှိတော့ပါ။", alert=True)
            text, buttons = await _build_bulk_scrap_menu(owner_id, mask)
            try:
                await event.edit(text, parse_mode='html', buttons=buttons)
            except errors.MessageNotModifiedError:
                pass
            return
        total_removed = sum(removed.values())
        rows = "\n".join(f"{_bs_tier_label(t)} — <code>{n:,}</code> ကဒ်" for t, n in removed.items() if n)
        await event.answer(f"🔥 {total_removed:,} ကဒ် scrap ပြီးပါပြီ!")
        try:
            await event.edit(
                "✅ <b>Bulk Scrap ပြီးပါပြီ!</b>\n"
                f"<blockquote>{rows}\n\n🗑️ <b>စုစုပေါင်း:</b> <code>{total_removed:,}</code> ကဒ်\n"
                f"💠 <b>ရရှိ:</b> <code>{format_vlt_plain(payout)}</code></blockquote>",
                parse_mode='html',
                buttons=[[Button.inline("♻️ Menu ပြန်ကြည့်", data=f"bscrap_m_{owner_id}_{_BS_DEFAULT_MASK}"),
                          Button.inline("❌ ပိတ်မယ်", data=f"bscrap_x_{owner_id}")]]
            )
        except Exception:
            await bot1.send_message(event.chat_id, f"✅ Scrapped {total_removed:,} → +{format_vlt_plain(payout)}", parse_mode='html')
    except Exception as e:
        print(f"bulk_scrap_callback error: {e}")
        try:
            await event.answer("❌ တစ်ခုခု မှားသွားပါတယ် — ပြန်ကြိုးစားပါ။", alert=True)
        except Exception:
            pass


# ==========================================
# 🔥 SELL BY RARITY — bare /sell (2026-11, owner request: "sell ချည်းပဲဆို လူတွေသူတို့ပိုင်ထားတဲ့ rarity no 4 to no 9 …
# ==========================================
# (SELL_ALL_MULT lives next to RARITY_VLT_PRICE at the top of the file — the buy floor is derived from it)
SELL_ALL_TIERS = tuple(RARITY_TIERS[3:])            # Rarity No.4 .. No.9
_SELL_ALL_MASK = sum(_bs_bit(t) for t in SELL_ALL_TIERS)
SELL_ALL_SAMPLE_CARDS = 5                           # how many example cards the confirm screen lists

def _sellall_unit(tier):
    """💠 VLT paid for ONE card of `tier` (same tier price table /buy, /sell and /scrap use)."""
    return round(tier_value_range(tier)[1] * SELL_ALL_MULT, 2)

def _sellall_value(tier, count):
    return round(_sellall_unit(tier) * count, 2)

def _sellall_plan(harem, info, selected_tiers):
    """PURE function (no DB) — the single place that decides what gets sold.
    info = {char_id: (tier, name)} for every character the roster knows.
    Returns (new_harem, counts, removed):
      counts  — {tier: {char_id: copies}} for every sellable vault copy in SELL_ALL_TIERS (drives the menu numbers)
      removed — same shape, but only for `selected_tiers` (what actually gets deleted)
    Non-vault items, unknown characters and tiers outside SELL_ALL_TIERS are never touched, whatever the selection."""
    selected = {t for t in selected_tiers if t in SELL_ALL_TIERS}
    counts = {t: {} for t in SELL_ALL_TIERS}
    removed = {t: {} for t in SELL_ALL_TIERS}
    new_harem = []
    for item in harem:
        if not isinstance(item, dict) or not item.get("char_id") or item.get("status") != "vault":
            new_harem.append(item)
            continue
        cid = item["char_id"]
        tier = (info.get(cid) or (None, None))[0]
        if tier not in counts:                      # unknown character / a tier this menu never sells -> never touch
            new_harem.append(item)
            continue
        counts[tier][cid] = counts[tier].get(cid, 0) + 1
        if tier in selected:
            removed[tier][cid] = removed[tier].get(cid, 0) + 1
        else:
            new_harem.append(item)
    return new_harem, counts, removed

async def _sellall_load(user_id):
    """One read of the vault + a pure in-memory lookup of every character's tier/name from the roster snapshot
    (no per-card Mongo query). Returns (harem, fav_card, info)."""
    doc = await users_catcher_col.find_one({"user_id": user_id}, {"harem": 1, "fav_card": 1, "_id": 0}) or {}
    harem = doc.get("harem") or []
    by_id = _roster_derived(await get_all_characters_cached())["by_id"]
    info = {}
    for it in harem:
        if isinstance(it, dict) and it.get("char_id") and it.get("status") == "vault" and it["char_id"] not in info:
            c = by_id.get(it["char_id"])
            if c:
                info[it["char_id"]] = (classify_rarity(c.get("rarity_tier") or c.get("rarity", "")), c.get("name") or "?")
    return harem, doc.get("fav_card"), info

def _sellall_tier_totals(counts, tier):
    n = sum(counts[tier].values())
    return n, len(counts[tier]), _sellall_value(tier, n)

async def _build_sellall_menu(user_id):
    """Main menu for bare /sell: (text, buttons)."""
    harem, _fav, info = await _sellall_load(user_id)
    _new, counts, _rem = _sellall_plan(harem, info, set())
    avail = [t for t in SELL_ALL_TIERS if counts[t]]
    head = (
        "🔥 <b>SELL BY RARITY</b>\n"
        "<blockquote>Rarity <b>No.4 – No.9</b> ကဒ်တွေကို ပိုင်ထားသမျှ အကုန် 💠 VLT နဲ့ တစ်ခါတည်း ရောင်းနိုင်ပါတယ်။\n"
        "⚠️ ရွေးထားတဲ့ rarity ရဲ့ ကဒ် <b>အားလုံး</b> ဖျက်မှာမို့ ၁ ကဒ်မှ မချန်ပါဘူး\n"
        "ℹ️ No.1 – No.3 ကိုတော့ <code>/sell [CharID]</code> နဲ့ တစ်ကဒ်ချင်းပဲ ရောင်းလို့ရပါတယ်</blockquote>\n"
        f"<i>💠 Payout — Owner Shop ဈေးရဲ့ {SELL_ALL_MULT * 100:g}% / ကဒ်</i>\n"
    )
    single_hint = "\n📌 <b>တစ်ကဒ်တည်း:</b> <code>/sell [CharID]</code> <i>(ဥပမာ <code>/sell 1234</code>)</i>"
    if not avail:
        return (head + "\n📭 <b>Rarity No.4 – No.9 ကဒ် မရှိပါဘူး</b>" + single_hint,
                [[Button.inline("♻️ ထပ်နေတာ Scrap", data=f"bscrap_m_{user_id}_{_BS_DEFAULT_MASK}"),
                  Button.inline("❌ ပိတ်မယ်", data=f"sellall_x_{user_id}")]])
    lines = [head, "ရောင်းမယ့် rarity ကို နှိပ်ပါ 👇"]
    all_n = all_unique = 0
    all_val = 0.0
    all_mask = 0
    for t in avail:
        n, u, val = _sellall_tier_totals(counts, t)
        all_n += n
        all_unique += u
        all_val += val
        all_mask |= _bs_bit(t)
        lines.append(f"{_bs_tier_label(t)} — <code>{n:,}</code> ကဒ် ({u:,} မျိုး) → <code>{format_vlt_plain(val)}</code>")
    all_val = round(all_val, 2)
    lines.append(single_hint)
    toggles = [Button.inline(f"{RARITY_EMOJI.get(t, RARITY_DEFAULT_EMOJI)} {RARITY_DISPLAY_NAME.get(t, t)} ×{sum(counts[t].values()):,}",
                             data=f"sellall_c_{user_id}_{_bs_bit(t)}") for t in avail]
    buttons = [toggles[i:i + 2] for i in range(0, len(toggles), 2)]
    if len(avail) > 1:
        buttons.append([colored_button(f"💥 No.4–9 အကုန်ရောင်းမယ် — {all_n:,} ကဒ် → {format_vlt_plain(all_val)}",
                                       f"sellall_c_{user_id}_{all_mask}", color="danger")])
    buttons.append([Button.inline("♻️ ထပ်နေတာပဲ Scrap (၁ ကဒ်ချန်)", data=f"bscrap_m_{user_id}_{_BS_DEFAULT_MASK}"),
                    Button.inline("❌ ပိတ်မယ်", data=f"sellall_x_{user_id}")])
    return "\n".join(lines), buttons

async def _build_sellall_confirm(user_id, mask):
    """Confirm screen — recomputed live from the DB so the numbers always match what will actually be deleted."""
    harem, fav, info = await _sellall_load(user_id)
    _new, counts, _rem = _sellall_plan(harem, info, set())
    sel = [t for t in SELL_ALL_TIERS if counts[t] and mask & _bs_bit(t)]
    if not sel:
        return None, None
    total = unique = 0
    value = 0.0
    rows = []
    pool = {}                                        # char_id -> copies, across the selected tiers (for the sample list)
    for t in sel:
        n, u, val = _sellall_tier_totals(counts, t)
        total += n
        unique += u
        value += val
        rows.append(f"{_bs_tier_label(t)} — <code>{n:,}</code> ကဒ် ({u:,} မျိုး) × <code>{format_vlt_plain(_sellall_unit(t))}</code> = <code>{format_vlt_plain(val)}</code>")
        pool.update(counts[t])
    value = round(value, 2)
    top = sorted(pool.items(), key=lambda kv: (-kv[1], (info.get(kv[0]) or (None, "?"))[1]))[:SELL_ALL_SAMPLE_CARDS]
    sample = ", ".join(f"{escape_html(str((info.get(cid) or (None, '?'))[1]))} <code>[{display_char_id(cid)}]</code>" + (f" ×{n}" if n > 1 else "") for cid, n in top)
    more = f" … +{unique - len(top):,} မျိုး" if unique > len(top) else ""
    warn = ""
    if any(t in BULK_SCRAP_HIGH_TIERS for t in sel):
        warn += "🚨 <b>Rarity No.4 (ရှားပါးတဲ့ ကဒ်) ပါနေပါတယ်!</b> ပြန်ရှာရခက်နိုင်လို့ သေချာစစ်ပါ။\n"
    if fav and fav in pool:
        warn += "⭐ <b>သင့် Favourite ကဒ်လည်း ပါနေပါတယ်</b> — ရောင်းလိုက်ရင် Favourite ပျောက်သွားပါမယ်။\n"
    text = (
        "⚠️ <b>ရောင်းမယ်ဆိုတာ အတည်ပြုပါ</b>\n"
        f"<blockquote>{chr(10).join(rows)}\n\n"
        f"🗑️ <b>ရောင်းမယ့်ကဒ်:</b> <code>{total:,}</code> ကဒ် ({unique:,} မျိုး)\n"
        f"💠 <b>ရမယ့် VLT:</b> <code>{format_vlt_plain(value)}</code>\n"
        f"🃏 <b>ဥပမာ:</b> {sample}{more}</blockquote>\n"
        f"{warn}"
        "<i>ရွေးထားတဲ့ rarity ရဲ့ ကဒ် အားလုံးကို ဖျက်ပါမယ် (၁ ကဒ်မှ မချန်) · LE မထိပါ · ပြန်ပြင်လို့ မရတော့ပါ</i>"
    )
    buttons = [[
        colored_button("✅ Confirm — ရောင်းမယ်", f"sellall_g_{user_id}_{mask}", color="danger"),
        Button.inline("❌ Cancel", data=f"sellall_n_{user_id}"),
    ]]
    return text, buttons

async def _sellall_execute(user_id, mask):
    """Deletes the cards + pays the VLT in ONE atomic update. Returns (status, removed, payout) with status in
    {"ok", "none", "busy"}; removed = {tier: {char_id: copies}}."""
    selected = {t for t in _bs_tiers_from_mask(mask) if t in SELL_ALL_TIERS}      # server-side: never No.1-3
    for _ in range(BULK_SCRAP_MAX_RETRIES):
        harem, fav, info = await _sellall_load(user_id)
        new_harem, _counts, removed = _sellall_plan(harem, info, selected)
        total = sum(sum(v.values()) for v in removed.values())
        if total == 0:
            return "none", removed, 0.0
        payout = round(sum(_sellall_value(t, sum(v.values())) for t, v in removed.items()), 2)
        res = await users_catcher_col.update_one(
            {"user_id": user_id, "harem": {"$size": len(harem)}},
            {"$set": {"harem": new_harem}, "$inc": {"vlt_balance": payout}}
        )
        if res.matched_count:
            try:                                      # a sold /fav card (no copy left) must not stay as the favourite
                if fav and not is_owner_mode(user_id) and not any(isinstance(it, dict) and it.get("char_id") == fav for it in new_harem):
                    await users_catcher_col.update_one({"user_id": user_id, "fav_card": fav}, {"$unset": {"fav_card": "", "fav_note": ""}})
            except Exception as e:
                print(f"sellall fav cleanup error ({user_id}): {e}")
            return "ok", removed, payout
    return "busy", {}, 0.0

@bot1.on(events.CallbackQuery(pattern=r'^sellall_([mcgxn])_(\d+)(?:_(\d+))?$'))
async def sellall_callback(event):
    """m = menu (edit in place) · c = confirm screen · g = go (execute) · n = cancel (back to the menu) · x = close."""
    def _grp(i):
        v = event.pattern_match.group(i)
        return v.decode('utf-8') if isinstance(v, bytes) else v
    async def _edit(text, buttons):
        try:
            await event.edit(text, parse_mode='html', buttons=buttons)
        except errors.MessageNotModifiedError:
            pass
    try:
        action = _grp(1)
        owner_id = int(_grp(2))
        mask_raw = _grp(3)
        mask = (int(mask_raw) & _SELL_ALL_MASK) if mask_raw is not None else 0      # no mask -> sell nothing (never default to "all")
        if event.sender_id != owner_id:
            return await event.answer("⚠️ ဒါ မင်းရဲ့ menu မဟုတ်ပါဘူး!", alert=True)

        if action == 'x':
            await event.answer()
            try:
                await event.delete()
            except Exception:
                pass
            return

        if action in ('m', 'n'):
            text, buttons = await _build_sellall_menu(owner_id)
            await event.answer("❌ ပယ်ဖျက်လိုက်ပါပြီ — ကဒ်တွေ မရောင်းပါဘူး" if action == 'n' else None)
            return await _edit(text, buttons)

        if action == 'c':
            text, buttons = await _build_sellall_confirm(owner_id, mask)
            if not text:
                await event.answer("ℹ️ ရောင်းစရာ ကဒ် မရှိတော့ပါ။", alert=True)
                text, buttons = await _build_sellall_menu(owner_id)
                return await _edit(text, buttons)
            await event.answer()
            return await _edit(text, buttons)

        # action == 'g' — execute
        if not mask:
            return await event.answer("ℹ️ Rarity တစ်ခုခု အရင်ရွေးပါ။", alert=True)
        if not claim_single_tap(event):
            return await event.answer("⏳ Already processing...", alert=False)
        status, removed, payout = await _sellall_execute(owner_id, mask)
        if status == "busy":
            return await event.answer("⏳ Vault ပြောင်းလဲနေလို့ မလုပ်ပေးနိုင်သေးပါ — ခဏနေ ပြန်နှိပ်ပါ။", alert=True)
        if status == "none":
            await event.answer("ℹ️ ရောင်းစရာ ကဒ် မရှိတော့ပါ။", alert=True)
            text, buttons = await _build_sellall_menu(owner_id)
            return await _edit(text, buttons)
        total_removed = sum(sum(v.values()) for v in removed.values())
        rows = "\n".join(f"{_bs_tier_label(t)} — <code>{sum(v.values()):,}</code> ကဒ်" for t, v in removed.items() if v)
        await event.answer(f"🔥 {total_removed:,} ကဒ် ရောင်းပြီးပါပြီ!")
        try:
            await event.edit(
                "✅ <b>ရောင်းပြီးပါပြီ!</b>\n"
                f"<blockquote>{rows}\n\n🗑️ <b>စုစုပေါင်း:</b> <code>{total_removed:,}</code> ကဒ်\n"
                f"💠 <b>ရရှိ:</b> <code>{format_vlt_plain(payout)}</code></blockquote>",
                parse_mode='html',
                buttons=[[Button.inline("🔥 Menu ပြန်ကြည့်", data=f"sellall_m_{owner_id}"),
                          Button.inline("❌ ပိတ်မယ်", data=f"sellall_x_{owner_id}")]]
            )
        except Exception:
            await bot1.send_message(event.chat_id, f"✅ Sold {total_removed:,} → +{format_vlt_plain(payout)}", parse_mode='html')
    except Exception as e:
        print(f"sellall_callback error: {e}")
        try:
            await event.answer("❌ တစ်ခုခု မှားသွားပါတယ် — ပြန်ကြိုးစားပါ။", alert=True)
        except Exception:
            pass


