@bot1.on(events.CallbackQuery(pattern=r'^prembuy_(\d+)_(\d+)$'))
async def vip_purchase_callback(event):
    months = int(event.pattern_match.group(1))
    owner_uid = int(event.pattern_match.group(2))
    if event.sender_id != owner_uid:
        return await event.answer("⚠️ This isn't your menu!", alert=True)
    if months != 1:
        return await event.answer("⚠️ ဒီ menu က အဟောင်းဖြစ်နေပါပြီ — /buyvipmode ကို ပြန်ရိုက်ပါ။", alert=True)
    if not await vip_sale_enabled():
        return await event.answer("👑 VIP Mode purchases are paused while VIP Mode is being updated.", alert=True)
    if not claim_single_tap(event):
        return await event.answer("⏳ Already processing...", alert=False)
    async with _vlt_lock(owner_uid):                     # two taps at once can't both pass the check below
        doc = await users_catcher_col.find_one({"user_id": owner_uid}, {"premium_until": 1, "vlt_balance": 1, "_id": 0})
        can_buy, left = _vip_can_buy(doc)
        if not can_buy:
            return await event.answer(f"👑 VIP Mode ရှိပြီးသား ({left:.1f} ရက်ကျန်) — ကုန်ခါနီး {VIP_RENEW_WINDOW_DAYS} ရက်အတွင်းမှ ပြန်ဝယ်နိုင်ပါမယ်။", alert=True)
        if not await try_deduct_vlt(owner_uid, VIP_PRICE_VLT):
            have = (doc or {}).get("vlt_balance", 0) or 0
            return await event.answer(f"❌ 💠 VLT မလုံလောက်ပါ။ လိုအပ်: {VIP_PRICE_VLT:,} | ရှိ: {format_vlt_plain(have)}", alert=True)
        new_until = await grant_vip_days(owner_uid, VIP_DAYS)
        try:
            card_names = await grant_vip_bonus_cards(owner_uid)
        except Exception as e:
            card_names = []
            print(f"grant_vip_bonus_cards error ({owner_uid}): {e}")
    expiry_str = datetime.fromtimestamp(new_until, TZ).strftime("%Y-%m-%d %H:%M")
    cards_line = ("\n🎁 <b>Divine ကဒ်:</b> " + ", ".join(f"<code>{escape_html(n)}</code>" for n in card_names)) if card_names else ""
    await event.answer("👑 VIP Mode Activated!", alert=True)
    await event.edit(
        f"👑 <b>BOT VIP MODE ACTIVATED!</b>\n"
        f"<blockquote>"
        f"⏳ <b>သက်တမ်း:</b> <code>{expiry_str}</code> အထိ"
        f"{cards_line}"
        f"</blockquote>\n"
        f"🎉 <i>VIP Mode အကျိုးခံစားခွင့်များ ချက်ချင်း စတင်အသုံးပြုနိုင်ပါပြီ!</i>",
        parse_mode='html', buttons=None
    )

