# ==========================================
# 💠 /buyvlt & /sellvlt — ⭐ Star <-> 💠 VLT exchange (2026-08, replaces /buystar & /sellstar).
# ==========================================
import math as _math

VLT_SELL_RATIO = float(os.environ.get("VLT_SELL_RATIO", "0.90"))             # /sellvlt pays this share of the live rate
VLT_FLIP_MAX_PROFIT = float(os.environ.get("VLT_FLIP_MAX_PROFIT", "0.0"))     # 🛡 bought-with-⭐ VLT may be sold back at most this far above cost (0 = never above cost)
# 🔓 CHANGED (2026-11, per owner request — "sellvlt ကို လွတ်လွတ်လပ်လပ် ရောင်းခွင့်ပေးလိုက်ပါ"): the default is now FREE SELLING. Every 💠 a player holds — bought with ⭐ or earned from card …
VLT_EARNED_SELL_RATE = float(os.environ.get("VLT_EARNED_SELL_RATE", "-1"))
VLT_MAX_EXCHANGE_AMOUNT = 1_000_000_000
_vlt_exchange_locks = {}                                                     # one lock per player: two sells can't both spend the same cost basis

def _vlt_lock(user_id):
    return _vlt_exchange_locks.setdefault(user_id, asyncio.Lock())

def _parse_vlt_amount(raw):
    """A finite amount between 0.01 and 1e9, rounded to 2 decimals — or None. ('nan' / 'inf' used to slip through float() and
    the <= 0 checks and could write NaN into a balance.)"""
    try:
        v = float(str(raw).replace(",", ""))
    except (TypeError, ValueError):
        return None
    if not _math.isfinite(v):
        return None
    v = round(v, 2)
    return v if 0.01 <= v <= VLT_MAX_EXCHANGE_AMOUNT else None

def _vlt_trend(rate, ref):
    if not ref:
        return "▬ 0.0%"
    pct = (rate - ref) / ref * 100
    arrow = "▲" if pct > 0.05 else ("▼" if pct < -0.05 else "▬")
    return f"{arrow} {pct:+.1f}%"

def _vlt_gauge(rate, width=10):
    pos = min(1.0, max(0.0, (rate - VLT_RATE_MIN) / (VLT_RATE_MAX - VLT_RATE_MIN)))
    filled = round(pos * width)
    return "▰" * filled + "▱" * (width - filled), int(round(pos * 100))

def _vlt_spark(history, n=16):
    bars = "▁▂▃▄▅▆▇█"
    span = VLT_RATE_MAX - VLT_RATE_MIN
    return "".join(bars[min(7, max(0, int((float(h) - VLT_RATE_MIN) / span * 8)))] for h in (history or [])[-n:])

def _vlt_market_block(market):
    """The shared 'rate card' shown by both /buyvlt and /sellvlt."""
    rate = market["rate"]
    sell_rate = round(rate * VLT_SELL_RATIO, 2)
    gauge, pos = _vlt_gauge(rate)
    return (
        f"📈 <b>Buy rate</b>   <code>1 💠 = {rate:,.2f} ⭐</code>\n"
        f"📉 <b>Sell rate</b>  <code>1 💠 = {sell_rate:,.2f} ⭐</code> <i>({VLT_SELL_RATIO * 100:.0f}% of live)</i>\n"
        f"📅 <b>Today</b> <code>{_vlt_trend(rate, market.get('day_open_rate'))}</code>   "
        f"⏱ <b>Last tick</b> <code>{_vlt_trend(rate, market.get('prev_tick_rate'))}</code>\n"
        f"🎚 <code>{gauge}</code> <i>{pos}% of {VLT_RATE_MIN:g}–{VLT_RATE_MAX:g} ⭐</i>\n"
        f"📊 <code>{_vlt_spark(market.get('history'))}</code> <i>price, last 4h</i>"
    )

# ---- 🛡 NO-PROFIT EXCHANGE (2026-11) — replacement code for the helpers below -----------------------------------------------------
# Owner's report: players bought 💠 at ~30⭐ and sold at ~70⭐, and both currencies inflated. Three leaks, three fixes:
#   1. the rate wandered over a 3.25x range  -> it now stays inside ±VLT_RATE_BAND of VLT_RATE_CENTER (see the constants up top);
#   2. VLT that was NOT bought with ⭐ (card /sell money, rewards, gifts, bless …) could be sold at the full live rate — i.e. every
#      free card could be turned into ~50⭐ per 💠, a Star printing press. Such VLT is now NOT exchangeable (VLT_EARNED_SELL_RATE = 0);
#   3. VLT bought with ⭐ could come back at +10% over its cost -> it now comes back at MOST what it cost (VLT_FLIP_MAX_PROFIT = 0),
#      minus the exchange fee. Because the cap is per player and per coin, gifting/alt accounts can't launder a profit either.
# Net effect: ⭐ -> 💠 -> ⭐ can only ever LOSE (fee + rate drift), and 💠 can never mint ⭐. Both currencies keep their value.
def _vlt_floor2(x):
    """Round DOWN to 2 decimals — the 'max' amounts must never exceed what the player really has."""
    try:
        return _math.floor(float(x) * 100 + 1e-9) / 100
    except (TypeError, ValueError, OverflowError):
        return 0.0

def _vlt_sellable(rate, balance, stored_qty, stored_cost, ratio=None):
    """What /sellvlt can take back RIGHT NOW, as one pure function.
    stored_qty/stored_cost = VLT bought with ⭐ and what it cost. Returns a dict:
      sellable — 💠 that can be exchanged now        star   — ⭐ that all of it pays
      locked   — 💠 held that can NOT be exchanged   per_bought / per_other — ⭐ paid per 💠 for each kind"""
    sell_rate = round(rate * (VLT_SELL_RATIO if ratio is None else ratio), 2)
    balance = max(0.0, float(balance or 0))
    stored_qty = max(0.0, float(stored_qty or 0))
    stored_cost = max(0.0, float(stored_cost or 0))
    avg_cost = (stored_cost / stored_qty) if stored_qty > 0 else 0.0
    held_bought = min(stored_qty, balance) if avg_cost > 0 else 0.0     # bought VLT that was later SPENT is no longer in the pool
    other_held = max(0.0, balance - held_bought)
    free = VLT_EARNED_SELL_RATE < 0                       # 🔓 default: every 💠 sells at the live sell rate, bought or earned
    earned_on = VLT_EARNED_SELL_RATE != 0
    per_bought = (sell_rate if free else min(sell_rate, avg_cost * (1 + VLT_FLIP_MAX_PROFIT))) if avg_cost > 0 else 0.0     # rework mode: never above what it cost
    per_other = (sell_rate if free else min(VLT_EARNED_SELL_RATE, sell_rate)) if earned_on else 0.0
    sellable = held_bought + (other_held if earned_on else 0.0)
    star = round(held_bought * per_bought + (other_held * per_other if earned_on else 0.0), 2)
    return {"sell_rate": sell_rate, "avg_cost": avg_cost, "held_bought": held_bought, "other_held": other_held,
            "sellable": sellable, "locked": 0.0 if earned_on else other_held, "star": star,
            "per_bought": per_bought, "per_other": per_other}

def _vlt_sell_quote(vlt_amount, rate, balance, stored_qty, stored_cost, ratio=None):
    """Everything /sellvlt pays, as one pure function. `ok` is False when more is asked than can be exchanged."""
    s = _vlt_sellable(rate, balance, stored_qty, stored_cost, ratio)
    balance = max(0.0, float(balance or 0))
    stored_qty = max(0.0, float(stored_qty or 0))
    q_bought = min(vlt_amount, s["held_bought"])
    q_other = max(0.0, vlt_amount - q_bought)
    ok = vlt_amount <= s["sellable"] + 1e-6
    gross_live = round(vlt_amount * rate, 2)                      # worth at the live rate
    gross = round(vlt_amount * s["sell_rate"], 2)                 # …after the exchange fee
    star_gained = round(q_bought * s["per_bought"] + q_other * s["per_other"], 2) if ok else 0.0
    return {
        "ok": ok, "sellable": s["sellable"], "locked": s["locked"], "sell_rate": s["sell_rate"], "avg_cost": s["avg_cost"],
        "q_bought": q_bought, "q_other": q_other, "gross_live": gross_live, "gross": gross,
        "fee": round(gross_live - gross, 2), "limited": round(max(0.0, gross - star_gained), 2) if ok else 0.0,
        "star_gained": star_gained,
        "new_qty": max(0.0, min(stored_qty - q_bought, balance - vlt_amount)),
    }

_VLT_DOC_FIELDS = {"star_balance": 1, "vlt_balance": 1, "vlt_bought_qty": 1, "vlt_bought_cost": 1, "premium_until": 1, "_id": 0}

async def _vlt_wallet_doc(user_id):
    return await users_catcher_col.find_one({"user_id": user_id}, _VLT_DOC_FIELDS) or {}

def _vlt_available_block(market, mode, doc):
    """The one 'what can I exchange RIGHT NOW' box shown by /buyvlt and /sellvlt with no amount. FACTS ONLY (2026-11, owner: the notes to users in /buyvlt /sellvlt were still
    confusing, and the ones saying it was 'no use / no profit' had to go): no explanations, no fee talk, no warnings, no gauge or price graph. /buyvlt shows the rate and what
    the wallet can buy; /sellvlt shows what can be sold and what it pays — the amount the player will really receive (the fee and the 'never above what it cost' cap are already
    inside it), so there is never a second 'sell rate' that does not match the payout."""
    doc = doc or {}
    rate = market["rate"]
    if mode == "buy":
        try:
            stars = float(doc.get("star_balance", 0) or 0)
        except (TypeError, ValueError, OverflowError):
            stars = 0.0
        max_vlt = min(_vlt_floor2(stars / rate) if rate > 0 else 0.0, float(VLT_MAX_EXCHANGE_AMOUNT))
        rows = [f"1 💠 = <code>{rate:,.2f} ⭐</code>", f"💼 <code>{format_star_plain(stars)}</code>"]
        if max_vlt >= 0.01:
            rows.append(f"ဝယ်လို့ရတာ  <code>{max_vlt:,.2f} 💠</code> = <code>{round(max_vlt * rate, 2):,.2f} ⭐</code>")
        else:
            rows.append("⭐ မလုံလောက်သေးပါ")
        return "<blockquote>" + "\n".join(rows) + "</blockquote>"
    ratio = VIP_VLT_SELL_RATIO if is_vip_active(doc) else VLT_SELL_RATIO
    try:
        balance = float(doc.get("vlt_balance", 0) or 0)
    except (TypeError, ValueError, OverflowError):
        balance = 0.0
    s = _vlt_sellable(rate, balance, doc.get("vlt_bought_qty"), doc.get("vlt_bought_cost"), ratio)
    now_amt = _vlt_floor2(s["sellable"])
    if now_amt >= 0.01:
        q = _vlt_sell_quote(now_amt, rate, balance, doc.get("vlt_bought_qty"), doc.get("vlt_bought_cost"), ratio)
        return f"<blockquote>ရောင်းလို့ရတာ  <code>{now_amt:,.2f} 💠</code> → <code>{q['star_gained']:,.2f} ⭐</code></blockquote>"
    return "<blockquote>ရောင်းလို့ရတဲ့ 💠 မရှိပါ</blockquote>"

def _vlt_info_text(market, mode, doc=None):
    title = small_caps_full("vlt exchange")
    cmd = "buyvlt" if mode == "buy" else "sellvlt"
    action = "ဝယ်ရန်" if mode == "buy" else "ရောင်းရန်"
    return (
        f"💠 <b>{title}</b> · <b>{action}</b>\n"
        f"{_vlt_available_block(market, mode, doc)}\n"
        f"📌 <code>/{cmd} [VLT amount]</code> · <code>/{cmd} max</code> (အကုန်)"
    )

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]buyvlt(?:@\w+)?(?:\s+(\S+))?$', 'bot1')))
async def buy_vlt_handler(event):
    user_id = event.sender_id
    raw = event.pattern_match.group(1)
    market = await get_or_create_vlt_market()
    if not raw:
        return await event.reply(_vlt_info_text(market, "buy", await _vlt_wallet_doc(user_id)), parse_mode='html')
    want_max = raw.strip().lower() in ("max", "all")
    vlt_amount = None
    if not want_max:
        vlt_amount = _parse_vlt_amount(raw)
        if vlt_amount is None:
            return await event.reply("❌ <b>VLT ပမာဏ မှန်ကန်အောင် ရိုက်ပါ။</b> <i>(0.01 နဲ့ အထက်၊ ဂဏန်းသာ — ဒါမှမဟုတ် <code>max</code>)</i>", parse_mode='html')
    rate = market["rate"]
    async with _vlt_lock(user_id):
        if want_max:
            stars = float((await _vlt_wallet_doc(user_id)).get("star_balance", 0) or 0)
            vlt_amount = min(_vlt_floor2(stars / rate), float(VLT_MAX_EXCHANGE_AMOUNT))
            while vlt_amount >= 0.01 and round(vlt_amount * rate, 2) > stars + 1e-9:       # rounding the cost up must not overspend
                vlt_amount = round(vlt_amount - 0.01, 2)
            if vlt_amount < 0.01:
                return await event.reply(
                    f"❌ <b>⭐ Star Balance မလုံလောက်ပါ။</b>\n<blockquote>1 💠 = <code>{rate:,.2f} ⭐</code> | "
                    f"💼 လက်ကျန်: <code>{format_star_plain(stars)}</code></blockquote>", parse_mode='html')
        star_cost = round(vlt_amount * rate, 2)
        if not await try_deduct_star(user_id, star_cost):
            doc = await users_catcher_col.find_one({"user_id": user_id}, {"star_balance": 1, "_id": 0}) or {}
            return await event.reply(
                f"❌ <b>⭐ Star Balance မလုံလောက်ပါ။</b>\n"
                f"<blockquote>🧮 <code>{vlt_amount:,.2f} 💠 × {rate:,.2f} ⭐ = {star_cost:,.2f} ⭐</code>\n"
                f"💼 လက်ကျန်: <code>{format_star_plain(doc.get('star_balance', 0) or 0)}</code></blockquote>",
                parse_mode='html')
        # bought-with-⭐ VLT is tracked (qty + what it cost): it is the ONLY 💠 /sellvlt will take back, and never above this cost
        await users_catcher_col.update_one(
            {"user_id": user_id},
            {"$inc": {"vlt_balance": vlt_amount, "vlt_bought_qty": vlt_amount, "vlt_bought_cost": star_cost}},
            upsert=True)
    after = await users_catcher_col.find_one({"user_id": user_id}, {"star_balance": 1, "vlt_balance": 1, "_id": 0}) or {}
    await event.reply(
        f"✅ <b>{small_caps_full('vlt purchased')}</b>\n"
        f"<blockquote><code>{vlt_amount:,.2f} 💠 × {rate:,.2f} ⭐ = {star_cost:,.2f} ⭐</code></blockquote>\n"
        f"💼 <code>{format_star_plain(after.get('star_balance', 0) or 0)}</code> · <code>{format_vlt_plain(after.get('vlt_balance', 0) or 0)}</code>",
        parse_mode='html')

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]sellvlt(?:@\w+)?(?:\s+(\S+))?$', 'bot1')))
async def sell_vlt_handler(event):
    user_id = event.sender_id
    raw = event.pattern_match.group(1)
    market = await get_or_create_vlt_market()
    if not raw:
        return await event.reply(_vlt_info_text(market, "sell", await _vlt_wallet_doc(user_id)), parse_mode='html')
    want_max = raw.strip().lower() in ("max", "all")
    vlt_amount = None
    if not want_max:
        vlt_amount = _parse_vlt_amount(raw)
        if vlt_amount is None:
            return await event.reply("❌ <b>VLT ပမာဏ မှန်ကန်အောင် ရိုက်ပါ။</b> <i>(0.01 နဲ့ အထက်၊ ဂဏန်းသာ — ဒါမှမဟုတ် <code>max</code>)</i>", parse_mode='html')
    rate = market["rate"]
    async with _vlt_lock(user_id):
        doc = await _vlt_wallet_doc(user_id)
        ratio = VIP_VLT_SELL_RATIO if is_vip_active(doc) else VLT_SELL_RATIO        # 👑 VIP perk: 5% fee instead of 10%
        balance = float(doc.get("vlt_balance", 0) or 0)
        if want_max:
            vlt_amount = _vlt_floor2(_vlt_sellable(rate, balance, doc.get("vlt_bought_qty"), doc.get("vlt_bought_cost"), ratio)["sellable"])
            vlt_amount = min(vlt_amount, float(VLT_MAX_EXCHANGE_AMOUNT))
            if vlt_amount < 0.01:
                return await event.reply(_vlt_info_text(market, "sell", doc), parse_mode='html')
        if balance + 1e-9 < vlt_amount:
            return await event.reply(
                f"❌ <b>💠 VLT Balance မလုံလောက်ပါ။</b>\n"
                f"<blockquote>💼 လက်ကျန်: <code>{format_vlt_plain(balance)}</code></blockquote>", parse_mode='html')
        q = _vlt_sell_quote(vlt_amount, rate, balance, doc.get("vlt_bought_qty"), doc.get("vlt_bought_cost"), ratio=ratio)
        if not q["ok"]:
            can = _vlt_floor2(q["sellable"])
            return await event.reply(
                (f"❌ <b>ရောင်းလို့ရတာ <code>{can:,.2f}</code> 💠 ပဲ ရှိပါတယ်။</b>\n⚡ <code>/sellvlt max</code>" if can >= 0.01
                 else "❌ <b>ရောင်းလို့ရတဲ့ 💠 မရှိပါ။</b>"), parse_mode='html')
        avg_cost, star_gained, new_qty = q["avg_cost"], q["star_gained"], q["new_qty"]
        if star_gained <= 0:
            return await event.reply("❌ <b>ပမာဏ အရမ်းသေးလို့ ⭐ တစ်ခုမှ မရနိုင်ပါ။</b>", parse_mode='html')
        if not await try_deduct_vlt(user_id, vlt_amount):
            return await event.reply("❌ <b>💠 VLT Balance မလုံလောက်ပါ။</b>", parse_mode='html')
        await users_catcher_col.update_one(
            {"user_id": user_id},
            {"$inc": {"star_balance": star_gained},
             "$set": {"vlt_bought_qty": round(new_qty, 6), "vlt_bought_cost": round(avg_cost * new_qty, 6)}},
            upsert=True)
    after = await users_catcher_col.find_one({"user_id": user_id}, {"star_balance": 1, "vlt_balance": 1, "_id": 0}) or {}
    await event.reply(
        f"✅ <b>{small_caps_full('vlt sold')}</b>\n"
        f"<blockquote><code>{vlt_amount:,.2f} 💠 → {star_gained:,.2f} ⭐</code></blockquote>\n"
        f"💼 <code>{format_star_plain(after.get('star_balance', 0) or 0)}</code> · <code>{format_vlt_plain(after.get('vlt_balance', 0) or 0)}</code>",
        parse_mode='html')

# ==========================================
# 🏆 LEADERBOARDS
# ==========================================
TOP_MEDALS = {0: "🥇", 1: "🥈", 2: "🥉"}

# 🎨 ONE LOOK FOR EVERY BOARD (2026-10, per owner request — "richest / top / gtop / today UI ကို ပုံစံပြင်ပါ"). The four boards used to look like four …
def _lb_bar(value, peak, width=8):
    """▰▰▰▱▱▱▱▱ — `value` as a share of `peak`; anything above zero shows at least one block."""
    try:
        frac = max(0.0, min(1.0, float(value) / float(peak))) if peak else 0.0
    except (TypeError, ValueError, ZeroDivisionError):
        frac = 0.0
    filled = max(1, round(frac * width)) if frac > 0 else 0
    return "▰" * filled + "▱" * (width - filled)

def _lb_rank_tag(i):
    """🥇🥈🥉 for the podium, then 04, 05 … (i is 0-based)."""
    return TOP_MEDALS.get(i, f"<code>{i + 1:02d}</code>")

def _lb_title(icon, title, subtitle=""):
    return f"{icon} <b>{small_caps_full(title)}</b>" + (f"\n<i>{subtitle}</i>" if subtitle else "")

# 🩹 (2026-10, Render 5 GB/month outbound cap — the owner named /harem /top /gtop /richest /balance and the casino as the busiest commands):
LEADERBOARD_TEXT_TTL = 60
_LEADERBOARD_TEXT_CACHE = {}      # key -> (text, expiry)

async def _cached_text(key, builder, ttl=LEADERBOARD_TEXT_TTL):
    now = time.time()
    hit = _LEADERBOARD_TEXT_CACHE.get(key)
    if hit and now < hit[1]:
        return hit[0]
    text = await builder()
    if text:                                       # never cache "nothing here yet" — the first catch should show up at once
        if len(_LEADERBOARD_TEXT_CACHE) > 600:
            _LEADERBOARD_TEXT_CACHE.clear()
        _LEADERBOARD_TEXT_CACHE[key] = (text, now + ttl)
    return text

async def _resolve_one_top_mention(client, user_id, stored_fullname):
    """Best-effort LIVE clickable mention (tg://user?id=...) for a leaderboard row, so /top
    and /gtop always point at the actual current account instead of a possibly-stale stored
    name. Falls back to the safely-sanitized stored fullname if the entity can't be resolved
    (e.g. the bot has genuinely never seen that user) — never breaks the leaderboard."""
    try:
        _hit = _PLAIN_NAME_CACHE.get(user_id)
        if _hit and time.time() < _hit[1]:
            live_name = _hit[0]
        else:
            entity = await client.get_entity(user_id)
            first = getattr(entity, 'first_name', '') or ''
            last = getattr(entity, 'last_name', '') or ''
            live_name = f"{first} {last}".strip() or getattr(entity, 'username', '') or f"User {user_id}"
            _PLAIN_NAME_CACHE[user_id] = (live_name, time.time() + 600)
        display = clean_display_name(live_name, fallback=f"User {user_id}")
    except Exception:
        display = clean_display_name(stored_fullname, fallback=f"User {user_id}")
    return f"<a href='tg://user?id={user_id}'><b>{escape_html(display)}</b></a>"

async def _resolve_top_mentions(client, users):
    # ⚡ PERFORMANCE: resolving 10 rows one-at-a-time meant 10 sequential Telegram round-trips
    # before /top or /gtop could reply — easily a couple of seconds, and the sort of thing
    # that reads as "the bot got heavier". Resolving all of them concurrently turns that into
    # a single parallel batch instead.
    return await asyncio.gather(*(
        _resolve_one_top_mention(client, u["user_id"], u.get("fullname")) for u in users
    ))

# ==========================================
# 🏅 COLLECTOR POINTS — /top, /gtop, /points, /setpoints (2026-11, per owner request — "Top gtop က စျေးကြီးသော high Rarity တွေပဲစုတဲ့သူတွေက ကဒ် amount မများတာမို့ မပါနေဘူး၊ rarity ၉ ဆင့်လုံးမှာ POINT သတ်မှတ်ပါ၊
# ULTRA and SUPREME က VLT စျေးတအားများတာမို့ ပိုင်ဆိုင်ဖို့ခက်ခဲတာမို့ အနိမ့် rarity တွေထက် သိသာတဲ့ point ပိုသတ်မှတ်ပါ၊ mlbb ကလို mega collector ဘာညာ သတ်မှတ်လို့ဖြစ်မှာလေ")
# ==========================================
# /top (this group) and /gtop (everyone) used to rank by NUMBER of cards caught, so a collector holding a handful of ULTRA / SUPREME cards — worth far more than hundreds of …
RARITY_POINTS_DEFAULT = {
    "ULTRA": 2000, "LEGEND": 1500,                 # 🎞 ULTRA · 🪞 SUPREME — hard & very expensive to own
    "MYTHIC": 300, "EPIC": 120,                    # 🦚 CROSSVERSE · ⚜️ DIVINE
    "INCREDIBLE": 50, "GOLD": 20,                  # 🐦‍🔥 INCREDIBLE · 🌕 GOLDENMOON
    "RARE": 8, "UNCOMMON": 3, "COMMON": 1,         # 🫐 RARE · ⚪ UNCOMMON · 🟤 COMMON
}
# (points needed, emoji, title) — the next title starts at the next row's number
COLLECTOR_TITLES = [
    (0, "🌱", "Rookie Collector"), (50, "📘", "Collector"), (300, "🥉", "Elite Collector"), (1000, "🥈", "Master Collector"),
    (3000, "🥇", "Grandmaster Collector"), (8000, "💎", "Epic Collector"), (20000, "🔥", "Legend Collector"),
    (50000, "👑", "Mega Collector"), (120000, "🌌", "Mythical Glory"),
]
COLLECTOR_BOARD_TTL = 300
_point_overrides = {}                                         # tier -> points set by /setpoints (mirrored in bot_settings_col "collector_points")
_POINTS_MAP_CACHE = {"at": 0.0, "map": {}}                    # {stored rarity string: points}

def points_for_tier(tier):
    if tier in _point_overrides:
        return _point_overrides[tier]
    return RARITY_POINTS_DEFAULT.get(tier, 0)

def collector_title(points):
    """(emoji, title, points needed for the next title or None)."""
    idx = 0
    for i, (need, _, _) in enumerate(COLLECTOR_TITLES):
        if points >= need:
            idx = i
    _, emoji, name = COLLECTOR_TITLES[idx]
    nxt = COLLECTOR_TITLES[idx + 1][0] if idx + 1 < len(COLLECTOR_TITLES) else None
    return emoji, name, nxt

_RARITY_TIER_MEMO = {}                                        # stored rarity string -> tier (a handful of distinct strings, so /harem can call this on every page turn)

def _tier_of_rarity_string(rarity):
    key = rarity if isinstance(rarity, str) else None
    tier = _RARITY_TIER_MEMO.get(key)
    if tier is None:
        tier = classify_rarity(key)
        if len(_RARITY_TIER_MEMO) < 2000:
            _RARITY_TIER_MEMO[key] = tier
    return tier

def collector_points_of_harem(harem):
    """(points, card count, {tier: count}) for a harem list — the same maths the leaderboard aggregation does inside MongoDB. Corrupt (non-dict) entries are skipped."""
    counts = {}
    for item in harem or []:
        if not isinstance(item, dict):
            continue
        tier = _tier_of_rarity_string(item.get("rarity"))
        counts[tier] = counts.get(tier, 0) + 1
    return sum(points_for_tier(t) * n for t, n in counts.items()), sum(counts.values()), counts

async def load_collector_point_overrides():
    try:
        doc = await bot_settings_col.find_one({"_id": "collector_points"}) or {}
        _point_overrides.clear()
        for tier, pts in (doc.get("points") or {}).items():
            if tier in RARITY_TIERS and isinstance(pts, int) and 0 <= pts <= 1_000_000:
                _point_overrides[tier] = pts
    except Exception as e:
        print(f"load_collector_point_overrides error: {e}")

async def _collector_points_map(force=False):
    """{stored rarity string: points}. Harem copies keep whatever display string their rarity had when they were caught (fancy fonts, old emoji…), so the strings are
    collected from the character list AND from the harems themselves, each classified once in Python — MongoDB then only does a cheap lookup per card."""
    now = time.time()
    if not force and _POINTS_MAP_CACHE["map"] and now - _POINTS_MAP_CACHE["at"] < 600:
        return _POINTS_MAP_CACHE["map"]
    strings = set()
    try:
        strings |= {c.get("rarity") for c in await get_all_characters_cached() if c.get("rarity")}
    except Exception as e:
        print(f"points map: character list error: {e}")
    try:
        strings |= set(await users_catcher_col.distinct("harem.rarity"))
    except Exception as e:
        print(f"points map: harem rarity scan error: {e}")
    mapping = {s: points_for_tier(classify_rarity(s)) for s in strings if isinstance(s, str) and s}
    _POINTS_MAP_CACHE["map"], _POINTS_MAP_CACHE["at"] = mapping, now
    return mapping

def _invalidate_points_caches():
    _POINTS_MAP_CACHE["at"] = 0.0
    _LEADERBOARD_TEXT_CACHE.clear()

async def _collector_top(match, limit=10):
    """Top `limit` players matching `match`, ranked by Collector Points, computed server-side. Rows: user_id, fullname, cards, points."""
    mapping = await _collector_points_map()
    strings, points = list(mapping.keys()), list(mapping.values())
    per_card = {"$let": {"vars": {"i": {"$indexOfArray": [{"$literal": strings}, "$$c.rarity"]}},
                         "in": {"$cond": [{"$gte": ["$$i", 0]}, {"$arrayElemAt": [{"$literal": points}, "$$i"]}, 0]}}}
    pipeline = [
        {"$match": match},
        {"$project": {"_id": 0, "user_id": 1, "fullname": 1,
                      "cards": {"$size": {"$ifNull": ["$harem", []]}},
                      "points": {"$sum": {"$map": {"input": {"$ifNull": ["$harem", []]}, "as": "c", "in": per_card}}}}},
        {"$match": {"points": {"$gt": 0}}},
        {"$sort": {"points": -1, "cards": 1, "user_id": 1}},
        {"$limit": limit},
    ]
    return await users_catcher_col.aggregate(pipeline, allowDiskUse=True).to_list(length=limit)

def _collector_rows(top_users, mentions):
    """One line per collector: rank · name · rank-title emoji — points. (2026-11, owner: "Top gtop ကလည်း message box က အလွန်ရှည်လျားပြီး UI မလှနေဘူး"): every row used to be THREE lines
    (name / title / "pts · cards ▰▰▱ bar") — 30+ lines for ten players. The title's words, the card count and the bar are gone; the title keeps its emoji (👑 = Mega Collector …)
    and /points spells the titles out. `mention` already comes back bold from _resolve_one_top_mention."""
    rows = []
    for i, (u, mention) in enumerate(zip(top_users, mentions)):
        emoji, _name, _ = collector_title(u["points"])
        rows.append(f"{_lb_rank_tag(i)} {mention} {emoji} — <code>{u['points']:,}</code> pts")
    return "\n".join(rows)

_POINTS_FOOTER = "<i>🏅 Points by rarity · <code>/points</code></i>"

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]top(?:@\w+)?$', 'bot1')))
async def local_group_top_handler(event):
    if event.is_private: return
    chat_id = event.chat_id

    async def _build():
        top_users = await _collector_top({f"group_catches.{str(chat_id)}": {"$gt": 0}, "user_id": {"$nin": banned_user_ids()}})
        if not top_users:
            return None
        mentions = await _resolve_top_mentions(event.client, top_users)
        return (
            f"{_lb_title('🏆', 'top collectors', 'This group · ranked by Collector Points')}\n"
            f"<blockquote>{_collector_rows(top_users, mentions)}</blockquote>\n{_POINTS_FOOTER}"
        )

    msg = await _cached_text(("top", chat_id), _build, ttl=COLLECTOR_BOARD_TTL)
    if not msg:
        return await event.reply(f"🏆 <b>No rank data in this group yet.</b>\n<i>Catch a card to get on the board!</i>", parse_mode='html')
    await event.reply(msg, parse_mode='html')

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]gtop(?:@\w+)?$', 'bot1')))
async def global_top_handler(event):
    async def _build():
        top_users = await _collector_top({"harem.0": {"$exists": True}, "user_id": {"$nin": banned_user_ids()}})
        if not top_users:
            return None
        mentions = await _resolve_top_mentions(event.client, top_users)
        return (
            f"{_lb_title('🌐', 'global top collectors', 'All groups · ranked by Collector Points')}\n"
            f"<blockquote>{_collector_rows(top_users, mentions)}</blockquote>\n{_POINTS_FOOTER}"
        )

    msg = await _cached_text(("gtop",), _build, ttl=COLLECTOR_BOARD_TTL)
    if not msg:
        return await event.reply(f"🌐 <b>No global ranking yet.</b>\n<i>Catch a card to get on the board!</i>", parse_mode='html')
    await event.reply(msg, parse_mode='html')

def _points_table_html():
    return "\n".join(
        f"{RARITY_EMOJI.get(t, RARITY_DEFAULT_EMOJI)} {RARITY_DISPLAY_NAME.get(t, t)} — <code>{points_for_tier(t):,}</code>" + (" ✏️" if t in _point_overrides else "")
        for t in RARITY_TIERS
    )

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]points(?:@\w+)?$', 'bot1')))
async def collector_points_handler(event):
    if is_duplicate_event(event): return
    target_id = event.sender_id
    if event.is_reply:
        rm = await event.get_reply_message()
        if rm and rm.sender_id:
            target_id = rm.sender_id
    doc = await users_catcher_col.find_one({"user_id": target_id}, {"harem": 1, "fullname": 1})
    harem = (doc or {}).get("harem") or []
    points, cards, counts = collector_points_of_harem(harem)
    emoji, name, nxt = collector_title(points)
    who = await get_html_mention(event, target_id)
    lines = [f"🏅 <b>COLLECTOR POINTS</b> — {who}", f"{emoji} <b>{name}</b> · <code>{points:,}</code> pts · <code>{cards:,}</code> card{'' if cards == 1 else 's'}"]
    if nxt is not None:
        lines.append(f"📈 Next title at <code>{nxt:,}</code> pts — <code>{nxt - points:,}</code> to go")
    else:
        lines.append("👑 Highest title reached!")
    owned = [(t, counts[t]) for t in RARITY_TIERS if counts.get(t)]
    if owned:
        lines += ["", "<blockquote>" + "\n".join(
            f"{RARITY_EMOJI.get(t, RARITY_DEFAULT_EMOJI)} {RARITY_DISPLAY_NAME.get(t, t)} ×{n:,} → <code>{points_for_tier(t) * n:,}</code>" for t, n in owned) + "</blockquote>"]
    lines += ["", "<b>Points per card</b>", f"<blockquote>{_points_table_html()}</blockquote>",
              "🏆 <code>/top</code> (this group) · <code>/gtop</code> (everyone) rank by these points."]
    await event.reply("\n".join(lines), parse_mode='html')

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]setpoints(?:@\w+)?(?:\s+(?:no)?(\d)\s+(\d+|reset))?(?:\s+(reset))?$', 'bot1')))
async def setpoints_handler(event):
    if event.sender_id != OWNER_ID: return
    if is_duplicate_event(event): return
    num, val = event.pattern_match.group(1), event.pattern_match.group(2)
    if num is None:
        txt = (event.raw_text or "").strip().lower()
        if txt.split()[-1:] == ["reset"] and len(txt.split()) == 2:          # "/setpoints reset" — every tier back to default
            _point_overrides.clear()
            try:
                await bot_settings_col.delete_one({"_id": "collector_points"})
            except Exception as e:
                print(f"setpoints reset save error: {e}")
            _invalidate_points_caches()
            return await event.reply("✅ <b>All tiers are back to their default points.</b>", parse_mode='html')
        return await event.reply(
            "🏅 <b>Collector Points per card</b> <i>(✏️ = owner-set)</i>\n"
            f"<blockquote>{_points_table_html()}</blockquote>\n"
            "<b>Change:</b> <code>/setpoints no1 2500</code> <i>(tier No.1 = ULTRA … No.9 = COMMON)</i>\n"
            "<code>/setpoints no1 reset</code> · <code>/setpoints reset</code> <i>(everything)</i>", parse_mode='html')
    idx = int(num) - 1
    if not (0 <= idx < len(RARITY_TIERS)):
        return await event.reply("⚠️ Tier must be <code>no1</code> … <code>no9</code>.", parse_mode='html')
    tier = RARITY_TIERS[idx]
    if val == "reset":
        _point_overrides.pop(tier, None)
        msg = f"✅ {RARITY_EMOJI.get(tier, '')} <b>{RARITY_DISPLAY_NAME.get(tier, tier)}</b> is back to the default <code>{RARITY_POINTS_DEFAULT.get(tier, 0):,}</code> pts."
    else:
        pts = int(val)
        if pts > 1_000_000:
            return await event.reply("⚠️ Max is 1,000,000 points per card.", parse_mode='html')
        _point_overrides[tier] = pts
        msg = f"✅ {RARITY_EMOJI.get(tier, '')} <b>{RARITY_DISPLAY_NAME.get(tier, tier)}</b> now earns <code>{pts:,}</code> pts per card."
    try:
        await bot_settings_col.update_one({"_id": "collector_points"}, {"$set": {"points": dict(_point_overrides)}}, upsert=True)
    except Exception as e:
        print(f"setpoints save error: {e}")
        msg += "\n⚠️ <i>Saved in memory only — a restart would lose it.</i>"
    _invalidate_points_caches()
    await event.reply(msg + "\n<i>/top and /gtop use it right away.</i>", parse_mode='html')

# ==========================================
# 💰 BALANCE (Wallet HUD card + optional owner-set banner photo)
# ==========================================
# 🖼️ /addbalance — owner-only, reply to a photo or video to set a GLOBAL banner shown on top of
# EVERY user's /balance card. Same storage pattern as /addchar: the media gets forwarded into
# SPECIFIC_CONTROL_GROUP exactly once, and only its storage_msg_id is kept (in bot_settings_col
# this time, since this is a single bot-wide setting, not a per-character doc) —
# check_points_balance below fetches it fresh from storage on every /balance call.
@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]addbalance(?:@\w+)?$', 'bot1')))
async def add_balance_banner(event):
    if event.sender_id != OWNER_ID: return
    if is_duplicate_event(event): return
    if not event.is_reply:
        return await event.reply(
            "❌ <b>Reply to a photo or video with /addbalance</b> — that media becomes the "
            "banner shown on top of everyone's /balance card.",
            parse_mode='html'
        )
    reply_msg = await event.get_reply_message()
    if not reply_msg or not (reply_msg.photo or reply_msg.video or reply_msg.document):
        return await event.reply("❌ <b>Valid media not found</b>", parse_mode='html')
    try:
        forwarded_msg = await send_safe_message(bot1, SPECIFIC_CONTROL_GROUP, "", file=reply_msg.media)
        await bot_settings_col.update_one(
            {"_id": "balance_wallet_banner"},
            {"$set": {"storage_msg_id": forwarded_msg.id, "set_by": event.sender_id, "set_at": time.time()}},
            upsert=True
        )
        _BALANCE_BANNER_CACHE[1] = 0.0
        await event.reply("✅ <b>Wallet banner updated!</b> Every /balance card will show it from now on.", parse_mode='html')
    except Exception as e:
        await event.reply(f"❌ <b>Failed to save banner:</b> <code>{escape_html(str(e))}</code>", parse_mode='html')

# 🩹 (2026-10, Render 5 GB/month outbound cap): every /balance read the banner setting from Mongo AND asked Telegram for the banner message
# (GetMessages) before sending. The banner almost never changes, so it is now fetched once per 5 minutes (30 s after a failed attempt) and
# re-used; /addbalance and /removebalance clear it immediately.
_BALANCE_BANNER_CACHE = [None, 0.0]       # [media or None, expiry]

async def _get_balance_banner_media():
    now = time.time()
    if now < _BALANCE_BANNER_CACHE[1]:
        return _BALANCE_BANNER_CACHE[0]
    media, ttl = None, 300
    try:
        banner_doc = await bot_settings_col.find_one({"_id": "balance_wallet_banner"})
        storage_msg_id = banner_doc.get("storage_msg_id") if banner_doc else None
        if storage_msg_id:
            storage_msg = await bot1.get_messages(SPECIFIC_CONTROL_GROUP, ids=storage_msg_id)
            if storage_msg and storage_msg.media:
                media = storage_msg.media
            else:
                ttl = 30
    except Exception:
        ttl = 30
    _BALANCE_BANNER_CACHE[0], _BALANCE_BANNER_CACHE[1] = media, now + ttl
    return media

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]balance(?:@\w+)?$', 'bot1')))
async def check_points_balance(event):
    user_id = event.sender_id
    user_doc = await users_catcher_col.find_one({"user_id": user_id})
    star_balance = user_doc.get("star_balance", 0) if user_doc else 0
    vlt_balance = user_doc.get("vlt_balance", 0) if user_doc else 0
    plain_name = await get_plain_name(event, user_id)

    # sc() runs BEFORE escape_html() on purpose — escaping first would turn a literal '&' into
    # the entity '&amp;', and sc() blindly remapping every lowercase letter would then mangle
    # that entity's own 'a'/'m'/'p' into small-caps glyphs too. Small-caps first, escape second.
    title_text = escape_html(sc(f"{plain_name}'s Wallet"))
    crown = " 👑" if user_doc and is_vip_active(user_doc) else ""
    market = await _vlt_market_for_display()

    # 🎨 (2026-10, per owner request) new wallet card — see _wallet_block: balances in a quote block (the old one printed every emoji twice,
    # "⭐ Stars: 1,234 ⭐"), what the VLT would fetch if sold, and today's exchange rate with its movement.
    text = (
        f"👛 <b>{title_text}</b>{crown}\n"
        f"{_wallet_block(star_balance, vlt_balance, market, bought=((user_doc or {}).get('vlt_bought_qty'), (user_doc or {}).get('vlt_bought_cost')))}\n"
        f"{_rate_line(market)}"
    ).rstrip()

    # 🔹 ဒီမှာ ခလုတ်တွေကို ၂ တန်း ၂ လုံးစီ ခွဲထားတယ်
    buttons = [
        [
            Button.inline("🏪 စျေးဝယ်မယ်", data=f"buyhub_cards_{user_id}"),
            Button.inline("💠 VLT ဝယ်မယ်", data=f"buyhub_star_{user_id}")
        ],
        [
            Button.inline("👑 VIP Mode ဝယ်မယ်", data=f"buyhub_vip_{user_id}"),
            Button.inline("🎰 Casino ဂိမ်းများ", data="nav_casino_main")  # ဒီခလုတ်က bot1 မှာရှိတဲ့ Menu ကိုပဲ ခေါ်သွားမယ်
        ]
    ]

    # 🎰 The reply-to is only attached in supergroups/channels.
    _wallet_reply_to = event.message.id if getattr(event, "is_channel", False) else None

    # 🖼️ Optional owner-set wallet banner (see /addbalance above) — falls back to plain text
    # if none has been set yet, or if the stored media couldn't be fetched for any reason.
    banner_media = await _get_balance_banner_media()
    if banner_media:
        try:
            await _casino_out(event, message=text, parse_mode='html', file=banner_media, buttons=buttons, reply_to=_wallet_reply_to)
            return
        except Exception:
            _BALANCE_BANNER_CACHE[1] = 0.0          # the cached media may have gone stale — look it up afresh next time
    await _casino_out(event, message=text, parse_mode='html', buttons=buttons, reply_to=_wallet_reply_to)

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]topgift(?:@\w+)?$', 'bot1')))
async def top_gifters_handler(event):
    cursor = users_catcher_col.find({"total_gifted": {"$gt": 0}, "user_id": {"$nin": banned_user_ids()}}).sort("total_gifted", -1).limit(10)
    top_users = await cursor.to_list(length=10)
    if not top_users:
        return await event.reply(f"🎁 <b>No gifts sent yet.</b>\n<i>/gift a card to get on the board!</i>", parse_mode='html')
    mentions = await _resolve_top_mentions(event.client, top_users)
    peak = top_users[0].get("total_gifted", 0)
    lines = []
    for i, (u, mention) in enumerate(zip(top_users, mentions)):
        count = u.get("total_gifted", 0)
        title = get_giver_title(count)
        title_str = f" {title[0]}" if title else ""
        lines.append(f"{_lb_rank_tag(i)} <b>{mention}</b>{title_str}\n      <code>{count:,}</code> gift{'' if count == 1 else 's'}  <code>{_lb_bar(count, peak)}</code>")
    msg = (
        f"{_lb_title('🎁', 'top gifters', 'Cards given · all time')}\n"
        f"<blockquote>{chr(10).join(lines)}</blockquote>"
    )
    await event.reply(msg, parse_mode='html')

