# ==========================================
# 🎖️ GIFT RANK TITLES — 6 escalating Burmese titles for GIVING (total_gifted) and a separate
# 6 for RECEIVING (total_gift_received). Purely a cosmetic badge computed live off the two
# counters already tracked on every /gift — nothing extra to keep in sync. Sorted descending
# by threshold so the first match in a scan is always the highest tier reached.
# ==========================================
GIFT_TIER_THRESHOLDS = (10, 30, 50, 100, 200, 300)  # 300+ is the open-ended top tier

GIFT_GIVER_TITLES = [  # (threshold, emoji, title) — "the one who gives cards away"
    (300, "🏆", "ကဒ်ဘုရင်"),        # Card King
    (200, "👑", "ကဒ်မင်းလေး"),          # Card Prince
    (100, "⚔️", "ကဒ်သခင်"),         # Card Lord
    (50, "📜", "ကဒ်ဆရာ"),           # Card Master
    (30, "🎗️", "ကဒ်ရက်ရောရှင်"),    # Generous Card-Giver
    (10, "🎁", "ကဒ်အလှူရှင်"),        # Card Donor
]
GIFT_RECEIVER_TITLES = [  # (threshold, emoji, title) — "the one showered with cards"
    (300, "👑", "ကဒ်ဘုန်းရှင်"),     # The Glorious One
    (200, "🌺", "ကဒ်ဂုဏ်ရှင်"),      # The Honored One
    (100, "💎", "ကဒ်မြတ်နိုးရှင်"),   # The Cherished One
    (50, "🌟", "ကဒ်ကျော်စောရှင်"),   # The Renowned One
    (30, "💝", "ကဒ်နှစ်လိုရှင်"),     # The Beloved One
    (10, "🎀", "ကဒ်ကံရှင်"),         # Fortune's Chosen
]

def _gift_title_for_count(count, titles_desc):
    """titles_desc must be sorted descending by threshold. Returns (emoji, title) for the
    highest tier `count` qualifies for, or None if below every threshold."""
    for threshold, emoji, title in titles_desc:
        if count >= threshold:
            return emoji, title
    return None

def get_giver_title(total_gifted):
    return _gift_title_for_count(total_gifted, GIFT_GIVER_TITLES)

def get_receiver_title(total_gift_received):
    return _gift_title_for_count(total_gift_received, GIFT_RECEIVER_TITLES)

# ==========================================
# 🎁 GIFT (fixed)
# ==========================================
_OWN_BOT_NAME_CACHE = {}   # our bot's user id -> display name

async def own_bot_display_name(user_id):
    """Display name of OUR bot (bot1) — or None when user_id isn't it.
    Used to word a card handed to a bot (see gift_asset_handler / gift_callback_handler)."""
    if not user_id or user_id not in bot_ids:
        return None
    cached = _OWN_BOT_NAME_CACHE.get(user_id)
    if cached:
        return cached
    for _cl in (bot1,):
        try:
            _me = await _cl.get_me()
        except Exception:
            continue
        if _me and _me.id == user_id:
            _name = f"{getattr(_me, 'first_name', '') or ''} {getattr(_me, 'last_name', '') or ''}".strip() \
                    or getattr(_me, 'username', '') or "the bot"
            _OWN_BOT_NAME_CACHE[user_id] = _name
            return _name
    return None

def _bot_card_block_text(bot_name):
    """The reply when someone tries to send a card to one of OUR bots. Never says 'gift'; names the bot; makes clear the card is safe."""
    return (
        f"🛡️ <b>Card protected</b>\n\n"
        f"<b>{escape_html(bot_name)}</b> is a bot — it has no collection to keep cards in, so it can't receive one.\n"
        f"Nothing was taken from you: your card is still safe in your collection.\n\n"
        f"<i>To send a card, reply to a player's message with the command.</i>"
    )

GIFT_NOTE_MAX_LEN = 150  # characters — keeps the note a quick line, not a wall of text on the gift card

def _rarity_label_plain(rarity_str):
    """HTML-safe rarity text with its leading tier emoji stripped off (\"🦚 𝗠𝗬𝗧𝗛𝗜𝗖𝗔𝗟 𝗡𝗼.𝟯\" ->
    \"𝗠𝗬𝗧𝗛𝗜𝗖𝗔𝗟 𝗡𝗼.𝟯\"). The gift cards below show the tier emoji separately (next to the card
    name / as the 🦋 label), so leaving it on the text too just doubles it up."""
    txt = (rarity_str or "Unknown").strip()
    emoji = RARITY_EMOJI.get(classify_rarity(txt))
    if emoji and txt.startswith(emoji):
        txt = txt[len(emoji):].strip()
    return escape_html(txt or "Unknown")

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]gift(?:@\w+)?\s+(\S+)(?:\s+(.+))?$', 'bot1')))
async def gift_asset_handler(event):
    if (event.pattern_match.group(1) or "").strip().lower() == "all":
        return      # "/gift all" has its own handler (giftall_prompt) — this one is for a single card id
    if not event.is_reply:
        return await event.reply("❌ <b>Reply to the user you want to gift.</b>", parse_mode='html')

    char_id = normalize_char_id_input(event.pattern_match.group(1))
    # 💌 NEW (per owner request — "Gift with a Note"): anything typed after the char_id is an …
    gift_note = escape_html((event.pattern_match.group(2) or "").strip()[:GIFT_NOTE_MAX_LEN])
    sender_id = event.sender_id
    reply_msg = await event.get_reply_message()
    receiver_id = reply_msg.sender_id

    if sender_id == receiver_id:
        return await event.reply("❌ <b>Can't gift to yourself!</b>", parse_mode='html')

    # 🛡️ (2026-11, per owner request — "ငါတို့ bot ကို ပေးမိလို့ လူတွေ ကဒ်မဆုံးသွားအောင်") a bot has no collection: a card sent to one of OUR bots would just vanish.
    # So it is never accepted — no confirmation card, nothing leaves the sender's collection — and the reply says so (English, names the bot).
    _bot_name = await own_bot_display_name(receiver_id)
    if _bot_name:
        return await event.reply(_bot_card_block_text(_bot_name), parse_mode='html')

    # 🩹 FIX (per owner report — "gbanned players still ending up with cards"): gban_block_gate …
    receiver_banned, _receiver_ban_rec = is_gbanned(receiver_id)
    if receiver_banned:
        return await event.reply("🚫 <b>That user is globally banned — they can't receive gifts right now.</b>", parse_mode='html')

    # 🩹 FIX (moved to gift_callback_handler below, per owner report): the 1000 ⭐ gift fee …
    if exl_parse_id(char_id):
        return await _exl_gift_prompt(event, sender_id, receiver_id, exl_parse_id(char_id), gift_note)

    char_data = await characters_base_col.find_one({"char_id": char_id})
    if not char_data:
        return await event.reply("❌ <b>Character data not found.</b>", parse_mode='html')

    if sender_id != OWNER_ID:
        sender_doc = await users_catcher_col.find_one({"user_id": sender_id})
        sender_harem = sender_doc.get("harem", []) if sender_doc else []
        char_item = next((x for x in sender_harem if isinstance(x, dict) and x.get("char_id") == char_id and x.get("status") != "market"), None)
        if not char_item:
            _hint = ("\n\nℹ️ <i>Your Complete Collection is view-only — you can only gift cards you've really obtained.</i>"
                     if sender_id in added_owner_ids else "")
            return await event.reply(f"❌ <b>You don’t have this card.</b>{_hint}", parse_mode='html')

    r_mention = await get_html_mention(event, receiver_id)
    # 🩹 REDESIGNED (2026-09, per owner request — "too many separate fields, feels like a bot
    # message"): card info is grouped into 2 short lines (name · #id, then rarity · artist)
    # instead of one field per line, and the confirmation reads like a sentence.
    rarity_text = _rarity_label_plain(char_data.get("rarity", "Unknown"))
    artist_raw = char_data.get("artist")
    artist_part = f"  ·  🎨 {escape_html(str(artist_raw).strip())}" if artist_raw and str(artist_raw).strip() else ""
    note_preview = f"💭 Note: <i>{gift_note}</i>\n" if gift_note else ""
    confirm_text = (
        f"<b>🫧 Gift Confirmation</b>\n\n"
        f"🎁 <b>{escape_html(char_data['name'])}</b> · <code>#{display_char_id(char_id)}</code>\n"
        f"🦋 {rarity_text}{artist_part}\n\n"
        f"💌 Sending to {r_mention}\n"
        f"{note_preview}\n"
        f"<blockquote>Send this card to {r_mention}?</blockquote>\n\n"
        f"✨ Tap below to confirm! Sir."
    )
    if gift_note:
        pending_gift_notes[(sender_id, receiver_id, char_id)] = {"note": gift_note, "expiry": time.time() + 600}

    buttons = [
        [
            colored_button("✅ Yep, Why Not✔", f"gift_confirm_{sender_id}_{receiver_id}_{char_id}", color="success"),
            Button.inline("❌ Nope, Jk✗", data=f"gift_cancel_{sender_id}_{receiver_id}_{char_id}")
        ]
    ]

    async def _send_gift_confirm(media):
        return await event.reply(confirm_text, file=media, buttons=buttons, parse_mode='html')

    sent = await send_with_char_media(char_data["char_id"], char_data["storage_msg_id"], _send_gift_confirm)
    if sent is None:
        await event.reply(confirm_text, buttons=buttons, parse_mode='html')

@bot1.on(events.CallbackQuery(pattern=r'^gift_(confirm|cancel)_(\d+)_(\d+)_([a-zA-Z0-9_]+)$'))
async def gift_callback_handler(event):
    action = event.pattern_match.group(1)
    if isinstance(action, bytes):
        action = action.decode('utf-8')
    sender_id = int(event.pattern_match.group(2))
    receiver_id = int(event.pattern_match.group(3))
    char_id_raw = event.pattern_match.group(4)
    if isinstance(char_id_raw, bytes):
        char_id = char_id_raw.decode('utf-8').upper()
    else:
        char_id = char_id_raw.upper()
    if event.sender_id != sender_id:
        return await event.answer("❌ This action is not for you!", alert=True)
    # 🛡️ same protection for an old confirmation card that is still on screen: a card is never moved to one of OUR bots (see gift_asset_handler)
    _bot_name = await own_bot_display_name(receiver_id)
    if _bot_name:
        try:
            await event.edit(_bot_card_block_text(_bot_name), parse_mode='html', buttons=None)
        except Exception:
            pass
        return await event.answer("Card protected — nothing was sent.", alert=True)
    if action == "confirm":
        receiver_banned, _receiver_ban_rec = is_gbanned(receiver_id)
        if receiver_banned:
            await event.edit("🚫 <b>That user is globally banned — this gift can't go through.</b>", parse_mode='html', buttons=None)
            return await event.answer("Recipient is globally banned.", alert=True)
    if not claim_single_tap(event):
        return await event.answer("⏳ Already processing...", alert=False)
    # 💌 Pop (not peek) — a note is meant for exactly the ONE gift it was typed alongside, not
    # reused if this same trio somehow gets confirmed again later.
    note_entry = pending_gift_notes.pop((sender_id, receiver_id, char_id), None)
    gift_note = note_entry["note"] if (note_entry and time.time() <= note_entry["expiry"]) else ""
    if action == "cancel":
        await event.edit(
            f"❌ <b>Gift Cancelled</b>\n\n"
            f"Card <code>{display_char_id(char_id)}</code> was not sent.\n"
            f"🐇 Maybe next time!",
            parse_mode='html',
            buttons=None
        )
        await event.answer("Gift cancelled.", alert=True)
        return
    # confirm
    if exl_parse_id(char_id):        # 🧣 EXCLUSIVE LIMITED (2026-11) — the card moves to the receiver, see part 4
        return await _exl_gift_execute(event, sender_id, receiver_id, exl_parse_id(char_id), gift_note)
    if sender_id == OWNER_ID:
        # 👑 Unlimited vault: nothing to remove — this card stays available for every future
        # gift too. Rarity comes straight from the character record instead of a harem item
        # (the owner may never have actually caught this one for real). Gift stats are still
        # tracked for visibility, they just don't touch the owner's real harem array.
        char_data = await characters_base_col.find_one({"char_id": char_id})
        if not char_data:
            await event.edit(
                f"❌ <b>Oops!</b>\n\n"
                f"Character <code>{display_char_id(char_id)}</code> no longer exists.",
                parse_mode='html',
                buttons=None
            )
            await event.answer("Card not found.", alert=True)
            return
        char_rarity = char_data.get("rarity", "Unknown")
        gift_tier = classify_rarity(char_rarity)
        await users_catcher_col.update_one(
            {"user_id": sender_id},
            {"$inc": {"total_gifted": 1, f"gifted_by_rarity.{gift_tier}": 1}},
            upsert=True
        )
        # 🩹 FIX (per owner report — "always having to run /refillcatch after gifts"): the …
        await characters_base_col.update_one({"char_id": char_id}, {"$inc": {"spawn_count": 1}})
        asyncio.create_task(wishlist_progress_notify(char_id, exclude=(receiver_id,)))
    else:
        sender_doc = await users_catcher_col.find_one({"user_id": sender_id})
        sender_harem = sender_doc.get("harem", []) if sender_doc else []
        char_item = next((x for x in sender_harem if isinstance(x, dict) and x.get("char_id") == char_id and x.get("status") != "market"), None)
        if not char_item:
            await event.edit(
                f"❌ <b>Oops!</b>\n\n"
                f"It seems you no longer have card <code>{display_char_id(char_id)}</code>.\n"
                f"☄️ Looks like luck played a little trick on you!",
                parse_mode='html',
                buttons=None
            )
            await event.answer("Card not found.", alert=True)
            return
        # 🩹 FIX: atomic $pull-based removal (see remove_one_harem_copy) instead of the old
        # find_one → sender_harem.remove() → $set the whole array back — same lost-update
        # race risk as marketplace/trade/sell fixed earlier.
        char_rarity = char_item.get("rarity", "Unknown")
        gift_tier = char_item.get("rarity_tier") or classify_rarity(char_rarity)
        await remove_one_harem_copy(sender_id, char_id, char_item.get("status", "vault"))
        await users_catcher_col.update_one(
            {"user_id": sender_id},
            {"$inc": {"total_gifted": 1, f"gifted_by_rarity.{gift_tier}": 1}}
        )
        sender_doc_after = await users_catcher_col.find_one({"user_id": sender_id}, {"harem": 1})
        await clear_stale_favorite(sender_id, char_id, (sender_doc_after or {}).get("harem", []))

    # 🩹 FIX: the 1000 ⭐ gift fee is now charged HERE — only once validation above has …
    fee_note = ""

    r_mention = await get_html_mention(event, receiver_id)
    r_plain_name = await get_plain_name(event, receiver_id)
    await users_catcher_col.update_one(
        {"user_id": receiver_id},
        {
            "$push": {"harem": {"char_id": char_id, "caught_date": time.time(), "rarity": char_rarity, "status": "vault"}},
            "$inc": {"total_caught": 1, "total_gift_received": 1},
            "$set": {"fullname": r_plain_name}
        },
        upsert=True
    )
    # 🩹 REMOVED (2026-11, per owner request): no per-gift history rows are written to the database any more (it was never needed).

    # 🎖️ Gift Rank: pull the sender's fresh post-gift count and work out (a) their current
    # title, and (b) whether THIS gift is the exact moment that crossed them into a new tier
    # (count lands precisely on a threshold — safe since each gift only ever moves a counter
    # up by 1) — that's the promotion banner moment, shown once, right when it happens.
    sender_after = await users_catcher_col.find_one({"user_id": sender_id}, {"total_gifted": 1})
    sender_gift_count = (sender_after or {}).get("total_gifted", 0)
    giver_title = get_giver_title(sender_gift_count)
    giver_promoted = sender_gift_count in GIFT_TIER_THRESHOLDS
    # 🩹 REDESIGNED (2026-09, per owner request): rank + running gift count share one line
    # ("🎁 ကဒ်အလှူရှင် · Gift #12"); below the first tier (no title yet) it's just "Gift #N".
    if giver_title:
        giver_rank_line = f"{giver_title[0]} {giver_title[1]} · Gift #{sender_gift_count}\n"
    else:
        giver_rank_line = f"🎁 Gift #{sender_gift_count}\n"
    giver_promo_line = (
        f"\n\n🎉 <b>New rank unlocked!</b>\n{giver_title[0]} {giver_title[1]} · {sender_gift_count} gifts"
        if giver_promoted and giver_title else ""
    )

    # 🎨 A designed confirmation where the gift happened.
    char_doc = await characters_base_col.find_one({"char_id": char_id})
    char_name_display = escape_html(char_doc.get("name", "?")) if char_doc else char_id
    rarity_emoji = RARITY_EMOJI.get(gift_tier, RARITY_DEFAULT_EMOJI)
    s_mention = await get_html_mention(event, sender_id)

    await event.edit(
        f"<b>🎁 Gift sent!</b>\n\n"
        f"{s_mention} → {r_mention}\n\n"
        f"{rarity_emoji} <b>{char_name_display}</b> <code>#{display_char_id(char_id)}</code>\n"
        f"{_rarity_label_plain(char_rarity)}\n\n"
        f"{fee_note}"
        f"{giver_rank_line}"
        f"{'💭 <i>' + gift_note + '</i>' + chr(10) if gift_note else ''}\n"
        f"Enjoy your card ♡"
        f"{giver_promo_line}",
        parse_mode='html',
        buttons=None
    )
    await event.answer("Gift sent successfully!", alert=True)
    # 🩹 CHANGED (per owner request): a DM to the receiver used to be sent here too — removed,
    # the in-chat confirmation above is enough now.

# ==========================================
# 🎁 /gift all (2026-11, per owner request) — VIP only: hand your WHOLE harem to one player, for 3,000 💠
# ==========================================
# WHY IT IS BUILT AROUND A "HOLD": a redeploy ("Clear cache & deploy") can kill this process at ANY line, and moving cards between two Mongo documents can't be one
# atomic write — so nothing here ever relies on the process staying alive between the two sides.
#   1. ONE atomic update on the SENDER's own document charges the fee AND moves every transferable card out of `harem` into `gift_all_hold` (same document, same write).
#      From then on the cards are never "in the air": they are in the harem or in the hold, and the hold carries everything needed to finish the job (receiver, the exact
#      card entries, the fee, the message to edit).
#   2. The receiver gets the cards with ONE update guarded by a per-transfer marker (gift_all_received $ne tid) — running it twice can never deliver twice.
#   3. ONE atomic update on the sender removes the hold and books the gift stats — also safe to run twice.
# A crash leaves a hold behind; giftall_recovery_loop() (first pass ~20s after every boot) finishes it — or, if the receiver got banned meanwhile or it still can't be
# delivered after an hour, puts the cards AND the fee back on the sender. A confirm button tapped just before a redeploy is simply "expired" afterwards (the preview lives
# in memory) and costs nothing: nothing is charged or moved before the confirm tap. Cards listed on the market (status "market") and 🧣 Exclusive Artwork (own collection)
# never move. The fee is burned (not credited to anyone). Cards keep counting against their catch limits exactly as before (the copies still exist — only the owner changes).
GIFT_ALL_FEE_VLT = 3000
GIFT_ALL_PENDING_TTL = 300             # seconds the preview's confirm button stays valid
GIFT_ALL_MAX_CARDS = 30000             # one Mongo document must stay far below 16 MB on both sides of the move
GIFT_ALL_GIVEUP_SECONDS = 3600         # a hold that still can't be delivered after this long is rolled back to the sender
gift_all_journal_col = db["gift_all_journal"]      # {_id: tid, sender_id, receiver_id, started} — tiny "something may be unfinished" list, so recovery never scans the players collection
_giftall_pending = {}                  # token -> preview data (memory only, on purpose)
_giftall_inflight = set()              # sender ids currently confirming (a second tap while one runs is refused)

# A harem entry moves only if it is a real card (string char_id) and is not escrowed in a market listing. The keep-side is the exact complement,
# so every entry ends up in exactly one of the two lists — nothing can be dropped.
_GIFTALL_MOVES = {"$and": [
    {"$eq": [{"$type": "$$it.char_id"}, "string"]},
    {"$ne": ["$$it.status", "market"]},
]}

def _giftall_tier(it):
    t = it.get("rarity_tier") or classify_rarity(it.get("rarity", ""))
    return t if t in RARITY_TIERS else None

def _giftall_movable(it):
    return isinstance(it, dict) and isinstance(it.get("char_id"), str) and it.get("status") != "market"

def _giftall_summarize(harem):
    """(movable count, Counter of tiers) — what a /gift all would move out of this harem right now."""
    items = [it for it in (harem or []) if _giftall_movable(it)]
    return len(items), Counter(_giftall_tier(it) for it in items)

def _giftall_tier_lines(tiers):
    lines, shown = [], 0
    for t in RARITY_TIERS:
        c = tiers.get(t, 0)
        if c:
            shown += c
            lines.append(f"{RARITY_EMOJI.get(t, RARITY_DEFAULT_EMOJI)} {RARITY_DISPLAY_NAME.get(t, t)} — <b>{c:,}</b>")
    other = sum(tiers.values()) - shown
    if other > 0:
        lines.append(f"❓ Other — <b>{other:,}</b>")
    return "\n".join(lines)

def _giftall_mention(uid, name):
    return f"<a href='tg://user?id={uid}'><b>{escape_html(clean_display_name(name))}</b></a>"

def _giftall_text(hold, status, vlt_left=None):
    """Final message — shared by the live tap and by recovery after a redeploy."""
    items = hold.get("items") or []
    n = len(items)
    s = _giftall_mention(hold.get("sender_id"), hold.get("sender_name"))
    r = _giftall_mention(hold.get("receiver_id"), hold.get("receiver_name"))
    fee = format_vlt_plain(hold.get("fee", GIFT_ALL_FEE_VLT))
    if status == "returned":
        return (
            f"↩️ <b>Gift All cancelled</b>\n\n"
            f"{r} can't receive gifts right now, so nothing was sent.\n"
            f"<blockquote>🃏 <b>{n:,}</b> card(s) are back in your harem\n💠 {fee} refunded</blockquote>"
        )
    tiers = Counter(_giftall_tier(it) for it in items)
    left = f"  ·  left <code>{format_vlt_plain(vlt_left)}</code>" if vlt_left is not None else ""
    return (
        f"<b>🎁 Gift All sent!</b>\n\n"
        f"{s} → {r}\n\n"
        f"<blockquote>🃏 <b>{n:,}</b> card(s) moved\n{_giftall_tier_lines(tiers)}</blockquote>\n"
        f"💠 Fee paid: <code>{fee}</code>{left}\n\n"
        f"Enjoy your cards ♡"
    )

async def _giftall_drop_caches(sender_id, receiver_id):
    """Both collections changed hands — forget cached boards / card ranks / cached profiles (they refresh on their own TTL anyway)."""
    try:
        _LEADERBOARD_TEXT_CACHE.clear()
        _LB_LOCAL.clear()
        _CARDRANK_LOCAL.clear()
        await redis_client.delete(f"user:{sender_id}", f"user:{receiver_id}")
    except Exception:
        pass

async def giftall_begin(sender_id, receiver_id, receiver_name, sender_name, tid, chat_id, msg_id):
    """STEP 1 — one atomic write on the sender's document: re-checks VIP, 💠 balance, 'no transfer already open' and 'has at least one movable card', then charges the
    fee and moves the cards into the hold. Returns the sender's document AFTER the write ({"gift_all_hold", "vlt_balance"}), or None if any condition failed
    (nothing was changed). Needs MongoDB 4.2+ (pipeline-style update) — on an older server the call raises BEFORE anything is changed."""
    now = time.time()
    return await users_catcher_col.find_one_and_update(
        {
            "user_id": sender_id,
            "premium_until": {"$gt": now},
            "vlt_balance": {"$gte": GIFT_ALL_FEE_VLT},
            "gift_all_hold": {"$exists": False},
            "harem": {"$elemMatch": {"char_id": {"$type": "string"}, "status": {"$ne": "market"}}},
            "$expr": {"$lte": [{"$size": {"$ifNull": ["$harem", []]}}, GIFT_ALL_MAX_CARDS]},
        },
        [
            {"$set": {
                "vlt_balance": {"$subtract": ["$vlt_balance", GIFT_ALL_FEE_VLT]},
                "gift_all_hold": {
                    "tid": tid, "sender_id": sender_id, "receiver_id": receiver_id,
                    "receiver_name": {"$literal": receiver_name}, "sender_name": {"$literal": sender_name},   # $literal: a name starting with "$" must not be read as a field path
                    "fee": GIFT_ALL_FEE_VLT, "started": now, "chat_id": chat_id, "msg_id": msg_id,
                    "items": {"$filter": {"input": "$harem", "as": "it", "cond": _GIFTALL_MOVES}},
                },
            }},
            {"$set": {"harem": {"$filter": {"input": "$harem", "as": "it", "cond": {"$not": [_GIFTALL_MOVES]}}}}},
        ],
        projection={"_id": 0, "gift_all_hold": 1, "vlt_balance": 1},
        return_document=ReturnDocument.AFTER,
    )

async def _giftall_return(sender_id, hold):
    """Rollback: ONE atomic write puts the held cards back in the harem, refunds the fee and removes the hold (matches only while the hold exists → safe to repeat)."""
    items = hold.get("items") or []
    res = await users_catcher_col.update_one(
        {"user_id": sender_id, "gift_all_hold.tid": hold["tid"]},
        [
            {"$set": {
                "harem": {"$concatArrays": [{"$ifNull": ["$harem", []]}, {"$ifNull": ["$gift_all_hold.items", []]}]},
                "vlt_balance": {"$add": [{"$ifNull": ["$vlt_balance", 0]}, {"$ifNull": ["$gift_all_hold.fee", 0]}]},
            }},
            {"$set": {"gift_all_hold": "$$REMOVE"}},
        ],
    )
    try:
        await gift_all_journal_col.delete_one({"_id": hold["tid"]})
    except Exception as e:
        print(f"gift all journal cleanup error: {e}")
    await _giftall_drop_caches(sender_id, hold.get("receiver_id"))
    return {"status": "returned", "count": len(items), "finalized": bool(res.matched_count)}

async def _giftall_settle(sender_id, hold, force_return=False):
    """STEPS 2 + 3 (or the rollback). Idempotent: any crash, repeat, or two workers running it at once ends in the same single outcome."""
    tid, receiver_id = hold["tid"], hold["receiver_id"]
    items = hold.get("items") or []
    n = len(items)

    already = await users_catcher_col.find_one({"user_id": receiver_id, "gift_all_received": tid}, {"_id": 1})
    if not already:
        if force_return or receiver_id == sender_id or is_gbanned(receiver_id)[0]:
            return await _giftall_return(sender_id, hold)
        # make sure the receiver's profile exists WITHOUT touching the guarded update below (an upsert there would try to re-create the profile on a repeat run)
        await users_catcher_col.update_one(
            {"user_id": receiver_id},
            {"$setOnInsert": {"user_id": receiver_id, "fullname": hold.get("receiver_name") or ""}},
            upsert=True,
        )
        stamp = time.time()
        await users_catcher_col.update_one(                                       # STEP 2 — same entry shape as a normal /gift
            {"user_id": receiver_id, "gift_all_received": {"$ne": tid}},
            {
                "$push": {
                    "harem": {"$each": [
                        {"char_id": it["char_id"], "caught_date": stamp, "rarity": it.get("rarity") or "Unknown", "status": "vault"}
                        for it in items
                    ]},
                    "gift_all_received": {"$each": [tid], "$slice": -100},
                },
                "$inc": {"total_caught": n, "total_gift_received": n},
            },
        )

    inc = {"total_gifted": n}                                                     # STEP 3 — counted like n normal gifts (/giftranks reads these counters)
    for t, c in Counter(_giftall_tier(it) for it in items).items():
        if t:
            inc[f"gifted_by_rarity.{t}"] = c
    unset = {"gift_all_hold": ""}
    if not is_owner_mode(sender_id):
        unset.update({"fav_card": "", "fav_note": ""})                            # every card they could have favourited just left (owner-mode favourites aren't tied to real copies)
    res = await users_catcher_col.update_one({"user_id": sender_id, "gift_all_hold.tid": tid}, {"$unset": unset, "$inc": inc})
    try:
        await gift_all_journal_col.delete_one({"_id": tid})
    except Exception as e:
        print(f"gift all journal cleanup error: {e}")
    await _giftall_drop_caches(sender_id, receiver_id)
    return {"status": "delivered", "count": n, "finalized": bool(res.matched_count)}

async def _giftall_notify(hold, res):
    """After a recovery: update the message the sender was looking at (or post a new one if it can't be edited)."""
    chat_id, msg_id = hold.get("chat_id"), hold.get("msg_id")
    if not chat_id:
        return
    text = _giftall_text(hold, res["status"])
    try:
        await bot1.edit_message(chat_id, msg_id, text, parse_mode='html', buttons=None)
    except Exception:
        try:
            await bot1.send_message(chat_id, text, parse_mode='html')
        except Exception as e:
            print(f"gift all notify error: {e}")

async def giftall_recover(min_age=30):
    """Finishes every interrupted /gift all that is at least `min_age` seconds old. Returns how many it settled."""
    now = time.time()
    settled = 0
    rows = await gift_all_journal_col.find({"started": {"$lte": now - min_age}}).to_list(length=200)
    for j in rows:
        tid, sender_id = j["_id"], j.get("sender_id")
        doc = await users_catcher_col.find_one({"user_id": sender_id, "gift_all_hold.tid": tid}, {"_id": 0, "gift_all_hold": 1})
        hold = (doc or {}).get("gift_all_hold")
        if not hold:
            await gift_all_journal_col.delete_one({"_id": tid})                   # finished earlier, or it never got as far as step 1 — nothing to do
            continue
        age = now - hold.get("started", now)
        try:
            res = await _giftall_settle(sender_id, hold)                          # always try to DELIVER first — however long the bot was down
        except Exception as e:
            print(f"gift all recovery error ({tid}): {e}")
            if age <= GIFT_ALL_GIVEUP_SECONDS:
                continue                                                          # keep retrying every minute
            try:                                                                  # it has been failing for over an hour — stop holding the player's cards hostage
                res = await _giftall_settle(sender_id, hold, force_return=True)
            except Exception as e2:
                print(f"gift all rollback error ({tid}): {e2}")
                continue
        settled += 1
        print(f"🎁 /gift all {tid}: recovered → {res['status']} ({res['count']} card(s), sender {sender_id})")
        await _giftall_notify(hold, res)
    return settled

async def giftall_recovery_loop():
    await asyncio.sleep(20)
    while True:
        try:
            await giftall_recover()
        except Exception as e:
            print(f"giftall_recovery_loop error: {e}")
        await asyncio.sleep(60)

async def _giftall_why_not(sender_id):
    """Why step 1 refused — read AFTER the fact, only to word the message."""
    doc = await users_catcher_col.find_one(
        {"user_id": sender_id}, {"_id": 0, "premium_until": 1, "vlt_balance": 1, "gift_all_hold": 1, "harem": 1}
    ) or {}
    if not is_vip_active(doc): return "vip"
    if doc.get("gift_all_hold"): return "busy"
    if (doc.get("vlt_balance") or 0) < GIFT_ALL_FEE_VLT: return "vlt"
    n, _ = _giftall_summarize(doc.get("harem"))
    if n == 0: return "empty"
    if n > GIFT_ALL_MAX_CARDS: return "toomany"
    return "changed"

_GIFTALL_REFUSALS = {
    "vip": "👑 <b>/gift all is for VIP members only.</b>\n<i>Get VIP with /buy → 👑 VIP Mode.</i>",
    "busy": "⏳ <b>A previous /gift all is still being finished.</b>\n<i>Give it a minute, then try again.</i>",
    "vlt": f"❌ <b>Not enough 💠 VLT</b> — /gift all costs <code>{GIFT_ALL_FEE_VLT:,} 💠</code>.",
    "empty": "📭 <b>You have no cards to gift.</b>\n<i>Cards listed on the market stay where they are.</i>",
    "toomany": f"❌ <b>Too many cards for one transfer</b> (max {GIFT_ALL_MAX_CARDS:,}).",
    "changed": "⚠️ <b>Your harem changed while you were deciding.</b>\n<i>Nothing was taken — run /gift all again.</i>",
}

@bot1.on(events.NewMessage(pattern=own_pattern(r'(?is)^[/.]gift(?:@\w+)?\s+all(?:\s.*)?$', 'bot1')))
async def giftall_prompt(event):
    if is_duplicate_event(event):
        return
    sender_id = event.sender_id
    if sender_id == OWNER_ID:
        return await event.reply("👑 <b>Owner:</b> use <code>/mgift</code> — your vault is unlimited, there is no harem to hand over.", parse_mode='html')
    doc = await users_catcher_col.find_one(
        {"user_id": sender_id}, {"_id": 0, "premium_until": 1, "vlt_balance": 1, "gift_all_hold": 1, "harem": 1}
    ) or {}
    if not is_vip_active(doc):
        return await event.reply(_GIFTALL_REFUSALS["vip"], parse_mode='html')
    if doc.get("gift_all_hold"):
        return await event.reply(_GIFTALL_REFUSALS["busy"], parse_mode='html')

    receiver_id, err = await _resolve_gift_receiver(event)        # reply required · not yourself · not a bot
    if err:
        return await event.reply(err + "\n<i>Usage: reply to the player's message with</i> <code>/gift all</code>", parse_mode='html')
    if receiver_id <= 0:
        return await event.reply("❌ <b>Reply to a real player's message.</b>", parse_mode='html')
    _bot_name = await own_bot_display_name(receiver_id)
    if _bot_name:
        return await event.reply(_bot_card_block_text(_bot_name), parse_mode='html')
    try:
        _r_ent = await (await event.get_reply_message()).get_sender()
        if getattr(_r_ent, "bot", False):
            return await event.reply("❌ <b>Can't gift to a bot.</b>", parse_mode='html')
    except Exception:
        pass
    if is_gbanned(receiver_id)[0]:
        return await event.reply("🚫 <b>That user is globally banned — they can't receive gifts right now.</b>", parse_mode='html')

    n, tiers = _giftall_summarize(doc.get("harem"))
    if n == 0:
        return await event.reply(_GIFTALL_REFUSALS["empty"], parse_mode='html')
    if n > GIFT_ALL_MAX_CARDS:
        return await event.reply(_GIFTALL_REFUSALS["toomany"], parse_mode='html')
    vlt = doc.get("vlt_balance") or 0
    if vlt < GIFT_ALL_FEE_VLT:
        return await event.reply(
            f"{_GIFTALL_REFUSALS['vlt']}\n<i>You have <code>{format_vlt_plain(vlt)}</code>.</i>", parse_mode='html'
        )

    r_mention = await get_html_mention(event, receiver_id)
    r_name = await get_plain_name(event, receiver_id)
    s_name = await get_plain_name(event, sender_id)
    now = time.time()
    for k in [k for k, v in _giftall_pending.items() if now - v["ts"] > GIFT_ALL_PENDING_TTL]:
        _giftall_pending.pop(k, None)
    if len(_giftall_pending) > 300:                                # bound memory: drop the oldest
        for k in sorted(_giftall_pending, key=lambda k: _giftall_pending[k]["ts"])[:len(_giftall_pending) - 300]:
            _giftall_pending.pop(k, None)
    token = secrets.token_hex(4)
    _giftall_pending[token] = {"sender_id": sender_id, "receiver_id": receiver_id, "receiver_name": r_name, "sender_name": s_name, "ts": now}

    await event.reply(
        f"<b>🎁 Gift ALL — Confirmation</b>\n\n"
        f"📤 Your <b>whole harem</b> → {r_mention}\n\n"
        f"<blockquote>🃏 <b>{n:,}</b> card(s)\n{_giftall_tier_lines(tiers)}</blockquote>\n"
        f"💠 <b>Fee:</b> <code>{format_vlt_plain(GIFT_ALL_FEE_VLT)}</code>  ·  you have <code>{format_vlt_plain(vlt)}</code>\n\n"
        f"⚠️ <b>Every card you hold at the moment you confirm moves — it can't be undone.</b>\n"
        f"<i>Cards listed on the market and 🧣 Exclusive Artwork stay with you.</i>",
        parse_mode='html',
        buttons=[[
            colored_button(f"✅ Send all {n:,}", f"giftall_ok_{token}", color="danger"),
            Button.inline("❌ Cancel", data=f"giftall_no_{token}"),
        ]],
    )

@bot1.on(events.CallbackQuery(pattern=r'^giftall_(ok|no)_([0-9a-f]{8})$'))
async def giftall_confirm_cb(event):
    action = event.pattern_match.group(1)
    token = event.pattern_match.group(2)
    if isinstance(action, bytes): action = action.decode('utf-8')
    if isinstance(token, bytes): token = token.decode('utf-8')
    pending = _giftall_pending.get(token)
    if pending and event.sender_id != pending["sender_id"]:
        return await event.answer("❌ This action is not for you!", alert=True)     # someone else's button — leave their preview alone
    pending = _giftall_pending.pop(token, None)                                    # no await between the check and the pop: a double-tap can never get the same preview twice
    if not pending or time.time() - pending["ts"] > GIFT_ALL_PENDING_TTL:
        return await event.answer("⌛ Expired — run /gift all again.", alert=True)
    if action == "no":
        await event.answer("Cancelled.")
        return await event.edit("❌ <b>Gift All cancelled</b> — nothing was sent or charged.", parse_mode='html', buttons=None)

    sender_id, receiver_id = pending["sender_id"], pending["receiver_id"]
    if sender_id in _giftall_inflight:
        return await event.answer("⏳ Already processing...", alert=False)
    if is_gbanned(receiver_id)[0]:
        await event.answer("Recipient is globally banned.", alert=True)
        return await event.edit("🚫 <b>That user is globally banned — this gift can't go through.</b>", parse_mode='html', buttons=None)

    _giftall_inflight.add(sender_id)
    began = False
    try:
        await event.answer("⏳ Sending...")
        try:
            await event.edit("⏳ <b>Moving your harem…</b>\n<i>Please wait — don't tap anything.</i>", parse_mode='html', buttons=None)
        except Exception:
            pass
        tid = secrets.token_hex(8)
        await gift_all_journal_col.insert_one({"_id": tid, "sender_id": sender_id, "receiver_id": receiver_id, "started": time.time()})
        after = await giftall_begin(sender_id, receiver_id, pending["receiver_name"], pending["sender_name"], tid, event.chat_id, event.message_id)
        if after is None:                                                          # a condition failed at the last moment — nothing was changed
            await gift_all_journal_col.delete_one({"_id": tid})
            why = await _giftall_why_not(sender_id)
            return await event.edit(_GIFTALL_REFUSALS.get(why, _GIFTALL_REFUSALS["changed"]), parse_mode='html', buttons=None)
        began = True
        hold = after["gift_all_hold"]
        res = await _giftall_settle(sender_id, hold)
        await event.edit(_giftall_text(hold, res["status"], vlt_left=after.get("vlt_balance")), parse_mode='html', buttons=None)
    except Exception as e:
        print(f"giftall_confirm_cb error (began={began}): {type(e).__name__}: {e}")
        await report_system_error("gift all", e)
        try:
            if began:
                await event.edit(
                    "⚠️ <b>Something interrupted the transfer.</b>\n"
                    "<i>Your cards are safe — it finishes (or is rolled back, fee refunded) automatically within a couple of minutes.</i>",
                    parse_mode='html', buttons=None)
            else:
                await event.edit("❌ <b>Couldn't start the transfer</b> — nothing was taken. Please try again.", parse_mode='html', buttons=None)
        except Exception:
            pass
    finally:
        _giftall_inflight.discard(sender_id)

# ==========================================
# 📦 /mgift — MASS GIFT (Owner Only, 2026-11)
# ==========================================
_MGIFT_ALL_RE = re.compile(r'^all$', re.IGNORECASE)
_MGIFT_RARITY_RE = re.compile(r'^no\.?([1-9])(?:\s+event\s+(\d+))?$', re.IGNORECASE)
_MGIFT_EVENT_RE = re.compile(r'^event\s+(\d+)$', re.IGNORECASE)
_MGIFT_FORCE_RE = re.compile(r'\s+force\s*$', re.IGNORECASE)
MGIFT_PENDING_TTL = 300
MGIFT_CHUNK = 500              # cards written per Mongo round trip
_mgift_pending = {}            # token -> {...}

MGIFT_USAGE = (
    "📦 <b>MASS GIFT — /mgift (Owner Only)</b>\n\n"
    "<i>Receiver ရဲ့ message ကို Reply လုပ်ပြီး:</i>\n"
    "<code>/mgift all</code> — receiver မပိုင်သေးတဲ့ ကဒ်အားလုံး (R1-9)\n"
    "<code>/mgift all force</code> — ကဒ်အားလုံး (ပိုင်ပြီးသားတွေပါ)\n"
    "<code>/mgift no3</code> — Rarity No.3 တစ်ခုလုံး\n"
    "<code>/mgift event 7</code> — Event 7 တစ်ခုလုံး\n"
    "<code>/mgift no1 event 3</code> — No.1 + Event 3\n\n"
    "⚠️ <b>Default:</b> receiver မှာ ≥1x ရှိပြီးသား ကဒ်ကို ကျော် (fill-collection)\n"
    "🛡️ အဆုံးမှာ <code>force</code> ထည့်ရင် အားလုံးပေး\n"
    "🚫 Exclusive Artwork (🧣 EX…) အမြဲ ဖယ် · Rarity No.1-9 ပဲ\n"
    "📌 Preview ပြီး ✅ နှိပ်မှ အမှန်ပေးမယ်"
)


def _parse_mgift_arg(arg):
    """Returns (rarity_filter, event_filter, force, error)."""
    arg = (arg or "").strip()
    force = False
    if _MGIFT_FORCE_RE.search(arg):
        force = True
        arg = _MGIFT_FORCE_RE.sub("", arg).strip()
    if not arg:
        return None, None, force, "filter needed"
    if _MGIFT_ALL_RE.match(arg):
        return None, None, force, None
    m = _MGIFT_RARITY_RE.match(arg)
    if m:
        rf = RARITY_TIERS[int(m.group(1)) - 1]
        ef = int(m.group(2)) if m.group(2) else None
        return rf, ef, force, None
    m = _MGIFT_EVENT_RE.match(arg)
    if m:
        return None, int(m.group(1)), force, None
    return None, None, force, "invalid"


def _mgift_event_cond(ev):
    """Same rule as filter_items_by_event / /hmode: ULTRA event KINDS (1-8) live on ULTRA cards only (event_no);
    custom events (9+) are stored as custom_event_no on every other rarity."""
    if ev in EVENT_TYPES:
        return {"rarity_tier": RARITY_TIERS[0], "event_no": ev}
    return {"custom_event_no": ev}


def _mgift_purge_expired():
    now = time.time()
    for k in [k for k, v in _mgift_pending.items() if now - v["ts"] > MGIFT_PENDING_TTL]:
        _mgift_pending.pop(k, None)


@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]mgift(?:@\w+)?(?:\s+([\s\S]+))?$', 'bot1')))
async def mgift_handler(event):
    if event.sender_id != OWNER_ID:
        return
    if is_duplicate_event(event):
        return

    arg = (event.pattern_match.group(1) or "").strip()
    if not arg:
        return await event.reply(MGIFT_USAGE, parse_mode='html')

    rarity_filter, event_filter, force, err = _parse_mgift_arg(arg)
    if err:
        return await event.reply(MGIFT_USAGE, parse_mode='html')

    if event_filter is not None and event_filter not in EVENT_TYPES and event_filter not in _CUSTOM_EVENTS:
        return await event.reply(f"❌ Event #{event_filter} မရှိပါ။", parse_mode='html')

    # Event 1-8 are ULTRA kinds (no1 only); Event 9+ are custom events (no2-no9 only) — a mixed pair can never match.
    if rarity_filter and event_filter is not None:
        if (event_filter in EVENT_TYPES) != (rarity_filter == RARITY_TIERS[0]):
            return await event.reply(
                f"❌ <b>ဒီ ပေါင်းစပ်မှု မရပါ။</b>\n"
                f"<i>Event 1-{len(EVENT_TYPES)} က <code>no1</code> (ULTRA) အတွက်ပဲ၊ "
                f"Event {CUSTOM_EVENT_FIRST_NO}+ က <code>no2</code>-<code>no9</code> အတွက်ပဲ။</i>",
                parse_mode='html'
            )

    if not event.is_reply:
        return await event.reply("❌ Receiver ကို Reply လုပ်ပြီး ရိုက်ပါ။", parse_mode='html')
    reply_msg = await event.get_reply_message()
    if not reply_msg or not reply_msg.sender_id:
        return await event.reply("❌ Receiver ကို မသိနိုင်ပါ။", parse_mode='html')
    receiver_id = reply_msg.sender_id

    if receiver_id == OWNER_ID or receiver_id in bot_ids:
        return await event.reply("❌ ဒီ user ကို ပေးလို့ မရပါ။", parse_mode='html')
    if is_gbanned(receiver_id)[0]:
        return await event.reply("🚫 Receiver က gban ခံထားရပါတယ်။", parse_mode='html')

    # ---- 1. Matching characters. Exclusive Artwork lives in exclusive_cards_col (never here) and is double-checked
    #         with exl_parse_id; anything whose tier is not one of the 9 RARITY_TIERS is dropped. ----
    conds = []
    if rarity_filter:
        # `$exists: False` keeps cards from before the rarity_tier backfill; the exact tier is re-checked below.
        conds.append({"$or": [{"rarity_tier": rarity_filter}, {"rarity_tier": {"$exists": False}}]})
    if event_filter is not None:
        conds.append(_mgift_event_cond(event_filter))
    query = {"$and": conds} if conds else {}

    matching = []
    async for cd in characters_base_col.find(
        query, {"char_id": 1, "name": 1, "rarity": 1, "rarity_tier": 1, "_id": 0}
    ):
        cid = cd.get("char_id")
        if not cid or exl_parse_id(cid):
            continue
        tier = cd.get("rarity_tier") or classify_rarity(cd.get("rarity", ""))
        if tier not in RARITY_TIERS:
            continue
        if rarity_filter and tier != rarity_filter:
            continue
        cd["_tier"] = tier
        matching.append(cd)

    if not matching:
        return await event.reply("📭 ဒီ filter နဲ့ ကိုက်ညီတဲ့ ကဒ် မရှိပါဘူး။", parse_mode='html')

    # ---- 2. Default (no "force"): skip cards the receiver already owns at least once ----
    skip_count = 0
    if force:
        gift_list = matching
    else:
        r_doc = await users_catcher_col.find_one(
            {"user_id": receiver_id}, {"harem.char_id": 1, "_id": 0}
        )
        owned = {it.get("char_id") for it in ((r_doc or {}).get("harem") or [])
                 if isinstance(it, dict) and it.get("char_id")}
        gift_list = []
        for cd in matching:
            if cd["char_id"] in owned:
                skip_count += 1
            else:
                gift_list.append(cd)

    if not gift_list:
        return await event.reply(
            f"📭 <b>Nothing new to gift.</b>\n<i>Receiver already owns all {len(matching)} matching card(s). "
            f"Try </i><code>/mgift {escape_html(' '.join(arg.split()))} force</code><i> to gift them anyway.</i>",
            parse_mode='html'
        )

    # ---- 3. Preview ----
    tier_sum = Counter(cd["_tier"] for cd in gift_list)
    summary = "\n".join(
        f"{RARITY_EMOJI.get(t, RARITY_DEFAULT_EMOJI)} {RARITY_DISPLAY_NAME.get(t, t)} — <b>{tier_sum[t]}</b>"
        for t in RARITY_TIERS if tier_sum.get(t)
    )
    sample = "\n".join(
        f"{RARITY_EMOJI.get(cd['_tier'], RARITY_DEFAULT_EMOJI)} "
        f"{escape_html(str(cd.get('name', '?'))[:30])} <code>{display_char_id(cd['char_id'])}</code>"
        for cd in sorted(gift_list, key=lambda x: -rarity_rank_value(x.get("rarity", "")))[:15]
    )
    if len(gift_list) > 15:
        sample += f"\n<i>… +{len(gift_list) - 15} more</i>"

    filter_desc = []
    if rarity_filter:
        filter_desc.append(f"{RARITY_EMOJI.get(rarity_filter, '')} {RARITY_DISPLAY_NAME.get(rarity_filter, rarity_filter)}")
    if event_filter is not None:
        filter_desc.append(event_filter_label(event_filter) or f"Event #{event_filter}")
    if not filter_desc:
        filter_desc.append("All (R1-9)")

    r_mention = await get_html_mention(event, receiver_id)
    r_name = await get_plain_name(event, receiver_id)
    warn = (f"\n\n⚠️ <b>BIG:</b> <code>{len(gift_list)}</code> cards — ✅ မနှိပ်ခင် သေချာစစ်ပါ။"
            if len(gift_list) >= 500 else "")
    skip_note = f"\n⏭️ <b>Skipped (receiver owns):</b> <code>{skip_count}</code>" if skip_count else ""
    mode_line = "🔁 <b>Force mode</b> — dupes included" if force else "🎯 <b>Fill mode</b> — new cards only"

    _mgift_purge_expired()
    token = secrets.token_hex(4)
    _mgift_pending[token] = {
        "sender_id": OWNER_ID, "receiver_id": receiver_id, "receiver_name": r_name,
        "cards": [(cd["char_id"], cd.get("rarity") or "Unknown", cd["_tier"]) for cd in gift_list],
        "ts": time.time(),
    }

    await event.reply(
        f"📦 <b>MASS GIFT — Preview</b>\n"
        f"<i>{mode_line} · Filter: {' · '.join(filter_desc)}</i>\n\n"
        f"👤 <b>To:</b> {r_mention}\n"
        f"🎁 <b>Total:</b> <code>{len(gift_list)}</code> card(s){skip_note}\n\n"
        f"<b>By rarity:</b>\n{summary}\n\n"
        f"<b>Sample:</b>\n{sample}"
        f"{warn}\n\n"
        f"<i>Owner's unlimited vault — nothing is removed from your side.</i>",
        parse_mode='html',
        buttons=[[
            colored_button(f"✅ Gift {len(gift_list)}", f"mgift_ok_{token}", color="success"),
            Button.inline("❌ Cancel", data=f"mgift_no_{token}"),
        ]]
    )


@bot1.on(events.CallbackQuery(pattern=r'^mgift_(ok|no)_([0-9a-f]{8})$'))
async def mgift_callback(event):
    if event.sender_id != OWNER_ID:
        return await event.answer("Owner only.", alert=True)
    action = event.pattern_match.group(1)
    token = event.pattern_match.group(2)
    if isinstance(action, bytes): action = action.decode('utf-8')
    if isinstance(token, bytes): token = token.decode('utf-8')

    # pop() is synchronous, so a double-tap can never get the same pending twice — the 2nd tap just sees "used".
    pending = _mgift_pending.pop(token, None)
    if not pending:
        return await event.answer("⌛ Expired or already used.", alert=True)
    if time.time() - pending["ts"] > MGIFT_PENDING_TTL:
        return await event.answer("⌛ Expired — /mgift ကို ပြန်ရိုက်ပါ။", alert=True)

    if action == "no":
        await event.answer("Cancelled.")
        return await event.edit("❌ <b>Mass gift cancelled.</b>", parse_mode='html', buttons=None)

    await event.answer("⏳ Processing...")
    try:
        await event.edit(f"⏳ <b>Gifting {len(pending['cards'])} card(s)…</b>", parse_mode='html', buttons=None)
    except Exception:
        pass
    ok, msg = await _execute_mgift_owner(
        pending["sender_id"], pending["receiver_id"], pending["cards"], pending.get("receiver_name") or f"User {pending['receiver_id']}"
    )
    await event.edit(msg, parse_mode='html', buttons=None)


async def _execute_mgift_owner(sender_id, receiver_id, cards, receiver_name):
    """cards = [(char_id, rarity_str, tier)]. Owner gifts 1 copy each from the unlimited vault (no harem removal).
    Written MGIFT_CHUNK cards at a time, each chunk fully booked (harem + counters + spawn_count + history) before the
    next, so a failure part-way leaves exact numbers instead of half-updated ones. Returns (ok, message_html)."""
    total = len(cards)
    if total <= 0:
        return False, "❌ Nothing to gift."

    now = time.time()
    delivered = 0
    try:
        for i in range(0, total, MGIFT_CHUNK):
            chunk = cards[i:i + MGIFT_CHUNK]
            n = len(chunk)

            # 1) Receiver — one atomic update: new harem entries + counters (same entry shape as /gift's confirm tap)
            await users_catcher_col.update_one(
                {"user_id": receiver_id},
                {
                    "$push": {"harem": {"$each": [
                        {"char_id": cid, "caught_date": now, "rarity": rarity, "status": "vault"}
                        for cid, rarity, _ in chunk
                    ]}},
                    "$inc": {"total_caught": n, "total_gift_received": n},
                    "$set": {"fullname": receiver_name},
                },
                upsert=True
            )
            delivered += n

            # 2) Sender (owner) gift stats — the owner's real harem is untouched
            try:
                sender_inc = {"total_gifted": n}
                for tier, cnt in Counter(t for _, _, t in chunk).items():
                    sender_inc[f"gifted_by_rarity.{tier}"] = cnt
                await users_catcher_col.update_one({"user_id": sender_id}, {"$inc": sender_inc}, upsert=True)
            except Exception as e:
                print(f"mgift sender stats error: {e}")

            # 3) "Global Catches" counter, +1 per copy given (what /gift does for the owner)
            try:
                spawn_inc = Counter(cid for cid, _, _ in chunk)
                await characters_base_col.bulk_write(
                    [UpdateOne({"char_id": cid}, {"$inc": {"spawn_count": cnt}}) for cid, cnt in spawn_inc.items()],
                    ordered=False
                )
            except Exception as e:
                print(f"mgift spawn_count bulk error: {e}")

            # 4) 🩹 REMOVED (2026-11, per owner request): no gift_history rows any more (/giftranks reads the counters above, never those rows).
    except Exception as e:
        print(f"mgift execute error after {delivered}/{total}: {e}")
        return False, (
            f"⚠️ <b>Mass gift stopped part-way.</b>\n\n"
            f"🎁 Delivered: <b>{delivered}</b> / {total} card(s)\n"
            f"<i>Everything delivered so far is fully recorded. Run /mgift again — fill mode skips what they already got.</i>"
        )

    return True, (
        f"✅ <b>Mass gift sent!</b>\n\n"
        f"🎁 <b>{delivered}</b> card(s) → {escape_html(receiver_name)}\n"
        f"<i>Owner vault unaffected.</i>"
    )


# ==========================================
# 🎁 /grant — GIFT MANY CARDS BY ID, WITH A CARD-BY-CARD PREVIEW (Owner Only, 2026-11)
# ==========================================
GRANT_MAX_CARDS = 300
GRANT_PENDING_TTL = 900            # seconds of INACTIVITY: every Prev/Next tap pushes the expiry back, so a long list never times out while it is being reviewed
_grant_pending = {}                # token -> {receiver_id, receiver_name, receiver_mention, cards, skip_note, ts}
_GRANT_SPLIT_RE = re.compile(r'[\s,;]+')
_GRANT_ID_RE = re.compile(r'(?:BOD)?(\d{1,9})')

GRANT_USAGE = (
    "🎁 <b>GRANT — /grant (Owner Only)</b>\n\n"
    "<i>ဝယ်သူရဲ့ message ကို Reply လုပ်ပြီး ကဒ် ID တွေကို တစ်ခါတည်း ပေး:</i>\n"
    "<code>/grant 12 345 678 9012</code>\n\n"
    "• ID တွေကို space / comma / စာကြောင်းခွဲ ရေးလို့ရ\n"
    "• Reply မလုပ်ရင် <code>/grant @username 12 345 678</code>\n"
    f"• တစ်ခါမှာ ကဒ် {GRANT_MAX_CARDS} ခုအထိ · တူတဲ့ ID ထပ်ရင် တစ်ခုပဲ ယူ\n"
    "• Preview မှာ ⬅️ Prev / ➡️ Next နဲ့ ကဒ်တစ်ခုချင်း ကြည့်ပြီး ✅ နှိပ်မှ အမှန်ပေးမယ်\n"
    "🚫 Exclusive (EX…) မပါ — <code>/gift EX1</code> သုံးပါ\n"
    "📦 Filter နဲ့ အများကြီးပေးချင်ရင် <code>/mgift</code>"
)

def _grant_parse_args(raw):
    """/grant arguments -> (username, ids, dup_count, ex_ids, junk).
      username   an optional '@name' — only the FIRST token may be one; it names the receiver when the command is not a reply
      ids        canonical BOD ids, in the order typed, each once (0071 / 71 / BOD71 / #71 are the same card)
      dup_count  how many repeated ids were dropped        ex_ids  Exclusive Artwork ids (EX…) — never granted here
      junk       tokens that are not a card id at all (one of these refuses the whole command)"""
    tokens = [t for t in _GRANT_SPLIT_RE.split(raw or "") if t]
    username = None
    if tokens and tokens[0].startswith("@") and len(tokens[0]) > 1:
        username = tokens.pop(0)
    ids, seen, dup_count, ex_ids, junk = [], set(), 0, [], []
    for tok in tokens:
        t = tok.lstrip("#").strip()
        ex = exl_parse_id(t)
        if ex:
            if ex not in ex_ids:
                ex_ids.append(ex)
            continue
        m = _GRANT_ID_RE.fullmatch(t.upper())
        if not m:
            junk.append(tok)
            continue
        cid = f"BOD{int(m.group(1))}"
        if cid in seen:
            dup_count += 1
            continue
        seen.add(cid)
        ids.append(cid)
    return username, ids, dup_count, ex_ids, junk

async def _grant_lookup(ids):
    """{char_id: card doc} for the ids that exist — ONE query."""
    found = {}
    async for cd in characters_base_col.find(
        {"char_id": {"$in": ids}},
        {"_id": 0, "char_id": 1, "name": 1, "rarity": 1, "rarity_tier": 1, "artist": 1, "storage_msg_id": 1}
    ):
        if cd.get("char_id"):
            found[cd["char_id"]] = cd
    return found

def _grant_skip_note(missing, ex_ids, dup_count):
    parts = []
    if missing:
        shown = ", ".join(f"<code>{display_char_id(c)}</code>" for c in missing[:8])
        parts.append(f"❓ Not found: {shown}" + (f" +{len(missing) - 8}" if len(missing) > 8 else ""))
    if ex_ids:
        shown = ", ".join(f"<code>{e}</code>" for e in ex_ids[:5])
        parts.append(f"🧣 Exclusive — use /gift: {shown}")
    if dup_count:
        parts.append(f"🔁 Repeated ids ignored: {dup_count}")
    return "\n".join(parts)

def _grant_purge():
    now = time.time()
    for k in [k for k, v in _grant_pending.items() if now - v["ts"] > GRANT_PENDING_TTL]:
        _grant_pending.pop(k, None)
    if len(_grant_pending) > 40:                              # bound memory: drop the oldest
        for k in sorted(_grant_pending, key=lambda k: _grant_pending[k]["ts"])[:len(_grant_pending) - 40]:
            _grant_pending.pop(k, None)

def _grant_caption(p, idx):
    """One card's page. Always names the receiver and the total, so the owner can never confirm for the wrong person or the wrong amount."""
    c = p["cards"][idx]
    total = len(p["cards"])
    emoji = RARITY_EMOJI.get(c["tier"], RARITY_DEFAULT_EMOJI)
    body = (f"{emoji} <b>{escape_html(c['name'][:60])}</b>\n"
            f"🆔 <code>{display_char_id(c['char_id'])}</code>\n"
            f"🦋 {_rarity_label_plain(c['rarity'])}")
    art = artist_line(c, suffix="")
    if art:
        body += "\n" + art
    note = f"\n\n⚠️ <b>Skipped</b>\n{p['skip_note']}" if p["skip_note"] else ""
    return (f"🎁 <b>{small_caps_full('grant')}</b> — <code>{idx + 1}/{total}</code>\n"
            f"👤 To: {p['receiver_mention']}\n"
            f"<blockquote>{body}</blockquote>\n"
            f"📦 Total <b>{total}</b> card(s){note}")

def _grant_buttons(token, idx, total):
    rows = []
    if total > 1:
        rows.append([Button.inline("⬅️ Prev", data=f"grant_nav_{token}_{(idx - 1) % total}"),
                     Button.inline("➡️ Next", data=f"grant_nav_{token}_{(idx + 1) % total}")])
    rows.append([colored_button(f"✅ Gift all {total}" if total > 1 else "✅ Gift", f"grant_ok_{token}", color="success"),
                 Button.inline("❌ Cancel", data=f"grant_no_{token}")])
    return rows

async def _grant_send_first(event, token):
    """The first page, as a reply to the owner's command: the card's picture when it has one (storage_msg_id — a card WITHOUT one must never be handed to the
    media helper, Telethon would read ids=None as 'the latest message' and show somebody else's picture), otherwise just the text."""
    p = _grant_pending[token]
    caption, buttons = _grant_caption(p, 0), _grant_buttons(token, 0, len(p["cards"]))
    card = p["cards"][0]
    if card.get("storage_msg_id"):
        async def _send(media):
            return await event.reply(caption, file=media, buttons=buttons, parse_mode='html')
        try:
            if await send_with_char_media(card["char_id"], card["storage_msg_id"], _send) is not None:
                return
        except Exception as e:
            print(f"grant first page media error ({card['char_id']}): {e}")
    await event.reply(caption, buttons=buttons, parse_mode='html')

async def _grant_edit_page(event, token, idx):
    """Flip to card `idx` by editing the same message (picture and all) — same technique as /show. If Telegram refuses the in-place swap (e.g. text-only <-> picture)
    or the card has no picture, the message is deleted and sent again fresh; the buttons carry the same token, so nothing is lost."""
    p = _grant_pending.get(token)
    card = p["cards"][idx]
    caption, buttons = _grant_caption(p, idx), _grant_buttons(token, idx, len(p["cards"]))
    if card.get("storage_msg_id"):
        async def _edit(media):
            return await event.edit(caption, file=media, buttons=buttons, parse_mode='html')
        try:
            if await send_with_char_media(card["char_id"], card["storage_msg_id"], _edit) is not None:
                return await event.answer()
        except errors.MessageNotModifiedError:
            return await event.answer()
        except Exception:
            pass
    try:
        await event.delete()
    except Exception:
        pass
    sent = None
    if card.get("storage_msg_id"):
        async def _resend(media):
            return await bot1.send_message(event.chat_id, caption, file=media, buttons=buttons, parse_mode='html')
        try:
            sent = await send_with_char_media(card["char_id"], card["storage_msg_id"], _resend)
        except Exception as e:
            print(f"grant page resend media error ({card['char_id']}): {e}")
    if sent is None:
        await bot1.send_message(event.chat_id, caption, buttons=buttons, parse_mode='html')
    await event.answer()

async def _grant_resolve_receiver(event, username):
    """-> (receiver_id, error_html_or_None). An @username typed in the command wins over the message that was replied to."""
    rid, ent = None, None
    if username:
        try:
            ent = await bot1.get_entity(username)
        except Exception:
            return None, f"❌ <code>{escape_html(username)}</code> ကို ရှာမတွေ့ပါ — ဝယ်သူရဲ့ message ကို Reply လုပ်ပြီး ပေးကြည့်ပါ။"
        if not isinstance(ent, types.User):
            return None, "❌ ဒါ user မဟုတ်ပါ။"
        rid = ent.id
    elif event.is_reply:
        reply_msg = await event.get_reply_message()
        rid = reply_msg.sender_id if reply_msg else None
        if rid:
            try:
                ent = await reply_msg.get_sender()
            except Exception:
                ent = None
    else:
        return None, "❌ ဝယ်သူရဲ့ message ကို <b>Reply</b> လုပ်ပါ (ဒါမှမဟုတ် <code>/grant @username 12 345</code>)။"
    if not rid:
        return None, "❌ Receiver ကို မသိနိုင်ပါ။"
    if rid == OWNER_ID:
        return None, "❌ ဒီ user ကို ပေးလို့ မရပါ။"
    _bot_name = await own_bot_display_name(rid)
    if _bot_name:
        return None, _bot_card_block_text(_bot_name)
    if getattr(ent, "bot", False):
        return None, "❌ Bot ကို ကဒ် ပေးလို့ မရပါ။"
    if is_gbanned(rid)[0]:
        return None, "🚫 Receiver က gban ခံထားရပါတယ်။"
    return rid, None

@bot1.on(events.NewMessage(pattern=own_pattern(r'(?i)^[/.]grant(?:@\w+)?(?:\s+([\s\S]+))?$', 'bot1')))
async def grant_handler(event):
    if event.sender_id != OWNER_ID:
        return
    if is_duplicate_event(event):
        return
    raw = (event.pattern_match.group(1) or "").strip()
    if not raw:
        return await event.reply(GRANT_USAGE, parse_mode='html')

    username, ids, dup_count, ex_ids, junk = _grant_parse_args(raw)
    if junk:
        shown = ", ".join(f"<code>{escape_html(j[:20])}</code>" for j in junk[:6])
        return await event.reply(
            f"❌ <b>ID မဟုတ်တာတွေ ပါနေတယ်:</b> {shown}\n<i>ကဒ် ID ကို ဂဏန်းနဲ့ပဲ ရေးပါ (space / comma ခြား)။ ဘာမှ မပေးရသေးပါဘူး။</i>", parse_mode='html')
    if not ids:
        if ex_ids:
            return await event.reply("🧣 Exclusive (EX…) ကဒ်ကို ဒီမှာ မပေးနိုင်ပါ — <code>/gift EX1</code> ကို သုံးပါ။", parse_mode='html')
        return await event.reply(GRANT_USAGE, parse_mode='html')
    if len(ids) > GRANT_MAX_CARDS:
        return await event.reply(
            f"❌ တစ်ခါမှာ ကဒ် <b>{GRANT_MAX_CARDS}</b> ခုအထိပဲ ပေးလို့ရတယ် — အခု <b>{len(ids)}</b> ခု ပါနေတယ်။ နှစ်ခါခွဲပါ။", parse_mode='html')

    receiver_id, err = await _grant_resolve_receiver(event, username)
    if err:
        return await event.reply(err, parse_mode='html')

    found = await _grant_lookup(ids)
    cards, missing = [], []
    for cid in ids:                                           # typed order is kept — it is the order the owner will flip through
        cd = found.get(cid)
        if not cd:
            missing.append(cid)
            continue
        rarity = cd.get("rarity") or "Unknown"
        cards.append({"char_id": cid, "name": str(cd.get("name") or "?"), "rarity": rarity,
                      "tier": cd.get("rarity_tier") or classify_rarity(rarity),
                      "artist": cd.get("artist"), "storage_msg_id": cd.get("storage_msg_id")})
    if not cards:
        return await event.reply(f"📭 <b>ပေးစရာ ကဒ် မရှိပါ။</b>\n{_grant_skip_note(missing, ex_ids, dup_count)}", parse_mode='html')

    _grant_purge()
    token = secrets.token_hex(4)
    _grant_pending[token] = {
        "receiver_id": receiver_id,
        "receiver_name": await get_plain_name(event, receiver_id),
        "receiver_mention": await get_html_mention(event, receiver_id),
        "cards": cards,
        "skip_note": _grant_skip_note(missing, ex_ids, dup_count),
        "ts": time.time(),
    }
    await _grant_send_first(event, token)

def _grant_receipt(p):
    """The message that replaces the preview once the cards are given: who, how many, and the list (cut so it always fits a picture caption)."""
    lines, budget = [], 760
    for c in p["cards"]:
        cost = len(c["name"][:24]) + 8
        if budget < cost:
            break
        budget -= cost
        lines.append(f"{RARITY_EMOJI.get(c['tier'], RARITY_DEFAULT_EMOJI)} {escape_html(c['name'][:24])} <code>{display_char_id(c['char_id'])}</code>")
    more = len(p["cards"]) - len(lines)
    return (f"✅ <b>Granted!</b>\n"
            f"🎁 <b>{len(p['cards'])}</b> card(s) → {p['receiver_mention']}\n\n"
            + "\n".join(lines)
            + (f"\n<i>… +{more} more</i>" if more > 0 else ""))

@bot1.on(events.CallbackQuery(pattern=r'^grant_(ok|no|nav)_([0-9a-f]{8})(?:_(\d{1,3}))?$'))
async def grant_callback(event):
    if event.sender_id != OWNER_ID:
        return await event.answer("Owner only.", alert=True)
    action, token, idx_raw = (g.decode('utf-8') if isinstance(g, bytes) else g for g in event.pattern_match.groups())

    if action == "nav":
        p = _grant_pending.get(token)
        if not p or time.time() - p["ts"] > GRANT_PENDING_TTL:
            _grant_pending.pop(token, None)
            return await event.answer("⌛ Expired — /grant ကို ပြန်ရိုက်ပါ။", alert=True)
        p["ts"] = time.time()
        return await _grant_edit_page(event, token, int(idx_raw or 0) % len(p["cards"]))

    # pop() is synchronous, so a double tap can never take the same pending twice — the second tap just sees "used".
    p = _grant_pending.pop(token, None)
    if not p:
        return await event.answer("⌛ Expired or already used.", alert=True)
    if time.time() - p["ts"] > GRANT_PENDING_TTL:
        return await event.answer("⌛ Expired — /grant ကို ပြန်ရိုက်ပါ။", alert=True)

    if action == "no":
        await event.answer("Cancelled.")
        return await event.edit("❌ <b>Grant cancelled.</b> — ဘာမှ မပေးပါဘူး။", parse_mode='html', buttons=None)

    await event.answer("⏳ Processing...")
    if is_gbanned(p["receiver_id"])[0]:                       # a gban may have landed while the owner was flipping through the cards
        return await event.edit("🚫 <b>Receiver က gban ခံထားရပါတယ်။</b> — ဘာမှ မပေးပါဘူး။", parse_mode='html', buttons=None)
    try:
        await event.edit(f"⏳ <b>Gifting {len(p['cards'])} card(s)…</b>", parse_mode='html', buttons=None)
    except Exception:
        pass
    ok, _msg = await _execute_mgift_owner(
        OWNER_ID, p["receiver_id"], [(c["char_id"], c["rarity"], c["tier"]) for c in p["cards"]], p["receiver_name"])
    if not ok:
        # at most GRANT_MAX_CARDS (< MGIFT_CHUNK) means ONE write to the receiver — so a failure here almost surely means nothing landed, but a timeout could hide a write that did
        text = ("⚠️ <b>Grant မအောင်မြင်ပါ။</b>\n"
                "<i>ထပ်မပေးခင် receiver ရဲ့ /harem ကို အရင်စစ်ပါ — ကဒ် နှစ်ခါ မရောက်စေဖို့။</i>")
    else:
        text = _grant_receipt(p)
    try:
        await event.edit(text, parse_mode='html', buttons=None)
    except Exception:
        await event.respond(text, parse_mode='html')

# ==========================================
# 🎁 /giftusd, /giftstar, /giftvipmode — direct user-to-user gifting of ⭐, ⭐ Star, and Bot
# VIP. All three: reply to the receiver's message, same confirm/cancel pattern as the card
# /gift above. /giftvipmode is paid for by the SENDER in ⭐ Star at the exact /buyvipmode rate
# (see VIP_TIERS) — the days land on the RECEIVER instead of the buyer; the Star still
# flows to the Owner, same Star sink as every other VIP purchase.
# ==========================================
GIFT_STAR_MIN = 0.01

async def _resolve_gift_receiver(event):
    """Shared receiver resolution + validation for all three /gift* commands below.
    Returns (receiver_id, error_message_or_None)."""
    if not event.is_reply:
        return None, "❌ <b>Reply to the user you want to gift.</b>"
    reply_msg = await event.get_reply_message()
    receiver_id = reply_msg.sender_id if reply_msg else None
    if not receiver_id:
        return None, "❌ <b>Couldn't identify that user.</b>"
    if receiver_id == event.sender_id:
        return None, "❌ <b>Can't gift to yourself!</b>"
    if receiver_id in bot_ids:
        return None, "❌ <b>Can't gift to a bot.</b>"
    return receiver_id, None

# ---- /giftstar ----
@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]giftstar(?:@\w+)?\s+(\d+(?:\.\d+)?)$', 'bot1')))
async def gift_star_handler(event):
    amount = round(float(event.pattern_match.group(1)), 2)
    receiver_id, err = await _resolve_gift_receiver(event)
    if err:
        return await event.reply(err, parse_mode='html')
    
    # 🩹 REMOVED (2026-10, per owner request): the 0.2% fee is gone — the receiver now gets exactly what the sender sends.
    if amount < GIFT_STAR_MIN:
        return await event.reply(f"❌ <b>Gift amount too small</b> <i>(minimum {GIFT_STAR_MIN} ⭐).</i>", parse_mode='html')

    sender_id = event.sender_id
    r_mention = await get_html_mention(event, receiver_id)

    # Check sender Star balance
    sender_doc = await users_catcher_col.find_one({"user_id": sender_id})
    star_balance = sender_doc.get("star_balance", 0) if sender_doc else 0
    if star_balance < amount:
        return await event.reply(
            f"❌ <b>Insufficient Star balance!</b> You need {format_star_plain(amount)}.",
            parse_mode='html'
        )

    confirm_text = (
        f"⭐ <b>Gift Confirmation</b>\n\n"
        f"💰 <b>Amount:</b> <code>{format_star_plain(amount)}</code> <i>(no fee)</i>\n"
        f"🎯 <b>Receiver:</b> {r_mention}\n\n"
        f"<blockquote>Are you sure you want to send this?</blockquote>"
    )
    buttons = [[
        colored_button("✅ Confirm", f"giftstar_confirm_{sender_id}_{receiver_id}_{amount}", color="success"),
        Button.inline("❌ Cancel", data=f"giftstar_cancel_{sender_id}_{receiver_id}_{amount}")
    ]]
    await event.reply(confirm_text, buttons=buttons, parse_mode='html')

@bot1.on(events.CallbackQuery(pattern=r'^giftstar_(confirm|cancel)_(\d+)_(\d+)_([\d.]+)(?:_([\d.]+))?$'))
async def gift_star_callback(event):
    action = event.pattern_match.group(1)
    if isinstance(action, bytes):
        action = action.decode('utf-8')
    sender_id = int(event.pattern_match.group(2))
    receiver_id = int(event.pattern_match.group(3))
    amount = round(float(event.pattern_match.group(4)), 2)
    # (2026-10) no fee any more. Confirm buttons sent BEFORE this change still carry a fee number in their data — it is ignored on purpose,
    # so an old pending button can't charge one either.
    fee = 0

    if event.sender_id != sender_id:
        return await event.answer("❌ This action is not for you!", alert=True)
    if not claim_single_tap(event):
        return await event.answer("⏳ Already processing...", alert=False)
    
    if action == "cancel":
        await event.edit(f"❌ <b>Gift Cancelled.</b> {format_star_plain(amount)} was not sent.", parse_mode='html', buttons=None)
        return await event.answer("Gift cancelled.", alert=True)
    
    # Deduct the amount from the sender
    if not await try_deduct_star(sender_id, amount):
        await event.edit("❌ <b>Not enough ⭐ Star balance anymore.</b>", parse_mode='html', buttons=None)
        return await event.answer("Insufficient Star.", alert=True)

    # The receiver gets all of it
    net_amount = amount
    if net_amount > 0:
        r_plain_name = await get_plain_name(event, receiver_id)
        await users_catcher_col.update_one(
            {"user_id": receiver_id},
            {"$inc": {"star_balance": net_amount}, "$set": {"fullname": r_plain_name}},
            upsert=True
        )
    
    r_mention = await get_html_mention(event, receiver_id)
    s_mention = await get_html_mention(event, sender_id)
    await event.edit(
        f"✅ <b>{format_star_plain(net_amount)} sent to {r_mention}!</b>",
        parse_mode='html',
        buttons=None
    )
    # 🩹 CHANGED (per owner request): the receiver DM notification was removed here — the
    # in-chat confirmation above is enough now.

