DICE_SESSION_MAX_AGE = 600  # seconds (10 minutes)

# 🚦 NEW (per owner request — anti-spam): a player gets CASINO_COOLDOWN_TRIGGER plays across …
CASINO_COOLDOWN_TRIGGER = 10   # plays in one burst before the long break
# 🩹 CHANGED (2026-10, per owner request — "ဆယ်ခါပြီးတိုင်း နှစ်မိနစ်နားတာကနေ ငါးမိနစ်နားတာပြောင်းပေး"): the break after every …
CASINO_COOLDOWN_SECONDS = 600
# 🩹 REMOVED (2026-10, per owner request): there used to be a 1-minute rest after EVERY single play, on top of the break …
CASINO_PLAY_GAP_SECONDS = 0
# 🆕 The play counter used to only ever reset when a lock fired, so a player who spread 10 plays over a whole
# day still got locked. Harmless at 60s, not at 10 minutes — so the counter now starts over once a player has
# been idle this long. (Must stay comfortably above CASINO_PLAY_GAP_SECONDS.)
CASINO_BURST_RESET_SECONDS = 900
# 🆕 A blocked player who keeps tapping / retyping gets ONE "you're resting" notice per this many seconds,
# not one edit/send per attempt — the notice itself was becoming the spam.
CASINO_BLOCK_NOTICE_GAP = 4
# 🆕 (2026-10) short notices a TYPED command gets back — "you're resting", a bad amount, not enough ⭐ — clean themselves up
# after this many seconds, so a player mashing /dice can't leave a trail of them behind.
CASINO_NOTICE_LIFETIME = 25

def _fmt_rest(seconds):
    """'45s' / '9m 41s' — compact countdown text."""
    seconds = max(0, int(seconds))
    return f"{seconds}s" if seconds < 60 else f"{seconds // 60}m {seconds % 60:02d}s"

def _casino_cooldown_status(user_id, now=None):
    """PURE check (changes nothing). Returns (blocked, remaining_seconds, kind) where kind is
    "rest" (the long break after CASINO_COOLDOWN_TRIGGER plays), "gap" (the 1-minute rest after a
    single play) or None. Owner is exempt, same convention as is_on_cooldown()."""
    if user_id == OWNER_ID:
        return False, 0, None
    state = casino_play_counts.get(user_id)
    if not state:
        return False, 0, None
    now = now or time.time()
    for key, kind in (("locked_until", "rest"), ("next_play_at", "gap")):
        left = state.get(key, 0) - now
        if left > 0:
            return True, int(left) + (1 if left > int(left) else 0), kind   # round UP: never show "0s" while still blocked
    return False, 0, None

def _reserve_casino_play(user_id):
    """Check AND take the play slot in one synchronous step (no awaits, so two near-simultaneous taps from
    the same player can't both slip through). Returns (blocked, remaining, kind, snapshot). If the play then
    doesn't happen (bad bet, not enough balance, engine hiccup...), hand `snapshot` to _release_casino_play
    so a mistyped amount never costs anyone a minute. Replaces the old _check_casino_cooldown."""
    blocked, remaining, kind = _casino_cooldown_status(user_id)
    if blocked:
        return True, remaining, kind, None
    if user_id == OWNER_ID:
        return False, 0, None, None
    now = time.time()
    state = casino_play_counts.setdefault(user_id, {"count": 0, "locked_until": 0, "next_play_at": 0, "last_play": 0})
    snapshot = dict(state)
    if now - state.get("last_play", 0) > CASINO_BURST_RESET_SECONDS:
        state["count"] = 0
    state["count"] += 1
    state["last_play"] = now
    state["next_play_at"] = (now + CASINO_PLAY_GAP_SECONDS) if CASINO_PLAY_GAP_SECONDS > 0 else 0
    if state["count"] >= CASINO_COOLDOWN_TRIGGER:
        state["count"] = 0
        state["locked_until"] = now + CASINO_COOLDOWN_SECONDS
    return False, 0, None, snapshot

def _release_casino_play(user_id, snapshot):
    """Undo a _reserve_casino_play whose play never actually happened."""
    state = casino_play_counts.get(user_id)
    if snapshot is None or state is None:
        return
    state.clear()
    state.update(snapshot)

def _casino_should_notify_block(user_id):
    """True at most once per CASINO_BLOCK_NOTICE_GAP seconds per player — see that constant."""
    state = casino_play_counts.get(user_id)
    if state is None:
        return True
    now = time.time()
    if now - state.get("last_notice", 0) < CASINO_BLOCK_NOTICE_GAP:
        return False
    state["last_notice"] = now
    return True

def _casino_block_text(mention, remaining, kind):
    if kind == "rest":
        return (
            f"😮‍💨 {mention} — that's {CASINO_COOLDOWN_TRIGGER} plays in a row, time for a break.\n"
            f"You can play again in <code>{_fmt_rest(remaining)}</code>."
        )
    return (
        f"⏳ {mention} — catch your breath.\n"
        f"Next play in <code>{_fmt_rest(remaining)}</code>."
    )

def _casino_block_toast(remaining, kind):
    """Plain-text version for a button tap's pop-up (no chat message at all)."""
    if kind == "rest":
        return f"😮‍💨 Break time — back in {_fmt_rest(remaining)}"
    return f"⏳ Next play in {_fmt_rest(remaining)}"

def _casino_next_play_note(user_id):
    """Footer line for a finished game's result card, so players know the rest they just earned ('' for the Owner)."""
    blocked, remaining, kind = _casino_cooldown_status(user_id)
    if not blocked:
        return ""
    if kind == "rest":
        return f"😮‍💨 <i>{CASINO_COOLDOWN_TRIGGER} plays in a row — take a break! Back in {_fmt_rest(remaining)}</i>"
    return f"⏳ <i>Next play in {_fmt_rest(remaining)}</i>"

