# =========================================================
# 🪨📄✂️ ROCK PAPER SCISSORS (2026-09, per owner's own design)
# =========================================================
# Two-stage interactive reveal, not an instant roll like slot/basketball/dice above: the player …
RPS_MOVES = ["🪨", "📄", "✂️"]
RPS_NAMES = {"🪨": "Rock", "📄": "Paper", "✂️": "Scissors"}
RPS_BEATS = {"🪨": "✂️", "✂️": "📄", "📄": "🪨"}  # key beats value
RPS_REVEAL_TTL = 90    # seconds to tap the NEXT reveal before this round auto-cancels + refunds
RPS_WIN_MULT = 3
RPS_WIN_CHANCE = 0.30   # → 3 × 0.30 = 90% RTP, in line with this casino's other house edges

def _rps_card_text(mention, bet, bot_move, player_move, footer=""):
    return (
        f"🪨📄✂️ <b>ROCK PAPER SCISSORS</b>\n"
        f"👤 {mention} · 💵 <code>{format_star_plain(bet)}</code>\n\n"
        f"🤖 <b>Bot's move:</b> {bot_move or '❓'}\n"
        f"🎮 <b>Your move:</b> {player_move or '❓'}"
        + (f"\n\n{footer}" if footer else "")
    )

async def _rps_timeout_watchdog(user_id, expiry):
    """If the player never finishes both reveals within RPS_REVEAL_TTL, refunds the already-
    deducted bet and tears the round down — same 'never let real escrowed Star get stuck'
    principle as _cardgame_lobby_timeout_watchdog, just keyed by user_id instead of chat_id."""
    wait_for = expiry - time.time()
    if wait_for > 0:
        await asyncio.sleep(wait_for)
    game = active_rps_games.get(user_id)
    if not game or game.get("expiry") != expiry:
        return  # already finished (or superseded by a fresher reveal stage) for this user
    active_rps_games.pop(user_id, None)
    try:
        await users_catcher_col.update_one({"user_id": user_id}, {"$inc": {"star_balance": game["bet"]}})
        await bot3_treasury_adjust(usd=-game["bet"])
    except Exception as e:
        logging.error(f"❌ RPS timeout refund failed for {user_id}: {e}")
    try:
        text = _rps_card_text(game["mention"], game["bet"], game["bot_move"], None,
                               "⏳ <i>Round expired — your bet has been fully refunded.</i>")
        _wd_client = bot1
        await _wd_client.edit_message(game["chat_id"], game["msg_id"], text, parse_mode=_pm(_wd_client), buttons=None)
    except Exception as e:
        logging.error(f"❌ RPS timeout edit failed for {user_id}: {e}")

async def _start_rps_reveal(event, user_id, bet, mention):
    """Opens the RPS card and lets the PLAYER trigger the bot's reveal first — their own reveal
    (and the actual payout decision) only happens after that, in rps_player_reveal_cb below. The
    bet is already deducted by the time this runs (see _casino_play's dispatch just above it)."""
    chat_id = event.chat_id
    text = _rps_card_text(mention, bet, None, None, "👇 <i>Tap below to reveal the Bot's move!</i>")
    buttons = [[Button.inline("🎲 Reveal Bot's Move", data=f"rps_bot_{user_id}")]]
    sent = await _casino_out(event, message=text, parse_mode='html', buttons=buttons)
    expiry = time.time() + RPS_REVEAL_TTL
    active_rps_games[user_id] = {
        "bet": bet, "mention": mention, "chat_id": chat_id, "msg_id": sent.id,
        "bot_move": None, "expiry": expiry,
    }
    asyncio.create_task(_rps_timeout_watchdog(user_id, expiry))

async def rps_bot_reveal_cb(event):
    user_id = int(event.pattern_match.group(1))
    if event.sender_id != user_id:
        return await event.answer("⚠️ That's not your game!", alert=True)
    game = active_rps_games.get(user_id)
    if not game or game["bot_move"] is not None:
        return await event.answer("⏳ That round is over or has expired.", alert=True)
    if not claim_single_tap(event):
        return await event.answer("⏳ Hang on", alert=False)
    await event.answer("🎲 Rolling...")

    # 🩹 Result decided upfront, same "sleep is purely cosmetic" philosophy as every other casino
    # game's animation in this file — this loop only controls what the player visually sees.
    final_move = random.choice(RPS_MOVES)
    decoys = [m for m in RPS_MOVES if m != final_move]
    random.shuffle(decoys)
    for frame in decoys + [final_move]:
        try:
            await event.edit(_rps_card_text(game["mention"], game["bet"], frame, None), parse_mode=_pm(event.client), buttons=None)
        except Exception:
            pass
        await asyncio.sleep(0.6)

    game["bot_move"] = final_move
    game["expiry"] = time.time() + RPS_REVEAL_TTL  # reset the clock — now waiting on the player's turn
    text = _rps_card_text(game["mention"], game["bet"], final_move, None, "👇 <i>Your turn — tap to reveal your move!</i>")
    buttons = [[Button.inline("🎲 Reveal Your Move", data=f"rps_player_{user_id}")]]
    try:
        await event.edit(text, parse_mode=_pm(event.client), buttons=buttons)
    except Exception as e:
        logging.error(f"❌ RPS bot-reveal final edit failed for {user_id}: {e}")
    asyncio.create_task(_rps_timeout_watchdog(user_id, game["expiry"]))

bot1.on(events.CallbackQuery(pattern=r'^rps_bot_(\d+)$'))(rps_bot_reveal_cb)

async def rps_player_reveal_cb(event):
    user_id = int(event.pattern_match.group(1))
    if event.sender_id != user_id:
        return await event.answer("⚠️ That's not your game!", alert=True)
    game = active_rps_games.get(user_id)
    if not game or not game["bot_move"]:
        return await event.answer("⏳ That round is over or has expired.", alert=True)
    if not claim_single_tap(event):
        return await event.answer("⏳ Hang on", alert=False)
    await event.answer("🎲 Rolling...")

    # 🔒 Pop FIRST, before any further awaits — commits this round to resolving now, same
    # "nothing else can touch it again" reasoning as cardgame_start_cb.
    active_rps_games.pop(user_id, None)
    bot_move = game["bot_move"]
    bet, mention, chat_id = game["bet"], game["mention"], game["chat_id"]

    # See RPS_WIN_CHANCE's own note above — weighted, not a fair coin flip between the two
    # non-tying moves, so the payout math actually holds up over the long run.
    win_move = next(k for k, v in RPS_BEATS.items() if v == bot_move)   # what beats bot_move
    lose_move = RPS_BEATS[bot_move]                                     # what bot_move beats
    player_move = win_move if random.random() < RPS_WIN_CHANCE else lose_move

    decoys = [m for m in RPS_MOVES if m != player_move]
    random.shuffle(decoys)
    for frame in decoys + [player_move]:
        try:
            await event.edit(_rps_card_text(mention, bet, bot_move, frame), parse_mode=_pm(event.client), buttons=None)
        except Exception:
            pass
        await asyncio.sleep(0.6)

    did_win = (player_move == win_move)
    win_amount = round(bet * RPS_WIN_MULT, 2) if did_win else 0
    if win_amount > 0:
        await users_catcher_col.update_one({"user_id": user_id}, {"$inc": {"star_balance": win_amount}})
        await bot3_treasury_adjust(usd=-win_amount)
    net = win_amount - bet
    await casino_record_net(user_id, net)                     # 🏦 feeds the daily net-win ceiling

    if did_win:
        result_line = f"🏆 <b>{RPS_NAMES[player_move]} beats {RPS_NAMES[bot_move]} — you win!</b>"
    else:
        result_line = f"💔 <b>{RPS_NAMES[bot_move]} beats {RPS_NAMES[player_move]} — you lose.</b>"
    net_emoji = "📈" if net > 0 else ("📉" if net < 0 else "➖")
    footer = f"{result_line}\n{net_emoji} <b>Net:</b> <code>{'+' if net >= 0 else ''}{format_star_plain(net)}</code>"
    next_note = _casino_next_play_note(user_id)   # same ⏳/😮‍💨 footer the dice-style games show
    if next_note:
        footer += f"\n\n{next_note}"
    text = _rps_card_text(mention, bet, bot_move, player_move, footer)
    try:
        await event.edit(text, parse_mode=_pm(event.client), buttons=_game_result_buttons(user_id, bet, "rps"))
    except Exception as e:
        logging.error(f"❌ RPS result edit failed for {user_id}: {e}")
        await event.client.send_message(chat_id, text, parse_mode=_pm(event.client), buttons=_game_result_buttons(user_id, bet, "rps"))

bot1.on(events.CallbackQuery(pattern=r'^rps_player_(\d+)$'))(rps_player_reveal_cb)

# ---- 🎰 Slot paytable — decoding Telegram's own native 🎰 dice value (1-64) ----
# 🩹 REVERTED BACK TO NATIVE (2026-09, round 2, per owner request): see the big note above the …
SLOT_SYMBOL_NAMES = ("bar", "grapes", "lemon", "seven")
SLOT_SYMBOL_DISPLAY = {"bar": "BAR", "grapes": "🍇", "lemon": "🍋", "seven": "7️⃣"}

def _slot_decode(value):
    """Decodes a Telegram 🎰 dice value (1-64) into its 3 reel symbols, for DISPLAY only —
    payout itself uses the direct value lookup below, not this. This mapping is Telegram's own
    (undocumented but stable, and relied on by every open-source Telegram casino bot that reads
    dice results): treat (value-1) as a base-4 number; each digit 0-3 selects one reel's symbol
    from SLOT_SYMBOL_NAMES, least-significant digit first."""
    v = value - 1
    reels = []
    for _ in range(3):
        reels.append(SLOT_SYMBOL_NAMES[v % 4])
        v //= 4
    return reels  # [reel1, reel2, reel3]

# Of the 64 equally-likely outcomes: exactly 1 is 777 (value 64), 3 are any-other-triple …
SLOT_JACKPOT_VALUE = 64
SLOT_TRIPLE_VALUES = {1, 22, 43}
SLOT_TWO_SEVENS_VALUES = {16, 32, 48, 52, 56, 60, 61, 62, 63}
# 🩹 RETUNED (2026-09, round 2, per owner request — Star inflation, now against the CORRECTED …
SLOT_JACKPOT_MULT = 13
SLOT_TRIPLE_MULT = 3
SLOT_TWO_SEVENS_MULT = 1

# ---- 🏀 Basketball — Telegram value 1-5. 4 or 5 = a made basket (undocumented but stable
# Telegram behavior); 1-3 = a miss. 🩹 CHANGED (per owner request): flat 2x on ANY make, no
# swish/bank-in distinction anymore. 2/5 chance of a make → 2×0.4 = 80% RTP. ----
BBALL_IN_VALUES = {4, 5}
BBALL_MAKE_MULT = 2

# ---- 🎲 Dice — Telegram value 1-6, uniform. 🩹 CHANGED AGAIN (2026-09, per owner request):
DICE_WIN_VALUES = {5, 6}
# 🩹 CHANGED (2026-10, per owner report — "Casino မှာ native emoji တွေက အမြဲအနိုင်ပေးနေတယ်၊ dice ကစားပြီး ကစားသမား တစ်ဦးက 1000⭐ ကနေ …
_dice_mult = float(os.environ.get("DICE_WIN_MULT", "2.2"))
DICE_WIN_MULT = int(_dice_mult) if _dice_mult.is_integer() else _dice_mult

# ---- 🎯 Darts — NEW casino game, same native-dice engine as basketball/dice above. Telegram's …
DART_BULLSEYE_VALUE = 6
DART_BULLSEYE_MULT = 4
DART_RESULT_LABELS = {
    1: "🌫️ Way off the board",
    2: "🔘 Outer ring",
    3: "⭕ Outer ring",
    4: "🟡 Inner ring",
    5: "🟠 Just off the bullseye",
    6: "🎯 BULLSEYE!",
}

# ---- ⚽ Football (2026-11, per owner request) — same native-dice engine as basketball/darts. Telegram's ⚽ dice is uniform 1-5 server-side
# and (undocumented but stable, same family as the basketball values above) 4 or 5 = a GOAL, 1-3 = a miss. The paytable pays EXACTLY the values the
# animation shows as goals, so "the shown result always matches the payout" holds. 2/5 chance × 2x = 80% RTP — identical to basketball.
FOOTBALL_GOAL_VALUES = {4, 5}
FOOTBALL_GOAL_MULT = 2

# ---- 🎳 Bowling (2026-11, per owner request) — native dice again, uniform 1-6: 6 = STRIKE (every pin down), 1 = every pin missed, 2-5 = somewhere
# in between (Telegram doesn't document the exact pin counts, so none are claimed on the result card). Only the strike pays:
# 1/6 chance × 4.5x = 75% RTP — between slot (~48%) and basketball/football (80%).
BOWLING_STRIKE_VALUE = 6
BOWLING_STRIKE_MULT = 4.5

def _chunk_buttons(buttons, n=4):
    """Telegram allows at most 8 buttons per inline row — with 8 games + the card game the casino menu would overflow that, so button lists are
    cut into rows of `n` instead of one long row."""
    return [buttons[i:i + n] for i in range(0, len(buttons), n)]

# =========================================================
# 💣 MINES (2026-11, per owner request)
# =========================================================
# NOT a native-dice game — a 5×5 board of inline buttons, MINES_COUNT mines hidden among the 25 tiles. Every safe tile the player opens raises the …
def _mines_env_float(name, default):
    try:
        return float(os.environ.get(name, default))
    except (TypeError, ValueError):
        return float(default)

MINES_TILES = 25
MINES_ROW_LEN = 5
# 💣 CHANGED (2026-11, per owner request — players spam /mines to farm Stars and a lucky run of ~10 safe tiles paid many times the bet):
MINES_COUNT = int(min(max(_mines_env_float("MINES_COUNT", 5), 1), MINES_TILES - 1))
MINES_GROWTH = int(min(max(_mines_env_float("MINES_GROWTH", 0), 0), MINES_TILES))
MINES_RULE_NOTE = " — every safe tile adds a mine, so the risk climbs" if MINES_GROWTH else ""
MINES_RTP = min(max(_mines_env_float("MINES_RTP", 0.60), 0.50), 0.99)
MINES_MAX_MULT = max(_mines_env_float("MINES_MAX_MULT", 25), 2.0)
_MINES_DEFAULT_PAYOUTS = [0.75, 0.94, 1.15, 1.35, 1.60, 1.85, 2.15, 2.55, 3.15, 4.00, 5.00, 6.00, 7.50, 9.00, 11.00, 13.00, 16.00, 19.00, 22.00, 25.00]   # tile 1 … tile 20

def _mines_load_payouts():
    """The ladder: multiplier after k safe tiles = table[k-1]. Env MINES_PAYOUTS="0.75,0.94,…" replaces it, "off" switches back to fair odds × MINES_RTP.
    A bad value falls back to the default; the list is forced to never go DOWN as k grows (a deeper tile can't pay less than a shallower one)."""
    raw = os.environ.get("MINES_PAYOUTS", "").strip()
    if raw.lower() in ("off", "none", "formula"):
        return []
    vals = _MINES_DEFAULT_PAYOUTS
    if raw:
        try:
            parsed = [float(x) for x in raw.replace(";", ",").split(",") if x.strip()]
            if parsed and all(v > 0 for v in parsed):
                vals = parsed
        except ValueError:
            pass
    out, top = [], 0.0
    for v in vals:
        top = max(top, round(v, 2))
        out.append(top)
    return out

MINES_PAYOUT_TABLE = _mines_load_payouts()
print(f"💣 Mines: " + (f"payout ladder {MINES_PAYOUT_TABLE[:12]}…" if (MINES_PAYOUT_TABLE and not MINES_GROWTH) else f"RTP {MINES_RTP:.0%} (house keeps ~{(1 - MINES_RTP):.0%})") + f" · max win {MINES_MAX_MULT:g}x · {MINES_COUNT} mines" + (f" (+{MINES_GROWTH} per safe tile)" if MINES_GROWTH else "")
      + ("  ⚠️ MINES_RTP is set in the environment — that value overrides the code default" if "MINES_RTP" in os.environ else ""))
MINES_IDLE_TTL = 120          # seconds without a tap before the round is settled automatically
_MINES_TASKS = set()          # strong refs so a pending watchdog can't be garbage-collected mid-sleep

def _mines_count_at(k):
    """Mines on the board once k safe tiles are open: MINES_COUNT at the start, MINES_GROWTH more for every safe tile (never more than the tiles still closed)."""
    k = max(0, int(k))
    return min(MINES_COUNT + MINES_GROWTH * k, MINES_TILES - k)

def _mines_safe_left(k):
    """How many safe tiles are still closed after k safe tiles are open (0 = the board is cleared)."""
    k = max(0, int(k))
    return max(0, MINES_TILES - k - _mines_count_at(k))

def _mines_multiplier(k):
    """Payout multiplier after k safe tiles are open (1.0 for none): the payout ladder (MINES_PAYOUT_TABLE), or — when MINES_PAYOUTS=off or MINES_GROWTH is on — fair odds from the REAL per-tile risk × MINES_RTP."""
    k = max(0, int(k))
    if k <= 0:
        return 1.0
    if MINES_PAYOUT_TABLE and not MINES_GROWTH:                     # 🪜 the payout ladder (the card shows these exact numbers)
        return min(MINES_PAYOUT_TABLE[min(k, len(MINES_PAYOUT_TABLE)) - 1], MINES_MAX_MULT)
    fair = 1.0
    for i in range(k):
        safe = _mines_safe_left(i)
        if safe <= 0:
            break                                   # no safe tile could be opened at this step — the round would already be over
        fair *= (MINES_TILES - i) / safe
    return min(_math.floor(fair * MINES_RTP * 100 + 1e-9) / 100, MINES_MAX_MULT)

def _mines_grow(game):
    """After a safe tile: add MINES_GROWTH more mines (random closed tiles) so the next tap is riskier."""
    k = len(game["revealed"])
    need = _mines_count_at(k) - len(game["mines"])
    if need > 0:
        free = [i for i in range(MINES_TILES) if i not in game["revealed"] and i not in game["mines"]]
        game["mines"].update(random.sample(free, min(need, len(free))))

def _mines_grid_text(game, hit_idx=None):
    rows = []
    for r in range(MINES_TILES // MINES_ROW_LEN):
        cells = []
        for c in range(MINES_ROW_LEN):
            i = r * MINES_ROW_LEN + c
            if i == hit_idx:
                cells.append("💥")
            elif i in game["mines"]:
                cells.append("💣")
            elif i in game["revealed"]:
                cells.append("💎")
            else:
                cells.append("⬜")
        rows.append(" ".join(cells))
    return "\n".join(rows)

def _mines_card_text(game, footer="", state="playing", hit_idx=None):
    """state: playing / won / lost / expired. The full board is only drawn once the round is over."""
    bet = game["bet"]
    k = len(game["revealed"])
    mines_now = len(game["mines"])
    lines = [
        "💣 <b>MINES</b>",
        f"👤 {game['mention']} · 💵 <code>{format_star_plain(bet)}</code>",
        "",
    ]
    if state != "playing":
        lines += [_mines_grid_text(game, hit_idx), ""]
    lines.append(f"💎 <b>Safe tiles:</b> {k}  ·  💣 <b>Mines:</b> {mines_now}")
    if k and state in ("playing", "won"):
        mult = _mines_multiplier(k)
        lines.append(f"📈 <b>Multiplier:</b> <code>{mult:.2f}x</code> → <code>{format_star_plain(round(bet * mult, 2))}</code>")
    if state == "playing":
        if _mines_safe_left(k) > 0:
            risk = mines_now / (MINES_TILES - k) * 100            # the real chance the next tap is a mine
            lines.append(f"➡️ <b>Next tile:</b> <code>{_mines_multiplier(k + 1):.2f}x</code>  ·  ⚠️ <code>{risk:.0f}%</code> mine")
        lines += ["", "👇 <i>Tap a tile — avoid the mines." + (" Every safe tile adds a mine, so the risk keeps rising." if MINES_GROWTH else "") + " Cash out any time after your first safe tile.</i>"]
    if footer:
        lines += ["", footer]
    return "\n".join(lines)

def _mines_board_buttons(user_id, game):
    rows = []
    for r in range(MINES_TILES // MINES_ROW_LEN):
        rows.append([
            Button.inline("💎" if (r * MINES_ROW_LEN + c) in game["revealed"] else "⬜", data=f"mn_{user_id}_{r * MINES_ROW_LEN + c}")
            for c in range(MINES_ROW_LEN)
        ])
    k = len(game["revealed"])
    if k:
        label = f"💰 Cash Out {format_star_plain(round(game['bet'] * _mines_multiplier(k), 2))}"
    else:
        label = "💰 Cash Out"
    rows.append([Button.inline(label, data=f"mncash_{user_id}")])
    return rows

async def _mines_answer(event, *args, **kwargs):
    try:
        await event.answer(*args, **kwargs)
    except Exception:
        pass            # a stale/expired query id is never worth breaking a round over

async def _mines_pay(user_id, amount):
    """Credits `amount` to the player (and mirrors it on the treasury). True once the credit has landed — see _casino_credit."""
    return await _casino_credit(user_id, amount, "Mines")

async def _mines_settle(user_id, game, outcome, hit_idx=None):
    """Moves the money for a finished round and builds its final card. The game must already be popped from active_mines_games.
    outcome: lose / cashout / cap / timeout_cash / timeout_refund. Returns (text, buttons)."""
    bet = game["bet"]
    k = len(game["revealed"])
    mult = _mines_multiplier(k)
    win, state = 0.0, "lost"
    if outcome in ("cashout", "cap", "timeout_cash"):
        win, state = round(bet * mult, 2), "won"
    elif outcome == "timeout_refund":
        win, state = bet, "expired"

    paid = True
    if win > 0:
        paid = await _mines_pay(user_id, win)
        if not paid:
            logging.error(f"🚨 MINES PAYOUT NOT CREDITED: user {user_id} is owed {win} (outcome {outcome}) — fix by hand.")
    net = win - bet
    if outcome != "timeout_refund":
        await casino_record_net(user_id, net)                 # 🏦 feeds the daily net-win ceiling

    net_emoji = "📈" if net > 0 else ("📉" if net < 0 else "➖")
    net_line = f"{net_emoji} <b>Net:</b> <code>{'+' if net >= 0 else ''}{format_star_plain(net)}</code>"
    if outcome == "lose":
        footer = f"💥 <b>BOOM! You hit a mine.</b>\n{net_line}"
    elif outcome == "cashout":
        footer = f"🏆 <b>Cashed out at {mult:.2f}x!</b>\n{net_line}"
    elif outcome == "cap":
        footer = f"🏆 <b>Max reached — cashed out at {mult:.2f}x!</b>\n{net_line}"
    elif outcome == "timeout_cash":
        footer = f"⏳ <i>Idle too long — cashed out automatically at {mult:.2f}x.</i>\n{net_line}"
    else:
        footer = "⏳ <i>Round expired — your bet has been fully refunded.</i>"
    if not paid:
        footer += (f"\n\n⚠️ <b>The payout hit a database error</b> — <code>{format_star_plain(win)}</code> is owed to you. "
                   f"Screenshot this and message the owner.")
    if outcome in ("lose", "cashout", "cap"):
        next_note = _casino_next_play_note(user_id)           # same ⏳/😮‍💨 footer the other games show
        if next_note:
            footer += f"\n\n{next_note}"

    text = _mines_card_text(game, footer, state=state, hit_idx=hit_idx)
    buttons = _game_result_buttons(user_id, bet, "mines") if outcome in ("lose", "cashout", "cap") else None
    return text, buttons

async def _mines_finish(event, user_id, game, outcome, hit_idx=None, toast=""):
    """Interactive ending (a tap): settle the money, then turn the board message into the result card."""
    if toast:
        await _mines_answer(event, toast)
    text, buttons = await _mines_settle(user_id, game, outcome, hit_idx)
    try:
        await event.edit(text, parse_mode=_pm(event.client), buttons=buttons)
    except Exception as e:
        logging.error(f"❌ Mines result edit failed for {user_id}: {e}")
        try:
            await event.client.send_message(game["chat_id"], text, parse_mode=_pm(event.client), buttons=buttons)
        except Exception as e2:
            logging.error(f"❌ Mines result send failed for {user_id}: {e2}")

async def _mines_expire(user_id, expiry):
    """Idle timeout. Never raises. Skips if the round has moved on (a newer tap reset the clock, it ended, or a tap is mid-flight)."""
    try:
        game = active_mines_games.get(user_id)
        if not game or game.get("expiry") != expiry or game.get("busy"):
            return
        active_mines_games.pop(user_id, None)                 # commit first — nothing else can touch this round now
        outcome = "timeout_cash" if game["revealed"] else "timeout_refund"
        text, _ = await _mines_settle(user_id, game, outcome)
        client = bot1
        try:
            await client.edit_message(game["chat_id"], game["msg_id"], text, parse_mode=_pm(client), buttons=None)
        except Exception as e:
            logging.error(f"❌ Mines timeout edit failed for {user_id}: {e}")
    except Exception as e:
        logging.error(f"❌ Mines timeout handler failed for {user_id}: {e}")

async def _mines_timeout_watchdog(user_id, expiry):
    wait_for = expiry - time.time()
    if wait_for > 0:
        await asyncio.sleep(wait_for)
    await _mines_expire(user_id, expiry)

def _mines_arm_watchdog(user_id, game):
    game["expiry"] = time.time() + MINES_IDLE_TTL
    task = asyncio.create_task(_mines_timeout_watchdog(user_id, game["expiry"]))
    _MINES_TASKS.add(task)
    task.add_done_callback(_MINES_TASKS.discard)

async def _start_mines(event, user_id, bet, mention):
    """Opens the board. The bet is already deducted by the time this runs (see _casino_play's dispatch). If SENDING the board fails this raises
    BEFORE the round is registered, and the caller refunds — so a bet is never kept for a board the player never got."""
    game = {
        "bet": bet, "mention": mention, "chat_id": event.chat_id, "msg_id": None,
        "mines": set(random.sample(range(MINES_TILES), MINES_COUNT)), "revealed": set(),
        "expiry": 0.0, "busy": False,
    }
    sent = await _casino_out(event, message=_mines_card_text(game), parse_mode='html', buttons=_mines_board_buttons(user_id, game))
    game["msg_id"] = sent.id
    active_mines_games[user_id] = game
    _mines_arm_watchdog(user_id, game)

async def mines_tile_cb(event):
    try:
        user_id = int(event.pattern_match.group(1))
        idx = int(event.pattern_match.group(2))
    except Exception:
        return await _mines_answer(event)
    if event.sender_id != user_id:
        return await _mines_answer(event, "⚠️ That's not your game!", alert=True)
    game = active_mines_games.get(user_id)
    if not game or event.message_id != game["msg_id"]:
        return await _mines_answer(event, "⏳ That round is over or has expired.", alert=True)
    if not (0 <= idx < MINES_TILES):
        return await _mines_answer(event)
    if idx in game["revealed"]:
        return await _mines_answer(event, "✅ Already opened", alert=False)
    if game["busy"]:
        return await _mines_answer(event, "⏳ Hang on", alert=False)
    game["busy"] = True            # no await since the checks above, so two quick taps can never both get past them
    try:
        if idx in game["mines"]:
            active_mines_games.pop(user_id, None)             # 🔒 commit the loss before any further await
            return await _mines_finish(event, user_id, game, "lose", hit_idx=idx, toast="💥 BOOM!")
        game["revealed"].add(idx)
        k = len(game["revealed"])
        _mines_grow(game)                                      # 💣 a safe tile adds mines — the next tap is riskier
        if _mines_safe_left(k) <= 0 or _mines_multiplier(k) >= MINES_MAX_MULT:
            active_mines_games.pop(user_id, None)
            return await _mines_finish(event, user_id, game, "cap", toast="🏆 Max win!")
        await _mines_answer(event, "💎 Safe!")
        try:
            await event.edit(_mines_card_text(game), parse_mode=_pm(event.client), buttons=_mines_board_buttons(user_id, game))
        except Exception as e:
            logging.error(f"❌ Mines board edit failed for {user_id}: {e}")
    except Exception as e:
        logging.error(f"❌ Mines tile handler failed for {user_id}: {e}")
    finally:
        game["busy"] = False
        if active_mines_games.get(user_id) is game:           # still running — restart its idle clock
            _mines_arm_watchdog(user_id, game)

async def mines_cash_cb(event):
    try:
        user_id = int(event.pattern_match.group(1))
    except Exception:
        return await _mines_answer(event)
    if event.sender_id != user_id:
        return await _mines_answer(event, "⚠️ That's not your game!", alert=True)
    game = active_mines_games.get(user_id)
    if not game or event.message_id != game["msg_id"]:
        return await _mines_answer(event, "⏳ That round is over or has expired.", alert=True)
    if game["busy"]:
        return await _mines_answer(event, "⏳ Hang on", alert=False)
    if not game["revealed"]:
        return await _mines_answer(event, "💎 Open at least one safe tile first!", alert=True)
    game["busy"] = True
    active_mines_games.pop(user_id, None)                     # 🔒 commit to cashing out — nothing else can touch this round now
    try:
        await _mines_finish(event, user_id, game, "cashout", toast="💰 Cashing out...")
    except Exception as e:
        logging.error(f"❌ Mines cash-out failed for {user_id}: {e}")

bot1.on(events.CallbackQuery(pattern=r'^mn_(\d+)_(\d+)$'))(mines_tile_cb)
bot1.on(events.CallbackQuery(pattern=r'^mncash_(\d+)$'))(mines_cash_cb)

# =========================================================
# 🎡 LUCKY WHEEL (2026-11, per owner request)
# =========================================================
# One tap: the bet is taken, a text "wheel" spins (a few edited frames, purely cosmetic — the landing slot is drawn up front, server-side) and lands on
# one of 20 slots. Every slot is equally likely, so the payout table below IS the odds:
#   💀 0x ×8 · 🟠 0.5x ×4 · 🟡 1x ×3 · 🟢 1.5x ×2 · 🔵 2x ×2 · 🟣 5x ×1   →   RTP = (0×8 + 0.5×4 + 1×3 + 1.5×2 + 2×2 + 5×1) / 20 = 17/20 = 85%.
# Tune by editing WHEEL_RING (keep it 20 slots, and keep equal emoji from sitting next to each other so the spin looks varied).
WHEEL_MULT = {"💀": 0, "🟠": 0.5, "🟡": 1, "🟢": 1.5, "🔵": 2, "🟣": 5}
WHEEL_RING = ["💀", "🟠", "💀", "🟡", "💀", "🔵", "💀", "🟠", "💀", "🟢",
              "💀", "🟡", "💀", "🟣", "💀", "🟠", "🟡", "🟢", "🔵", "🟠"]
_WHEEL_SPINNING = set()       # user_ids with a spin in flight — a second bet must not stack on an unfinished spin

def _wheel_window(center):
    n = len(WHEEL_RING)
    return " ".join(WHEEL_RING[(center + off) % n] if off else f"〔{WHEEL_RING[center % n]}〕" for off in (-2, -1, 0, 1, 2))

def _wheel_mult_text(m):
    return f"{m:g}x"

def _wheel_card_text(mention, bet, center, footer=""):
    legend = " · ".join(f"{e} {_wheel_mult_text(m)}" for e, m in WHEEL_MULT.items())
    return (
        f"🎡 <b>LUCKY WHEEL</b>\n"
        f"👤 {mention} · 💵 <code>{format_star_plain(bet)}</code>\n\n"
        f"{_wheel_window(center)}\n\n"
        f"<i>{legend}</i>"
        + (f"\n\n{footer}" if footer else "")
    )

async def _casino_credit(user_id, amount, label="casino"):
    """Credits `amount` to the player and mirrors it on the treasury. Retries a couple of times; True once the credit has landed."""
    credited = False
    for attempt in range(3):
        try:
            await users_catcher_col.update_one({"user_id": user_id}, {"$inc": {"star_balance": amount}})
            credited = True
            break
        except Exception as e:
            logging.error(f"❌ {label} payout attempt {attempt + 1} failed for {user_id} ({amount}): {e}")
            await asyncio.sleep(0.5 * (attempt + 1))
    if not credited:
        return False
    try:
        await bot3_treasury_adjust(usd=-amount)
    except Exception as e:
        logging.error(f"❌ {label} treasury mirror failed for {user_id} ({amount}) — player WAS paid: {e}")
    return True

async def _casino_edit_msg(client, chat_id, msg_id, text, buttons=None):
    """Best-effort edit of a message this game owns; if the edit fails, the text is posted as a fresh message instead (never swallow a result)."""
    try:
        await client.edit_message(chat_id, msg_id, text, parse_mode=_pm(client), buttons=buttons)
        return True
    except Exception as e:
        logging.error(f"❌ casino edit failed ({chat_id}/{msg_id}): {e}")
    try:
        await client.send_message(chat_id, text, parse_mode=_pm(client), buttons=buttons)
    except Exception as e2:
        logging.error(f"❌ casino fallback send failed ({chat_id}): {e2}")
    return False

async def _start_wheel(event, user_id, bet, mention):
    """The bet is already deducted (see _casino_play). Raises ONLY if the opening card can't be sent — before anything else happened — so the caller can
    refund; after that point every failure is handled here (a half-run spin is refunded, never kept)."""
    target = random.randrange(len(WHEEL_RING))
    _WHEEL_SPINNING.add(user_id)
    try:
        sent = await _casino_out(event, message=_wheel_card_text(mention, bet, target - 12), parse_mode='html')
    except Exception:
        _WHEEL_SPINNING.discard(user_id)
        raise
    chat_id = event.chat_id
    client = bot1
    settled = False
    try:
        for back in (8, 5, 3, 1):
            await asyncio.sleep(0.8)
            try:
                await client.edit_message(chat_id, sent.id, _wheel_card_text(mention, bet, target - back) + "\n\n🌀 <i>Spinning…</i>", parse_mode=_pm(client))
            except Exception:
                pass                                    # a dropped animation frame never matters
        await asyncio.sleep(0.8)
        emoji = WHEEL_RING[target]
        mult = WHEEL_MULT[emoji]
        win = round(bet * mult, 2)
        paid = True
        if win > 0:
            paid = await _casino_credit(user_id, win, "Wheel")
            if not paid:
                logging.error(f"🚨 WHEEL PAYOUT NOT CREDITED: user {user_id} is owed {win} — fix by hand.")
        settled = True
        net = win - bet
        await casino_record_net(user_id, net)                 # 🏦 feeds the daily net-win ceiling
        if mult == 0:
            status = "💔 <b>No win this time</b>"
        elif mult < 1:
            status = f"↩️ <b>Half back:</b> +{format_star_plain(win)} <code>({_wheel_mult_text(mult)})</code>"
        elif mult == 1:
            status = f"↔️ <b>Money back</b> <code>({_wheel_mult_text(mult)})</code>"
        elif mult >= 5:
            status = f"🔥 <b>JACKPOT!</b> +{format_star_plain(win)} <code>({_wheel_mult_text(mult)})</code>"
        else:
            status = f"✨ <b>Win! +{format_star_plain(win)}</b> <code>({_wheel_mult_text(mult)})</code>"
        net_emoji = "📈" if net > 0 else ("📉" if net < 0 else "➖")
        footer = f"{status}\n{net_emoji} <b>Net:</b> <code>{'+' if net >= 0 else ''}{format_star_plain(net)}</code>"
        if not paid:
            footer += f"\n\n⚠️ <b>The payout hit a database error</b> — <code>{format_star_plain(win)}</code> is owed to you. Screenshot this and message the owner."
        next_note = _casino_next_play_note(user_id)
        if next_note:
            footer += f"\n\n{next_note}"
        await _casino_edit_msg(client, chat_id, sent.id, _wheel_card_text(mention, bet, target, footer), _game_result_buttons(user_id, bet, "wheel"))
    except Exception as e:
        logging.error(f"❌ Wheel spin failed for {user_id}: {e}")
        if not settled:
            if await _casino_credit(user_id, bet, "Wheel refund"):
                await _casino_edit_msg(client, chat_id, sent.id, "⚠️ The wheel hiccuped — your bet has been fully refunded, please try again.")
            else:
                logging.error(f"🚨 WHEEL REFUND NOT CREDITED: user {user_id} is owed {bet} — fix by hand.")
    finally:
        _WHEEL_SPINNING.discard(user_id)

# =========================================================
# 🚀 CRASH (2026-11, per owner request)
# =========================================================
# A rocket's multiplier climbs one step every CRASH_TICK_SECONDS; the player taps 💰 Cash Out before it crashes. Opening the round draws the CRASH POINT …
CRASH_RTP = min(max(_mines_env_float("CRASH_RTP", 0.90), 0.50), 0.99)
CRASH_MAX_MULT = max(_mines_env_float("CRASH_MAX_MULT", 25), 2.0)
CRASH_STEP = 1.18
CRASH_TICK_SECONDS = 1.5
CRASH_STALE_SECONDS = 180      # a round can't legitimately outlive this (the cap is reached in ~30s) — see the guard in _casino_play
_CRASH_TASKS = set()

def _crash_point():
    r = random.random()
    return max(1.0, _math.floor(CRASH_RTP / (1.0 - r) * 100) / 100)

def _crash_mult(k):
    """The multiplier shown after k surviving ticks (1.00 at the launch pad)."""
    if k <= 0:
        return 1.0
    return min(_math.floor(CRASH_STEP ** k * 100) / 100, CRASH_MAX_MULT)

def _crash_card_text(game, state="running", footer=""):
    bet, k, mult = game["bet"], game["k"], game["mult"]
    lines = ["🚀 <b>CRASH</b>", f"👤 {game['mention']} · 💵 <code>{format_star_plain(bet)}</code>", ""]
    if state == "running":
        if k >= 1:
            lines.append(f"📈 <b>{mult:.2f}x</b> → <code>{format_star_plain(round(bet * mult, 2))}</code>")
            lines += ["", "👇 <i>Cash out before it crashes!</i>"]
        else:
            lines += ["📈 <b>1.00x</b>", "", "🛫 <i>Launching… get ready to cash out!</i>"]
    elif state == "crashed":
        lines.append(f"💥 <b>CRASHED at {game['cp']:.2f}x</b>")
    else:
        lines.append(f"🏆 <b>Cashed out at {mult:.2f}x</b>")
    if footer:
        lines += ["", footer]
    return "\n".join(lines)

def _crash_buttons(user_id, game):
    if game["k"] >= 1:
        label = f"💰 Cash Out {format_star_plain(round(game['bet'] * game['mult'], 2))}"
    else:
        label = "🛫 Launching…"
    return [[Button.inline(label, data=f"crcash_{user_id}")]]

async def _crash_settle(user_id, game, outcome):
    """Moves the money for a finished round and builds its final card. The game must already be popped from active_crash_games.
    outcome: crash / cashout / cap / refund. Returns (text, buttons)."""
    bet = game["bet"]
    if outcome == "crash":
        win, state = 0.0, "crashed"
    elif outcome == "cap":
        game["mult"] = CRASH_MAX_MULT
        win, state = round(bet * CRASH_MAX_MULT, 2), "won"
    elif outcome == "cashout":
        win, state = round(bet * game["mult"], 2), "won"
    else:
        win, state = bet, "crashed"
    paid = True
    if win > 0:
        paid = await _casino_credit(user_id, win, "Crash")
        if not paid:
            logging.error(f"🚨 CRASH PAYOUT NOT CREDITED: user {user_id} is owed {win} (outcome {outcome}) — fix by hand.")
    if outcome == "refund":
        return "⚠️ The Crash round hit an error — your bet has been fully refunded.", None
    net = win - bet
    await casino_record_net(user_id, net)                     # 🏦 feeds the daily net-win ceiling
    net_emoji = "📈" if net > 0 else ("📉" if net < 0 else "➖")
    net_line = f"{net_emoji} <b>Net:</b> <code>{'+' if net >= 0 else ''}{format_star_plain(net)}</code>"
    if outcome == "crash":
        footer = f"💔 <b>The rocket crashed before you cashed out.</b>\n{net_line}"
    elif outcome == "cap":
        footer = f"🔥 <b>Max win reached — cashed out automatically!</b>\n{net_line}"
    else:
        footer = f"✅ <b>Safe landing!</b>\n{net_line}"
    if not paid:
        footer += f"\n\n⚠️ <b>The payout hit a database error</b> — <code>{format_star_plain(win)}</code> is owed to you. Screenshot this and message the owner."
    next_note = _casino_next_play_note(user_id)
    if next_note:
        footer += f"\n\n{next_note}"
    return _crash_card_text(game, state, footer), _game_result_buttons(user_id, bet, "crash")

async def _crash_finish_msg(user_id, game, outcome):
    """Runner-side ending (no tap involved): settle, then turn the rocket message into the result card."""
    text, buttons = await _crash_settle(user_id, game, outcome)
    client = bot1
    await _casino_edit_msg(client, game["chat_id"], game["msg_id"], text, buttons)

async def _crash_runner(user_id, game):
    try:
        while True:
            await asyncio.sleep(CRASH_TICK_SECONDS)
            if active_crash_games.get(user_id) is not game:
                return                                         # cashed out (or settled elsewhere) — nothing left to run
            game["k"] += 1                                     # ── no await from here down to the crash/cap decision ──
            m = _crash_mult(game["k"])
            if game["cp"] <= m:
                active_crash_games.pop(user_id, None)          # 🔒 commit the crash before any await
                return await _crash_finish_msg(user_id, game, "crash")
            game["mult"] = m
            if m >= CRASH_MAX_MULT:
                active_crash_games.pop(user_id, None)
                return await _crash_finish_msg(user_id, game, "cap")
            client = bot1
            try:
                await client.edit_message(game["chat_id"], game["msg_id"], _crash_card_text(game), parse_mode=_pm(client), buttons=_crash_buttons(user_id, game))
            except Exception as e:
                logging.error(f"❌ Crash tick edit failed for {user_id}: {e}")     # the round keeps running; the next tick tries again
    except Exception as e:
        logging.error(f"❌ Crash runner failed for {user_id}: {e}")
        if active_crash_games.get(user_id) is game:           # something broke mid-round — never keep a bet for a round that can't finish
            active_crash_games.pop(user_id, None)
            try:
                text, _ = await _crash_settle(user_id, game, "refund")
                client = bot1
                await _casino_edit_msg(client, game["chat_id"], game["msg_id"], text)
            except Exception as e2:
                logging.error(f"🚨 CRASH REFUND FAILED for {user_id} ({game.get('bet')}): {e2}")

async def _crash_refund_stale(user_id):
    """A round that outlived CRASH_STALE_SECONDS (its runner died) is refunded so the player isn't locked out. Never raises."""
    try:
        game = active_crash_games.pop(user_id, None)
        if game:
            await _crash_settle(user_id, game, "refund")
    except Exception as e:
        logging.error(f"❌ Crash stale refund failed for {user_id}: {e}")

async def _start_crash(event, user_id, bet, mention):
    """The bet is already deducted (see _casino_play). Raises BEFORE registering the round if the rocket card can't be sent, so the caller refunds."""
    game = {
        "bet": bet, "mention": mention, "chat_id": event.chat_id, "msg_id": None, "cp": _crash_point(),
        "k": 0, "mult": 1.0, "started": time.time(),
    }
    sent = await _casino_out(event, message=_crash_card_text(game), parse_mode='html', buttons=_crash_buttons(user_id, game))
    game["msg_id"] = sent.id
    active_crash_games[user_id] = game
    task = asyncio.create_task(_crash_runner(user_id, game))
    _CRASH_TASKS.add(task)
    task.add_done_callback(_CRASH_TASKS.discard)

async def crash_cash_cb(event):
    try:
        user_id = int(event.pattern_match.group(1))
    except Exception:
        return await _mines_answer(event)
    if event.sender_id != user_id:
        return await _mines_answer(event, "⚠️ That's not your game!", alert=True)
    game = active_crash_games.get(user_id)
    if not game or event.message_id != game["msg_id"]:
        return await _mines_answer(event, "💥 Too late — this round is already over.", alert=True)
    if game["k"] < 1:
        return await _mines_answer(event, "🛫 Hold on — the rocket hasn't lifted off yet!", alert=False)
    active_crash_games.pop(user_id, None)                     # 🔒 commit to cashing out — the runner now sees it's gone and stops
    await _mines_answer(event, f"💰 Cashed out at {game['mult']:.2f}x!")
    try:
        text, buttons = await _crash_settle(user_id, game, "cashout")
        try:
            await event.edit(text, parse_mode=_pm(event.client), buttons=buttons)
        except Exception as e:
            logging.error(f"❌ Crash result edit failed for {user_id}: {e}")
            await _casino_edit_msg(event.client, game["chat_id"], game["msg_id"], text, buttons)
    except Exception as e:
        logging.error(f"❌ Crash cash-out failed for {user_id}: {e}")

bot1.on(events.CallbackQuery(pattern=r'^crcash_(\d+)$'))(crash_cash_cb)

_CUSTOM_GAME_STARTERS = {"mines": _start_mines, "wheel": _start_wheel, "crash": _start_crash}   # games with their own flow — see _casino_play's dispatch

# ==========================================
# 🏦 DAILY NET-WIN CEILING per player (2026-10, per owner report — a player reached 10,000,000⭐ from 1,000⭐ in 2 days).
# ==========================================
CASINO_DAILY_NET_WIN_CAP = float(os.environ.get("CASINO_DAILY_NET_WIN_CAP", "1000000"))
casino_daily_col = db["casino_daily"]          # one tiny doc per player per day: _id "YYYY-MM-DD:user_id" -> {"net": ...}

def _casino_day():
    return datetime.now(TZ).strftime("%Y-%m-%d")

# 🩹 (2026-10, Render 5 GB/month outbound cap — casino plays are one of the busiest things the bot does): this used to send Mongo a find …
_CASINO_NET = {}      # user_id -> {"day": "YYYY-MM-DD", "net": float, "dirty": bool}

async def casino_net_today(user_id):
    day = _casino_day()
    e = _CASINO_NET.get(user_id)
    if e and e["day"] == day:
        return e["net"]
    doc = await casino_daily_col.find_one({"_id": f"{day}:{user_id}"})
    net = float(doc.get("net", 0) or 0) if doc else 0.0
    _CASINO_NET[user_id] = {"day": day, "net": net, "dirty": False}
    return net

async def casino_record_net(user_id, net):
    """Adds a finished game's net result (win − bet, negative for a loss) to the player's day total. Never raises into a game."""
    if user_id == OWNER_ID or not CASINO_DAILY_NET_WIN_CAP:
        return
    try:
        await casino_net_today(user_id)                     # makes sure today's entry is loaded
        e = _CASINO_NET[user_id]
        e["net"] += net
        e["dirty"] = True
    except Exception as ex:
        print(f"casino_record_net error ({user_id}): {ex}")

async def casino_net_flush_loop():
    while True:
        await asyncio.sleep(60)
        try:
            today = _casino_day()
            ops, flushed = [], []
            for uid, e in list(_CASINO_NET.items()):
                if e["dirty"]:
                    ops.append(UpdateOne({"_id": f"{e['day']}:{uid}"}, {"$set": {"net": round(e["net"], 2), "user_id": uid, "date": e["day"]}}, upsert=True))
                    flushed.append(e)
                elif e["day"] != today:
                    _CASINO_NET.pop(uid, None)              # yesterday's finished tally — drop it
            if ops:
                await casino_daily_col.bulk_write(ops, ordered=False)
                for e in flushed:
                    e["dirty"] = False
        except Exception as ex:
            print(f"casino_net_flush_loop error: {ex}")

async def casino_daily_cap_text(user_id):
    """None if this player may bet; otherwise the 'limit reached' message to show instead (no bet is taken)."""
    if user_id == OWNER_ID or not CASINO_DAILY_NET_WIN_CAP:
        return None
    try:
        net = await casino_net_today(user_id)
    except Exception as e:
        print(f"casino_daily_cap_text error ({user_id}): {e}")
        return None                                   # a DB hiccup must never lock honest players out
    if net < CASINO_DAILY_NET_WIN_CAP:
        return None
    return (f"🏦 <b>Daily winning limit reached</b> — you're up <code>{format_star_plain(round(net, 2))}</code> today.\n"
            f"<i>The casino opens for you again at midnight (Yangon time).</i>")

def _payout_and_status(game_key, value):
    """Returns (multiplier, tier) — tier is "jackpot"/"big"/"small"/"lose", used for both the
    reward math and picking which status line/wording to show. All three games decide
    everything from Telegram's own raw native-dice value (🩹 /slot is back to this too, 2026-09
    round 2 — see the paytable's revert note above)."""
    if game_key == "slot":
        if value == SLOT_JACKPOT_VALUE:
            return SLOT_JACKPOT_MULT, "jackpot"
        if value in SLOT_TRIPLE_VALUES:
            return SLOT_TRIPLE_MULT, "big"
        if value in SLOT_TWO_SEVENS_VALUES:
            return SLOT_TWO_SEVENS_MULT, "small"
        return 0, "lose"
    if game_key == "bball":
        if value in BBALL_IN_VALUES:
            return BBALL_MAKE_MULT, "big"
        return 0, "lose"
    if game_key == "dice":
        if value in DICE_WIN_VALUES:
            return DICE_WIN_MULT, "big"
        return 0, "lose"
    if game_key == "dart":
        if value == DART_BULLSEYE_VALUE:
            return DART_BULLSEYE_MULT, "jackpot"
        return 0, "lose"
    if game_key == "football":
        if value in FOOTBALL_GOAL_VALUES:
            return FOOTBALL_GOAL_MULT, "big"
        return 0, "lose"
    if game_key == "bowling":
        if value == BOWLING_STRIKE_VALUE:
            return BOWLING_STRIKE_MULT, "jackpot"
        return 0, "lose"
    return 0, "lose"

def _result_line(game_key, value):
    """The one line showing what actually happened — reel symbols for slot, a shot description
    for basketball, the rolled pip-face for dice."""
    if game_key == "slot":
        reels = _slot_decode(value)
        return " │ ".join(SLOT_SYMBOL_DISPLAY[r] for r in reels)
    if game_key == "bball":
        return {4: "🏀 In the hoop!", 5: "🏀 SWISH! Nothing but net"}.get(value, "🏀 Missed the hoop")
    if game_key == "dice":
        pip = {1: "⚀", 2: "⚁", 3: "⚂", 4: "⚃", 5: "⚄", 6: "⚅"}.get(value, str(value))
        return f"{pip} Rolled a {value}"
    if game_key == "dart":
        return DART_RESULT_LABELS.get(value, str(value))
    if game_key == "football":
        return {4: "⚽ GOAL!", 5: "⚽ GOAL! Right in the net"}.get(value, "🥅 No goal")
    if game_key == "bowling":
        if value == BOWLING_STRIKE_VALUE:
            return "🎳 STRIKE! Every pin down"
        if value == 1:
            return "💨 Missed every pin"
        return "🪵 Pins left standing — no strike"
    return str(value)

def _status_headline(tier, win, mult):
    if tier == "jackpot":
        return f"🔥 <b>JACKPOT!</b> +{format_star_plain(win)} <code>({mult}x)</code>"
    if tier == "big":
        return f"✨ <b>Big win! +{format_star_plain(win)}</b> <code>({mult}x)</code>"
    if tier == "small":
        return f"🎉 <b>+{format_star_plain(win)}</b> <code>({mult}x)</code>"
    return "💔 <b>No win this time</b>"

def _game_result_buttons(user_id, bet, game_key):
    row1 = [Button.inline(f"🔄 Play again ({format_star_plain(bet)})", data=f"cg_go_{game_key}_{user_id}_{bet}")]
    switch = [Button.inline(g["emoticon"], data=f"cg_go_{k}_{user_id}_{bet}") for k, g in GAMES.items() if k != game_key]
    preset_row = [Button.inline(f"{amt:,}⭐", data=f"cg_go_{game_key}_{user_id}_{amt}") for amt in SLOT_BET_PRESETS[:3]]
    # 🩹 2026-11: with 8 games the "play again + every other game" row would be 8 buttons wide (Telegram's hard limit, and unreadable) — switch buttons now wrap 4 per row.
    return [row1] + _chunk_buttons(switch, 4) + [preset_row]

async def _casino_out(event, **kwargs):
    """Send a casino-flow / wallet message through the event's own client. Accepts file= too (native
    dice, banners). If Telegram refuses the premium-emoji layer, the SAME message is retried with plain emoji."""
    chat_id = event.chat_id
    client = event.client
    try:
        return await client.send_message(chat_id, **kwargs)
    except Exception as e_pe:
        if kwargs.get("parse_mode") is not PREMIUM_HTML or isinstance(e_pe, _CASINO_GONE_ERRORS):
            raise
        print(f"⚠️ Premium-emoji send failed in {chat_id} ({e_pe}); retrying with plain emoji")
        _retry_file = kwargs.get("file")
        if hasattr(_retry_file, "seek"):
            _retry_file.seek(0)
        return await client.send_message(chat_id, **dict(kwargs, parse_mode='html'))

async def _casino_banner_media():
    """The owner-set image/video shown above every game's menu and result card — shared across
    slot/basketball/dice (see /addslotbanner). Same reply-to-media storage trick as /addbalance's
    wallet banner: the media is forwarded once into SPECIFIC_CONTROL_GROUP and only its
    message_id is kept. Returns None if none is set or it couldn't be fetched, in which case
    callers just send text-only."""
    banner_doc = await bot_settings_col.find_one({"_id": "slot_banner"})
    storage_msg_id = banner_doc.get("storage_msg_id") if banner_doc else None
    if not storage_msg_id:
        return None
    try:
        storage_msg = await bot1.get_messages(SPECIFIC_CONTROL_GROUP, ids=storage_msg_id)
        return storage_msg.media if (storage_msg and storage_msg.media) else None
    except Exception:
        return None

async def _casino_edit_or_send(event, user_id, text, buttons, banner, ephemeral_after=None):
    """Edits the player's existing result message in this chat; sends a fresh one (banner re-attached) only if there's no usable session, it's stale (DICE_SESSION_MAX_AGE), reused CASINO_SESSION_MAX_PLAYS times, or the edit fails - the old message is deleted first. Returns the msg_id used."""
    chat_id = event.chat_id
    session_key = (user_id, chat_id)
    session = active_dice_sessions.get(session_key)
    # 🩹 CHANGED (2026-10, per owner report — "/dice amount လုပ်တာတောင် result က အပေါ်မှာသွားပေါ်နေတယ်၊ လူတွေမသိဘူး"): a TYPED …
    typed = not isinstance(event, events.CallbackQuery.Event)
    if (not typed) and session and (time.time() - session["ts"]) < DICE_SESSION_MAX_AGE and session.get("plays", 0) < CASINO_SESSION_MAX_PLAYS:
        client = bot1
        try:
            await client.edit_message(chat_id, session["msg_id"], text, parse_mode=_pm(client), buttons=buttons)
            session["ts"] = time.time()
            session["plays"] = session.get("plays", 0) + 1
            return session["msg_id"]
        except errors.MessageNotModifiedError:
            # 🩹 2026-10: same text again (e.g. a resting player re-tapping within the same second) is NOT a
            # failure — the message already shows exactly this. It used to fall through to the delete + fresh
            # send below, which is the very spam the edit-in-place design exists to prevent.
            return session["msg_id"]
        except Exception:
            pass  # stale/deleted/too-old-to-edit/rate-limited — fall through to a fresh send below

    if session:
        # 🗑️ Retiring this message (cap hit, stale, or the edit above just failed) — delete it
        # outright instead of leaving it behind. Best-effort: it may already be gone (a player
        # deleted it themselves, or it's too old for the bot to touch), which isn't an error
        # worth logging, just a no-op here.
        old_client = bot1
        try:
            await old_client.delete_messages(chat_id, [session["msg_id"]])
        except Exception:
            pass

    send_kwargs = {"message": text, "parse_mode": 'html', "buttons": buttons}
    if banner:
        send_kwargs["file"] = banner
    result_msg = None
    if typed:
        try:    # as a reply to the player's command, so it's clear what it answers
            result_msg = await _casino_out(event, **dict(send_kwargs, reply_to=event.id))
        except Exception:
            result_msg = None    # e.g. the command message was deleted meanwhile — post it without the reply instead
    if result_msg is None:
        result_msg = await _casino_out(event, **send_kwargs)
    active_dice_sessions[session_key] = {"msg_id": result_msg.id, "ts": time.time(), "plays": 1}
    if typed and ephemeral_after and not event.is_private:
        schedule_game_cleanup(event.client, chat_id, result_msg.id, delay=ephemeral_after)
    return result_msg.id

async def _casino_play(event, user_id, bet, mention, game_key):
    """One complete spin/roll/shot: validate -> deduct bet -> send native dice -> resolve result -> pay out -> summary + buttons (editing the existing result message when possible). Shared by every game's command and button; /rps shares the validate/deduct steps, then branches to _start_rps_reveal. No play fee or whale tax - each paytable is the only house edge."""
    # 🛡️ (2026-10, spam guard v2) a spam-muted player is ignored by the casino — no reply, no bet taken. (A tapped button just stops spinning.)
    if is_spam_muted(user_id):
        if isinstance(event, events.CallbackQuery.Event):
            try:
                await event.answer()
            except Exception:
                pass
        return None
    game = GAMES[game_key]
    chat_id = event.chat_id
    back_btn = [[Button.inline("🔙 Back", data="nav_back_home")]]

    # 🪨📄✂️ Guard BEFORE any validation/deduction below — a second bet must never stack on top
    # of an unfinished round for the same user (see active_rps_games's own BotState comment).
    if game_key == "rps" and user_id in active_rps_games:
        text = "⏳ You've already got a Rock Paper Scissors round in progress — finish that one first."
        return await _casino_edit_or_send(event, user_id, text, back_btn, None, ephemeral_after=CASINO_NOTICE_LIFETIME)

    # 💣 Same guard for Mines. A leftover round whose timer never fired (older than its expiry + 30s) is settled right here instead of locking the player out.
    if game_key == "mines":
        _old_round = active_mines_games.get(user_id)
        if _old_round and not _old_round.get("busy") and time.time() > _old_round.get("expiry", 0) + 30:
            await _mines_expire(user_id, _old_round.get("expiry"))
        if user_id in active_mines_games:
            text = "⏳ You've already got a Mines round in progress — finish it (or cash out) first."
            return await _casino_edit_or_send(event, user_id, text, back_btn, None, ephemeral_after=CASINO_NOTICE_LIFETIME)

    # 🚀 / 🎡 same idea: one Crash round per player (a round whose runner died is refunded instead of locking them out), and no second wheel bet mid-spin.
    if game_key == "crash":
        _old_rocket = active_crash_games.get(user_id)
        if _old_rocket and time.time() - _old_rocket.get("started", 0) > CRASH_STALE_SECONDS:
            await _crash_refund_stale(user_id)
        if user_id in active_crash_games:
            text = "⏳ You've already got a Crash round in progress — cash out of that one first."
            return await _casino_edit_or_send(event, user_id, text, back_btn, None, ephemeral_after=CASINO_NOTICE_LIFETIME)
    if game_key == "wheel" and user_id in _WHEEL_SPINNING:
        text = "🎡 Your wheel is still spinning — let it land first."
        return await _casino_edit_or_send(event, user_id, text, back_btn, None, ephemeral_after=CASINO_NOTICE_LIFETIME)

    # 🚦 Anti-spam cooldown — BEFORE any validation, so a resting player mashing the button or retyping
    # /slot with junk amounts still can't slip a fresh message through. Two layers (see the constants above):
    # an optional rest after every play (CASINO_PLAY_GAP_SECONDS, 0 = off) and the break after every CASINO_COOLDOWN_TRIGGER plays. This also TAKES
    # the play slot right away (synchronously), and every early exit below gives it back via _bail — a typo or a
    # too-small balance never costs anyone their minute.
    blocked, remaining, kind, play_snapshot = _reserve_casino_play(user_id)
    if blocked:
        if not _casino_should_notify_block(user_id):
            return  # told them a moment ago — stay quiet rather than edit/send again
        return await _casino_edit_or_send(event, user_id, _casino_block_text(mention, remaining, kind), back_btn, None,
                                          ephemeral_after=CASINO_NOTICE_LIFETIME)

    async def _bail(text):
        _release_casino_play(user_id, play_snapshot)
        return await _casino_edit_or_send(event, user_id, text, back_btn, None, ephemeral_after=CASINO_NOTICE_LIFETIME)

    if bet < SLOT_MIN_BET:
        return await _bail(f"❌ Bet at least {SLOT_MIN_BET}⭐.")
    if bet > SLOT_MAX_BET:
        return await _bail(f"❌ You can only bet up to {SLOT_MAX_BET:,}⭐ per play.")

    user_doc = await users_catcher_col.find_one({"user_id": user_id})
    balance = user_doc.get("star_balance", 0) if user_doc else 0
    if balance < bet:
        return await _bail(f"❌ You only have {format_star_plain(balance)}.")

    _cap_text = await casino_daily_cap_text(user_id)          # 🏦 daily net-win ceiling — refused BEFORE any bet is taken
    if _cap_text:
        return await _bail(_cap_text)

    if not await try_deduct_bet_bot3(event, user_id, bet):
        _release_casino_play(user_id, play_snapshot)
        return  # try_deduct_bet_bot3 already sent the AML-jail/bust or balance message itself
    await bot3_treasury_adjust(usd=bet)

    if game_key == "rps":
        return await _start_rps_reveal(event, user_id, bet, mention)

    if game_key in _CUSTOM_GAME_STARTERS:
        try:
            return await _CUSTOM_GAME_STARTERS[game_key](event, user_id, bet, mention)
        except Exception as e:
            # The opening card never reached the player (these starters raise before registering anything) — give the whole bet back.
            await users_catcher_col.update_one({"user_id": user_id}, {"$inc": {"star_balance": bet}})
            await bot3_treasury_adjust(usd=-bet)
            print(f"❌ /{game_key} opening card failed to send, refunded {user_id}: {e}")
            return await _bail("⚠️ The game engine hiccuped — your bet's been refunded, please try again.")

    # 🎲 THE actual native Telegram animation — this is what the player sees play out.
    try:
        dice_msg = await _casino_out(event, file=types.InputMediaDice(emoticon=game["emoticon"]))
        value = dice_msg.media.value
    except Exception as e:
        # Refund everything taken so far — never eat a bet if we couldn't even show the roll.
        await users_catcher_col.update_one({"user_id": user_id}, {"$inc": {"star_balance": bet}})
        await bot3_treasury_adjust(usd=-bet)
        print(f"❌ /{game_key} dice send failed, refunded {user_id}: {e}")
        text = "⚠️ The game engine hiccuped — your bet's been refunded, please try again."
        return await _bail(text)

    # 🩹 The result is already decided server-side and sitting in `value` right now — this
    # sleep is PURELY cosmetic, so the result card lands right as Telegram's own client-side
    # animation visually finishes instead of appearing while it's still playing.
    await asyncio.sleep(game["anim_delay"])

    mult, tier = _payout_and_status(game_key, value)
    win = round(bet * mult, 2) if mult else 0
    if win > 0:
        await users_catcher_col.update_one({"user_id": user_id}, {"$inc": {"star_balance": win}})
        await bot3_treasury_adjust(usd=-win)
    net = win - bet
    await casino_record_net(user_id, net)                     # 🏦 feeds the daily net-win ceiling

    result_line = _result_line(game_key, value)
    status_line = _status_headline(tier, win, mult)
    net_emoji = "📈" if net > 0 else ("📉" if net < 0 else "➖")
    # 🩹 CHANGED (per owner report — "the ━━━ dividers aren't pretty"): no more divider lines —
    # a plain, compact card, matching the style /check moved to.
    text = (
        f"{game['emoticon']} <b>{game['name']}</b>\n"
        f"👤 {mention} · 💵 <code>{format_star_plain(bet)}</code>\n\n"
        f"<b>{result_line}</b>\n\n"
        f"{status_line}\n"
        f"{net_emoji} <b>Net:</b> <code>{'+' if net >= 0 else ''}{format_star_plain(net)}</code>"
    )
    next_note = _casino_next_play_note(user_id)   # ⏳ "Next play in …" / 😮‍💨 long-break notice
    if next_note:
        text += f"\n\n{next_note}"
    banner = await _casino_banner_media()
    await _casino_edit_or_send(event, user_id, text, _game_result_buttons(user_id, bet, game_key), banner)

    # 🩹 The public group announcement below is deliberately reserved for genuinely RARE wins …
    if game_key == "slot" and tier == "jackpot":
        await _casino_out(event, message=f"🔥 {mention} hit the {game['name']} Jackpot — <b>{format_star_plain(win)}</b>!", parse_mode='html')

    # 🩹 Only the native dice ANIMATION message gets auto-deleted — the result card is now
    # reused via edit (see _casino_edit_or_send), so it's never piling up the way repeat fresh
    # sends used to.
    if not event.is_private:
        schedule_game_cleanup(event.client, chat_id, dice_msg.id, delay=20)

async def _game_cmd_handler(event, game_key):
    if is_duplicate_event(event): return
    user_id = event.sender_id
    bet_str = event.pattern_match.group(1)
    mention = await get_html_mention(event, user_id)
    # 🛡️ (2026-10, spam guard v2) a spam-muted player is ignored by the casino — no reply, no bet taken. (A tapped button just stops spinning.)
    if is_spam_muted(user_id):
        if isinstance(event, events.CallbackQuery.Event):
            try:
                await event.answer()
            except Exception:
                pass
        return None
    game = GAMES[game_key]

    if not bet_str:
        # 🩹 FIX (per owner report — "if someone spams the /slot command it becomes spam"):
        text = (
            f"{game['emoticon']} <b>{game['name']}</b>\n\n"
            f"{bold_italic_serif('Reply with your')} ⭐ {bold_italic_serif('Star Amount, bro / sis!')}\n"
            f"<i>Min {SLOT_MIN_BET}⭐, max {SLOT_MAX_BET:,}⭐</i>"
        )
        banner = await _casino_banner_media()
        msg_id = await _casino_edit_or_send(event, user_id, text, [[Button.inline("🔙 Back", data="nav_back_home")]], banner)
        pending_casino_bet[user_id] = {
            "chat_id": event.chat_id, "prompt_msg_id": msg_id, "game_key": game_key,
            "expiry": time.time() + CASINO_BET_PROMPT_TTL,
        }
        return

    try:
        bet = round(float(bet_str), 2)
    except ValueError:
        text = f"❌ Enter a valid number — e.g. <code>{game['example']}</code>"
        return await _casino_edit_or_send(event, user_id, text, [[Button.inline("🔙 Back", data="nav_back_home")]], None,
                                          ephemeral_after=CASINO_NOTICE_LIFETIME)

    await _casino_play(event, user_id, bet, mention, game_key)

# ==========================================
# 🎮 /casino — menu-driven entry point (per owner request), separate from typing /slot, …
# ==========================================
CASINO_WELCOME_BONUS = 50_000  # ⭐ one-time, first /casino visit ever — see the atomic claim below
CASINO_BET_PROMPT_TTL = 300     # seconds the "reply with your bet" prompt stays valid

def _casino_menu_buttons(user_id):
    game_row = [Button.inline(g["emoticon"], data=f"cgmenu_{k}_{user_id}") for k, g in GAMES.items()]
    # 🩹 NEW (2026-09, per owner request): 🃏 Card Game alongside the 3 vs-the-house games — not …
    game_row.append(Button.inline("🃏", data=f"cgmenu_cardgame_{user_id}"))
    # 🩹 2026-11: 8 games + the card game = 9 buttons — one more than Telegram allows in a single row, so the picker wraps 4 per row.
    return _chunk_buttons(game_row, 4) + [[Button.inline("🔙 Back", data="nav_back_home")]]

@bot1.on(events.NewMessage(pattern=own_pattern(r'(?i)^[/.]casino(?:@\w+)?$', 'bot1')))
async def casino_menu_cmd(event):
    if is_duplicate_event(event): return
    user_id = event.sender_id
    mention = await get_html_mention(event, user_id)

    # 🎉 One-time welcome bonus — atomic claim (find_one_and_update), same pattern as the
    # VIP daily Star gift's date-gated claim elsewhere in this file, just with a boolean
    # flag instead of a date since this only ever fires once per account, not once per day.
    claimed = await users_catcher_col.find_one_and_update(
        {"user_id": user_id, "casino_welcome_claimed": {"$ne": True}},
        {"$set": {"casino_welcome_claimed": True}}
    )
    bonus_line = ""
    if claimed:
        await users_catcher_col.update_one({"user_id": user_id}, {"$inc": {"star_balance": CASINO_WELCOME_BONUS}})
        bonus_line = f"🎉 {bold_italic_serif('Welcome to the casino!')} +{format_star_plain(CASINO_WELCOME_BONUS)} {bold_italic_serif('is on the house — good luck!')}\n\n"

    text = (
        f"{bonus_line}"
        f"{bold_italic_serif('Wanna grow your')} ⭐ {bold_italic_serif('Stars by playing games?')}\n"
        f"{bold_italic_serif('Try these games below!')} 🎮"
    )
    banner = await _casino_banner_media()
    send_kwargs = {"message": text, "parse_mode": 'html', "buttons": _casino_menu_buttons(user_id)}
    if banner:
        send_kwargs["file"] = banner
    await _casino_out(event, **send_kwargs)

async def casino_menu_pick_cb(event):
    game_key = event.pattern_match.group(1)
    if isinstance(game_key, bytes):
        game_key = game_key.decode('utf-8')
    owner_user_id = int(event.pattern_match.group(2))
    # 🩹 (per owner request) — only the person who opened /casino can use these buttons.
    if event.sender_id != owner_user_id:
        return await event.answer("⚠️ That's not your Casino menu — run /casino yourself.", alert=True)
    if not claim_single_tap(event):
        return await event.answer("⏳ Hang on", alert=False)

    # 🃏 NEW (2026-09, per owner request) — PVP, not vs-house, so it's not in GAMES and doesn't …
    if game_key == "cardgame":
        if event.is_private:
            return await event.answer(
                f"🃏 Card Game can only be played in a group — needs at least {CARDGAME_MIN_PLAYERS} players.",
                alert=True
            )
        text = (
            f"🃏 <b>CARD GAME</b>\n\n"
            f"{bold_italic_serif('Reply with your')} ⭐ {bold_italic_serif('Star Amount, bro / sis!')}\n"
            f"<i>Highest unique card 1-10 wins — {CARDGAME_MIN_PLAYERS}-{CARDGAME_MAX_PLAYERS} players</i>\n"
            f"<i>Min {CARDGAME_MIN_BET}⭐, max {CARDGAME_MAX_BET:,}⭐</i>"
        )
        await event.edit(text, parse_mode=_pm(event.client), buttons=[[Button.inline("🔙 Back", data="nav_back_home")]])
        await event.answer()
        msg = await event.get_message()
        pending_casino_bet[owner_user_id] = {
            "chat_id": event.chat_id, "prompt_msg_id": msg.id, "game_key": "cardgame",
            "expiry": time.time() + CASINO_BET_PROMPT_TTL,
        }
        return

    # 🛡️ (2026-10, spam guard v2) a spam-muted player is ignored by the casino — no reply, no bet taken. (A tapped button just stops spinning.)
    if is_spam_muted(owner_user_id):
        if isinstance(event, events.CallbackQuery.Event):
            try:
                await event.answer()
            except Exception:
                pass
        return None
    game = GAMES[game_key]
    text = (
        f"{game['emoticon']} <b>{game['name']}</b>\n\n"
        f"{bold_italic_serif('Reply with your')} ⭐ {bold_italic_serif('Star Amount, bro / sis!')}\n"
        f"<i>Min {SLOT_MIN_BET}⭐, max {SLOT_MAX_BET:,}⭐</i>"
    )
    await event.edit(text, parse_mode=_pm(event.client), buttons=[[Button.inline("🔙 Back", data="nav_back_home")]])
    await event.answer()

    # 🩹 Pre-seeds the edit-in-place session to point at THIS message, so when the reply below …
    msg = await event.get_message()
    chat_id = event.chat_id
    # 🩹 "plays": 0 — this pre-seed itself doesn't count as a play; the counter starts moving
    # once _casino_edit_or_send below is actually asked to show a real result (see
    # CASINO_SESSION_MAX_PLAYS).
    active_dice_sessions[(owner_user_id, chat_id)] = {"msg_id": msg.id, "ts": time.time(), "plays": 0}
    pending_casino_bet[owner_user_id] = {
        "chat_id": chat_id, "prompt_msg_id": msg.id, "game_key": game_key,
        "expiry": time.time() + CASINO_BET_PROMPT_TTL,
    }

_CG_GAME_KEYS = "|".join(GAMES)       # built from GAMES itself, so a game added there can never be forgotten in these two patterns
bot1.on(events.CallbackQuery(pattern=rf'^cgmenu_({_CG_GAME_KEYS}|cardgame)_(\d+)$'))(casino_menu_pick_cb)

@bot1.on(events.NewMessage(incoming=True))
async def casino_bet_reply_handler(event):
    user_id = event.sender_id
    state = pending_casino_bet.get(user_id)
    if not state:
        return
    if not event.is_reply or event.chat_id != state["chat_id"] or event.reply_to_msg_id != state["prompt_msg_id"]:
        return
    if is_duplicate_event(event): return
    if time.time() > state["expiry"]:
        pending_casino_bet.pop(user_id, None)
        return await event.reply("⏳ That expired — run /casino again.", parse_mode='html')

    raw = (event.raw_text or "").strip()
    try:
        bet = round(float(raw), 2)
    except ValueError:
        return await event.reply("❌ Reply to this with a valid number — e.g. <code>500</code>", parse_mode='html')

    game_key = state["game_key"]
    pending_casino_bet.pop(user_id, None)
    if game_key == "cardgame":
        return await _start_cardgame_lobby(event, bet)
    mention = await get_html_mention(event, user_id)
    await _casino_play(event, user_id, bet, mention, game_key)

