# ==========================================
# 🏹 HUNT — FULL REBUILD (2026-11, per owner request: "Useless command ဖြစ်နေတယ် … တစ်ခုခုကို အမဲလိုက်သလို လုပ်သင့်တယ်")
# ==========================================
HUNT_COOLDOWN = 240                 # seconds between hunts (counted from the moment a hunt STARTS)
HUNT_COOLDOWN_VIP = 150
HUNT_DAILY_LIMIT = 15               # hunts per day (resets at midnight, bot timezone)
HUNT_DAILY_LIMIT_VIP = 25
HUNT_IDLE_TTL = 90                  # seconds a hunt waits for the next tap before the prey wanders off
HUNT_MAX_FOCUS = 3                  # 0 = standing in the open … 3 = point-blank
HUNT_HIT_CHANCE = (0.42, 0.52, 0.64, 0.78)      # hit chance at focus 0..3 (was 0.50/0.65/0.80/0.92 — too easy)
HUNT_REWARD_MULT = (1.0, 1.1, 1.2, 1.3)         # prize multiplier at focus 0..3
HUNT_FLEE_SCALE = (1.0, 1.4, 1.9)               # × the prey's flee chance, for the stalk step focus 0→1, 1→2, 2→3
HUNT_PAYOUT_MIN = 3_000             # a winning hunt ALWAYS pays inside this band, whatever the bonuses (owner request)
HUNT_PAYOUT_MAX = 9_000
HUNT_MIN_BALANCE = 3_000            # ⭐ you must hold at least this to start a hunt — a failed hunt costs ⭐, so there has to be something to lose
HUNT_FLEE_LOSS_SHARE = 0.6          # a bolt costs this share of the prey's miss-penalty (a miss costs the full amount)
HUNT_STREAK_BONUS_PER = 0.05        # +5% prize per kill already chained …
HUNT_STREAK_BONUS_CAP = 0.50        # … up to +50%
HUNT_VIP_REWARD_MULT = 1.15
HUNT_TIERS = {
    # flee = chance the prey bolts on the FIRST stalk step (scaled up on later steps) · reward = base ⭐ prize range · loss = ⭐ lost on a miss
    # vlt = (drop chance, (min, max) 💠)
    "COMMON":    {"label": "COMMON",    "dot": "🟢", "weight": 50, "flee": 0.12, "reward": (3000, 3600), "loss": (2600, 3600),   "vlt": None,
                  "prey": [("🐇", "Wild Rabbit"), ("🦆", "Marsh Duck"), ("🐗", "Wild Boar"), ("🐓", "Jungle Fowl")]},
    "UNCOMMON":  {"label": "UNCOMMON",  "dot": "🔵", "weight": 28, "flee": 0.16, "reward": (3400, 4400), "loss": (3000, 4200),  "vlt": None,
                  "prey": [("🦌", "Red Stag"), ("🦊", "Silver Fox"), ("🐆", "Clouded Leopard"), ("🦏", "Plains Rhino")]},
    "RARE":      {"label": "RARE",      "dot": "🟣", "weight": 14, "flee": 0.21, "reward": (4000, 5200), "loss": (3400, 4600),  "vlt": None,
                  "prey": [("🐺", "Dire Wolf"), ("🦅", "Storm Eagle"), ("🐊", "Swamp Crocodile"), ("🦈", "River Shark")]},
    "EPIC":      {"label": "EPIC",      "dot": "🟠", "weight": 6,  "flee": 0.27, "reward": (5000, 6400), "loss": (4000, 5400),  "vlt": (0.05, (0.2, 0.6)),
                  "prey": [("🐻", "Ancient Bear"), ("🐅", "Shadow Tiger"), ("🦬", "Thunder Bison"), ("🦍", "Silverback Titan")]},
    "LEGENDARY": {"label": "LEGENDARY", "dot": "🔴", "weight": 2,  "flee": 0.33, "reward": (6000, 7200), "loss": (4800, 6400),  "vlt": (0.25, (0.5, 1.5)),
                  "prey": [("🐲", "Jade Dragon"), ("🦄", "Moonlit Unicorn"), ("🦉", "Spirit Owl"), ("🐘", "Mammoth King")]},
}
HUNT_BIOMES = [("🌲", "Mistwood Forest"), ("🏔️", "Frostpeak Ridge"), ("🌾", "Golden Savanna"),
               ("🌴", "Emerald Jungle"), ("🏜️", "Dune Sea"), ("🌋", "Ashfall Crater"), ("🌊", "Tidal Marsh")]
HUNT_MOODS = ("It hasn't noticed you yet.", "Its ears twitch — it senses something.",
              "It sniffs the air, muscles tense.", "One wrong step and it bolts!")
pending_hunts = {}   # hunt_id -> live session (in-memory only: a restart simply lets the prey wander off — and costs nobody anything)

def hunt_hit_chance(focus):
    return HUNT_HIT_CHANCE[max(0, min(int(focus), HUNT_MAX_FOCUS))]

def hunt_reward_mult(focus):
    return HUNT_REWARD_MULT[max(0, min(int(focus), HUNT_MAX_FOCUS))]

def hunt_flee_chance(tier, focus):
    """Chance the prey bolts when you STALK from `focus` to focus+1 (0 once you're already point-blank)."""
    if focus >= HUNT_MAX_FOCUS:
        return 0.0
    return min(0.85, HUNT_TIERS[tier]["flee"] * HUNT_FLEE_SCALE[int(focus)])

def hunt_streak_bonus(streak):
    return min(max(int(streak), 0) * HUNT_STREAK_BONUS_PER, HUNT_STREAK_BONUS_CAP)

def hunt_roll_prey():
    tiers = list(HUNT_TIERS)
    tier = random.choices(tiers, weights=[HUNT_TIERS[t]["weight"] for t in tiers], k=1)[0]
    cfg = HUNT_TIERS[tier]
    emoji, name = random.choice(cfg["prey"])
    return {"tier": tier, "emoji": emoji, "name": name,
            "base": random.randint(*cfg["reward"]), "loss": random.randint(*cfg["loss"])}

def hunt_focus_bar(focus):
    return "▰" * int(focus) + "▱" * (HUNT_MAX_FOCUS - int(focus))

def hunt_payout(st, focus):
    """The exact ⭐ a hit pays at this focus — streak + vip included, then hard-clamped into the owner's 3,000–9,000 band."""
    prem = HUNT_VIP_REWARD_MULT if st.get("vip") else 1.0
    raw = st["base"] * hunt_reward_mult(focus) * (1 + hunt_streak_bonus(st.get("streak", 0))) * prem
    return int(max(HUNT_PAYOUT_MIN, min(HUNT_PAYOUT_MAX, round(raw))))

def hunt_fail_loss(st, kind):
    """⭐ a failed hunt costs BEFORE the can't-lose-more-than-you-hold cap: a miss = the full penalty, a bolt = HUNT_FLEE_LOSS_SHARE of it."""
    return int(st["loss"]) if kind == "miss" else int(round(st["loss"] * HUNT_FLEE_LOSS_SHARE))
# --- /HUNT PURE LOGIC ---

async def _hunt_take_stars(uid, amount):
    """Take up to `amount`⭐ from a player. NEVER more than they hold and never below zero (no negative balance, no debt created) —
    the deduction is a conditional atomic $inc ({star_balance: {$gte: take}}), retried if their balance moved in between. Returns what was actually taken."""
    amount = int(amount)
    if amount <= 0:
        return 0
    for _ in range(3):
        doc = await users_catcher_col.find_one({"user_id": uid}, {"star_balance": 1})
        bal = float((doc or {}).get("star_balance", 0) or 0)
        take = min(amount, int(bal))
        if take <= 0:
            return 0
        res = await users_catcher_col.update_one({"user_id": uid, "star_balance": {"$gte": take}},
                                                 {"$inc": {"star_balance": -take, "hunt_total_lost": take}})
        if getattr(res, "modified_count", 0) == 1:
            return take
    return 0

def _hunt_active_text(st, note=None):
    cfg = HUNT_TIERS[st["tier"]]
    f = st["focus"]
    mult = hunt_reward_mult(f)
    prize = hunt_payout(st, f)
    hit = int(round(hunt_hit_chance(f) * 100))
    flee = int(round(hunt_flee_chance(st["tier"], f) * 100))
    head = f"🏹 <b>{sans_bold_italic('Hunt')}</b>\n   {small_caps_full('stalk closer or take the shot')}\n\n"
    if st["tier"] in ("EPIC", "LEGENDARY"):
        head += f"🚨 <b>{small_caps_full('rare sighting')}</b> 🚨\n\n"
    tags = []
    sb = hunt_streak_bonus(st.get("streak", 0))
    if sb > 0:
        tags.append(f"🔥+{int(round(sb * 100))}%")
    if st.get("vip"):
        tags.append(f"👑+{int(round((HUNT_VIP_REWARD_MULT - 1) * 100))}%")
    stats = (f"🐾 {small_caps_full('focus')}: <code>{hunt_focus_bar(f)}</code> {f}/{HUNT_MAX_FOCUS}\n"
             f"🎯 {small_caps_full('hit chance')}: <code>{hit}%</code>\n"
             f"💰 {small_caps_full('prize')}: <code>{prize:,}⭐</code> (×{mult:g}{' ' + ' '.join(tags) if tags else ''})\n"
             f"💸 {small_caps_full('if you miss')}: <code>−{hunt_fail_loss(st, 'miss'):,}⭐</code>")
    if f < HUNT_MAX_FOCUS:
        stats += (f"\n⚠️ {small_caps_full('flee risk if you stalk')}: <code>{flee}%</code> "
                  f"(<code>−{hunt_fail_loss(st, 'flee'):,}⭐</code>)")
    text = (f"{head}👤 {st['mention']}\n"
            f"{st['biome'][0]} {small_caps_full('zone')}: <b>{st['biome'][1]}</b>\n\n"
            f"<blockquote>{st['emoji']} <b>{st['name']}</b> · {cfg['dot']} {small_caps_full(cfg['label'].lower())}\n"
            f"<i>{HUNT_MOODS[f]}</i></blockquote>\n"
            f"<blockquote>{stats}</blockquote>\n"
            f"<i>{small_caps_full('you can only lose what you hold')}</i>")
    if st.get("streak", 0) > 0:
        text += f"\n🔥 {small_caps_full('kill streak')}: <b>{st['streak']}</b>"
    if note:
        text += f"\n{note}"
    return text

def _hunt_buttons(st):
    f, hid, step = st["focus"], st["id"], st["step"]
    hit = int(round(hunt_hit_chance(f) * 100))
    row = [colored_button(f"🎯 {'Final shot' if f >= HUNT_MAX_FOCUS else 'Shoot'} · {hit}%", f"hunt_shoot_{hid}_{step}", color="success")]
    if f < HUNT_MAX_FOCUS:
        flee = int(round(hunt_flee_chance(st["tier"], f) * 100))
        row.append(colored_button(f"🐾 Stalk · {flee}% flee", f"hunt_stalk_{hid}_{step}", color="primary"))
    return [row]

def _hunt_footer(st):
    return (f"\n\n🕐 {small_caps_full('next hunt')}: <code>{st['cooldown']}s</code> · "
            f"🗓 {small_caps_full('today')}: <code>{st['today']}/{st['limit']}</code>")

def _hunt_loss_line(st, kind, lost):
    """The 💸 line of a failed hunt — says plainly when the cap kicked in (the player simply didn't hold the full penalty)."""
    wanted = hunt_fail_loss(st, kind)
    if lost <= 0:
        return f"💸 {small_caps_full('you had nothing to lose')}"
    line = f"💸 {small_caps_full('lost')}: <code>−{lost:,}⭐</code>"
    if lost < wanted:
        line += f" <i>({small_caps_full('all you had')})</i>"
    return line

def _hunt_result_text(st, kind, payout=0, vlt=0.0, extra="", lost=0):
    cfg = HUNT_TIERS[st["tier"]]
    f = st["focus"]
    prey_line = (f"<blockquote>{st['emoji']} <b>{st['name']}</b> · {cfg['dot']} {small_caps_full(cfg['label'].lower())}\n"
                 f"{st['biome'][0]} {st['biome'][1]} · 🐾 <code>{hunt_focus_bar(f)}</code> {f}/{HUNT_MAX_FOCUS}</blockquote>\n")
    if kind == "win":
        title = f"🌟 <b>{sans_bold_italic('Legendary Kill!')}</b>" if st["tier"] == "LEGENDARY" else f"✅ <b>{sans_bold_italic('Prey Down!')}</b>"
        body = f"⭐ <code>+{payout:,}</code>"
        if vlt:
            body += f"\n💠 <code>+{vlt:g}</code> {small_caps_full('rare drop')}!"
        bonus = []
        sb = hunt_streak_bonus(st.get("streak", 0))
        if sb > 0:
            bonus.append(f"🔥 +{int(round(sb * 100))}%")
        if st.get("vip"):
            bonus.append(f"👑 +{int(round((HUNT_VIP_REWARD_MULT - 1) * 100))}%")
        if bonus:
            body += f"\n{small_caps_full('bonus')}: " + " · ".join(bonus)
        body += f"\n🔥 {small_caps_full('kill streak')}: <b>{st.get('streak', 0) + 1}</b>"
        return (f"{title}\n\n👤 {st['mention']}\n{prey_line}<blockquote>{body}</blockquote>" + extra + _hunt_footer(st))
    if kind == "miss":
        return (f"💨 <b>{sans_bold_italic('Missed!')}</b>\n   {small_caps_full('the prey fought back')}\n\n👤 {st['mention']}\n{prey_line}"
                f"<blockquote>{_hunt_loss_line(st, 'miss', lost)}\n"
                f"🔥 {small_caps_full('kill streak reset')}</blockquote>" + _hunt_footer(st))
    if kind == "flee":
        return (f"🏃 <b>{sans_bold_italic('It Bolted!')}</b>\n   {small_caps_full('you got too greedy')}\n\n👤 {st['mention']}\n{prey_line}"
                f"<blockquote>{_hunt_loss_line(st, 'flee', lost)}\n"
                f"🔥 {small_caps_full('kill streak reset')}</blockquote>" + _hunt_footer(st))
    return (f"🌫️ <b>{sans_bold_italic('Prey Got Away')}</b>\n   {small_caps_full('you waited too long — nothing lost')}\n\n👤 {st['mention']}\n{prey_line}"
            f"<blockquote>🔥 {small_caps_full('kill streak reset')}</blockquote>" + _hunt_footer(st))

async def _hunt_expire(hid):
    """Prey wandered off (idle too long). Costs nothing but the streak. Returns the final text, or None if the hunt already finished."""
    st = pending_hunts.get(hid)
    if not st or st["done"]:
        return None
    st["done"] = True
    pending_hunts.pop(hid, None)
    try:
        await users_catcher_col.update_one({"user_id": st["user_id"]}, {"$set": {"hunt_streak": 0}})
    except Exception as e:
        print(f"hunt expire DB error: {type(e).__name__}: {e}")
    return _hunt_result_text(st, "expired")

async def _hunt_expiry_watch(hid, msg):
    try:
        while True:
            st = pending_hunts.get(hid)
            if not st or st["done"]:
                return
            wait = st["deadline"] - time.time()
            if wait > 0:
                await asyncio.sleep(wait + 0.5)
                continue
            text = await _hunt_expire(hid)
            if text:
                try:
                    await msg.edit(text, parse_mode='html', buttons=None)
                except Exception as e:
                    print(f"hunt expire edit error: {type(e).__name__}: {e}")
            return
    except Exception as e:
        print(f"hunt expiry watcher error: {type(e).__name__}: {e}")

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]hunt(?:@\w+)?$', 'bot1')))
async def text_adventure_hunt_handler(event):
    user_id = event.sender_id
    mention = await get_html_mention(event, user_id)
    plain_name = await get_plain_name(event, user_id)
    await ensure_user_registered(user_id, plain_name)
    user_doc = await users_catcher_col.find_one({"user_id": user_id}) or {}
    now = time.time()
    vip = is_vip_active(user_doc)
    cooldown = HUNT_COOLDOWN_VIP if vip else HUNT_COOLDOWN
    limit = HUNT_DAILY_LIMIT_VIP if vip else HUNT_DAILY_LIMIT

    if any(s["user_id"] == user_id and not s["done"] for s in pending_hunts.values()):
        return await event.reply(f"🏹 {mention} <b>You're already stalking prey — finish that hunt first!</b>", parse_mode='html')
    last_hunt = user_doc.get("hunt_cooldown", 0) or 0
    if now - last_hunt < cooldown:
        left = int(cooldown - (now - last_hunt))
        return await event.reply(
            f"⏳ {mention} <b>{small_caps_full('the forest is quiet')}</b>\n"
            f"🕐 {small_caps_full('next hunt in')}: <code>{left // 60}m {left % 60:02d}s</code>", parse_mode='html')
    today = datetime.now(TZ).strftime("%Y-%m-%d")
    used_today = (user_doc.get("hunt_today", 0) or 0) if user_doc.get("hunt_day") == today else 0
    if used_today >= limit:
        return await event.reply(
            f"🌙 {mention} <b>{small_caps_full('no more hunts today')}</b>\n"
            f"🗓 <code>{used_today}/{limit}</code> — {small_caps_full('the hunt resets at midnight')}", parse_mode='html')
    balance = float(user_doc.get("star_balance", 0) or 0)
    if balance < HUNT_MIN_BALANCE:
        return await event.reply(
            f"🎒 {mention} <b>{small_caps_full('you are too poor to hunt')}</b>\n"
            f"💸 {small_caps_full('a failed hunt costs ⭐ — you need at least')} <code>{HUNT_MIN_BALANCE:,}⭐</code>\n"
            f"💰 {small_caps_full('you have')}: <code>{int(balance):,}⭐</code>", parse_mode='html')

    # 🔒 Compare-and-swap on the exact hunt_cooldown just read — a double-sent /hunt can only start ONE hunt.
    cas_filter = {"user_id": user_id, "hunt_cooldown": user_doc["hunt_cooldown"]} if "hunt_cooldown" in user_doc \
        else {"user_id": user_id, "hunt_cooldown": {"$exists": False}}
    locked = await users_catcher_col.find_one_and_update(
        cas_filter, {"$set": {"hunt_cooldown": now, "hunt_day": today, "hunt_today": used_today + 1, "fullname": plain_name}})
    if not locked:
        return

    prey = hunt_roll_prey()
    hid = f"H{random.randint(100000, 999999)}"
    while hid in pending_hunts:
        hid = f"H{random.randint(100000, 999999)}"
    st = {"id": hid, "user_id": user_id, "mention": mention, "vip": vip, "streak": user_doc.get("hunt_streak", 0) or 0,
          "focus": 0, "step": 0, "done": False, "deadline": now + HUNT_IDLE_TTL, "biome": random.choice(HUNT_BIOMES),
          "cooldown": cooldown, "today": used_today + 1, "limit": limit, **prey}
    pending_hunts[hid] = st
    try:
        msg = await event.reply(_hunt_active_text(st), parse_mode='html', buttons=_hunt_buttons(st))
    except Exception as e:
        pending_hunts.pop(hid, None)
        print(f"hunt start reply failed: {type(e).__name__}: {e}")
        await users_catcher_col.update_one({"user_id": user_id}, {"$set": {"hunt_cooldown": last_hunt, "hunt_today": used_today}})
        return
    st["task"] = asyncio.create_task(_hunt_expiry_watch(hid, msg))

async def hunt_action_callback(event):
    def _s(v):
        return v.decode('utf-8') if isinstance(v, bytes) else v
    action, hid, step = _s(event.pattern_match.group(1)), _s(event.pattern_match.group(2)), int(_s(event.pattern_match.group(3)))
    st = pending_hunts.get(hid)
    if not st or st["done"]:
        return await event.answer("🌫️ This hunt is over.", alert=True)
    if event.sender_id != st["user_id"]:
        return await event.answer("⚠️ This isn't your hunt!", alert=True)
    if step != st["step"]:
        return await event.answer("⏳ Too fast — use the newest buttons.", alert=False)
    if time.time() > st["deadline"] + 1:
        text = await _hunt_expire(hid)
        await event.answer("🌫️ The prey wandered off.", alert=True)
        if text:
            try:
                await event.edit(text, parse_mode='html', buttons=None)
            except Exception:
                pass
        return
    uid = st["user_id"]

    if action == "stalk":
        if st["focus"] >= HUNT_MAX_FOCUS:
            return await event.answer("You're already point-blank — take the shot!", alert=True)
        if random.random() < hunt_flee_chance(st["tier"], st["focus"]):
            st["done"] = True
            pending_hunts.pop(hid, None)
            await users_catcher_col.update_one({"user_id": uid}, {"$set": {"hunt_streak": 0}})
            lost = await _hunt_take_stars(uid, hunt_fail_loss(st, "flee"))
            await event.answer("🏃 It bolted!", alert=False)
            return await event.edit(_hunt_result_text(st, "flee", lost=lost), parse_mode='html', buttons=None)
        st["focus"] += 1
        st["step"] += 1
        st["deadline"] = time.time() + HUNT_IDLE_TTL
        await event.answer("🐾 You creep closer…", alert=False)
        return await event.edit(_hunt_active_text(st, note=f"🐾 <i>{small_caps_full('you creep closer — it has not noticed')}</i>"),
                                parse_mode='html', buttons=_hunt_buttons(st))

    # ── SHOOT ── the session is closed BEFORE the first await, so a double tap can never pay (or charge) twice.
    st["done"] = True
    pending_hunts.pop(hid, None)
    if random.random() < hunt_hit_chance(st["focus"]):
        payout = hunt_payout(st, st["focus"])
        vlt = 0.0
        vcfg = HUNT_TIERS[st["tier"]]["vlt"]
        if vcfg and random.random() < vcfg[0]:
            vlt = round(random.uniform(*vcfg[1]), 2)
        inc = {"star_balance": payout, "hunt_kills": 1, "hunt_total_star": payout, "hunt_streak": 1}
        if vlt:
            inc["vlt_balance"] = vlt
        await users_catcher_col.update_one({"user_id": uid}, {"$inc": inc, "$max": {"hunt_best": payout}})
        await settle_star_debt(uid)
        extra = ""
        try:
            extra = format_achievement_unlocks(await check_and_award_achievements(uid))
        except Exception as e:
            print(f"hunt achievements error: {type(e).__name__}: {e}")
        await event.answer(f"🎯 Direct hit! +{payout:,}⭐", alert=False)
        return await event.edit(_hunt_result_text(st, "win", payout=payout, vlt=vlt, extra=extra), parse_mode='html', buttons=None)

    await users_catcher_col.update_one({"user_id": uid}, {"$set": {"hunt_streak": 0}})
    lost = await _hunt_take_stars(uid, hunt_fail_loss(st, "miss"))
    await event.answer("💨 Missed!", alert=False)
    await event.edit(_hunt_result_text(st, "miss", lost=lost), parse_mode='html', buttons=None)

bot1.on(events.CallbackQuery(pattern=r'^hunt_(shoot|stalk)_(\w+)_(\d+)$'))(hunt_action_callback)

