# 📊 /stats compact layout helpers (2026-11, per owner request — the old 18-progress-bar list was too long / ugly)
def _stats_compact_num(n):
    """1,250,000 -> '1.25M', 500,000,000 -> '500M'. Under 1M the full number is shown with commas."""
    try:
        v = float(n)
    except Exception:
        return str(n)
    for div, suffix in ((1_000_000_000_000, "T"), (1_000_000_000, "B"), (1_000_000, "M")):
        if abs(v) >= div:
            return f"{v / div:.2f}".rstrip("0").rstrip(".") + suffix
    return f"{int(round(v)):,}"

# how the 9 tiers are wrapped onto lines (indexes into RARITY_TIERS: ULTRA, LEGEND, MYTHIC, EPIC, INCREDIBLE, GOLD, RARE, UNCOMMON, COMMON)
_STATS_DB_LINES = ((0, 2), (2, 4), (4, 6), (6, 9))      # emoji + name + count  (2 / 2 / 2 / 3 per line)
_STATS_CATCH_LINES = ((0, 4), (4, 7), (7, 9))           # emoji + count only    (4 / 3 / 2 per line)

def _stats_tier_lines(counts, line_ranges, with_names):
    lines = []
    for a, b in line_ranges:
        parts = []
        for t in RARITY_TIERS[a:b]:
            emoji = RARITY_EMOJI.get(t, RARITY_DEFAULT_EMOJI)
            if with_names:
                parts.append(f"{emoji} {RARITY_DISPLAY_NAME.get(t, t)} {counts.get(t, 0):,}")
            else:
                parts.append(f"{emoji} {counts.get(t, 0):,}")
        lines.append(" · ".join(parts))
    return lines

@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]stats(?:@\w+)?$', 'bot1')))
async def system_inflation_stats(event):
    status_msg = await event.reply("⏳ <b>Compiling statistics...</b>", parse_mode='html')
    try:
        pipeline_cash = [
            {"$group": {
                "_id": None,
                "total_cash": {"$sum": "$star_balance"},
                "players_count": {"$sum": 1}
            }}
        ]
        econ_data = await users_catcher_col.aggregate(pipeline_cash).to_list(length=1)
        metrics = econ_data[0] if econ_data else {"total_cash": 0, "players_count": 0}
        all_base_chars = await characters_base_col.find({}, {"rarity": 1}).to_list(length=None)
        base_total = len(all_base_chars)
        base_tier_counts = {t: 0 for t in RARITY_TIERS}
        for c in all_base_chars:
            tier = classify_rarity(c.get("rarity", ""))
            if tier in base_tier_counts:
                base_tier_counts[tier] += 1
        all_users = await users_catcher_col.find({}, {"harem": 1}).to_list(length=None)
        catch_tier_counts = {t: 0 for t in RARITY_TIERS}
        other_catch_count = 0  # 🩹 FIX: harem items whose rarity string doesn't match any
        # known tier (e.g. legacy "Unknown" rarity from old trades/gifts) used to be silently …
        other_rarity_samples = set()
        total_catches = 0
        caught_unique_ids = set()
        for u in all_users:
            harem = u.get("harem", [])
            total_catches += len(harem)
            for item in harem:
                if isinstance(item, dict) and "char_id" in item:
                    caught_unique_ids.add(item["char_id"])
                    raw_rarity = item.get("rarity", "")
                    tier = classify_rarity(raw_rarity)
                    if tier in catch_tier_counts:
                        catch_tier_counts[tier] += 1
                    else:
                        other_catch_count += 1
                        if len(other_rarity_samples) < 20:
                            other_rarity_samples.add(repr(raw_rarity))
        if other_catch_count:
            print(f"⚠️ /stats: {other_catch_count} harem items had unclassifiable rarity strings: {sorted(other_rarity_samples)}")
        discovery_count = len(caught_unique_ids)
        db_lines = _stats_tier_lines(base_tier_counts, _STATS_DB_LINES, True)
        catch_lines = _stats_tier_lines(catch_tier_counts, _STATS_CATCH_LINES, False)
        if other_catch_count:
            catch_lines[-1] += f" · ❓ {other_catch_count:,}"
        disc_pct = (discovery_count / base_total * 100) if base_total else 0
        disc_txt = f"{disc_pct:.1f}".rstrip("0").rstrip(".")
        msg = (
            f"📊 <b>Global Stats</b>\n"
            f"<blockquote>"
            f"👥 {int(metrics['players_count']):,} Players  ·  💰 {_stats_compact_num(metrics['total_cash'])} ⭐ circulating\n\n"
            f"📚 <b>Character Database</b> — {base_total:,} cards\n"
            + "\n".join(db_lines) + "\n\n"
            f"🎒 <b>Total Catches</b> — {total_catches:,}\n"
            + "\n".join(catch_lines) + "\n\n"
            f"🔍 <b>Discovery</b> — {disc_txt}% ({discovery_count:,}/{base_total:,})"
            f"</blockquote>"
        )
        await status_msg.edit(msg, parse_mode='html')
    except Exception as e:
        error_text = f"❌ <b>Stats Error:</b>\n<code>{escape_html(str(e))}</code>"
        await status_msg.edit(error_text, parse_mode='html')
        await report_system_error("system_inflation_stats", e)

