# 🔒 EVERY-BOOT ENFORCEMENT — fixed catch limit for ULTRA + SUPREME (2026-10, per owner request). Unlike the …
# ==========================================
async def run_fixed_catch_limit_enforcement():
    tiers = sorted(FIXED_CATCH_LIMIT_TIERS, key=RARITY_TIERS.index)
    result = await characters_base_col.update_many(
        {"rarity_tier": {"$in": tiers}, "spawn_limit": {"$ne": FIXED_CATCH_LIMIT}},
        {"$set": {"spawn_limit": FIXED_CATCH_LIMIT}}
    )
    if not result.modified_count:
        return
    await invalidate_character_caches()
    # Cards that already have at least that many catches are locked the moment the new limit lands — worth saying.
    locked_now = await characters_base_col.count_documents(
        {"rarity_tier": {"$in": tiers}, "spawn_count": {"$gte": FIXED_CATCH_LIMIT}}
    )
    print(f"🔒 Fixed catch limit: {result.modified_count} ULTRA/SUPREME character(s) set to {FIXED_CATCH_LIMIT}.")
    try:
        await bot1.send_message(OWNER_ID, (
            f"🔒 <b>Catch limit set to {FIXED_CATCH_LIMIT} for ULTRA & SUPREME.</b>\n"
            f"🔁 <b>Characters changed:</b> <code>{result.modified_count}</code>\n"
            f"🔐 <b>Locked right now</b> (already caught {FIXED_CATCH_LIMIT}+ times): <code>{locked_now}</code>"
        ), parse_mode='html')
    except Exception:
        pass

