# 🎨 ONE-TIME MIGRATION — artist enforcement on EXISTING cards (2026-11, per owner request).
# ==========================================
async def run_artist_enforcement_migration():
    try:
        flag = await bot_settings_col.find_one({"_id": "artist_enforcement_migration_v1"})
        if flag and flag.get("done"):
            return
        print("🎨 Running one-time artist enforcement migration...")
        ultra_q = {"rarity_tier": RARITY_TIERS[0], "artist": {"$exists": True}}
        upper_q = {"rarity_tier": {"$in": [RARITY_TIERS[1], RARITY_TIERS[2]]}, "artist": {"$ne": OWNER_ARTIST_NAME}}   # $ne also matches "no artist yet"

        backup = {}
        async for d in characters_base_col.find({"$or": [ultra_q, upper_q]}, {"char_id": 1, "artist": 1}):
            if d.get("artist") is not None:
                backup[str(d.get("char_id"))] = d["artist"]
        if backup:
            await bot_settings_col.update_one(
                {"_id": "artist_enforcement_backup_v1"},
                {"$set": {"artists": backup, "saved_at": time.time()}}, upsert=True)

        ultra_res = await characters_base_col.update_many(ultra_q, {"$unset": {"artist": ""}})
        upper_res = await characters_base_col.update_many(upper_q, {"$set": {"artist": OWNER_ARTIST_NAME}})
        await invalidate_character_caches()
        await bot_settings_col.update_one(
            {"_id": "artist_enforcement_migration_v1"},
            {"$set": {"done": True, "completed_at": time.time(),
                      "ultra_cleared": ultra_res.modified_count, "upper_set": upper_res.modified_count,
                      "backed_up": len(backup)}},
            upsert=True)
        print(f"✅ Artist migration: ULTRA cleared {ultra_res.modified_count}, SUPREME/CROSSVERSE set {upper_res.modified_count}, {len(backup)} old credit(s) backed up.")
        try:
            await bot1.send_message(OWNER_ID, (
                f"🎨 <b>Artist enforcement applied</b>\n"
                f"🎞 <b>ULTRA</b> — artist removed on <code>{ultra_res.modified_count}</code> card(s)\n"
                f"🪞🦚 <b>SUPREME + CROSSVERSE</b> — set to <code>{OWNER_ARTIST_NAME}</code> on <code>{upper_res.modified_count}</code> card(s)\n"
                f"💾 <i>The {len(backup)} old credit(s) were saved to</i> <code>bot_settings › artist_enforcement_backup_v1</code>"
            ), parse_mode='html')
        except Exception:
            pass
    except Exception as e:
        print(f"⚠️ artist_enforcement_migration failed (will retry next start): {type(e).__name__}: {e}")

