async def run_ultra_event_assignment_migration():
    try:
        flag = await bot_settings_col.find_one({"_id": "ultra_event_assignment_migration"})
        if flag and flag.get("done"):
            return
        print("🎪 Running one-time ULTRA Event assignment migration...")
        applied, already, name_mismatch, missing = 0, 0, [], []
        ops = []
        for num, (event_no, expected_name) in _ULTRA_EVENT_ASSIGNMENTS.items():
            doc = await characters_base_col.find_one({"char_id": f"BOD{num}"}, {"char_id": 1, "name": 1, "event_no": 1})
            if not doc:
                missing.append(num)
            elif str(doc.get("name", "")).strip().lower() != expected_name:
                name_mismatch.append(num)
            elif doc.get("event_no"):
                already += 1
            else:
                ops.append(UpdateOne({"_id": doc["_id"]}, {"$set": {"event": EVENT_TYPES[event_no], "event_no": event_no}}))
                applied += 1
        for i in range(0, len(ops), 500):
            await characters_base_col.bulk_write(ops[i:i + 500], ordered=False)
        if ops:
            await invalidate_character_caches()
        await bot_settings_col.update_one(
            {"_id": "ultra_event_assignment_migration"},
            {"$set": {"done": True, "completed_at": time.time(), "applied": applied, "already_set": already,
                      "name_mismatch": name_mismatch, "missing": missing}},
            upsert=True
        )
        print(f"✅ ULTRA Event assignment complete: {applied} set, {already} already had one, "
              f"{len(name_mismatch)} name mismatch, {len(missing)} missing.")
        try:
            note = (f"🎪 <b>ULTRA Events assigned.</b>\n✅ <b>Set:</b> <code>{applied}</code>\n"
                    f"⏭️ <b>Already had an event:</b> <code>{already}</code>\n")
            if name_mismatch:
                note += f"⚠️ <b>Skipped — name changed since the export:</b> <code>{', '.join(str(n).zfill(4) for n in name_mismatch[:30])}</code>\n"
            if missing:
                note += f"❓ <b>Not in the database:</b> <code>{', '.join(str(n).zfill(4) for n in missing[:30])}</code>\n"
            note += "\nFix any wrong one with <code>/setevent N | CharID</code>."
            await bot1.send_message(OWNER_ID, note, parse_mode='html')
        except Exception:
            pass
    except Exception as e:
        print(f"⚠️ run_ultra_event_assignment_migration failed (nothing marked done, will retry next start): {type(e).__name__}: {e}")

