async def _create_indexes_background():
    """Runs create_indexes() without blocking bot startup — index creation is a MongoDB round
    trip per index (~35 of them), which used to make bot1 sit disconnected from Telegram
    for however long that took. Indexes are a pure performance optimization (queries still
    work without one, just slower), so there's no correctness reason to wait on them."""
    try:
        await create_indexes()
    except Exception as e:
        print(f"Index creation error: {e}")

async def start_bot_state_cleanup_loop():
    """Sweeps BotState's expired cache entries every 10 minutes for the life of the process."""
    while True:
        await asyncio.sleep(600)
        try:
            removed = bot_state.cleanup_expired()
            if removed:
                print(f"🧹 BotState cleanup: removed {removed} stale entries")
        except Exception as e:
            print(f"BotState cleanup error: {e}")

async def _startup_perf_warm():
    """Load the roster (+ its derived indexes) and the persisted file-identity cache BEFORE the first player asks, so the
    first /harem, inline query or /who after a deploy isn't the one that pays for them."""
    try:
        chars = await get_all_characters_cached()
        _roster_derived(chars)
        await _get_char_hash_index()
    except Exception as e:
        print(f"⚠️ startup roster warm failed (it will load on first use instead): {e}")
    try:
        print(f"🗂️ media identity cache: {await load_media_identity_cache_from_db()} file(s) loaded from DB")
    except Exception as e:
        print(f"⚠️ media identity load failed: {e}")

# ==========================================
# 💰 PROACTIVE MASS-SELL OFFER (2026-11, per owner request)
# ==========================================
MASS_SELL_HAREM_THRESHOLD = 200          # vault cards needed before the offer is made
MASS_SELL_TIERS = ("COMMON", "UNCOMMON", "RARE")
# 🩹 2026-11 (owner: "ကိုက်ညီချင်တယ်"): Mass Sell used to pay a hard-coded 3 / 4 / 5 💠 per card (≈1% of the DEFAULT prices) no matter what …
def _mass_sell_unit(tier):
    """💠 paid for ONE card of `tier` — the same number /sell [ID] and SELL BY RARITY pay (see _sellall_unit)."""
    return round(tier_value_range(tier)[1] * SELL_ALL_MULT, 2)
MASS_SELL_OFFER_COOLDOWN = 7 * 86400     # after an offer is sent / declined → wait 7 days
MASS_SELL_FAIL_COOLDOWN = 86400          # DM failed (blocked / never /start-ed) → retry after 1 day
MASS_SELL_MANUAL_THROTTLE = 60           # /masssell spam guard (seconds)
MASS_SELL_CHECK_INTERVAL = 3600          # background scan every hour
MASS_SELL_LOOP_LIMIT = 50                # offers per scan (flood safety)
MASS_SELL_BATCH_LIMIT = 500              # max cards in one offer (safety cap)
MASS_SELL_MAX_RETRIES = 3
MASS_SELL_FREE_CATCH_SLOTS = True        # give sold copies back to the Global Catches count (like /gban does)
# NOTE: /sell and /scrap do NOT free catch slots today; set this to False if you want mass-sell to behave like them.


def _mass_sell_vault_count(harem):
    return sum(1 for it in (harem or []) if isinstance(it, dict) and it.get("char_id") and it.get("status") == "vault")


def _mass_sell_plan(harem):
    """PURE function (no DB) — the single place that decides what gets sold.
    Returns (new_harem, sold_by_tier, sold_ids) where sold_ids = Counter{char_id: copies sold}."""
    new_harem = []
    sold_by_tier = {t: 0 for t in MASS_SELL_TIERS}
    sold_ids = Counter()
    total = 0
    for item in harem or []:
        if (not isinstance(item, dict) or not item.get("char_id") or item.get("status") != "vault"
                or total >= MASS_SELL_BATCH_LIMIT):
            new_harem.append(item)
            continue
        cid = item["char_id"]
        if exl_parse_id(cid):                      # 🧣 Exclusive cards are never touched
            new_harem.append(item)
            continue
        tier = _tier_of_rarity_string(item.get("rarity"))
        if tier not in sold_by_tier:               # higher rarities / "OTHER" (unclassifiable) → never touch
            new_harem.append(item)
            continue
        sold_by_tier[tier] += 1
        sold_ids[cid] += 1
        total += 1
    return new_harem, sold_by_tier, sold_ids


def _mass_sell_payout(sold_by_tier):
    return round(sum(_mass_sell_unit(t) * n for t, n in sold_by_tier.items()), 2)


def _mass_sell_offer_view(user_id, vault_count, sold_by_tier):
    """(text, buttons) for the offer message — used for the first DM AND for an in-place refresh."""
    n = sum(sold_by_tier.values())
    payout = _mass_sell_payout(sold_by_tier)
    tier_lines = [
        f"{RARITY_EMOJI.get(t, RARITY_DEFAULT_EMOJI)} {RARITY_DISPLAY_NAME.get(t, t)} ×{sold_by_tier[t]:,} "
        f"@ <code>{format_vlt_plain(_mass_sell_unit(t))}</code> — <code>{format_vlt_plain(_mass_sell_unit(t) * sold_by_tier[t])}</code>"
        for t in MASS_SELL_TIERS if sold_by_tier[t]
    ]
    text = (
        f"💰 <b>Mass Sell Offer</b>\n\n"
        f"📊 သင့် vault မှာ ကဒ် <code>{vault_count:,}</code> ခု ရှိနေပါပြီ။\n"
        f"ဒီထဲက <b>RARE / UNCOMMON / COMMON</b> ကဒ်အားလုံးကို bot က 💠 VLT နဲ့ "
        f"ပြန်ဝယ်ဖို့ အဆင်သင့်ရှိပါတယ်။\n\n"
        f"<b>ပေးမယ့် စျေး:</b>\n" + "\n".join(tier_lines) + "\n\n"
        f"💰 <b>စုစုပေါင်း:</b> <code>{format_vlt_plain(payout)}</code> (<code>{n:,}</code> cards)\n\n"
        f"⚠️ <i>Confirm လုပ်ရင် ဒီကဒ်တွေ အားလုံး သင့် vault ကနေ ပျောက်သွားပါမယ် (ပြန်ပြင်လို့ မရတော့ပါ)။ "
        f"🧣 Exclusive နဲ့ ပိုရှားတဲ့ rarity ကဒ်တွေ မထိပါ။ Cancel လုပ်ရင် ဘာမှ မပြောင်းလဲပါ။</i>"
    )
    cents = int(round(payout * 100))
    buttons = [[
        colored_button(f"✅ Sell for {format_vlt_plain(payout)}", f"msell_ok_{user_id}_{n}_{cents}", color="success"),
        Button.inline("❌ Cancel", data=f"msell_no_{user_id}"),
    ]]
    return text, buttons


async def _maybe_send_mass_sell_offer(user_id, force=False):
    """Checks eligibility and sends the DM. force=True (player typed /masssell) skips the cooldowns.
    Returns one of: sent · below · cooldown · nothing · blocked · error · skip."""
    if user_id == OWNER_ID or user_id in bot_ids or user_id in banned_user_ids():
        return "skip"
    now = time.time()
    user_doc = await users_catcher_col.find_one(
        {"user_id": user_id},
        {"harem": 1, "mass_sell_offer_sent_at": 1, "mass_sell_dm_failed_at": 1},
    )
    if not user_doc:
        return "skip"
    harem = user_doc.get("harem") or []
    vault_count = _mass_sell_vault_count(harem)
    if vault_count < MASS_SELL_HAREM_THRESHOLD:
        return "below"
    last_sent = user_doc.get("mass_sell_offer_sent_at", 0) or 0
    last_fail = user_doc.get("mass_sell_dm_failed_at", 0) or 0
    if force:
        if now - last_sent < MASS_SELL_MANUAL_THROTTLE:
            return "cooldown"
    elif now - last_sent < MASS_SELL_OFFER_COOLDOWN or now - last_fail < MASS_SELL_FAIL_COOLDOWN:
        return "cooldown"

    _new, sold_by_tier, _ids = _mass_sell_plan(harem)
    if not any(sold_by_tier.values()):
        # 200+ cards but nothing sellable (all higher rarity / EX) — stamp it so the hourly scan
        # doesn't re-check this player every hour.
        await users_catcher_col.update_one({"user_id": user_id}, {"$set": {"mass_sell_offer_sent_at": now}})
        return "nothing"

    text, buttons = _mass_sell_offer_view(user_id, vault_count, sold_by_tier)
    try:
        await bot1.send_message(user_id, text, parse_mode='html', buttons=buttons)
    except (errors.UserIsBlockedError, errors.InputUserDeactivatedError,
            errors.PeerIdInvalidError, errors.UserIdInvalidError):
        # Blocked the bot / account gone / never pressed /start — remember it so we don't hammer them.
        await users_catcher_col.update_one({"user_id": user_id}, {"$set": {"mass_sell_dm_failed_at": now}})
        return "blocked"
    except FloodWaitError as e:
        await asyncio.sleep(min(getattr(e, "seconds", 5), 60))
        return "error"
    except Exception as e:
        print(f"⚠️ mass-sell DM failed ({user_id}): {e}")
        return "error"
    await users_catcher_col.update_one(
        {"user_id": user_id},
        {"$set": {"mass_sell_offer_sent_at": now}, "$unset": {"mass_sell_dm_failed_at": ""}},
    )
    return "sent"


@bot1.on(events.NewMessage(pattern=own_pattern(r'^[/.]masssell(?:@\w+)?$', 'bot1')))
async def mass_sell_request_handler(event):
    user_id = event.sender_id
    user_doc = await users_catcher_col.find_one({"user_id": user_id}, {"harem": 1})
    vault_count = _mass_sell_vault_count((user_doc or {}).get("harem"))
    if vault_count < MASS_SELL_HAREM_THRESHOLD:
        return await event.reply(
            f"💰 <b>Mass Sell</b>\n\n"
            f"📊 သင့် vault မှာ ကဒ် <code>{vault_count:,}</code> ခု ရှိပါတယ်။\n"
            f"<i>ကဒ် <code>{MASS_SELL_HAREM_THRESHOLD}</code> ခု ပြည့်တဲ့အခါ bot က DM ကနေ "
            f"RARE / UNCOMMON / COMMON ကဒ်တွေကို 💠 VLT နဲ့ ပြန်ဝယ်ဖို့ မေးပါလိမ့်မယ်။</i>",
            parse_mode='html',
        )
    status = await _maybe_send_mass_sell_offer(user_id, force=True)
    replies = {
        "sent": "📩 Offer ကို DM မှာ ပို့ပေးလိုက်ပါပြီ။",
        "cooldown": "⏳ Offer ကို ခုနကပဲ ပို့ပြီးပါပြီ — DM ကို ကြည့်ပါ။",
        "nothing": "ℹ️ ဝယ်ယူနိုင်တဲ့ (RARE / UNCOMMON / COMMON) ကဒ် သင့် vault မှာ မရှိပါဘူး။",
        "blocked": "❌ DM ကို မပို့နိုင်ပါ — bot ကို DM မှာ <code>/start</code> အရင်လုပ်ပြီး ပြန်စမ်းပါ။",
    }
    await event.reply(replies.get(status, "⚠️ ခဏနေမှ ပြန်စမ်းပါ။"), parse_mode='html')


async def _execute_mass_sell(user_id, expect_n, expect_cents):
    """Re-reads, re-prices and sells in ONE atomic update. Returns (status, data):
      ("ok", (sold_by_tier, payout)) · ("none", None) · ("changed", (vault_count, sold_by_tier)) · ("busy", None)
    "changed" = the card count / payout no longer matches what the player was shown → nothing is sold."""
    for _ in range(MASS_SELL_MAX_RETRIES):
        user_doc = await users_catcher_col.find_one({"user_id": user_id}, {"harem": 1, "_id": 0})
        harem = (user_doc or {}).get("harem") or []
        new_harem, sold_by_tier, sold_ids = _mass_sell_plan(harem)
        n = sum(sold_by_tier.values())
        if n == 0:
            return "none", None
        payout = _mass_sell_payout(sold_by_tier)
        if n != expect_n or int(round(payout * 100)) != expect_cents:
            return "changed", (_mass_sell_vault_count(harem), sold_by_tier)
        res = await users_catcher_col.update_one(
            {"user_id": user_id, "harem": {"$size": len(harem)}},
            {"$set": {"harem": new_harem}, "$inc": {"vlt_balance": payout}},
        )
        if not res.matched_count:
            continue    # a catch/gift/trade landed between our read and write — re-read and retry
        if MASS_SELL_FREE_CATCH_SLOTS:
            try:
                await free_catch_slots(dict(sold_ids))
            except Exception as e:
                print(f"mass sell free_catch_slots error ({user_id}): {e}")
        try:  # a sold-out /fav card would otherwise linger on /harem and /profile
            fav_doc = await users_catcher_col.find_one({"user_id": user_id}, {"fav_card": 1, "harem": 1, "_id": 0}) or {}
            if fav_doc.get("fav_card") in sold_ids:
                await clear_stale_favorite(user_id, fav_doc["fav_card"], fav_doc.get("harem") or [])
        except Exception as e:
            print(f"mass sell fav cleanup error ({user_id}): {e}")
        return "ok", (sold_by_tier, payout)
    return "busy", None


@bot1.on(events.CallbackQuery(pattern=r'^msell_(ok|no)_(\d+)(?:_(\d+)_(\d+))?$'))
async def mass_sell_callback(event):
    def _grp(i):
        v = event.pattern_match.group(i)
        return v.decode('utf-8') if isinstance(v, bytes) else v
    try:
        action = _grp(1)
        owner_id = int(_grp(2))
        if event.sender_id != owner_id:
            return await event.answer("⚠️ ဒါ သင့် offer မဟုတ်ပါ။", alert=True)

        if action == "no":
            await event.answer("Cancelled.")
            await users_catcher_col.update_one(      # decline → the 7-day cooldown restarts from now
                {"user_id": owner_id}, {"$set": {"mass_sell_offer_sent_at": time.time()}}
            )
            return await event.edit("❌ <b>Mass sell cancelled. Nothing changed.</b>", parse_mode='html', buttons=None)

        expect_n, expect_cents = int(_grp(3) or 0), int(_grp(4) or 0)
        if not claim_single_tap(event):
            return await event.answer("⏳ Processing...", alert=False)
        status, data = await _execute_mass_sell(owner_id, expect_n, expect_cents)

        if status == "busy":
            return await event.answer("⏳ Vault ပြောင်းလဲနေလို့ မလုပ်ပေးနိုင်သေးပါ — ခဏနေ ပြန်နှိပ်ပါ။", alert=True)
        if status == "none":
            await event.answer("ℹ️ ရောင်းစရာ ကဒ် မရှိတော့ပါ။", alert=True)
            return await event.edit("ℹ️ <b>ဒီ offer အတွက် ကဒ် မရှိတော့ပါ။</b>", parse_mode='html', buttons=None)
        if status == "changed":
            vault_count, sold_by_tier = data
            await event.answer("⚠️ Vault ပြောင်းသွားလို့ offer အသစ် ပြန်ပြထားပါတယ် — ထပ်စစ်ပြီး နှိပ်ပါ။", alert=True)
            text, buttons = _mass_sell_offer_view(owner_id, vault_count, sold_by_tier)
            try:
                return await event.edit(text, parse_mode='html', buttons=buttons)
            except errors.MessageNotModifiedError:
                return

        sold_by_tier, payout = data
        total = sum(sold_by_tier.values())
        rows = "\n".join(
            f"{RARITY_EMOJI.get(t, RARITY_DEFAULT_EMOJI)} {RARITY_DISPLAY_NAME.get(t, t)} ×{n:,}"
            for t, n in sold_by_tier.items() if n
        )
        await event.answer(f"✅ {total:,} ကဒ် ရောင်းပြီးပါပြီ!")
        await event.edit(
            f"✅ <b>Mass sell complete!</b>\n"
            f"<blockquote>{rows}\n\n🗑️ <b>Removed:</b> <code>{total:,}</code> card(s)\n"
            f"💰 <b>Earned:</b> <code>{format_vlt_plain(payout)}</code></blockquote>\n"
            f"<code>/harem</code> ပြန်ကြည့်နိုင်ပါပြီ။",
            parse_mode='html', buttons=None,
        )
    except Exception as e:
        print(f"mass_sell_callback error: {e}")
        try:
            await event.answer("❌ တစ်ခုခု မှားသွားပါတယ် — ပြန်ကြိုးစားပါ။", alert=True)
        except Exception:
            pass


async def mass_sell_offer_loop():
    """Hourly: find players with 200+ cards who haven't been offered recently and DM them the offer."""
    await asyncio.sleep(120)   # let the bots connect first
    while True:
        try:
            if bot1.is_connected():
                now = time.time()
                # `harem.199 exists` = "array has at least 200 entries" — cheap pre-filter, so we never
                # run per-document array maths over every player. Missing/non-array harem can't match.
                query = {
                    f"harem.{MASS_SELL_HAREM_THRESHOLD - 1}": {"$exists": True},
                    "user_id": {"$nin": list(set(banned_user_ids()) | {OWNER_ID})},
                    "$and": [
                        {"$or": [{"mass_sell_offer_sent_at": {"$exists": False}},
                                 {"mass_sell_offer_sent_at": {"$lt": now - MASS_SELL_OFFER_COOLDOWN}}]},
                        {"$or": [{"mass_sell_dm_failed_at": {"$exists": False}},
                                 {"mass_sell_dm_failed_at": {"$lt": now - MASS_SELL_FAIL_COOLDOWN}}]},
                    ],
                }
                candidates = await users_catcher_col.find(query, {"user_id": 1, "_id": 0}) \
                    .limit(MASS_SELL_LOOP_LIMIT).to_list(length=MASS_SELL_LOOP_LIMIT)
                sent = 0
                for c in candidates:
                    if await _maybe_send_mass_sell_offer(c["user_id"]) == "sent":
                        sent += 1
                    await asyncio.sleep(0.5)        # flood safety
                if sent:
                    print(f"💰 Mass sell offers sent: {sent}")
        except Exception as e:
            print(f"mass_sell_offer_loop error: {e}")
        await asyncio.sleep(MASS_SELL_CHECK_INTERVAL)


async def start_system():
    threading.Thread(target=run_flask, daemon=True).start()
    print("Bot System Starting...")
    asyncio.create_task(_startup_perf_warm())
    asyncio.create_task(_loop_lag_monitor())
    asyncio.create_task(_pe_load_custom())
    asyncio.create_task(_pe_startup_check())
    asyncio.create_task(_create_indexes_background())
    asyncio.create_task(start_bot_state_cleanup_loop())
    asyncio.create_task(daily_report_scheduler())
    asyncio.create_task(trivia_top10_reward_scheduler())
    asyncio.create_task(nightly_vlt_draw_scheduler())
    asyncio.create_task(casino_net_flush_loop())
    asyncio.create_task(data_retention_loop())
    asyncio.create_task(mass_sell_offer_loop())
    asyncio.create_task(giftall_recovery_loop())      # 🎁 finishes any /gift all a redeploy interrupted
    await run_bot1_forever()

if __name__ == "__main__":
    try:
        asyncio.run(start_system())
    except (KeyboardInterrupt, SystemExit):
        print("Bot System Shutting Down.")
        
